        ("crm_leads", "atendido_em", "TIMESTAMP"),
        # Funil que "Atender agora" (inbox da extensão) dispara pra esse consultor
        # — cada um pode ter o seu (abertura personalizada).
        ("usuarios", "funil_atendimento_id", "INTEGER"),
