def _plano_from_modalidade(modalidade, tipo_pessoa=''):
    """Mapeia a modalidade/tipo da proposta para o plano da tabela: PME / PF / ADESAO."""
    s = ((modalidade or '') + ' ' + (tipo_pessoa or '')).upper()
    if 'ADES' in s:
        return 'ADESAO'
    if ' PF' in (' ' + s) or 'PESSOA F' in s or 'INDIVID' in s or 'FAMILIAR' in s or s.strip() == 'PF':
        return 'PF'
    return 'PME'  # PME, Coletivo, Empresarial, Porte N → PME

def _split_operadora(operadora):
    """'Affix · Hapvida' -> ('Affix', 'Hapvida'). Sem separador -> (nome, '')."""
    op = (operadora or '').strip()
    for sep in (' · ', ' - ', '·', ' / '):
        if sep in op:
            a, b = op.split(sep, 1)
            return a.strip(), b.strip()
    return op, ''


def _num_brl(v):
    """Valor monetário digitado -> float, aceitando BR ('1.194,63') E ponto decimal
    ('1194.63'). Regra: SE tem vírgula, o ponto é milhar e a vírgula é o decimal;
    SEM vírgula, o ponto (se houver) é o decimal — NÃO apagar, senão '1194.63' vira
    119463 (bug do milhar no editar/criar proposta). Já vem número? passa direto."""
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v if v is not None else '').strip()
    if not s:
        return 0.0
    s = s.replace('R$', '').replace(' ', '').replace(' ', '')
    if ',' in s:
        s = s.replace('.', '').replace(',', '.')
    try:
        return float(s)
    except (ValueError, TypeError):
        return 0.0


def _op_compact(s):
    """Nome de operadora reduzido a só letras/números, sem acento e minúsculo:
    'Med Senior SP/RJ' -> 'medseniorsprj', 'MedSênior' -> 'medsenior'. Serve pra
    casar a MESMA operadora escrita de formas diferentes (acento, espaço, praça)."""
    return ''.join(ch for ch in _normaliza_op(s or '') if ch.isalnum())


# Nomes comerciais diferentes para a MESMA operadora, quando a regra de prefixo
# não dá conta. 'Porto Saúde' e 'Porto Seguro' são a mesma empresa, mas divergem
# já na segunda palavra — e sem isto uma venda gravada com um dos nomes não acha
# preço nenhum e a comissão zera calada.
#
# Só entra aqui o que é fato comercial, não erro de digitação: para grafia
# diferente do mesmo nome existe a regra de prefixo, e para unificar de vez existe
# o "Renomear" em /operadoras, que troca o nome no cadastro, no repasse e em todas
# as propostas de uma vez.
_OP_SINONIMOS = [
    {'porto seguro', 'porto saude', 'porto seguro saude'},
]
_OP_SINONIMOS_IDX = {}
for _g in _OP_SINONIMOS:
    _chave = frozenset(_op_compact(n) for n in _g)
    for _n in _g:
        _OP_SINONIMOS_IDX.setdefault(_op_compact(_n), _chave)


def _op_casa(a, b):
    """True se dois nomes são a MESMA operadora tolerando acento, espaço e sufixo
    de praça ('MedSênior' == 'Medsenior' == 'Med Senior SP/RJ'). Exige que o menor
    tenha >=4 chars e seja prefixo do maior — não casa nomes só parecidos.

    Além disso casa os sinônimos comerciais declarados em `_OP_SINONIMOS`, que a
    regra de prefixo não alcança ('Porto Saúde' x 'Porto Seguro')."""
    ca, cb = _op_compact(a), _op_compact(b)
    if not ca or not cb:
        return False
    if ca == cb:
        return True
    ga = _OP_SINONIMOS_IDX.get(ca)
    if ga and cb in ga:
        return True
    # Sinônimo com sufixo de praça: 'Porto Saude SP' x 'Porto Seguro'.
    for grupo in _OP_SINONIMOS:
        alcanca_a = any(ca.startswith(n) or n.startswith(ca)
                        for n in (_op_compact(x) for x in grupo))
        alcanca_b = any(cb.startswith(n) or n.startswith(cb)
                        for n in (_op_compact(x) for x in grupo))
        if alcanca_a and alcanca_b:
            return True
    menor, maior = (ca, cb) if len(ca) <= len(cb) else (cb, ca)
    return len(menor) >= 4 and maior.startswith(menor)


def _resolver_nome_operadora(conn, op_nome, plano):
    """Devolve o nome de operadora REALMENTE cadastrado nas tabelas de preço PARA
    ESTE PLANO. Se o nome exato não tem preço nesse plano mas há UMA operadora
    equivalente com grafia diferente, devolve a canônica — assim uma proposta
    gravada como 'MedSênior' PF acha os preços cadastrados como 'Med Senior SP/RJ'
    PF e a comissão não zera. Checagem POR PLANO de propósito: existe 'MedSênior'
    cadastrado em outro plano, e um check global achava que estava tudo certo.
    Ambiguidade (>1 candidata) mantém o original (zero + aviso) — melhor não pagar
    do que pagar errado."""
    try:
        existe = conn.execute(
            "SELECT 1 FROM recebimento WHERE operadora=? AND plano=? "
            "UNION SELECT 1 FROM repasse_corretor WHERE operadora=? AND plano=? "
            "UNION SELECT 1 FROM gestor_regra WHERE operadora=? AND plano=? LIMIT 1",
            (op_nome, plano, op_nome, plano, op_nome, plano)).fetchone()
        if existe:
            return op_nome
        nomes = set()
        for tab in ('recebimento', 'repasse_corretor', 'gestor_regra'):
            for r in conn.execute(f"SELECT DISTINCT operadora FROM {tab} WHERE plano=?", (plano,)).fetchall():
                if _op_casa(r['operadora'], op_nome):
                    nomes.add(r['operadora'])
        if len(nomes) == 1:
            return nomes.pop()
    except Exception:
        if DB_MODE == 'postgres':
            try: conn.rollback()
            except Exception: pass
    return op_nome


def _op_display(operadora, obs):
    """(operadora, obs) -> nome de exibição único ('Operadora · obs' ou só o nome).
    É a forma canônica gravada em propostas.adm_operadora e no registro de nomes."""
    op = (operadora or '').strip()
    ob = (obs or '').strip()
    return f"{op} · {ob}" if ob else op


def _operadoras_lista(conn):
    """FONTE ÚNICA da lista de operadoras (por identidade operadora+obs).
    Une o registro de nomes (tabela operadoras, que guarda o display completo)
    com o que existe em recebimento e repasse_corretor — assim um nome cadastrado
    sem preço aparece, um preço sem passar pelo cadastro aparece, e as telas
    (form da proposta, /repasses, /operadoras, produtos) enxergam a MESMA lista.
    Retorna [{operadora, obs, display}] ordenado por display."""
    pares = {}
    def _add(op, ob):
        op = (op or '').strip(); ob = (ob or '').strip()
        if op:
            pares.setdefault((op, ob), _op_display(op, ob))
    try:
        for r in conn.execute("SELECT DISTINCT operadora, obs FROM recebimento").fetchall():
            _add(r['operadora'], r['obs'])
    except Exception:
        pass
    try:
        for r in conn.execute("SELECT DISTINCT operadora, obs FROM repasse_corretor").fetchall():
            _add(r['operadora'], r['obs'])
    except Exception:
        pass
    try:
        for r in conn.execute("SELECT DISTINCT operadora, obs FROM gestor_regra").fetchall():
            _add(r['operadora'], r['obs'])
    except Exception:
        pass
    try:
        for r in conn.execute("SELECT operadora FROM operadoras").fetchall():
            _add(*_split_operadora(r['operadora']))
    except Exception:
        pass
    return sorted(({'operadora': op, 'obs': ob, 'display': disp}
                   for (op, ob), disp in pares.items()),
                  key=lambda x: x['display'].lower())

def _nivel_por_producao(prod, conn):
    """Determina o nível (n1/n2/n3) pela produção acumulada, respeitando a tabela niveis."""
    try:
        niveis = conn.execute("SELECT codigo,faixa_min,faixa_max FROM niveis ORDER BY ordem").fetchall()
    except Exception:
        niveis = []
    for nv in niveis:
        mn = float(nv['faixa_min'] or 0)
        mx = nv['faixa_max']
        if prod >= mn and (mx is None or prod <= float(mx)):
            return nv['codigo']
    # fallback fixo
    if prod <= 3000: return 'n1'
    if prod <= 7000: return 'n2'
    return 'n3'


def _producao_mes(conn, usuario_id, mes_meta, excluir_pid=None):
    """Soma a produção (valor) do consultor no CICLO DE VENDAS (mes_meta) —
    o mesmo mês que o resto do sistema usa (dashboard, filtro de mês,
    fechamento). Guilherme, 20/07: "não respeita o calendário de vendas do
    mês, precisa funcionar por ciclo/mês" — antes filtrava pelo calendário
    de criado_em (data em que a proposta foi lançada no sistema), que diverge
    do ciclo comercial real quando o fechamento cai num mês diferente do
    lançamento; o nível N1/N2/N3 saía calculado no mês errado nesses casos."""
    ma = str(mes_meta or '')[:7]  # 'YYYY-MM'
    if len(ma) != 7:
        return 0
    try:
        # Proposta excluída ou estornada NÃO conta produção — essa soma define o
        # nível N1/N2/N3 (percentual de comissão); contar venda que caiu deixava
        # o consultor subir de nível com base em nada.
        base_sql = """SELECT COALESCE(SUM(valor),0) v FROM propostas
            WHERE usuario_id=? AND mes_meta=?
              AND status <> 'Excluída' AND COALESCE(estornada,0)=0"""
        if excluir_pid is not None:
            r = conn.execute(base_sql + " AND id<>?",
                (usuario_id, ma, excluir_pid)).fetchone()
        else:
            r = conn.execute(base_sql, (usuario_id, ma)).fetchone()
        return r['v'] if r else 0
    except Exception:
        if DB_MODE == 'postgres':
            try: conn.rollback()
            except Exception: pass
        return 0


def _regua_recebimento(receb_row):
    """Régua da operadora a partir da linha de `recebimento`.

    Devolve [{'ordem':1,'percentual':100,'mes':1}, ...] — mesmo formato de
    gestor_regra.fracoes_json. Sem régua cadastrada devolve [], e aí o cálculo
    cai no comportamento antigo (proporcional) em vez de quebrar."""
    try:
        fr = json.loads((receb_row or {}).get('regua_json') or '[]')
        return fr if isinstance(fr, list) and fr else []
    except Exception:
        return []


def _aplicar_promocao(regua, receb_row):
    """Acrescenta a diferença da promoção como uma fração extra.

    A tabela da Affinity paga X (ex.: Amil 240% em 100/100/40). A condição
    promocional negociada paga Y (280%). A diferença (40%) chega no mês
    seguinte ao último da tabela — é uma fração a mais, não um aumento
    diluído nas existentes. Por isso entra como fração nova."""
    try:
        total_tab = float((receb_row or {}).get('total') or 0)
        total_promo = float((receb_row or {}).get('promo_total') or 0)
    except (TypeError, ValueError):
        return regua
    if not regua or total_promo <= total_tab:
        return regua
    # Converte a diferença em pontos da mesma escala da régua (% da mensalidade)
    soma = sum(float(f.get('percentual') or 0) for f in regua) or 1.0
    delta_pontos = soma * ((total_promo - total_tab) / total_tab) if total_tab else 0.0
    if delta_pontos <= 0:
        return regua
    ultimo_mes = max(int(f.get('mes') or f.get('ordem') or 0) for f in regua)
    try:
        mes_promo = int((receb_row or {}).get('promo_parcela') or 0) or (ultimo_mes + 1)
    except (TypeError, ValueError):
        mes_promo = ultimo_mes + 1
    nova = list(regua) + [{'ordem': len(regua) + 1, 'percentual': round(delta_pontos, 4),
                           'mes': mes_promo, 'promocional': True}]
    return nova


def calc_comissao(operadora, regime_base, prod_acumulada, valor_venda, modalidade='',
                  tipo_pessoa='', conn=None):
    """Motor de comissão isolando a regra da Taxa de Adesão.

    `conn` opcional: quem já tem conexão aberta empresta a sua e fica dono dela.
    Sem isso, varrer a base chamava `db()` uma vez por venda — em Postgres cada
    chamada é uma conexão nova pela rede (não há pool), e a auditoria de milhares
    de vendas viraria milhares de conexões."""
    conn_propria = conn is None
    if conn_propria:
        conn = db()

    def _fecha():
        if conn_propria:
            close_db(conn)

    valor = float(valor_venda or 0)
    op_nome, op_obs = _split_operadora(operadora)
    plano = _plano_from_modalidade(modalidade, tipo_pessoa)
    # Casa grafias diferentes da mesma operadora NESTE plano ('MedSênior' PF ->
    # 'Med Senior SP/RJ' PF) ANTES de buscar preço, senão o nome do seletor não
    # bate com a tabela e a comissão zera.
    op_nome = _resolver_nome_operadora(conn, op_nome, plano)

    # 1) Recebimento da corretora (mensalidades / resíduo)
    receb = conn.execute(
        "SELECT * FROM recebimento WHERE operadora=? AND obs=? AND plano=?",
        (op_nome, op_obs, plano)).fetchone()
    if not receb:
        receb = conn.execute(
            "SELECT * FROM recebimento WHERE operadora=? AND plano=? ORDER BY (obs='') DESC LIMIT 1",
            (op_nome, plano)).fetchone()
    rd = dict(receb) if receb else {}
    # Promoção vigente substitui o total da tabela (ex.: Amil 240% -> 280%).
    # A diferença cai numa parcela combinada, depois do fim da régua da tabela.
    receb_mens = float(rd.get('total') or 0.0)
    promo_total = rd.get('promo_total')
    regua_receb = _regua_recebimento(rd)
    if promo_total:
        try:
            receb_mens = float(promo_total)
            regua_receb = _aplicar_promocao(regua_receb, rd)
        except (TypeError, ValueError):
            pass
    total_corretora = round(valor * receb_mens, 2)

    # GESTOR VENDEDOR: leva 100% da corretora
    if regime_base == 'gestor_vendedor':
        _fecha()
        regua = [receb_mens] if receb_mens else [1.0]
        return {
            'codigo': 'gestor_vendedor', 'modelo': 'gestor_vendedor', 'nivel': '', 'plano': plano,
            'num_parcelas': 1, 'dist_corretora': str(receb_mens or 1.0),
            'regua_mens': regua, 'receb_mens': receb_mens, 'rep_mens': receb_mens, 'taxa': 0,
            'valor': valor, 'total_corretora': total_corretora,
            'consultor': total_corretora, 'liquido': 0.0,
            'regua_receb': regua_receb,
            'aviso': ''
        }

    # 2) Modelo + nível
    modelo = REGIME_TO_MODELO.get(regime_base, 'sem_lead_sem_fixo')
    nivel = ''
    if modelo == 'com_lead':
        nivel = regime_base if regime_base in ('n1', 'n2', 'n3') else _nivel_por_producao(prod_acumulada, conn)

    # 3) Repasse ao corretor
    rep = conn.execute(
        "SELECT total,regua,taxa FROM repasse_corretor WHERE operadora=? AND obs=? AND plano=? AND modelo=? AND nivel=?",
        (op_nome, op_obs, plano, modelo, nivel)).fetchone()
    if not rep:
        rep = conn.execute(
            "SELECT total,regua,taxa FROM repasse_corretor WHERE operadora=? AND plano=? AND modelo=? AND nivel=? ORDER BY (obs='') DESC LIMIT 1",
            (op_nome, plano, modelo, nivel)).fetchone()
            
    rep_mens = float(rep['total']) if rep else 0.0
    regua_str = (rep['regua'] if rep and rep['regua'] else '') or ''
    taxa = int(rep['taxa']) if rep and rep['taxa'] is not None else 0

    # ==========================================
    # --- RAMO ISOLADO: ADESÃO ---
    # ==========================================
    if plano == 'ADESAO':
        # Na Adesão, a corretora recolhe a taxa. O consultor ganha um % apenas sobre essa 1ª mensalidade.
        consultor = round(valor * rep_mens, 2)
        # O líquido da corretora = Total de recebíveis da operadora - O que foi pago de taxa pro consultor
        liquido = round(total_corretora - consultor, 2)
        _fecha()
        
        avisos = []
        if receb_mens == 0: avisos.append(f"Falta RECEBIMENTO: {op_nome} / ADESAO")
        if rep_mens == 0: avisos.append(f"Falta REPASSE: {op_nome} / ADESAO / {MODELO_NOME.get(modelo, modelo)}")
        
        return {
            'codigo': nivel or modelo, 'modelo': modelo, 'nivel': nivel, 'plano': plano,
            'num_parcelas': 1, 'dist_corretora': '100',
            'regua_mens': [rep_mens] if rep_mens else [0.0], 'receb_mens': receb_mens, 'rep_mens': rep_mens, 'taxa': 1,
            'valor': valor, 'total_corretora': total_corretora,
            'consultor': consultor, 'liquido': liquido,
            'regua_receb': regua_receb,
            'aviso': ' · '.join(avisos),
        }

    # ==========================================
    # --- RAMO PADRÃO: PME / PF ---
    # ==========================================
    consultor = round(valor * rep_mens, 2)
    liquido = round(total_corretora - consultor, 2)

    regua = [float(x) for x in regua_str.split(';') if x.strip()]
    if not regua:
        regua = [rep_mens] if rep_mens else [0.0]

    _fecha()
    avisos = []
    if receb_mens == 0:
        avisos.append(f"Falta RECEBIMENTO: {op_nome} / {plano}")
    if rep_mens == 0:
        avisos.append(f"Falta REPASSE: {op_nome} / {plano} / {MODELO_NOME.get(modelo, modelo)}{(' / ' + nivel.upper()) if nivel else ''}")

    return {
        'codigo': nivel or modelo, 'modelo': modelo, 'nivel': nivel, 'plano': plano,
        'num_parcelas': len(regua), 'dist_corretora': regua_str or ';'.join(str(x) for x in regua),
        'regua_mens': regua, 'receb_mens': receb_mens, 'rep_mens': rep_mens, 'taxa': taxa,
        'valor': valor, 'total_corretora': total_corretora,
        'consultor': consultor, 'liquido': liquido,
        'regua_receb': regua_receb,
        'aviso': ' · '.join(avisos),
    }


# ═══════════ MOTOR DE REGRA DO GESTOR/ADMIN VENDEDOR ═══════════
# Todo admin e todo gestor pode vender. O que muda de venda pra venda é a
# OPERADORA, a variação e o plano — não a pessoa. Por isso a regra é comercial e
# mora em gestor_regra, e não num campo do usuário.
#
# O legado 'gestor_vendedor' continua no arquivo e continua sendo lido, mas só
# para HISTÓRICO. Ele entrega 100% de toda a comissão numa parcela só, o que
# não é o combinado: ele não distingue fração da operadora, parte do gestor e
# retenção, então também não sabe dizer o que sobra para a Serenus. Não
# recalculamos nada com ele — proposta antiga fica como está.
#
# QUATRO CONTAS SEPARADAS, nesta ordem:
#   1. régua de recebimento — quanto e quando a operadora/Affinity paga;
#   2. régua do gestor      — quanto de cada fração recebida é do gestor;
#   3. retenção             — o que sai do bruto do gestor, e de quem é a conta;
#   4. saldo Serenus        — recebido menos bruto do gestor, menos as retenções
#                             de responsabilidade da empresa, menos despesas.
_GESTOR_PERFIS = ('admin', 'supervisor', 'gestor_vendedor')
_RETENCAO_BASES = ('bruto_gestor', 'fracao_recebida')
_RETENCAO_RESPONSAVEIS = ('gestor', 'serenus')


def _gestor_regra_buscar(conn, operadora, plano):
    """Acha a regra por operadora + variação + plano. Devolve (regra, retencoes).

    Cai para a regra sem variação (obs vazio) quando a exata não existe — mesmo
    comportamento das tabelas de recebimento e repasse, pra não obrigar a
    cadastrar toda variação quando a regra é a mesma."""
    op_nome, op_obs = _split_operadora(operadora)
    try:
        r = conn.execute("""SELECT * FROM gestor_regra
                            WHERE operadora=? AND obs=? AND plano=? AND COALESCE(ativo,1)=1""",
                         (op_nome, op_obs, plano)).fetchone()
        if not r:
            r = conn.execute("""SELECT * FROM gestor_regra
                                WHERE operadora=? AND plano=? AND COALESCE(ativo,1)=1
                                ORDER BY (obs='') DESC LIMIT 1""", (op_nome, plano)).fetchone()
        if not r:
            return None, []
        ret = [dict(x) for x in conn.execute(
            """SELECT * FROM gestor_retencao WHERE regra_id=? AND COALESCE(ativo,1)=1
               ORDER BY id""", (r['id'],)).fetchall()]
        return dict(r), ret
    except Exception:
        if DB_MODE == 'postgres':
            try: conn.rollback()
            except Exception: pass
        return None, []


def _gestor_regra_faltas(regra, retencoes):
    """O que falta pra regra estar COMPLETA. Lista de frases prontas pra tela.

    Regra incompleta não é erro de digitação — é uma pergunta comercial ainda sem
    resposta. Por isso a lista diz o que perguntar, e não 'campo inválido'."""
    falta = []
    if not regra:
        return ['A régua de recebimento desta operadora, variação e plano não está cadastrada.']
    try:
        fracoes = json.loads(regra.get('fracoes_json') or '[]')
    except Exception:
        fracoes = []
    try:
        gestor = json.loads(regra.get('gestor_json') or '[]')
    except Exception:
        gestor = []
    if not fracoes:
        falta.append('Falta a régua de recebimento: quantas frações a operadora paga, '
                     'com que percentual e em que mês ou evento.')
    for f in fracoes:
        if f.get('percentual') is None:
            falta.append(f"Fração {f.get('ordem', '?')} da régua de recebimento está sem percentual.")
        if not (f.get('evento') or f.get('mes')):
            falta.append(f"Fração {f.get('ordem', '?')} está sem mês ou evento definido.")
    if not gestor:
        falta.append('Falta a régua do gestor: quanto de cada fração recebida pertence a ele.')
    elif len(gestor) != len(fracoes):
        falta.append(f'A régua do gestor tem {len(gestor)} fração(ões) e a de recebimento tem '
                     f'{len(fracoes)}. As duas precisam falar das mesmas frações.')
    for g in gestor:
        if g.get('percentual_gestor') is None:
            falta.append(f"Fração {g.get('ordem', '?')} da régua do gestor está sem percentual.")
    if not regra.get('confirmada'):
        falta.append('A régua foi montada mas ninguém confirmou. A sugestão de 100% na primeira '
                     'fração é sugestão — precisa de confirmação de quem responde pelo comercial.')
    for r in retencoes:
        # NULL é ausência de decisão; 0 é uma decisão. A diferença é o ponto.
        if r.get('percentual') is None:
            falta.append(f"A retenção '{r.get('nome') or r.get('tipo')}' está sem alíquota informada. "
                         f"O JOB não inventa alíquota.")
        if r.get('base_calculo') not in _RETENCAO_BASES:
            falta.append(f"A retenção '{r.get('nome') or r.get('tipo')}' está sem base de cálculo.")
        if r.get('responsavel') not in _RETENCAO_RESPONSAVEIS:
            falta.append(f"A retenção '{r.get('nome') or r.get('tipo')}' está sem responsável "
                         f"(quem paga: o gestor ou a Serenus).")
    return falta


def _gestor_calcular(snapshot, total_corretora):
    """Abre a conta fração a fração a partir do snapshot congelado na proposta.

    Devolve por fração: quanto se espera receber, quanto é bruto do gestor,
    quanto é retenção (separada por responsável), quanto sai líquido pro PIX do
    gestor e quanto sobra de saldo Serenus.

    Não calcula nada quando a regra está incompleta: devolver número com regra
    pela metade é pior que não devolver, porque número na tela vira decisão."""
    vazio = {'completa': False, 'fracoes': [], 'total_recebido': 0.0, 'total_bruto_gestor': 0.0,
             'total_retencao_gestor': 0.0, 'total_retencao_serenus': 0.0,
             'total_liquido_gestor': 0.0, 'total_saldo_serenus': 0.0}
    if not snapshot or not snapshot.get('completa'):
        return vazio
    try:
        fracoes = json.loads(snapshot.get('fracoes_json') or '[]')
        gestor = json.loads(snapshot.get('gestor_json') or '[]')
        retencoes = json.loads(snapshot.get('retencoes_json') or '[]')
    except Exception:
        return vazio
    gpor = {int(g.get('ordem', 0)): g for g in gestor}
    base = float(total_corretora or 0)
    # Os percentuais da régua de recebimento são *fatias da mensalidade*.
    # Ex.: 100% + 100% + 80% representa 2,8 mensalidades. Eles não podem
    # incidir cada um sobre a comissão total, pois isso faria uma comissão de
    # R$ 5.400 virar R$ 15.120. Para distribuir a comissão total sem inventar
    # dinheiro, cada fração recebe seu peso relativo dentro da régua inteira.
    # Também funciona para uma regra 30% + 70%, cuja soma já é 100%.
    pesos = [max(0.0, float(f.get('percentual') or 0)) for f in fracoes]
    peso_total = sum(pesos)
    if peso_total <= 0:
        return vazio
    linhas = []
    for indice, f in enumerate(fracoes):
        ordem = int(f.get('ordem', 0))
        pct_receb = float(f.get('percentual') or 0)
        # A última absorve só o resíduo de centavos da divisão. Assim, todas
        # as retenções abaixo são calculadas sobre o valor final da fração.
        recebido = (round(base * pct_receb / peso_total, 2)
                    if indice < len(fracoes) - 1
                    else round(base - sum(l['recebido'] for l in linhas), 2))
        pct_gestor = float((gpor.get(ordem) or {}).get('percentual_gestor') or 0)
        bruto_gestor = round(recebido * pct_gestor / 100.0, 2)
        ret_gestor, ret_serenus, det = 0.0, 0.0, []
        for r in retencoes:
            pct = r.get('percentual')
            if pct is None:
                continue
            alvo = bruto_gestor if r.get('base_calculo') == 'bruto_gestor' else recebido
            v = round(alvo * float(pct) / 100.0, 2)
            if r.get('responsavel') == 'serenus':
                ret_serenus += v
            else:
                ret_gestor += v
            det.append({'nome': r.get('nome') or r.get('tipo'), 'percentual': float(pct),
                        'base': r.get('base_calculo'), 'responsavel': r.get('responsavel'),
                        'valor': v})
        liquido_gestor = round(bruto_gestor - ret_gestor, 2)
        saldo_serenus = round(recebido - bruto_gestor - ret_serenus, 2)
        linhas.append({
            'ordem': ordem, 'evento': f.get('evento') or '', 'mes': f.get('mes'),
            'percentual_recebimento': pct_receb, 'recebido': recebido,
            'percentual_gestor': pct_gestor, 'bruto_gestor': bruto_gestor,
            'retencao_gestor': round(ret_gestor, 2), 'retencao_serenus': round(ret_serenus, 2),
            'retencoes': det,
            'liquido_gestor': liquido_gestor, 'saldo_serenus': saldo_serenus,
        })
    som = lambda k: round(sum(l[k] for l in linhas), 2)
    return {'completa': True, 'fracoes': linhas,
            'total_recebido': som('recebido'), 'total_bruto_gestor': som('bruto_gestor'),
            'total_retencao_gestor': som('retencao_gestor'),
            'total_retencao_serenus': som('retencao_serenus'),
            'total_liquido_gestor': som('liquido_gestor'),
            'total_saldo_serenus': som('saldo_serenus')}


def _gestor_e_vendedor(conn, usuario_id):
    """O usuário desta venda é gestor/admin vendendo? Pergunta ao PERFIL, não a um
    campo de regime — todo admin e todo gestor pode vender, e forçar
    'sem_lead_sem_fixo' no cadastro deles era o que fazia a venda de um gestor
    cair na régua de consultor sem ninguém escolher isso."""
    if not usuario_id:
        return False
    try:
        u = conn.execute("SELECT perfil FROM usuarios WHERE id=?", (usuario_id,)).fetchone()
        return bool(u and (u['perfil'] or '') in _GESTOR_PERFIS)
    except Exception:
        return False


def _gestor_congelar_snapshot(conn, proposta_id, operadora, plano, usuario_id, usuario_nome):
    """Congela a regra vigente NA PROPOSTA. Só INSERT: snapshot existente nunca é
    reescrito.

    É o que impede que mudar a regra amanhã mude o que foi combinado ontem. Sem
    isso, corrigir um percentual reescreveria silenciosamente a comissão de todas
    as vendas passadas — e ninguém consegue explicar pro consultor por que o
    valor da venda dele mudou sozinho."""
    ja = conn.execute("SELECT id FROM proposta_regra_snapshot WHERE proposta_id=?",
                      (proposta_id,)).fetchone()
    if ja:
        return False
    regra, retencoes = _gestor_regra_buscar(conn, operadora, plano)
    falta = _gestor_regra_faltas(regra, retencoes)
    op_nome, op_obs = _split_operadora(operadora)
    conn.execute("""INSERT INTO proposta_regra_snapshot
        (proposta_id, regra_id, operadora, obs, plano, fracoes_json, gestor_json,
         retencoes_json, completa, falta_json, usuario_id, usuario_nome, congelado_por, congelado_em)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (proposta_id, (regra or {}).get('id'), op_nome, op_obs, plano,
         (regra or {}).get('fracoes_json') or '[]', (regra or {}).get('gestor_json') or '[]',
         json.dumps(retencoes, ensure_ascii=False, default=str),
         0 if falta else 1, json.dumps(falta, ensure_ascii=False),
         usuario_id, usuario_nome, usuario_nome, _agora_sp()))
    return True


def _gestor_calculo_inicial(conn, operadora, modalidade, tipo_pessoa, valor):
    """Monta as parcelas iniciais de uma venda de sócio/gestor.

    Isso é deliberadamente separado de ``calc_comissao``: aquele motor continua
    exclusivo dos três regimes de consultor. Para sócio/gestor, a única fonte é
    a regra comercial cadastrada por operadora, variação e plano.

    Enquanto a regra não estiver completa, a venda pode nascer como rascunho,
    mas não ganha valores fictícios nem parcelas do modelo Sem Lead/Sem Fixo.
    """
    plano = _plano_from_modalidade(modalidade, tipo_pessoa)
    regra, retencoes = _gestor_regra_buscar(conn, operadora, plano)
    falta = _gestor_regra_faltas(regra, retencoes)
    op_nome, _op_obs = _split_operadora(operadora)
    if falta:
        return {
            'codigo': 'socio_gestor_pendente', 'modelo': 'socio_gestor_pendente',
            'nivel': '', 'plano': plano, 'num_parcelas': 0,
            'dist_corretora': '', 'regua_mens': [], 'receb_mens': 0.0,
            'rep_mens': 0.0, 'taxa': 0, 'valor': valor,
            'total_corretora': 0.0, 'consultor': 0.0, 'liquido': 0.0,
            'aviso': 'Regra de comissão do sócio/gestor pendente: ' + falta[0],
            'falta_regra_gestor': falta, 'operadora_regra': op_nome,
        }
    snap = {
        'completa': 1, 'fracoes_json': regra['fracoes_json'],
        'gestor_json': regra['gestor_json'],
        'retencoes_json': json.dumps(retencoes, ensure_ascii=False, default=str),
    }
    # O valor de recebimento da corretora continua vindo da tabela Operadoras.
    # A nova regra divide esse recebimento; ela não inventa a comissão total.
    # Mesma resolucao que calc_comissao usa: 'MedSenior' PF e 'Med Senior SP/RJ'
    # PF sao a mesma operadora, e sem resolver o nome a busca falha e a comissao
    # zera. Antes esta funcao buscava so pelo nome cru, entao venda de gestor e
    # venda de consultor podiam achar linhas DIFERENTES para a mesma operadora.
    op_nome = _resolver_nome_operadora(conn, op_nome, plano)
    receb = conn.execute(
        "SELECT * FROM recebimento WHERE operadora=? AND obs=? AND plano=?",
        (op_nome, _op_obs, plano)).fetchone()
    if not receb:
        receb = conn.execute(
            "SELECT * FROM recebimento WHERE operadora=? AND plano=? ORDER BY (obs='') DESC LIMIT 1",
            (op_nome, plano)).fetchone()
    # A promocao vale para QUEM vendeu, nao so para consultor. Sem isto a venda
    # de socio/gestor era calculada pela tabela e a diferenca negociada sumia.
    _rd = dict(receb) if receb else {}
    receb_mens = float(_rd.get('total') or 0)
    if _rd.get('promo_total'):
        try: receb_mens = float(_rd['promo_total'])
        except (TypeError, ValueError): pass
    total_corretora = round(float(valor or 0) * receb_mens, 2) if receb else 0.0
    if not receb:
        return {
            'codigo': 'socio_gestor_pendente', 'modelo': 'socio_gestor_pendente',
            'nivel': '', 'plano': plano, 'num_parcelas': 0,
            'dist_corretora': '', 'regua_mens': [], 'receb_mens': 0.0,
            'rep_mens': 0.0, 'taxa': 0, 'valor': valor,
            'total_corretora': 0.0, 'consultor': 0.0, 'liquido': 0.0,
            'aviso': f'Falta RECEBIMENTO: {op_nome} / {plano}.',
            'falta_regra_gestor': [f'Falta cadastrar quanto a corretora recebe de {op_nome} / {plano}.'],
            'operadora_regra': op_nome,
        }
    conta = _gestor_calcular(snap, total_corretora)
    regua = [f['percentual_recebimento'] / 100.0 for f in conta['fracoes']]
    return {
        'codigo': 'socio_gestor_regra', 'modelo': 'socio_gestor_regra',
        'nivel': '', 'plano': plano, 'num_parcelas': len(regua),
        'dist_corretora': ';'.join(str(x) for x in regua), 'regua_mens': regua,
        'receb_mens': receb_mens, 'receb_operadora': op_nome,
        'receb_tabela': float(_rd.get('total') or 0),
        'receb_promo': bool(_rd.get('promo_total')), 'rep_mens': 0.0, 'taxa': 0,
        'valor': valor, 'total_corretora': total_corretora,
        # A coluna histórica continua populada para compatibilidade; o número
        # definitivo para pagamento vem do snapshot congelado e da retenção.
        'consultor': conta['total_liquido_gestor'],
        'liquido': conta['total_saldo_serenus'], 'aviso': '',
        'fracoes_gestor': conta['fracoes'],
        'falta_regra_gestor': [], 'operadora_regra': op_nome,
    }


def _migrar_venda_legada_para_gestor(conn, proposta_id, usuario_executor):
    """Troca UMA venda antiga de gestor do regime de consultor para a regra nova.

    Não é recálculo em massa. É uma decisão explícita na própria proposta e só
    é permitida antes de dinheiro andar: parcela paga, PIX iniciado ou extrato
    conciliado tornam a venda imutável. Antes de substituir o snapshot acidental
    ou legado, o estado anterior é guardado no histórico da proposta.
    """
    p = conn.execute("SELECT * FROM propostas WHERE id=?", (proposta_id,)).fetchone()
    if not p:
        return False, 'Venda não encontrada.'
    if not _gestor_e_vendedor(conn, p['usuario_id']):
        return False, 'O vendedor desta proposta não é gestor/admin. O regime de consultor foi preservado.'
    if (p['regime_aplicado'] or '') in ('socio_gestor_regra', 'socio_gestor_pendente'):
        return False, 'Esta venda já usa a regra de sócio/gestor.'
    travas = _historico_travas(conn, proposta_id)
    if travas:
        return False, 'Esta venda já tem financeiro em andamento: ' + travas[0]
    # Mesmo sem PIX ou conciliação, uma parcela liberada já foi conferida pela
    # equipe; não mudamos sua origem silenciosamente.
    fora_da_fila = conn.execute("""SELECT numero,status FROM parcelas WHERE proposta_id=?
                                  AND COALESCE(status,'') NOT IN
                                  ('Pendente de receber','Bloqueado - Falta Comprovante')
                                  ORDER BY numero LIMIT 1""", (proposta_id,)).fetchone()
    if fora_da_fila:
        return False, f"Parcela {fora_da_fila['numero']} já saiu da fila inicial ({fora_da_fila['status']})."
    c = _gestor_calculo_inicial(conn, p['adm_operadora'] or '', p['modalidade'] or '',
                                p['tipo_pessoa'] if 'tipo_pessoa' in p.keys() else '', p['valor'] or 0)
    if c.get('modelo') != 'socio_gestor_regra':
        aviso = (c.get('falta_regra_gestor') or [c.get('aviso') or 'Regra incompleta.'])[0]
        return False, 'A migração não foi feita: ' + aviso
    anterior = {
        'regime_aplicado': p['regime_aplicado'], 'num_parcelas': p['num_parcelas'],
        'distribuicao_parcelas': p['distribuicao_parcelas'],
        'comissao_total_corretora': p['comissao_total_corretora'],
        'comissao_consultor': p['comissao_consultor'],
        'comissao_corretora_liquida': p['comissao_corretora_liquida'],
        'snapshot': _gestor_snapshot(conn, proposta_id),
    }
    conn.execute("""INSERT INTO historico_proposta
        (proposta_id,usuario_nome,campo,valor_antes,valor_depois,criado_em)
        VALUES (?,?,?,?,?,?)""",
        (proposta_id, usuario_executor, 'Migração para regra de sócio/gestor',
         json.dumps(anterior, ensure_ascii=False, default=str)[:3000],
         json.dumps({'regime_aplicado': c['codigo'], 'recebimento': c['total_corretora'],
                     'repasse_gestor': c['consultor'], 'saldo_serenus': c['liquido']},
                    ensure_ascii=False)[:3000], _agora_sp()))
    conn.execute("""UPDATE propostas SET regime_aplicado=?,num_parcelas=?,distribuicao_parcelas=?,
                    comissao_total_corretora=?,comissao_consultor=?,comissao_corretora_liquida=?
                    WHERE id=?""",
                 (c['codigo'], c['num_parcelas'], c['dist_corretora'], c['total_corretora'],
                  c['consultor'], c['liquido'], proposta_id))
    conn.execute("DELETE FROM parcelas WHERE proposta_id=?", (proposta_id,))
    for parc in gerar_parcelas_socio_gestor(proposta_id, p['vigencia'] or '', c,
                                             p['dia_vencimento'] if 'dia_vencimento' in p.keys() else None):
        conn.execute("""INSERT INTO parcelas
            (proposta_id,numero,percentual,valor,valor_corretora,perc_cliente,data_prevista,status,
             competencia,mensalidade_ref,tipo_origem)
            VALUES (?,?,?,?,?,?,?,?,?,?,'comissao')""",
            (parc['proposta_id'], parc['numero'], parc['percentual'], parc['valor'],
             parc['valor_corretora'], parc['perc_cliente'], parc['data_prevista'], parc['status'],
             parc['competencia'], parc['mensalidade_ref']))
    # Alguns cadastros feitos na transição receberam snapshot mesmo usando o
    # regime de consultor. Ele não é apagado sem rastro: está no histórico acima.
    conn.execute("DELETE FROM proposta_regra_snapshot WHERE proposta_id=?", (proposta_id,))
    _gestor_congelar_snapshot(conn, proposta_id, p['adm_operadora'] or '', c['plano'],
                              p['usuario_id'], p['consultor'] or usuario_executor)
    return True, 'Venda atualizada para a regra de sócio/gestor.'


def _gestor_retencao_empresa(conn, meses=6):
    """De cada R$100 que a administradora paga em venda de sócio, quanto FICA
    na empresa — e quanto de aporte foi preciso no mesmo período.

    Este é o número que explica o aporte. Ele existe hoje espalhado em vinte
    réguas separadas, e ninguém consegue somar de cabeça: cada regra diz sua
    fatia, nenhuma diz o efeito no caixa. Sem ele, "a empresa fica sem dinheiro"
    é sensação; com ele, é conta — e a régua do gestor vira uma decisão em vez
    de um hábito."""
    out = {'tem_dados': False, 'meses': meses}
    try:
        corte = (datetime.now(TZ_SP) - relativedelta(months=meses)).strftime('%Y-%m-%d')
        bruto = gestor = serenus = 0.0
        vendas = 0
        for s in conn.execute("""SELECT s.*, COALESCE(p.comissao_total_corretora,0) comissao
                                   FROM proposta_regra_snapshot s
                                   JOIN propostas p ON p.id = s.proposta_id
                                  WHERE COALESCE(p.status,'') <> 'Excluída'
                                    AND COALESCE(p.estornada,0) = 0
                                    AND COALESCE(p.regime_aplicado,'') IN
                                        ('socio_gestor_regra','socio_gestor_pendente')
                                    AND COALESCE(p.vigencia,'') >= ?""", (corte,)).fetchall():
            snap = dict(s)
            if not snap.get('completa'):
                continue
            r = _gestor_calcular(snap, snap['comissao'])
            if not r.get('completa'):
                continue
            vendas += 1
            bruto += float(r.get('total_recebido') or 0)
            gestor += float(r.get('total_bruto_gestor') or 0)
            serenus += float(r.get('total_saldo_serenus') or 0)
        if not vendas:
            return out
        out.update({'tem_dados': True, 'vendas': vendas,
                    'bruto': round(bruto, 2), 'gestor': round(gestor, 2),
                    'serenus': round(serenus, 2),
                    'por_cem': round((serenus / bruto * 100), 1) if bruto else 0.0})
        # Aporte no mesmo período: o contraponto. Se a empresa retém pouco e
        # precisa de aporte alto, os dois números contam a mesma história.
        try:
            ap = conn.execute("""SELECT COALESCE(SUM(valor),0) v FROM lancamentos
                                  WHERE tipo='aporte' AND COALESCE(data_competencia,'') >= ?""",
                              (corte[:7],)).fetchone()['v']
            out['aporte'] = round(float(ap or 0), 2)
        except Exception:
            out['aporte'] = None
    except Exception as e:
        app.logger.warning(f"[GESTOR] retencao da empresa nao calculada: {e}")
    return out


def _gestor_snapshot(conn, proposta_id):
    try:
        r = conn.execute("SELECT * FROM proposta_regra_snapshot WHERE proposta_id=?",
                         (proposta_id,)).fetchone()
        return dict(r) if r else None
    except Exception:
        if DB_MODE == 'postgres':
            try: conn.rollback()
            except Exception: pass
        return None


def _gestor_bloqueio(conn, proposta_id):
    """O que está travado nesta venda por falta de regra, e por quê.

    Devolve {'bloqueia': bool, 'falta': [...], 'operadora': ..., 'plano': ...,
    'link': ...}. O link é a ação direta: abre a configuração exata que falta, em
    vez de mandar a pessoa procurar no menu qual das telas de comissão é a certa.

    Venda de consultor não passa por aqui: a regra do gestor não se aplica a ela,
    e bloquear o que não depende dessa regra pararia o sistema inteiro."""
    vazio = {'bloqueia': False, 'falta': [], 'operadora': '', 'plano': '', 'link': '',
             'eh_gestor': False}
    p = conn.execute("""SELECT id, usuario_id, adm_operadora, modalidade, tipo_pessoa, status,
                               regime_aplicado
                        FROM propostas WHERE id=?""", (proposta_id,)).fetchone()
    if not p:
        return vazio
    # Perfil atual da pessoa não reclassifica uma venda que já foi gravada. Só
    # propostas nascidas com a regra comercial própria entram neste motor.
    # Isso protege os repasses históricos de consultor, inclusive quando um
    # consultor depois vira administrador ou gestor.
    if (p['regime_aplicado'] or '') not in ('socio_gestor_regra', 'socio_gestor_pendente'):
        return vazio
    plano = _plano_from_modalidade(p['modalidade'], p['tipo_pessoa'] if 'tipo_pessoa' in p.keys() else '')
    operadora = p['adm_operadora'] or ''
    snap = _gestor_snapshot(conn, proposta_id)
    if snap:
        try:
            falta = json.loads(snap.get('falta_json') or '[]')
        except Exception:
            falta = []
        completa = bool(snap.get('completa'))
    else:
        regra, retencoes = _gestor_regra_buscar(conn, operadora, plano)
        falta = _gestor_regra_faltas(regra, retencoes)
        completa = not falta
    op_nome, op_obs = _split_operadora(operadora)
    from urllib.parse import urlencode as _ue
    link = '/comissoes/regra-gestor?' + _ue({'operadora': op_nome, 'obs': op_obs, 'plano': plano})
    return {'bloqueia': not completa, 'falta': falta, 'operadora': operadora or '(sem operadora)',
            'plano': plano, 'link': link, 'eh_gestor': True,
            'tem_snapshot': bool(snap)}


def _fin_visao(conn, competencia=''):
    """LEITURA ÚNICA DO DINHEIRO DE COMISSÃO. Financeiro e Fluxo de Caixa chamam
    esta função, e só ela — as duas telas discordavam porque cada uma somava de
    uma tabela diferente, e duas verdades sobre o mesmo dinheiro é o mesmo que
    nenhuma.

    Lê do razão (fin_evento) e da conciliação. Não duplica lançamento: o razão é
    append-only e cada fato tem chave única, então somar aqui não pode contar
    duas vezes o que foi importado duas vezes — porque não foi.

    As colunas são as sete perguntas que a operação faz, nesta ordem:
      bruto esperado      — o que a régua diz que deveria vir;
      apurado Affinity    — o que ela emitiu extrato dizendo que vai pagar;
      entrada confirmada  — o que se provou que entrou na conta;
      bruto do gestor     — a parte dele, antes de retenção;
      retenção            — o que sai, com responsável definido;
      líquido para PIX    — o que ele recebe de fato;
      saldo Serenus       — o que sobra pra empresa.
    """
    onde, params = '', []
    if competencia:
        onde, params = 'WHERE competencia = ?', [competencia]

    def _soma(estado, papel=None, sinal=None):
        sql = f"""SELECT COALESCE(SUM(valor),0) v FROM fin_evento
                  {onde}{' AND' if onde else 'WHERE'} estado = ?"""
        p = list(params) + [estado]
        if papel:
            sql += " AND papel = ?"; p.append(papel)
        if sinal is not None:
            sql += " AND sinal = ?"; p.append(sinal)
        try:
            return round(float(conn.execute(sql, p).fetchone()['v'] or 0), 2)
        except Exception:
            return 0.0

    visao = {
        'competencia': competencia,
        'apurado_affinity': round(_soma('apurado_affinity', 'affinity', 1), 2),
        'tarifas': round(_soma('apurado_affinity', 'tarifa', -1), 2),
        'entrada_confirmada': round(_soma('entrada_confirmada'), 2),
        'bruto_esperado': 0.0, 'bruto_gestor': 0.0, 'retencao_gestor': 0.0,
        'retencao_serenus': 0.0, 'liquido_pix_gestor': 0.0, 'saldo_serenus': 0.0,
        'vendas_gestor': 0, 'sem_regra': 0,
    }
    # Bruto esperado e a conta do gestor vêm do snapshot congelado de cada venda:
    # é o que foi COMBINADO, não o que a régua de hoje diria.
    try:
        sql = """SELECT s.*, COALESCE(p.comissao_total_corretora,0) comissao
                 FROM proposta_regra_snapshot s
                 JOIN propostas p ON p.id = s.proposta_id
                 WHERE COALESCE(p.status,'') <> 'Excluída' AND COALESCE(p.estornada,0)=0"""
        sql += " AND COALESCE(p.regime_aplicado,'') IN ('socio_gestor_regra','socio_gestor_pendente')"
        # ESCOPO: quando a tela pede um mês, este bloco também tem que respeitar.
        # Antes ele somava TODAS as vendas de gestor de todos os tempos enquanto
        # o resto da tela mostrava só o mês — dois números com cara de "o que
        # vamos receber" e escopos diferentes, um do lado do outro.
        # A fração `ordem` corresponde a `parcelas.numero`, e a parcela é quem
        # sabe a competência. Por isso o mapa vem de lá.
        comp_por_parcela = {}
        if competencia:
            try:
                for pr in conn.execute(
                        "SELECT proposta_id, numero FROM parcelas WHERE competencia = ?",
                        (competencia,)).fetchall():
                    d = dict(pr)
                    comp_por_parcela.setdefault(d['proposta_id'], set()).add(d['numero'])
            except Exception:
                comp_por_parcela = {}

        for s in conn.execute(sql).fetchall():
            snap = dict(s)
            if not snap.get('completa'):
                # Venda sem regra completa conta como pendência do mês inteiro:
                # não dá pra dizer em que competência ela cairia.
                visao['vendas_gestor'] += 1
                visao['sem_regra'] += 1
                continue
            r = _gestor_calcular(snap, snap['comissao'])
            fracoes = r.get('fracoes') or []
            if competencia:
                nums = comp_por_parcela.get(snap.get('proposta_id')) or set()
                fracoes = [f for f in fracoes if f.get('ordem') in nums]
                if not fracoes:
                    continue          # esta venda não tem fração neste mês
            visao['vendas_gestor'] += 1
            visao['bruto_esperado'] += sum(f['recebido'] for f in fracoes)
            visao['bruto_gestor'] += sum(f['bruto_gestor'] for f in fracoes)
            visao['retencao_gestor'] += sum(f['retencao_gestor'] for f in fracoes)
            visao['retencao_serenus'] += sum(f['retencao_serenus'] for f in fracoes)
            visao['liquido_pix_gestor'] += sum(f['liquido_gestor'] for f in fracoes)
            visao['saldo_serenus'] += sum(f['saldo_serenus'] for f in fracoes)
    except Exception:
        if DB_MODE == 'postgres':
            try: conn.rollback()
            except Exception: pass
    for k in ('bruto_esperado', 'bruto_gestor', 'retencao_gestor', 'retencao_serenus',
              'liquido_pix_gestor', 'saldo_serenus'):
        visao[k] = round(visao[k], 2)
    visao['retencao_total'] = round(visao['retencao_gestor'] + visao['retencao_serenus'], 2)
    # A diferença entre apurado e confirmado é a pergunta que a tela precisa
    # fazer sozinha: quanto a Affinity disse que paga e ainda não apareceu.
    visao['aguardando_entrada'] = round(visao['apurado_affinity'] - visao['entrada_confirmada'], 2)
    try:
        visao['linhas_sem_vinculo'] = conn.execute(
            "SELECT COUNT(*) c FROM affinity_conciliacao WHERE estado='sem_vinculo'").fetchone()['c']
    except Exception:
        visao['linhas_sem_vinculo'] = 0
    return visao


def _gestor_regras_faltando(conn, limite=400):
    """Resumo das vendas de gestor travadas por regra incompleta, agrupado por
    operadora/variação/plano — que é o que precisa ser cadastrado.

    Agrupado e não uma linha por venda de propósito: 40 vendas travadas pela MESMA
    operadora são um cadastro faltando, não 40 problemas. Listar 40 esconde que é
    um só."""
    grupos = {}
    try:
        propostas = conn.execute("""SELECT id FROM propostas
                                    WHERE COALESCE(status,'') <> 'Excluída'
                                      AND COALESCE(estornada,0)=0
                                    ORDER BY id DESC LIMIT ?""", (limite,)).fetchall()
    except Exception:
        return []
    for p in propostas:
        b = _gestor_bloqueio(conn, p['id'])
        if not b['bloqueia']:
            continue
        chave = (b['operadora'], b['plano'])
        g = grupos.setdefault(chave, {'operadora': b['operadora'], 'plano': b['plano'],
                                      'vendas': 0, 'falta': b['falta'][:2], 'link': b['link'],
                                      'exemplo': p['id']})
        g['vendas'] += 1
    return sorted(grupos.values(), key=lambda x: -x['vendas'])


def gerar_parcelas(proposta_id, vigencia, c, dia_vencimento=None, status_override=None):
    """Gera parcelas usando a régua REAL (mensalidades por parcela).
    Parcela consultor i = valor × regua[i]. Corretora distribuída proporcional à régua.
    status_override: força um status fixo em todas as parcelas (ex: 'Bloqueado - Falta Comprovante')."""
    from dateutil.relativedelta import relativedelta
    try:
        base = datetime.strptime(vigencia[:7], '%Y-%m') if (vigencia and len(vigencia) >= 7) else datetime.now(TZ_SP).replace(day=1)
    except Exception:
        base = datetime.now(TZ_SP).replace(day=1)

    dia = int(dia_vencimento) if dia_vencimento else base.day
    regua = c.get('regua_mens') or [float(x) for x in (c.get('dist_corretora','') or '').split(';') if x.strip()] or [1.0]
    valor = float(c.get('valor', 0))
    total_cor = float(c.get('total_corretora', 0))
    soma_regua = sum(regua) or 1.0

    # ── Recebível da corretora: usa a régua REAL da operadora quando existe ──
    # Antes o recebível era fatiado pela régua do CONSULTOR (mens/soma_regua).
    # Isso só acerta por acaso: a Amil paga 100/100/40 em 3 meses, e a régua do
    # consultor tem outro formato quase sempre. O resultado era um fluxo de caixa
    # errado por construção — e o /financeiro e o /bi herdavam o erro.
    # `regua_receb` = [{'ordem':1,'percentual':100,'mes':1}, ...] de recebimento.
    regua_receb = c.get('regua_receb') or []
    mapa_receb = {}
    if regua_receb:
        soma_receb = sum(float(f.get('percentual') or 0) for f in regua_receb) or 1.0
        for f in regua_receb:
            mes = int(f.get('mes') or f.get('ordem') or 0)
            if mes >= 1:
                mapa_receb[mes] = mapa_receb.get(mes, 0.0) + (
                    total_cor * (float(f.get('percentual') or 0) / soma_receb))

    # A operadora pode pagar em MAIS meses do que a régua do consultor tem
    # parcelas (é o caso da promoção: a diferença cai no mês seguinte ao último
    # da tabela). Sem isso esse dinheiro simplesmente não apareceria em lugar
    # nenhum. Nesses meses extras o consultor recebe 0 e a corretora recebe a
    # fração — a linha existe pro caixa enxergar a entrada.
    n_parcelas = max(len(regua), max(mapa_receb) if mapa_receb else 0)

    parcelas = []
    for i in range(n_parcelas):
        mens = regua[i] if i < len(regua) else 0.0
        mes_ref = base + relativedelta(months=i)
        try:
            data = mes_ref.replace(day=min(dia, 28)).strftime('%Y-%m-%d')
        except Exception:
            data = mes_ref.strftime('%Y-%m-01')
        val_c = round(valor * mens, 2)
        if mapa_receb:
            val_cor = round(mapa_receb.get(i + 1, 0.0), 2)
        else:
            val_cor = round(total_cor * (mens / soma_regua), 2)
        perc = round((mens / soma_regua) * 100, 2)
        parcelas.append({
            'proposta_id': proposta_id, 'numero': i + 1, 'percentual': perc,
            'valor': val_c, 'valor_corretora': val_cor, 'perc_cliente': perc,
            'data_prevista': data,
            'status': status_override if status_override else 'Pendente de receber',
            'competencia': mes_ref.strftime('%Y-%m'), 'mensalidade_ref': i + 1,
        })
    return parcelas


def gerar_parcelas_socio_gestor(proposta_id, vigencia, c, dia_vencimento=None,
                                status_override=None):
    """Gera parcelas da régua comercial de sócio/gestor.

    ``parcelas.valor`` continua sendo a quantia líquida a pagar à pessoa, como
    sempre foi. Diferente dos consultores, ela não pode ser derivada do valor
    mensal do cliente: vem de cada fração, depois da retenção cadastrada.
    """
    from dateutil.relativedelta import relativedelta
    try:
        base = datetime.strptime(vigencia[:7], '%Y-%m') if vigencia and len(vigencia) >= 7 else datetime.now(TZ_SP).replace(day=1)
    except Exception:
        base = datetime.now(TZ_SP).replace(day=1)
    dia = int(dia_vencimento) if dia_vencimento else base.day
    parcelas = []
    for i, f in enumerate(c.get('fracoes_gestor') or []):
        mes_ref = base + relativedelta(months=i)
        try:
            data = mes_ref.replace(day=min(dia, 28)).strftime('%Y-%m-%d')
        except Exception:
            data = mes_ref.strftime('%Y-%m-01')
        parcelas.append({
            'proposta_id': proposta_id, 'numero': i + 1,
            'percentual': round(float(f.get('percentual_recebimento') or 0), 2),
            'valor': round(float(f.get('liquido_gestor') or 0), 2),
            'valor_corretora': round(float(f.get('recebido') or 0), 2),
            'perc_cliente': round(float(f.get('percentual_recebimento') or 0), 2),
            'data_prevista': data,
            'status': status_override if status_override else 'Pendente de receber',
            'competencia': mes_ref.strftime('%Y-%m'), 'mensalidade_ref': i + 1,
        })
    return parcelas



# ─── AUTH ────────────────────────────────────────────────────────────────────────
# Hash de senha: PBKDF2-SHA256 com salt (via Werkzeug). Mantém retrocompatibilidade
# com senhas antigas em SHA-256 puro — essas são migradas no próximo login.
from werkzeug.security import generate_password_hash, check_password_hash
from werkzeug.utils import secure_filename

def _sanitizar_filename(nome):
    """Remove espaços, acentos e caracteres especiais do nome do arquivo.
    Mantém extensão. Ex: 'WhatsApp Image 2026.jpeg' → 'WhatsApp_Image_2026.jpeg'"""
    import unicodedata, re as _re
    # Normaliza unicode (remove acentos)
    nome = unicodedata.normalize('NFD', nome)
    nome = ''.join(c for c in nome if unicodedata.category(c) != 'Mn')
    # Substitui espaços e caracteres problemáticos por _
    nome = _re.sub(r'[\s\(\)\[\]]+', '_', nome)
    nome = _re.sub(r'[^\w\.\-]', '', nome)
    nome = _re.sub(r'_+', '_', nome).strip('_')
    return nome or 'arquivo'

def hash_senha(s):
    """Gera hash seguro PBKDF2 (com salt automático) para uma senha nova."""
    return generate_password_hash(s or '', method='pbkdf2:sha256', salt_length=16)

def _parse_dt_seguro(valor):
    """Converte um valor de data/hora para datetime, aceitando:
    - datetime já pronto (PostgreSQL retorna assim)
    - string ISO (SQLite retorna assim)
    Retorna None se vazio ou inválido."""
    if not valor:
        return None
    if isinstance(valor, datetime):
        return valor
    try:
        return datetime.fromisoformat(str(valor))
    except Exception:
        try:
            return datetime.strptime(str(valor)[:19], '%Y-%m-%d %H:%M:%S')
        except Exception:
            return None

def _data_expirada(valor):
    """True se a data/hora informada já passou. Trata datetime (PG) e string (SQLite),
    e lida com timezone de forma segura (sem erro de naive vs aware)."""
    expira = _parse_dt_seguro(valor)
    if not expira:
        return False
    agora = datetime.now(TZ_SP)
    try:
        if expira.tzinfo is None:
            agora = agora.replace(tzinfo=None)
        return expira < agora
    except Exception:
        return False

def _eh_sha256_legado(h):
    """Detecta o formato antigo: SHA-256 puro = 64 caracteres hexadecimais."""
    return isinstance(h, str) and len(h) == 64 and all(c in '0123456789abcdef' for c in h.lower())

def verifica_senha(senha_digitada, hash_armazenado):
    """Verifica senha aceitando tanto o formato novo (PBKDF2) quanto o antigo (SHA-256).
    Retorna (ok: bool, precisa_migrar: bool)."""
    if not hash_armazenado:
        return False, False
    if _eh_sha256_legado(hash_armazenado):
        # Formato antigo — compara SHA-256 puro
        ok = hashlib.sha256((senha_digitada or '').encode()).hexdigest() == hash_armazenado
        return ok, ok  # se acertou, sinaliza para migrar
    # Formato novo — PBKDF2
    try:
        return check_password_hash(hash_armazenado, senha_digitada or ''), False
    except Exception:
        return False, False


# ════════════════════════════════════════════════════════════════════════════
# SEGURANÇA: Decorators robusto + Sanitização + Logging
# ════════════════════════════════════════════════════════════════════════════

def require_auth(f):
    """Valida autenticação. Retorna JSON 401 (não redirect)."""
    @wraps(f)
    def wrapper(*args, **kwargs):
        user_id = session.get('user_id')
        perfil = session.get('perfil')
        if not user_id or perfil not in ('admin', 'consultor', 'supervisor'):
            app.logger.warning(f"[AUTH] Acesso não autenticado a {request.endpoint}")
            return jsonify({'erro': 'Não autenticado', 'codigo': 'AUTH_REQUIRED'}), 401
        return f(*args, **kwargs)
    return wrapper

def require_admin(f):
    """Permite apenas admin. Retorna 403 se não autorizado."""
    @wraps(f)
    def wrapper(*args, **kwargs):
        user_id = session.get('user_id')
        perfil = session.get('perfil')
        if not user_id or perfil != 'admin':
            app.logger.warning(f"[AUTH] Negado (não-admin) em {request.endpoint} por user_id={user_id}")
            return jsonify({'erro': 'Acesso negado', 'codigo': 'FORBIDDEN'}), 403
        return f(*args, **kwargs)
    return wrapper

def sanitize_string(s, max_length=255):
    """Valida entrada: deve ser string, não vazia, tamanho <= max_length."""
    if not isinstance(s, str):
        return None
    s = s.strip()
    return s if len(s) > 0 and len(s) <= max_length else None

def error_json(mensagem, codigo=None, status=400):
    """Retorna erro padronizado (nunca expõe detalhes internos)."""
    return jsonify({
        'erro': mensagem,
        'codigo': codigo or 'ERRO_DESCONHECIDO'
    }), status


def chave_ou_login_ou_extensao(escopo):
    """As duas portas na mesma rota: chave de API pública OU sessão/extensão.

    `/api/v1/cotacao/planos` e `/calcular` eram só de chave de API. A extensão
    entra por token do consultor e levava 401 — o consultor não conseguia cotar
    MedSênior, Beneficência Vital nem Santa Tereza, que só existem no JOB.

    TROCAR o decorador teria aberto pra extensão e FECHADO pra quem já usa
    chave. Não dá pra saber daqui se existe chave viva com esse escopo, e
    derrubar integração de terceiro pra economizar uma linha é o tipo de coisa
    que só aparece quando alguém liga reclamando.

    Como se decide qual porta: token de extensão é `<id>.<segredo>`, começa com
    dígitos e ponto. Chave de API não tem esse formato. Sem `Authorization`
    nem `X-API-Key`, cai no caminho de sessão/extensão, que é quem sabe
    responder 401 com a mensagem certa.
    """
    def deco(f):
        por_chave = api_requer_chave(escopo)(f)
        por_login = login_ou_extensao(f)

        @wraps(f)
        def w(*a, **kw):
            if request.method == 'OPTIONS':
                return por_login(*a, **kw)
            bruta = ''
            auth = (request.headers.get('Authorization') or '').strip()
            if auth.lower().startswith('bearer '):
                bruta = auth[7:].strip()
            if (request.headers.get('X-API-Key') or '').strip():
                return por_chave(*a, **kw)
            if bruta and not re.match(r'^\d+\.', bruta):
                return por_chave(*a, **kw)
            return por_login(*a, **kw)
        return w
    return deco


def login_ou_extensao(f):
    @wraps(f)
    def w(*a, **kw):
        # 1. Site — mas NAO quando o pedido traz token de aparelho (ver
        #    `_tem_token_de_aparelho`): ai quem manda e o token.
        if 'user_id' in session and not _tem_token_de_aparelho():
            g.usuario_id = session['user_id']
            g.auth_via = 'sessao'
            # Para popular g.usuario de forma consistente, fazemos a query.
            conn = db()
            g.usuario = conn.execute("SELECT * FROM usuarios WHERE id=?", (g.usuario_id,)).fetchone()
            close_db(conn)
            if not g.usuario or not g.usuario['ativo']:
                return jsonify({"ok": False, "erro": "Acesso negado (inativo)"}), 403
            return f(*a, **kw)
            
        # 2. Token da Extensão (Novo)
        auth = request.headers.get('Authorization')
        if auth and auth.startswith('Bearer '):
            token_raw = auth.split(' ', 1)[1].strip()
            partes = token_raw.split('.')
            if len(partes) == 2 and partes[0].isdigit():
                sess_id = int(partes[0])
                secreto = partes[1]
                conn = db()
                sessao = conn.execute("SELECT usuario_id, token_hash, revogado_em FROM extensao_sessao WHERE id=?", (sess_id,)).fetchone()
                if sessao and not sessao['revogado_em']:
                    import hmac, hashlib
                    esperado = hashlib.sha256(secreto.encode()).hexdigest()
                    ok = hmac.compare_digest(esperado, sessao['token_hash'])
                    if ok:
                        g.usuario_id = sessao['usuario_id']
                        # QUAL APARELHO, e nao so quem. A fila de cotacao inteira
                        # depende disto: e por `sessao_id` que o servidor sabe se
                        # QUEM esta pedindo trabalho e a maquina marcada como
                        # trabalhadora. Sem esta linha, `getattr(g,'sessao_id',0)`
                        # devolvia 0 nas cinco rotas da fila, nenhuma sessao tem
                        # id 0, e o resultado era a fila inteira morta em silencio:
                        # "sem_trabalhador" pra quem pede e "nao_e_trabalhador"
                        # pro Dell, mesmo tudo configurado certo.
                        g.sessao_id = sess_id
                        g.auth_via = 'token'
                        g.usuario = conn.execute("SELECT * FROM usuarios WHERE id=?", (g.usuario_id,)).fetchone()
                        conn.execute("UPDATE extensao_sessao SET ultimo_uso=? WHERE id=?", (_agora_sp(), sess_id))
                        conn.commit()
                        close_db(conn)
                        if not g.usuario or not g.usuario['ativo']:
                            # IMPORTANTE: precisamos de CORS se a chamada vier da extensão (como é o caso de imagem/legenda agora abertas)
                            # E _wa_cors deve embrulhar a resposta.
                            resp = jsonify({"ok": False, "erro": "Usuário inativo"})
                            resp.headers['Access-Control-Allow-Origin'] = '*'
                            return resp, 403
                        return f(*a, **kw)
                close_db(conn)
                # O token tem a forma certa (id.segredo) e mesmo assim nao
                # autenticou: ou a sessao foi revogada, ou o segredo nao bate.
                #
                # ISTO E O DEFEITO QUE ANULAVA TODOS OS OUTROS CONSERTOS DE HOJE.
                # Ate aqui, so recusava se a chave antiga TAMBEM estivesse
                # ausente — e a extensao manda as duas quando tem as duas
                # guardadas. Resultado: revogar um aparelho em /usuarios nao
                # tirava o acesso dele, so trocava o crachá. O aparelho seguia
                # chamando fila, mensagem, nota, tudo, com a chave que e igual
                # nas oito maquinas. "Desconectar" nunca desconectou.
                #
                # Um Bearer com a FORMA certa (id.segredo) que nao autentica e
                # sempre um aparelho que precisa entrar de novo — revogado ou
                # com segredo errado. Isso vale por si só, tenha ou não chave
                # antiga junto. Barra sempre.
                return _sessao_morta()
                
        # 3. Chave Antiga (Transição) — só chega aqui quem NUNCA mandou Bearer.
        #    Quem manda Bearer de aparelho revogado já foi barrado acima.
        # IMPORTANTE: _wa_auth_ok() acessa `request`, que é global na thread no Flask.
        if request.headers.get('X-Extension-Key') and _wa_auth_ok():
            app.logger.info('[EXT] chave antiga usada em %s', request.path)
            g.auth_via = 'chave'
            uid = None
            try:
                j = request.get_json(silent=True) or {}
                uid = j.get('usuario_id')
            except Exception:
                pass
            if not uid:
                uid = request.args.get('usuario_id')
                
            if uid and str(uid).isdigit():
                g.usuario_id = int(uid)
                conn = db()
                g.usuario = conn.execute("SELECT * FROM usuarios WHERE id=?", (g.usuario_id,)).fetchone()
                close_db(conn)
            else:
                g.usuario_id = None
                g.usuario = None
                
            return f(*a, **kw)
            
        resp = jsonify({"ok": False, "erro": "Acesso negado"})
        resp.headers['Access-Control-Allow-Origin'] = '*'
        return resp, 403
    return w

def _tem_token_de_aparelho():
    """Veio um token de aparelho (formato <id>.<segredo>) neste pedido?

    Serve pra decidir QUEM autentica quando ha duas credenciais na mesma
    requisicao. O navegador manda o cookie do site junto com as chamadas da
    extensao, e a sessao do site era a primeira porta dos decoradores: quem
    estivesse logado no JOB naquele Chrome era autenticado pelo login do site,
    e o token do aparelho nunca chegava a ser conferido.

    Isso tornava a revogacao de aparelho invisivel justamente pra quem
    administra o sistema — e fazia a mesma extensao se comportar de um jeito
    pra quem estava logado no site e de outro pra quem nao estava.

    Quem manda token esta dizendo "me autentique COMO ESTE APARELHO". O cookie
    deixa de ter preferencia nesse caso.
    """
    auth = (request.headers.get('Authorization') or '').strip()
    if not auth.lower().startswith('bearer '):
        return False
    partes = auth[7:].strip().split('.')
    return len(partes) == 2 and partes[0].isdigit()


def _sessao_morta():
    """Resposta para token de aparelho que existe, mas nao vale mais.

    A extensao guarda o token no proprio Chrome. Revogar do lado do servidor
    nao apaga nada la — entao ela continuava mostrando a pessoa logada, com o
    nome e tudo, e so parava de funcionar em silencio. Foi assim que o
    Guilherme "entrou pelo popup" sem entrar: nao havia o que clicar, porque a
    tela nao estava pedindo login.

    Antes isto caia no 403 generico de "Acesso negado", que e a mesma resposta
    de falta de permissao — e deslogar alguem por falta de permissao seria pior
    que o defeito. Por isso o motivo vem escrito: `sessao_revogada` quer dizer
    UMA coisa so, e a extensao pode agir sobre ela sem adivinhar.
    """
    resp = jsonify({'ok': False, 'erro': 'sessao_revogada',
                    'mensagem': 'Este aparelho foi desconectado. Entre de novo pelo popup da extensao.'})
    resp.headers['Access-Control-Allow-Origin'] = '*'
    return resp, 401


def login_required(f):
    @wraps(f)
    def w(*a, **kw):
        if 'user_id' not in session: return redirect(url_for('login'))
        return f(*a, **kw)
    return w

def admin_required(f):
    @wraps(f)
    def w(*a, **kw):
        if session.get('perfil') == 'admin':
            return f(*a, **kw)
        # Consultor: só passa se a rota for de um MÓDULO concedido a ele (deixa
        # liberar Modelos/Funis/Operadoras etc. por consultor). Rota admin que
        # não é módulo (config, edição de usuário...) segue exclusiva do admin.
        permitidos = _modulos_permitidos_atual()
        mod = _modulo_do_path(request.path)
        if mod and permitidos is not None and mod in permitidos:
            return f(*a, **kw)
        return redirect(url_for('dashboard'))
    return w


# ─── OPERADOR (nós, o fornecedor) vs admin do cliente ────────────────────────
# Ferramentas de infra/diagnóstico/suporte (emergency, backup, testar-*,
# observabilidade, seletores da extensão) NÃO são pro admin do cliente — só pra
# quem opera o produto. `MODO_OPERADOR` liga isso. DEFAULT = ligado, pra a
# instância do Serenus (que não seta env) continuar idêntica; a instância de
# cliente seta MODO_OPERADOR=0 e essas telas somem (do menu e das rotas). Nós,
# pra dar suporte à instância de um cliente, ligamos MODO_OPERADOR=1 nela.
MODO_OPERADOR = (os.environ.get('MODO_OPERADOR', '1').strip().lower() not in ('0', 'false', 'nao', 'não', ''))

# Marca é do Serenus? Usado pra esconder recursos específicos do Serenus
# (importar-meninas, ZapVoice, Affinity, manual) nas outras marcas.
def _eh_serenus():
    return BRAND.get('nome_curto', '').strip().lower() == 'serenus'

# Prefixos de rota que só o OPERADOR vê (infra/diagnóstico/suporte). Numa
# instância de cliente (MODO_OPERADOR=0) somem do menu E das rotas (404).
_ROTAS_OPERADOR = (
    '/admin/emergency', '/admin/db/', '/admin/backup', '/admin/asaas',
    '/admin/testar-', '/admin/observabilidade', '/admin/ultimo-erro',
    '/admin/webhook-diagnostico', '/admin/recovery-anexos',
    '/admin/anexos/reconciliar-r2', '/admin/modo-teste', '/admin/testar-r2',
    '/extensao/erros', '/extensao/config-remota',
)
# Prefixos específicos do Serenus (integração/parceiro/conteúdo). Somem nas
# outras marcas.
_ROTAS_SERENUS = (
    '/crm/importar-meninas',
    '/crm/modelos/importar-zapvoice', '/manual',
)
# Sufixos em /proposta/<id>/... do fluxo Affinity (parceiro do Serenus): envio
# de protocolo/antecipação e o e-mail-modelo. Também só no Serenus.
_SUFIXOS_AFFINITY = (
    '/email-affinity', '/enviar-plataforma', '/enviar-teste',
    '/antecipacao/enviar', '/antecipacao/preview',
)


@app.teardown_request
def _fechar_conexoes_esquecidas(exc):
    """Fecha o que a rota nao fechou. Ver `_lembrar_conexao`."""
    abertas = getattr(g, '_conns_abertas', None)
    if not abertas:
        return
    g._conns_abertas = []
    for c in abertas:
        try:
            if exc is not None:
                try:
                    c.rollback()
                except Exception:
                    pass
            close_db(c)
        except Exception:
            pass


@app.before_request
def _gate_operador_serenus():
    """Esconde (404) as rotas de operador quando MODO_OPERADOR=0, e as rotas
    específicas do Serenus quando a marca não é Serenus. Centraliza a política
    num lugar só (em vez de trocar o decorator em ~30 rotas)."""
    p = request.path
    if not MODO_OPERADOR and p.startswith(_ROTAS_OPERADOR):
        abort(404)
    if not _eh_serenus() and (p.startswith(_ROTAS_SERENUS)
                              or (p.startswith('/proposta/') and p.endswith(_SUFIXOS_AFFINITY))):
        abort(404)


# ─── MÓDULOS POR CONSULTOR (acesso configurável em Usuários) ─────────────────
