@app.route('/admin/anexos/reconciliar-r2', methods=['GET', 'POST'])
@login_required
@admin_required
def reconciliar_anexos_r2():
    """Varre contrato/comprovante/documentos de TODAS as propostas e sobe para o
    R2 qualquer arquivo que só exista localmente — corrige uploads cujo backup
    em R2 falhou silenciosamente (só ficava um log warning que ninguém via)."""
    if os.environ.get('R2_ENABLED') != 'true':
        return jsonify({"ok": False, "msg": "R2 não está habilitado (R2_ENABLED != true)."}), 400

    import boto3, io
    account_id = os.environ.get('R2_ACCOUNT_ID', '').strip()
    access_key = os.environ.get('R2_ACCESS_KEY', '').strip()
    secret_key = os.environ.get('R2_SECRET_KEY', '').strip()
    bucket     = os.environ.get('R2_BUCKET_NAME', '').strip()
    if not (account_id and access_key and secret_key and bucket):
        return jsonify({"ok": False, "msg": "Credenciais R2 incompletas."}), 400

    s3 = boto3.client('s3', endpoint_url=f"https://{account_id}.r2.cloudflarestorage.com",
                       aws_access_key_id=access_key, aws_secret_access_key=secret_key, region_name='auto')

    # Lista tudo que já está no R2 (só o nome do arquivo, sem o caminho da pasta)
    ja_no_r2 = set()
    try:
        paginator = s3.get_paginator('list_objects_v2')
        for page in paginator.paginate(Bucket=bucket):
            for obj in page.get('Contents', []):
                ja_no_r2.add(obj['Key'].split('/')[-1])
    except Exception as e:
        return jsonify({"ok": False, "msg": f"Erro ao listar bucket: {e}"}), 500

    conn = db()
    props = conn.execute("SELECT id, contrato_arquivo, comprovante_boleto, anexos FROM propostas").fetchall()
    close_db(conn)

    subidos, sem_local_nem_r2, ja_ok = [], [], 0
    for p in props:
        pid = p['id']
        itens = []
        if p['contrato_arquivo']:
            itens.append(('contrato', p['contrato_arquivo']))
        if p['comprovante_boleto']:
            itens.append(('comprovante', p['comprovante_boleto']))
        try:
            extras = json.loads(p['anexos']) if p['anexos'] else []
            for x in extras:
                nome_x = x['nome'] if isinstance(x, dict) else x
                if nome_x:
                    itens.append(('documentos', nome_x))
        except Exception:
            pass

        for tipo, nome in itens:
            if nome in ja_no_r2:
                ja_ok += 1
                continue
            caminho_local = os.path.join(UPLOAD_FOLDER, os.path.basename(nome))
            if not os.path.exists(caminho_local):
                sem_local_nem_r2.append(f"proposta {pid}: {nome}")
                continue
            try:
                with open(caminho_local, 'rb') as fh:
                    dados = fh.read()
                chave = f"propostas/{pid}/{tipo}/{nome}"
                s3.upload_fileobj(io.BytesIO(dados), bucket, chave)
                subidos.append(f"proposta {pid}: {nome}")
                ja_no_r2.add(nome)
            except Exception as e:
                sem_local_nem_r2.append(f"proposta {pid}: {nome} (falhou upload: {type(e).__name__}: {e})")

    return jsonify({
        "ok": True,
        "ja_estavam_no_r2": ja_ok,
        "subidos_agora": subidos,
        "faltando_local_e_r2": sem_local_nem_r2,
    })

@app.route('/admin/testar-smtp')
@login_required
@admin_required
def testar_smtp():
    """Testa envio de email via API do Brevo."""
    import urllib.request, json as _json
    api_key  = os.environ.get('BREVO_API_KEY','')
    remetente = os.environ.get('SMTP_USER','noreply@serenuscorretora.com.br')
    destinatario = session.get('email') or remetente
    resultado = {'api': 'Brevo HTTP API', 'remetente': remetente, 'etapas': []}
    if not api_key:
        resultado['erro'] = 'BREVO_API_KEY não configurada no Railway.'
        return jsonify(resultado)
    try:
        resultado['etapas'].append('Chamando API Brevo...')
        payload = _json.dumps({
            "sender":  {"name": "JOB Serenus", "email": remetente},
            "to":      [{"email": remetente}],
            "subject": "JOB · Teste de email",
            "htmlContent": "<p>Email de teste do JOB Serenus funcionando!</p>"
        }).encode('utf-8')
        req = urllib.request.Request(
            "https://api.brevo.com/v3/smtp/email",
            data=payload,
            headers={"Content-Type":"application/json","api-key":api_key},
            method="POST"
        )
        with urllib.request.urlopen(req, timeout=15) as resp:
            body = resp.read().decode()
            resultado['etapas'].append(f'HTTP {resp.status} — Email enviado para {remetente}')
            resultado['ok'] = True
            resultado['resposta'] = body
    except Exception as e:
        resultado['etapas'].append(f'Erro: {e}')
        resultado['erro'] = str(e)
    return jsonify(resultado)

@app.route('/admin/emergency/diag-anexos')
@login_required
@admin_required
def diag_anexos():
    """Diagnóstico: mostra o que está no disco vs o que o banco espera."""
    import os
    # Lista arquivos físicos no UPLOAD_FOLDER
    arquivos_disco = []
    try:
        arquivos_disco = sorted(os.listdir(UPLOAD_FOLDER))
    except Exception as e:
        arquivos_disco = [f"ERRO ao listar: {e}"]

    # Cruza com o que o banco aponta
    conn = db()
    props = conn.execute("SELECT id, razao_social, comprovante_boleto, contrato_arquivo, anexos FROM propostas ORDER BY id").fetchall()
    close_db(conn)

    detalhe = []
    for p in props:
        itens = []
        for campo in ('comprovante_boleto', 'contrato_arquivo'):
            nome = p[campo]
            if nome:
                caminho = os.path.join(UPLOAD_FOLDER, os.path.basename(nome))
                itens.append({"campo": campo, "nome": nome, "existe_no_disco": os.path.exists(caminho)})
        try:
            _raw = json.loads(p['anexos']) if p['anexos'] else []
            extras = [x['nome'] if isinstance(x, dict) else x for x in _raw]
        except Exception:
            extras = []
        for nome in extras:
            if nome:
                caminho = os.path.join(UPLOAD_FOLDER, os.path.basename(nome))
                itens.append({"campo": "anexo_extra", "nome": nome, "existe_no_disco": os.path.exists(caminho)})
        if itens:
            detalhe.append({"proposta_id": p['id'], "cliente": p['razao_social'], "anexos": itens})

    return jsonify({
        "upload_folder": UPLOAD_FOLDER,
        "upload_folder_existe": os.path.isdir(UPLOAD_FOLDER),
        "total_arquivos_no_disco": len([a for a in arquivos_disco if not a.startswith('ERRO')]),
        "arquivos_no_disco": arquivos_disco,
        "propostas_com_anexos": detalhe,
    })

@app.route('/admin/emergency/reenviar-anexo', methods=['POST'])
@login_required
@admin_required
def emergency_reenviar_anexo():
    """
    Recebe um arquivo e o salva em UPLOAD_FOLDER com o nome exato informado.
    Usado para recuperar anexos perdidos.
    Payload multipart: file=<arquivo>, nome_original=<nome exato do banco>
    """
    nome_original = (request.form.get('nome_original') or '').strip()
    f = request.files.get('file')

    if not f or not f.filename:
        return jsonify({'ok': False, 'erro': 'Nenhum arquivo enviado'}), 400
    if not nome_original:
        return jsonify({'ok': False, 'erro': 'Nome original não informado'}), 400

    # Salva com o nome EXATO que está no banco
    caminho = os.path.join(UPLOAD_FOLDER, nome_original)
    try:
        f.save(caminho)
        return jsonify({
            'ok': True,
            'msg': f'Arquivo salvo: {nome_original}',
            'caminho': caminho,
            'tamanho': os.path.getsize(caminho)
        })
    except Exception as e:
        return jsonify({'ok': False, 'erro': str(e)}), 500




