def _pagar_parcela_asaas_core(conn, pid, operador_nome):
    """Núcleo do pagamento PIX de UMA parcela via Asaas — usado pela rota
    individual e pelo pagamento em lote do /fechamento. Faz as validações
    (liberada, sem transfer iniciado, chave PIX), cria a transferência e grava
    o transfer_id. Retorna (ok, info) — info é transfer_id ou mensagem de erro.
    Commita a cada parcela (quem chama não precisa)."""
    parc = conn.execute("""SELECT pa.*, p.consultor, p.usuario_id, p.razao_social
        FROM parcelas pa JOIN propostas p ON p.id=pa.proposta_id WHERE pa.id=?""", (pid,)).fetchone()
    if not parc:
        return False, "Parcela não encontrada"
    if parc['status'] != 'Liberado para o corretor':
        return False, "Só é possível pagar parcelas liberadas para o corretor"
    if parc['asaas_transfer_id']:
        return False, "Esta parcela já tem um pagamento Asaas iniciado"
    # ÚLTIMA TRAVA ANTES DO PIX. A liberação já checa a regra, mas o PIX é o
    # ponto sem volta: se a regra ficou incompleta DEPOIS de liberar (retenção
    # desativada, regra apagada), o dinheiro não pode sair mesmo assim.
    travado = _bloqueio_parcela_gestor(conn, pid)
    if travado:
        return False, travado

    consultor = conn.execute("SELECT chave_pix, nome FROM usuarios WHERE id=?", (parc['usuario_id'],)).fetchone()
    chave_pix = (consultor['chave_pix'] if consultor else '') or ''
    if not chave_pix.strip():
        return False, f"{parc['consultor']} não tem chave PIX cadastrada. Cadastre em Usuários."

    tipo_chave = asaas_detectar_tipo_chave(chave_pix)
    valor = round(float(parc['valor']), 2)

    payload = {
        "value": valor,
        "pixAddressKey": chave_pix.strip(),
        "pixAddressKeyType": tipo_chave,
        "description": f"Comissão {parc['razao_social']} - Parcela {parc['numero']}"[:140],
        "externalReference": f"parcela_{pid}",
    }
    data, status = asaas_request('POST', '/transfers', payload)

    if status in (200, 201) and data.get('id'):
        conn.execute("""UPDATE parcelas SET asaas_transfer_id=?, asaas_status=?, asaas_erro=NULL WHERE id=?""",
                     (data['id'], data.get('status', 'PENDING'), pid))
        conn.execute("""INSERT INTO historico_proposta (proposta_id, usuario_nome, campo, valor_antes, valor_depois)
                        VALUES (?,?,?,?,?)""",
                     (parc['proposta_id'] if 'proposta_id' in parc.keys() else None, operador_nome,
                      'Pagamento PIX (Asaas)', '', f"R$ {valor:.2f} para {parc['consultor']} — transfer {data['id']}"))
        # O PIX sair da fila e fato: entra no razao antes da confirmacao, senao
        # dinheiro em transito nao aparece em lugar nenhum.
        _fin_repasse(conn, pid, 'pix_iniciado', operador_nome)
        conn.commit()
        return True, data['id']
    erro_msg = data.get('_erro')
    if not erro_msg and data.get('errors'):
        erro_msg = '; '.join([e.get('description', str(e)) for e in data['errors']])
    conn.execute("UPDATE parcelas SET asaas_erro=? WHERE id=?", (str(erro_msg)[:300], pid))
    conn.commit()
    return False, erro_msg or "Erro desconhecido do Asaas"


@app.route('/parcela/<int:pid>/pagar-asaas', methods=['POST'])
@login_required
@admin_required
def parcela_pagar_asaas(pid):
    """Cria uma transferência PIX real via Asaas para pagar a comissão do consultor."""
    if not asaas_configurado():
        return jsonify({"ok": False, "erro": "Asaas não configurado. Adicione ASAAS_API_KEY no Railway."}), 400
    conn = db()
    ok, info = _pagar_parcela_asaas_core(conn, pid, session.get('nome'))
    close_db(conn)
    if ok:
        return jsonify({"ok": True, "transfer_id": info})
    return jsonify({"ok": False, "erro": info}), 400


@app.route('/webhook/asaas', methods=['POST'])
def webhook_asaas():
    """Recebe e processa eventos do Asaas (transferências, cobranças).
    
    Segurança:
    - Valida token asaas-access-token se configurado
    - Implementa idempotência via webhook_log
    - Loga cada etapa para diagnóstico
    
    Retorna sempre 200 para não gerar fila de retentativas infinita.
    """
    # Declarados aqui fora, nao dentro do try: se a excecao acontecer ANTES
    # de uma destas linhas rodar (ex: JSON malformado), o bloco de erro
    # ainda precisa saber o que da pra saber — em vez de estourar de novo
    # tentando ler um nome que nunca existiu.
    evento_id = evento = None
    try:
        # 1. VALIDAÇÃO DO TOKEN (se configurado)
        if ASAAS_WEBHOOK_TOKEN:
            token_recebido = request.headers.get('asaas-access-token', '')
            if token_recebido != ASAAS_WEBHOOK_TOKEN:
                app.logger.warning(f"[WEBHOOK] ❌ Token inválido ou faltante (recebido: '{token_recebido[:20] if token_recebido else 'VAZIO'}'...)")
                return jsonify({"ok": False, "erro": "Token inválido"}), 200
            app.logger.info("[WEBHOOK] ✅ Token validado com sucesso")
        
        # 2. PARSE DO JSON
        data = request.get_json(force=True) or {}
        evento_id = data.get('id', '')
        evento = data.get('event', '')
        
        app.logger.info(f"[WEBHOOK] Evento recebido: id={evento_id[:30] if evento_id else 'VAZIO'}, event={evento}")
        
        if not evento_id:
            app.logger.warning("[WEBHOOK] ⚠️ evento_id vazio, ignorando")
            return jsonify({"ok": True, "msg": "evento_id vazio, ignorado"}), 200
        
        # 3. RESERVA O EVENTO (claim atômico via UNIQUE em evento_id).
        #
        # ANTES: um SELECT aqui checava "já processado?" e só no FINAL do
        # processamento (passo 5) é que o INSERT marcava o evento como feito.
        # Dois webhooks quase simultâneos do MESMO evento_id (reenvio do
        # Asaas) passavam os dois pelo SELECT antes que qualquer um
        # commitasse o INSERT — os dois processavam a mesma transferência em
        # paralelo. A UPDATE de status é idempotente (não duplica dinheiro),
        # mas a notificação ao consultor saía duas vezes.
        #
        # Reservar aqui, ANTES de qualquer efeito colateral, faz o UNIQUE do
        # banco decidir atomicamente qual requisição "ganha" o evento — a
        # outra recebe erro de UNIQUE na hora, sem ter processado nada.
        conn = db()
        try:
            conn.execute("INSERT INTO webhook_log (evento_id, evento) VALUES (?,?)", (evento_id, evento))
            conn.commit()
        except Exception:
            try: conn.rollback()
            except Exception: pass
            app.logger.info(f"[WEBHOOK] ⏭️  Evento duplicado (id={evento_id[:30]}), ignorando")
            close_db(conn)
            return jsonify({"ok": True, "msg": "duplicado, ignorado"}), 200

        # 4. PROCESSAR EVENTOS DE TRANSFERÊNCIA
        if evento.startswith('TRANSFER_'):
            app.logger.info(f"[WEBHOOK] 🔄 Processando transferência: evento={evento}")
            transfer = data.get('transfer', {})
            transfer_id = transfer.get('id', '')
            novo_status = transfer.get('status', '')
            
            if transfer_id:
                parc = conn.execute(
                    "SELECT id, proposta_id FROM parcelas WHERE asaas_transfer_id=?",
                    (transfer_id,)
                ).fetchone()
                
                if parc:
                    app.logger.info(f"[WEBHOOK] ✅ Parcela encontrada: id={parc['id']}, proposta_id={parc['proposta_id']}")
                    
                    # Atualizar status
                    conn.execute("UPDATE parcelas SET asaas_status=? WHERE id=?", (novo_status, parc['id']))
                    
                    if evento == 'TRANSFER_DONE':
                        data_efetiva = transfer.get('effectiveDate') or datetime.now(TZ_SP).strftime('%Y-%m-%d')
                        conn.execute(
                            "UPDATE parcelas SET status='Pago ao corretor', data_pagamento=? WHERE id=?",
                            (data_efetiva, parc['id'])
                        )
                        conn.execute(
                            "INSERT INTO historico_proposta (proposta_id, usuario_nome, campo, valor_antes, valor_depois) VALUES (?,?,?,?,?)",
                            (parc['proposta_id'], 'Asaas (webhook)', 'Status do pagamento', 'Pendente', 'Pago ao corretor (PIX confirmado)')
                        )
                        _fin_repasse(conn, parc['id'], 'pago', 'Asaas (webhook)',
                                     data_liquidacao=_data_iso(data_efetiva))
                        app.logger.info(f"[WEBHOOK] 💰 Transferência concluída: parcela {parc['id']} marcada como 'Pago ao corretor'")

                    elif evento in ('TRANSFER_FAILED', 'TRANSFER_CANCELLED'):
                        motivo = transfer.get('failReason') or 'Transferência falhou ou foi cancelada'
                        conn.execute("UPDATE parcelas SET asaas_erro=? WHERE id=?", (str(motivo)[:300], parc['id']))
                        app.logger.warning(f"[WEBHOOK] ❌ Transferência falhou: parcela {parc['id']}, motivo={motivo[:50]}")

                    conn.commit()
                    # Consultor só era avisado no caminho manual — pagamento via
                    # PIX/Asaas confirmava em silêncio (sino mudo).
                    if evento == 'TRANSFER_DONE':
                        _notificar_parcela_consultor(conn, parc['id'], 'paga', origem='PIX via Asaas')
                else:
                    app.logger.warning(f"[WEBHOOK] ⚠️  Transferência não encontrada: asaas_transfer_id={transfer_id}")
            else:
                app.logger.warning(f"[WEBHOOK] ⚠️  transfer.id vazio no payload")
        
        elif evento.startswith('PAYMENT_'):
            app.logger.info(f"[WEBHOOK] 💳 Evento de cobrança: {evento} (implementação futura)")

        # Evento já foi reservado no passo 3 — só falta commitar o que o
        # processamento acima mudou (parcela/histórico).
        conn.commit()
        close_db(conn)
        
        app.logger.info(f"[WEBHOOK] ✅ Webhook processado com sucesso: {evento_id[:30]}")
        return jsonify({"ok": True, "msg": "processado"}), 200
    
    except Exception as e:
        app.logger.error(f"[WEBHOOK] 🔴 ERRO: {str(e)}", exc_info=True)
        # A ROTA SEMPRE RESPONDE 200 (de proposito: 200 evita o Asaas
        # reenviando o mesmo evento em fila). Mas isso tem um preco: o Asaas
        # NUNCA vai saber que falhou, entao NADA reenvia. Se o unico rastro
        # for o log do Railway (volatil, rotaciona), o evento desaparece —
        # uma parcela podia ter sido paga de verdade e o sistema nunca soube.
        # Grava aqui, mesmo sem saber o evento_id direito (JSON pode nem ter
        # chegado a parsear): um id sintetico com timestamp garante que o
        # UNIQUE em evento_id nao apague o registro por cima de outro.
        #
        # Se evento_id já existe, o passo 3 (reserva) já commitou essa linha
        # antes do erro acontecer — UPDATE nela em vez de INSERT (que bateria
        # no mesmo UNIQUE e caía neste except de novo, mascarando o erro real).
        try:
            conn_erro = db()
            if evento_id:
                cur = conn_erro.execute("UPDATE webhook_log SET erro=? WHERE evento_id=?", (str(e)[:500], evento_id))
                if not getattr(cur, 'rowcount', 0):
                    conn_erro.execute(
                        "INSERT INTO webhook_log (evento_id, evento, erro) VALUES (?,?,?)",
                        (evento_id, evento or '', str(e)[:500]))
            else:
                conn_erro.execute(
                    "INSERT INTO webhook_log (evento_id, evento, erro) VALUES (?,?,?)",
                    (f"falha_{datetime.now(TZ_SP).strftime('%Y%m%d%H%M%S%f')}", evento or '', str(e)[:500]))
            conn_erro.commit()
            close_db(conn_erro)
        except Exception:
            pass  # Se nem isso funcionar, o log do Railway acima ainda existe.
        return jsonify({"ok": False, "erro": str(e)[:100]}), 200


@app.route('/admin/webhook-diagnostico', methods=['GET'])
@login_required
@admin_required
def webhook_diagnostico():
    """Mostra os últimos webhooks do Asaas recebidos, para diagnóstico."""
    conn = db()
    try:
        # Últimos 20 webhooks
        webhooks = conn.execute(
            "SELECT id, evento_id, evento, erro, processado_em FROM webhook_log ORDER BY processado_em DESC LIMIT 20"
        ).fetchall()

        total = conn.execute("SELECT COUNT(*) AS cnt FROM webhook_log").fetchone()
        total_webhooks = total['cnt'] if total else 0
        # Falha que existia so no log volatil do Railway agora fica aqui —
        # este contador e o que diz se sobrou algo pra investigar.
        falhas = conn.execute("SELECT COUNT(*) AS cnt FROM webhook_log WHERE erro IS NOT NULL").fetchone()
        total_falhas = falhas['cnt'] if falhas else 0
    except Exception as e:
        app.logger.error(f"[WEBHOOK-DIAG] Erro ao consultar webhook_log: {e}")
        webhooks = []
        total_webhooks = 0
        total_falhas = 0
    finally:
        close_db(conn)

    resultado = {
        "config": {
            "asaas_configurado": asaas_configurado(),
            "asaas_webhook_token_configurado": bool(ASAAS_WEBHOOK_TOKEN),
            "asaas_base_url": ASAAS_BASE_URL,
            "ambiente": "produção" if "api.asaas.com" in ASAAS_BASE_URL else "sandbox",
        },
        "ultimos_webhooks": [
            {
                "id": w['id'],
                "evento_id": w['evento_id'],
                "evento": w['evento'],
                "erro": w['erro'] if 'erro' in w.keys() else None,
                "processado_em": str(w['processado_em']),
            }
            for w in webhooks
        ],
        "total_webhooks": total_webhooks,
        "total_falhas": total_falhas,
    }

    return jsonify(resultado), 200


