# ─── SERVIR ARQUIVOS (contratos, comprovantes) ──────────────────────────────────
def _localizar_anexo(nome):
    """Localiza um anexo por nome, local primeiro (volume persistente), depois no
    R2 como fallback (tenta a chave exata e depois varre o bucket por sufixo, já
    que no R2 os arquivos ficam dentro de pastas tipo propostas/<id>/<tipo>/).
    Usado tanto para SERVIR (visualizar/baixar) quanto para ANEXAR EM E-MAIL —
    mesma lógica nos dois casos, pra não perder anexo que só existe no R2.
    Retorna (conteudo_bytes, content_type) ou (None, None) se não achou."""
    nome = os.path.basename(nome or '')
    if not nome:
        return None, None

    # PRIORIDADE 1: LOCAL (/data/anexos — volume persistente)
    for candidato in (nome, _sanitizar_filename(nome)):
        caminho = os.path.join(UPLOAD_FOLDER, candidato)
        if os.path.exists(caminho):
            app.logger.info(f"[ANEXO] ✅ LOCAL: {candidato}")
            with open(caminho, 'rb') as fh:
                return fh.read(), None  # content_type None = deixa o chamador inferir pelo nome

    # PRIORIDADE 2: R2 (fallback se local não tem)
    if os.environ.get('R2_ENABLED') == 'true':
        try:
            import boto3
            account_id = os.environ.get('R2_ACCOUNT_ID', '').strip()
            access_key = os.environ.get('R2_ACCESS_KEY', '').strip()
            secret_key = os.environ.get('R2_SECRET_KEY', '').strip()
            bucket     = os.environ.get('R2_BUCKET_NAME', '').strip()
            if account_id and access_key and secret_key and bucket:
                s3 = boto3.client(
                    's3',
                    endpoint_url=f"https://{account_id}.r2.cloudflarestorage.com",
                    aws_access_key_id=access_key,
                    aws_secret_access_key=secret_key,
                    region_name='auto'
                )

                # Lista de chaves R2 a tentar, em ordem
                chaves_tentar = [nome, _sanitizar_filename(nome)]

                # Os arquivos no R2 ficam dentro de pastas (ex: propostas/20/contrato/ARQ.pdf),
                # mas a gente só tem o nome do arquivo. Então varremos o bucket procurando
                # qualquer chave que TERMINE com esse nome de arquivo.
                achou_key = None
                for k in chaves_tentar:
                    try:
                        s3.head_object(Bucket=bucket, Key=k)
                        achou_key = k
                        break
                    except Exception:
                        pass

                if not achou_key:
                    try:
                        paginator = s3.get_paginator('list_objects_v2')
                        alvo = nome.lower()
                        alvo_limpo = _sanitizar_filename(nome).lower()
                        for page in paginator.paginate(Bucket=bucket):
                            for obj in page.get('Contents', []):
                                key = obj['Key']
                                base = key.split('/')[-1].lower()
                                if base == alvo or base == alvo_limpo:
                                    achou_key = key
                                    break
                            if achou_key:
                                break
                    except Exception as e:
                        app.logger.warning(f"[ANEXO] ⚠️ R2 listagem falhou: {type(e).__name__}: {e}")

                if achou_key:
                    resp = s3.get_object(Bucket=bucket, Key=achou_key)
                    content = resp['Body'].read()
                    ctype = resp.get('ContentType', 'application/octet-stream')
                    app.logger.info(f"[ANEXO] ✅ R2 (fallback): {achou_key}")
                    return content, ctype
        except Exception as e:
            app.logger.warning(f"[ANEXO] ⚠️ R2 falhou ({nome}): {type(e).__name__}: {e}")

    return None, None


@app.route('/avatar/<int:uid>')
def avatar_usuario(uid):
    """Foto de perfil do usuário, pública (sem login) — só assim o cliente de e-mail
    do lead consegue carregar a imagem no corpo do e-mail. Não usar pra nada além de
    foto de perfil: diferente de /anexos, aqui não tem documento sensível envolvido."""
    conn = db()
    u = conn.execute("SELECT foto FROM usuarios WHERE id=?", (uid,)).fetchone()
    close_db(conn)
    if not u or not u['foto']:
        abort(404)
    conteudo, ctype = _localizar_anexo(u['foto'])
    if conteudo is None:
        abort(404)
    if ctype is None:
        ctype = mimetypes.guess_type(u['foto'])[0] or 'image/jpeg'
    resp = Response(conteudo, mimetype=ctype)
    resp.headers['Cache-Control'] = 'public, max-age=86400'
    return resp


@app.route('/anexos/<path:nome>')
@login_required
def servir_anexo(nome):
    """Serve arquivo LOCAL primeiro (volume persistente), depois tenta R2 como fallback."""
    from urllib.parse import unquote
    nome = os.path.basename(unquote(nome))
    conteudo, ctype = _localizar_anexo(nome)
    if conteudo is None:
        app.logger.error(f"[SERVE] ❌ Arquivo não encontrado: {nome}")
        abort(404)
    if ctype is None:
        ctype = mimetypes.guess_type(nome)[0] or 'application/octet-stream'
    return Response(conteudo, mimetype=ctype,
                    headers={'Content-Disposition': f'inline; filename="{nome}"'})

@app.route('/proposta/<int:pid>/anexo/excluir', methods=['POST'])
@login_required
@admin_required
def excluir_anexo(pid):
    """Exclui um anexo de uma proposta. Apenas admin.
    tipo: 'contrato' | 'comprovante' | 'doc' (com 'nome' do arquivo no array anexos)."""
    d = request.json or {}
    tipo = (d.get('tipo') or '').strip()
    nome = os.path.basename((d.get('nome') or '').strip())
    conn = db()
    p = conn.execute("SELECT * FROM propostas WHERE id=?", (pid,)).fetchone()
    if not p:
        close_db(conn); return jsonify({"ok": False, "msg": "Proposta não encontrada"}), 404

    arquivo_remover = None
    if tipo == 'contrato':
        arquivo_remover = p['contrato_arquivo']
        conn.execute("UPDATE propostas SET contrato_arquivo=NULL WHERE id=?", (pid,))
    elif tipo == 'comprovante':
        arquivo_remover = p['comprovante_boleto']
        conn.execute("UPDATE propostas SET comprovante_boleto=NULL WHERE id=?", (pid,))
    elif tipo == 'doc':
        try:
            lista = json.loads(p['anexos']) if p['anexos'] else []
        except Exception:
            lista = []
        if nome in lista:
            lista.remove(nome)
            arquivo_remover = nome
            conn.execute("UPDATE propostas SET anexos=? WHERE id=?", (json.dumps(lista), pid))
    else:
        close_db(conn); return jsonify({"ok": False, "msg": "Tipo inválido"}), 400

    conn.commit(); close_db(conn)

    # Remove o arquivo físico (best-effort; não falha se já sumiu)
    if arquivo_remover:
        try:
            os.remove(os.path.join(UPLOAD_FOLDER, os.path.basename(arquivo_remover)))
        except Exception:
            pass
    return jsonify({"ok": True})

# ─── EMAIL UTILITÁRIO ────────────────────────────────────────────────────────
def _enviar_email(destinatario, assunto, corpo_html, cc=None, anexos=None, remetente_nome=None,
                  sincrono=False):
    """Envia email via API do Brevo (HTTPS porta 443 — nunca bloqueada pelo Railway).
    Configure BREVO_API_KEY no Railway. SMTP_USER define o remetente.
    destinatario: string (1 email) ou lista de emails.
    cc: string ou lista de emails para cópia (opcional).
    anexos: lista de nomes de arquivo (em UPLOAD_FOLDER) a anexar (opcional).
    remetente_nome: nome exibido como remetente (padrão 'JOB Serenus' — e-mails
    pro lead usam 'Cotação de Plano de Saúde', mais reconhecível pra quem nunca
    ouviu falar do sistema interno)."""
    api_key = os.environ.get('BREVO_API_KEY','')
    remetente = os.environ.get('SMTP_USER','noreply@serenuscorretora.com.br')
    remetente_nome = remetente_nome or 'JOB Serenus'

    # Normaliza destinatários e cópia para listas
    if isinstance(destinatario, str):
        to_list = [e.strip() for e in destinatario.replace(';', ',').split(',') if e.strip()]
    else:
        to_list = [e.strip() for e in destinatario if e and e.strip()]

    cc_list = []
    if cc:
        if isinstance(cc, str):
            cc_list = [e.strip() for e in cc.replace(';', ',').split(',') if e.strip()]
        else:
            cc_list = [e.strip() for e in cc if e and e.strip()]

    # Monta lista de anexos em base64 (Brevo: attachment=[{content, name}])
    # Usa _localizar_anexo (local → fallback R2) — antes só olhava o disco local,
    # então um anexo que só existisse no R2 (ex: volume local reiniciado) sumia
    # do e-mail sem aviso nenhum, mesmo a proposta tendo o arquivo cadastrado.
    attach_payload = []
    if anexos:
        import base64, re as _re
        total_bytes = 0
        LIMITE_BYTES = 9 * 1024 * 1024  # ~9MB de arquivos brutos (Brevo aceita até ~10MB no payload)
        for item in anexos:
            if not item:
                continue
            # Aceita 'arquivo.pdf' OU ('arquivo.pdf', 'NOME QUE O OUTRO LADO VE').
            # Quem recebe a proposta abre uma pasta de anexos: 'RG-CNH - TITULAR
            # - BRUNO.pdf' se le, '20260801_doc_IMG-2231.pdf' nao.
            nome, nome_desejado = (item if isinstance(item, (tuple, list)) else (item, None))
            if not nome:
                continue
            conteudo, _ctype = _localizar_anexo(nome)
            if conteudo is None:
                print(f"[EMAIL] ⚠️ Anexo não encontrado (local nem R2), ignorando: {nome}")
                continue
            try:
                tam = len(conteudo)
                if total_bytes + tam > LIMITE_BYTES:
                    print(f"[EMAIL] ⚠️ Limite de anexos atingido (~9MB). Pulando: {nome} ({tam} bytes)")
                    continue
                conteudo_b64 = base64.b64encode(conteudo).decode('ascii')
                total_bytes += tam
                # Nome amigável: remove prefixo timestamp/categoria
                nome_limpo = os.path.basename(nome_desejado or nome)
                if nome_desejado:
                    nome_exibe = nome_limpo
                else:
                    partes = nome_limpo.split('_', 3)
                    nome_exibe = partes[-1] if len(partes) >= 2 else nome_limpo
                # SANITIZA: Brevo rejeita nomes com espaços/acentos/caracteres especiais.
                base_nome, ext = os.path.splitext(nome_exibe)
                base_nome = _re.sub(r'[^A-Za-z0-9._-]', '_', base_nome)   # troca espaço/acento por _
                base_nome = _re.sub(r'_+', '_', base_nome).strip('_')      # colapsa __ e remove bordas
                if not base_nome:
                    base_nome = 'documento'
                nome_seguro = (base_nome + ext.lower())[:120]
                attach_payload.append({"content": conteudo_b64, "name": nome_seguro})
                print(f"[EMAIL] 📎 Anexo preparado: {nome_seguro} ({tam} bytes)")
            except Exception as e:
                print(f"[EMAIL] ⚠️ Falha ao processar anexo {nome}: {e}")

    if not api_key:
        print(f"[EMAIL] ⚠️ BREVO_API_KEY não configurada. Assunto: {assunto} → {to_list} (cc: {cc_list})")
        return False

    def _construir_e_enviar():
        import urllib.request, urllib.error, json as _json
        corpo_payload = {
            "sender":  {"name": remetente_nome, "email": remetente},
            "to":      [{"email": e} for e in to_list],
            "subject": assunto,
            "htmlContent": corpo_html
        }
        if cc_list:
            corpo_payload["cc"] = [{"email": e} for e in cc_list]
        if attach_payload:
            corpo_payload["attachment"] = attach_payload
        payload = _json.dumps(corpo_payload).encode('utf-8')
        req = urllib.request.Request(
            "https://api.brevo.com/v3/smtp/email",
            data=payload,
            headers={"Content-Type": "application/json", "api-key": api_key},
            method="POST"
        )
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                print(f"[EMAIL] ✅ Enviado via Brevo (HTTP {resp.status}): {assunto} → {to_list} (cc: {cc_list}, {len(attach_payload)} anexos)")
            return True, None
        except urllib.error.HTTPError as e:
            erro_corpo = ''
            try: erro_corpo = e.read().decode()
            except Exception: pass
            print(f"[EMAIL] ❌ Brevo HTTP {e.code}: {erro_corpo}")
            return False, f"Brevo HTTP {e.code}: {erro_corpo}"
        except Exception as e:
            print(f"[EMAIL] ❌ Erro ao enviar para {to_list}: {e}")
            return False, str(e)

    # Com anexos: envia SÍNCRONO para capturar e reportar erros reais do Brevo.
    # Sem anexos: mantém envio em background (rápido para o usuário).
    # sincrono=True: quem chamou VAI MOSTRAR o resultado na tela, entao precisa
    # do resultado de verdade. Sem isso o e-mail sem anexo saia numa thread e a
    # funcao devolvia True na hora — a tela dizia 'enviado', o historico gravava
    # 'enviado', e o e-mail podia nunca ter saido. Foi o que aconteceu.
    if attach_payload or sincrono:
        ok, _erro = _construir_e_enviar()
        _enviar_email.ultimo_erro = _erro
        return ok
    else:
        import threading
        threading.Thread(target=lambda: _construir_e_enviar(), daemon=True).start()
        _enviar_email.ultimo_erro = None
        return True


def _enviar_sms(telefone, mensagem):
    """Envia SMS via API da GTI SMS. Configure GTISMS_API_KEY no Railway.
    telefone: string, com ou sem 55/DDD (normaliza sozinho pro formato 55+DDD+numero que a GTI espera).
    Retorna (ok: bool, erro: str|None). Nunca lança exceção."""
    api_key = os.environ.get('GTISMS_API_KEY', '').strip()
    if not api_key:
        return False, "GTISMS_API_KEY não configurada no Railway."
    n = re.sub(r'\D', '', telefone or '')
    if not n.startswith('55') and len(n) in (10, 11):
        n = '55' + n
    if len(n) not in (12, 13):
        return False, f"Telefone inválido: {telefone!r}"
    try:
        import requests as _rq
        resp = _rq.post(
            "https://sms.gtisms.com/api/v3/sms/send",
            json={"recipient": n, "message": mensagem},
            headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
            timeout=15)
        try:
            j = resp.json()
        except Exception:
            j = {}
        if resp.status_code in (200, 201):
            return True, None
        return False, f"GTI SMS: {j.get('message') or j.get('error') or resp.text[:200]}"
    except Exception as e:
        return False, f"Falha ao enviar SMS: {e}"


# ─── RECUPERAÇÃO DE SENHA (usuário) ─────────────────────────────────────────
# O CODIGO E NUMERICO DE 6 DIGITOS. SEM LIMITE, DA PRA CHUTAR.
#
# Nao e um segredo de 32 caracteres — sao 1 milhao de combinacoes, validas
# por 15 minutos, e quem sabe so o e-mail (previsivel: nome@serenus...) podia
# tentar todas dentro da janela, sem nada barrando. Mesmo padrao ja usado no
# login da extensao (_WA_LOGIN_ATTEMPTS): dicionario em memoria, chave
# (ip, email), zera sozinho quando o servidor reinicia — aceitavel pelo
# mesmo motivo de la, e simples de auditar.
_RESET_SENHA_TENTATIVAS = {}  # { (ip, email): [timestamp, ...] }
_RESET_SENHA_MAX = 5          # depois disso, o codigo morre — pede um novo


@app.route('/esqueci-senha', methods=['GET','POST'])
def esqueci_senha():
    """Passo 1: usuário informa o e-mail → recebe código de 6 dígitos."""
    if request.method == 'GET':
        return render_template('esqueci_senha.html')
    email = request.form.get('email','').strip().lower()
    conn = db()
    u = conn.execute("SELECT id,nome,ativo FROM usuarios WHERE email=?", (email,)).fetchone()
    if not u or not u['ativo']:
        close_db(conn)
        # Mensagem genérica por segurança (não revela se e-mail existe)
        return render_template('esqueci_senha.html', enviado=True)
    import random
    codigo = f"{random.randint(0,999999):06d}"
    expira = (datetime.now(TZ_SP) + timedelta(minutes=15)).isoformat()
    conn.execute("UPDATE usuarios SET reset_code=?, reset_expira=? WHERE id=?", (codigo, expira, u['id']))
    conn.commit(); close_db(conn)
    corpo = f"""
    <div style="font-family:sans-serif; max-width:420px; margin:auto; padding:30px;">
      <h2 style="color:#1fd8a4;">JOB · Corretora Serenus</h2>
      <p>Olá, <strong>{u['nome']}</strong>.</p>
      <p>Recebemos uma solicitação de redefinição de senha. Use o código abaixo:</p>
      <div style="font-size:36px; font-weight:700; letter-spacing:10px; text-align:center;
                  background:#f3f4f6; padding:20px; border-radius:8px; margin:24px 0; color:#111;">
        {codigo}
      </div>
      <p style="color:#666;">O código expira em <strong>15 minutos</strong>.</p>
      <p style="color:#666;">Se não foi você, ignore este e-mail.</p>
    </div>"""
    _enviar_email(email, "JOB · Código de redefinição de senha", corpo)
    return render_template('esqueci_senha.html', enviado=True, email=email)

@app.route('/redefinir-senha', methods=['GET','POST'])
def redefinir_senha():
    """Passo 2: usuário informa código + nova senha."""
    email = request.args.get('email','') or request.form.get('email','')
    if request.method == 'GET':
        return render_template('redefinir_senha.html', email=email)
    email  = request.form.get('email','').strip().lower()
    codigo = request.form.get('codigo','').strip()
    s1 = request.form.get('senha','')
    s2 = request.form.get('senha2','')

    import time as _time
    ip = request.remote_addr
    k = (ip, email)
    agora = _time.time()
    if k in _RESET_SENHA_TENTATIVAS:
        # Mesma janela do proprio codigo: passado 15 min o codigo ja expirou
        # sozinho, entao tentativa velha nao precisa continuar contando.
        _RESET_SENHA_TENTATIVAS[k] = [t for t in _RESET_SENHA_TENTATIVAS[k] if agora - t < 900]
    if len(_RESET_SENHA_TENTATIVAS.get(k, [])) >= _RESET_SENHA_MAX:
        conn = db()
        # Invalida o codigo de verdade — nao so recusa a tentativa. Sem isto,
        # a pessoa só ficava impedida enquanto o rate-limit em memoria
        # durasse; o codigo continuava valido pra quem tivesse mais paciencia
        # ou tentasse de outro IP.
        conn.execute("UPDATE usuarios SET reset_code=NULL, reset_expira=NULL WHERE email=?", (email,))
        conn.commit(); close_db(conn)
        app.logger.warning(f"[RESET-SENHA] limite de tentativas atingido: {email} via {ip}")
        return render_template('redefinir_senha.html', email=email,
            erro='Muitas tentativas erradas. Por segurança, este código foi cancelado — solicite um novo.')

    conn = db()
    u = conn.execute("SELECT id,reset_code,reset_expira FROM usuarios WHERE email=? AND ativo=1", (email,)).fetchone()
    erro = None
    if not u or u['reset_code'] != codigo:
        erro = 'Código inválido ou e-mail não encontrado.'
    elif _data_expirada(u['reset_expira']):
        erro = 'Código expirado. Solicite um novo.'
    elif len(s1) < 6:
        erro = 'Senha deve ter pelo menos 6 caracteres.'
    elif s1 != s2:
        erro = 'Senhas não conferem.'
    if erro:
        # Conta como tentativa so quando o CODIGO estava errado — senha curta
        # ou senhas diferentes nao e um chute, e nao deve gastar do limite.
        if not u or u['reset_code'] != codigo:
            _RESET_SENHA_TENTATIVAS.setdefault(k, []).append(agora)
        close_db(conn)
        return render_template('redefinir_senha.html', email=email, erro=erro)
    _RESET_SENHA_TENTATIVAS.pop(k, None)
    conn.execute("UPDATE usuarios SET senha_hash=?, reset_code=NULL, reset_expira=NULL WHERE id=?",
                 (hash_senha(s1), u['id']))
    conn.commit(); close_db(conn)
    return render_template('redefinir_senha.html', sucesso=True)

# ─── RESET DE SENHA PELO GESTOR (admin define senha nova direto) ─────────────
@app.route('/usuario/reset-senha/<int:uid>', methods=['POST'])
@login_required
@admin_required
def usuario_reset_senha(uid):
    nova = request.form.get('nova_senha','').strip()
