@app.template_filter('dur_curta')
def _dur_curta(ms):
    """Milissegundos -> '3 min', '1h20', '45s'. Vazio vira travessão.

    Corretor não lê milissegundo. E '0' seria pior que travessão: dá a entender
    que houve medição e o tempo foi zero, quando na verdade não houve medição.
    """
    if ms is None or ms == '':
        return '—'
    try:
        seg = int(ms) // 1000
    except (TypeError, ValueError):
        return '—'
    if seg < 60:
        return f'{seg}s'
    if seg < 3600:
        return f'{seg // 60} min'
    h, m = seg // 3600, (seg % 3600) // 60
    return f'{h}h{m:02d}' if m else f'{h}h'


def _tempo_resposta_do_dia(conn, usuario_id=None):
    """Le a medicao de hoje. usuario_id=None traz a equipe inteira (visao admin).

    Devolve None quando nao ha medicao: a tela precisa distinguir "hoje ninguem
    respondeu devagar" de "hoje ninguem mediu". Zero no lugar de vazio seria uma
    mentira boa de olhar — o consultor com a extensao desligada apareceria como
    o mais rapido da equipe.
    """
    dia = datetime.now(TZ_SP).strftime('%Y-%m-%d')
    if usuario_id:
        r = conn.execute("""SELECT * FROM wa_tempo_resposta WHERE usuario_id=? AND dia=?""",
                         (usuario_id, dia)).fetchone()
        return dict(r) if r else None
    linhas = conn.execute("""SELECT t.*, u.nome FROM wa_tempo_resposta t
        JOIN usuarios u ON u.id = t.usuario_id
        WHERE t.dia=? AND u.ativo=1
        ORDER BY (t.mediana_ms IS NULL), t.mediana_ms""", (dia,)).fetchall()
    return [dict(x) for x in linhas] or None


@app.route('/')
@login_required
def dashboard():
    conn = db(); uid = session['user_id']
    if session['perfil'] == 'admin':
        m = {}
        # Filtro de mês (base mes_meta) — sem isso, virava o mês e a produção de todos os meses
        # continuava somada junto (ex: junho + julho misturados). Default: mês atual.
        f_mes = (request.args.get('mes') or '').strip() or datetime.now(TZ_SP).strftime('%Y-%m')
        if f_mes == 'todos':
            filtro_mes_sql, filtro_mes_params = "", []
        else:
            filtro_mes_sql, filtro_mes_params = " AND mes_meta=?", [f_mes]
        m['propostas'] = conn.execute(f"SELECT COUNT(*) c FROM propostas WHERE status != 'Excluída'{filtro_mes_sql}", filtro_mes_params).fetchone()['c']
        m['vidas'] = conn.execute(f"SELECT COALESCE(SUM(total_vidas),0) v FROM propostas WHERE status != 'Excluída'{filtro_mes_sql}", filtro_mes_params).fetchone()['v']
        m['producao'] = conn.execute(f"SELECT COALESCE(SUM(valor),0) v FROM propostas WHERE status != 'Excluída'{filtro_mes_sql}", filtro_mes_params).fetchone()['v']
        m['com_bruta'] = conn.execute(f"SELECT COALESCE(SUM(comissao_total_corretora),0) v FROM propostas WHERE status != 'Excluída'{filtro_mes_sql}", filtro_mes_params).fetchone()['v']
        m['com_repasse'] = conn.execute(f"SELECT COALESCE(SUM(comissao_consultor),0) v FROM propostas WHERE status != 'Excluída'{filtro_mes_sql}", filtro_mes_params).fetchone()['v']
        m['com_liquido'] = conn.execute(f"SELECT COALESCE(SUM(comissao_corretora_liquida),0) v FROM propostas WHERE status != 'Excluída'{filtro_mes_sql}", filtro_mes_params).fetchone()['v']
        # Fluxo de caixa: saldo ATUAL (todas as propostas Emitida/Ativa, não é "produção do mês" — não filtra por mês de propósito)
        m['fc_pendente'] = conn.execute("""SELECT COALESCE(SUM(pa.valor),0) v FROM parcelas pa
            JOIN propostas p ON p.id=pa.proposta_id
            WHERE pa.status='Pendente de receber' AND p.status_operacional='Emitida/Ativa'""").fetchone()['v']
        m['fc_caixa'] = conn.execute("""SELECT COALESCE(SUM(pa.valor),0) v FROM parcelas pa
            JOIN propostas p ON p.id=pa.proposta_id
            WHERE pa.status='Recebido e não repassado' AND p.status_operacional='Emitida/Ativa'""").fetchone()['v']
        m['fc_liberado'] = conn.execute("""SELECT COALESCE(SUM(pa.valor),0) v FROM parcelas pa
            JOIN propostas p ON p.id=pa.proposta_id
            WHERE pa.status='Liberado para o corretor' AND p.status_operacional='Emitida/Ativa'""").fetchone()['v']
        m['fc_pago'] = conn.execute("""SELECT COALESCE(SUM(pa.valor),0) v FROM parcelas pa
            JOIN propostas p ON p.id=pa.proposta_id
            WHERE pa.status='Pago ao corretor' AND p.status_operacional='Emitida/Ativa'""").fetchone()['v']
        m['fc_antecip'] = conn.execute("SELECT COUNT(*) c FROM parcelas WHERE status='Antecipação - Aguardando ADM'").fetchone()['c']
        # Vendas do dia e da semana (Guilherme, 20/07: "gostaria de saber as
        # vendas do dia, da semana e do mês"). "Hoje" e "semana" olham pra
        # criado_em (quando a proposta foi de fato lançada no sistema) — datas
        # de calendário reais, diferente do "mês" acima (que usa mes_meta, o
        # ciclo comercial/fechamento). "Semana" usa o MESMO ciclo quinta-a-
        # terça que o resto do sistema já usa em Fluxo de Caixa, pra não criar
        # um terceiro conceito de semana.
        hoje_ini = date.today().isoformat()
        hoje_fim = (date.today() + timedelta(days=1)).isoformat()
        m['hoje_qtd'] = conn.execute(
            "SELECT COUNT(*) c FROM propostas WHERE status != 'Excluída' AND criado_em>=? AND criado_em<?",
            (hoje_ini, hoje_fim)).fetchone()['c']
        m['hoje_valor'] = conn.execute(
            "SELECT COALESCE(SUM(valor),0) v FROM propostas WHERE status != 'Excluída' AND criado_em>=? AND criado_em<?",
            (hoje_ini, hoje_fim)).fetchone()['v']
        _ciclo_sem = ciclo_atual()
        sem_ini = _ciclo_sem['inicio_iso']
        sem_fim = (date.fromisoformat(_ciclo_sem['fim_iso']) + timedelta(days=1)).isoformat()
        m['semana_qtd'] = conn.execute(
            "SELECT COUNT(*) c FROM propostas WHERE status != 'Excluída' AND criado_em>=? AND criado_em<?",
            (sem_ini, sem_fim)).fetchone()['c']
        m['semana_valor'] = conn.execute(
            "SELECT COALESCE(SUM(valor),0) v FROM propostas WHERE status != 'Excluída' AND criado_em>=? AND criado_em<?",
            (sem_ini, sem_fim)).fetchone()['v']
        # Alerta auditoria: propostas que precisam evoluir o status operacional
        m['auditoria_pendente'] = conn.execute("""SELECT COUNT(*) c FROM propostas
            WHERE status != 'Excluída' AND status_operacional NOT IN ('Emitida/Ativa')
            AND status_operacional IS NOT NULL""").fetchone()['c']
        ultimas = conn.execute(f"SELECT * FROM propostas WHERE status != 'Excluída'{filtro_mes_sql} ORDER BY id DESC LIMIT 5", filtro_mes_params).fetchall()
        por_operadora = conn.execute(f"""SELECT adm_operadora,COUNT(*) qtd,COALESCE(SUM(valor),0) valor
            FROM propostas WHERE status != 'Excluída'{filtro_mes_sql} GROUP BY adm_operadora ORDER BY valor DESC LIMIT 8""", filtro_mes_params).fetchall()
        por_consultor = conn.execute(f"""SELECT consultor,COUNT(*) qtd,COALESCE(SUM(valor),0) valor,COALESCE(SUM(comissao_consultor),0) com
            FROM propostas WHERE status != 'Excluída'{filtro_mes_sql} GROUP BY consultor ORDER BY valor DESC""", filtro_mes_params).fetchall()
        meses_disponiveis = [r['mes_meta'] if hasattr(r,'keys') else r[0] for r in conn.execute(
            "SELECT DISTINCT mes_meta FROM propostas WHERE mes_meta IS NOT NULL AND mes_meta != '' ORDER BY mes_meta DESC").fetchall()]
        # So periodo bem formado entra no seletor.
        #
        # Uma proposta com mes_meta torto (o Guilherme viu um '7202', que e
        # 2027 digitado ao contrario) virava uma opcao chamada '/7202' — um
        # periodo que nao existe, oferecido como se existisse. Filtrar aqui nao
        # conserta o dado; impede que o dado errado vire escolha na tela.
        meses_disponiveis = [x for x in meses_disponiveis if _mes_meta_valido(x)]
        mes_atual_sp = datetime.now(TZ_SP).strftime('%Y-%m')
        if mes_atual_sp not in meses_disponiveis:
            meses_disponiveis.insert(0, mes_atual_sp)
        # A FILA VEM PRIMEIRO. O dashboard abria com dinheiro do mes e o consultor
        # nao sabia o que fazer AGORA — a informacao mais acionavel da tela.
        fila = _agenda_fila(conn, uid, eh_admin=False, limite=6)
        fila_n = _agenda_resumo(conn, uid, eh_admin=False)
        tempo_resp = _tempo_resposta_do_dia(conn)
        close_db(conn)
        return render_template('dashboard_admin.html', m=m, ultimas=ultimas,
                               por_operadora=por_operadora, por_consultor=por_consultor,
                               fila=fila, fila_n=fila_n, tempo_resp=tempo_resp,
                               ciclo=ciclo_atual(), f_mes=f_mes, meses_disponiveis=meses_disponiveis)
    else:
        m = {}
        ma = datetime.now(TZ_SP).strftime('%Y-%m')
        m['propostas'] = conn.execute("SELECT COUNT(*) c FROM propostas WHERE usuario_id=? AND status != 'Excluída'",(uid,)).fetchone()['c']
        m['vidas'] = conn.execute("SELECT COALESCE(SUM(total_vidas),0) v FROM propostas WHERE usuario_id=? AND status != 'Excluída'",(uid,)).fetchone()['v']
        m['producao'] = conn.execute("SELECT COALESCE(SUM(valor),0) v FROM propostas WHERE usuario_id=? AND status != 'Excluída'",(uid,)).fetchone()['v']
        m['minha_comissao'] = conn.execute("SELECT COALESCE(SUM(comissao_consultor),0) v FROM propostas WHERE usuario_id=? AND status != 'Excluída'",(uid,)).fetchone()['v']
        # mes_meta para metas comerciais (usa coluna mes_meta, não criado_em)
        m['mes_propostas'] = conn.execute("SELECT COUNT(*) c FROM propostas WHERE usuario_id=? AND status != 'Excluída' AND mes_meta=?",(uid,ma)).fetchone()['c']
        m['mes_producao'] = conn.execute("SELECT COALESCE(SUM(valor),0) v FROM propostas WHERE usuario_id=? AND status != 'Excluída' AND mes_meta=?",(uid,ma)).fetchone()['v']
        m['mes_comissao'] = conn.execute("SELECT COALESCE(SUM(comissao_consultor),0) v FROM propostas WHERE usuario_id=? AND status != 'Excluída' AND mes_meta=?",(uid,ma)).fetchone()['v']
        # Saldo do consultor por status de parcelas (apenas Emitida/Ativa)
        m['a_receber'] = conn.execute("""SELECT COALESCE(SUM(pa.valor),0) v FROM parcelas pa
            JOIN propostas p ON p.id=pa.proposta_id
            WHERE p.usuario_id=? AND pa.status='Liberado para o corretor' AND p.status_operacional='Emitida/Ativa'""",(uid,)).fetchone()['v']
        m['pago_total'] = conn.execute("""SELECT COALESCE(SUM(pa.valor),0) v FROM parcelas pa
            JOIN propostas p ON p.id=pa.proposta_id WHERE p.usuario_id=? AND pa.status='Pago ao corretor'""",(uid,)).fetchone()['v']
        m['antecip_solicitadas'] = conn.execute("""SELECT COUNT(*) c FROM parcelas pa
            JOIN propostas p ON p.id=pa.proposta_id WHERE p.usuario_id=? AND pa.comprovante_antecipacao IS NOT NULL""",(uid,)).fetchone()['c']
        # Pendências: parcelas bloqueadas por falta de comprovante
        m['bloqueadas'] = conn.execute("""SELECT COUNT(*) c FROM parcelas pa
            JOIN propostas p ON p.id=pa.proposta_id
            WHERE p.usuario_id=? AND pa.status='Bloqueado - Falta Comprovante'""",(uid,)).fetchone()['c']
        pendencias_comprovante = conn.execute("""SELECT p.id, p.razao_social, p.adm_operadora, COUNT(pa.id) qtd_bloq
            FROM propostas p JOIN parcelas pa ON pa.proposta_id=p.id
            WHERE p.usuario_id=? AND pa.status='Bloqueado - Falta Comprovante'
            GROUP BY p.id ORDER BY p.id DESC""",(uid,)).fetchall()
        rb = session.get('regime_base')
        if rb == 'com_lead':
            # Nível pela MESMA fonte do cálculo real (tabela niveis via
            # _nivel_por_producao) — era hardcoded N1<=3000/N2<=7000 aqui, então
            # mudar as faixas em /niveis mudava o pagamento mas o consultor via
            # o rótulo antigo (duas verdades na tela).
            nivel_cod = _nivel_por_producao(m['mes_producao'] or 0, conn)
            try:
                nv = conn.execute("SELECT label, faixa_min, faixa_max FROM niveis WHERE codigo=?",
                                  (nivel_cod,)).fetchone()
            except Exception:
                nv = None
            if nv:
                fx = (f"até R$ {float(nv['faixa_max']):,.0f}".replace(',', '.') if nv['faixa_max'] is not None
                      else f"acima de R$ {float(nv['faixa_min'] or 0):,.0f}".replace(',', '.'))
                m['regime_label'] = f"Com Lead — {nv['label'] or nivel_cod.upper()} ({fx})"
            else:
                m['regime_label'] = f"Com Lead — {nivel_cod.upper()}"
        elif rb == 'com_fixo_lead': m['regime_label'] = 'Com Fixo + Com Lead'
        else: m['regime_label'] = 'Sem Lead e Sem Fixo'
        # Fixo da MESMA fonte que o pagamento usa (usuarios.valor_fixo, via
        # gerar_fixo_mes) — antes lia da tabela legado 'regimes' e o consultor
        # podia ver um valor diferente do que recebia.
        m['valor_fixo'] = 0
        if rb == 'com_fixo_lead':
            r = conn.execute("SELECT valor_fixo FROM usuarios WHERE id=?", (uid,)).fetchone()
            m['valor_fixo'] = (r['valor_fixo'] or 0) if r else 0
        pendentes_aceite = conn.execute("""SELECT pa.*, p.razao_social, p.adm_operadora FROM parcelas pa
            JOIN propostas p ON p.id=pa.proposta_id
            WHERE p.usuario_id=? AND pa.status='Liberado para o corretor' AND pa.aceite_corretor=0
            ORDER BY pa.id""",(uid,)).fetchall()
        ultimas = conn.execute("SELECT * FROM propostas WHERE usuario_id=? AND status != 'Excluída' ORDER BY id DESC LIMIT 5",(uid,)).fetchall()
        por_operadora = conn.execute("""SELECT adm_operadora,COUNT(*) qtd,COALESCE(SUM(valor),0) valor
            FROM propostas WHERE usuario_id=? AND status != 'Excluída' GROUP BY adm_operadora ORDER BY valor DESC LIMIT 6""",(uid,)).fetchall()
        fila = _agenda_fila(conn, uid, eh_admin=False, limite=6)
        fila_n = _agenda_resumo(conn, uid, eh_admin=False)
        tempo_resp = _tempo_resposta_do_dia(conn, uid)
        close_db(conn)
        return render_template('dashboard_consultor.html', m=m, ultimas=ultimas,
                               fila=fila, fila_n=fila_n, tempo_resp=tempo_resp,
                               por_operadora=por_operadora, pendentes_aceite=pendentes_aceite,
                               pendencias_comprovante=pendencias_comprovante)

# ─── PROPOSTAS ───────────────────────────────────────────────────────────────────
# Onde a venda e OPERADA no sistema da operadora. A Serenus vende; quem tem os
# acessos aos paineis das operadoras nem sempre e a Serenus. Isso muda o que
# acontece depois do cadastro, entao vira dado, nao combinado por WhatsApp.
# O CONSULTOR NAO PRECISA SABER A ESTRUTURA DA PARCERIA. Ele precisa saber o que
# acontece com a venda dele. Entao a tela pergunta UMA coisa — quem lanca isto na
# operadora — e o sistema traduz pra plataforma certa aqui atras.
# Axioma saiu: nao se protocola mais venda por la (cadastro em encerramento).
_PLATAFORMA_PADRAO = 'Affinity (Serenus)'
# DUAS opcoes, nao tres. A terceira ('eu lanco e aviso') pedia ao vendedor uma
# decisao que nao e dele: avisar ou nao o escritorio e assunto de bastidor. Ele
# decide uma coisa so — se ele mesmo faz o cadastro ou se pede pra fazerem.
_PLATAFORMA_PAPEL = {
    'propria': 'Eu mesmo faço',
    'processar': 'Quero que façam por mim',
}


def _plataforma_do_papel(papel):
    """Papel escolhido na tela -> plataforma de verdade. 'propria' e a Serenus
    resolvendo sozinha; qualquer outro passa pela operacao parceira."""
    return _PLATAFORMA_PADRAO if (papel or 'propria') == 'processar' else 'Serenus'



@app.route('/nova-proposta')
@login_required
def nova_proposta():
    conn = db()
    sups = conn.execute("SELECT * FROM supervisoras WHERE ativo=1 ORDER BY nome").fetchall()
    ops = [o['display'] for o in _operadoras_lista(conn)]
    # Pré-preenchimento a partir da última análise de WhatsApp do lead (botão
    # "Fechei essa proposta — criar no JOB" na extensão manda ?lead=N). Enche só
    # o que a IA extraiu com segurança dos documentos; o financeiro fica pro
    # consultor. Se não houver análise/lead, vem vazio (formulário normal).
    prefill = {}
    lead_id = (request.args.get('lead') or '').strip()
    if lead_id.isdigit():
        row = conn.execute("SELECT sugestoes_json FROM whatsapp_analises WHERE lead_id=? ORDER BY id DESC LIMIT 1",
                           (lead_id,)).fetchone()
        lead = conn.execute("SELECT nome, valor_estimado FROM crm_leads WHERE id=?", (lead_id,)).fetchone()
        diag = {}
        if row:
            try:
                diag = json.loads(row['sugestoes_json'] or '{}')
            except Exception:
                diag = {}
        ia = diag.get('ia') or {}
        pessoas = ia.get('documentos_pessoas') or []
        empresa = ia.get('dados_empresa') or {}
        extr = diag.get('extracao') or {}
        # O QUE VEIO DOS DOCUMENTOS TEM PRECEDENCIA sobre o que a IA deduziu da
        # conversa: um RG lido e melhor fonte que uma frase no WhatsApp. Antes
        # este caminho so olhava a analise da conversa, entao lead que mandou os
        # documentos pela extensao abria a proposta em branco.
        _ex = _extracao_ler(conn, int(lead_id))
        if _ex.get('pessoas'):
            pessoas = _ex['pessoas']
        if _ex.get('empresa', {}).get('cnpj'):
            empresa = _ex['empresa']

        # QUEM E O TITULAR nao se adivinha por ordem da lista: o consultor ja
        # respondeu isso documento por documento. Endereco e contato nao entram
        # aqui porque o formulario nao tem esses campos — eles vao no bloco de
        # texto, que e onde servem.
        try:
            papeis = {}
            for r_ in conn.execute("""SELECT pessoa, titularidade, parentesco FROM lead_documento
                                      WHERE lead_id=? AND pessoa IS NOT NULL AND pessoa<>''""",
                                   (int(lead_id),)).fetchall():
                atual = papeis.get(r_['pessoa']) or {}
                papeis[r_['pessoa']] = {'titularidade': r_['titularidade'] or atual.get('titularidade'),
                                        'parentesco': r_['parentesco'] or atual.get('parentesco')}
            def _papel(nome):
                for k, v_ in papeis.items():
                    if doc_mesma_pessoa(k, nome):
                        return v_
                return {}
            tit_doc = next((p for p in pessoas if _papel(p.get('nome')).get('titularidade') == 'titular'), None)
            if tit_doc:
                pessoas = [tit_doc] + [p for p in pessoas if p is not tit_doc]
            for p in pessoas:
                p['_parentesco'] = _DOC_PARENTESCO_ROTULO.get(_papel(p.get('nome')).get('parentesco'), '')
        except Exception as e_:
            app.logger.info(f"[PROPOSTA] papeis: {e_}")
        def _iso(dt):  # aceita DD/MM/AAAA e AAAA-MM-DD -> YYYY-MM-DD (input type=date)
            s = str(dt or '').strip()
            # A leitura de documento ja devolve ISO; so a analise de conversa
            # devolve BR. Aceitar so um dos dois deixava a data de nascimento
            # em branco justo quando ela vinha do RG, que e a fonte boa.
            m = re.match(r'^(\d{4})-(\d{1,2})-(\d{1,2})$', s)
            if m:
                return f"{m.group(1)}-{int(m.group(2)):02d}-{int(m.group(3)):02d}"
            m = re.match(r'^(\d{1,2})/(\d{1,2})/(\d{4})', s)
            return f"{m.group(3)}-{int(m.group(2)):02d}-{int(m.group(1)):02d}" if m else ''

        if pessoas:
            tit = pessoas[0]
            prefill['nome_titular'] = tit.get('nome') or ''
            prefill['cpf_titular'] = tit.get('cpf') or ''
            prefill['data_nasc_titular'] = _iso(tit.get('nascimento'))
            # O CPF do dependente vem junto porque e ele que destrava a busca do
            # cartao SUS: com CPF + nascimento no prefill, o CNS da familia
            # inteira aparece sozinho quando o formulario abre.
            prefill['dependentes'] = [{'nome': p.get('nome') or '', 'nasc': _iso(p.get('nascimento')),
                                       'cpf': p.get('cpf') or '',
                                       'parentesco': p.get('_parentesco') or ''}
                                      for p in pessoas[1:] if p.get('nome')]
            prefill['total_vidas'] = len(pessoas)
        cnpj = (empresa.get('cnpj') or extr.get('cnpj') or '').strip()
        prefill['cnpj'] = cnpj
        prefill['tipo_pessoa'] = 'PME' if cnpj else 'PF'
        prefill['razao_social'] = (empresa.get('razao_social') or (pessoas[0].get('nome') if pessoas else '')
                                   or (lead['nome'] if lead else '') or '')
        if lead and lead['valor_estimado']:
            prefill['valor'] = f"{float(lead['valor_estimado']):.2f}".replace('.', ',')
        # O bloco pronto pra colar na operadora vai junto: quem abre a proposta
        # normalmente vai preencher o sistema deles logo em seguida.
        try:
            prefill['docs_texto'] = docs_texto_bloco(conn, int(lead_id)) or (diag.get('docs_extraidos') or '')
        except Exception:
            prefill['docs_texto'] = diag.get('docs_extraidos') or ''
    close_db(conn)
    # Propaga o id do lead pro formulário: e a chave que liga a venda a origem de
    # midia. Sem ela, salvar_proposta re-adivinha por telefone/CNPJ justamente no
    # caso em que a resposta certa ja estava na mao.
    # DONO DA VENDA vira gente de verdade, nao texto digitado. E quem sobe a
    # venda e a sessao — o formulario so mostra, nao pergunta.
    conn2 = db()
    consultores = [dict(r) for r in conn2.execute(
        "SELECT id, nome FROM usuarios WHERE ativo=1 ORDER BY nome").fetchall()]
    close_db(conn2)
    return render_template('form.html', supervisoras=sups, operadoras=ops, prefill=prefill,
                           consultores=consultores,
                           papeis=_PLATAFORMA_PAPEL,
                           lead_id_origem=(lead_id if lead_id.isdigit() else ''))


# ── AVISO A PLATAFORMA DE VENDA (Affinity) ────────────────────────────────────
# Sao DUAS conversas diferentes com a mesma empresa, e tratar as duas como uma
# so e o que faz venda parar no meio:
#   ciencia   — eu ja subi na operadora, voces nao precisam fazer nada. Sem
#               anexo: e recado, nao processo.
#   protocolo — subam voces por mim. Aqui vao os documentos, com nome que se le.
# NADA SAI SOZINHO. O consultor le, ajusta se quiser, e manda.

def _cfg_valor(conn, chave, padrao=''):
    r = conn.execute("SELECT valor FROM config WHERE chave=?", (chave,)).fetchone()
    return (r['valor'] if r and r['valor'] else padrao)


