def _plataforma_dados(conn, pid):
    p = conn.execute("SELECT * FROM propostas WHERE id=?", (pid,)).fetchone()
    if not p:
        return None
    d = dict(p)
    d['_vidas'] = d.get('total_vidas') or 0
    d['_valor'] = _moeda(d.get('valor') or 0)
    d['_vig'] = _fmt_data_br(d.get('vigencia'))
    d['_vig_confirmada'] = bool(d.get('vigencia_confirmada'))
    d['_local'] = ' / '.join(x for x in [d.get('cidade'), d.get('estado')] if x)
    return d


def _plataforma_assunto(d, tipo):
    quem = d.get('razao_social') or d.get('nome_titular') or 'cliente'
    num = (d.get('numero_proposta') or '').strip()
    marca = f" — proposta {num}" if num else ""
    if tipo == 'protocolo':
        return f"Solicitacao de protocolo: {quem} — {d.get('adm_operadora') or 'operadora'}{marca}"
    return f"Ciencia: venda protocolada por nos — {quem} — {d.get('adm_operadora') or 'operadora'}{marca}"


def _plataforma_corpo(d, tipo, docs=None):
    """Corpo em TEXTO PURO — a tela edita num textarea e quem transforma em
    e-mail bonito e o `_montar_email_html_profissional`, que ja existe. Devolver
    HTML aqui faria o consultor editar tag no meio do texto."""
    linhas = []
    def li(rot, val):
        if val not in (None, '', 0):
            linhas.append(f"{rot}: {val}")
    li('Cliente', d.get('razao_social'))
    li('CNPJ', d.get('cnpj'))
    li('CPF do titular', d.get('cpf_titular'))
    li('Cidade/UF', d.get('_local'))
    li('Operadora', d.get('adm_operadora'))
    li('Produto', d.get('produto'))
    li('Modalidade', d.get('modalidade'))
    li('Acomodacao', d.get('acomodacao'))
    li('Coparticipacao', d.get('fator_moderador'))
    li('Vidas', d.get('_vidas'))
    li('Valor mensal', d.get('_valor'))
    li('Vigencia', (d.get('_vig') or '') + ('' if d.get('_vig_confirmada') else ' (previsao, a confirmar)'))
    li('No da proposta', d.get('numero_proposta'))
    if d.get('resp_fin_nome'):
        linhas.append('')
        linhas.append(f"Responsavel financeiro: {d['resp_fin_nome']}"
                      + (f" ({d.get('resp_fin_parentesco')})" if d.get('resp_fin_parentesco') else ''))
        li('CPF do responsavel', d.get('resp_fin_cpf'))

    if tipo == 'protocolo':
        cab = ("Segue proposta para cadastro no sistema da operadora. "
               "Os documentos do cliente vao em anexo, ja nomeados.")
        pe = ("Qualquer pendencia de documento ou divergencia de dado, e so responder "
              "este e-mail que resolvemos com o cliente.")
    else:
        cab = ("Esta venda ja foi cadastrada por nos diretamente no sistema da operadora. "
               "NAO E PRECISO FAZER NADA — este e-mail e apenas para ciencia e acompanhamento.")
        pe = "Qualquer duvida, e so responder este e-mail."

    corpo = [cab, ''] + linhas
    if tipo == 'protocolo':
        corpo += ['']
        if docs:
            corpo += [f"Documentos em anexo ({len(docs)}):"] + [f"- {x}" for x in docs]
        else:
            corpo += ["Sem documentos anexados — vamos enviar em seguida."]
    corpo += ['', pe]
    return "\n".join(corpo)


# ═══════════ QUE ANEXO VAI EM QUE E-MAIL ═══════════════════════════════════
# Cada e-mail que sai daqui leva um pacote diferente, e isso estava escrito
# dentro de cada função de envio — a antecipação mandava comprovante E contrato
# porque alguém digitou os dois numa lista, e mudar exigia deploy.
#
# Agora a regra é dado, não código: mora na tabela `config` e o Guilherme muda
# na tela. O default abaixo é só o ponto de partida de quem nunca configurou.
_EMAIL_MODELOS = [
    ('protocolo',   'Protocolo da proposta',
     'Vai para a administradora com a documentação do cliente.'),
    ('antecipacao', 'Antecipação de comissão',
     'Pede o adiantamento. Não precisa da papelada do cliente de novo.'),
    ('ciencia',     'Ciência / aviso',
     'Comunicado sem documentação.'),
]
_EMAIL_ANEXOS_PADRAO = {
    # Tudo do cliente, MENOS o que é da antecipação.
    'protocolo': ['identidade', 'cpf', 'comprovante_endereco', 'cartao_cnpj',
                  'contrato_social', 'certidao_casamento', 'declaracao_uniao_estavel',
                  'certidao_nascimento', 'carteira_trabalho', 'holerite',
                  'cartao_plano', 'cartao_sus', 'declaracao_saude', 'outro'],
    # O Guilherme foi explícito: só o comprovante, mais nada.
    'antecipacao': ['comprovante_pagamento'],
    'ciencia': [],
}


def _email_regra_anexos(conn, modelo):
    """Tipos de documento que seguem naquele modelo de e-mail."""
    try:
        salvo = _cfg_valor(conn, 'email_anexos_' + modelo, '')
        if salvo:
            return [t for t in json.loads(salvo) if t in _DOC_TIPO_NOME]
    except Exception:
        pass
    return list(_EMAIL_ANEXOS_PADRAO.get(modelo, []))


def _email_regra_salvar(conn, modelo, tipos):
    tipos = [t for t in (tipos or []) if t in _DOC_TIPO_NOME]
    valor = json.dumps(tipos, ensure_ascii=False)
    if HAS_POSTGRES:
        conn.execute("""INSERT INTO config (chave,valor) VALUES (?,?)
                        ON CONFLICT (chave) DO UPDATE SET valor=EXCLUDED.valor""",
                     ('email_anexos_' + modelo, valor))
    else:
        conn.execute("INSERT OR REPLACE INTO config (chave,valor) VALUES (?,?)",
                     ('email_anexos_' + modelo, valor))
    return tipos


def _anexos_por_regra(conn, proposta, modelo):
    """Filtra os anexos da proposta pelos tipos que aquele modelo leva.

    O tipo mora no NOME do arquivo (ver _doc_tipo_do_nome). Documento antigo,
    gravado antes de existir tipo, cai em 'outro' — por isso 'outro' está no
    pacote do protocolo: sem ele, proposta antiga sairia sem anexo nenhum."""
    permitidos = set(_email_regra_anexos(conn, modelo))
    try:
        lista = json.loads((proposta.get('anexos') if isinstance(proposta, dict)
                            else proposta['anexos']) or '[]') or []
    except Exception:
        lista = []
    saida = []
    for item in lista:
        nome = item.get('nome') if isinstance(item, dict) else item
        if nome and _doc_tipo_do_nome(os.path.basename(nome)) in permitidos:
            saida.append(nome)
    # Os dois campos dedicados não estão no array de anexos, mas têm tipo fixo.
    def _pega(campo, tipo):
        v = (proposta.get(campo) if isinstance(proposta, dict) else proposta[campo])
        if v and tipo in permitidos:
            saida.append(v)
    _pega('comprovante_boleto', 'comprovante_pagamento')
    _pega('contrato_arquivo', 'proposta_operadora')
    return saida


def _plataforma_anexos(conn, d):
    """Os arquivos do PROTOCOLO, com o nome que o outro lado consegue ler.

    Regra que ja existia e continua valendo: contrato assinado e comprovante de
    pagamento NAO vao no protocolo — sao documentos finais, usados na
    antecipacao de comissao. O que muda e que agora vao junto os documentos do
    cliente lidos pela extensao, com o nome padronizado ('RG-CNH - TITULAR -
    BRUNO.pdf') em vez de '20260801_doc_IMG-2231.pdf'."""
    saida, vistos = [], set()
    lead_id = d.get('lead_id')
    if lead_id:
        for r in conn.execute("""SELECT arquivo, nome_final, nome_arquivo FROM lead_documento
                                 WHERE lead_id=? AND arquivo IS NOT NULL
                                 ORDER BY titularidade DESC, tipo""", (lead_id,)).fetchall():
            base = os.path.basename(r['arquivo'])
            if base in vistos:
                continue
            vistos.add(base)
            saida.append((base, r['nome_final'] or r['nome_arquivo'] or base))
    try:
        for nome in (json.loads(d.get('anexos') or '[]') or []):
            n = nome.get('nome') if isinstance(nome, dict) else nome
            b = os.path.basename(n or '')
            if b and b not in vistos:
                vistos.add(b)
                saida.append((b, None))
    except Exception:
        pass
    return saida


def _plataforma_whats(d, tipo, destino):
    """Resumo pro grupo. Diz que e automatico e que o e-mail ja foi — senao a
    gestora fica sem saber se precisa responder aqui ou la."""
    cab = ('Protocolo solicitado' if tipo == 'protocolo' else 'Venda protocolada por nos')
    linhas = [f"*{cab}*", ""]
    for rot, val in (('Cliente', d.get('razao_social')), ('Operadora', d.get('adm_operadora')),
                     ('Produto', d.get('produto')), ('Modalidade', d.get('modalidade')),
                     ('Vidas', d.get('_vidas')), ('Valor', d.get('_valor')),
                     ('Cidade', d.get('_local')),
                     ('Vigencia', (d.get('_vig') or '') + ('' if d.get('_vig_confirmada') else ' (previsao)')),
                     ('Nº proposta', d.get('numero_proposta'))):
        if val not in (None, '', 0):
            linhas.append(f"{rot}: {val}")
    linhas.append("")
    linhas.append("Nao precisa fazer nada — e so ciencia." if tipo != 'protocolo'
                  else "Pedimos que voces protocolem no sistema da operadora.")
    linhas.append("")
    # Sem endereco de e-mail aqui: e mensagem de grupo, nao cabecalho de e-mail.
    linhas.append("_Mensagem automatica do JOB. O e-mail com os detalhes ja foi enviado._")
    return "\n".join(linhas)


@app.route('/proposta/<int:pid>/plataforma/preview')
@login_required
def proposta_plataforma_preview(pid):
    """Monta o e-mail pra pessoa LER antes de mandar. Nada sai sozinho."""
    tipo = 'protocolo' if request.args.get('tipo') == 'protocolo' else 'ciencia'
    conn = db()
    d = _plataforma_dados(conn, pid)
    if not d:
        close_db(conn); return jsonify({"ok": False, "erro": "Proposta não encontrada"}), 404
    destino = _plataforma_email_destino(conn, d.get('plataforma_venda'))
    anexos = _plataforma_anexos(conn, d) if tipo == 'protocolo' else []
    close_db(conn)
    nomes = [n or os.path.basename(f) for f, n in anexos]
    return jsonify({"ok": True, "tipo": tipo, "destino": destino,
                    "papel": d.get('plataforma_papel') or 'propria',
                    "plataforma": d.get('plataforma_venda') or '',
                    "assunto": _plataforma_assunto(d, tipo),
                    "corpo": _plataforma_corpo(d, tipo, nomes),
                    "anexos": nomes,
                    "whats": _plataforma_whats(d, tipo, destino),
                    "avisada_em": d.get('plataforma_avisada_em')})



# ── MUTIRAO: as perdas antigas que ficaram sem motivo ─────────────────────────
# A trava nova so vale daqui pra frente. O passivo (216 perdas com "Nao
# informado") nao se resolve sozinho, e uma a uma pela ficha ninguem faz.
# Esta tela existe pra ser fechada: quando o numero chegar a zero, ela some do
# painel e nao volta.

# O que cada motivo QUER DIZER. Sem isto, "Sumiu" e "Nao e o decisor" viram
# escolha por eliminacao, e o relatorio de perda mede o chute do consultor.
# Frase curta e no lugar onde ele escolhe — nao num manual que ninguem abre.
MOTIVO_PERDA_AJUDA = {
    'Preço': 'Achou caro e não fechou nem com desconto ou plano menor. Se ele fechou com um mais barato em OUTRA corretora, é "Fechou com outro".',
    'Fechou com outro': 'Comprou plano de saúde, mas com outro corretor ou direto na operadora. A venda existiu — só não foi nossa.',
    'Rede insuficiente': 'O hospital ou o médico que ele queria não está na rede do plano que a gente conseguia oferecer.',
    'Carência': 'Precisava usar antes do prazo de carência, ou não conseguiu aproveitar carência do plano antigo.',
    'Não é o decisor': 'Falamos com quem não decide. O sócio, o RH ou o cônjuge não aprovou e não conseguimos chegar em quem decide.',
    'Recusado pela operadora': 'A operadora não aceitou a proposta — por saúde declarada, região, porte da empresa ou análise interna.',
    'Sumiu': 'Parou de responder e não deu motivo. Use quando não dá pra saber o que houve.',
    'Fora de área': 'A operadora não vende ou não tem rede na cidade dele.',
    'Lead inválido': 'Número errado, teste, duplicado, ou pessoa que nunca pediu cotação. Não era um cliente em potencial.',
    # NOSSA recusa, não a da operadora. São coisas diferentes e o relatório de
    # perda precisa saber qual foi: "recusado pela operadora" é mercado, "pelo
    # corretor" é decisão nossa — e decisão nossa exige justificativa escrita,
    # senão vira caixa preta onde qualquer desistência se esconde.
    'Recusado pelo corretor': 'NÓS decidimos não seguir — pré-existência que inviabiliza, perfil de risco, '
                              'cliente problemático, valor que não paga o trabalho. Escreva o porquê no campo abaixo.',
}


def _motivos_perda_lista(conn):
    try:
        r = conn.execute("SELECT opcoes_json FROM crm_campos WHERE chave='motivo_perda'").fetchone()
        return json.loads(r['opcoes_json'] or '[]') if r else []
    except Exception:
        return []


def _campo_motivo_perda(conn):
    return conn.execute("SELECT id, opcoes_json FROM crm_campos WHERE chave='motivo_perda'").fetchone()


@app.route('/crm/mutirao-perdas')
@login_required
@admin_required
def crm_mutirao_perdas():
    conn = db()
    campo = _campo_motivo_perda(conn)
    try:
        opcoes = json.loads(campo['opcoes_json'] or '[]') if campo else []
    except Exception:
        opcoes = []
    # Sem motivo NEM na coluna NEM no campo — as duas fontes existem e alguem
    # pode ter preenchido so uma delas.
    linhas = conn.execute("""
        SELECT l.id, l.nome, l.telefone, l.origem, l.criado_em, l.avancou_em,
               e.nome AS etapa_nome, u.nome AS responsavel
          FROM crm_leads l
          JOIN crm_etapas e ON e.slug = l.etapa AND e.tipo = 'perdido'
          LEFT JOIN usuarios u ON u.id = l.responsavel_id
         WHERE COALESCE(NULLIF(TRIM(COALESCE(l.perdido_motivo,'')), ''), '') = ''
           AND l.id NOT IN (SELECT lead_id FROM crm_lead_campos
                            WHERE campo_id = ? AND TRIM(COALESCE(valor,'')) <> '')
         ORDER BY COALESCE(l.avancou_em, l.criado_em) DESC
    """, (campo['id'] if campo else 0,)).fetchall()
    # A ultima coisa que aconteceu ajuda a lembrar por que se perdeu — sem isso
    # e um nome numa lista e o consultor chuta.
    ultimas = {}
    if linhas:
        ids = [r['id'] for r in linhas]
        marc = ','.join(['?'] * len(ids))
        try:
            for r in conn.execute(f"""SELECT lead_id, descricao, criado_em FROM crm_atividades
                                      WHERE lead_id IN ({marc})
                                      ORDER BY id DESC""", ids).fetchall():
                ultimas.setdefault(r['lead_id'], (r['descricao'] or '')[:110])
        except Exception:
            pass
    close_db(conn)
    itens = [{**dict(r), 'ultima': ultimas.get(r['id'], ''),
              'quando': _fmt_data_br(r['avancou_em'] or r['criado_em'])} for r in linhas]
    return render_template('crm_mutirao_perdas.html', itens=itens, opcoes=opcoes,
                           ajuda=MOTIVO_PERDA_AJUDA)


@app.route('/crm/mutirao-perdas/salvar', methods=['POST'])
@login_required
@admin_required
def crm_mutirao_perdas_salvar():
    """Grava em lote. Escreve nos DOIS lugares: a coluna, de onde o painel le, e
    o campo, que e o que a ficha mostra."""
    d = request.json or {}
    itens = d.get('itens') or []
    if not isinstance(itens, list) or not itens:
        return jsonify({"ok": False, "erro": "Nada para salvar"}), 400
    conn = db()
    campo = _campo_motivo_perda(conn)
    try:
        validas = set(json.loads(campo['opcoes_json'] or '[]')) if campo else set()
    except Exception:
        validas = set()
    n = 0
    try:
        for it in itens[:500]:
            try:
                lid = int(it.get('id') or 0)
            except (TypeError, ValueError):
                continue
            motivo = str(it.get('motivo') or '').strip()
            if not lid or not motivo or (validas and motivo not in validas):
                continue
            conn.execute("UPDATE crm_leads SET perdido_motivo=? WHERE id=?", (motivo[:120], lid))
            gravar_campo_lead(conn, lid, 'motivo_perda', motivo, fonte='mutirao')
            conn.execute("""INSERT INTO crm_atividades (lead_id, usuario_nome, tipo, descricao)
                            VALUES (?,?,?,?)""",
                         (lid, session.get('nome'), 'nota',
                          f'Motivo da perda preenchido no mutirão: {motivo}'))
            n += 1
        conn.commit()
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        close_db(conn)
        app.logger.warning(f"[MUTIRAO] {e}")
        return jsonify({"ok": False, "erro": "Não consegui salvar"}), 200
    close_db(conn)
    return jsonify({"ok": True, "gravados": n})



# ═══ MOTOR DA AGENDA ══════════════════════════════════════════════════════════
# A agenda tinha 1 atrasada, 0 hoje e 0 futuras — com 5.086 leads sem primeiro
# contato. Nao era falta de disciplina: so existia o que alguem digitou a mao, e
# ninguem digita. Aqui a tarefa NASCE do que o sistema ja sabe.
#
# Tres decisoes que vieram do estudo e das criticas dos consultores:
#
# 1. TETO POR PESSOA. Um consultor que tambem atende, cota e fecha faz 20 a 25
#    leads novos por dia. Fila maior que isso nao e ambicao, e paralisia — a
#    pessoa para de encarar QUALQUER fila. Por isso o motor tem teto diario.
# 2. TAREFA NASCE COM O MOTIVO E A FRASE. "Fazer follow-up" faz o consultor
#    abrir, nao saber o que dizer e adiar. Toda tarefa carrega por que existe e
#    como comecar a conversa.
# 3. NADA DE LIGACAO COMO PRIMEIRO TOQUE, nada de audio pra quem nunca
#    respondeu. Numero desconhecido nao e atendido no interior, e audio nao
#    solicitado pra silencio total e o caminho mais curto pro bloqueio.

AGENDA_TETO_DIA = 25          # tarefas novas por consultor por dia
