@app.route('/proposta/<int:pid>')
@login_required
def ver_proposta(pid):
    conn = db()
    p = conn.execute("""SELECT p.*,s.nome as supervisora_nome,u.nome as vendedor_nome,u.perfil as vendedor_perfil
        FROM propostas p LEFT JOIN supervisoras s ON s.id=p.supervisora_id
        LEFT JOIN usuarios u ON u.id=p.usuario_id WHERE p.id=?""",(pid,)).fetchone()
    if not p: return "Não encontrada", 404
    if session['perfil'] != 'admin' and p['usuario_id'] != session['user_id']: return "Acesso negado", 403
    parcelas = conn.execute("SELECT * FROM parcelas WHERE proposta_id=? ORDER BY numero ASC",(pid,)).fetchall()
    # Lead correspondente no CRM. USA A CHAVE GRAVADA (propostas.lead_id) — o
    # comentário antigo dizia "propostas não tem lead_id" e readivinhava por
    # telefone a cada abertura da tela. Tem desde 29/07; readivinhar significa
    # mostrar um lead diferente do que está gravado se o telefone mudar.
    lead_crm = None
    _lid_prop = (p['lead_id'] if 'lead_id' in p.keys() else None)
    if _lid_prop:
        lead_crm = conn.execute(
            """SELECT id, nome, responsavel_id, etapa, sub_status, telefone, telefone_norm, criado_em
               FROM crm_leads WHERE id=?""", (_lid_prop,)).fetchone()
    if not lead_crm:
        for tel in (p['tel_resp_contrato'] if 'tel_resp_contrato' in p.keys() else None,
                    p['tel_resp_negociacao'] if 'tel_resp_negociacao' in p.keys() else None):
            tn = _normalizar_telefone(str(tel or ''))
            if tn:
                lead_crm = _buscar_lead_por_telefone(conn, tn)
                if lead_crm:
                    break
    # Identidade no WhatsApp desse lead: o @lid, que o Guilherme quer ver em TODO
    # lugar onde o lead aparece — não só na ficha do CRM.
    lead_wa = None
    if lead_crm:
        try:
            r = conn.execute("""SELECT chat_id FROM wa_chat_lead WHERE lead_id=?
                                ORDER BY atualizado_em DESC LIMIT 1""", (lead_crm['id'],)).fetchone()
            if r and r['chat_id']:
                cid = r['chat_id']
                lead_wa = {'chat_id': cid,
                           'tipo': 'lid' if '@lid' in cid else ('numero' if '@c.us' in cid else 'outro'),
                           'curto': cid.split('@')[0][:16] + ('…' if len(cid.split('@')[0]) > 16 else '')}
        except Exception:
            pass
    campos_def = conn.execute("SELECT * FROM campos_custom ORDER BY ordem,id").fetchall()
    # Operadora no editar = SELECT da lista única (não texto livre). Antes era
    # input de texto: dava pra digitar um nome que não existe na tabela de preço
    # e a comissão zerava. O valor atual entra na lista mesmo se for histórico,
    # pra a edição nunca apagar a operadora que já estava na proposta.
    op_lista = [o['display'] for o in _operadoras_lista(conn)]
    atual_op = ((p['adm_operadora'] if 'adm_operadora' in p.keys() else '') or '').strip()
    if atual_op and atual_op not in op_lista:
        op_lista = [atual_op] + op_lista
    # QUAL taxa produziu este numero. Sem isso, comissao errada vira misterio:
    # ninguem consegue dizer se o problema foi a operadora, o plano ou a promo.
    taxa_usada = None
    try:
        _c = _comissao_calculada(conn, p)
        if _c:
            taxa_usada = {'mens': _c.get('receb_mens') or _c.get('rep_mens'),
                          'operadora': _c.get('receb_operadora') or (p['adm_operadora'] or ''),
                          'plano': _c.get('plano') or '',
                          'tabela': _c.get('receb_tabela'), 'promo': _c.get('receb_promo')}
    except Exception:
        taxa_usada = None

    # A comissao gravada envelhece quando a venda e corrigida depois. Em vez de
    # esperar alguem abrir a lista de divergentes, a propria proposta avisa.
    # CALCULADO AQUI, antes do close_db — depois dele a consulta falha calada.
    try:
        _dv = comissao_divergente(conn, p)
        divergencia = _dv if (_dv and _dv['divergente']) else None
        if divergencia:
            divergencia['travas'] = _historico_travas(conn, p['id'])
    except Exception as _e:
        app.logger.warning(f"[DETALHE] divergencia nao calculada: {_e}")
        divergencia = None
    close_db(conn)
    campos_secoes = []
    for s in CAMPOS_EDIT_SECOES:
        campos = [({**c, 'tipo': 'select', 'opcoes': op_lista} if c['k'] == 'adm_operadora' else c)
                  for c in s['campos']]
        campos_secoes.append({**s, 'campos': campos})
    # Nome legível do modelo/regime aplicado
    cod = p['regime_aplicado'] or ''
    nome_regime = MODELO_NOME.get(cod, cod or '—')
    regime = {'nome': nome_regime}
    vendedor = {'nome': p['vendedor_nome'] or p['consultor'] or 'Não informado',
                'perfil': p['vendedor_perfil'] or ''}
    # Decodifica valores dos campos custom
    try:
        extras = json.loads(p['campos_extras']) if p['campos_extras'] else {}
    except: extras = {}
    extras_view = []
    for c in campos_def:
        if c['nome_tecnico'] in extras and extras[c['nome_tecnico']]:
            extras_view.append({'label': c['label'], 'valor': extras[c['nome_tecnico']]})
    # Valores atuais dos campos editáveis (para preencher o formulário de edição)
    valores_edit = {}
    for campo in CAMPOS_EDITAVEIS.keys():
        valores_edit[campo] = (p[campo] if campo in p.keys() else '') or ''

    # Solicitação de edição pendente (para o admin ver e aprovar/recusar)
    solic_pendente = None
    comissao_aviso = ''
    if session.get('perfil') == 'admin':
        sp = conn2 = db()
        row = conn2.execute("SELECT * FROM solicitacoes_edicao WHERE proposta_id=? AND status='Pendente' ORDER BY criado_em DESC LIMIT 1", (pid,)).fetchone()
        # Diagnóstico AO VIVO da comissão de consultor. Venda de sócio/gestor
        # não consulta Repasse: sua regra própria já está congelada na proposta.
        try:
            if (p['regime_aplicado'] or '') not in ('socio_gestor_regra', 'socio_gestor_pendente'):
                u = conn2.execute("SELECT regime_base FROM usuarios WHERE id=?", (p['usuario_id'],)).fetchone()
                prod = _producao_mes(conn2, p['usuario_id'], p['mes_meta'], excluir_pid=pid) + (p['valor'] or 0)
                cc = calc_comissao(p['adm_operadora'], (u['regime_base'] if u else '') or 'sem_lead_sem_fixo',
                                   prod, p['valor'] or 0, p['modalidade'],
                                   p['tipo_pessoa'] if 'tipo_pessoa' in p.keys() else '')
                comissao_aviso = cc.get('aviso') or ''
        except Exception:
            comissao_aviso = ''
        close_db(conn2)
        if row:
            solic_pendente = dict(row)
            try: solic_pendente['alteracoes_parsed'] = json.loads(row['alteracoes']) if row['alteracoes'] else {}
            except Exception: solic_pendente['alteracoes_parsed'] = {}

    # Regra do gestor desta venda: aparece na própria proposta, com a operadora e
    # o plano exatos e o link direto pra configuração que falta. Aviso genérico
    # ("configure as comissões") faz a pessoa procurar; este diz onde ir.
    conn3 = db()
    bloqueio_gestor = _gestor_bloqueio(conn3, pid)
    conta_gestor = None
    if bloqueio_gestor.get('eh_gestor') and not bloqueio_gestor['bloqueia']:
        conta_gestor = _gestor_calcular(_gestor_snapshot(conn3, pid),
                                        p.get('comissao_total_corretora') if isinstance(p, dict)
                                        else p['comissao_total_corretora'])
    pode_migrar_gestor = False
    motivo_migracao_gestor = ''
    if _gestor_e_vendedor(conn3, p['usuario_id']) and (p['regime_aplicado'] or '') not in (
            'socio_gestor_regra', 'socio_gestor_pendente'):
        travas_migracao = _historico_travas(conn3, pid)
        fora_da_fila = conn3.execute("""SELECT numero,status FROM parcelas WHERE proposta_id=?
                                       AND COALESCE(status,'') NOT IN
                                       ('Pendente de receber','Bloqueado - Falta Comprovante')
                                       ORDER BY numero LIMIT 1""", (pid,)).fetchone()
        plano_migracao = _plano_from_modalidade(p['modalidade'],
                                                p['tipo_pessoa'] if 'tipo_pessoa' in p.keys() else '')
        regra_migracao, ret_migracao = _gestor_regra_buscar(conn3, p['adm_operadora'] or '', plano_migracao)
        faltas_migracao = _gestor_regra_faltas(regra_migracao, ret_migracao)
        if travas_migracao:
            motivo_migracao_gestor = travas_migracao[0]
        elif fora_da_fila:
            motivo_migracao_gestor = f"Parcela {fora_da_fila['numero']} já saiu da fila inicial."
        elif faltas_migracao:
            motivo_migracao_gestor = faltas_migracao[0]
        else:
            pode_migrar_gestor = True
    close_db(conn3)
    # Os cartões sempre mostram a mesma fonte usada pelo fluxo financeiro. Para
    # gestor, não reutilizam as colunas legadas de "consultor" por conveniência.
    comissao_exibicao = {
        'recebimento': float(p['comissao_total_corretora'] or 0),
        'repasse': float(p['comissao_consultor'] or 0),
        'saldo_serenus': float(p['comissao_corretora_liquida'] or 0),
    }
    if conta_gestor and conta_gestor.get('completa'):
        comissao_exibicao = {
            'recebimento': conta_gestor['total_recebido'],
            'repasse': conta_gestor['total_liquido_gestor'],
            'saldo_serenus': conta_gestor['total_saldo_serenus'],
        }

    return render_template('detalhe.html', p=p, parcelas=parcelas, regime=regime, extras=extras_view,
                           divergencia=divergencia, taxa_usada=taxa_usada,
                           campos_secoes=campos_secoes, valores_edit=valores_edit,
                           solic_pendente=solic_pendente, comissao_aviso=comissao_aviso,
                           lead_crm=lead_crm, lead_wa=lead_wa,
                           bloqueio_gestor=bloqueio_gestor, conta_gestor=conta_gestor, vendedor=vendedor,
                           comissao_exibicao=comissao_exibicao,
                           pode_migrar_gestor=pode_migrar_gestor,
                           motivo_migracao_gestor=motivo_migracao_gestor,
                           etiquetas_sugeridas=_etiquetas_do_momento(p, lead_crm))


@app.route('/proposta/<int:pid>/migrar-regra-gestor', methods=['POST'])
@login_required
@admin_required
def migrar_regra_gestor_proposta(pid):
    """Migração manual e unitária de venda antiga de gestor para a régua nova."""
    conn = db()
    try:
        ok, msg = _migrar_venda_legada_para_gestor(conn, pid, session.get('nome') or 'Administrador')
        if not ok:
            conn.rollback()
            return jsonify({'ok': False, 'erro': msg}), 409
        conn.commit()
        return jsonify({'ok': True, 'msg': msg})
    except Exception:
        try: conn.rollback()
        except Exception: pass
        app.logger.exception('[REGRA-GESTOR] migração da proposta %s falhou', pid)
        return jsonify({'ok': False, 'erro': 'Não foi possível migrar esta venda. Nenhum valor foi alterado.'}), 500
    finally:
        close_db(conn)

@app.route('/proposta/<int:pid>/consultor', methods=['POST'])
@login_required
@admin_required
def editar_consultor(pid):
    """Remaneja a proposta para outro consultor e RECALCULA a comissão pelo regime dele.
    Só regenera as parcelas que ainda NÃO entraram no fluxo (Pendente de receber)."""
    novo_uid = request.form.get('usuario_id')
    conn = db()
    u = conn.execute("SELECT * FROM usuarios WHERE id=?", (novo_uid,)).fetchone()
    p = conn.execute("SELECT * FROM propostas WHERE id=?", (pid,)).fetchone()
    if not u or not p:
        close_db(conn); return jsonify({"ok": False, "msg": "Consultor ou proposta inválidos"}), 400

    # Produção do CICLO (mes_meta) do NOVO consultor (exceto esta proposta) + esta venda
    prod_antes = _producao_mes(conn, novo_uid, p['mes_meta'], excluir_pid=pid)
    prod_acumulada = prod_antes + (p['valor'] or 0)
    if _gestor_e_vendedor(conn, novo_uid):
        c = _gestor_calculo_inicial(conn, p['adm_operadora'], p['modalidade'],
                                    p['tipo_pessoa'] if 'tipo_pessoa' in p.keys() else '',
                                    p['valor'] or 0)
    else:
        c = calc_comissao(p['adm_operadora'], u['regime_base'], prod_acumulada,
                           p['valor'] or 0, p['modalidade'],
                           p['tipo_pessoa'] if 'tipo_pessoa' in p.keys() else '')

    conn.execute("""UPDATE propostas SET usuario_id=?, consultor=?, regime_aplicado=?,
        num_parcelas=?, distribuicao_parcelas=?, comissao_total_corretora=?, comissao_consultor=?,
        comissao_corretora_liquida=? WHERE id=?""",
        (novo_uid, u['nome'], c['codigo'], c['num_parcelas'], c['dist_corretora'],
         c['total_corretora'], c['consultor'], c['liquido'], pid))

    # Regenera apenas parcelas ainda "Pendente de receber"
    pagas = conn.execute("""SELECT COUNT(*) n FROM parcelas WHERE proposta_id=? AND status<>'Pendente de receber'""", (pid,)).fetchone()['n']
    if pagas == 0:
        conn.execute("DELETE FROM parcelas WHERE proposta_id=?", (pid,))
        gerador_parcelas = (gerar_parcelas_socio_gestor
                            if c.get('modelo') == 'socio_gestor_regra'
                            else gerar_parcelas)
        for parc in gerador_parcelas(pid, p['vigencia'] or '', c,
                                     p['dia_vencimento'] if 'dia_vencimento' in p.keys() else None):
            conn.execute("""INSERT INTO parcelas (proposta_id,numero,percentual,valor,valor_corretora,perc_cliente,data_prevista,status,competencia,mensalidade_ref,tipo_origem)
                VALUES (?,?,?,?,?,?,?,?,?,?,'comissao')""", (parc['proposta_id'],parc['numero'],parc['percentual'],
                    parc['valor'],parc['valor_corretora'],parc['perc_cliente'],parc['data_prevista'],parc['status'],
                    parc['competencia'],parc['mensalidade_ref']))
        if _gestor_e_vendedor(conn, novo_uid):
            _gestor_congelar_snapshot(conn, pid, p['adm_operadora'], c['plano'],
                                      novo_uid, u['nome'])
        msg = "Consultor remanejado e comissão recalculada."
    else:
        msg = "Consultor trocado. Parcelas já em fluxo foram mantidas; só novas seguem o novo regime."
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "msg": msg})

@app.route('/propostas/recalcular-todas', methods=['POST'])
@login_required
@admin_required
def recalcular_todas():
    """Recalcula a comissão de TODAS as propostas com o motor atual.
    Só regenera parcelas que ainda não entraram no fluxo. Retorna relatório de avisos."""
    conn = db()
    props = conn.execute("""SELECT p.*, u.regime_base, u.perfil FROM propostas p
        LEFT JOIN usuarios u ON u.id=p.usuario_id WHERE COALESCE(p.estornada,0)=0""").fetchall()
    recalc, avisos = 0, []
    for p in props:
        # Nunca passe uma venda de sócio/gestor pelo motor de consultor. Os
        # snapshots dessas vendas são imutáveis; recalcular tudo não pode
        # apagar a origem do acordo nem substituir suas parcelas.
        if (p['regime_aplicado'] or '') in ('socio_gestor_regra', 'socio_gestor_pendente'):
            avisos.append({'id': p['id'], 'cliente': p['razao_social'],
                           'operadora': p['adm_operadora'],
                           'aviso': 'Venda de sócio/gestor preservada: não é recalculada pelo motor de consultor.'})
            continue
        regime = p['regime_base'] or 'sem_lead_sem_fixo'
        prod_antes = _producao_mes(conn, p['usuario_id'], p['mes_meta'], excluir_pid=p['id'])
        prod_acum = prod_antes + (p['valor'] or 0)
        tp = p['tipo_pessoa'] if 'tipo_pessoa' in p.keys() else ''
        c = calc_comissao(p['adm_operadora'], regime, prod_acum, p['valor'] or 0, p['modalidade'], tp)
        conn.execute("""UPDATE propostas SET regime_aplicado=?, num_parcelas=?, distribuicao_parcelas=?,
            comissao_total_corretora=?, comissao_consultor=?, comissao_corretora_liquida=? WHERE id=?""",
            (c['codigo'], c['num_parcelas'], c['dist_corretora'],
             c['total_corretora'], c['consultor'], c['liquido'], p['id']))
        # Regenera só parcelas ainda pendentes de receber
        pagas = conn.execute("""SELECT COUNT(*) n FROM parcelas
            WHERE proposta_id=? AND status<>'Pendente de receber'""", (p['id'],)).fetchone()['n']
        if pagas == 0:
            conn.execute("DELETE FROM parcelas WHERE proposta_id=?", (p['id'],))
            for parc in gerar_parcelas(p['id'], p['vigencia'] or '', c,
                                       p['dia_vencimento'] if 'dia_vencimento' in p.keys() else None):
                conn.execute("""INSERT INTO parcelas (proposta_id,numero,percentual,valor,valor_corretora,perc_cliente,data_prevista,status,competencia,mensalidade_ref,tipo_origem)
                    VALUES (?,?,?,?,?,?,?,?,?,?,'comissao')""",
                    (parc['proposta_id'],parc['numero'],parc['percentual'],parc['valor'],
                     parc['valor_corretora'],parc['perc_cliente'],parc['data_prevista'],
                     parc['status'],parc['competencia'],parc['mensalidade_ref']))
        recalc += 1
        if c.get('aviso'):
            avisos.append({'id': p['id'], 'cliente': p['razao_social'],
                           'operadora': p['adm_operadora'], 'aviso': c['aviso']})
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "recalculadas": recalc, "avisos": avisos})


@app.route('/admin/comissoes-problemas')
@login_required
@admin_required
def comissoes_problemas():
    """Painel: lista as propostas ativas com comissão quebrada (bruto zero, líquido
    negativo ou falta de cadastro) dizendo EXATAMENTE o que falta em cada operadora,
    e um resumo dos cadastros faltantes agrupados. Read-only — não altera nada."""
    conn = db()
    props = conn.execute("""SELECT p.*, u.regime_base, u.perfil FROM propostas p
        LEFT JOIN usuarios u ON u.id=p.usuario_id
        WHERE COALESCE(p.estornada,0)=0 AND p.status<>'Excluída' ORDER BY p.id DESC""").fetchall()
    quebradas = []
    falta_receb, falta_rep = set(), set()
    for p in props:
        valor = p['valor'] or 0
        if valor <= 0:
            continue
        tp = p['tipo_pessoa'] if 'tipo_pessoa' in p.keys() else ''
        prod = _producao_mes(conn, p['usuario_id'], p['mes_meta'], excluir_pid=p['id']) + valor
        # A tela de diagnóstico não pode consultar o motor de consultor para
        # uma venda de gestor: isso criava um falso "falta repasse" e induzia
        # o usuário a cadastrar a regra no lugar errado.
        eh_gestor = (p['perfil'] or '') in _GESTOR_PERFIS
        if (p['regime_aplicado'] or '') in ('socio_gestor_regra', 'socio_gestor_pendente'):
            b = _gestor_bloqueio(conn, p['id'])
            aviso = ' · '.join(b['falta']) if b['bloqueia'] else ''
            cc = {'plano': b['plano'], 'liquido': p['comissao_corretora_liquida'] or 0,
                  'aviso': aviso}
        elif eh_gestor:
            plano = _plano_from_modalidade(p['modalidade'], tp)
            cc = {'plano': plano, 'liquido': p['comissao_corretora_liquida'] or 0,
                  'aviso': 'Venda de gestor ainda usa regime legado de consultor. Abra a proposta e revise a migração individual para a regra de sócio/gestor.'}
        else:
            cc = calc_comissao(p['adm_operadora'], (p['regime_base'] or 'sem_lead_sem_fixo'),
                               prod, valor, p['modalidade'], tp)
        aviso = cc.get('aviso') or ''
        if not aviso and (cc.get('liquido') or 0) >= 0:
            continue
        quebradas.append({'id': p['id'], 'cliente': p['razao_social'] or '—',
                          'operadora': p['adm_operadora'] or '—', 'plano': cc.get('plano', ''),
                          'valor': valor, 'aviso': aviso,
                          'liquido': cc.get('liquido') or 0})
        op = (p['adm_operadora'] or '').strip()
        if 'Falta RECEBIMENTO' in aviso:
            falta_receb.add(f"{op} · {cc.get('plano','')}")
        if 'Falta REPASSE' in aviso:
            falta_rep.add(f"{op} · {cc.get('plano','')}")
    close_db(conn)

    def _linhas():
        if not quebradas:
            return '<tr><td colspan="5" style="padding:24px;text-align:center;color:#16a34a;">Nenhuma proposta com comissão quebrada. Tudo certo.</td></tr>'
        out = []
        for q in quebradas:
            liq = f"R$ {q['liquido']:,.2f}".replace(',', 'X').replace('.', ',').replace('X', '.')
            out.append(
                f'<tr><td style="padding:10px 12px;"><a href="/proposta/{q["id"]}" style="color:#2563eb;">#{q["id"]}</a></td>'
                f'<td style="padding:10px 12px;">{q["cliente"]}</td>'
                f'<td style="padding:10px 12px;">{q["operadora"]} · {q["plano"]}</td>'
                f'<td style="padding:10px 12px;color:{"#dc2626" if q["liquido"]<0 else "#6b7280"};">{liq}</td>'
                f'<td style="padding:10px 12px;color:#b91c1c;font-size:12.5px;">{q["aviso"] or "líquido negativo"}</td></tr>')
        return ''.join(out)

    def _chips(s, label):
        if not s:
            return ''
        itens = ''.join(f'<li>{x}</li>' for x in sorted(s))
        return f'<div style="margin:10px 0;"><b>{label}:</b><ul style="margin:6px 0 0;padding-left:20px;">{itens}</ul></div>'

