# ═══════════════ DISPARO PARA CAMPANHAS (base própria) ═══════════════
#
# O motor irmão do disparo MEI, e a diferença que justifica ele existir: lá a
# lista é fria e ninguém tem dono, então a roleta reparte entre quem estiver
# apto. Aqui o público é a base da casa — gente que já tem consultor — e a
# mensagem sai pelo WhatsApp de quem já conversa com ela.
#
# A PLANILHA AQUI É UM FILTRO DA BASE, NÃO UMA LISTA NOVA. O admin monta no
# Excel os clientes que quer atingir (os da MedSênior, por exemplo), sobe, e o
# sistema casa cada telefone com o lead que já existe pra descobrir o dono. Quem
# não casar não vira contato solto: fica separado, esperando dono, e entra
# sozinho quando alguém assumir.
#
# As colunas extras da planilha viram variáveis da mensagem. É o que faz uma
# campanha de operadora soar como conversa ("seu plano de {mensalidade} reajusta
# em {vencimento}") em vez de mala direta.

_DISPARO_ORIGEM = 'disparo_base'          # como o item aparece na fila de envio

# Cabeçalhos que a gente reconhece sozinho. O admin não devia ter que aprender o
# nome que o sistema quer — ele exporta do lugar de onde exportou e sobe.
_DISPARO_COL_TEL = ('telefone', 'celular', 'whatsapp', 'fone', 'tel', 'contato', 'numero')
_DISPARO_COL_NOME = ('nome', 'cliente', 'titular', 'razao_social', 'razao', 'beneficiario')


def _disparo_slug(txt):
    """Cabeçalho da planilha -> nome de variável. 'Valor da Mensalidade' vira
    'valor_da_mensalidade', que é o que se escreve entre chaves na mensagem."""
    import unicodedata as _u, re as _re
    t = _u.normalize('NFKD', str(txt or '')).encode('ascii', 'ignore').decode('ascii')
    t = _re.sub(r'[^a-zA-Z0-9]+', '_', t).strip('_').lower()
    return t


def _disparo_parse_planilha(fs):
    """Lê a planilha do admin COM CABEÇALHO e devolve (contatos, colunas).

    Diferente do parser do MEI, que adivinha coluna por formato: aqui o
    cabeçalho importa, porque é ele que vira o nome da variável usada na
    mensagem. Acha o telefone pelo nome da coluna e, se não achar, pela coluna
    que mais parece telefone — planilha de operadora vem com cabeçalho torto e
    recusar o arquivo inteiro por causa disso seria empurrar trabalho pro admin.
    """
    if not fs or not getattr(fs, 'filename', ''):
        return [], []
    nome_arq = (getattr(fs, 'filename', '') or '').lower()
    linhas = []
    try:
        if nome_arq.endswith('.xlsx') or nome_arq.endswith('.xlsm'):
            import openpyxl, io as _io
            wb = openpyxl.load_workbook(_io.BytesIO(fs.read()), read_only=True, data_only=True)
            for row in wb.active.iter_rows(values_only=True):
                linhas.append(['' if c is None else str(c).strip() for c in row])
        else:
            import csv as _csv, io as _io
            dados = fs.read().decode('utf-8', errors='ignore')
            amostra = dados[:2000]
            sep = ';' if amostra.count(';') > amostra.count(',') else ','
            for row in _csv.reader(_io.StringIO(dados), delimiter=sep):
                linhas.append([(c or '').strip() for c in row])
    except Exception:
        return [], []
    linhas = [l for l in linhas if any((c or '').strip() for c in l)]
    if len(linhas) < 2:
        return [], []   # só cabeçalho (ou nada) não é lista

    cab = [_disparo_slug(c) for c in linhas[0]]
    # nomeia coluna sem cabeçalho pra não sumir com o dado
    cab = [c if c else f'coluna_{i + 1}' for i, c in enumerate(cab)]
    corpo = linhas[1:]

    def _acha(cands):
        for i, c in enumerate(cab):
            if any(c == k or c.startswith(k + '_') or k in c.split('_') for k in cands):
                return i
        return -1

    i_tel = _acha(_DISPARO_COL_TEL)
    if i_tel < 0:
        # sem cabeçalho reconhecível: a coluna que mais parece telefone ganha
        import re as _re
        melhor, placar = -1, 0
        for i in range(len(cab)):
            n = sum(1 for l in corpo if i < len(l) and len(_re.sub(r'\D', '', l[i] or '')) >= 10)
            if n > placar:
                melhor, placar = i, n
        i_tel = melhor
    if i_tel < 0:
        return [], cab
    i_nome = _acha(_DISPARO_COL_NOME)

    contatos = []
    for l in corpo:
        val = lambda i: (l[i] if 0 <= i < len(l) else '') or ''
        tel = val(i_tel)
        norm = _normalizar_telefone(tel)
        if not norm:
            continue   # linha sem telefone válido não tem como ser disparada
        variaveis = {}
        for i, chave in enumerate(cab):
            if i == i_tel:
                continue
            v = val(i).strip()
            if v:
                variaveis[chave] = v
        contatos.append({'nome': val(i_nome).strip(), 'telefone': tel.strip(),
                         'telefone_norm': norm, 'variaveis': variaveis})
    return contatos, cab


def _disparo_dono(conn, tel_norm, publico='leads'):
    """Quem fala com essa pessoa hoje. Devolve (lead_id, consultor_id).

    O consultor precisa estar ATIVO: dono desligado é o mesmo que não ter dono —
    a mensagem sairia por um WhatsApp que ninguém abre. São 356 leads nessa
    situação hoje, e eles vão pra fila de quem precisa de dono, não pro disparo.

    Em campanha de VENDAS o dono é quem vendeu (propostas.usuario_id), não quem
    captou o lead: é com o vendedor que o cliente falou por último.
    """
    if not tel_norm:
        return None, None
    lead = conn.execute("""SELECT id, responsavel_id FROM crm_leads
        WHERE telefone_norm=? ORDER BY (responsavel_id IS NULL), id DESC LIMIT 1""",
        (tel_norm,)).fetchone()
    if not lead:
        return None, None
    dono = lead['responsavel_id']
    if publico == 'vendas':
        pr = conn.execute("""SELECT usuario_id FROM propostas
            WHERE lead_id=? AND COALESCE(status,'Ativo')<>'Cancelado'
            ORDER BY id DESC LIMIT 1""", (lead['id'],)).fetchone()
        if pr and pr['usuario_id']:
            dono = pr['usuario_id']
    if dono and not conn.execute("SELECT 1 FROM usuarios WHERE id=? AND ativo=1", (dono,)).fetchone():
        dono = None
    return lead['id'], dono


def _disparo_bloqueado(conn, tel_norm):
    """True se esse telefone pediu pra nunca mais receber campanha."""
    if not tel_norm:
        return False
    try:
        return bool(conn.execute("SELECT 1 FROM disparo_bloqueio WHERE telefone_norm=?",
                                 (tel_norm,)).fetchone())
    except Exception:
        return False


def _disparo_importar(conn, campanha_id, contatos, publico='leads'):
    """Põe os contatos da planilha na campanha, cada um já com dono resolvido.

    Devolve o resumo do que aconteceu com CADA linha — é o que a tela mostra
    depois. Subir uma planilha e ver só "300 importados" esconde que 120 não
    casaram com ninguém; o admin precisa ver os quatro destinos.
    """
    import json as _json
    resumo = {'total': 0, 'com_dono': 0, 'sem_dono': 0, 'sem_lead': 0,
              'bloqueado': 0, 'duplicado': 0}
    vistos = set()
    for c in contatos:
        norm = c.get('telefone_norm') or ''
        if not norm:
            continue
        resumo['total'] += 1
        if norm in vistos:
            resumo['duplicado'] += 1
            continue
        vistos.add(norm)
        if _disparo_bloqueado(conn, norm):
            resumo['bloqueado'] += 1
            continue
        lead_id, dono = _disparo_dono(conn, norm, publico)
        if not lead_id:
            status = 'sem_lead'      # a planilha trouxe alguém que não está na base
        elif not dono:
            status = 'sem_dono'
        else:
            status = 'pendente'
        resumo['com_dono' if status == 'pendente' else status] += 1
        try:
            conn.execute("""INSERT INTO disparo_campanha_alvo
                (campanha_id, lead_id, consultor_id, nome, telefone, telefone_norm,
                 variaveis_json, status, criado_em) VALUES (?,?,?,?,?,?,?,?,?)""",
                (campanha_id, lead_id, dono, c.get('nome') or '', c.get('telefone') or norm, norm,
                 _json.dumps(c.get('variaveis') or {}, ensure_ascii=False), status, _agora_sp()))
        except Exception:
            # Bateu no UNIQUE(campanha_id, telefone_norm): o mesmo número já está
            # nesta campanha. É a trava funcionando, não erro.
            resumo['duplicado'] += 1
            resumo[('com_dono' if status == 'pendente' else status)] -= 1
            if DB_MODE == 'postgres':
                try: conn.rollback()
                except Exception: pass
    return resumo


def _disparo_reprocessar_sem_dono(conn, campanha_id):
    """Tenta de novo achar dono pros que estavam órfãos. Roda quando o admin
    atribui leads em massa — sem isto, o trabalho de atribuir não teria efeito
    nenhum e a planilha teria que ser subida de novo."""
    camp = conn.execute("SELECT publico FROM disparo_campanha WHERE id=?", (campanha_id,)).fetchone()
    pub = (camp['publico'] if camp else 'leads') or 'leads'
    n = 0
    for a in conn.execute("""SELECT id, telefone_norm FROM disparo_campanha_alvo
        WHERE campanha_id=? AND status IN ('sem_dono','sem_lead')""", (campanha_id,)).fetchall():
        lead_id, dono = _disparo_dono(conn, a['telefone_norm'], pub)
        if lead_id and dono:
            conn.execute("""UPDATE disparo_campanha_alvo SET lead_id=?, consultor_id=?, status='pendente'
                WHERE id=?""", (lead_id, dono, a['id']))
            n += 1
        elif lead_id:
            conn.execute("UPDATE disparo_campanha_alvo SET lead_id=?, status='sem_dono' WHERE id=?",
                         (lead_id, a['id']))
    return n


def _disparo_janela_aberta(camp, agora=None):
    """A campanha pode disparar AGORA? Dia da semana e faixa de horário, os dois
    configuráveis por campanha. Devolve (pode, motivo) — o motivo vai pra tela,
    porque "não saiu nada" sem explicação é o que faz o admin achar que quebrou.
    """
    a = agora or datetime.now(TZ_SP)
    dias = str((camp['dias_semana'] if 'dias_semana' in camp.keys() else '') or '1,2,3,4,5')
    permitidos = {d.strip() for d in dias.split(',') if d.strip()}
    hoje = str(a.isoweekday())          # 1=segunda ... 7=domingo
    if permitidos and hoje not in permitidos:
        return False, 'Hoje não é dia de disparo desta campanha.'
    ini = str((camp['hora_inicio'] if 'hora_inicio' in camp.keys() else '') or '08:00')
    fim = str((camp['hora_fim'] if 'hora_fim' in camp.keys() else '') or '18:00')
    agora_hm = a.strftime('%H:%M')
    if not (ini <= agora_hm < fim):
        return False, f'Fora da janela desta campanha ({ini} às {fim}).'
    return True, ''


def _disparo_modelo_do_consultor(conn, campanha_id, consultor_id):
    """Um modelo DELE, sorteado. Nada de texto padrão: se o consultor não tem
    modelo nesta campanha, o alvo para e aparece na tela pedindo modelo. Inventar
    um texto seria mandar, em nome dele, palavra que ele nunca escreveu."""
    import random as _rnd
    rows = conn.execute("""SELECT m.id, m.corpo_texto, m.midia_arquivo, m.midia_tipo
        FROM disparo_campanha_modelo dm JOIN modelos_conteudo m ON m.id=dm.modelo_id
        WHERE dm.campanha_id=? AND dm.consultor_id=? AND COALESCE(m.ativo,1)=1""",
        (campanha_id, consultor_id)).fetchall()
    rows = [r for r in rows if (r['corpo_texto'] or '').strip()]
    return dict(_rnd.choice(rows)) if rows else None


def _disparo_variaveis_fixas(conn, campanha_id):
    """As variáveis criadas no JOB pra esta campanha. Valem pra todo mundo da
    lista — é o que evita repetir a mesma informação em 300 linhas de planilha."""
    import json as _json
    try:
        r = conn.execute("SELECT variaveis_fixas FROM disparo_campanha WHERE id=?", (campanha_id,)).fetchone()
        return _json.loads((r['variaveis_fixas'] if r else '') or '{}') or {}
    except Exception:
        return {}


# NOMES QUE O SISTEMA JÁ RESOLVE. Criar uma variável fixa com um destes seria
# ou inútil ({nome} já é trocado antes) ou perigoso: {consultor} fixo assinaria
# a mensagem da Karen com o nome do Guilherme, porque a campanha sai por VÁRIOS
# consultores. Quem tenta é barrado com o motivo.
_DISPARO_VARS_SISTEMA = {
    'nome': 'o primeiro nome de quem recebe, tirado do CRM',
    'saudacao': 'Bom dia / Boa tarde / Boa noite, pela hora real do envio',
    'consultor': 'o primeiro nome de QUEM ESTÁ MANDANDO — muda por consultor',
    'consultor_completo': 'o nome completo de quem está mandando',
    # Link cravado no texto manda TODO MUNDO pro mesmo WhatsApp, mesmo quando a
    # campanha sai por sete pessoas. Estas duas resolvem pelo número de quem
    # está mandando — e são o que faz SMS e e-mail terem pra onde voltar.
    'consultor_whatsapp': 'o número de WhatsApp de quem está mandando',
    'consultor_link': 'o link wa.me pro WhatsApp de quem está mandando',
}


def _disparo_texto(conn, alvo, modelo, agora=None, fixas=None, consultor=None, fone_consultor=None):
    """Monta a mensagem: {nome} e {saudacao} como no resto do sistema, mais as
    colunas da planilha entre chaves. Devolve (texto, faltando).

    `faltando` existe porque mandar "seu plano de {mensalidade}" com a chave
    crua na tela do cliente é pior do que não mandar. Alvo com variável faltando
    não sai — ele aparece na tela dizendo qual coluna faltou.
    """
    import json as _json, re as _re
    # O nome vem da planilha; se ela não trouxe coluna de nome, o CRM sabe quem
    # é. Sem esta volta, uma planilha só de telefones mandaria "Oi tudo bem?"
    # pra gente que a Serenus conhece pelo nome há dois anos.
    quem = (alvo['nome'] or '').strip()
    if not quem and alvo['lead_id']:
        try:
            _l = conn.execute("SELECT nome FROM crm_leads WHERE id=?", (alvo['lead_id'],)).fetchone()
            quem = (_l['nome'] or '').strip() if _l else ''
        except Exception:
            quem = ''
    txt = _preencher_texto((modelo or {}).get('corpo_texto') or '', quem, agora)
    try:
        variaveis = _json.loads(alvo['variaveis_json'] or '{}')
    except Exception:
        variaveis = {}
    # PRECEDÊNCIA, do mais geral pro mais específico: o que o sistema resolve
    # perde pra fixa da campanha, que perde pra coluna da linha. O valor mais
    # específico sobre aquela pessoa é sempre o que vale.
    juntas = {}
    if consultor:
        primeiro = (consultor or '').strip().split(' ')[0]
        juntas['consultor'] = _nome_pra_pessoa(primeiro) or primeiro
        juntas['consultor_completo'] = consultor
    if fone_consultor:
        _f = _waspeed_normaliza_fone(fone_consultor)
        if _f:
            # (19) 98318-9498 — como se escreve pra gente ler, não 5519983189498.
            _n = _f[2:] if _f.startswith('55') else _f
            juntas['consultor_whatsapp'] = (f'({_n[:2]}) {_n[2:-4]}-{_n[-4:]}' if len(_n) in (10, 11) else _f)
            juntas['consultor_link'] = 'wa.me/' + _f
    juntas.update(fixas or {})
    juntas.update(variaveis or {})
    for chave, valor in juntas.items():
        txt = txt.replace('{' + chave + '}', str(valor))
    faltando = sorted(set(_re.findall(r'\{([a-z0-9_]+)\}', txt)))
    return txt, faltando


def _disparo_etiqueta_id(conn, nome, cor='#3b82f6'):
    """Acha ou cria a etiqueta do CRM com esse nome. Idempotente — a campanha
    chama isto toda vez e nunca duplica."""
    nome = (nome or '').strip()[:60]
    if not nome:
        return None
    r = conn.execute("SELECT id FROM crm_etiquetas WHERE nome=?", (nome,)).fetchone()
    if r:
        return r['id']
    try:
        conn.execute("INSERT INTO crm_etiquetas (nome, cor, ordem, ativo) VALUES (?,?,?,1)", (nome, cor, 90))
    except Exception:
        if DB_MODE == 'postgres':
            try: conn.rollback()
            except Exception: pass
    r = conn.execute("SELECT id FROM crm_etiquetas WHERE nome=?", (nome,)).fetchone()
    return r['id'] if r else None


def _disparo_etiquetar(conn, lead_id, etiqueta_id):
    """Cola a etiqueta no lead. A de participação NUNCA é retirada: daqui a três
    meses ela é a única resposta pra 'quem recebeu a campanha de setembro?'."""
    if not (lead_id and etiqueta_id):
        return False
    try:
        conn.execute("INSERT INTO crm_lead_etiquetas (lead_id, etiqueta_id, criado_em) VALUES (?,?,?)",
                     (lead_id, etiqueta_id, _agora_sp()))
        return True
    except Exception:
        # Já tinha a etiqueta (PK composta). Não é erro.
        if DB_MODE == 'postgres':
            try: conn.rollback()
            except Exception: pass
        return False


def _disparo_nota(conn, lead_id, texto, autor='Campanha'):
    """Escreve no histórico do lead — o mesmo lugar que a extensão e o site já
    mostram. Duas notas por alvo: uma quando recebe, outra quando responde. Sem
    as duas datas não existe 'quanto tempo levou pra responder', que é o número
    que diz se a campanha funcionou."""
    if not lead_id:
        return
    try:
        conn.execute("""INSERT INTO crm_atividades (lead_id, usuario_nome, tipo, descricao, criado_em)
            VALUES (?,?,?,?,?)""", (lead_id, autor, 'whatsapp', (texto or '')[:600], _agora_sp()))
    except Exception:
        if DB_MODE == 'postgres':
            try: conn.rollback()
            except Exception: pass


def _disparo_decorrido(de, ate=None):
    """'3 h 12 min' / '25 min'. Texto pra humano, não segundos pra máquina."""
    ini, fim = _parse_dt_seguro(de), (_parse_dt_seguro(ate) if ate else datetime.now(TZ_SP))
    if not ini or not fim:
        return ''
    if ini.tzinfo is None:
        ini = TZ_SP.localize(ini)
    if fim.tzinfo is None:
        fim = TZ_SP.localize(fim)
    seg = int((fim - ini).total_seconds())
    if seg < 60:
        return 'menos de 1 min'
    if seg < 3600:
        return f'{seg // 60} min'
    if seg < 86400:
        h, m = seg // 3600, (seg % 3600) // 60
        return f'{h} h' + (f' {m} min' if m else '')
    d = seg // 86400
    return f'{d} dia' + ('s' if d > 1 else '')


# ─── COSTURA DE CANAIS: SMS e e-mail depois do WhatsApp ───────────────────
#
# O WhatsApp depende do consultor estar com a aba aberta. SMS e e-mail saem DO
# SERVIDOR — chegam mesmo com todo mundo de WhatsApp fechado, que é justamente
# o buraco medido nesta semana (4 de 7 consultores fora do ar às 11h).
#
# A regra que faz isso ser costura e não spam: cada passo só pega quem NÃO
# respondeu. Quem respondeu saiu da campanha, e o atendimento é do consultor.

_DISPARO_SMS_TETO = int(os.environ.get('DISPARO_SMS_TETO_DIA', '300'))   # SMS custa por envio


def _disparo_canais_rotulo(canal):
    return {'whatsapp': 'WhatsApp', 'sms': 'SMS', 'email': 'E-mail'}.get(canal, canal)


def _disparo_passos(conn, campanha_id):
    """Os passos da campanha, em ordem. Sem passo cadastrado, o comportamento é
    o de sempre: um único envio por WhatsApp, no dia zero."""
    try:
        rows = conn.execute("""SELECT * FROM disparo_campanha_passo
            WHERE campanha_id=? AND COALESCE(ativo,1)=1 ORDER BY ordem, id""", (campanha_id,)).fetchall()
    except Exception:
        return []
    return [dict(r) for r in rows]


def _disparo_email_do_alvo(conn, alvo):
    """O e-mail de quem vai receber: da planilha, se veio; senão do CRM."""
    import json as _json
    try:
        v = _json.loads(alvo['variaveis_json'] or '{}') or {}
    except Exception:
        v = {}
    for chave in ('email', 'e_mail', 'e_mail_1', 'email_1'):
        if v.get(chave) and '@' in str(v[chave]):
            return str(v[chave]).strip()
    if alvo['lead_id']:
        try:
            r = conn.execute("SELECT email FROM crm_leads WHERE id=?", (alvo['lead_id'],)).fetchone()
            if r and r['email'] and '@' in r['email']:
                return r['email'].strip()
        except Exception:
            pass
    return ''


def _disparo_rodar_passos(conn=None, agora=None, so_campanha=None):
    """Manda os passos de SMS e e-mail que já venceram a espera.

    Roda no servidor, de tempos em tempos. Para cada campanha ativa, cada passo
    que não seja WhatsApp: pega quem RECEBEU o WhatsApp há tempo suficiente, não
    respondeu, não está bloqueado, e ainda não recebeu ESTE passo.

    Devolve o resumo — e nunca estoura: um erro num contato não pode parar a
    varredura dos outros.
    """
    fechar = conn is None
    if conn is None:
        try:
            conn = db()
        except Exception:
            return {'enviados': 0, 'erro': 'sem banco'}
    agora = agora or datetime.now(TZ_SP)
    resumo = {'sms': 0, 'email': 0, 'falhas': 0, 'pulados': 0}
    try:
        q = "SELECT * FROM disparo_campanha WHERE status='ativa'"
        args = ()
        if so_campanha:
            q += " AND id=?"; args = (so_campanha,)
        campanhas = [dict(c) for c in conn.execute(q, args).fetchall()]
    except Exception:
        if fechar: close_db(conn)
        return resumo

    sms_hoje = 0
    for camp in campanhas:
        pode, _motivo = _disparo_janela_aberta(camp, agora)
        if not pode:
            continue
        fixas = _disparo_variaveis_fixas(conn, camp['id'])
        nomes = {r['id']: r['nome'] for r in conn.execute("SELECT id, nome FROM usuarios WHERE ativo=1").fetchall()}
        try:
            fones = {r['usuario_id']: r['numero'] for r in
                     conn.execute("SELECT usuario_id, numero FROM consultor_wpp_status").fetchall()}
        except Exception:
            fones = {}
        for passo in _disparo_passos(conn, camp['id']):
            if passo['canal'] == 'whatsapp':
                continue      # WhatsApp sai pela fila da extensão, não daqui
            corte = (agora - timedelta(days=int(passo['apos_dias'] or 0))).strftime('%Y-%m-%d %H:%M:%S')
            alvos = conn.execute("""SELECT a.* FROM disparo_campanha_alvo a
                WHERE a.campanha_id=? AND a.status='enviado' AND a.respondeu_em IS NULL
                  AND a.enviado_em IS NOT NULL AND CAST(a.enviado_em AS TEXT) <= ?
                  AND NOT EXISTS (SELECT 1 FROM disparo_campanha_envio e
                                  WHERE e.alvo_id=a.id AND e.passo_id=?)
                ORDER BY a.id LIMIT 400""", (camp['id'], corte, passo['id'])).fetchall()
            for alvo in [dict(a) for a in alvos]:
                if _disparo_bloqueado(conn, alvo['telefone_norm']):
                    resumo['pulados'] += 1
                    continue
                modelo = {'corpo_texto': passo['texto'] or ''}
                texto, faltando = _disparo_texto(conn, alvo, modelo, agora, fixas,
                                                 nomes.get(alvo['consultor_id']),
                                                 fones.get(alvo['consultor_id']))
                if faltando:
                    resumo['pulados'] += 1
                    continue
                if passo['canal'] == 'sms':
                    if sms_hoje >= _DISPARO_SMS_TETO:
                        resumo['pulados'] += 1
                        continue
                    destino = alvo['telefone_norm'] or alvo['telefone']
                    ok, erro = _enviar_sms(destino, texto)
                    sms_hoje += 1
                    resumo['sms' if ok else 'falhas'] += 1
                else:
                    destino = _disparo_email_do_alvo(conn, alvo)
                    if not destino:
                        resumo['pulados'] += 1
                        # registra pra não tentar de novo toda varredura
                        _disparo_registrar_envio(conn, alvo['id'], passo, '', texto, False, 'sem e-mail')
                        continue
                    assunto, _f2 = _disparo_texto(conn, alvo, {'corpo_texto': passo['assunto'] or ''},
                                                  agora, fixas, nomes.get(alvo['consultor_id']),
                                                  fones.get(alvo['consultor_id']))
                    corpo = '<div style="font-family:Arial,sans-serif;font-size:15px;line-height:1.6;color:#222;">' \
                            + texto.replace('\n', '<br>') + '</div>'
                    ok, erro = _enviar_email(destino, assunto or 'Mensagem da Serenus', corpo,
                                             remetente_nome='Serenus Corretora', sincrono=True)
                    resumo['email' if ok else 'falhas'] += 1
                _disparo_registrar_envio(conn, alvo['id'], passo, destino, texto, ok, erro)
                if ok:
                    _disparo_nota(conn, alvo['lead_id'],
                                  f"{_disparo_canais_rotulo(passo['canal'])} da campanha \"{camp['nome']}\": {texto[:200]}")
        conn.commit()
    if fechar:
        close_db(conn)
    return resumo


def _disparo_registrar_envio(conn, alvo_id, passo, destino, texto, ok, erro):
    """Um registro por (alvo, passo). O UNIQUE é o que impede mandar o mesmo SMS
    duas vezes quando a varredura roda de novo — e SMS mandado duas vezes é
    dinheiro gasto e cliente irritado."""
    try:
        conn.execute("""INSERT INTO disparo_campanha_envio
            (alvo_id, passo_id, canal, destino, texto, ok, erro, criado_em)
            VALUES (?,?,?,?,?,?,?,?)""",
            (alvo_id, passo['id'], passo['canal'], (destino or '')[:120], (texto or '')[:600],
             1 if ok else 0, (erro or '')[:200] or None, _agora_sp()))
    except Exception:
        if DB_MODE == 'postgres':
            try: conn.rollback()
            except Exception: pass


def _disparo_enfileirar(conn, campanha_id, agora=None):
    """Empurra pra fila da extensão o que pode sair agora, por consultor.

    O ritmo não é escolha estética: teto por dia (aquecimento), janela de
    horário, e o gate da própria fila entre um envio e outro. Consultor inapto
    (WhatsApp fechado) não recebe nada na fila — os alvos dele esperam ele
    voltar, e não passam pra outro. A mensagem tem que sair por quem o cliente
    conhece; se esse alguém não está, ela espera.
    """
    agora = agora or datetime.now(TZ_SP)
    camp = conn.execute("SELECT * FROM disparo_campanha WHERE id=?", (campanha_id,)).fetchone()
    if not camp:
        return {'enfileirados': 0, 'motivo': 'Campanha não encontrada.'}
    if camp['status'] != 'ativa':
        return {'enfileirados': 0, 'motivo': 'A campanha não está ativa.'}
    pode, motivo = _disparo_janela_aberta(camp, agora)
    if not pode:
        return {'enfileirados': 0, 'motivo': motivo}

    fixas = _disparo_variaveis_fixas(conn, campanha_id)
    # Nome de cada consultor, pra {consultor} sair certo em cada envio.
    nomes_cons = {r['id']: r['nome'] for r in
                  conn.execute("SELECT id, nome FROM usuarios WHERE ativo=1").fetchall()}
    # O WhatsApp de cada um, pro {consultor_link} apontar pra pessoa certa.
    try:
        fones_cons = {r['usuario_id']: r['numero'] for r in
                      conn.execute("SELECT usuario_id, numero FROM consultor_wpp_status").fetchall()}
    except Exception:
        fones_cons = {}
    aptos = {p['id'] for p in _consultores_presenca(conn) if p['apto']}
    teto = max(1, int(camp['teto_dia'] or 10))
    hoje = agora.strftime('%Y-%m-%d')
    n, sem_modelo, inaptos, sem_variavel = 0, set(), set(), 0

    donos = [r['consultor_id'] for r in conn.execute("""SELECT DISTINCT consultor_id
        FROM disparo_campanha_alvo WHERE campanha_id=? AND status='pendente'
          AND consultor_id IS NOT NULL""", (campanha_id,)).fetchall()]
    for cid in donos:
        if cid not in aptos:
            inaptos.add(cid)
            continue
        ja_hoje = conn.execute("""SELECT COUNT(*) q FROM disparo_campanha_alvo
            WHERE campanha_id=? AND consultor_id=? AND enviado_em IS NOT NULL
              AND substr(CAST(enviado_em AS TEXT),1,10)=?""", (campanha_id, cid, hoje)).fetchone()['q']
        na_fila = conn.execute("""SELECT COUNT(*) q FROM disparo_campanha_alvo a
            JOIN whatsapp_extensao_fila f ON f.id=a.fila_id
            WHERE a.campanha_id=? AND a.consultor_id=? AND a.status='enfileirado'
              AND f.status IN ('pendente','enviando')""", (campanha_id, cid)).fetchone()['q']
        resta = teto - ja_hoje - na_fila
        if resta <= 0:
            continue
        alvos = conn.execute("""SELECT * FROM disparo_campanha_alvo
            WHERE campanha_id=? AND consultor_id=? AND status='pendente' ORDER BY id LIMIT ?""",
            (campanha_id, cid, resta)).fetchall()
        for alvo in alvos:
            modelo = _disparo_modelo_do_consultor(conn, campanha_id, cid)
            if not modelo:
                sem_modelo.add(cid)
                break   # sem modelo dele, nenhum alvo dele sai
            if _disparo_bloqueado(conn, alvo['telefone_norm']):
                conn.execute("UPDATE disparo_campanha_alvo SET status='bloqueado' WHERE id=?", (alvo['id'],))
                continue
            chat_id = _wa_chat_id(alvo['telefone_norm'] or alvo['telefone'] or '')
            if not chat_id:
                conn.execute("UPDATE disparo_campanha_alvo SET status='invalido' WHERE id=?", (alvo['id'],))
                continue
            texto, faltando = _disparo_texto(conn, alvo, modelo, agora, fixas,
                                             nomes_cons.get(cid), fones_cons.get(cid))
            if faltando:
                # "faltou na planilha" mentiria agora: a variável também pode vir
                # das fixas criadas no JOB. O que falta é VALOR, venha de onde vier.
                conn.execute("UPDATE disparo_campanha_alvo SET status='sem_variavel', texto_enviado=? WHERE id=?",
                             (('sem valor: ' + ', '.join(faltando))[:300], alvo['id']))
                sem_variavel += 1
                continue
            tipo = modelo.get('midia_tipo') if modelo.get('midia_tipo') in ('audio', 'imagem', 'video', 'documento') else 'texto'
            # pos_acao viaja COM o item: quem arquiva é a extensão, com a conversa
            # na mão, logo depois de confirmar o envio.
            pos_acao = 'arquivar' if int(camp['arquivar'] if 'arquivar' in camp.keys() and camp['arquivar'] is not None else 1) else None
            conn.execute("""INSERT INTO whatsapp_extensao_fila
                (lead_id, responsavel_id, telefone, chat_id, tipo, texto, midia_arquivo,
                 origem, criado_por, criado_em, pos_acao) VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
                (alvo['lead_id'], cid, alvo['telefone'] or alvo['telefone_norm'], chat_id, tipo, texto,
                 (modelo.get('midia_arquivo') if tipo != 'texto' else None),
                 _DISPARO_ORIGEM, cid, _agora_sp(), pos_acao))
            fila_id = (conn.execute("SELECT lastval() AS id").fetchone()['id'] if DB_MODE == 'postgres'
                       else conn.execute("SELECT last_insert_rowid() id").fetchone()['id'])
            conn.execute("""UPDATE disparo_campanha_alvo
                SET status='enfileirado', fila_id=?, modelo_id=?, texto_enviado=? WHERE id=?""",
                (fila_id, modelo.get('id'), texto[:500], alvo['id']))
            n += 1
    conn.commit()
    nomes = lambda ids: [r['nome'] for r in conn.execute(
        f"SELECT nome FROM usuarios WHERE id IN ({','.join(['?'] * len(ids))})", tuple(ids)).fetchall()] if ids else []
    return {'enfileirados': n, 'motivo': '', 'sem_modelo': nomes(list(sem_modelo)),
            'inaptos': nomes(list(inaptos)), 'sem_variavel': sem_variavel}


def _disparo_enfileirar_automatico(conn=None, agora=None):
    """Empurra sozinho o que pode sair agora, de TODA campanha ativa.

    Sem isto a campanha era um botão, não um motor: o Guilherme ligava a
    campanha e ela ficava muda até alguém abrir a tela e clicar em
    "enfileirar". Foi exatamente o que aconteceu com a MEDSÊNIOR — ativa às
    11:41, 43 alvos, zero mensagens três horas depois. "Ativa" tem que
    significar andando.

    Roda no scheduler E por request (o APScheduler morre em restart), e o
    próprio `_disparo_enfileirar` já é a trava: teto do dia, janela de
    horário, consultor apto e o que já está na fila. Chamar de novo fora de
    hora não manda nada — só volta com o motivo.
    """
    prop = conn is None
    conn = conn or db()
    total, tocadas = 0, 0
    try:
        ativas = [r['id'] for r in conn.execute(
            "SELECT id FROM disparo_campanha WHERE status='ativa' ORDER BY id").fetchall()]
        for cid in ativas:
            try:
                r = _disparo_enfileirar(conn, cid, agora)
            except Exception as e:
                app.logger.warning(f"[DISPARO_AUTO] campanha {cid} falhou: {e}")
                continue
            n = int(r.get('enfileirados') or 0)
            total += n
            if n:
                tocadas += 1
        if total:
            app.logger.info(f"[DISPARO_AUTO] {total} na fila, {tocadas} campanha(s)")
    finally:
        if prop:
            close_db(conn)
    return {'enfileirados': total, 'campanhas': tocadas}


# ─── Telas do disparo para campanhas ──────────────────────────────────────
# Só admin, como o MEI. E moram sob /disparos pra dividir o mesmo item de menu
# com ele: o menu já tem 25 itens e tela nova não ganha entrada própria.

_DISPARO_STATUS_LABEL = {
    'pendente': 'Prontos pra sair', 'enfileirado': 'Na fila agora', 'enviado': 'Enviados',
    'respondeu': 'Responderam', 'sem_dono': 'Sem dono', 'sem_lead': 'Fora da base',
    'sem_modelo': 'Sem modelo', 'sem_variavel': 'Falta coluna na planilha',
    'bloqueado': 'Não querem receber', 'invalido': 'Telefone inválido',
    'travado': 'Não saiu em 3 tentativas',
}


def _disparo_resumo(conn, campanha_id):
    """Quantos alvos em cada destino. É o que a tela mostra no lugar de um
    '300 importados' que esconde que 120 não casaram com ninguém."""
    out = {}
    for r in conn.execute("""SELECT status, COUNT(*) n FROM disparo_campanha_alvo
        WHERE campanha_id=? GROUP BY status""", (campanha_id,)).fetchall():
        out[r['status']] = r['n']
    return out


