@app.route('/disparos/campanha/<int:cid>/ritmo', methods=['POST'])
@login_required
@admin_required
def disparo_campanha_ritmo(cid):
    """Teto por dia, janela de horário e dias — editáveis com a campanha rodando.

    O ritmo é a variável de negócio desta tela: com 3.685 leads, 10/dia por
    consultor leva dois meses e 30/dia leva três semanas. Ter que recriar a
    campanha pra mudar isso faria o admin escolher errado no primeiro dia e
    conviver com a escolha."""
    d = request.json or {}
    try:
        teto = max(1, min(500, int(d.get('teto_dia') or 10)))
    except (TypeError, ValueError):
        teto = 10
    ini = str(d.get('hora_inicio') or '08:00')[:5]
    fim = str(d.get('hora_fim') or '18:00')[:5]
    dias = ','.join([str(x) for x in (d.get('dias_semana') or []) if str(x) in '1234567']) or '1,2,3,4,5'
    if not (len(ini) == 5 and len(fim) == 5 and ini < fim):
        return jsonify({"ok": False, "erro": "A hora de início precisa ser antes da hora de fim."}), 400
    conn = db()
    arquivar = 1 if d.get('arquivar', True) else 0
    avisar_fora = 1 if d.get('avisar_fora_horario') else 0
    conn.execute("""UPDATE disparo_campanha SET teto_dia=?, hora_inicio=?, hora_fim=?, dias_semana=?,
        arquivar=?, avisar_fora_horario=? WHERE id=?""",
        (teto, ini, fim, dias, arquivar, avisar_fora, cid))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "teto_dia": teto, "hora_inicio": ini, "hora_fim": fim, "dias_semana": dias,
                    "arquivar": arquivar, "avisar_fora_horario": avisar_fora})


@app.route('/disparos/campanha/<int:cid>/passos', methods=['POST'])
@login_required
@admin_required
def disparo_campanha_passos(cid):
    """Salva a sequência de canais da campanha.

    Regra que faz isso ser costura e não metralhadora: o WhatsApp é sempre o
    passo 1 (é por ele que a campanha começa, pelo dono do lead), e os outros
    contam os dias A PARTIR do envio dele — só pegando quem não respondeu.
    """
    d = request.json or {}
    passos = (d.get('passos') or [])[:6]
    limpos, erros = [], []
    for i, p in enumerate(passos):
        canal = str((p or {}).get('canal') or '').strip()
        if canal not in ('whatsapp', 'sms', 'email'):
            continue
        texto = str((p or {}).get('texto') or '').strip()
        assunto = str((p or {}).get('assunto') or '').strip()
        try:
            dias = max(0, min(60, int((p or {}).get('apos_dias') or 0)))
        except (TypeError, ValueError):
            dias = 0
        if canal == 'whatsapp':
            limpos.append({'canal': canal, 'apos_dias': 0, 'texto': '', 'assunto': ''})
            continue
        if not texto:
            erros.append(f"O {_disparo_canais_rotulo(canal)} está sem texto.")
            continue
        if canal == 'sms' and len(texto) > 320:
            erros.append(f"O SMS tem {len(texto)} caracteres. O limite é 320 — acima disso a operadora quebra em vários e cobra por cada.")
            continue
        if canal == 'email' and not assunto:
            erros.append("O e-mail está sem assunto — sem ele vai direto pro spam.")
            continue
        if dias < 1:
            erros.append(f"O {_disparo_canais_rotulo(canal)} precisa esperar pelo menos 1 dia depois do WhatsApp. "
                         "Dois canais no mesmo dia é o que faz o cliente sentir perseguição.")
            continue
        limpos.append({'canal': canal, 'apos_dias': dias, 'texto': texto, 'assunto': assunto})
    if erros:
        return jsonify({"ok": False, "erro": erros[0]}), 400
    conn = db()
    conn.execute("DELETE FROM disparo_campanha_passo WHERE campanha_id=?", (cid,))
    for i, p in enumerate(limpos):
        conn.execute("""INSERT INTO disparo_campanha_passo
            (campanha_id, ordem, canal, apos_dias, assunto, texto, ativo) VALUES (?,?,?,?,?,?,1)""",
            (cid, i + 1, p['canal'], p['apos_dias'], p['assunto'] or None, p['texto'] or None))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "passos": len(limpos)})


@app.route('/disparos/campanha/<int:cid>/variaveis', methods=['POST'])
@login_required
@admin_required
def disparo_campanha_variaveis(cid):
    """Variáveis criadas no JOB, valendo pra toda a campanha.

    A planilha resolve o que MUDA por pessoa (mensalidade, vencimento). Isto
    resolve o que é IGUAL pra todo mundo — operadora, prazo, nome do plano — sem
    obrigar o admin a repetir a mesma informação em trezentas linhas.

    Nome vira minúsculo com underline, igual ao cabeçalho da planilha: é o mesmo
    formato que ele já escreve entre chaves, e duas regras de nome seria uma a
    mais do que o necessário.
    """
    import json as _json
    itens = (request.json or {}).get('variaveis') or []
    fixas, erros, reservados = {}, [], []
    for it in itens[:40]:
        nome = _disparo_slug((it or {}).get('nome'))
        valor = str((it or {}).get('valor') or '').strip()[:300]
        if not nome:
            continue
        if nome in _DISPARO_VARS_SISTEMA:
            reservados.append(nome)
            continue
        if not valor:
            erros.append(nome)
            continue
        fixas[nome] = valor
    if reservados:
        n = reservados[0]
        return jsonify({"ok": False,
                        "erro": f"{{{n}}} o sistema já preenche sozinho — é {_DISPARO_VARS_SISTEMA[n]}. "
                                f"Criar uma fixa com esse nome mandaria o mesmo valor pra todo mundo."}), 400
    if erros:
        return jsonify({"ok": False,
                        "erro": "Sem valor: " + ", ".join(erros) + ". Variável vazia deixaria a chave crua na tela do cliente."}), 400
    conn = db()
    conn.execute("UPDATE disparo_campanha SET variaveis_fixas=? WHERE id=?",
                 (_json.dumps(fixas, ensure_ascii=False), cid))
    # Alvo que tinha parado por falta de variável merece nova chance: pode ser
    # exatamente a que acabou de ser criada.
    conn.execute("""UPDATE disparo_campanha_alvo SET status='pendente', texto_enviado=NULL
        WHERE campanha_id=? AND status='sem_variavel'""", (cid,))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "variaveis": len(fixas)})


@app.route('/disparos/campanha/<int:cid>/modelos', methods=['POST'])
@login_required
@admin_required
def disparo_campanha_modelos(cid):
    """Quais modelos cada consultor usa NESTA campanha. Troca a lista inteira do
    consultor de uma vez — mais simples de entender do que somar e subtrair."""
    d = request.json or {}
    try:
        consultor_id = int(d.get('consultor_id'))
    except (TypeError, ValueError):
        return jsonify({"ok": False, "erro": "consultor"}), 400
    ids = [int(i) for i in (d.get('modelo_ids') or []) if str(i).isdigit()]
    conn = db()
    conn.execute("DELETE FROM disparo_campanha_modelo WHERE campanha_id=? AND consultor_id=?",
                 (cid, consultor_id))
    for mid in ids:
        try:
            conn.execute("INSERT INTO disparo_campanha_modelo (campanha_id, consultor_id, modelo_id) VALUES (?,?,?)",
                         (cid, consultor_id, mid))
        except Exception:
            if DB_MODE == 'postgres':
                try: conn.rollback()
                except Exception: pass
    # Alvo que tinha parado por falta de modelo pode voltar pra fila agora.
    conn.execute("""UPDATE disparo_campanha_alvo SET status='pendente'
        WHERE campanha_id=? AND consultor_id=? AND status='sem_modelo'""", (cid, consultor_id))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "modelos": len(ids)})


@app.route('/disparos/campanha/<int:cid>/bloquear', methods=['POST'])
@login_required
@admin_required
def disparo_campanha_bloquear(cid):
    """Marca que essa pessoa não quer mais receber campanha — de ninguém, nunca.

    É sempre uma pessoa clicando, nunca a detecção automática: "vou parar de
    pagar esse plano" tem as mesmas palavras de um pedido de saída, e apagar um
    cliente da base por causa disso seria caro e invisível.
    """
    d = request.json or {}
    try:
        alvo_id = int(d.get('alvo_id') or 0)
    except (TypeError, ValueError):
        alvo_id = 0
    conn = db()
    alvo = conn.execute("""SELECT a.*, c.nome campanha_nome FROM disparo_campanha_alvo a
        JOIN disparo_campanha c ON c.id=a.campanha_id WHERE a.id=? AND a.campanha_id=?""",
        (alvo_id, cid)).fetchone()
    if not alvo:
        close_db(conn); return jsonify({"ok": False, "erro": "Contato não encontrado."}), 404
    _disparo_bloquear(conn, alvo['telefone_norm'],
                      f"Pediu pra não receber (campanha {alvo['campanha_nome']})",
                      alvo['lead_id'], session.get('user_id'))
    conn.execute("UPDATE disparo_campanha_alvo SET status='bloqueado', quer_parar=1 WHERE id=?", (alvo['id'],))
    # Os pendentes do MESMO número em OUTRAS campanhas saem junto: o pedido é
    # "não me manda mais", não "não me manda mais nesta campanha".
    conn.execute("""UPDATE disparo_campanha_alvo SET status='bloqueado'
        WHERE telefone_norm=? AND status IN ('pendente','sem_dono','sem_lead','travado')""",
        (alvo['telefone_norm'],))
    _disparo_nota(conn, alvo['lead_id'],
                  "Pediu pra não receber mais campanha. Está bloqueado para qualquer disparo, "
                  "de qualquer consultor. Conversa normal com ele segue valendo.")
    conn.commit(); close_db(conn)
    return jsonify({"ok": True})


