@app.route('/disparos/campanha/<int:cid>/atribuir', methods=['POST'])
@login_required
@admin_required
def disparo_campanha_atribuir(cid):
    """Dá dono aos que estavam órfãos e devolve eles pra campanha.

    Quem já tem lead na base só ganha responsável. Quem veio na planilha e NÃO
    está na base vira lead de verdade — senão não haveria como disparar pra ele,
    e a planilha do admin teria trazido gente que o sistema ignora em silêncio.
    """
    d = request.json or {}
    try:
        consultor_id = int(d.get('consultor_id'))
    except (TypeError, ValueError):
        return jsonify({"ok": False, "erro": "consultor"}), 400
    ids = [int(i) for i in (d.get('alvo_ids') or []) if str(i).isdigit()]
    if not ids:
        return jsonify({"ok": False, "erro": "Nenhum contato marcado."}), 400
    conn = db()
    if not conn.execute("SELECT 1 FROM usuarios WHERE id=? AND ativo=1", (consultor_id,)).fetchone():
        close_db(conn); return jsonify({"ok": False, "erro": "Consultor inválido."}), 400
    marcadores = ','.join(['?'] * len(ids))
    alvos = conn.execute(f"""SELECT id, lead_id, nome, telefone, telefone_norm FROM disparo_campanha_alvo
        WHERE campanha_id=? AND id IN ({marcadores})""", (cid, *ids)).fetchall()
    criados = 0
    for a in alvos:
        lead_id = a['lead_id']
        if not lead_id:
            lead = conn.execute("SELECT id FROM crm_leads WHERE telefone_norm=? ORDER BY id DESC LIMIT 1",
                                (a['telefone_norm'],)).fetchone()
            if lead:
                lead_id = lead['id']
            else:
                conn.execute("""INSERT INTO crm_leads (nome, telefone, telefone_norm, origem, etapa,
                    responsavel_id, criado_em, atualizado_em) VALUES (?,?,?,'campanha','primeiro_contato',?,?,?)""",
                    ((a['nome'] or a['telefone_norm']), a['telefone'] or a['telefone_norm'],
                     a['telefone_norm'], consultor_id, _agora_sp(), _agora_sp()))
                lead_id = (conn.execute("SELECT lastval() AS id").fetchone()['id'] if DB_MODE == 'postgres'
                           else conn.execute("SELECT last_insert_rowid() id").fetchone()['id'])
                criados += 1
        conn.execute("UPDATE crm_leads SET responsavel_id=? WHERE id=?", (consultor_id, lead_id))
    n = _disparo_reprocessar_sem_dono(conn, cid)
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "atribuidos": n, "leads_criados": criados})


@app.route('/api/whatsapp/campanha/resposta', methods=['POST', 'OPTIONS'])
@requer('whatsapp:enviar')
def api_whatsapp_campanha_resposta():
    """A extensão avisa quando um número de campanha RESPONDEU. Marca o contato
    como 'respondeu' (fica quente, libera o disparo do contexto). Chave da extensão.
    usuario_id (opcional) escopa pro consultor dono — evita marcar a resposta em
    campanha de outro consultor que por acaso tenha o mesmo número."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    d = request.json or {}
    tel = _normalizar_telefone(str(d.get('telefone') or ''))
    if not tel:
        return _wa_cors(jsonify({"ok": False, "erro": "telefone"})), 400
    uid = d.get('usuario_id')
    # COMO foi descoberto: ao vivo pelo evento, ou pela conferência que roda de
    # minuto em minuto. Guardar isso é o que permite dizer depois se uma campanha
    # foi mal ou se a gente é que estava cego.
    origem_det = str(d.get('detectado_por') or 'evento')[:20]
    if origem_det not in ('evento', 'ronda', 'manual'):
        origem_det = 'evento'
    # HORA DA RESPOSTA: quando a extensão consegue ler o carimbo da mensagem do
    # cliente, é ELE que vale — a resposta pode ter chegado às 21h e só ser vista
    # às 9h do dia seguinte, quando o consultor abriu o WhatsApp. Gravar a hora da
    # descoberta em vez da hora do fato faria todo tempo-até-responder mentir.
    quando = _agora_sp()
    try:
        _ts = int(d.get('respondeu_ts') or 0)
        if _ts > 0:
            _dt = datetime.fromtimestamp(_ts, TZ_SP)
            # Nunca aceita futuro: relógio torto do aparelho não pode virar dado.
            if _dt <= datetime.now(TZ_SP):
                quando = _dt.strftime('%Y-%m-%d %H:%M:%S')
    except (TypeError, ValueError, OSError, OverflowError):
        pass
    conn = db()
    # 'sem_resposta' entra na lista: a detecção velha era cega em conversa que já
    # existia, então há contato marcado como silencioso que na verdade respondeu.
    # Quando a conferência achar essa resposta antiga, o registro se corrige — e o
    # funil não sai junto, que é o que a validade de envio (commit anterior) trava.
    _sts = "('enfileirado','enviado','sem_resposta')"
    if uid:
        conn.execute(f"""UPDATE campanha_contato SET status='respondeu', respondeu_em=?, detectado_por=?
            WHERE telefone_norm=? AND consultor_id=? AND status IN {_sts}""",
            (quando, origem_det, tel, uid))
    else:
        conn.execute(f"""UPDATE campanha_contato SET status='respondeu', respondeu_em=?, detectado_por=?
            WHERE telefone_norm=? AND status IN {_sts}""", (quando, origem_det, tel))
    # Auto-dispara o funil da campanha (com delay aleatório) pros que responderam
    # agora e ainda não receberam. NÃO exige campanha 'ativa': o lead pode responder
    # dias depois, com a campanha já concluída — o conteúdo tem que sair mesmo assim.
    disparados = 0
    q = "SELECT cc.* FROM campanha_contato cc JOIN campanha c ON c.id=cc.campanha_id " \
        "WHERE cc.telefone_norm=? AND cc.status='respondeu' AND cc.funil_em IS NULL " \
        "AND c.status<>'pausada' AND c.funil_id IS NOT NULL"
    args = [tel]
    if uid:
        q += " AND cc.consultor_id=?"; args.append(uid)
    for ct in conn.execute(q, tuple(args)).fetchall():
        disparados += _campanha_disparar_funil(conn, ct)
    conn.commit(); close_db(conn)
    return _wa_cors(jsonify({"ok": True, "funil_passos": disparados}))


# FRASES DE QUEM QUER SAIR. Todas de duas palavras pra cima, de propósito: "pare"
# sozinho aparece em "não pare de me mandar novidades", e "parar" mora dentro de
# "vou parar de pagar esse plano" — que é conversa de venda, não pedido de saída.
# Isto NÃO bloqueia ninguém: levanta a mão pra o consultor decidir.
_DISPARO_PARAR_PADROES = (
    'nao quero receber', 'não quero receber', 'nao quero mais receber', 'não quero mais receber',
    'para de mandar', 'pare de mandar', 'parar de mandar', 'pare de me mandar',
    'nao me manda mais', 'não me manda mais', 'nao me mande mais', 'não me mande mais',
    'me tira dessa lista', 'me tire dessa lista', 'me tira da lista', 'me tire da lista',
    'sair da lista', 'descadastr', 'nao perturbe', 'não perturbe', 'me remova', 'remova meu',
    'nao envie mais', 'não envie mais', 'cancelar recebimento', 'nao tenho interesse em receber',
)


def _disparo_quer_parar(texto):
    """A resposta parece um pedido pra não receber mais? Sem acento e em caixa
    baixa dos dois lados, senão 'não' e 'nao' seriam palavras diferentes."""
    import unicodedata as _u
    t = _u.normalize('NFKD', str(texto or '')).encode('ascii', 'ignore').decode('ascii').lower()
    if not t.strip():
        return False
    for p in _DISPARO_PARAR_PADROES:
        alvo = _u.normalize('NFKD', p).encode('ascii', 'ignore').decode('ascii').lower()
        if alvo in t:
            return True
    return False


def _disparo_bloquear(conn, telefone_norm, motivo, lead_id=None, marcado_por=None):
    """Nunca mais em campanha nenhuma. Idempotente."""
    if not telefone_norm:
        return False
    try:
        conn.execute("""INSERT INTO disparo_bloqueio (telefone_norm, motivo, lead_id, marcado_por, criado_em)
            VALUES (?,?,?,?,?)""", (telefone_norm, (motivo or '')[:200], lead_id, marcado_por, _agora_sp()))
        return True
    except Exception:
        if DB_MODE == 'postgres':
            try: conn.rollback()
            except Exception: pass
        return False   # já estava bloqueado


def _disparo_aviso_texto(alvo):
    """O aviso que o dono do lead recebe. Diz QUEM respondeu, QUANTO tempo depois
    e o que já aconteceu — sem isso o consultor abre o WhatsApp sem saber se
    precisa correr ou se já foi tratado."""
    quem = (alvo['nome'] or alvo['telefone_norm'] or 'Um contato').strip()
    dec = _disparo_decorrido(alvo['enviado_em'], alvo['respondeu_em'])
    frase = f'{quem} respondeu'
    if dec:
        frase += f' {dec} depois do envio'
    return frase + '. A conversa voltou pra sua caixa de entrada — o atendimento é seu daqui.'


def _disparo_pode_avisar(camp, agora=None):
    """Fora do horário comercial, avisar ou segurar até de manhã é escolha da
    campanha (`avisar_fora_horario`). Padrão: segura — acordar sete pessoas às
    3h por uma resposta que só será atendida às 8h é ruído, não urgência."""
    try:
        livre = int(camp['avisar_fora_horario'] if 'avisar_fora_horario' in camp.keys()
                    and camp['avisar_fora_horario'] is not None else 0)
    except (TypeError, ValueError):
        livre = 0
    return bool(livre) or _horario_comercial(agora)


def _disparo_avisos_pendentes():
    """Solta os avisos que ficaram segurados fora do horário. Roda de 5 em 5 min
    junto da varredura da fila. Sem isto, o aviso segurado nunca chegaria — que
    é falha silenciosa com outro nome."""
    try:
        conn = db()
    except Exception:
        return
    try:
        pend = conn.execute("""SELECT a.*, c.nome campanha_nome, c.avisar_fora_horario
            FROM disparo_campanha_alvo a JOIN disparo_campanha c ON c.id=a.campanha_id
            WHERE a.respondeu_em IS NOT NULL AND a.notificado_em IS NULL
              AND a.consultor_id IS NOT NULL LIMIT 200""").fetchall()
        avisar = []
        for r in [dict(x) for x in pend]:
            if not _disparo_pode_avisar(r):
                continue
            conn.execute("UPDATE disparo_campanha_alvo SET notificado_em=? WHERE id=?",
                         (_agora_sp(), r['id']))
            avisar.append(r)
        if avisar:
            conn.commit()
    except Exception as e:
        app.logger.warning(f"[DISPARO_AVISO] {e}")
        try: conn.rollback()
        except Exception: pass
        avisar = []
    finally:
        try: close_db(conn)
        except Exception: pass
    for r in avisar:
        try:
            _notificar(r['consultor_id'], 'disparo_resposta',
                       f"Respondeu a campanha {r['campanha_nome']}",
                       _disparo_aviso_texto(r), '/crm')
        except Exception:
            pass


@app.route('/api/whatsapp/disparo/resposta', methods=['POST', 'OPTIONS'])
@requer('whatsapp:enviar')
def api_whatsapp_disparo_resposta():
    """O cliente respondeu a uma campanha da base. Cinco coisas acontecem aqui,
    e a sexta NÃO acontece de propósito.

    1. o alvo sai da campanha (não recebe mais nada dela, nunca);
    2. ganha a etiqueta "Respondeu <campanha>" — a de participação FICA, porque
       ela é o registro de quem recebeu o quê;
    3. a segunda nota entra no histórico, com o tempo que o cliente levou;
    4. o dono é avisado (ou o aviso fica pra manhã, se a campanha pedir isso);
    5. a extensão recebe a ordem de DESARQUIVAR a conversa.

    O que NÃO acontece: funil automático. Isto é cliente de carteira, e ele
    acabou de falar com uma pessoa — responder com sequência programada queima
    relacionamento que custou caro pra construir. O corretor assume daqui.
    """
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    d = request.json or {}
    uid = d.get('usuario_id')
    origem_det = str(d.get('detectado_por') or 'evento')[:20]
    if origem_det not in ('evento', 'ronda', 'manual'):
        origem_det = 'evento'
    quando = _agora_sp()
    try:
        _ts = int(d.get('respondeu_ts') or 0)
        if _ts > 0:
            _dt = datetime.fromtimestamp(_ts, TZ_SP)
            if _dt <= datetime.now(TZ_SP):
                quando = _dt.strftime('%Y-%m-%d %H:%M:%S')
    except (TypeError, ValueError, OSError, OverflowError):
        pass
    conn = db()
    try:
        alvo_id = int(d.get('alvo_id') or 0)
    except (TypeError, ValueError):
        alvo_id = 0
    if alvo_id:
        alvo = conn.execute("""SELECT a.*, c.nome campanha_nome, c.etiqueta_resp_id, c.avisar_fora_horario
            FROM disparo_campanha_alvo a JOIN disparo_campanha c ON c.id=a.campanha_id
            WHERE a.id=? AND a.status='enviado'""", (alvo_id,)).fetchone()
    else:
        tel = _normalizar_telefone(str(d.get('telefone') or ''))
        if not tel:
            close_db(conn); return _wa_cors(jsonify({"ok": False, "erro": "telefone"})), 400
        alvo = conn.execute("""SELECT a.*, c.nome campanha_nome, c.etiqueta_resp_id, c.avisar_fora_horario
            FROM disparo_campanha_alvo a JOIN disparo_campanha c ON c.id=a.campanha_id
            WHERE a.telefone_norm=? AND a.status='enviado'
              AND (? IS NULL OR a.consultor_id=?) ORDER BY a.id DESC LIMIT 1""", (tel, uid, uid)).fetchone()
    if not alvo:
        close_db(conn)
        return _wa_cors(jsonify({"ok": True, "nada": True}))   # já tratado, ou não é da base
    a = dict(alvo)
    conn.execute("""UPDATE disparo_campanha_alvo SET status='respondeu', respondeu_em=?, detectado_por=?
        WHERE id=?""", (quando, origem_det, a['id']))
    a['respondeu_em'] = quando
    etq_resp = a['etiqueta_resp_id'] or _disparo_etiqueta_id(
        conn, f"Respondeu {a['campanha_nome']}"[:60], '#1fd8a4')
    if etq_resp and not a['etiqueta_resp_id']:
        conn.execute("UPDATE disparo_campanha SET etiqueta_resp_id=? WHERE id=?", (etq_resp, a['campanha_id']))
    _disparo_etiquetar(conn, a['lead_id'], etq_resp)
    quer_parar = _disparo_quer_parar(d.get('texto'))
    if quer_parar:
        conn.execute("UPDATE disparo_campanha_alvo SET quer_parar=1 WHERE id=?", (a['id'],))
    dec = _disparo_decorrido(a['enviado_em'], quando)
    _disparo_nota(conn, a['lead_id'],
                  f"Respondeu a campanha \"{a['campanha_nome']}\"" + (f" — {dec} depois do envio." if dec else '.') +
                  " O atendimento é do consultor a partir daqui (a campanha não manda mais nada)." +
                  (" A resposta parece um pedido pra não receber mais campanha — confira e, "
                   "se for isso, marque na tela da campanha." if quer_parar else ''))
    pode = _disparo_pode_avisar(a)
    if pode:
        conn.execute("UPDATE disparo_campanha_alvo SET notificado_em=? WHERE id=?", (_agora_sp(), a['id']))
    conn.commit(); close_db(conn)
    if pode and a['consultor_id']:
        try:
            _notificar(a['consultor_id'], 'disparo_resposta',
                       ('Pediu pra não receber mais — ' if quer_parar else 'Respondeu a campanha ')
                       + a['campanha_nome'],
                       _disparo_aviso_texto(a) +
                       (' A mensagem dele parece um pedido pra sair da lista.' if quer_parar else ''),
                       '/crm')
        except Exception:
            pass
    return _wa_cors(jsonify({"ok": True, "desarquivar": True, "quer_parar": bool(quer_parar),
                             "chat_id": _wa_chat_id(a['telefone_norm'] or a['telefone'] or ''),
                             "avisado": bool(pode)}))


@app.route('/api/whatsapp/disparo/etiquetas', methods=['GET', 'OPTIONS'])
@requer('whatsapp:ler')
def api_whatsapp_disparo_etiquetas():
    """Quem, na lista do consultor, está em campanha — pra extensão pintar a
    etiqueta na conversa dentro do WhatsApp Web.

    Só o que ELE precisa: os alvos dele, das campanhas que não estão encerradas.
    Nome da campanha e nada mais — nem telefone de terceiro, nem lead de outro
    consultor. A lista é curta por natureza (é a campanha do mês), e a extensão
    guarda por alguns minutos: pintar não pode virar uma chamada por rolagem.
    """
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    uid = request.args.get('usuario_id', type=int)
    if not uid:
        return _wa_cors(jsonify({"ok": True, "etiquetas": []}))
    conn = db()
    try:
        rows = conn.execute("""SELECT a.telefone_norm, a.status, c.nome campanha
            FROM disparo_campanha_alvo a JOIN disparo_campanha c ON c.id=a.campanha_id
            WHERE a.consultor_id=? AND COALESCE(c.status,'') <> 'concluida'
              AND a.status IN ('pendente','enfileirado','enviado','respondeu')
              AND COALESCE(a.telefone_norm,'') <> ''
            ORDER BY a.id DESC LIMIT 2000""", (uid,)).fetchall()
    except Exception:
        rows = []   # banco sem as tabelas novas não pode derrubar a extensão
    close_db(conn)
    # Um telefone pode estar em duas campanhas: fica a mais recente, que é a que
    # o consultor tem na cabeça quando olha a conversa.
    vistos, saida = set(), []
    for r in rows:
        tel = r['telefone_norm']
        if tel in vistos:
            continue
        vistos.add(tel)
        saida.append({"telefone": tel, "campanha": (r['campanha'] or '')[:40],
                      "respondeu": r['status'] == 'respondeu'})
    return _wa_cors(jsonify({"ok": True, "etiquetas": saida}))


@app.route('/api/whatsapp/campanha/aguardando', methods=['GET', 'OPTIONS'])
@requer('whatsapp:ler')
def api_whatsapp_campanha_aguardando():
    """A extensão pergunta, pro consultor, quais números de campanha estão
    AGUARDANDO resposta (pra vigiar a chegada) e quais já viraram SEM RESPOSTA
    (pra oferecer apagar a conversa). Só leitura, escopado por consultor."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    uid = request.args.get('usuario_id', type=int)
    if not uid:
        return _wa_cors(jsonify({"ok": True, "aguardando": [], "excluir": []}))
    conn = db()
    _campanha_marcar_sem_resposta(conn)  # promove os vencidos antes de listar
    def _linha(r):
        # `desde` é a marca d'água: a hora em que a NOSSA mensagem saiu. A extensão
        # só chama de resposta o que entrou depois disso. Sem ela, a checagem tinha
        # que adivinhar pelo formato da conversa — e adivinhava errado em cliente
        # de carteira, onde já existe conversa de meses.
        return {"contato_id": r['id'], "telefone": r['telefone_norm'],
                "nome": (r['lead_nome'] or ''),
                "desde": _epoch_sp(r['enviado_em']),
                "chat_id": _wa_chat_id(r['telefone_norm'] or r['telefone'] or '')}
    # Nome do lead por subquery (não multiplica linha se houver lead duplicado)
    # — pra o aviso de limpeza dizer QUEM vai ser apagado, não só "2 conversas".
    aguard = conn.execute("""SELECT id, telefone, telefone_norm, enviado_em,
        (SELECT nome FROM crm_leads l WHERE l.telefone_norm = campanha_contato.telefone_norm ORDER BY l.id LIMIT 1) AS lead_nome
        FROM campanha_contato
        WHERE consultor_id=? AND status='enviado' AND respondeu_em IS NULL AND excluido_em IS NULL
          AND telefone_norm IS NOT NULL AND telefone_norm<>''""", (uid,)).fetchall()
    excluir = conn.execute("""SELECT id, telefone, telefone_norm, enviado_em,
        (SELECT nome FROM crm_leads l WHERE l.telefone_norm = campanha_contato.telefone_norm ORDER BY l.id LIMIT 1) AS lead_nome
        FROM campanha_contato
        WHERE consultor_id=? AND status='sem_resposta' AND excluido_em IS NULL
          AND telefone_norm IS NOT NULL AND telefone_norm<>''""", (uid,)).fetchall()
    conn2 = conn   # a consulta da campanha na base usa a mesma conexão, abaixo
    # DEDUP por telefone: o mesmo número pode estar em MAIS de uma campanha
    # (várias linhas em campanha_contato) — o aviso mostrava "Gábriel" duas
    # vezes e o apagar tentaria excluir o mesmo chat duas vezes. Uma conversa
    # no WhatsApp = uma entrada aqui, sempre.
    def _dedup(rows):
        # Chave = chat_id (não a string do telefone): '5519...' e '19...' são o
        # MESMO chat no WhatsApp e apareciam como duas entradas no aviso.
        por_chat = {}
        for r in rows:
            li = _linha(r)
            ja = por_chat.get(li['chat_id'])
            # fica a entrada COM nome (a linha sem 55 pode não casar o lead)
            if ja is None or (not ja['nome'] and li['nome']):
                por_chat[li['chat_id']] = li
        return list(por_chat.values())
    # CAMPANHA NA BASE, na mesma resposta de propósito: a extensão faz UMA
    # rodada de leitura por minuto e confere os dois motores nela. Dois
    # endpoints seriam duas chamadas e duas passadas pela memória do WhatsApp.
    # Chave separada porque as tabelas e as regras são separadas.
    base = []
    try:
        for r in conn2.execute("""SELECT a.id, a.nome, a.telefone, a.telefone_norm, a.enviado_em
            FROM disparo_campanha_alvo a
            WHERE a.consultor_id=? AND a.status='enviado' AND a.respondeu_em IS NULL
              AND a.enviado_em IS NOT NULL AND COALESCE(a.telefone_norm,'')<>''""", (uid,)).fetchall():
            base.append({"alvo_id": r['id'], "telefone": r['telefone_norm'], "nome": r['nome'] or '',
                         "desde": _epoch_sp(r['enviado_em']),
                         "chat_id": _wa_chat_id(r['telefone_norm'] or r['telefone'] or '')})
    except Exception:
        base = []   # banco sem as tabelas novas não derruba a vigília do MEI
    close_db(conn2)
    return _wa_cors(jsonify({"ok": True,
        "aguardando": _dedup(aguard),
        "excluir": _dedup(excluir),
        "base": base}))


@app.route('/api/whatsapp/campanha/excluir-conversa', methods=['POST', 'OPTIONS'])
@requer('whatsapp:enviar')
def api_whatsapp_campanha_excluir():
    """A extensão avisa que o consultor apagou a conversa de um não-respondente.
    Registra excluido_em (auditoria) e tira da lista de vigília. Ação irreversível
    no WhatsApp — quem apaga é o consultor no aparelho dele; aqui só registramos."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    d = request.json or {}
    uid = d.get('usuario_id')
    cid = d.get('contato_id')
    tel = _normalizar_telefone(str(d.get('telefone') or ''))
    if not uid or not (cid or tel):
        return _wa_cors(jsonify({"ok": False, "erro": "faltam dados"})), 400
    conn = db()
    if not conn.execute("SELECT 1 FROM usuarios WHERE id=? AND ativo=1", (uid,)).fetchone():
        close_db(conn); return _wa_cors(jsonify({"ok": False, "erro": "consultor inválido"})), 403
    # Marca por TELEFONE sempre que houver: o mesmo número pode estar em várias
    # campanhas (várias linhas) e a conversa apagada é UMA — marcar só pelo id
    # deixava a linha da outra campanha viva e o aviso de limpeza ressuscitava.
    # Casa TODAS as variantes do número (com/sem 55): campanha_contato guarda o
    # formato de quem importou, e _normalizar_telefone tira o 55 — sem isso o
    # UPDATE não achava a linha e o aviso voltava mesmo depois de apagar.
    import re as _re
    bruto = _re.sub(r'\D', '', str(d.get('telefone') or ''))
    variantes = {v for v in (
        tel, bruto,
        ('55' + tel) if tel and not tel.startswith('55') else '',
        tel[2:] if tel.startswith('55') else '',
        ('55' + bruto) if bruto and not bruto.startswith('55') else '',
        bruto[2:] if bruto.startswith('55') else '',
    ) if v}
    if variantes:
        marcadores = ','.join(['?'] * len(variantes))
        conn.execute(f"""UPDATE campanha_contato SET status='excluido', excluido_em=?
            WHERE telefone_norm IN ({marcadores}) AND consultor_id=? AND status IN ('sem_resposta','enviado')""",
            (_agora_sp(), *variantes, uid))
    elif cid:
        conn.execute("UPDATE campanha_contato SET status='excluido', excluido_em=? WHERE id=? AND consultor_id=?",
                     (_agora_sp(), cid, uid))
    conn.commit(); close_db(conn)
    return _wa_cors(jsonify({"ok": True}))


def _crm_grupos_duplicados(conn):
    """Grupos de leads SEM número duplicados por nome+consultor (o lixo gerado pelo
    bug do @lid). Só mescla os sem número — lead com número é confiável, não toca."""
    return conn.execute("""SELECT LOWER(TRIM(nome)) chave, COALESCE(responsavel_id,-1) resp, COUNT(*) n
        FROM crm_leads WHERE COALESCE(TRIM(telefone_norm),'')='' AND COALESCE(TRIM(nome),'')<>''
        GROUP BY LOWER(TRIM(nome)), COALESCE(responsavel_id,-1)
        HAVING COUNT(*) > 1 ORDER BY n DESC""").fetchall()


def _dup_nome_tokens(nome):
    """Palavras do nome, sem acento e sem pontuacao — pra comparar 'Zé Luiz' com
    'JOSE LUIZ' sem depender de como foi digitado."""
    import unicodedata as _u
    t = _u.normalize('NFKD', (nome or '')).encode('ascii', 'ignore').decode().lower()
    t = t.replace('ze ', 'jose ')          # apelido comum que quebrava a comparacao
    return [w for w in re.sub(r'[^a-z0-9 ]', ' ', t).split() if len(w) > 1]


def _dup_semelhanca(nomes):
    """Quanto os nomes de um grupo se parecem. E SUGESTAO, nao veredito.

    Aprendi na marra que essa classificacao erra dos dois lados: 'Ze Luiz' e
    'JOSE LUIZ' sao a mesma pessoa e o algoritmo dizia que nao; 'Jonas Estevao'
    e 'Maria Helena' dividem o telefone e nao sao. Por isso ela ordena a fila e
    colore o aviso — quem decide e quem conhece o cliente."""
    toks = [_dup_nome_tokens(n) for n in nomes]
    txt = [' '.join(t) for t in toks]
    if len(set(txt)) == 1:
        return 'identico', 'Nomes iguais'
    for i, a in enumerate(toks):
        for b in toks[i + 1:]:
            if a and b and (all(w in b for w in a) or all(w in a for w in b)):
                return 'contido', 'Um nome está contido no outro'
    if all(t for t in toks) and len(set(t[0] for t in toks)) == 1:
        return 'primeiro', 'Só o primeiro nome coincide'
    return 'diferente', 'Nomes sem relação — provavelmente pessoas diferentes'


@app.route('/crm/duplicados')
@login_required
@admin_required
def crm_duplicados():
    """Telefones com mais de um lead, lado a lado, pra decidir um a um.

    NAO junta sozinho, de proposito. A semelhanca do nome e sugestao: o
    algoritmo ja errou nos dois sentidos aqui, e num CRM de saude misturar o
    historico de duas pessoas e pior que conviver com um cadastro repetido."""
    conn = db()
    grupos = []
    try:
        tels = [r['telefone_norm'] for r in conn.execute(
            """SELECT telefone_norm FROM crm_leads
               WHERE telefone_norm IS NOT NULL AND telefone_norm <> ''
               GROUP BY telefone_norm HAVING COUNT(*) > 1""").fetchall()]
        for tel in tels:
            rows = conn.execute("""SELECT l.id, l.nome, l.etapa, l.origem, l.criado_em,
                l.email, l.empresa, l.responsavel_id,
                (SELECT COUNT(*) FROM propostas p WHERE p.lead_id=l.id) props,
                (SELECT COUNT(*) FROM wa_chat_lead w WHERE w.lead_id=l.id) convs,
                (SELECT COUNT(*) FROM crm_atividades a WHERE a.lead_id=l.id) ativs,
                (SELECT COUNT(*) FROM cotacao_salva cs WHERE cs.lead_id=l.id) cots
                FROM crm_leads l WHERE l.telefone_norm=? ORDER BY l.id""", (tel,)).fetchall()
            leads = [dict(r) for r in rows]
            etapas_nome = {e['id']: e['nome'] for e in carregar_etapas_crm(conn)}
            for l in leads:
                l['etapa_nome'] = etapas_nome.get(l['etapa'] or '', l['etapa'] or '')
                l['quando'] = _fmt_data_br(l['criado_em'])
                # QUANTO ELE CARREGA: e o que decide qual sobrevive. O sugerido e
                # o que tem mais historia — perder o vazio custa nada, perder o
                # cheio custa a venda.
                l['peso'] = (l['props'] * 100) + (l['cots'] * 20) + (l['convs'] * 10) + l['ativs']
            leads.sort(key=lambda x: -x['peso'])
            sem, rot = _dup_semelhanca([l['nome'] for l in leads])
            grupos.append({'tel': _formatar_telefone(tel), 'tel_norm': tel,
                           'leads': leads, 'semelhanca': sem, 'rotulo': rot,
                           'tem_proposta': any(l['props'] for l in leads)})
        ordem = {'identico': 0, 'contido': 1, 'primeiro': 2, 'diferente': 3}
        grupos.sort(key=lambda g: (ordem.get(g['semelhanca'], 9), g['tel']))
    except Exception as e:
        app.logger.warning(f"[DUPLICADOS] {e}")
    close_db(conn)
    cont = {}
    for g in grupos:
        cont[g['semelhanca']] = cont.get(g['semelhanca'], 0) + 1
    return render_template('crm_duplicados.html', grupos=grupos, cont=cont)


@app.route('/crm/leads-duplicados')
@login_required
@admin_required
def crm_leads_duplicados():
    conn = db()
    grupos = _crm_grupos_duplicados(conn)
    # Duplicados POR TELEFONE. Ficaram invisíveis até agora: esta tela só tratava
    # duplicado SEM número. A canonização do telefone (30/07) revelou 49 números
    # com mais de um lead, e o log manda revisar aqui — sem esta lista a mensagem
    # apontava pra uma tela que não mostra o que ela prometia.
    dup_tel = []
    try:
        chaves = conn.execute("""SELECT telefone_norm FROM crm_leads
            WHERE telefone_norm IS NOT NULL AND telefone_norm <> ''
            GROUP BY telefone_norm HAVING COUNT(*) > 1
            ORDER BY COUNT(*) DESC, telefone_norm""").fetchall()
        for k in chaves:
            tn = k['telefone_norm']
            leads = conn.execute("""SELECT l.id, l.nome, l.etapa, l.criado_em, u.nome resp
                FROM crm_leads l LEFT JOIN usuarios u ON u.id = l.responsavel_id
                WHERE l.telefone_norm=? ORDER BY l.criado_em, l.id""", (tn,)).fetchall()
            dup_tel.append({'tel': tn, 'leads': [dict(x) for x in leads]})
    except Exception as e:
        app.logger.warning(f"[DUPLICADOS] lista por telefone falhou: {e}")
    close_db(conn)
    extra = sum(g['n'] - 1 for g in grupos)
    linhas = ''.join(
        f'<tr><td style="padding:8px 12px;">{g["chave"]}</td><td style="padding:8px 12px;text-align:center;">{g["n"]}</td>'
        f'<td style="padding:8px 12px;text-align:center;color:#dc2626;">{g["n"]-1}</td></tr>' for g in grupos)
    corpo = (f'<p>{len(grupos)} nome(s) com duplicados sem número — <b>{extra} lead(s) a mesclar</b>. '
             'A mesclagem mantém o mais antigo de cada nome, move o histórico pra ele e apaga os demais. '
             'Leads COM número não são tocados.</p>'
             '<button class="btn" onclick="mesclar(this)">Mesclar duplicados</button>'
             '<table style="width:100%;border-collapse:collapse;margin-top:16px;font-size:13.5px;">'
             '<thead><tr><th style="text-align:left;padding:8px 12px;background:#f3f4f6;">Nome</th>'
             '<th style="padding:8px 12px;background:#f3f4f6;">Leads</th><th style="padding:8px 12px;background:#f3f4f6;">A apagar</th></tr></thead>'
             f'<tbody>{linhas or "<tr><td colspan=3 style=padding:20px;text-align:center;color:#16a34a;>Nenhum duplicado sem número.</td></tr>"}</tbody></table>'
             if grupos or True else '')

    def _lin_tel(d):
        # ESCAPAR: nome do lead é dado externo (formulário público via /webhook/sheets
        # e endpoint da extensão). Esta página tem o botão de mesclagem destrutiva,
        # então script injetado aqui roda com a sessão admin e pode dispará-la.
        import html as _html
        _e = lambda v: _html.escape(str(v or ''), quote=True)
        itens = ''.join(
            f'<li><a href="/crm?lead={int(x["id"])}" target="_blank">{_e(x["nome"]) or "(sem nome)"}</a>'
            f' <span class="cinza">· {_e(x["etapa"]) or "—"} · {_e(x["resp"]) or "sem consultor"}'
            f' · entrou em {_e(_fmt_data_br(x["criado_em"]))}</span></li>' for x in d['leads'])
        return (f'<div class="grupo"><div class="tel">{_formatar_telefone(d["tel"])}'
                f' <span class="cinza">— {len(d["leads"])} leads</span></div><ul>{itens}</ul></div>')
    bloco_tel = (
        '<h1 style="margin-top:38px;">Mesmo telefone, mais de um lead</h1>'
        f'<p>{len(dup_tel)} número(s) com mais de um lead. <b>Nada é mesclado automaticamente</b> — '
        'dois leads podem dividir um telefone de empresa ou de família e serem pessoas diferentes. '
        'Abra cada um e decida.</p>'
        + (''.join(_lin_tel(d) for d in dup_tel) if dup_tel
           else '<p style="color:#16a34a;">Nenhum telefone repetido.</p>'))

    html = f"""<!doctype html><html lang="pt-BR"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1"><title>Leads duplicados</title>
<style>body{{font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif;max-width:760px;margin:0 auto;padding:32px 22px 80px;color:#1a1d24;line-height:1.5;}}
h1{{font-size:23px;margin:0 0 12px}} a.voltar{{color:#2563eb;text-decoration:none;font-size:14px;}} tr{{border-bottom:1px solid #eee}}
.btn{{display:inline-block;background:#2563eb;color:#fff;border:none;text-decoration:none;padding:10px 18px;border-radius:8px;font-weight:600;font-size:14px;cursor:pointer;}}
.grupo{{border:1px solid #e5e7eb;border-radius:9px;padding:10px 14px;margin-bottom:10px;}}
.tel{{font-weight:700;font-size:14.5px;}} .cinza{{color:#6b7280;font-weight:400;font-size:13px;}}
.grupo ul{{margin:7px 0 0;padding-left:19px;}} .grupo li{{margin-bottom:3px;font-size:13.5px;}}
.grupo a{{color:#2563eb;text-decoration:none;}} .grupo a:hover{{text-decoration:underline;}}</style>
</head><body><a class="voltar" href="/crm">← Voltar ao CRM</a><h1>Leads duplicados sem número</h1>{corpo}{bloco_tel}
<script>async function mesclar(b){{b.disabled=true;b.textContent='Mesclando...';
const r=await fetch('/crm/leads-duplicados/aplicar',{{method:'POST'}});const d=await r.json();
alert(d.ok?('Mesclados '+d.mesclados+' lead(s) duplicado(s).'):'Erro');location.reload();}}</script>
</body></html>"""
    return html


@app.route('/crm/leads-duplicados/aplicar', methods=['POST'])
@login_required
@admin_required
def crm_leads_duplicados_aplicar():
    conn = db()
    grupos = _crm_grupos_duplicados(conn)
    mesclados = 0
    for g in grupos:
        rows = conn.execute("""SELECT id FROM crm_leads
            WHERE LOWER(TRIM(nome))=? AND COALESCE(responsavel_id,-1)=?
              AND COALESCE(TRIM(telefone_norm),'')='' ORDER BY id""", (g['chave'], g['resp'])).fetchall()
        if len(rows) < 2:
            continue
        keep = rows[0]['id']
        for r in rows[1:]:
            # move o histórico pro lead que fica e apaga o duplicado
            for tab in ('crm_atividades', 'whatsapp_extensao_fila'):
                try:
                    conn.execute(f"UPDATE {tab} SET lead_id=? WHERE lead_id=?", (keep, r['id']))
                except Exception:
                    if DB_MODE == 'postgres':
                        try: conn.rollback()
                        except Exception: pass
            conn.execute("DELETE FROM crm_leads WHERE id=?", (r['id'],))
            mesclados += 1
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "mesclados": mesclados})


