# ═══════════ COMISSÃO GRAVADA × REGRA ATUAL ═══════════
# A comissão fica GRAVADA na proposta (comissao_total_corretora e irmãs), e é
# dela que o Dashboard e o Financeiro somam. Quando a venda é corrigida depois
# — operadora trocada, valor ajustado — ou quando a régua da operadora muda, o
# número gravado envelhece em silêncio: nada avisa, e a soma continua saindo
# errada. Isto compara o gravado com o que a regra diz HOJE.

def _producao_mes_cacheada(conn, d, cache):
    """`_producao_mes(excluir_pid=id)` sem repetir a consulta por venda.

    Varrer a base inteira chamava esta soma uma vez por proposta, e todas as
    vendas do mesmo consultor no mesmo mês faziam a MESMA consulta. Aqui o total
    do par (consultor, mês) é lido uma vez e a própria venda é subtraída na mão —
    o mesmo que o `id<>?` fazia no banco.

    A subtração só vale se a venda entra na soma. Produção ignora excluída e
    estornada, e `status <> 'Excluída'` no SQL descarta status nulo (comparação
    com NULL não é verdadeira) — por isso a checagem abaixo repete essa regra em
    vez de assumir que toda venda varrida conta."""
    uid, ma = d.get('usuario_id'), str(d.get('mes_meta') or '')[:7]
    if len(ma) != 7:
        return 0
    chave = (uid, ma)
    if chave not in cache:
        cache[chave] = _producao_mes(conn, uid, ma)
    total = cache[chave]
    st = d.get('status')
    na_soma = (st is not None and st != 'Excluída' and not (d.get('estornada') or 0))
    return total - float(d.get('valor') or 0) if na_soma else total


def _comissao_calculada(conn, p, prod_cache=None, motivo=None):
    """O que a regra de hoje produziria para esta venda. None se não dá pra saber.

    `motivo`: lista opcional onde a razão de não dar pra saber é anotada. Sem
    ela, "não consegui conferir" e "está certo" viram o mesmo resultado na tela
    — e uma venda quebrada some dentro de um contador."""
    def _nao(por_que):
        if motivo is not None:
            motivo.append(por_que)
        return None

    d = dict(p)
    regime = d.get('regime_aplicado') or ''
    operadora = d.get('adm_operadora') or ''
    valor = float(d.get('valor') or 0)
    if not operadora:
        return _nao('Operadora não preenchida nesta venda.')
    if valor <= 0:
        return _nao('Valor da venda está zerado.')
    try:
        if regime in ('socio_gestor_regra', 'socio_gestor_pendente'):
            c = _gestor_calculo_inicial(conn, operadora, d.get('modalidade'),
                                        d.get('tipo_pessoa'), valor)
            if not c:
                return _nao('Não foi possível montar a regra de sócio/gestor.')
            if c.get('falta_regra_gestor'):
                return _nao(c.get('aviso') or c['falta_regra_gestor'][0])
            return c
        prod = (_producao_mes_cacheada(conn, d, prod_cache) if prod_cache is not None
                else _producao_mes(conn, d.get('usuario_id'), d.get('mes_meta'),
                                   excluir_pid=d.get('id'))) + valor
        base = d.get('regime_base')
        if not base:
            u = conn.execute("SELECT regime_base FROM usuarios WHERE id=?",
                             (d.get('usuario_id'),)).fetchone()
            base = (dict(u).get('regime_base') if u else '') or 'sem_lead_sem_fixo'
        return calc_comissao(operadora, base, prod, valor,
                             d.get('modalidade'), d.get('tipo_pessoa'), conn=conn)
    except Exception as e:
        app.logger.warning(f"[COMISSAO] nao consegui recalcular a proposta {d.get('id')}: {e}")
        return _nao(f'Erro ao recalcular: {e}')


def comissao_divergente(conn, p, tolerancia=0.05, prod_cache=None, motivo=None):
    """Compara o valor GRAVADO com o que a regra diz hoje.

    Devolve None quando não há como comparar (falta regra, valor zerado) — e
    isso é diferente de 'está certo'. Divergência sem explicação é pior que
    divergência conhecida."""
    calc = _comissao_calculada(conn, p, prod_cache=prod_cache, motivo=motivo)
    if not calc:
        return None
    d = dict(p)
    gravado = round(float(d.get('comissao_total_corretora') or 0), 2)
    correto = round(float(calc.get('total_corretora') or 0), 2)
    dif = round(correto - gravado, 2)
    return {'gravado': gravado, 'correto': correto, 'diferenca': dif,
            'divergente': abs(dif) > tolerancia,
            'consultor_correto': round(float(calc.get('consultor') or 0), 2),
            'liquido_correto': round(float(calc.get('liquido') or 0), 2),
            'calc': calc}


def _recalcular_proposta(conn, pid, quem='admin'):
    """Regrava a comissão desta venda pela regra de hoje. Devolve (ok, msg).

    Respeita as mesmas travas da edição: dinheiro que já andou não se toca."""
    p = conn.execute("SELECT * FROM propostas WHERE id=?", (pid,)).fetchone()
    if not p:
        return False, 'Proposta não encontrada.'
    d = dict(p)
    dv = comissao_divergente(conn, p)
    if not dv:
        return False, ('Não há regra completa para esta operadora/plano, então não dá '
                       'para dizer qual seria o valor certo. Cadastre a regra primeiro.')
    if not dv['divergente']:
        return True, 'A comissão gravada já está de acordo com a regra atual.'
    travas = _historico_travas(conn, pid)
    if travas:
        return False, ('Esta venda já tem dinheiro em movimento — recalcular mudaria número '
                       'que já foi pago ou conciliado. ' + ' '.join(travas))
    calc = dv['calc']
    conn.execute("""UPDATE propostas
                       SET comissao_total_corretora=?, comissao_consultor=?,
                           comissao_corretora_liquida=?, num_parcelas=?, distribuicao_parcelas=?
                     WHERE id=?""",
                 (calc['total_corretora'], calc['consultor'], calc['liquido'],
                  calc.get('num_parcelas'), calc.get('dist_corretora'), pid))
    # Parcelas: só as que ainda não andaram
    pagas = conn.execute("""SELECT COUNT(*) n FROM parcelas
                             WHERE proposta_id=? AND status<>'Pendente de receber'""",
                         (pid,)).fetchone()['n']
    if pagas == 0:
        conn.execute("DELETE FROM parcelas WHERE proposta_id=?", (pid,))
        for parc in gerar_parcelas(pid, d.get('vigencia'), calc, d.get('dia_vencimento')):
            conn.execute("""INSERT INTO parcelas (proposta_id,numero,percentual,valor,valor_corretora,
                            perc_cliente,data_prevista,status,competencia,mensalidade_ref,tipo_origem)
                            VALUES (?,?,?,?,?,?,?,?,?,?,'comissao')""",
                (parc['proposta_id'], parc['numero'], parc['percentual'], parc['valor'],
                 parc['valor_corretora'], parc['perc_cliente'], parc['data_prevista'],
                 parc['status'], parc['competencia'], parc['mensalidade_ref']))
        extra = ' Parcelas regeradas.'
    else:
        extra = ' Parcelas já em fluxo foram mantidas.'
    conn.execute("""INSERT INTO historico_proposta
                    (proposta_id,usuario_id,usuario_nome,campo,valor_antes,valor_depois,criado_em)
                    VALUES (?,?,?,?,?,?,?)""",
                 (pid, None, quem, 'Comissão recalculada',
                  _moeda(dv['gravado']), _moeda(dv['correto']), datetime.now(TZ_SP)))
    return True, (f"Comissão atualizada de {_moeda(dv['gravado'])} para "
                  f"{_moeda(dv['correto'])}.{extra}")


@app.route('/proposta/<int:pid>/recalcular-comissao', methods=['POST'])
@login_required
@admin_required
def proposta_recalcular_comissao(pid):
    """Força o recálculo desta venda pela regra de hoje."""
    conn = db()
    ok, msg = _recalcular_proposta(conn, pid, session.get('nome', 'admin'))
    if ok:
        conn.commit()
    else:
        try: conn.rollback()
        except Exception: pass
    close_db(conn)
    return jsonify({'ok': ok, 'msg' if ok else 'erro': msg}), (200 if ok else 409)


@app.route('/admin/comissoes-divergentes')
@login_required
@admin_required
def comissoes_divergentes():
    """Toda venda cuja comissão gravada discorda da regra de hoje.

    É a rede de segurança: erro de comissão não some sozinho, e sem uma lista
    ninguém descobre que existe até o fechamento não bater."""
    conn = db()
    linhas, nao_confere, conferidas, prod_cache = [], [], 0, {}
    # Sem LIMIT de propósito. Havia um teto de 800 aqui, e um teto silencioso numa
    # tela de auditoria mente: ela dizia "0 divergências" quando o certo era
    # "0 entre as 800 mais recentes" — e venda antiga é justamente onde a comissão
    # gravada teve mais tempo pra envelhecer. Custo medido: ~1,3s pra 6 mil vendas.
    for p in conn.execute("""SELECT * FROM propostas
                              WHERE COALESCE(status,'') <> 'Excluída'
                                AND COALESCE(estornada,0) = 0
                              ORDER BY id DESC""").fetchall():
        conferidas += 1
        d = dict(p)
        por_que = []
        dv = comissao_divergente(conn, p, prod_cache=prod_cache, motivo=por_que)
        if dv is None:
            # Antes isto virava só um contador. Venda de gestor com regra
            # incompleta caía aqui e sumia: a tela dizia "0 divergências" sem
            # dizer que nem tinha conseguido olhar pra ela.
            nao_confere.append({
                'id': d['id'], 'cliente': d.get('razao_social'),
                'operadora': d.get('adm_operadora'), 'consultor': d.get('consultor'),
                'valor': float(d.get('valor') or 0),
                'gravado': round(float(d.get('comissao_total_corretora') or 0), 2),
                'motivo': por_que[0] if por_que else 'Não foi possível comparar.'})
            continue
        if not dv['divergente']:
            continue
        linhas.append({'id': d['id'], 'cliente': d.get('razao_social'),
                       'operadora': d.get('adm_operadora'), 'consultor': d.get('consultor'),
                       'valor': float(d.get('valor') or 0),
                       'gravado': dv['gravado'], 'correto': dv['correto'],
                       'diferenca': dv['diferenca'],
                       'travas': _historico_travas(conn, d['id'])})
    close_db(conn)
    total = round(sum(l['diferenca'] for l in linhas), 2)
    return render_template('comissoes_divergentes.html', linhas=linhas, total=total,
                           sem_regra=len(nao_confere), nao_confere=nao_confere,
                           conferidas=conferidas)


@app.route('/admin/comissoes-divergentes/corrigir', methods=['POST'])
@login_required
@admin_required
def comissoes_divergentes_corrigir():
    """Corrige em lote — só o que foi marcado, e só o que não tem trava."""
    ids = (request.json or {}).get('ids') or []
    conn = db()
    ok, falhou = 0, []
    for pid in ids:
        try:
            feito, msg = _recalcular_proposta(conn, int(pid), session.get('nome', 'admin'))
        except (TypeError, ValueError):
            continue
        if feito:
            ok += 1
        else:
            falhou.append({'id': pid, 'motivo': msg})
    conn.commit(); close_db(conn)
    return jsonify({'ok': True, 'corrigidas': ok, 'falharam': falhou})


@app.route('/proposta/<int:pid>/editar', methods=['POST'])
@login_required
@admin_required
def proposta_editar(pid):
    """Edição completa de propostas — todos os campos (admin)."""
    d = request.json or {}
    conn = db()
    p = conn.execute("SELECT * FROM propostas WHERE id=?", (pid,)).fetchone()
    if not p: close_db(conn); return jsonify({"ok": False}), 404
    
    nome_user = session.get('nome','admin')
    user_id = session.get('user_id')
    
    # Campos numéricos para conversão
    NUMERICOS = {'valor','total_vidas','dia_vencimento','num_parcelas','comissao_total_corretora','comissao_consultor','comissao_corretora_liquida'}
    
    MONETARIOS = ('valor','comissao_total_corretora','comissao_consultor','comissao_corretora_liquida')
    def conv(campo, v):
        if campo in NUMERICOS:
            if campo in MONETARIOS:
                return _num_brl(v)  # aceita '1.194,63' e '1194.63' sem virar 119463
            try: return int(str(v or '').strip() or 0)
            except: return 0
        return v
    
    mudou = []
    
    # Edição restrita a CAMPOS_EDITAVEIS (mantém compatibilidade)
    for campo, label in CAMPOS_EDITAVEIS.items():
        if campo in d:
            antes = p[campo] if campo in p.keys() else ''
            depois = conv(campo, d[campo])
            if str(antes or '') != str(depois or ''):
                conn.execute(f"UPDATE propostas SET {campo}=? WHERE id=?", (depois, pid))
                conn.execute("""INSERT INTO historico_proposta (proposta_id,usuario_id,usuario_nome,campo,valor_antes,valor_depois,criado_em)
                    VALUES (?,?,?,?,?,?,?)""", (pid, user_id, nome_user, label, str(antes or '—'), str(depois or '—'), datetime.now(TZ_SP)))
                mudou.append(label)
    
    # Edição expandida: campos adicionais fora de CAMPOS_EDITAVEIS
    CAMPOS_ADICIONAIS = {
        'razao_social': 'Razão Social',
        'cpf_titular': 'CPF Titular',
        'cnpj': 'CNPJ',
        'valor': 'Valor da Venda',
        'vigencia': 'Vigência',
        'modalidade': 'Modalidade',
        'tipo_pessoa': 'Tipo Pessoa',
        'adm_operadora': 'Operadora',
        'produto': 'Produto',
        'total_vidas': 'Total de Vidas',
        'regime_aplicado': 'Regime Aplicado',
        'observacoes': 'Observações',
        'campos_extras': 'Campos Extras (JSON)',
    }
    
    for campo, label in CAMPOS_ADICIONAIS.items():
        if campo in d and campo not in CAMPOS_EDITAVEIS:
            antes = p[campo] if campo in p.keys() else ''
            depois = conv(campo, d[campo])
            if str(antes or '') != str(depois or ''):
                conn.execute(f"UPDATE propostas SET {campo}=? WHERE id=?", (depois, pid))
                conn.execute("""INSERT INTO historico_proposta (proposta_id,usuario_id,usuario_nome,campo,valor_antes,valor_depois,criado_em)
                    VALUES (?,?,?,?,?,?,?)""", (pid, user_id, nome_user, label, str(antes or '—'), str(depois or '—'), datetime.now(TZ_SP)))
                mudou.append(label)
    
    # ── O QUE FAZ A COMISSÃO MUDAR ──
    # Antes só o VALOR disparava recálculo. Trocar a operadora — que muda o
    # percentual inteiro — não recalculava nada: a venda ficava com o número da
    # operadora antiga e o Dashboard somava esse número errado. Mesmo problema
    # com modalidade e tipo de pessoa, que decidem o plano (PME/PF/ADESÃO).
    def _mudou(campo, conv_num=False):
        if campo not in d:
            return False
        antes = p[campo] if campo in p.keys() else None
        depois = d[campo]
        if conv_num:
            return round(float(antes or 0), 2) != round(_num_brl(depois), 2)
        return str(antes or '').strip() != str(depois or '').strip()

    muda_comissao = (_mudou('valor', conv_num=True) or _mudou('adm_operadora')
                     or _mudou('modalidade') or _mudou('tipo_pessoa'))

    if muda_comissao:
        # Os valores NOVOS mandam. Ler p['adm_operadora'] aqui pegava a
        # operadora ANTIGA (p foi lido antes dos updates), então trocar de
        # operadora recalculava com o percentual da anterior.
        novo_valor = _num_brl(d['valor']) if 'valor' in d else float(p['valor'] or 0)
        operadora = d.get('adm_operadora') if 'adm_operadora' in d else p['adm_operadora']
        mod = d.get('modalidade') if 'modalidade' in d else p['modalidade']
        tipo_p = d.get('tipo_pessoa') if 'tipo_pessoa' in d else p['tipo_pessoa']
        regime = p['regime_aplicado']
        if True:
            # ERA 'prod_acum = 0 # Simplificado'. Editar o valor de UMA proposta
            # recalculava a comissao como se o consultor tivesse produzido ZERO
            # no mes — mesmo que ele ja tivesse batido N3 com outras vendas.
            # Cenario real: consultor bate nivel alto no mes; admin corrige um
            # erro de digitacao numa proposta (R$1.000,00 -> R$1.050,00); a
            # comissao inteira e regravada usando nivel 1, pagando a menos.
            # Mesma conta que a tela de detalhe ja usa pra mostrar o aviso de
            # comissao (linha ~9097): soma a producao das OUTRAS propostas do
            # mes (exclui esta, que esta sendo editada) e soma o valor NOVO.
            prod_acum = _producao_mes(conn, p['usuario_id'], p['mes_meta'], excluir_pid=pid) + novo_valor

            # Regra de sócio/gestor nasce com snapshot e não pode ser jogada no
            # motor de consultor por uma edição de valor. A alteração comercial
            # precisa de uma revisão própria, com as frações visíveis.
            if regime in ('socio_gestor_regra', 'socio_gestor_pendente'):
                # Venda de sócio/gestor NÃO passa pelo motor de consultor. Antes
                # a rota devolvia 409 e fechava a conexão sem commit — o que
                # descartava TODA a edição em silêncio, inclusive campos sem
                # relação com dinheiro, dizendo apenas que "o valor não foi
                # alterado". Agora ou recalcula pelo motor certo, ou recusa
                # dizendo exatamente o que trava e desfazendo de forma explícita.
                travas = _historico_travas(conn, pid)
                if travas:
                    try: conn.rollback()
                    except Exception: pass
                    close_db(conn)
                    return jsonify({"ok": False, "erro": (
                        "Esta venda de sócio/gestor já tem dinheiro em movimento, então "
                        "mudar operadora ou valor mudaria número que já foi pago ou conciliado. "
                        "NENHUMA alteração foi salva. Travas: " + ' '.join(travas))}), 409
                # Sem dinheiro em movimento: a regra é recongelada para a
                # operadora/plano NOVOS — o acordo antigo descrevia uma
                # operadora que esta venda não tem mais.
                cg = _gestor_calculo_inicial(conn, operadora, mod, tipo_p, novo_valor)
                if not cg or cg.get('falta_regra_gestor'):
                    try: conn.rollback()
                    except Exception: pass
                    close_db(conn)
                    falta = ' · '.join((cg or {}).get('falta_regra_gestor')
                                       or ['regra de sócio/gestor não cadastrada'])
                    return jsonify({"ok": False, "erro": (
                        f"Não há regra de sócio/gestor completa para {operadora} neste plano, "
                        f"então a comissão não pode ser recalculada. NENHUMA alteração foi salva. "
                        f"Falta: {falta}")}), 409
                calc = cg
                _gestor_congelar_snapshot(conn, pid, operadora, calc.get('plano') or '',
                                          p['usuario_id'], p['consultor'] or nome_user)
                mudou.append("Regra de sócio/gestor recongelada para a nova operadora")
            else:
                # Recalcular comissão do consultor.
                calc = calc_comissao(operadora, regime, prod_acum, novo_valor, mod, tipo_p)

            # Atualizar comissões na proposta
            conn.execute("""
                UPDATE propostas
                SET comissao_total_corretora=?, comissao_consultor=?, comissao_corretora_liquida=?,
                    num_parcelas=?, distribuicao_parcelas=?
                WHERE id=?
            """, (calc['total_corretora'], calc['consultor'], calc['liquido'],
                  calc['num_parcelas'], calc['dist_corretora'], pid))

            # Regenera só as parcelas ainda pendentes (protege parcelas já recebidas)
            pagas = conn.execute(
                "SELECT COUNT(*) n FROM parcelas WHERE proposta_id=? AND status<>'Pendente de receber'", (pid,)
            ).fetchone()['n']
            if pagas == 0:
                conn.execute("DELETE FROM parcelas WHERE proposta_id=?", (pid,))
                dia_venc_atual = p['dia_vencimento'] if 'dia_vencimento' in p.keys() else None
                for parc in gerar_parcelas(pid, p['vigencia'], calc, dia_venc_atual):
                    conn.execute("""INSERT INTO parcelas (proposta_id,numero,percentual,valor,valor_corretora,perc_cliente,data_prevista,status,competencia,mensalidade_ref,tipo_origem)
                        VALUES (?,?,?,?,?,?,?,?,?,?,'comissao')""", (parc['proposta_id'],parc['numero'],parc['percentual'],
                            parc['valor'],parc['valor_corretora'],parc['perc_cliente'],parc['data_prevista'],parc['status'],
                            parc['competencia'],parc['mensalidade_ref']))
                mudou.append("Parcelas recalculadas")
            else:
                mudou.append("Comissão recalculada (parcelas já em fluxo foram mantidas)")
    
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "mudou": mudou})


# ─── SOLICITAÇÃO DE EDIÇÃO (consultor pede, admin aprova) ─────────────────────────
@app.route('/proposta/<int:pid>/solicitar-edicao', methods=['POST'])
@login_required
def solicitar_edicao(pid):
    """Consultor envia pedido de alteração; fica Pendente até o admin decidir."""
    d = request.json or {}
    alteracoes = d.get('alteracoes') or {}   # {campo: novo_valor}
    if not alteracoes:
        return jsonify({"ok": False, "msg": "Nenhuma alteração informada."}), 400

    conn = db()
    p = conn.execute("SELECT * FROM propostas WHERE id=?", (pid,)).fetchone()
    if not p:
        close_db(conn); return jsonify({"ok": False, "msg": "Proposta não encontrada"}), 404

    # Consultor só solicita nas próprias propostas; admin pode editar direto (não usa isto)
    if session['perfil'] != 'admin' and p['usuario_id'] != session['user_id']:
        close_db(conn); return jsonify({"ok": False, "msg": "Sem permissão"}), 403

    # Monta diff legível: só campos que realmente mudam
    diff = {}
    for campo, novo in alteracoes.items():
        if campo not in CAMPOS_EDITAVEIS:
            continue
        atual = p[campo] if campo in p.keys() else ''
        if str(atual or '') != str(novo or ''):
            diff[campo] = {'label': CAMPOS_EDITAVEIS[campo], 'de': str(atual or '—'), 'para': str(novo or '—'), 'valor': novo}
    if not diff:
        close_db(conn); return jsonify({"ok": False, "msg": "Os valores enviados são iguais aos atuais."}), 400

    # Evita duplicar pedido pendente para a mesma proposta
    ja = conn.execute("SELECT id FROM solicitacoes_edicao WHERE proposta_id=? AND status='Pendente'", (pid,)).fetchone()
    if ja:
        close_db(conn); return jsonify({"ok": False, "msg": "Já existe uma solicitação pendente para esta proposta. Aguarde o admin avaliar."}), 400

    conn.execute("""INSERT INTO solicitacoes_edicao (proposta_id,usuario_id,usuario_nome,alteracoes,status,criado_em)
        VALUES (?,?,?,?,?,?)""", (pid, session['user_id'], session.get('nome','consultor'),
        json.dumps(diff, ensure_ascii=False), 'Pendente', datetime.now(TZ_SP)))
    # Registra no histórico da proposta
    conn.execute("""INSERT INTO historico_proposta (proposta_id,usuario_id,usuario_nome,campo,valor_antes,valor_depois,criado_em)
        VALUES (?,?,?,?,?,?,?)""", (pid, session['user_id'], session.get('nome','consultor'),
        'solicitacao_edicao', '', f"{len(diff)} campo(s) solicitado(s) para alteração", datetime.now(TZ_SP)))
    conn.commit(); close_db(conn)
    # AVISA QUEM VAI AVALIAR. O sistema respondia "o administrador vai avaliar"
    # e nao contava pra ninguem: nenhuma tela apontava pra fila, nao havia sino,
    # nao havia item de menu. O pedido ficava parado ate alguem tropecar nele.
    try:
        _notificar_admins('edicao_pendente',
                          f"{session.get('nome','Consultor')} pediu edição na proposta #{pid}",
                          f"{len(diff)} alteração(ões) aguardando sua avaliação.",
                          '/admin/solicitacoes-edicao')
    except Exception as e:
        app.logger.info(f"[SOLIC] falha ao notificar admins: {e}")
    return jsonify({"ok": True, "msg": f"Solicitação enviada ({len(diff)} alteração(ões)). O administrador vai avaliar."})


@app.route('/admin/solicitacoes-edicao')
@login_required
@admin_required
def listar_solicitacoes():
    """Lista solicitações de edição pendentes (admin)."""
    conn = db()
    rows = conn.execute("""SELECT se.*, p.razao_social
        FROM solicitacoes_edicao se JOIN propostas p ON p.id=se.proposta_id
        WHERE se.status='Pendente' ORDER BY se.criado_em DESC""").fetchall()
    close_db(conn)
    out = []
    for r in rows:
        d = dict(r)
        try: d['alteracoes_parsed'] = json.loads(r['alteracoes']) if r['alteracoes'] else {}
        except Exception: d['alteracoes_parsed'] = {}
        out.append(d)
    return jsonify({"ok": True, "solicitacoes": out, "total": len(out)})


@app.route('/admin/solicitacao-edicao/<int:sid>/resolver', methods=['POST'])
@login_required
@admin_required
def resolver_solicitacao(sid):
    """Admin aprova (aplica as mudanças) ou recusa uma solicitação."""
    d = request.json or {}
    acao = d.get('acao')  # 'aprovar' | 'recusar'
    motivo = (d.get('motivo') or '').strip()

    conn = db()
    s = conn.execute("SELECT * FROM solicitacoes_edicao WHERE id=?", (sid,)).fetchone()
    if not s:
        close_db(conn); return jsonify({"ok": False, "msg": "Solicitação não encontrada"}), 404
    if s['status'] != 'Pendente':
        close_db(conn); return jsonify({"ok": False, "msg": "Esta solicitação já foi resolvida."}), 400

    pid = s['proposta_id']
    try: alteracoes = json.loads(s['alteracoes']) if s['alteracoes'] else {}
    except Exception: alteracoes = {}

    if acao == 'aprovar':
        p = conn.execute("SELECT * FROM propostas WHERE id=?", (pid,)).fetchone()
        if not p:
            # A proposta foi excluída depois que a solicitação foi aberta e
            # antes de ser resolvida — sem isto, o loop abaixo quebra com 500
            # ao tentar ler p[campo] de um None.
            close_db(conn)
            return jsonify({"ok": False, "msg": "A proposta desta solicitação não existe mais (foi excluída). Recuse a solicitação em vez de aprovar."}), 409
        NUMERICOS = {'valor','total_vidas','dia_vencimento'}
        aplicados = []
        for campo, info in alteracoes.items():
            if campo not in CAMPOS_EDITAVEIS:
                continue
            novo = info.get('valor') if isinstance(info, dict) else info
            if campo in NUMERICOS:
                if campo == 'valor':
                    novo = _num_brl(novo)  # '1.194,63' e '1194.63' sem virar 119463
                else:
                    try: novo = int(str(novo or '').strip() or 0)
                    except: novo = 0
            antes = p[campo] if campo in p.keys() else ''
            conn.execute(f"UPDATE propostas SET {campo}=? WHERE id=?", (novo, pid))
            conn.execute("""INSERT INTO historico_proposta (proposta_id,usuario_id,usuario_nome,campo,valor_antes,valor_depois,criado_em)
                VALUES (?,?,?,?,?,?,?)""", (pid, session['user_id'], session.get('nome','admin'),
                CAMPOS_EDITAVEIS[campo], str(antes or '—'), str(novo or '—'), datetime.now(TZ_SP)))
            aplicados.append(CAMPOS_EDITAVEIS[campo])
        conn.execute("""UPDATE solicitacoes_edicao SET status='Aprovada', resolvido_em=?, resolvido_por=? WHERE id=?""",
            (datetime.now(TZ_SP), session.get('nome','admin'), sid))
        conn.commit(); close_db(conn)
        return jsonify({"ok": True, "msg": f"Aprovada. {len(aplicados)} campo(s) atualizado(s): {', '.join(aplicados)}."})

    elif acao == 'recusar':
        conn.execute("""UPDATE solicitacoes_edicao SET status='Recusada', motivo_recusa=?, resolvido_em=?, resolvido_por=? WHERE id=?""",
            (motivo or 'Sem motivo informado', datetime.now(TZ_SP), session.get('nome','admin'), sid))
        conn.execute("""INSERT INTO historico_proposta (proposta_id,usuario_id,usuario_nome,campo,valor_antes,valor_depois,criado_em)
            VALUES (?,?,?,?,?,?,?)""", (pid, session['user_id'], session.get('nome','admin'),
            'solicitacao_recusada', '', f"Solicitação de edição recusada. {('Motivo: '+motivo) if motivo else ''}", datetime.now(TZ_SP)))
        conn.commit(); close_db(conn)
        return jsonify({"ok": True, "msg": "Solicitação recusada."})

    close_db(conn)
    return jsonify({"ok": False, "msg": "Ação inválida."}), 400


