# ─── FLUXO DE CAIXA ──────────────────────────────────────────────────────────────
@app.route('/fluxo-caixa')
@login_required
def fluxo_caixa():
    conn = db(); uid = session['user_id']
    ciclo = ciclo_atual()
    eh_admin = session['perfil'] == 'admin'

    # PARCELA DE PROPOSTA ESTORNADA/EXCLUIDA NAO CONTA EM LUGAR NENHUM DESTA
    # TELA. /financeiro ja filtra isso em toda consulta; aqui nao filtrava em
    # NENHUMA — nem nos totais, nem no lote que decide o pagamento real. Uma
    # parcela ja 'Liberado para o corretor' de uma proposta estornada depois
    # continuava aparecendo pronta pra entrar no lote de PIX, sem aviso
    # nenhum: os dois paineis contavam historias diferentes, e este e o que
    # decide o dinheiro que sai. Mesmo predicado usado em todo o resto do
    # arquivo (`_conferencia_mes`, `financeiro()`, etc).
    # Proposta estornada some do fluxo — MENOS a linha do estorno em si. Se ela
    # também sumisse, o débito que o consultor precisa devolver ficaria
    # invisível justamente na tela onde o dinheiro dele é somado, e o abatimento
    # nunca aconteceria. Todas as consultas abaixo já usam o alias `pa`.
    _AVIVA = ("p.status <> 'Excluída' AND (COALESCE(p.estornada,0)=0"
              " OR COALESCE(pa.tipo_origem,'')='estorno')")

    if eh_admin:
        # Totais por status
        totais = {}
        for s in ["Pendente de receber","Recebido e não repassado","Liberado para o corretor","Pago ao corretor"]:
            totais[s] = conn.execute(f"""
                SELECT COALESCE(SUM(pa.valor),0) v FROM parcelas pa
                JOIN propostas p ON p.id=pa.proposta_id
                WHERE pa.status=? AND {_AVIVA}""", (s,)).fetchone()['v']
        totais['antecipacoes'] = conn.execute(f"""
            SELECT COALESCE(SUM(pa.valor),0) v FROM parcelas pa
            JOIN propostas p ON p.id=pa.proposta_id
            WHERE pa.status IN ('Antecipação - Aguardando ADM','Antecipação Solicitada à Operadora')
              AND {_AVIVA}""").fetchone()['v']
        totais['total_em_aberto'] = sum(totais[s] for s in ["Pendente de receber","Recebido e não repassado","Liberado para o corretor"])

        # Antecipações aguardando aprovação ADM
        antecipacoes = conn.execute(f"""
            SELECT pa.*, p.razao_social, p.consultor, p.adm_operadora, p.valor as val_proposta
            FROM parcelas pa JOIN propostas p ON p.id=pa.proposta_id
            WHERE pa.status='Antecipação - Aguardando ADM' AND {_AVIVA} ORDER BY pa.id DESC
        """).fetchall()

        # Lote do ciclo atual (liberados para o corretor)
        lote = conn.execute(f"""
            SELECT pa.*, p.razao_social, p.consultor, p.adm_operadora, p.id as proposta_id,
                   u.chave_pix
            FROM parcelas pa
            JOIN propostas p ON p.id=pa.proposta_id
            LEFT JOIN usuarios u ON u.id=p.usuario_id
            WHERE pa.status='Liberado para o corretor' AND {_AVIVA} ORDER BY p.consultor, pa.id
        """).fetchall()

        # Todos os recebidos aguardando repasse
        recebidos = conn.execute(f"""
            SELECT pa.*, p.razao_social, p.consultor, p.adm_operadora, p.id as proposta_id
            FROM parcelas pa JOIN propostas p ON p.id=pa.proposta_id
            WHERE pa.status='Recebido e não repassado' AND {_AVIVA} ORDER BY pa.id DESC
        """).fetchall()

        # Histórico de pagos (últimos 30)
        pagos = conn.execute(f"""
            SELECT pa.*, p.razao_social, p.consultor, p.adm_operadora
            FROM parcelas pa JOIN propostas p ON p.id=pa.proposta_id
            WHERE pa.status='Pago ao corretor' AND {_AVIVA} ORDER BY pa.id DESC LIMIT 30
        """).fetchall()

        regras_faltando = _gestor_regras_faltando(conn)
        fin_visao = _fin_visao(conn)
        close_db(conn)
        return render_template('fluxo_caixa.html', ciclo=ciclo, totais=totais,
                               antecipacoes=antecipacoes, lote=lote,
                               recebidos=recebidos, pagos=pagos,
                               regras_faltando=regras_faltando, fin_visao=fin_visao,
                               status_fluxo=STATUS_FLUXO)
    else:
        # Visão do consultor. Mesmo filtro: sem ele, o consultor via (e
        # esperava receber) parcela de proposta ja estornada na propria tela.
        a_receber = conn.execute(f"""SELECT pa.*, p.razao_social, p.adm_operadora, p.id as proposta_id
            FROM parcelas pa JOIN propostas p ON p.id=pa.proposta_id
            WHERE p.usuario_id=? AND pa.status='Liberado para o corretor' AND {_AVIVA} ORDER BY pa.id""",(uid,)).fetchall()
        em_analise = conn.execute(f"""SELECT pa.*, p.razao_social, p.adm_operadora, p.id as proposta_id
            FROM parcelas pa JOIN propostas p ON p.id=pa.proposta_id
            WHERE p.usuario_id=? AND pa.status NOT IN ('Liberado para o corretor','Pago ao corretor')
            AND {_AVIVA} ORDER BY pa.id DESC""",(uid,)).fetchall()
        pagos_consul = conn.execute(f"""SELECT pa.*, p.razao_social, p.adm_operadora
            FROM parcelas pa JOIN propostas p ON p.id=pa.proposta_id
            WHERE p.usuario_id=? AND pa.status='Pago ao corretor' AND {_AVIVA} ORDER BY pa.id DESC LIMIT 30""",(uid,)).fetchall()
        total_a_receber = sum(p['valor'] for p in a_receber)
        total_pago = sum(p['valor'] for p in pagos_consul)
        # Fixo do mês do consultor (se houver)
        mes = competencia_atual()
        fixo_mes = conn.execute("""SELECT COALESCE(SUM(valor),0) v FROM lancamentos
            WHERE tipo='fixo' AND usuario_id=? AND data_competencia=?""", (uid, mes)).fetchone()['v']
        fixo_parcelas = conn.execute("""SELECT descricao,valor,data_lancamento,status FROM lancamentos
            WHERE tipo='fixo' AND usuario_id=? AND data_competencia=? ORDER BY data_lancamento""", (uid, mes)).fetchall()
        close_db(conn)
        return render_template('fluxo_caixa_consultor.html', ciclo=ciclo,
                               a_receber=a_receber, em_analise=em_analise,
                               pagos=pagos_consul, total_a_receber=total_a_receber,
                               total_pago=total_pago, fixo_mes=fixo_mes, fixo_parcelas=fixo_parcelas)

# ─── BI ──────────────────────────────────────────────────────────────────────────
def _so_digitos(v):
    return re.sub(r'\D', '', str(v or ''))


def achar_lead_da_proposta(conn, prop):
    """Descobre a qual lead do CRM uma proposta pertence. Devolve (lead_id, criterio)
    ou (None, motivo). Ordem dos critérios é do mais forte pro mais fraco, e
    AMBIGUIDADE NUNCA VIRA VÍNCULO: se dois leads batem, prefere não ligar a ligar
    errado — vínculo errado contamina comissão, origem de mídia e relatório de
    perda de uma vez, e ninguém percebe.

    1) CNPJ: identificador único de verdade, o mais seguro pra PME
    2) telefone exato (tel_resp_contrato / tel_resp_negociacao vs telefone_norm)
    3) telefone pelos últimos 8 dígitos — cobre a variação do 9º dígito, que é a
       diferença mais comum entre o número salvo no CRM e o digitado na proposta
    """
    def _unico(sql, params):
        rows = conn.execute(sql, params).fetchall()
        ids = {r['id'] for r in rows}
        if len(ids) == 1:
            return ids.pop()
        return None if not ids else 'AMBIGUO'

    cnpj = _so_digitos(prop['cnpj'] if 'cnpj' in prop.keys() else '')
    if len(cnpj) == 14:
        # Procura nas duas casas: a coluna legada e o campo personalizado novo.
        r = _unico("""SELECT DISTINCT l.id FROM crm_leads l
                      LEFT JOIN crm_lead_campos lc ON lc.lead_id = l.id
                      LEFT JOIN crm_campos c ON c.id = lc.campo_id AND c.chave='cnpj'
                      WHERE REPLACE(REPLACE(REPLACE(COALESCE(l.qual_cnpj,''),'.',''),'/',''),'-','')=?
                         OR REPLACE(REPLACE(REPLACE(COALESCE(lc.valor,''),'.',''),'/',''),'-','')=?""",
                  (cnpj, cnpj))
        if r == 'AMBIGUO':
            return None, 'ambiguo_cnpj'
        if r:
            return r, 'cnpj'

    tels = []
    for campo in ('tel_resp_contrato', 'tel_resp_negociacao'):
        if campo in prop.keys():
            tn = _normalizar_telefone(str(prop[campo] or ''))
            if tn and tn not in tels:
                tels.append(tn)
    for tn in tels:
        r = _unico("SELECT id FROM crm_leads WHERE telefone_norm=?", (tn,))
        if r == 'AMBIGUO':
            return None, 'ambiguo_telefone'
        if r:
            return r, 'telefone'
    for tn in tels:
        suf, ddd = tn[-8:], tn[:2]
        if len(suf) != 8 or len(ddd) != 2:
            continue
        # AMARRADO AO MESMO DDD, igual _buscar_lead_por_telefone. Sem isso,
        # (11) 9681-0150 e (19) 9681-0150 viravam a mesma pessoa — e aqui o
        # estrago é pior que numa busca: o vínculo é GRAVADO, e passa a mandar a
        # comissão dessa venda pro gclid de outra pessoa no Google Ads.
        r = _unico("SELECT id FROM crm_leads WHERE telefone_norm LIKE ? AND telefone_norm LIKE ?",
                   ('%' + suf, ddd + '%'))
        if r == 'AMBIGUO':
            return None, 'ambiguo_telefone_sufixo'
        if r:
            return r, 'telefone_sufixo'
    return None, 'sem_lead'


def vincular_proposta_lead(conn, proposta_id, prop=None, lead_id_certo=None):
    """Amarra a proposta ao lead e fecha o elo dos dois lados. Nunca sobrescreve um
    vínculo existente: se alguém corrigiu à mão, a heurística não desfaz."""
    if prop is None:
        prop = conn.execute("SELECT * FROM propostas WHERE id=?", (proposta_id,)).fetchone()
    if not prop:
        return None, 'proposta_inexistente'
    if 'lead_id' in prop.keys() and prop['lead_id']:
        return prop['lead_id'], 'ja_vinculado'
    # Quando o id do lead é CONHECIDO (proposta aberta a partir da ficha, via
    # /nova-proposta?lead=N), usa ele. Adivinhar por telefone/CNPJ justamente no
    # caso em que a resposta certa estava na mão é como se perde o gclid: basta o
    # responsável do contrato ter telefone diferente do lead pra dar 'sem_lead'.
    if lead_id_certo:
        try:
            lid_certo = int(lead_id_certo)
        except (TypeError, ValueError):
            lid_certo = 0
        if lid_certo and conn.execute("SELECT 1 FROM crm_leads WHERE id=?", (lid_certo,)).fetchone():
            conn.execute("UPDATE propostas SET lead_id=?, lead_vinculo=? WHERE id=?",
                         (lid_certo, 'informado', proposta_id))
            conn.execute("UPDATE crm_leads SET proposta_id=? WHERE id=? AND (proposta_id IS NULL OR proposta_id=0)",
                         (proposta_id, lid_certo))
            return lid_certo, 'informado'
    lid, criterio = achar_lead_da_proposta(conn, prop)
    if not lid:
        return None, criterio
    conn.execute("UPDATE propostas SET lead_id=?, lead_vinculo=? WHERE id=?", (lid, criterio, proposta_id))
    # Elo recíproco: crm_leads.proposta_id existe desde sempre e vive vazio.
    # Só preenche se estiver em branco — o lead pode ter mais de uma proposta e o
    # primeiro fechamento é o que interessa como "virou venda".
    conn.execute("UPDATE crm_leads SET proposta_id=? WHERE id=? AND (proposta_id IS NULL OR proposta_id=0)",
                 (proposta_id, lid))
    return lid, criterio


# ═══════════════ CONVERSÃO OFFLINE — GOOGLE ADS ═══════════════════════════════
# O problema que isso resolve: hoje o Google otimiza pra quem PREENCHE FORMULÁRIO,
# porque é a única conversão que ele enxerga. Devolvendo a venda com o valor real,
# ele passa a otimizar por quem COMPRA — que é outra pessoa. O gclid já era
# capturado na entrada do lead e nunca saía do banco.
#
# Sem biblioteca google-ads (dependência pesada, ~30MB): a API REST resolve com
# requests, que o projeto já usa.
#
# VERSÃO: o Google aposenta cada versão da API ~1 ano depois de lançar, e a
# aposentada responde 404 — todo envio falha de uma vez, sem aviso. Estava
# travada em v18, que já estava morta antes do primeiro envio real (medido em
# 04/08/2026: v15..v19 = 404; v20..v25 = vivas). Por isso fica em env: quando o
# Google aposentar esta, troca a variável e pronto, sem deploy de código.
_ADS_API_VERSAO = (os.environ.get('GOOGLE_ADS_API_VERSAO') or 'v25').strip() or 'v25'
_ADS_API = f'https://googleads.googleapis.com/{_ADS_API_VERSAO}'
# ONDE A CONVERSÃO É ENTREGUE HOJE. O caminho antigo (uploadClickConversions, na
# API do Google Ads) foi FECHADO pra integração nova — medido em 04/08/2026, ele
# responde CUSTOMER_NOT_ALLOWLISTED_FOR_THIS_FEATURE com a mensagem "New
# integrations for uploading click conversions should use the Data Manager API".
# Quem já usava continua; quem está começando, como a Serenus, só entra por aqui.
_DM_API = 'https://datamanager.googleapis.com/v1'
# Os dois escopos, porque são dois trabalhos diferentes com o MESMO refresh token:
# 'adwords' lê a conta e a ação de conversão (diagnóstico), 'datamanager' entrega
# a conversão. Um refresh token gerado só com 'adwords' autentica e depois toma
# 403 na entrega — foi exatamente o que aconteceu no primeiro teste.
_ADS_ESCOPOS = ('https://www.googleapis.com/auth/adwords',
                'https://www.googleapis.com/auth/datamanager')
# Teto de tentativas por conversão. Erro de rede/token é passageiro e merece
# retry; erro permanente não pode ficar batendo na porta do Google pra sempre.
_ADS_MAX_TENTATIVAS = int(os.environ.get('GOOGLE_ADS_MAX_TENTATIVAS', '4') or 4)
# Janela do Google entre o CLIQUE e a conversão. Venda mais velha que isso é
# recusada — enfileirar não adianta, só enche a fila de falha permanente.
_ADS_JANELA_DIAS = int(os.environ.get('GOOGLE_ADS_JANELA_DIAS', '90') or 90)


def _ads_refresh_token_guardado():
    """Refresh token gerado pela autorização feita DENTRO do JOB.

    Existe porque o token do env foi emitido só com o escopo de leitura do
    Google Ads, e entregar conversão exige um segundo escopo. Trocar isso pelo
    env significaria refazer o passo à mão toda vez que o Google expirar o
    consentimento; guardado aqui, virar a chave é um botão."""
    try:
        conn = db()
        r = conn.execute("SELECT valor FROM config WHERE chave='google_ads_refresh_token'").fetchone()
        close_db(conn)
        return ((r['valor'] if r else '') or '').strip()
    except Exception:
        return ''


def _ads_config():
    """Credenciais do Google Ads via env. Devolve (config, faltando) — a lista do
    que falta é o que a tela de diagnóstico mostra, em vez de só falhar calada."""
    campos = {
        'client_id': 'GOOGLE_ADS_CLIENT_ID',
        'client_secret': 'GOOGLE_ADS_CLIENT_SECRET',
        'refresh_token': 'GOOGLE_ADS_REFRESH_TOKEN',
        'developer_token': 'GOOGLE_ADS_DEVELOPER_TOKEN',
        'customer_id': 'GOOGLE_ADS_CUSTOMER_ID',
        'conversion_action_id': 'GOOGLE_ADS_CONVERSION_ACTION_ID',
    }
    cfg, faltando = {}, []
    for k, env in campos.items():
        v = (os.environ.get(env) or '').strip()
        if not v:
            faltando.append(env)
        cfg[k] = v
    # O token autorizado no JOB tem os DOIS escopos e por isso vence o do env,
    # que só sabe ler. Se ninguém autorizou ainda, fica o do env.
    guardado = _ads_refresh_token_guardado()
    if guardado:
        cfg['refresh_token'] = guardado
        if 'GOOGLE_ADS_REFRESH_TOKEN' in faltando:
            faltando.remove('GOOGLE_ADS_REFRESH_TOKEN')
    # Só dígitos: o Google mostra o id como 123-456-7890 e é fácil colar assim
    cfg['customer_id'] = re.sub(r'\D', '', cfg['customer_id'])
    cfg['login_customer_id'] = re.sub(r'\D', '', (os.environ.get('GOOGLE_ADS_LOGIN_CUSTOMER_ID') or ''))
    return cfg, faltando


def _ads_token(cfg):
    """Troca o refresh_token por um access_token. Vale ~1h; não guardo em cache
    porque o envio é em lote e raro — pedir um token por rodada é mais simples
    que administrar expiração, e o custo é uma requisição."""
    r = _requests.post('https://oauth2.googleapis.com/token', timeout=20, data={
        'client_id': cfg['client_id'], 'client_secret': cfg['client_secret'],
        'refresh_token': cfg['refresh_token'], 'grant_type': 'refresh_token'})
    if r.status_code != 200:
        raise RuntimeError(f"OAuth falhou ({r.status_code}): {r.text[:300]}")
    tok = (r.json() or {}).get('access_token')
    if not tok:
        raise RuntimeError("OAuth não devolveu access_token")
    return tok


def _dm_evento(c):
    """Uma conversão no formato da Data Manager API.

    Campos conferidos no discovery oficial da API (não em documentação de
    terceiro): `adIdentifiers.gclid|gbraid|wbraid`, `eventTimestamp` (RFC3339
    com fuso), `conversionValue`, `currency`, `transactionId`.

    transactionId é o que era orderId no caminho antigo: identidade da conversão
    do lado do Google. Sem ele, reenvio conta a venda duas vezes."""
    ev = {'eventTimestamp': _conversao_dt_sp(c['conversao_em']).isoformat(timespec='seconds'),
          'eventSource': 'WEB',
          'conversionValue': float(c['valor'] or 0),
          'currency': c['moeda'] or 'BRL',
          'transactionId': f"job-proposta-{c['proposta_id']}",
          'consent': {'adUserData': 'CONSENT_GRANTED', 'adPersonalization': 'CONSENT_GRANTED'}}
    tipo = (c['click_tipo'] or 'gclid')
    ev['adIdentifiers'] = {tipo if tipo in ('gclid', 'gbraid', 'wbraid') else 'gclid': c['click_id']}
    return ev


def _dm_destino(cfg):
    """Pra onde vai: a conta do Google Ads e, dentro dela, a ação de conversão."""
    return [{'operatingAccount': {'accountType': 'GOOGLE_ADS', 'accountId': cfg['customer_id']},
             'productDestinationId': cfg['conversion_action_id']}]


def _dm_erro_legivel(status, corpo):
    """Traduz o erro do Google pra uma frase que diz o que fazer."""
    alto = (corpo or '').upper()
    if 'ACCESS_TOKEN_SCOPE_INSUFFICIENT' in alto or 'INSUFFICIENT AUTHENTICATION SCOPES' in alto:
        return ('O login funciona, mas foi autorizado só para ler o Google Ads — não para entregar '
                'conversão. Gere um refresh token novo autorizando também o escopo '
                'https://www.googleapis.com/auth/datamanager e substitua GOOGLE_ADS_REFRESH_TOKEN.')
    if 'SERVICE_DISABLED' in alto or ('DATAMANAGER.GOOGLEAPIS.COM' in alto and 'DISABLED' in alto):
        return ('A Data Manager API não está habilitada no projeto do Google Cloud desta chave. '
                'Habilite "Data Manager API" no console e tente de novo.')
    if 'PERMISSION_DENIED' in alto:
        return ('A conta do Google Ads existe, mas este login não tem permissão de gravar nela. '
                'Confira se o usuário que autorizou tem acesso de administrador à conta.')
    if status == 404:
        return 'Conta ou ação de conversão não encontrada — confira o Customer ID e o Conversion Action ID.'

    try:
        dados = json.loads(corpo) if corpo else {}
        err = dados.get('error') or {}
        msg = err.get('message') or ''
        details = err.get('details') or []
        violacoes = []
        for d in details:
            for f in d.get('fieldViolations') or []:
                violacoes.append(f"{f.get('field')}: {f.get('description')}")
        if violacoes:
            return f"HTTP {status}: {'; '.join(violacoes)}"
        if msg and msg != 'There was a problem with the request.':
            return f"HTTP {status}: {msg}"
    except Exception:
        pass

    return f'HTTP {status}: {(corpo or "")[:350]}'


def _ads_click_id_do_lead(conn, lead_id):
    """(id, tipo) do clique. gclid é o comum; gbraid/wbraid vêm de iOS e de app,
    onde o Google não entrega gclid — sem eles a conversão do iPhone se perde,
    e iPhone é metade do tráfego."""
    if not lead_id:
        return None, None
    lead = conn.execute("SELECT gclid, dados_extras FROM crm_leads WHERE id=?", (lead_id,)).fetchone()
    if not lead:
        return None, None
    g = (lead['gclid'] or '').strip()
    if g:
        return g, 'gclid'
    for chave in ('gclid', 'gbraid', 'wbraid'):
        v = _campo_de_midia(lead['dados_extras'], chave)
        if v:
            return v, chave
    return None, None


# ═══════════════ CONVERSAO OFFLINE PRA META ═══════════════
# Mesmo raciocinio do Google: o anuncio otimiza pelo que a gente devolve. Se so
# devolvemos "virou lead", a Meta aprende a trazer quem PREENCHE FORMULARIO. Se
# devolvemos a venda, ela aprende a trazer quem COMPRA — que e outra pessoa, e a
# diferenca entre CAC caindo e CAC subindo com o mesmo orcamento.
#
# A Meta usa a Conversions API: um POST por lote no dataset (pixel). O que casa o
# evento com o clique e o `fbc`, montado a partir do fbclid — que o JOB ja captura
# na ingestao (_MIDIA_CAMINHOS) desde antes disto existir.
_META_API_VERSAO = os.environ.get('META_API_VERSAO', 'v21.0').strip() or 'v21.0'


def _meta_config():
    """Credenciais da Meta via env. Devolve (config, faltando) — a lista do que
    falta e o que a tela mostra, em vez de falhar calada."""
    campos = {'pixel_id': 'META_PIXEL_ID', 'access_token': 'META_ACCESS_TOKEN'}
    cfg, faltando = {}, []
    for k, env in campos.items():
        v = (os.environ.get(env) or '').strip()
        if not v:
            faltando.append(env)
        cfg[k] = v
    # Opcional: codigo de teste do Events Manager, pra conferir sem sujar o dado.
    cfg['test_event_code'] = (os.environ.get('META_TEST_EVENT_CODE') or '').strip()
    return cfg, faltando


def _meta_hash(v):
    """SHA-256 do dado normalizado, como a Meta exige. E-mail e telefone melhoram
    MUITO o casamento quando o fbclid sozinho nao basta — e vao hasheados, entao
    o dado do cliente nunca sai daqui em claro."""
    v = (v or '').strip().lower()
    if not v:
        return None
    return hashlib.sha256(v.encode('utf-8')).hexdigest()


def _meta_fbc(fbclid, quando):
    """Formato exigido: 'fb.1.<timestamp_ms>.<fbclid>'. Sem isso a Meta nao liga
    o evento ao clique e a conversao vira dado solto."""
    if not fbclid:
        return None
    dt = _parse_dt_seguro(quando) if quando else None
    if not dt:
        dt = datetime.now(TZ_SP)
    if dt.tzinfo is None:
        dt = TZ_SP.localize(dt)
    return f"fb.1.{int(dt.timestamp() * 1000)}.{fbclid}"


def _meta_click_do_lead(conn, lead_id):
    """(fbclid, facebook_lead_id) do lead — os DOIS jeitos da Meta identificar
    quem clicou, pra dois tipos de anuncio diferentes que nao se misturam.

    fbclid: anuncio que levou a uma landing (clique de verdade, formato
    'fb.1.<timestamp>.<fbclid>' pro campo `fbc`).
    facebook_lead_id: Formulario Instantaneo — a pessoa preenche dentro do
    proprio Facebook/Instagram, nunca sai pra lugar nenhum, entao nunca existe
    fbclid. Vai cru (sem formatacao, sem hash) no campo `lead_id`.

    Usa `_ler_do_extras` direto (nao `_campo_de_midia`) de proposito: aquele
    alias junta fbclid e facebook_lead_id pra tela de exibicao generica (onde
    "algum id de clique" basta), mas aqui os dois precisam ir pro campo CERTO
    do payload da Meta — misturar um formato no outro faz a Meta recusar o
    evento ou nao casar com ninguem."""
    if not lead_id:
        return None, None
    lead = conn.execute("SELECT dados_extras FROM crm_leads WHERE id=?", (lead_id,)).fetchone()
    if not lead:
        return None, None
    extras = lead['dados_extras']
    fbclid = _ler_do_extras(extras, 'click.fbclid') or _ler_do_extras(extras, 'fbclid') or None
    fb_lead_id = _ler_do_extras(extras, 'click.facebook_lead_id') or _ler_do_extras(extras, 'facebook_lead_id') or None
    return fbclid, fb_lead_id


def _meta_enfileirar(conn, proposta_id, motivo='venda confirmada'):
    """Registra a venda como conversao A ENVIAR pra Meta. Idempotente pelo UNIQUE
    em proposta_id. Mesmas guardas do Google, pelos mesmos motivos:
    'sem_clique' nao e definitivo (vira pendente quando o fbclid aparecer), e o
    que ja foi enviado NAO volta pra fila — reenviar conta a venda duas vezes."""
    prop = conn.execute("SELECT * FROM propostas WHERE id=?", (proposta_id,)).fetchone()
    if not prop:
        return None, 'proposta inexistente'
    ja = conn.execute("SELECT * FROM meta_conversoes WHERE proposta_id=?", (proposta_id,)).fetchone()
    if ja and ja['status'] in ('enviada', 'pendente'):
        return dict(ja), 'já registrada'
    if ja and (ja['enviado_em'] or ja['status'] == 'retratar'):
        conn.execute("UPDATE meta_conversoes SET detalhe=? WHERE proposta_id=?",
                     ('reativada após envio — ajuste manual no Events Manager, não reenviar', proposta_id))
        return dict(ja), 'ja_enviada_nao_reenvia'
    lead_id = prop['lead_id'] if 'lead_id' in prop.keys() else None
    fbclid, fb_lead_id = _meta_click_do_lead(conn, lead_id)
    valor = _ads_valor_da_proposta(prop)   # mesma regua do Google: receita, nao mensalidade
    # PENDENTE com QUALQUER UM dos dois identificadores — sao dois jeitos de
    # achar a mesma pessoa. Pra Serenus, na pratica, e sempre facebook_lead_id
    # (Lead Ads); fbclid fica pronto pro dia que um anuncio levar a uma landing.
    status = 'pendente' if (fbclid or fb_lead_id) else 'sem_clique'
    agora = _agora_sp()
    quando_venda = (prop['criado_em'] if 'criado_em' in prop.keys() else None) or agora
    # event_id estavel: se o mesmo evento subir duas vezes (retentativa, deploy no
    # meio do lote), a Meta deduplica em vez de contar a venda dobrada.
    event_id = f"job-venda-{proposta_id}"
    if ja:
        conn.execute("""UPDATE meta_conversoes SET lead_id=?, fbclid=?, facebook_lead_id=?, valor=?,
                        status=?, detalhe=?, conversao_em=?, event_id=? WHERE proposta_id=?""",
                     (lead_id, fbclid, fb_lead_id, valor, status, motivo, quando_venda, event_id, proposta_id))
    else:
        conn.execute("""INSERT INTO meta_conversoes
            (proposta_id, lead_id, fbclid, facebook_lead_id, valor, conversao_em, status, detalhe, event_id, criado_em)
            VALUES (?,?,?,?,?,?,?,?,?,?)""",
            (proposta_id, lead_id, fbclid, fb_lead_id, valor, quando_venda, status, motivo, event_id, agora))
    return dict(conn.execute("SELECT * FROM meta_conversoes WHERE proposta_id=?",
                             (proposta_id,)).fetchone()), status


def _ads_valor_da_proposta(prop):
    """Valor mandado ao Google. Padrão: comissão bruta da corretora — é a RECEITA
    que a venda gera. Mandar a mensalidade infla o número (não é nosso dinheiro) e
    mandar o líquido subestima a capacidade de pagar mídia. Ajustável por env pra
    quem preferir outra régua."""
    base = (os.environ.get('GOOGLE_ADS_VALOR_BASE') or 'comissao_bruta').strip()
    mapa = {
        'comissao_bruta': 'comissao_total_corretora',
        'comissao_liquida': 'comissao_corretora_liquida',
        'producao': 'valor',
    }
    col = mapa.get(base, 'comissao_total_corretora')
    try:
        return round(float(prop[col] or 0), 2)
    except Exception:
        return 0.0


def _ads_enfileirar(conn, proposta_id, motivo='venda confirmada'):
    """Registra a venda como conversão A ENVIAR. Idempotente pelo UNIQUE em
    proposta_id: chamar de novo não duplica, só devolve o que já existe."""
    prop = conn.execute("SELECT * FROM propostas WHERE id=?", (proposta_id,)).fetchone()
    if not prop:
        return None, 'proposta inexistente'
    # 'sem_clique' NÃO é definitivo: é o estado normal de toda venda antiga no
    # momento do backfill, e vira 'pendente' assim que o vínculo lead↔proposta ou
    # o gclid aparecerem. Tratar como final fazia a tela dizer "0 fora da fila"
    # enquanto essas vendas nunca seriam enviadas.
    ja = conn.execute("SELECT * FROM google_ads_conversoes WHERE proposta_id=?", (proposta_id,)).fetchone()
    if ja and ja['status'] in ('enviada', 'pendente'):
        return dict(ja), 'já registrada'
    # O que JÁ FOI ENVIADO uma vez não volta pra fila. Sem esta guarda, uma venda
    # que caiu (virou 'retratar') e depois voltou pra Emitida/Ativa era reenfileirada
    # como 'pendente' — apagando a marca de retratação e subindo a MESMA conversão
    # de novo, contada duas vezes pelo Google.
    if ja and (ja['enviado_em'] or ja['status'] == 'retratar'):
        conn.execute("""UPDATE google_ads_conversoes SET detalhe=? WHERE proposta_id=?""",
                     ('reativada após envio — precisa de ajuste manual no Google, não reenviar',
                      proposta_id))
        return dict(ja), 'ja_enviada_nao_reenvia'
    lead_id = prop['lead_id'] if 'lead_id' in prop.keys() else None
    click_id, tipo = _ads_click_id_do_lead(conn, lead_id)
    valor = _ads_valor_da_proposta(prop)
    # Sem clique não há o que devolver: a venda não veio de anúncio, ou veio antes
    # do gclid passar a ser capturado. Fica gravada como 'sem_clique' de propósito,
    # pra aparecer no diagnóstico em vez de sumir.
    status = 'pendente' if click_id else 'sem_clique'
    quando = _agora_sp()
    # FORA DA JANELA DO GOOGLE. Ele só casa a conversão com o clique dentro de
    # ~90 dias. Mandar venda mais velha é recusa garantida — e no backfill isso
    # é a base histórica inteira falhando em bloco, escondendo as recusas que
    # realmente importam. Fica com status próprio, visível, sem tentar.
    _quando_venda_dt = _conversao_dt_sp(
        (prop['criado_em'] if 'criado_em' in prop.keys() else None) or quando)
    if click_id and (datetime.now(TZ_SP) - _quando_venda_dt).days > _ADS_JANELA_DIAS:
        status = 'fora_da_janela'
        motivo = (f"venda de {_quando_venda_dt.strftime('%d/%m/%Y')} — passou dos "
                  f"{_ADS_JANELA_DIAS} dias que o Google aceita entre o clique e a conversão")
    # A conversão aconteceu quando a VENDA aconteceu, não quando alguém apertou o
    # botão. No backfill da base histórica isso era a diferença entre reportar a
    # data certa e mandar tudo com a data de hoje — o que distorce a atribuição e
    # ainda faz o Google recusar em massa, porque o clique fica fora da janela.
    quando_venda = (prop['criado_em'] if 'criado_em' in prop.keys() else None) or quando
    if ja:
        conn.execute("""UPDATE google_ads_conversoes SET lead_id=?, click_id=?, click_tipo=?,
                        valor=?, status=?, detalhe=?, conversao_em=? WHERE proposta_id=?""",
                     (lead_id, click_id, tipo, valor, status, motivo, quando_venda, proposta_id))
    else:
        conn.execute("""INSERT INTO google_ads_conversoes
            (proposta_id, lead_id, click_id, click_tipo, valor, conversao_em, status, detalhe, criado_em)
            VALUES (?,?,?,?,?,?,?,?,?)""",
            (proposta_id, lead_id, click_id, tipo, valor, quando_venda, status, motivo, quando))
    return dict(conn.execute("SELECT * FROM google_ads_conversoes WHERE proposta_id=?",
                             (proposta_id,)).fetchone()), status


def _ads_data_conversao(valor, ja_em_sp=False):
    """Formato exigido: 'yyyy-mm-dd hh:mm:ss+hh:mm'. Sem o fuso o Google recusa.

    ARMADILHA DO FUSO: propostas.criado_em nasce do DEFAULT CURRENT_TIMESTAMP,
    que no Postgres do Railway (sessão em UTC) e no SQLite grava UTC — mas a
    coluna não tem fuso, então volta como hora "solta". Carimbar isso como -03:00
    empurra a venda 3 horas PRA FRENTE: a de agora vira uma conversão no futuro
    (o Google recusa) e a da noite pula pro dia seguinte (atribuição no dia
    errado). `ja_em_sp=True` é pra valor que veio de _agora_sp(), esse sim já
    em horário de São Paulo.

    Nunca devolve data no futuro: se der, usa agora. Conversão adiantada é
    recusada em bloco, e um relógio fora de sincronia não pode derrubar o lote."""
    dt = _conversao_dt_sp(valor, ja_em_sp=ja_em_sp)
    return dt.strftime('%Y-%m-%d %H:%M:%S%z')[:-2] + ':' + dt.strftime('%z')[-2:]


def _conversao_dt_sp(valor, ja_em_sp=False):
    """Momento da conversão como datetime COM fuso de São Paulo. Ver a armadilha
    documentada em _ads_data_conversao — vale igual pra Meta, que manda o mesmo
    instante como epoch e erraria 3 horas do mesmo jeito."""
    dt = _parse_dt_seguro(valor) if valor else None
    if not dt:
        return datetime.now(TZ_SP)
    if dt.tzinfo is None:
        dt = TZ_SP.localize(dt) if ja_em_sp else pytz.utc.localize(dt).astimezone(TZ_SP)
    agora = datetime.now(TZ_SP)
    return agora if dt > agora else dt


# ═══════════════ GASTO DE MIDIA (LEITURA PURA) ═══════════════
# So GET. Nao existe nenhuma chamada aqui que crie, pause ou altere campanha,
# conjunto, anuncio ou orcamento — e nem vai existir: o Guilherme foi explicito
# em "somente puxar os dados", e essa e a linha.
#
# Por que guardar no JOB em vez de consultar na hora: o custo por lead precisa
# cruzar gasto (plataforma) com lead e venda (nosso banco). Fazer isso ao vivo
# significaria uma chamada externa por consulta e um numero que muda sozinho.
# Guardado por dia, o historico fica nosso e sobrevive a janela de retencao deles.
def _midia_chave(nome):
    """Chave de casamento tolerante pro NOME da campanha.

    Nome de campanha e digitado por gente: vem com acento, MAIUSCULA, espaco
    duplo, e as vezes com o pipe do padrao de nomenclatura. Comparar string crua
    faz "MEI SP" e "mei  sp" virarem campanhas diferentes — e o gasto de uma
    aparece como 'sem lead' enquanto os leads da outra aparecem como 'sem gasto'.
    Duas metades da mesma verdade, separadas por um espaco."""
    v = (nome or '').strip().lower()
    try:
        import unicodedata as _u
        v = ''.join(c for c in _u.normalize('NFD', v) if _u.category(c) != 'Mn')
    except Exception:
        pass
    v = re.sub(r'[^a-z0-9]+', ' ', v).strip()
    return re.sub(r'\s+', ' ', v)


def _midia_gravar(conn, canal, linhas):
    """Grava/atualiza as linhas de gasto. Reimportar o mesmo dia nao duplica —
    e o normal: o gasto do dia de hoje muda ate o dia fechar."""
    n = 0
    agora = _agora_sp()
    for l in linhas:
        chave = (canal, l.get('data'), l.get('campanha_id') or '', l.get('anuncio_id') or '')
        ja = conn.execute("""SELECT id FROM midia_gasto
                             WHERE canal=? AND data=? AND COALESCE(campanha_id,'')=?
                               AND COALESCE(anuncio_id,'')=?""", chave).fetchone()
        if ja:
            conn.execute("""UPDATE midia_gasto SET campanha_nome=?, conjunto_nome=?, anuncio_nome=?,
                            gasto=?, impressoes=?, cliques=?, moeda=?, conta_id=?, atualizado_em=?
                            WHERE id=?""",
                         (l.get('campanha_nome'), l.get('conjunto_nome'), l.get('anuncio_nome'),
                          l.get('gasto', 0), l.get('impressoes', 0), l.get('cliques', 0),
                          l.get('moeda', 'BRL'), l.get('conta_id'), agora, ja['id']))
        else:
            conn.execute("""INSERT INTO midia_gasto
                (canal, data, conta_id, campanha_id, campanha_nome, conjunto_nome, anuncio_id,
                 anuncio_nome, gasto, impressoes, cliques, moeda, atualizado_em)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (canal, l.get('data'), l.get('conta_id'), l.get('campanha_id'), l.get('campanha_nome'),
                 l.get('conjunto_nome'), l.get('anuncio_id'), l.get('anuncio_nome'),
                 l.get('gasto', 0), l.get('impressoes', 0), l.get('cliques', 0),
                 l.get('moeda', 'BRL'), agora))
        n += 1
    return n


def _meta_ads_config():
    """Credenciais pra LER gasto na Meta.

    META_AD_ACCOUNT_ID aceita VARIAS contas separadas por virgula. A Serenus vai
    ter duas BMs convivendo (a Axioma, onde as campanhas rodam hoje, e a nova da
    Serenus) — ler so uma faria metade do gasto sumir do custo por lead, e o
    numero pareceria certo. Uma conta so continua funcionando igual.

    O token da API de Conversoes costuma nao ter ads_read — por isso aceita um
    token proprio e so cai no da conversao se ele nao existir."""
    bruto = (os.environ.get('META_AD_ACCOUNT_ID') or '').strip()
    contas = []
    for c in re.split(r'[,;\s]+', bruto):
        c = c.strip()
        if not c:
            continue
        contas.append(c if c.startswith('act_') else 'act_' + c.lstrip('act_'))
    token = (os.environ.get('META_ADS_TOKEN') or os.environ.get('META_ACCESS_TOKEN') or '').strip()
    faltando = []
    if not contas:
        faltando.append('META_AD_ACCOUNT_ID')
    if not token:
        faltando.append('META_ADS_TOKEN (ou META_ACCESS_TOKEN com ads_read)')
    return {'contas': contas, 'conta': contas[0] if contas else '', 'token': token}, faltando


def puxar_gasto_meta(dias=30):
    """GET /insights por DIA e por ANUNCIO. Nada mais que leitura.

    level='ad' e time_increment=1 de proposito: gasto agregado por campanha nao
    responde 'qual criativo custou caro', que e a pergunta que importa quando se
    tem varios anuncios na mesma campanha."""
    cfg, faltando = _meta_ads_config()
    resumo = {'canal': 'meta', 'linhas': 0, 'gasto': 0.0, 'faltando': faltando, 'erros': []}
    if faltando:
        return resumo
    campos = ('date_start,spend,impressions,clicks,campaign_id,campaign_name,'
              'adset_name,ad_id,ad_name,account_currency')
    linhas = []
    resumo['contas'] = {}
    import requests as _rq
    for conta in cfg['contas']:
        # Uma conta que falha nao derruba as outras: o gasto que deu pra ler
        # entra, e a que falhou aparece nomeada no erro.
        url = f"https://graph.facebook.com/{_META_API_VERSAO}/{conta}/insights"
        params = {'fields': campos, 'level': 'ad', 'time_increment': 1,
                  'date_preset': 'last_30d' if dias > 7 else 'last_7d',
                  'limit': 500, 'access_token': cfg['token']}
        paginas, n_conta = 0, 0
        try:
            while url and paginas < 20:
                r = _rq.get(url, params=params if paginas == 0 else None, timeout=45)
                d = r.json() if r.content else {}
                if d.get('error'):
                    resumo['erros'].append(f"{conta}: " + ((d['error'] or {}).get('message') or f'HTTP {r.status_code}'))
                    break
                for x in d.get('data', []):
                    n_conta += 1
                    linhas.append({
                        'data': x.get('date_start'), 'conta_id': conta,
                        'campanha_id': x.get('campaign_id'), 'campanha_nome': x.get('campaign_name'),
                        'conjunto_nome': x.get('adset_name'),
                        'anuncio_id': x.get('ad_id'), 'anuncio_nome': x.get('ad_name'),
                        'gasto': float(x.get('spend') or 0),
                        'impressoes': int(x.get('impressions') or 0),
                        'cliques': int(x.get('clicks') or 0),
                        'moeda': x.get('account_currency') or 'BRL',
                    })
                url = ((d.get('paging') or {}).get('next')) or None
                paginas += 1
        except Exception as e:
            resumo['erros'].append(f'{conta}: falha ao falar com a Meta: {e}')
        resumo['contas'][conta] = n_conta
    if linhas:
        conn = db()
        try:
            resumo['linhas'] = _midia_gravar(conn, 'meta', linhas)
            conn.commit()
        except Exception as e:
            try: conn.rollback()
            except Exception: pass
            resumo['erros'].append(str(e)[:200])
        close_db(conn)
    resumo['gasto'] = round(sum(l['gasto'] for l in linhas), 2)
    return resumo


def puxar_gasto_google(dias=30):
    """Relatorio de campanha do Google Ads (searchStream). So leitura: e uma
    query GAQL de SELECT, nao existe mutate nenhum."""
    cfg, faltando = _ads_config()
    resumo = {'canal': 'google', 'linhas': 0, 'gasto': 0.0, 'faltando': faltando, 'erros': []}
    if faltando:
        return resumo
    try:
        token = _ads_token(cfg)
    except Exception as e:
        resumo['erros'].append(f'Não consegui autenticar: {e}')
        return resumo
    if not token:
        resumo['erros'].append('Não consegui autenticar no Google Ads')
        return resumo
    gaql = ("SELECT segments.date, campaign.id, campaign.name, metrics.cost_micros, "
            "metrics.impressions, metrics.clicks FROM campaign "
            f"WHERE segments.date DURING LAST_{30 if dias > 7 else 7}_DAYS")
    linhas = []
    try:
        import requests as _rq
        r = _rq.post(f"{_ADS_API}/customers/{cfg['customer_id']}/googleAds:searchStream",
                     headers={'Authorization': f'Bearer {token}',
                              'developer-token': cfg['developer_token'],
                              'Content-Type': 'application/json'},
                     json={'query': gaql}, timeout=60)
        if r.status_code != 200:
            resumo['erros'].append(f'HTTP {r.status_code}: {r.text[:200]}')
        else:
            for bloco in (r.json() or []):
                for x in bloco.get('results', []):
                    camp = x.get('campaign') or {}
                    met = x.get('metrics') or {}
                    linhas.append({
                        'data': (x.get('segments') or {}).get('date'),
                        'conta_id': cfg['customer_id'],
                        'campanha_id': str(camp.get('id') or ''), 'campanha_nome': camp.get('name'),
                        'conjunto_nome': None, 'anuncio_id': None, 'anuncio_nome': None,
                        # cost_micros: 1 real = 1.000.000. Dividir errado aqui daria
                        # um CAC mil vezes menor e ninguem desconfiaria do numero.
                        'gasto': round(int(met.get('costMicros') or 0) / 1_000_000, 2),
                        'impressoes': int(met.get('impressions') or 0),
                        'cliques': int(met.get('clicks') or 0),
                        'moeda': 'BRL',
                    })
    except Exception as e:
        resumo['erros'].append(f'Falha ao falar com o Google: {e}')
    if linhas:
        conn = db()
        try:
            resumo['linhas'] = _midia_gravar(conn, 'google', linhas)
            conn.commit()
        except Exception as e:
            try: conn.rollback()
            except Exception: pass
            resumo['erros'].append(str(e)[:200])
        close_db(conn)
    resumo['gasto'] = round(sum(l['gasto'] for l in linhas), 2)
    return resumo


def enviar_conversoes_meta(limite=200, so_simular=False):
    """Sobe as conversoes pendentes pra Meta. Devolve resumo pra tela e pro log.

    Revalida contra a proposta NA HORA: a venda pode ter sido estornada ou
    excluida depois de entrar na fila, e mandar receita que nao existe e
    exatamente o inflar de ROAS que este modulo diz impedir."""
    cfg, faltando = _meta_config()
    conn = db()
    # QUALQUER UM dos dois identificadores basta — sao dois jeitos de achar a
    # mesma pessoa (fbclid = clique numa landing; facebook_lead_id = Formulario
    # Instantaneo). Exigir so fbclid deixava de fora TODA a venda vinda de Lead
    # Ads, que e 100% do trafego de Facebook do Serenus hoje.
    pend = conn.execute("""SELECT m.* FROM meta_conversoes m
                           JOIN propostas p ON p.id = m.proposta_id
                           WHERE m.status='pendente'
                             AND ((m.fbclid IS NOT NULL AND m.fbclid <> '')
                               OR (m.facebook_lead_id IS NOT NULL AND m.facebook_lead_id <> ''))
                             AND p.status_operacional='Emitida/Ativa'
                             AND COALESCE(p.status,'') <> 'Excluída'
                             AND COALESCE(p.estornada,0)=0
                           ORDER BY m.id LIMIT ?""", (limite,)).fetchall()
    conn.execute("""UPDATE meta_conversoes SET status='cancelada',
            detalhe='venda estornada/excluída antes do envio'
        WHERE status='pendente' AND proposta_id IN (
            SELECT id FROM propostas
            WHERE status_operacional <> 'Emitida/Ativa' OR COALESCE(status,'')='Excluída'
               OR COALESCE(estornada,0)=1)""")
    conn.commit()
    resumo = {'pendentes': len(pend), 'enviadas': 0, 'falhas': 0,
              'faltando_config': faltando, 'simulado': bool(so_simular), 'erros': []}
    if not pend:
        close_db(conn); return resumo
    if faltando:
        resumo['erros'].append('Credenciais ausentes: ' + ', '.join(faltando))
        close_db(conn); return resumo
    if so_simular:
        close_db(conn); return resumo

    eventos, ids = [], []
    for c in pend:
        lead = conn.execute("SELECT nome, email, telefone_norm FROM crm_leads WHERE id=?",
                            (c['lead_id'],)).fetchone() if c['lead_id'] else None
        quando = _conversao_dt_sp(c['conversao_em'])
        # 'lead_id' vai CRU — sem hash, sem formatacao — e o campo que a Meta
        # documenta especificamente pra casar evento com Formulario Instantaneo.
        # 'fbc' e outro campo, outro formato, outro tipo de clique — os dois
        # podem coexistir no mesmo evento se um dia a venda tiver os dois.
        user = {'fbc': _meta_fbc(c['fbclid'], c['conversao_em'])}
        fb_lead_id_col = c['facebook_lead_id'] if 'facebook_lead_id' in c.keys() else None
        if fb_lead_id_col:
            user['lead_id'] = fb_lead_id_col
        if lead:
            em = _meta_hash(lead['email'])
            if em:
                user['em'] = [em]
            tel = (lead['telefone_norm'] or '').strip()
            if tel:
                # E.164 sem '+', como a Meta espera antes do hash.
                user['ph'] = [_meta_hash(tel if tel.startswith('55') else '55' + tel)]
        eventos.append({
            'event_name': 'Purchase',
            'event_time': int(quando.timestamp()),
            'event_id': c['event_id'] or f"job-venda-{c['proposta_id']}",
            # 'system_generated': o evento nasceu no nosso sistema, nao num
            # navegador. Dizer 'website' aqui seria mentir sobre a origem e a
            # Meta usa isso na atribuicao.
            'action_source': 'system_generated',
            'user_data': {k: v for k, v in user.items() if v},
            'custom_data': {'value': float(c['valor'] or 0), 'currency': c['moeda'] or 'BRL'},
        })
        ids.append(c['id'])

    url = f"https://graph.facebook.com/{_META_API_VERSAO}/{cfg['pixel_id']}/events"
    corpo = {'data': eventos, 'access_token': cfg['access_token']}
    if cfg.get('test_event_code'):
        corpo['test_event_code'] = cfg['test_event_code']
    try:
        import requests as _rq
        r = _rq.post(url, json=corpo, timeout=45)
        dados = r.json() if r.content else {}
    except Exception as e:
        conn.execute(f"""UPDATE meta_conversoes SET tentativas=COALESCE(tentativas,0)+1, detalhe=?
                         WHERE id IN ({','.join(['?'] * len(ids))})""",
                     [f'falha de rede: {e}'] + ids)
        conn.commit(); close_db(conn)
        resumo['falhas'] = len(ids)
        resumo['erros'].append(f'Falha ao falar com a Meta: {e}')
        return resumo

    if r.status_code == 200 and not dados.get('error'):
        marc = ','.join(['?'] * len(ids))
        conn.execute(f"""UPDATE meta_conversoes SET status='enviada', enviado_em=?,
                         detalhe=?, tentativas=COALESCE(tentativas,0)+1
                         WHERE id IN ({marc})""",
                     [_agora_sp(), f"recebidos: {dados.get('events_received', len(eventos))}"] + ids)
        resumo['enviadas'] = len(ids)
    else:
        erro = (dados.get('error') or {}).get('message') or f'HTTP {r.status_code}'
        marc = ','.join(['?'] * len(ids))
        conn.execute(f"""UPDATE meta_conversoes SET tentativas=COALESCE(tentativas,0)+1,
                         detalhe=? WHERE id IN ({marc})""", [str(erro)[:400]] + ids)
        resumo['falhas'] = len(ids)
        resumo['erros'].append(str(erro)[:400])
    conn.commit(); close_db(conn)
    return resumo


def enviar_conversoes_ads(limite=200, so_simular=False):
    """Sobe as conversões pendentes. Devolve um resumo pra tela e pro log.

    partialFailure=True: se uma conversão do lote for recusada (clique fora da
    janela, gclid inválido), as outras entram assim mesmo. Sem isso um gclid ruim
    derrubaria o lote inteiro e nada seria contabilizado."""
    cfg, faltando = _ads_config()
    conn = db()
    # Revalida contra a proposta NA HORA DO ENVIO. A venda pode ter sido estornada
    # ou excluída depois de entrar na fila — e estorno/exclusão não passam pela
    # troca de status_operacional, então nada as tirava daqui. Mandar receita que
    # não existe é exatamente o "inflar o ROAS" que este módulo diz impedir.
    pend = conn.execute("""SELECT g.* FROM google_ads_conversoes g
                           JOIN propostas p ON p.id = g.proposta_id
                           WHERE g.status='pendente' AND g.click_id IS NOT NULL AND g.click_id <> ''
                             AND p.status_operacional='Emitida/Ativa'
                             AND COALESCE(p.status,'') <> 'Excluída'
                             AND COALESCE(p.estornada,0)=0
                           ORDER BY g.id LIMIT ?""", (limite,)).fetchall()
    # As que ficaram para trás por deixarem de ser venda: saem da fila com o
    # motivo, em vez de tentarem de novo em toda rodada.
    conn.execute("""UPDATE google_ads_conversoes SET status='cancelada',
            detalhe='venda estornada/excluída antes do envio'
        WHERE status='pendente' AND proposta_id IN (
            SELECT id FROM propostas
            WHERE status_operacional <> 'Emitida/Ativa' OR COALESCE(status,'')='Excluída'
               OR COALESCE(estornada,0)=1)""")
    conn.commit()
    resumo = {'pendentes': len(pend), 'enviadas': 0, 'falhas': 0,
              'faltando_config': faltando, 'simulado': bool(so_simular), 'erros': []}
    if not pend:
        close_db(conn); return resumo
    if faltando:
        resumo['erros'].append('Credenciais ausentes: ' + ', '.join(faltando))
        close_db(conn); return resumo
    if so_simular:
        close_db(conn); return resumo

    # Data Manager API: até 2000 eventos por chamada. A fila é menor que isso na
    # prática, mas o teto está aqui pra não descobrir o limite em produção.
    lote = [_dm_evento(c) for c in pend[:2000]]
    try:
        token = _ads_token(cfg)
        headers = {'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json'}
        r = _requests.post(f"{_DM_API}/events:ingest", headers=headers, timeout=45,
                           json={'destinations': _dm_destino(cfg), 'events': lote})
        # TUDO OU NADA. A Data Manager API não tem envio parcial: um evento
        # inválido derruba o lote inteiro com 400. Então não existe "quem
        # falhou" — ou entrou tudo, ou nada entrou. Tratar como parcial marcaria
        # como enviada uma conversão que o Google nunca recebeu.
        if r.status_code != 200:
            raise RuntimeError(_dm_erro_legivel(r.status_code, r.text))
        corpo = r.json() or {}
        # E 200 NÃO QUER DIZER QUE ENTROU. O processamento é assíncrono: o que
        # volta é um requestId, e o resultado real só sai depois (até 24h) em
        # requestStatus:retrieve. Guardo o requestId pra ser possível auditar —
        # sem ele, "enviada" seria uma palavra sem prova nenhuma por trás.
        req_id = (corpo.get('requestId') or '').strip()
        avisos = [str(w)[:150] for w in (corpo.get('fieldWarnings') or corpo.get('warnings') or [])]
        falhou_idx = set()
        msg_pf = (' · '.join(avisos))[:400] if avisos else ''
        agora = _agora_sp()
        # O lote inteiro foi aceito (o 400 já teria caído no except). O detalhe
        # guarda o requestId porque é a ÚNICA forma de perguntar depois ao Google
        # o que aconteceu com estas conversões.
        det = (f"aceito · requestId {req_id}" if req_id else 'aceito')
        if msg_pf:
            det += ' · avisos: ' + msg_pf
        for c in pend:
            conn.execute("""UPDATE google_ads_conversoes SET status='enviada',
                            enviado_em=?, detalhe=? WHERE id=?""", (agora, det[:400], c['id']))
            resumo['enviadas'] += 1
        resumo['request_id'] = req_id
        if msg_pf:
            resumo['erros'].append(msg_pf)
        conn.commit()
    except Exception as e:
        # Erro do lote inteiro (rede, token, versão da API fora do ar). Volta pra
        # fila — mas com teto: sem ele a mesma conversão quebrada é retentada em
        # toda rodada, pra sempre, e o log vira ruído que ninguém lê. Depois do
        # teto ela para com o motivo escrito, esperando decisão humana.
        for c in pend:
            tent = (c['tentativas'] or 0) + 1
            if tent >= _ADS_MAX_TENTATIVAS:
                conn.execute("""UPDATE google_ads_conversoes SET status='falha', tentativas=?,
                                detalhe=? WHERE id=?""",
                             (tent, f"parou após {tent} tentativas: {e}"[:400], c['id']))
            else:
                conn.execute("""UPDATE google_ads_conversoes SET tentativas=?, detalhe=? WHERE id=?""",
                             (tent, f"tentativa {tent}: {e}"[:400], c['id']))
        conn.commit()
        resumo['erros'].append(str(e)[:400])
        app.logger.error(f"[ADS] envio falhou: {e}")
    close_db(conn)
    return resumo


def _perfil_da_venda(clientes):
    """Os fatores da venda agregados. Mora fora da rota porque a tela e o ebook
    precisam do MESMO número — dois cálculos parecidos divergem na primeira
    mudança, e aí o documento impresso contradiz a tela que o gerou."""
    rotulos = {'acomodacao': 'Acomodação', 'copart': 'Coparticipação',
               'faixa_vidas': 'Quantas vidas', 'faixa_idade': 'Idade do titular',
               'faixa_valor': 'Valor mensal', 'modalidade': 'Modalidade'}
    ordem_fixa = {
        'faixa_vidas': ['1 vida', '2 vidas', '3 vidas', '4 ou mais vidas'],
        'faixa_idade': ['Até 33 anos', '34 a 48 anos', '49 a 58 anos', '59 anos ou mais'],
        'faixa_valor': ['Até R$ 500', 'R$ 500 a R$ 1.000', 'R$ 1.000 a R$ 2.000', 'Acima de R$ 2.000'],
    }
    fatores = {k: Counter() for k in rotulos}
    for c in clientes:
        for k in fatores:
            v = c.get(k)
            if v:
                fatores[k][v] += 1
    perfil = []
    for k in ('faixa_vidas', 'faixa_idade', 'faixa_valor', 'acomodacao', 'copart', 'modalidade'):
        cnt = fatores[k]
        base = sum(cnt.values())
        if not base:
            continue
        itens = ([(n, cnt[n]) for n in ordem_fixa[k] if cnt.get(n)]
                 if k in ordem_fixa else cnt.most_common(6))
        perfil.append({
            'chave': k, 'titulo': rotulos[k], 'base': base,
            'itens': [{'nome': n, 'qtd': q, 'pct': round(q * 100 / base)} for n, q in itens],
            # O item mais forte serve pra frase do ebook ("55% compram 1 vida").
            'topo': (lambda t: {'nome': t[0][0], 'qtd': t[0][1],
                                'pct': round(t[0][1] * 100 / base)})(cnt.most_common(1)),
        })
    return perfil


def _pendencia_abrir(conn, chave, titulo, descricao='', link='', como_resolver='',
                     severidade='atencao', usuario_id=None):
    """Abre (ou mantem) uma PENDENCIA no sino.

    Diferenca pro aviso comum: aviso some quando lido, pendencia so some quando
    RESOLVIDA. Ler nao resolve nada — foi por isso que a leitura de conversa
    ficou 7 dias parada: mesmo que houvesse um aviso, ele teria sido lido,
    dispensado e esquecido, com o problema de pe.

    Idempotente por `chave`: a checagem roda o tempo todo e nao pode encher o
    sino de copias do mesmo problema. Enquanto a pendencia estiver aberta, esta
    funcao so atualiza o texto (o motivo pode mudar sem o problema sumir).
    """
    try:
        ja = conn.execute("""SELECT id FROM notificacoes
                              WHERE chave=? AND resolvida_em IS NULL
                              ORDER BY id DESC LIMIT 1""", (chave,)).fetchone()
        if ja:
            conn.execute("""UPDATE notificacoes SET titulo=?, descricao=?, link=?,
                            como_resolver=?, severidade=? WHERE id=?""",
                         (titulo, descricao, link, como_resolver, severidade, ja['id']))
            return False
        conn.execute("""INSERT INTO notificacoes
            (usuario_id, tipo, titulo, descricao, link, criado_em, chave,
             severidade, como_resolver)
            VALUES (?,?,?,?,?,?,?,?,?)""",
            (usuario_id, 'pendencia', titulo, descricao, link, _agora_sp(),
             chave, severidade, como_resolver))
        # PENDENCIA GRAVE PROCURA A PESSOA, uma unica vez: na abertura.
        #
        # O sino so avisa quem abre o sino, e o apagao de 7 dias aconteceu com
        # todo mundo trabalhando normalmente — ninguem tinha motivo pra abrir.
        # Coisa grave tem que ir atras. Uma vez so, na abertura, porque a
        # pendencia e idempotente por chave: sem isso o mesmo problema mandaria
        # WhatsApp a cada reconciliacao, que e de minuto em minuto, e a pessoa
        # aprenderia a ignorar.
        if severidade == 'erro':
            try:
                threading.Thread(
                    target=_notificar_whatsapp,
                    args=(usuario_id, 'pendencia', titulo,
                          (descricao + ' ' + (como_resolver or '')).strip(), link),
                    daemon=True).start()
            except Exception:
                pass
        return True
    except Exception as e:
        app.logger.warning(f"[PENDENCIA] abrir {chave}: {e}")
        return False


def _pendencia_resolver(conn, chave):
    """Fecha a pendencia porque o problema ACABOU — nao porque alguem clicou.

    Quem resolve e a realidade: a extensao atualizou, a leitura voltou a rodar.
    A tela nao tem botao de 'dispensar' de proposito.
    """
    try:
        cur = conn.execute("""UPDATE notificacoes SET resolvida_em=?, lida=1
                              WHERE chave=? AND resolvida_em IS NULL""",
                           (_agora_sp(), chave))
        return (getattr(cur, 'rowcount', 0) or 0) > 0
    except Exception as e:
        app.logger.warning(f"[PENDENCIA] resolver {chave}: {e}")
        return False


def _pendencias_reconciliar(conn):
    """Passa os detectores e deixa o sino igual a realidade: abre o que esta
    quebrado, fecha sozinho o que consertou.

    Roda barato (duas consultas) e e chamada de onde ja se sabe o estado: no
    pulso da extensao e ao abrir a tela de Configuracoes.
    """
    abertas, fechadas = 0, 0
    agora = datetime.now(TZ_SP)

    # 1) EXTENSAO ABAIXO DO IDEAL — por pessoa. Nao bloqueia o trabalho dela;
    #    so avisa que esta rodando reduzida, e some sozinha quando atualizar.
    try:
        for u in conn.execute("""SELECT id, nome, varr_versao, varr_visto_em FROM usuarios
                                  WHERE ativo=1 AND COALESCE(varredura_ativa,0)=1""").fetchall():
            chave = f'ext_versao:{u["id"]}'
            v = (u['varr_versao'] or '').strip()
            primeiro = (u['nome'] or '').split()[0]
            # VERSAO DESCONHECIDA E TRATADA COMO ANTIGA, de proposito.
            #
            # Quem nao manda a versao escapava de tudo: nao abria pendencia, nao
            # fechava, nao aparecia como atrasada. E o buraco cai justamente em
            # cima de quem mais precisa aparecer — as extensoes velhas sao as
            # que nao reportam versao. Silencio aqui nao e sinal de saude.
            if not v and u['varr_visto_em']:
                if _pendencia_abrir(
                    conn, chave,
                    f'A extensão de {primeiro} não diz qual versão é',
                    'Ela conversa com o JOB mas não informa a versão, o que só acontece '
                    'em versões antigas. Enquanto isso, não dá para garantir que a leitura '
                    'de conversa dela está correta.',
                    '/configuracoes',
                    f'Peça para atualizar para a {EXT_VERSAO["ideal"]}: chrome://extensions, '
                    'botão de atualizar, e F5 no WhatsApp Web.',
                    'atencao', None):
                    abertas += 1
                continue
            # DUAS GRAVIDADES, e a diferenca entre elas nao pode ser inventada
            # pelo texto: abaixo do piso a pessoa esta PARADA; entre o piso e o
            # ideal ela esta trabalhando reduzida. Dizer "continua lendo" pra
            # quem esta travado seria a tela mentindo com boa intencao.
            if v and not _versao_ge(v, EXT_VERSAO['bloqueia_abaixo']):
                if _pendencia_abrir(
                    conn, chave,
                    f'{primeiro} está sem ler conversa: extensão muito antiga',
                    f'A versão {v} lê a conversa errado (uma mensagem só, sem dono), '
                    f'então o JOB prefere não ler a gravar dado errado. Nada do que '
                    f'{primeiro} conversa está virando inteligência de venda.',
                    '/configuracoes',
                    f'Só volta a funcionar atualizando a extensão para a {EXT_VERSAO["ideal"]}: '
                    'chrome://extensions, botão de atualizar, e F5 no WhatsApp Web.',
                    'erro', None):
                    abertas += 1
            elif v and not _versao_ge(v, EXT_VERSAO['ideal']):
                if _pendencia_abrir(
                    conn, chave,
                    f'Extensão de {primeiro} está desatualizada',
                    f'Está na {v} e o recomendado é a {EXT_VERSAO["ideal"]}. '
                    f'Ela continua lendo conversa normalmente, só sem a parte nova — '
                    f'o JOB não consegue confirmar por que ela roda ou para.',
                    '/configuracoes',
                    'Peça para essa pessoa abrir chrome://extensions, clicar em atualizar, '
                    'e dar F5 no WhatsApp Web. A pendência some sozinha quando a versão subir.',
                    'atencao', None):
                    abertas += 1
            elif v:
                if _pendencia_resolver(conn, chave):
                    fechadas += 1
    except Exception as e:
        app.logger.warning(f"[PENDENCIA] versoes: {e}")

    # 2) LEITURA CALADA EM HORARIO COMERCIAL. E o alarme que faltava: sem ele,
    #    um apagao so aparece quando alguem for procurar. Com ele, aparece no
    #    sino no mesmo dia.
    try:
        cfg = varredura_cfg(conn)
        chave = 'varredura_calada'
        ult = _parse_dt_seguro(conn.execute(
            "SELECT MAX(criado_em) u FROM whatsapp_analises").fetchone()['u'])
        if ult is not None and ult.tzinfo is None:
            ult = TZ_SP.localize(ult)
        horas = int((agora - ult).total_seconds() // 3600) if ult else None
        dentro = (int(cfg.get('hora_inicio', 8)) <= agora.hour < int(cfg.get('hora_fim', 20))
                  and agora.weekday() < 5)
        # So acusa DENTRO do expediente: 12h de silencio de madrugada e o
        # esperado, e alarme que toca quando esta tudo bem ensina a ignorar.
        if cfg.get('ativa') and dentro and (horas is None or horas >= 6):
            # Frase montada, nao concatenada: 'Nenhuma conversa foi lida nunca
            # rodou' foi o que saiu na primeira versao.
            if horas is None:
                quanto = 'Nenhuma conversa foi lida ainda'
            elif horas >= 24:
                d = horas // 24
                quanto = f'A última conversa foi lida há {d} dia{"s" if d != 1 else ""}'
            else:
                quanto = f'A última conversa foi lida há {horas}h'
            if _pendencia_abrir(
                conn, chave,
                'A leitura de conversas parou',
                f'{quanto}, e a leitura automática está ligada. '
                f'Enquanto isso, nenhuma venda nova ganha objeção, score ou material de treino.',
                '/configuracoes',
                'Abra Configurações e veja "Está rodando agora?": ela diz o motivo de cada '
                'pessoa — extensão velha, WhatsApp Web fechado ou fora do horário.',
                'erro', None):
                abertas += 1
        elif horas is not None and horas < 6:
            if _pendencia_resolver(conn, chave):
                fechadas += 1
    except Exception as e:
        app.logger.warning(f"[PENDENCIA] varredura calada: {e}")

    if abertas or fechadas:
        try:
            conn.commit()
        except Exception:
            pass
    return {'abertas': abertas, 'fechadas': fechadas}


# ═══════════ POLITICA DE VERSAO DA EXTENSAO ═══════════
#
# REGRA DA CASA: versao nova melhora, versao velha NAO PARA O TRABALHO.
#
# Quem nao atualizou tem que continuar produzindo o minimo aceitavel. O sistema
# so bloqueia quando rodar seria PIOR que nao rodar — quando a versao antiga
# grava dado errado, e aí o estrago passa a ser permanente e silencioso. Fora
# esse caso, degrada e ABRE PENDENCIA: o trabalho segue e alguem fica sabendo.
#
# Por que a regra existe: a decisao da varredura passou a exigir uma rota que so
# a 4.96 conhece, e com isso TODA extensao anterior parou de ler conversa. Isso
# e exatamente o que nao pode: a versao nova melhorou pra quem atualizou e
# apagou o trabalho de quem nao atualizou.
EXT_VERSAO = {
    # Abaixo disto a leitura grava analise ERRADA (1 mensagem por conversa, sem
    # dono). Aqui sim bloqueia — e o unico caso.
    'bloqueia_abaixo': '3.27.0',
    # Abaixo disto funciona, porem sem a decisao autenticada e sem o pulso.
    # Nunca bloqueia: abre pendencia no sino e segue trabalhando.
    'ideal': '4.98.0',
}
_VARR_VERSAO_MINIMA = EXT_VERSAO['ideal']


def _versao_ge(v, minimo):
    def _t(x):
        p = [int(n) for n in str(x or '').split('.') if n.isdigit()]
        return tuple(p + [0] * (3 - len(p)))[:3]
    try:
        return _t(v) >= _t(minimo)
    except Exception:
        return False


_VARR_MOTIVOS = {
    'ok': ('Pode rodar', 'ok'),
    'rodar_agora': ('Rodando agora (forçado)', 'ok'),
    'desligada': ('A leitura automática está desligada na chave geral acima', 'atencao'),
    'consultor_fora': ('Esta pessoa não está marcada em "Quem participa"', 'atencao'),
    'fora_do_horario': ('Fora da janela de horário configurada', 'neutro'),
    'fim_de_semana': ('Fim de semana, e a configuração diz "só dias úteis"', 'neutro'),
    'consultor_desconhecido': ('O servidor não reconheceu este consultor', 'erro'),
    # A rota da fila grava este motivo; sem a entrada aqui o token cru vazava
    # pra tela, em cinza neutro, como se fosse normal.
    'versao_bloqueada': ('Extensão antiga demais: a fila recusou a leitura', 'erro'),
    'decisao_em_outra_rota': ('Extensão antiga: ela ainda pergunta no lugar errado', 'erro'),
    'sem_resposta_do_servidor': ('A extensão perguntou e não entendeu a resposta', 'erro'),
    'servidor_inacessivel': ('A extensão não conseguiu falar com o JOB', 'erro'),
}


def _fila_envio_saude(conn):
    """O estado da fila de envio, em número, para quem precisa decidir.

    ESTA FUNÇÃO EXISTE POR CAUSA DE UM ESTRAGO REAL.

    Em 18/08/2026 uma rotina de envio parada foi religada sem ninguém medir o
    que estava represado, e 17 mensagens de até três semanas atrás saíram para
    clientes. A lição escrita no ROADMAP foi "medir antes de religar" — só que
    a consulta ficou registrada como SQL que ninguém tinha como rodar: o banco
    de produção só aceita conexão de dentro da Railway. Regra que depende de um
    acesso que ninguém tem não é regra, é intenção.

    Agora o número está na tela, ao lado do resto da saúde da extensão.
    """
    agora = datetime.now(TZ_SP)
    out = {'validade_h': _WA_FILA_VALIDADE_HORAS, 'esperando': 0, 'vencendo': 0,
           'mais_antiga_min': None, 'itens': [], 'cancelados_atraso': 0, 'falhou': 0}
    linhas = conn.execute("""
        SELECT f.id, f.responsavel_id, f.origem, f.status, f.criado_em, f.liberar_em,
               u.nome AS consultor
        FROM whatsapp_extensao_fila f
        LEFT JOIN usuarios u ON u.id = f.responsavel_id
        WHERE f.status IN ('pendente','enviando')
        ORDER BY f.criado_em ASC LIMIT 50""").fetchall()
    for r in linhas:
        d = dict(r)
        nasceu = _parse_dt_seguro(d.get('criado_em'))
        idade_min = None
        if nasceu:
            if nasceu.tzinfo is None:
                nasceu = TZ_SP.localize(nasceu)
            idade_min = int((agora - nasceu).total_seconds() // 60)
        # VENCIDA quer dizer NÃO VAI SAIR. É o número que interessa: cada uma
        # dessas é um cliente que a mensagem nunca alcançou.
        #
        # O prazo é POR TIPO: abertura de lead pago vence em minutos porque a
        # pressa é o produto dela; o resto tem mais folga. A tela precisa contar
        # do mesmo jeito que o servidor decide, senão ela promete envio que não
        # vai acontecer.
        limite_min = _wa_fila_validade_min(d.get('origem'))
        vencida = bool(idade_min is not None and idade_min >= limite_min)
        out['itens'].append({
            'id': d['id'], 'consultor': (d.get('consultor') or '?').split()[0],
            'origem': d.get('origem') or '', 'status': d.get('status'),
            'idade_min': idade_min, 'vencida': vencida, 'limite_min': limite_min,
            'agendada': bool(d.get('liberar_em')),
        })
        out['esperando'] += 1
        if vencida:
            out['vencendo'] += 1
        if idade_min is not None and (out['mais_antiga_min'] is None or idade_min > out['mais_antiga_min']):
            out['mais_antiga_min'] = idade_min
    try:
        cutoff_7d = (agora - timedelta(days=7)).strftime('%Y-%m-%d %H:%M:%S')
        out['cancelados_atraso'] = conn.execute(
            "SELECT COUNT(*) c FROM whatsapp_extensao_fila WHERE status='cancelado_atraso'").fetchone()['c']
        out['falhou'] = conn.execute(
            "SELECT COUNT(*) c FROM whatsapp_extensao_fila WHERE status='falhou' AND CAST(criado_em AS TEXT) >= ?",
            (cutoff_7d,)).fetchone()['c']
    except Exception as e:
        app.logger.warning(f"[FILA_SAUDE] contagens: {e}")
    return out


def _varredura_saude(conn):
    """Quem está lendo conversa, quem não está, e o MOTIVO REAL de cada um.

    Existe por causa de um apagão de 7 dias (11/08 a 18/08/2026) em que a
    varredura não rodou uma única vez enquanto a tela de configuração mostrava
    tudo ligado. Não havia como saber: nenhum registro de tentativa, nenhum
    motivo, nada no log. A pergunta "está funcionando?" só tinha resposta
    cavando o banco.

    Agora cada extensão carimba no próprio usuário quando perguntou, com que
    versão e o que ouviu de volta. Esta função lê esse carimbo e cruza com a
    última análise que a pessoa de fato produziu — porque "perguntou e pode"
    ainda não é "leu": se o pulso está fresco e a última análise é de ontem, o
    problema está na máquina dela, não na configuração.
    """
    cfg = varredura_cfg(conn)
    linhas = conn.execute("""
        SELECT u.id, u.nome, COALESCE(u.varredura_ativa,0) participa,
               u.varr_visto_em, u.varr_versao, COALESCE(u.varr_pode,0) varr_pode,
               u.varr_motivo,
               (SELECT MAX(wa.criado_em) FROM whatsapp_analises wa
                 WHERE wa.criado_por = u.id) ultima_analise,
               (SELECT COUNT(*) FROM whatsapp_analises wa
                 WHERE wa.criado_por = u.id
                   AND wa.criado_em >= ?) analises_hoje
        FROM usuarios u WHERE u.ativo=1 ORDER BY u.nome
    """, (datetime.now(TZ_SP).strftime('%Y-%m-%d 00:00:00'),)).fetchall()
    agora = datetime.now(TZ_SP)
    pessoas, silencio = [], 0
    for r in linhas:
        visto = _parse_dt_seguro(r['varr_visto_em'])
        min_visto = None
        if visto:
            if visto.tzinfo is None:
                visto = TZ_SP.localize(visto)
            min_visto = int((agora - visto).total_seconds() // 60)
        versao = (r['varr_versao'] or '').strip()
        # VERSAO DESCONHECIDA E VERSAO VELHA — a mesma regra que o sino ja
        # aplica. Aqui ela estava faltando, e as duas telas se contradiziam: o
        # sino abria pendencia dizendo "nao diz qual versao e" enquanto esta
        # logo abaixo pintava a mesma pessoa de verde, "pode rodar". E a fila
        # de fato recusa quem nao se identifica, entao verde era mentira.
        desconhecida = (not versao) and bool(r['varr_visto_em'])
        atrasada = desconhecida or (bool(versao) and not _versao_ge(versao, EXT_VERSAO['ideal']))
        travada = desconhecida or (bool(versao) and not _versao_ge(versao, EXT_VERSAO['bloqueia_abaixo']))
        motivo = (r['varr_motivo'] or '').strip()
        # Versão velha é o motivo que MANDA: ela explica todos os outros, e sem
        # dizer isso a pessoa fica caçando configuração que já está certa.
        # As duas gravidades da politica, com o texto batendo com a realidade:
        # abaixo do piso a pessoa esta PARADA; entre o piso e o ideal ela
        # trabalha reduzida. Pintar as duas de vermelho ensinaria a ignorar as
        # duas.
        if desconhecida:
            texto, cor = ('A extensão não diz qual versão é — só versão antiga faz isso, '
                          f'e a fila recusa quem não se identifica. Atualize para a '
                          f'{EXT_VERSAO["ideal"]}'), 'erro'
        elif travada:
            texto, cor = (f'Extensão {versao} não lê conversa — precisa atualizar '
                          f'para a {EXT_VERSAO["ideal"]}'), 'erro'
        elif atrasada:
            texto, cor = (f'Extensão {versao} funciona, mas está atrás da '
                          f'{EXT_VERSAO["ideal"]}'), 'atencao'
        elif not min_visto and not motivo:
            texto, cor = 'A extensão desta pessoa nunca perguntou se pode rodar', 'erro'
        elif min_visto is not None and min_visto > 120:
            texto, cor = f'Sem sinal há {min_visto // 60}h — WhatsApp Web fechado ou extensão parada', 'erro'
        else:
            texto, cor = _VARR_MOTIVOS.get(motivo, (motivo or 'sem motivo registrado', 'neutro'))
        ultima = _parse_dt_seguro(r['ultima_analise'])
        if r['participa'] and cor == 'erro':
            silencio += 1
        pessoas.append({
            'id': r['id'], 'nome': r['nome'], 'participa': bool(r['participa']),
            'visto_min': min_visto, 'versao': versao or None, 'atrasada': atrasada,
            'pode': bool(r['varr_pode']), 'motivo': motivo,
            'texto': texto, 'cor': cor,
            'ultima_analise': ultima, 'analises_hoje': r['analises_hoje'] or 0,
        })
    ultima_geral = conn.execute(
        "SELECT MAX(criado_em) u FROM whatsapp_analises").fetchone()['u']
    ultima_geral = _parse_dt_seguro(ultima_geral)
    horas_sem = None
    if ultima_geral:
        if ultima_geral.tzinfo is None:
            ultima_geral = TZ_SP.localize(ultima_geral)
        horas_sem = int((agora - ultima_geral).total_seconds() // 3600)
    custo = conn.execute("""
        SELECT COUNT(*) n,
               COALESCE(SUM(COALESCE(custo_claude_usd,0) + COALESCE(custo_transcricao_usd,0)),0) usd
        FROM whatsapp_analises WHERE criado_em >= ?
    """, ((agora - timedelta(days=30)).strftime('%Y-%m-%d %H:%M:%S'),)).fetchone()
    return {
        'pessoas': pessoas, 'participando': sum(1 for p in pessoas if p['participa']),
        'em_silencio': silencio, 'ultima_geral': ultima_geral, 'horas_sem': horas_sem,
        'ligada': bool(cfg.get('ativa')),
        'analises_30d': custo['n'], 'custo_30d': float(custo['usd'] or 0),
        'versao_minima': _VARR_VERSAO_MINIMA,
    }


def _vendas_sem_analise(conn):
    """Vendas fechadas que ainda não têm conversa lida, com o que falta em cada.

    Medido em produção (18/08/2026), de 71 vendas: 21 tinham análise, 38 tinham
    lead mas ninguém mandou ler a conversa — e 33 dessas 38 JÁ TINHAM o vínculo
    @lid, ou seja, dava pra ler naquele instante. O problema nunca foi a
    extensão capturar mal: foi ninguém enfileirar. As 12 restantes nem lead têm.

    Devolve (prontas, sem_conversa, sem_lead) pra tela poder dizer exatamente
    qual é o impedimento de cada uma em vez de um total sem ação.
    """
    linhas = conn.execute("""
        SELECT p.id, p.razao_social, p.consultor, p.criado_em, p.lead_id,
               p.usuario_id, l.nome lead_nome, l.responsavel_id,
               (SELECT w.chat_id FROM wa_chat_lead w
                 WHERE w.lead_id = p.lead_id
                   AND NOT EXISTS (SELECT 1 FROM wa_conversa_ignorada i
                                    WHERE i.chat_id = w.chat_id)
                 LIMIT 1) chat_id,
               (SELECT COUNT(*) FROM varredura_item vi
                 JOIN varredura_lote vl ON vl.id = vi.lote_id
                WHERE vi.lead_id = p.lead_id AND vi.status IN ('pendente','lendo')
                  AND vl.status='rodando') na_fila
        FROM propostas p
        LEFT JOIN crm_leads l ON l.id = p.lead_id
        WHERE p.status <> 'Excluída' AND COALESCE(p.estornada,0)=0
          AND NOT EXISTS (SELECT 1 FROM whatsapp_analises wa WHERE wa.lead_id = p.lead_id)
        ORDER BY p.criado_em DESC
    """).fetchall()
    prontas, sem_conversa, sem_lead, na_fila = [], [], [], []
    for r in linhas:
        item = {'id': r['id'], 'nome': r['razao_social'], 'consultor': r['consultor'],
                'criado_em': r['criado_em'], 'lead_id': r['lead_id'],
                'lead_nome': r['lead_nome'], 'chat_id': r['chat_id'],
                # Quem tem a conversa no WhatsApp é quem vai lê-la: o responsável
                # pelo lead; sem ele, quem cadastrou a proposta.
                'dono': r['responsavel_id'] or r['usuario_id']}
        if not r['lead_id']:
            sem_lead.append(item)
        elif not r['chat_id']:
            sem_conversa.append(item)
        elif r['na_fila']:
            # JÁ ESPERANDO A EXTENSÃO. Sem separar isto de 'prontas', o botão
            # prometia "mandar ler as 24" e respondia "0 na fila" — porque as 24
            # já estavam lá. Quem clicou entendeu que quebrou.
            na_fila.append(item)
        else:
            prontas.append(item)
    return prontas, sem_conversa, sem_lead, na_fila


def _fila_vendas_enfileirar(conn, prontas):
    """Põe as vendas prontas na fila de leitura que a extensão JÁ drena.

    Não existe máquina nova aqui, e isso é o ponto: a extensão continua com o
    mesmo protocolo de sempre (pede um item, lê, devolve, espera 25s). O que
    muda é só QUEM entra na fila e em que ordem. Um lote permanente por
    consultor, marcado com prioridade 1, que vai sendo completado — em vez de
    varredura gigante criada à mão e abandonada no meio (7 dos 8 lotes já
    criados estavam 'parado', com 512 itens pendentes que ninguém leria).

    A fila fica minúscula por construção: são as vendas do mês, não a base de
    leads. Peso pra extensão: o mesmo de ler uma conversa, algumas vezes por mês.
    """
    if not prontas:
        return {'enfileiradas': 0, 'lotes': 0}
    porconsultor = {}
    for p in prontas:
        if p['dono']:
            porconsultor.setdefault(p['dono'], []).append(p)
    enfileiradas, lotes = 0, 0
    for uid, itens in porconsultor.items():
        lote = conn.execute("""SELECT id FROM varredura_lote
                                WHERE consultor_id=? AND status='rodando'
                                  AND COALESCE(prioridade,0) >= 1
                                ORDER BY id DESC LIMIT 1""", (uid,)).fetchone()
        if lote:
            lote_id = lote['id']
        else:
            cur = conn.execute("""INSERT INTO varredura_lote
                (consultor_id, criado_por, filtro_txt, total, status, criado_em, prioridade)
                VALUES (?,?,?,?,?,?,?)""",
                (uid, 'automático', 'Vendas fechadas sem conversa lida', 0, 'rodando',
                 _agora_sp(), 1))
            lote_id = _last_insert_id(cur)
            if lote_id is None:
                lote_id = conn.execute(
                    "SELECT id FROM varredura_lote ORDER BY id DESC LIMIT 1").fetchone()['id']
            lotes += 1
        for p in itens:
            # Idempotente: rodar de novo não duplica item que já está na fila.
            ja = conn.execute("""SELECT 1 FROM varredura_item
                                  WHERE lote_id=? AND lead_id=? AND status IN ('pendente','lendo')
                                  LIMIT 1""", (lote_id, p['lead_id'])).fetchone()
            if ja:
                continue
            conn.execute("""INSERT INTO varredura_item
                (lote_id, lead_id, chat_id, lead_nome, status, atualizado_em)
                VALUES (?,?,?,?,?,?)""",
                (lote_id, p['lead_id'], p['chat_id'],
                 (p['lead_nome'] or p['nome'] or '')[:120], 'pendente', _agora_sp()))
            enfileiradas += 1
        conn.execute("""UPDATE varredura_lote SET total =
            (SELECT COUNT(*) FROM varredura_item WHERE lote_id=?) WHERE id=?""",
            (lote_id, lote_id))
    return {'enfileiradas': enfileiradas, 'lotes': lotes}


def _rotulo_venda(v):
    """Só limpa. A juntada de 'Apartamento' com 'APARTAMENTO' acontece na hora
    de contar (_canonizar_rotulos), e não aqui com .title(): title-case cru
    destrói sigla — 'PF' virava 'Pf' e 'PME PORTE 1' virava 'Pme Porte 1'."""
    v = (str(v or '')).strip()
    return v or None


def _canonizar_rotulos(clientes, chaves):
    """Junta as grafias do mesmo valor e elege a MAIS USADA como a oficial.

    O cadastro é digitado à mão: 'Apartamento' (17x) convive com 'APARTAMENTO'
    (2x) e 'Saúde' com 'SAÚDE'. Contadas separadas, viram duas categorias e o
    gráfico mente. Eleger a grafia mais frequente (em vez de forçar um formato)
    preserva sigla e acento como a corretora escreve.

    Roda sobre a lista COMPLETA, antes de qualquer filtro: assim o nome de uma
    categoria não muda quando o usuário filtra por consultor.
    """
    for k in chaves:
        grafias = {}
        for c in clientes:
            v = c.get(k)
            if v:
                grafias.setdefault(str(v).casefold(), Counter())[str(v)] += 1
        oficial = {ch: cnt.most_common(1)[0][0] for ch, cnt in grafias.items()}
        for c in clientes:
            v = c.get(k)
            if v:
                c[k] = oficial.get(str(v).casefold(), v)


def _rotulo_copart(v):
    """'Sem' e 'Sem coparticipação' são o mesmo fator moderador."""
    v = (str(v or '')).strip().lower()
    if not v:
        return None
    if v.startswith('sem'):
        return 'Sem coparticipação'
    if v.startswith('com'):
        return 'Com coparticipação'
    return _rotulo_venda(v)


def _faixa_vidas(n):
    try:
        n = int(n or 0)
    except Exception:
        return None
    if n <= 0:
        return None
    return '1 vida' if n == 1 else ('%d vidas' % n if n <= 3 else '4 ou mais vidas')


def _faixa_valor(v):
    try:
        v = float(v or 0)
    except Exception:
        return None
    if v <= 0:
        return None
    if v < 500:
        return 'Até R$ 500'
    if v < 1000:
        return 'R$ 500 a R$ 1.000'
    if v < 2000:
        return 'R$ 1.000 a R$ 2.000'
    return 'Acima de R$ 2.000'


def _faixa_idade(nasc, quando):
    """Idade do titular NA DATA DA VENDA, não hoje: preço de plano de saúde é
    faixa etária, então a idade que explica a venda é a de quando ela aconteceu."""
    d1, d2 = _parse_dt_seguro(nasc), _parse_dt_seguro(quando)
    if not d1 or not d2:
        return None
    anos = d2.year - d1.year - ((d2.month, d2.day) < (d1.month, d1.day))
    # Titular com menos de 16 anos nao existe — e erro de digitacao no cadastro
    # (ha registro com nascimento no proprio mes da venda). Entra como nao
    # medido em vez de engordar a faixa mais nova com lixo.
    if anos < 16 or anos > 120:
        return None
    if anos <= 33:
        return 'Até 33 anos'
    if anos <= 48:
        return '34 a 48 anos'
    if anos <= 58:
        return '49 a 58 anos'
    return '59 anos ou mais'


def _fechados_com_analise(conn):
    """Vendas registradas cruzadas com a última análise de conversa e com o lead
    do CRM.

    DUAS CORREÇÕES DE BASE, ambas medidas em produção (18/08/2026):

    1) A BASE não é mais status_operacional='Emitida/Ativa'. Esse campo é a
       esteira de IMPLANTAÇÃO e ninguém a atualiza: das 71 propostas vivas, 45
       estavam no valor DEFAULT da coluna ('Aguardando Documentos'), 22 em
       'Em Análise Operadora' e exatamente 1 em 'Emitida/Ativa'. A tela inteira
       pendurada nesse filtro mostrava 1 cliente e zero insight — media a
       disciplina de preencher um campo, não a venda. No próprio JOB a fase
       'Proposta cadastrada' já significa "venda registrada pelo consultor",
       então a venda é a proposta viva (não excluída, não estornada). O estágio
       da esteira vira DIMENSÃO na tela, não porta de entrada.

    2) O cruzamento com a análise casa por lead_id, não por telefone. O
       telefone morreu com o @lid do WhatsApp: 1992 das 2033 análises têm
       telefone_norm vazio, porque a varredura passou a receber chat_id @lid no
       lugar do número. Mas 2000 das 2033 têm lead_id. Casando por lead_id, 21
       propostas ganham análise; por telefone eram 3. O telefone fica como
       retaguarda pros registros antigos que ainda o têm.
    """
    vendas = conn.execute("""
        SELECT p.id, p.razao_social, p.consultor, p.adm_operadora, p.modalidade,
               p.valor, p.total_vidas, p.criado_em,
               p.tel_resp_contrato, p.tel_resp_negociacao,
               p.lead_id, p.lead_vinculo,
               p.status_operacional, p.fase, p.comprovante_boleto,
               p.acomodacao, p.fator_moderador, p.tipo_pessoa, p.produto,
               p.data_nasc_titular, p.cidade, p.end_cidade
        FROM propostas p
        WHERE p.status <> 'Excluída' AND COALESCE(p.estornada,0)=0
        ORDER BY p.criado_em DESC
    """).fetchall()

    # Última análise por LEAD (chave principal) e por TELEFONE (retaguarda).
    # Os dois índices saem da mesma varredura pra não pagar duas consultas.
    por_lead, por_tel = {}, {}
    for a in conn.execute("""
        SELECT wa.id, wa.lead_id, wa.telefone_norm, wa.sugestoes_json,
               wa.score, wa.score_faixa, wa.criado_em
        FROM whatsapp_analises wa
        ORDER BY wa.id
    """).fetchall():
        # ORDER BY id crescente + sobrescrita = fica a mais recente, sem
        # subconsulta correlacionada por linha.
        if a['lead_id']:
            por_lead[a['lead_id']] = a
        tn = (a['telefone_norm'] or '').strip()
        if tn:
            por_tel[tn] = a

    clientes = []
    for r in vendas:
        wa, lead = None, None
        # Vínculo gravado tem prioridade: é a chave, não uma adivinhação refeita
        # a cada consulta.
        if 'lead_id' in r.keys() and r['lead_id']:
            lead = conn.execute("""SELECT id, nome, responsavel_id, etapa, criado_em
                                   FROM crm_leads WHERE id=?""", (r['lead_id'],)).fetchone()
            wa = por_lead.get(r['lead_id'])
        for tel in (r['tel_resp_contrato'], r['tel_resp_negociacao']):
            tn = _normalizar_telefone(str(tel or ''))
            if not tn:
                continue
            if wa is None and tn in por_tel:
                wa = por_tel[tn]
            if lead is None:
                lead = _buscar_lead_por_telefone(conn, tn)
                # Lead achado pelo telefone ainda pode destravar a análise.
                if lead is not None and wa is None:
                    wa = por_lead.get(lead['id'])
            if wa is not None and lead is not None:
                break

        extr, diag = {}, {}
        dias = None
        if wa is not None:
            try:
                diag = json.loads(wa['sugestoes_json'] or '{}') or {}
                extr = diag.get('extracao') or {}
            except Exception:
                extr, diag = {}, {}
            d1, d2 = _parse_dt_seguro(wa['criado_em']), _parse_dt_seguro(r['criado_em'])
            if d1 and d2 and d2 >= d1:
                dias = (d2 - d1).days
        # KPI mais completo: do LEAD entrar no CRM até a proposta fechar (o
        # 'dias_para_fechar' acima só cobre da análise em diante).
        dias_lead = None
        if lead is not None:
            d1, d2 = _parse_dt_seguro(lead['criado_em']), _parse_dt_seguro(r['criado_em'])
            if d1 and d2 and d2 >= d1:
                dias_lead = (d2 - d1).days
        ia = (diag.get('ia') or {}) if isinstance(diag.get('ia'), dict) else {}
        clientes.append({
            'id': r['id'], 'nome': r['razao_social'], 'consultor': r['consultor'],
            'operadora': r['adm_operadora'], 'modalidade': r['modalidade'],
            'valor': float(r['valor'] or 0), 'vidas': r['total_vidas'],
            'criado_em': r['criado_em'],
            'esteira': (r['status_operacional'] or 'Aguardando Documentos'),
            'fase': (r['fase'] or ''),
            'tem_comprovante': bool(r['comprovante_boleto']),
            'analise_id': (wa['id'] if wa is not None else None),
            'score': (wa['score'] if wa is not None else None),
            'faixa': (wa['score_faixa'] if wa is not None else None),
            # Fatores da venda: saem do CADASTRO da proposta, então existem
            # pra toda venda — não só pras que têm conversa lida. É isso que
            # deixa a leitura valer sobre a base inteira.
            'acomodacao': _rotulo_venda(r['acomodacao']),
            'copart': _rotulo_copart(r['fator_moderador']),
            'tipo_pessoa': _rotulo_venda(r['tipo_pessoa']),
            'produto': (r['produto'] or '').strip(),
            'faixa_vidas': _faixa_vidas(r['total_vidas']),
            'faixa_valor': _faixa_valor(r['valor']),
            'faixa_idade': _faixa_idade(r['data_nasc_titular'], r['criado_em']),
            # Cidade do cadastro primeiro; a da conversa entra só como reforço.
            'cidade': (str(r['cidade'] or r['end_cidade'] or '').strip().title()
                       or (str(extr.get('cidade') or '').strip().title() or None)),
            'objecoes': extr.get('objecoes') or [],
            'resumo_ia': (ia.get('resumo') or '').strip(),
            'followup': (diag.get('followup') or '').strip(),
            'dias_para_fechar': dias,
            'lead_id': (lead['id'] if lead is not None else None),
            'lead_etapa': (lead['etapa'] if lead is not None else None),
            'dias_desde_lead': dias_lead,
        })
    return clientes


@app.route('/inteligencia-vendas')
@login_required
@admin_required
def inteligencia_vendas():
    """O que faz a venda acontecer, lido de TODA proposta cadastrada.

    Não olha o andamento da proposta: o status operacional é a esteira de
    implantação e responde outra pergunta ("a apólice já está valendo?"). Aqui a
    pergunta é o que levou o cliente a contratar — e isso já está decidido no
    instante em que a proposta é cadastrada. Os fatores saem do próprio cadastro
    (acomodação, coparticipação, vidas, faixa etária, valor), então valem pra
    todas as vendas; a análise da conversa entra por cima, trazendo objeção e
    contexto pras que têm conversa lida.
    """
    conn = db()
    clientes = _fechados_com_analise(conn)
    # Cobertura: quantas vendas ainda não tiveram a conversa lida e, de cada
    # uma, QUAL é o impedimento. Sem separar assim, "50 sem análise" não diz o
    # que fazer — e o que fazer é diferente em cada caso.
    _pr, _sc, _sl, _nf = _vendas_sem_analise(conn)
    cobertura = {'prontas': len(_pr), 'sem_conversa': len(_sc),
                 'sem_lead': len(_sl), 'na_fila': len(_nf)}
    close_db(conn)
    _canonizar_rotulos(clientes, ('acomodacao', 'modalidade', 'tipo_pessoa'))

    # Opções saem da base COMPLETA, senão o filtro se apaga sozinho: escolher um
    # consultor sumia com os outros nomes do select.
    opc_consultores = sorted({(c['consultor'] or '').strip() for c in clientes if (c['consultor'] or '').strip()})
    opc_operadoras = sorted({(c['operadora'] or '').strip() for c in clientes if (c['operadora'] or '').strip()})
    opc_modalidades = sorted({(c['modalidade'] or '').strip() for c in clientes if (c['modalidade'] or '').strip()})
    total_geral = len(clientes)

    f_consultor = (request.args.get('consultor') or '').strip()
    f_operadora = (request.args.get('operadora') or '').strip()
    f_modalidade = (request.args.get('modalidade') or '').strip()
    f_analise = (request.args.get('analise') or '').strip()
    if f_consultor:
        clientes = [c for c in clientes if (c['consultor'] or '').strip() == f_consultor]
    if f_operadora:
        clientes = [c for c in clientes if (c['operadora'] or '').strip() == f_operadora]
    if f_modalidade:
        clientes = [c for c in clientes if (c['modalidade'] or '').strip() == f_modalidade]
    if f_analise == 'com':
        clientes = [c for c in clientes if c['analise_id']]
    elif f_analise == 'sem':
        clientes = [c for c in clientes if not c['analise_id']]
    filtrando = bool(f_consultor or f_operadora or f_modalidade or f_analise)

    total = len(clientes)
    soma_valor = sum(c['valor'] for c in clientes)
    por_operadora, val_operadora = Counter(), {}
    por_consultor, val_consultor = Counter(), {}
    objecoes, cidades = Counter(), Counter()
    scores, dias_ate_fechar, com_analise, com_lead = [], [], 0, 0
    # Cada fator é um Counter próprio: são perguntas diferentes sobre a mesma
    # venda, e cada um tem sua própria cobertura (nem todo cadastro traz tudo).
    for c in clientes:
        op = c['operadora'] or '—'
        por_operadora[op] += 1; val_operadora[op] = val_operadora.get(op, 0) + c['valor']
        cons = c['consultor'] or '—'
        por_consultor[cons] += 1; val_consultor[cons] = val_consultor.get(cons, 0) + c['valor']
        if c['analise_id']:
            com_analise += 1
        if c['lead_id']:
            com_lead += 1
        if c['score'] is not None:
            scores.append(c['score'])
        dias_c = c['dias_desde_lead'] if c['dias_desde_lead'] is not None else c['dias_para_fechar']
        if dias_c is not None:
            dias_ate_fechar.append(dias_c)
        for o in (c['objecoes'] or []):
            objecoes[str(o).strip().lower()] += 1
        if c['cidade']:
            cidades[c['cidade']] += 1

    def _limpo(v):
        return int(v) if float(v) == int(v) else round(float(v), 1)

    def _mediana(vals):
        if not vals:
            return None
        s2 = sorted(vals); n = len(s2)
        return _limpo(s2[n // 2] if n % 2 else (s2[n // 2 - 1] + s2[n // 2]) / 2)

    m = {
        'total': total, 'soma_valor': soma_valor,
        'ticket': round(soma_valor / total, 2) if total else 0,
        'com_analise': com_analise, 'com_lead': com_lead,
        'pct_analise': round(com_analise * 100 / total) if total else 0,
        'score_medio': round(sum(scores) / len(scores)) if scores else None,
        'tempo_medio': _limpo(sum(dias_ate_fechar) / len(dias_ate_fechar)) if dias_ate_fechar else None,
        'tempo_mediana': _mediana(dias_ate_fechar),
        'tempo_base': len(dias_ate_fechar),
    }

    perfil = _perfil_da_venda(clientes)

    top_operadoras = [{'nome': k, 'qtd': v, 'valor': val_operadora[k]} for k, v in por_operadora.most_common(10)]
    top_consultores = [{'nome': k, 'qtd': v, 'valor': val_consultor[k]} for k, v in por_consultor.most_common(15)]
    top_objecoes = [{'nome': k, 'qtd': v} for k, v in objecoes.most_common(12)]
    top_cidades = [{'nome': k, 'qtd': v} for k, v in cidades.most_common(10)]
    return render_template('inteligencia_vendas.html', m=m, clientes=clientes,
                           top_operadoras=top_operadoras, top_consultores=top_consultores,
                           top_objecoes=top_objecoes, top_cidades=top_cidades,
                           perfil=perfil, total_geral=total_geral, filtrando=filtrando,
                           cobertura=cobertura,
                           opc_consultores=opc_consultores, opc_operadoras=opc_operadoras,
                           opc_modalidades=opc_modalidades,
                           f_consultor=f_consultor, f_operadora=f_operadora,
                           f_modalidade=f_modalidade, f_analise=f_analise)


@app.route('/ebook-vendas')
@login_required
@admin_required
def ebook_vendas():
    """O material de treino montado a partir das vendas reais, em formato de
    documento — pra ler, imprimir ou virar PDF pelo navegador.

    Não é a tela de Inteligência com outra roupa: lá o admin investiga e filtra,
    aqui o consultor novo LÊ. Por isso vira texto corrido com os números dentro
    da frase, e cada objeção vem com os casos reais em que ela apareceu e o
    cliente comprou assim mesmo — que é a única prova de que dá pra contornar.

    Sem dependência de biblioteca de PDF: o navegador imprime. Uma dependência
    nova no Railway pra gerar um documento que o Chrome já gera é custo sem
    ganho.
    """
    conn = db()
    clientes = _fechados_com_analise(conn)
    close_db(conn)
    _canonizar_rotulos(clientes, ('acomodacao', 'modalidade', 'tipo_pessoa'))
    total = len(clientes)
    com_analise = [c for c in clientes if c['analise_id']]
    perfil = _perfil_da_venda(clientes)

    # Objeção -> casos reais em que ela apareceu E a venda aconteceu.
    por_objecao = {}
    for c in com_analise:
        for o in (c['objecoes'] or []):
            chave = str(o).strip().lower()
            if chave:
                por_objecao.setdefault(chave, []).append(c)
    objecoes = sorted(({'nome': k, 'qtd': len(v),
                        'casos': sorted(v, key=lambda x: -(x['score'] or 0))[:6]}
                       for k, v in por_objecao.items()), key=lambda x: -x['qtd'])

    # Mensagens que funcionaram: só as de venda fechada, sem repetir texto igual
    # (o gerador de follow-up repete o mesmo molde e o ebook ficaria com vinte
    # páginas da mesma frase).
    vistos, followups = set(), []
    for c in sorted(com_analise, key=lambda x: -(x['score'] or 0)):
        t = (c['followup'] or '').strip()
        if not t:
            continue
        assinatura = t[:60].lower()
        if assinatura in vistos:
            continue
        vistos.add(assinatura)
        followups.append(c)
        if len(followups) >= 12:
            break

    cidades = Counter(c['cidade'] for c in clientes if c['cidade'])
    operadoras = Counter(c['operadora'] for c in clientes if c['operadora'])
    tempos = [c['dias_desde_lead'] for c in clientes if c['dias_desde_lead'] is not None]
    tempos.sort()
    mediana = (tempos[len(tempos) // 2] if len(tempos) % 2
               else round((tempos[len(tempos) // 2 - 1] + tempos[len(tempos) // 2]) / 2, 1)) if tempos else None
    datas = [_parse_dt_seguro(c['criado_em']) for c in clientes]
    datas = sorted(d for d in datas if d)
    resumo = {
        'total': total, 'com_analise': len(com_analise),
        'soma': sum(c['valor'] for c in clientes),
        'ticket': round(sum(c['valor'] for c in clientes) / total, 2) if total else 0,
        'mediana_dias': mediana, 'base_tempo': len(tempos),
        'de': datas[0] if datas else None, 'ate': datas[-1] if datas else None,
    }
    return render_template('ebook_vendas.html', resumo=resumo, perfil=perfil,
                           objecoes=objecoes, followups=followups,
                           cidades=cidades.most_common(8), operadoras=operadoras.most_common(8),
                           gerado_em=datetime.now(TZ_SP))


