@app.route('/playbook')
@login_required
@admin_required
def playbook():
    """Playbook de vendas aprendido com quem FECHOU: por objeção, os casos reais
    de fechamento onde ela apareceu (o consultor novo lê como foi contornada) +
    o follow-up sugerido. É o material de treino e a base de conhecimento pro
    copiloto de IA."""
    conn = db()
    clientes = _fechados_com_analise(conn)
    close_db(conn)
    # Agrupa por objeção: cada objeção -> casos de fechamento onde apareceu.
    por_objecao = {}
    for c in clientes:
        if not c['analise_id']:
            continue
        for o in (c['objecoes'] or []):
            chave = str(o).strip().lower()
            if not chave:
                continue
            por_objecao.setdefault(chave, []).append(c)
    objecoes = sorted(
        ({'nome': k, 'qtd': len(v), 'casos': v} for k, v in por_objecao.items()),
        key=lambda x: -x['qtd'])
    # Follow-ups reais de quem fechou (exemplos de mensagem que converteu).
    followups = [c for c in clientes if c['analise_id'] and c['followup']][:20]
    total_com_analise = sum(1 for c in clientes if c['analise_id'])
    return render_template('playbook.html', objecoes=objecoes, followups=followups,
                           total_fechados=len(clientes), total_com_analise=total_com_analise)


def _comissao_por_midia(conn, f_mes=None):
    """Comissão agrupada por CAMPANHA e por CRIATIVO da mídia paga.

    É a pergunta que o relatório de leads não responde: não "qual anúncio gera
    lead", mas "qual anúncio paga a folha". Um criativo pode trazer o dobro de
    leads e metade da comissão — e no relatório de volume ele parece o melhor.

    Só é possível por causa das duas costuras: propostas.lead_id liga a venda ao
    lead, e a campanha/criativo do lead sai do dados_extras que a ingestão já
    gravava. Sem lead_id isso teria que recasar por telefone a cada consulta.

    Propostas SEM lead_id entram como 'Sem lead vinculado' em vez de sumir: uma
    linha faltando num relatório de dinheiro é pior que uma linha honesta dizendo
    que não sabemos a origem.
    """
    # Monta o filtro aqui em vez de receber o SQL pronto do /bi: o de lá não tem
    # prefixo de tabela ('AND mes_meta=?') e nesta query há JOIN, onde a coluna
    # precisa ser qualificada.
    if f_mes and f_mes != 'todos':
        filtro, params = " AND p.mes_meta=?", [f_mes]
    else:
        filtro, params = "", []
    try:
        rows = conn.execute(f"""
            SELECT p.id, p.valor, p.comissao_total_corretora bruto,
                   p.comissao_consultor do_consultor,
                   p.comissao_corretora_liquida liquido,
                   p.lead_id, l.dados_extras, l.origem, l.trafego
            FROM propostas p
            LEFT JOIN crm_leads l ON l.id = p.lead_id
            WHERE p.status <> 'Excluída' AND COALESCE(p.estornada,0)=0{filtro}
        """, params).fetchall()
    except Exception as e:
        app.logger.warning(f"[BI/MIDIA] consulta falhou: {e}")
        return []

    SEM = 'Sem lead vinculado'
    grupos = {}
    for r in rows:
        if not r['lead_id']:
            campanha, criativo, origem = SEM, '', ''
        else:
            campanha = _campo_de_midia(r['dados_extras'], 'campaign') or 'Sem campanha'
            criativo = _campo_de_midia(r['dados_extras'], 'content') or ''
            origem = _campo_de_midia(r['dados_extras'], 'source') or (r['origem'] or '')
        chave = (campanha, criativo)
        g = grupos.setdefault(chave, {'campanha': campanha, 'criativo': criativo, 'origem': origem,
                                      'vendas': 0, 'producao': 0.0, 'bruto': 0.0,
                                      'do_consultor': 0.0, 'liquido': 0.0})
        g['vendas'] += 1
        g['producao'] += float(r['valor'] or 0)
        g['bruto'] += float(r['bruto'] or 0)
        g['do_consultor'] += float(r['do_consultor'] or 0)
        g['liquido'] += float(r['liquido'] or 0)
    out = list(grupos.values())
    for g in out:
        # Líquido por venda é o que compara criativos de tamanhos diferentes:
        # muito volume com ticket baixo deixa de parecer melhor que o contrário.
        g['liquido_por_venda'] = (g['liquido'] / g['vendas']) if g['vendas'] else 0
    # Sem vínculo sempre no fim: é ruído de dado, não desempenho de campanha.
    out.sort(key=lambda g: (g['campanha'] == SEM, -g['liquido']))
    return out


@app.route('/bi')
@login_required
def bi():
    conn = db(); uid = session['user_id']; ea = session['perfil'] == 'admin'
    # Filtro por COMPETÊNCIA (mes_meta = ciclo de vendas), igual ao dashboard
    # de propostas ('/', filtro 'mes') — mesmo parâmetro, mesmo default (mês
    # atual) e mesma opção 'todos'. Pedido explícito do Guilherme pra esta
    # aba funcionar do mesmo jeito.
    f_mes = (request.args.get('mes') or '').strip() or datetime.now(TZ_SP).strftime('%Y-%m')
    if f_mes == 'todos':
        filtro_mes_sql, filtro_mes_params = "", []
    else:
        filtro_mes_sql, filtro_mes_params = " AND mes_meta=?", [f_mes]
    # Base comum: mesmo filtro de validade que _producao_mes usa pra definir
    # comissão (excluída/estornada não conta) + a competência selecionada.
    base_sql = "status <> 'Excluída' AND COALESCE(estornada,0)=0" + filtro_mes_sql
    meses_disponiveis = [r['mes_meta'] if hasattr(r, 'keys') else r[0] for r in conn.execute(
        "SELECT DISTINCT mes_meta FROM propostas WHERE mes_meta IS NOT NULL AND mes_meta != '' ORDER BY mes_meta DESC").fetchall()]
    # Mesmo filtro do dashboard: periodo torto no banco nao vira opcao na tela.
    meses_disponiveis = [x for x in meses_disponiveis if _mes_meta_valido(x)]
    mes_atual_sp = datetime.now(TZ_SP).strftime('%Y-%m')
    if mes_atual_sp not in meses_disponiveis:
        meses_disponiveis.insert(0, mes_atual_sp)
    if ea:
        # Tendência histórica por mês — visão de série temporal, propositalmente
        # NÃO filtrada pela competência selecionada (é o gráfico que já mostra
        # todos os meses lado a lado; filtrar reduziria a 1 barra só).
        por_mes = conn.execute("""SELECT strftime('%Y-%m',criado_em) mes,COUNT(*) qtd,
            COALESCE(SUM(valor),0) valor,COALESCE(SUM(comissao_total_corretora),0) com_total,
            COALESCE(SUM(comissao_consultor),0) com_consultor,COALESCE(SUM(comissao_corretora_liquida),0) com_liquido
            FROM propostas GROUP BY mes ORDER BY mes""").fetchall()
        # WHERE 1=1 (não status<>'Excluída' — preserva o comportamento que já
        # existia aqui antes desta mudança; só a competência é nova) porque
        # filtro_mes_sql começa com "AND" e antes essas 3 consultas não tinham
        # WHERE nenhum.
        por_operadora = conn.execute(f"""SELECT adm_operadora op,COUNT(*) qtd,COALESCE(SUM(valor),0) valor,
            COALESCE(SUM(comissao_total_corretora),0) com,COALESCE(SUM(total_vidas),0) vidas
            FROM propostas WHERE 1=1{filtro_mes_sql} GROUP BY adm_operadora ORDER BY valor DESC""", filtro_mes_params).fetchall()
        por_modalidade = conn.execute(f"""SELECT modalidade,COUNT(*) qtd,COALESCE(SUM(valor),0) valor
            FROM propostas WHERE 1=1{filtro_mes_sql} GROUP BY modalidade ORDER BY valor DESC""", filtro_mes_params).fetchall()
        por_consultor = conn.execute(f"""SELECT consultor,COUNT(*) qtd,COALESCE(SUM(valor),0) valor,
            COALESCE(SUM(comissao_consultor),0) com,COALESCE(SUM(total_vidas),0) vidas
            FROM propostas WHERE 1=1{filtro_mes_sql} GROUP BY consultor ORDER BY valor DESC""", filtro_mes_params).fetchall()
        # % GERAL sobre a produção do período filtrado: quanto da produção virou
        # comissão bruta, quanto foi repassado ao consultor e quanto ficou de
        # líquido — visão agregada de "tudo", não por consultor.
        geral = conn.execute(f"""SELECT COALESCE(SUM(valor),0) producao,
                COALESCE(SUM(comissao_total_corretora),0) bruto,
                COALESCE(SUM(comissao_consultor),0) do_consultor,
                COALESCE(SUM(comissao_corretora_liquida),0) liquido
            FROM propostas WHERE {base_sql}""", filtro_mes_params).fetchone()
        prod = geral['producao'] or 0
        pct_geral = {
            'producao': prod,
            'bruto': geral['bruto'] or 0, 'bruto_pct': (geral['bruto'] or 0) / prod * 100 if prod else 0,
            'consultor': geral['do_consultor'] or 0, 'consultor_pct': (geral['do_consultor'] or 0) / prod * 100 if prod else 0,
            'liquido': geral['liquido'] or 0, 'liquido_pct': (geral['liquido'] or 0) / prod * 100 if prod else 0,
        }
        # KPI: média de comissão POR MÊS por consultor, nos 3 níveis (bruto que
        # entra na corretora, parte do consultor, líquido que sobra). Agrupado
        # por mes_meta (CICLO de vendas, não mês do calendário). A média é por
        # MÊS ATIVO (mês em que a pessoa produziu) — dividir por todos os
        # meses do histórico puniria quem entrou depois. Respeita a mesma
        # competência selecionada acima (com 'todos' vira a média histórica).
        # CAST em criado_em: substr() direto em timestamp quebra no Postgres.
        com_media = conn.execute(f"""SELECT consultor,
                COUNT(DISTINCT COALESCE(NULLIF(mes_meta,''), substr(CAST(criado_em AS TEXT),1,7))) meses,
                COUNT(*) qtd,
                COALESCE(SUM(valor),0) producao,
                COALESCE(SUM(comissao_total_corretora),0) bruto,
                COALESCE(SUM(comissao_consultor),0) do_consultor,
                COALESCE(SUM(comissao_corretora_liquida),0) liquido
            FROM propostas
            WHERE {base_sql}
            GROUP BY consultor""", filtro_mes_params).fetchall()
        media_comissao = []
        for r in com_media:
            m = r['meses'] or 0
            if not m:
                continue
            prod_c = r['producao'] or 0
            media_comissao.append({
                'consultor': r['consultor'] or '—', 'meses': m, 'qtd': r['qtd'],
                'bruto_mes': (r['bruto'] or 0) / m,
                'consultor_mes': (r['do_consultor'] or 0) / m,
                'liquido_mes': (r['liquido'] or 0) / m,
                'bruto_total': r['bruto'] or 0,
                'consultor_total': r['do_consultor'] or 0,
                'liquido_total': r['liquido'] or 0,
                # % sobre a PRODUÇÃO do consultor (mesma lógica do card geral) —
                # normal passar de 100%: comissão é em Nº DE MENSALIDADES
                # acumuladas (ex: 2,8 mensalidades = 280%), não uma fração de
                # uma mensalidade só (ver /operadoras, onde isso é configurado).
                'bruto_pct': (r['bruto'] or 0) / prod_c * 100 if prod_c else 0,
                'consultor_pct': (r['do_consultor'] or 0) / prod_c * 100 if prod_c else 0,
                'liquido_pct': (r['liquido'] or 0) / prod_c * 100 if prod_c else 0,
            })
        media_comissao.sort(key=lambda x: x['bruto_mes'], reverse=True)
        # DIAGNÓSTICO: propostas do período com comissão bruta zerada — sinal
        # de que falta cadastrar o RECEBIMENTO ou o REPASSE daquela operadora/
        # plano em /operadoras ou /repasses. Esse check já existia (motor
        # calc_comissao já gera o aviso 'Falta RECEBIMENTO'/'Falta REPASSE',
        # e /admin/db/detalhes já contava quantas tinham comissão zerada) mas
        # ficava só num endpoint JSON interno que ninguém via na prática
        # (Guilherme, 29/07: "tem como eu saber se tem algo de errado"). Reusa
        # o MESMO calc_comissao da tela de detalhe da proposta, só que
        # aplicado a todas as zeradas do período, agrupado por aviso pra não
        # virar uma lista repetida de 40 linhas iguais.
        zeradas = conn.execute(f"""SELECT id, razao_social, adm_operadora, modalidade,
                tipo_pessoa, valor, usuario_id
            FROM propostas WHERE {base_sql}
              AND COALESCE(valor,0) > 0
              AND (comissao_total_corretora IS NULL OR comissao_total_corretora = 0)
            ORDER BY id""", filtro_mes_params).fetchall()
        avisos_comissao = []
        if zeradas:
            regimes = {}
            for r in conn.execute("SELECT id, regime_base FROM usuarios").fetchall():
                regimes[r['id']] = r['regime_base'] or 'sem_lead_sem_fixo'
            por_aviso = {}
            for p in zeradas:
                try:
                    cc = calc_comissao(p['adm_operadora'], regimes.get(p['usuario_id'], 'sem_lead_sem_fixo'),
                                       0, p['valor'] or 0, p['modalidade'],
                                       p['tipo_pessoa'] if 'tipo_pessoa' in p.keys() else '')
                    aviso = (cc.get('aviso') or '').strip()
                except Exception:
                    aviso = ''
                chave = aviso or f"Comissão zerada: {p['adm_operadora'] or '—'} / {p['modalidade'] or '—'} (verificar cadastro)"
                if chave not in por_aviso:
                    por_aviso[chave] = {'aviso': chave, 'qtd': 0, 'valor': 0, 'exemplos': []}
                por_aviso[chave]['qtd'] += 1
                por_aviso[chave]['valor'] += p['valor'] or 0
                if len(por_aviso[chave]['exemplos']) < 4:
                    por_aviso[chave]['exemplos'].append({'id': p['id'], 'nome': p['razao_social']})
            avisos_comissao = sorted(por_aviso.values(), key=lambda x: x['qtd'], reverse=True)
    else:
        por_mes = conn.execute("""SELECT strftime('%Y-%m',criado_em) mes,COUNT(*) qtd,
            COALESCE(SUM(valor),0) valor,COALESCE(SUM(comissao_consultor),0) com_consultor
            FROM propostas WHERE usuario_id=? GROUP BY mes ORDER BY mes""",(uid,)).fetchall()
        por_operadora = conn.execute(f"""SELECT adm_operadora op,COUNT(*) qtd,COALESCE(SUM(valor),0) valor,
            COALESCE(SUM(comissao_consultor),0) com,COALESCE(SUM(total_vidas),0) vidas
            FROM propostas WHERE usuario_id=?{filtro_mes_sql}
            GROUP BY adm_operadora ORDER BY valor DESC""", [uid] + filtro_mes_params).fetchall()
        por_modalidade = conn.execute(f"""SELECT modalidade,COUNT(*) qtd,COALESCE(SUM(valor),0) valor
            FROM propostas WHERE usuario_id=?{filtro_mes_sql}
            GROUP BY modalidade ORDER BY valor DESC""", [uid] + filtro_mes_params).fetchall()
        por_consultor = []
        # Consultor vê só a própria % e a própria média — bruto da corretora e
        # líquido da Serenus são margem da empresa, não vão pra cá.
        r = conn.execute(f"""SELECT COALESCE(SUM(valor),0) producao,
                COALESCE(SUM(comissao_consultor),0) do_consultor
            FROM propostas WHERE usuario_id=? AND {base_sql}""", [uid] + filtro_mes_params).fetchone()
        prod = r['producao'] or 0
        pct_geral = {
            'producao': prod, 'consultor': r['do_consultor'] or 0,
            'consultor_pct': (r['do_consultor'] or 0) / prod * 100 if prod else 0,
        }
        r2 = conn.execute(f"""SELECT
                COUNT(DISTINCT COALESCE(NULLIF(mes_meta,''), substr(CAST(criado_em AS TEXT),1,7))) meses,
                COUNT(*) qtd,
                COALESCE(SUM(comissao_consultor),0) do_consultor
            FROM propostas WHERE usuario_id=? AND {base_sql}""", [uid] + filtro_mes_params).fetchone()
        media_comissao = []
        if r2 and (r2['meses'] or 0):
            media_comissao.append({
                'consultor': session.get('nome') or 'Você', 'meses': r2['meses'], 'qtd': r2['qtd'],
                'consultor_mes': (r2['do_consultor'] or 0) / r2['meses'],
                'consultor_total': r2['do_consultor'] or 0,
                'consultor_pct': pct_geral['consultor_pct'],
            })
        # Diagnóstico de cadastro é operação da corretora (config de operadora/
        # repasse) — só admin vê, mesma régua do bruto/líquido nesta página.
        avisos_comissao = []
    # Comissão por campanha/criativo é leitura de investimento em mídia — visão de
    # corretora, mesma régua do bruto/líquido nesta página.
    por_midia = _comissao_por_midia(conn, f_mes) if ea else []
    # Antes de fechar a conexão — senão a consulta falha calada e a seção
    # simplesmente não aparece, que foi exatamente o que aconteceu aqui.
    saude = _bi_saude_dinheiro(conn, f_mes) if (ea and FINANCEIRO_NOVO) else None
    close_db(conn)
    return render_template('bi.html', por_mes=por_mes, por_operadora=por_operadora,
                           por_modalidade=por_modalidade, por_consultor=por_consultor,
                           media_comissao=media_comissao, pct_geral=pct_geral,
                           avisos_comissao=avisos_comissao, por_midia=por_midia,
                           saude=saude,
                           f_mes=f_mes, meses_disponiveis=meses_disponiveis)


def _bi_saude_dinheiro(conn, mes=None):
    """Saúde do dinheiro: o que era esperado, o que entrou, o que escapou.

    O BI respondia 'quanto vendemos'. Isso responde 'quanto realmente entra e
    quanto escapa' — que é outra pergunta, e é a que dói. Três blocos:
    recebimento (esperado x recebido), escape (estornos) e projeção (pela régua
    real da operadora, não pela do consultor)."""
    out = {'tem_dados': False}
    try:
        # ── 1. Recebimento: esperado x recebido, no líquido ──
        conf = conferir_comissao(conn, competencia=mes or None, limite=5000)
        r = conf['resumo']
        # Nomes vindos do razão. 'recebido' passa a ser o que ENTROU na conta
        # (entrada_confirmada), não o que a Affinity apurou — são coisas
        # diferentes e a tela agora mostra as duas.
        out['esperado'] = r['total_previsto']
        out['apurado'] = r['total_apurado']
        out['recebido'] = r['total_entrou']
        out['repassado'] = r['total_repassado']
        out['estorno_parcelas'] = r['total_estorno']
        out['diferenca'] = r['total_diferenca']
        out['linhas_ok'] = r['ok']
        out['linhas_dif'] = r['divergentes']
        out['linhas_sem'] = r['sem_extrato']
        # Aderência = o que a Affinity apurou contra o que era previsto.
        out['aderencia'] = round((r['total_apurado'] / r['total_previsto'] * 100), 1) \
            if r['total_previsto'] else 0.0
        # Do que ela apurou, quanto se provou que entrou na conta.
        out['entrou_do_apurado'] = round((r['total_entrou'] / r['total_apurado'] * 100), 1) \
            if r['total_apurado'] else 0.0
        out['aguardando'] = round(r['total_apurado'] - r['total_entrou'], 2)

        # Onde o dinheiro escapa: operadoras com maior divergência acumulada
        porop = {}
        for l in conf['linhas']:
            if l['situacao'] in ('ok', 'sem_extrato'):
                continue
            k = l['operadora'] or '—'
            d = porop.setdefault(k, {'operadora': k, 'diferenca': 0.0, 'linhas': 0})
            d['diferenca'] += l['diferenca']; d['linhas'] += 1
        out['divergencia_operadora'] = sorted(
            porop.values(), key=lambda x: x['diferenca'])[:8]

        # ── 2. Escape: estornos aplicados ──
        w, p = [], []
        if mes:
            w.append("substr(CAST(ea.criado_em AS TEXT),1,7) = ?"); p.append(mes)
        onde = ('WHERE ' + ' AND '.join(w)) if w else ''
        est = dict(conn.execute(f"""
            SELECT COALESCE(SUM(ea.valor_estornado),0) total, COUNT(*) qtd
              FROM estorno_aplicado ea {onde}""", tuple(p)).fetchone())
        out['estorno_total'] = round(float(est['total'] or 0), 2)
        out['estorno_qtd'] = int(est['qtd'] or 0)
        out['estorno_operadora'] = [dict(x) for x in conn.execute(f"""
            SELECT p.adm_operadora operadora, COALESCE(SUM(ea.valor_estornado),0) total,
                   COUNT(*) qtd
              FROM estorno_aplicado ea JOIN propostas p ON p.id = ea.proposta_id
              {onde}
             GROUP BY p.adm_operadora ORDER BY total DESC LIMIT 6""", tuple(p)).fetchall()]
        # Taxa de escape: quanto do que entrou voltou pela porta dos fundos
        out['taxa_estorno'] = round((out['estorno_total'] / out['recebido'] * 100), 1) \
            if out['recebido'] else 0.0
        out['retencoes'] = 0.0   # retenção vive no painel do razão, não aqui

        # ── 3. Projeção: o que ainda vai entrar, mês a mês, pela régua real ──
        hoje = datetime.now(TZ_SP).strftime('%Y-%m')
        out['projecao'] = [dict(x) for x in conn.execute("""
            SELECT pa.competencia mes,
                   COALESCE(SUM(pa.valor_corretora),0) corretora,
                   COALESCE(SUM(pa.valor),0) consultor,
                   COUNT(*) qtd
              FROM parcelas pa JOIN propostas p ON p.id = pa.proposta_id
             WHERE pa.competencia >= ?
               AND pa.status NOT IN ('Pago ao corretor','Cancelada / Estornada')
               AND p.status <> 'Excluída' AND COALESCE(p.estornada,0) = 0
             GROUP BY pa.competencia ORDER BY pa.competencia LIMIT 8""", (hoje,)).fetchall()]
        out['projecao_total'] = round(sum(float(x['corretora'] or 0) for x in out['projecao']), 2)

        # ── 4. Régua cadastrada? Sem isso a projeção é chute ──
        tot_op = conn.execute("SELECT COUNT(*) c FROM recebimento").fetchone()['c']
        com_regua = conn.execute("""SELECT COUNT(*) c FROM recebimento
            WHERE regua_json IS NOT NULL AND regua_json <> '' AND regua_json <> '[]'""").fetchone()['c']
        out['op_total'] = tot_op
        out['op_com_regua'] = com_regua
        out['cobertura_regua'] = round((com_regua / tot_op * 100), 0) if tot_op else 0

        out['tem_dados'] = True
    except Exception as e:
        app.logger.warning(f"[BI] saude do dinheiro falhou: {e}")
    return out

# ─── USUÁRIOS ────────────────────────────────────────────────────────────────────
@app.route('/usuarios')
@login_required
@admin_required
def usuarios():
    conn = db()
    rows = conn.execute("SELECT * FROM usuarios ORDER BY id").fetchall()
    funis_l = [dict(r) for r in conn.execute(
        "SELECT id, nome, categoria FROM whatsapp_funis WHERE COALESCE(ativo,1)=1 ORDER BY nome").fetchall()]
    close_db(conn)
    # dict simples: Row do SQLite não é serializável pelo |tojson do template,
    # e o hash de senha não deve ir para o HTML
    usuarios_l = []
    for r in rows:
        d = dict(r)
        d['senha_hash'] = bool(d.get('senha_hash'))
        d.pop('reset_token', None)
        usuarios_l.append(d)
    return render_template('usuarios.html', usuarios=usuarios_l, host=request.host_url.rstrip('/'),
                           modulos=MODULOS, funis=funis_l)

@app.route('/usuario/novo', methods=['POST'])
@login_required
@admin_required
def usuario_novo():
    d = request.form
    nome=d.get('nome','').strip(); email=d.get('email','').strip().lower()
    if not nome or not email:
        flash('Nome e e-mail obrigatórios.'); return redirect(url_for('usuarios'))
    token=secrets.token_urlsafe(32); expira=(datetime.now(TZ_SP)+timedelta(days=7)).isoformat()
    cpf = d.get('cpf','').strip()
    conn = db()
    try:
        # Regime de comissão: consultor usa o que foi escolhido no form.
        # Admin, supervisor e gestor vendedor NÃO usam regime de consultor — a
        # comissão deles vem da REGRA DO GESTOR, que é por operadora, variação e
        # plano (ver _gestor_regra_buscar). Gravar 'sem_lead_sem_fixo' neles era
        # o que fazia a venda de um gestor cair na régua de consultor sem
        # ninguém ter escolhido isso, e ainda mostrava na tela um regime que não
        # era o aplicado. Fica em branco de propósito: em branco aqui quer dizer
        # "não é por regime, é por regra comercial".
        conn.execute("""INSERT INTO usuarios (nome,email,perfil,regime_base,token_setup,token_expira,cpf)
            VALUES (?,?,?,?,?,?,?)""",(nome,email,d.get('perfil','consultor'),
            (d.get('regime_base','sem_lead_sem_fixo') if d.get('perfil','consultor')=='consultor' else ''),token,expira,cpf or None))
        conn.commit()
    except sqlite3.IntegrityError:
        flash('E-mail já cadastrado.'); close_db(conn); return redirect(url_for('usuarios'))
    close_db(conn)
    return redirect(url_for('usuarios', link_token=token))

@app.route('/usuario/foto/upload', methods=['POST'])
@login_required
def usuario_foto_upload():
    """Upload de foto de perfil via AJAX. Salva em R2 com fallback local."""
    fimg = request.files.get('foto')
    if not fimg or not fimg.filename:
        return jsonify({"ok": False, "erro": "Arquivo não enviado"}), 400

    ext = os.path.splitext(fimg.filename)[1].lower()
    if ext not in ('.png', '.jpg', '.jpeg', '.webp'):
        return jsonify({"ok": False, "erro": "Formato inválido. Use PNG, JPG ou WebP"}), 400

    fimg.seek(0, os.SEEK_END)
    if fimg.tell() > 2 * 1024 * 1024:
        return jsonify({"ok": False, "erro": "Arquivo muito grande (máx 2MB)"}), 400
    fimg.seek(0)

    # Admin pode alterar foto de outro usuário
    uid_logado = session.get('user_id')
    uid_alvo = request.form.get('uid', uid_logado)
    if str(uid_alvo) != str(uid_logado) and session.get('perfil') != 'admin':
        return jsonify({"ok": False, "erro": "Sem permissão"}), 403
    uid_alvo = int(uid_alvo)

    conn = db()
    foto_antiga = conn.execute("SELECT foto FROM usuarios WHERE id=?", (uid_alvo,)).fetchone()

    foto_nome = f"perfil_{uid_alvo}_{datetime.now(TZ_SP).strftime('%Y%m%d%H%M%S')}{ext}"
    
    # Upload para R2 + fallback local
    try:
        upload_arquivo_r2(fimg, foto_nome)
    except Exception as e:
        app.logger.warning(f"[FOTO] R2 falhou, usando local: {e}")
        fimg.seek(0)
        fimg.save(os.path.join(UPLOAD_FOLDER, foto_nome))

    conn.execute("UPDATE usuarios SET foto=? WHERE id=?", (foto_nome, uid_alvo))
    conn.commit(); close_db(conn)

    # Se é a própria foto, atualiza a sessão para aparecer na sidebar
    if uid_alvo == uid_logado:
        session['foto'] = foto_nome

    return jsonify({"ok": True, "foto": foto_nome})

@app.route('/usuario/editar/<int:uid>', methods=['POST'])
@login_required
@admin_required
def usuario_editar(uid):
    d = request.form; conn = db()
    ativo = 1 if d.get('ativo') else 0   # checkbox: ausente = inativo
    def fnum(k):
        v = (d.get(k,'') or '').replace('.','').replace(',','.')
        try: return float(v) if v else 0
        except: return 0
    # Foto de perfil (upload opcional)
    foto_atual = conn.execute("SELECT foto FROM usuarios WHERE id=?", (uid,)).fetchone()
    foto_nome = foto_atual['foto'] if foto_atual else None
    fimg = request.files.get('foto')
    if fimg and fimg.filename:
        ext = os.path.splitext(fimg.filename)[1].lower()
        if ext in ('.png','.jpg','.jpeg','.webp'):
            foto_nome = f"perfil_{uid}_{datetime.now(TZ_SP).strftime('%Y%m%d%H%M%S')}{ext}"
            # R2 + fallback local — mesmo padrão de usuario_foto_upload().
            # Salvar só local aqui sumia no próximo deploy (Railway não
            # persiste disco).
            try:
                upload_arquivo_r2(fimg, foto_nome)
            except Exception as e:
                app.logger.warning(f"[FOTO] R2 falhou, usando local: {e}")
                fimg.seek(0)
                fimg.save(os.path.join(UPLOAD_FOLDER, foto_nome))
    # Módulos liberados (checkboxes). "modulos_todos" marcado = sem restrição
    # (grava NULL = tudo). Senão grava só os marcados. Só vale pra não-admin.
    if d.get('modulos_todos') or d.get('perfil') == 'admin':
        modulos_val = None
    else:
        marcados = [k for k in _MODULOS_KEYS if d.get('mod_' + k)]
        modulos_val = json.dumps(marcados)
    funil_atendimento_id = (d.get('funil_atendimento_id', '') or '').strip()
    funil_atendimento_id = int(funil_atendimento_id) if funil_atendimento_id.isdigit() else None
    # Regime de comissão: consultor usa o que veio do form; admin, supervisor e
    # gestor vendedor ficam SEM regime — a comissão deles vem da regra do gestor,
    # por operadora/variação/plano. Mesmo motivo do usuario_novo acima.
    conn.execute("""UPDATE usuarios SET nome=?,email=?,perfil=?,regime_base=?,ativo=?,valor_fixo=?,chave_pix=?,foto=?,cpf=?,telefone=?,waspeed_token=?,modulos=?,funil_atendimento_id=? WHERE id=?""",
        (d['nome'],d['email'].lower(),d['perfil'],
         (d['regime_base'] if d['perfil']=='consultor' else ''),ativo,fnum('valor_fixo'),d.get('chave_pix',''),foto_nome,d.get('cpf','') or None,
         d.get('telefone','').strip(),d.get('waspeed_token','').strip() or None,modulos_val,funil_atendimento_id,uid))
    conn.commit(); close_db(conn)
    return redirect(url_for('usuarios'))

@app.route('/usuario/regenerar-link/<int:uid>')
@require_auth
@require_admin
def usuario_regenerar(uid):
    """Regenera link de setup pra usuário."""
    try:
        if not uid or uid <= 0:
            app.logger.warning(f"[usuarios] ID inválido pra regenerar-link: {uid}")
            flash('ID de usuário inválido', 'error')
            return redirect(url_for('usuarios')), 400
        
        conn = db()
        cur = conn.cursor()
        cur.execute("SELECT id FROM usuarios WHERE id=?", (uid,))
        user = cur.fetchone()
        
        if not user:
            app.logger.warning(f"[usuarios] Usuário não encontrado: {uid}")
            flash('Usuário não encontrado', 'error')
            return redirect(url_for('usuarios')), 404
        
        token = secrets.token_urlsafe(32)
        expira = (datetime.now(TZ_SP) + timedelta(days=7)).isoformat()
        # NÃO zera senha_hash aqui. Isto só gera o link — quem entrega pro
        # usuário é o admin, manualmente, depois. Zerar na hora derrubava a
        # senha ATUAL antes de o link sequer sair da tela: se o admin
        # esquecesse de mandar (aba fechada, distração), o usuário ficava sem
        # conseguir logar com a senha antiga e sem link novo em mãos. Mantendo
        # a senha antiga válida até o setup novo ser concluído, "regenerar
        # link" vira uma ação só de adicionar um caminho, nunca de tirar o que
        # já funcionava — /setup/<token> substitui o hash quando o usuário de
        # fato define a senha nova.
        cur.execute("UPDATE usuarios SET token_setup=?, token_expira=? WHERE id=?",
                    (token, expira, uid))
        conn.commit()
        close_db(conn)
        
        app.logger.info(f"[usuarios] Link regenerado pra user_id={uid}")
        flash('Link enviado com sucesso', 'success')
        return redirect(url_for('usuarios', link_token=token))
    except Exception as e:
        app.logger.error(f"[usuarios] Erro ao regenerar link: {type(e).__name__}")
        flash('Erro ao gerar link', 'error')
        return redirect(url_for('usuarios')), 500

