@app.route('/nivel/salvar', methods=['POST'])
@login_required
@admin_required
def nivel_salvar():
    """Sincroniza a lista completa de níveis: cria, atualiza e remove."""
    dados = request.json.get('niveis', [])
    conn = db()
    codigos = []
    for i, n in enumerate(dados):
        cod = (n.get('codigo') or '').strip().lower() or f"n{i+1}"
        label = (n.get('label') or cod.upper()).strip()
        fmin = float(n['faixa_min']) if n.get('faixa_min') not in (None,'') else 0
        fmax = float(n['faixa_max']) if n.get('faixa_max') not in (None,'') else None
        codigos.append(cod)
        conn.execute("""INSERT INTO niveis (codigo,label,faixa_min,faixa_max,ordem) VALUES (?,?,?,?,?)
            ON CONFLICT(codigo) DO UPDATE SET label=excluded.label, faixa_min=excluded.faixa_min,
            faixa_max=excluded.faixa_max, ordem=excluded.ordem""", (cod, label, fmin, fmax, i+1))
    if codigos:
        ph = ','.join('?'*len(codigos))
        conn.execute(f"DELETE FROM niveis WHERE codigo NOT IN ({ph})", codigos)
    conn.commit(); close_db(conn)
    return jsonify({"ok": True})

# ─── SCORE DE UTILIZAÇÃO ───────────────────────────────────────────────────────
# Cada tipo de ação tem seu peso — pedido explícito do Guilherme ("cada coisa
# tem a sua pontuação"). Ações que exigem mais esforço/geram mais resultado
# (proposta criada, cotação enviada) pesam mais que sinais passivos (minuto
# ativo no navegador).
SCORE_PESOS = {
    'login': 10,
    'minuto_ativo': 1,       # cada heartbeat = ~2min de uso ativo real (mouse/teclado)
    'crm_ligacao': 3,
    'crm_nota': 2,
    'crm_movimentacao': 3,   # mover etapa, criar lead, qualificar
    'crm_whatsapp': 4,
    'crm_sms': 4,
    'crm_email': 3,
    'proposta_criada': 15,
    'proposta_editada': 5,
    'cotacao_enviada': 8,
}
SCORE_LABELS = {
    'login': 'Logins', 'minutos_ativos': 'Minutos ativos (navegador)',
    'crm_ligacao': 'Ligações registradas', 'crm_nota': 'Notas no CRM',
    'crm_movimentacao': 'Movimentações no CRM', 'crm_whatsapp': 'WhatsApp enviados',
    'crm_sms': 'SMS enviados', 'crm_email': 'E-mails enviados',
    'proposta_criada': 'Propostas criadas', 'proposta_editada': 'Edições de proposta',
    'cotacao_enviada': 'Cotações enviadas',
}


def _calcular_score_periodo(conn, data_inicio, data_fim):
    """data_inicio/data_fim: 'YYYY-MM-DD' (inclusive nos dois extremos — pode
    ser o mesmo dia pra manter o comportamento diário). Retorna a lista de
    usuários ativos com o score do período, ordenada do maior pro menor, com
    o detalhe de cada categoria que compôs o score (pra nunca ser uma
    caixa-preta) e o perfil (tipo) de cada usuário, pra permitir ranking
    separado por tipo de usuário na tela."""
    usuarios = conn.execute("SELECT id, nome, perfil FROM usuarios WHERE ativo=1 ORDER BY nome").fetchall()
    resultado = []
    for u in usuarios:
        uid, nome, perfil = u['id'], u['nome'], u['perfil']
        d = {}
        d['login'] = conn.execute(
            "SELECT COUNT(*) c FROM login_log WHERE usuario_id=? AND DATE(criado_em) BETWEEN ? AND ?",
            (uid, data_inicio, data_fim)).fetchone()['c']
        hb = conn.execute(
            "SELECT COALESCE(SUM(minutos_ativos),0) c FROM score_heartbeat WHERE usuario_id=? AND dia BETWEEN ? AND ?",
            (uid, data_inicio, data_fim)).fetchone()
        d['minutos_ativos'] = (hb['c'] if hb else 0) or 0

        ativ = conn.execute("""SELECT tipo, COUNT(*) c FROM crm_atividades
            WHERE usuario_nome=? AND DATE(criado_em) BETWEEN ? AND ? GROUP BY tipo""",
            (nome, data_inicio, data_fim)).fetchall()
        am = {a['tipo']: a['c'] for a in ativ}
        d['crm_ligacao'] = am.get('ligacao', 0)
        d['crm_nota'] = am.get('nota', 0)
        d['crm_movimentacao'] = am.get('movimentacao', 0) + am.get('criacao', 0) + am.get('atividade', 0)
        d['crm_whatsapp'] = am.get('whatsapp', 0)
        d['crm_sms'] = am.get('sms', 0)
        d['crm_email'] = am.get('email', 0) + am.get('cliente_email', 0)

        d['proposta_criada'] = conn.execute(
            "SELECT COUNT(*) c FROM propostas WHERE usuario_id=? AND DATE(criado_em) BETWEEN ? AND ?",
            (uid, data_inicio, data_fim)).fetchone()['c']
        d['proposta_editada'] = conn.execute(
            "SELECT COUNT(*) c FROM historico_proposta WHERE usuario_nome=? AND DATE(criado_em) BETWEEN ? AND ?",
            (nome, data_inicio, data_fim)).fetchone()['c']
        d['cotacao_enviada'] = conn.execute(
            "SELECT COUNT(*) c FROM cotacao_salva WHERE corretor_id=? AND DATE(criado_em) BETWEEN ? AND ?",
            (uid, data_inicio, data_fim)).fetchone()['c']

        score = sum(d[k] * SCORE_PESOS.get(k if k != 'minutos_ativos' else 'minuto_ativo', 0) for k in d)
        resultado.append({'usuario_id': uid, 'nome': nome, 'perfil': perfil, 'score': score, 'detalhe': d})
    resultado.sort(key=lambda x: -x['score'])
    return resultado


def _calcular_score_dia(conn, dia):
    """Compatibilidade: score de um único dia."""
    return _calcular_score_periodo(conn, dia, dia)


@app.route('/score')
@login_required
@admin_required
def score_utilizacao():
    """Painel de utilização do sistema por consultor — pra saber quem esteve
    ativo de verdade e quem sumiu, com o detalhe de cada ação que compôs o
    score (nunca é uma caixa-preta). Suporta 3 janelas: dia, semana (segunda
    a domingo da semana do dia informado) e mês (1º ao último dia do mês)."""
    dia = (request.args.get('dia') or datetime.now(TZ_SP).strftime('%Y-%m-%d')).strip()
    periodo = (request.args.get('periodo') or 'dia').strip()
    dia_dt = datetime.strptime(dia, '%Y-%m-%d').date()

    if periodo == 'semana':
        data_inicio = dia_dt - timedelta(days=dia_dt.weekday())
        data_fim = data_inicio + timedelta(days=6)
    elif periodo == 'mes':
        data_inicio = dia_dt.replace(day=1)
        prox_mes = (data_inicio.replace(day=28) + timedelta(days=4)).replace(day=1)
        data_fim = prox_mes - timedelta(days=1)
    else:
        data_inicio = data_fim = dia_dt

    conn = db()
    ranking = _calcular_score_periodo(conn, data_inicio.isoformat(), data_fim.isoformat())
    close_db(conn)
    max_score = max([r['score'] for r in ranking], default=0) or 1

    ranking_por_perfil = {}
    for r in ranking:
        ranking_por_perfil.setdefault(r['perfil'] or 'consultor', []).append(r)

    return render_template('score.html', dia=dia, periodo=periodo, ranking=ranking, max_score=max_score,
                           labels=SCORE_LABELS, pesos=SCORE_PESOS,
                           ranking_por_perfil=ranking_por_perfil,
                           data_inicio=data_inicio.strftime('%d/%m'), data_fim=data_fim.strftime('%d/%m'))


# ─── FINANCEIRO: fixo, custos, aporte, comissões futuras, estorno ─────────────────
def competencia_atual():
    return date.today().strftime('%Y-%m')


# ═══════════ FINANCEIRO — PRD Fase 1: vencimento, status e centro de custo ════
# Listas fechadas num lugar só: a tela, o filtro e o formulário leem daqui, e
# um valor novo aparece nos três sem ninguém lembrar de três lugares.
CENTROS_CUSTO = ['Estrutura', 'Ferramentas', 'Mídia', 'Pessoal', 'Impostos']
TIPOS_LANCAMENTO = ['Fixo', 'Variável', 'Recorrente', 'Parcelado', 'Pontual']
CANAIS_MIDIA = ['Meta', 'Google']
# 'Agendado' é débito automático — alguém MARCA que está agendado.
# 'Vencido' NÃO entra aqui de propósito: ver _lanc_status_efetivo.
STATUS_LANCAMENTO = ['Previsto', 'Agendado', 'Pago']


def _lanc_status_efetivo(status, data_vencimento, hoje=None):
    """Status que a tela mostra — 'Vencido' é CALCULADO, nunca gravado.

    O PRD pede o status Vencido junto de Pago/Previsto/Agendado, mas gravar
    'Vencido' no banco criaria uma mentira com data de validade: a linha só
    vira vencida quando o dia passa, e ninguém vai rodar um job de madrugada
    reescrevendo o status de todo lançamento em aberto. Guardado, ele estaria
    errado no dia seguinte à gravação — e pior, um lançamento pago depois
    ficaria 'Vencido' pra sempre.

    Derivar na leitura é sempre verdade e não precisa de manutenção: em aberto
    + vencimento no passado = Vencido."""
    st = (status or 'Previsto').strip()
    if st == 'Pago':
        return 'Pago'
    dt = _parse_dt_seguro(data_vencimento) if data_vencimento else None
    if not dt:
        return st
    ref = hoje or date.today()
    d = dt.date() if hasattr(dt, 'date') else dt
    return 'Vencido' if d < ref else st


def _lanc_faixa_where(faixa, coluna='l.data_vencimento', de=None, ate=None):
    """WHERE da faixa de vencimento + os parâmetros. Devolve ('', []) quando
    não há filtro, pra quem chama concatenar sem if.

    Os atalhos são os do PRD: 01–10, 11–20, 21–31, próximos 7 dias e VENCIDAS.
    Comparo como TEXTO porque data_vencimento é TEXT em 'AAAA-MM-DD' (e no
    Postgres substr em data exige CAST — armadilha já conhecida deste projeto).
    Formato ISO ordena igual como texto e como data, então funciona nos dois
    bancos sem função de data nenhuma."""
    f = (faixa or '').strip()
    if not f:
        return '', []
    hoje = date.today()
    if f == 'personalizado':
        # INTERVALO ESCOLHIDO A MAO. Os dois lados sao opcionais: so a data
        # inicial vale como "daqui pra frente", so a final vale como "ate".
        # Sem nenhuma das duas, nao filtra — melhor mostrar tudo que mostrar
        # uma tela vazia enquanto ele ainda esta escolhendo a data.
        d1, d2 = (de or '').strip(), (ate or '').strip()
        if d1 and d2 and d1 > d2:
            d1, d2 = d2, d1        # digitou ao contrario: entende, nao esvazia
        w, p = '', []
        if d1:
            w += " AND {c} IS NOT NULL AND {c} <> '' AND {c} >= ?".format(c=coluna); p.append(d1)
        if d2:
            w += " AND {c} IS NOT NULL AND {c} <> '' AND {c} <= ?".format(c=coluna); p.append(d2)
        return w, p
    if f == 'vencidas':
        # Em aberto E com vencimento no passado. Sem o status, um lançamento
        # já pago apareceria como vencido só por ter data antiga.
        status_coluna = 'l.status' if str(coluna).startswith('l.') else 'status'
        return (" AND COALESCE({s},'') <> 'Pago' AND {c} IS NOT NULL AND {c} <> ''"
                " AND {c} < ?".format(s=status_coluna, c=coluna), [hoje.strftime('%Y-%m-%d')])
    if f == 'proximos7':
        return (" AND {c} >= ? AND {c} <= ?".format(c=coluna),
                [hoje.strftime('%Y-%m-%d'), (hoje + timedelta(days=7)).strftime('%Y-%m-%d')])
    dias = {'01-10': ('01', '10'), '11-20': ('11', '20'), '21-31': ('21', '31')}.get(f)
    if not dias:
        return '', []
    # Só o DIA do vencimento importa aqui — a competência já é filtrada à parte,
    # então comparar os dois últimos caracteres da data resolve sem CAST.
    return (" AND {c} IS NOT NULL AND {c} <> '' AND substr({c}, 9, 2) BETWEEN ? AND ?".format(c=coluna),
            list(dias))

def gerar_fixo_mes(ano_mes):
    """Gera os lançamentos de FIXO do mês para cada consultor com fixo.
    Pago em 2 fluxos: dia 15 e dia 30 (metade em cada), conforme o calendário."""
    conn = db()
    consultores = conn.execute("""SELECT id,nome,valor_fixo FROM usuarios
        WHERE ativo=1 AND regime_base='com_fixo_lead' AND COALESCE(valor_fixo,0)>0""").fetchall()
    criados = 0
    for u in consultores:
        metade = round((u['valor_fixo'] or 0)/2, 2)
        for dia in (15, 30):
            ja = conn.execute("""SELECT id FROM lancamentos WHERE tipo='fixo' AND usuario_id=?
                AND data_competencia=? AND descricao LIKE ?""",
                (u['id'], ano_mes, f"%dia {dia}%")).fetchone()
            if not ja:
                conn.execute("""INSERT INTO lancamentos (tipo,categoria,descricao,valor,data_competencia,data_lancamento,usuario_id,status)
                    VALUES ('fixo','Fixo consultor',?,?,?,?,?,'Previsto')""",
                    (f"Fixo {u['nome']} — dia {dia}", metade, ano_mes, f"{ano_mes}-{dia:02d}", u['id']))
                criados += 1
    conn.commit(); close_db(conn)
    return criados


# ─── Meios de pagamento (cadastro) ──────────────────────────────────────────
# Registro de cartões/contas específicos usados nos custos da empresa — além
# do tipo genérico (Pix, Cartão de crédito...), guarda titular/final do
# cartão/dia de fechamento e vencimento da fatura "quando cabe" (só cartão
# tem esses campos; Pix/boleto/dinheiro/transferência não precisam).
_MEIO_TIPOS_CARTAO = ('cartao_credito', 'cartao_debito')


@app.route('/meio-pagamento/salvar', methods=['POST'])
@login_required
@admin_required
def meio_pagamento_salvar():
    d = request.json or {}
    nome = (d.get('nome') or '').strip()
    tipo = (d.get('tipo') or '').strip()
    if not nome or not tipo:
        return jsonify({"ok": False, "msg": "Nome e tipo são obrigatórios"}), 400

    def num_ou_none(v):
        try:
            return int(v)
        except (TypeError, ValueError):
            return None

    eh_cartao = tipo in _MEIO_TIPOS_CARTAO
    conn = db()
    conn.execute("""INSERT INTO meios_pagamento
        (nome, tipo, banco, titular, final_cartao, dia_fechamento, dia_vencimento_fatura, ativo)
        VALUES (?,?,?,?,?,?,?,1)""",
        (nome, tipo, (d.get('banco') or '').strip() or None,
         (d.get('titular') or '').strip() or None if eh_cartao else None,
         (d.get('final_cartao') or '').strip()[:4] or None if eh_cartao else None,
         num_ou_none(d.get('dia_fechamento')) if tipo == 'cartao_credito' else None,
         num_ou_none(d.get('dia_vencimento_fatura')) if tipo == 'cartao_credito' else None))
    mid = (conn.execute("SELECT lastval() AS id").fetchone()['id'] if DB_MODE == 'postgres'
           else conn.execute("SELECT last_insert_rowid() id").fetchone()['id'])
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "id": mid})


@app.route('/meio-pagamento/<int:mid>/editar', methods=['POST'])
@login_required
@admin_required
def meio_pagamento_editar(mid):
    d = request.json or {}
    nome = (d.get('nome') or '').strip()
    tipo = (d.get('tipo') or '').strip()
    if not nome or not tipo:
        return jsonify({"ok": False, "msg": "Nome e tipo são obrigatórios"}), 400

    def num_ou_none(v):
        try:
            return int(v)
        except (TypeError, ValueError):
            return None

    eh_cartao = tipo in _MEIO_TIPOS_CARTAO
    conn = db()
    if not conn.execute("SELECT id FROM meios_pagamento WHERE id=?", (mid,)).fetchone():
        close_db(conn); return jsonify({"ok": False, "msg": "Meio de pagamento não encontrado"}), 404
    conn.execute("""UPDATE meios_pagamento SET nome=?, tipo=?, banco=?, titular=?, final_cartao=?,
        dia_fechamento=?, dia_vencimento_fatura=? WHERE id=?""",
        (nome, tipo, (d.get('banco') or '').strip() or None,
         (d.get('titular') or '').strip() or None if eh_cartao else None,
         (d.get('final_cartao') or '').strip()[:4] or None if eh_cartao else None,
         num_ou_none(d.get('dia_fechamento')) if tipo == 'cartao_credito' else None,
         num_ou_none(d.get('dia_vencimento_fatura')) if tipo == 'cartao_credito' else None,
         mid))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True})


@app.route('/meio-pagamento/<int:mid>/toggle', methods=['POST'])
@login_required
@admin_required
def meio_pagamento_toggle(mid):
    conn = db()
    m = conn.execute("SELECT ativo FROM meios_pagamento WHERE id=?", (mid,)).fetchone()
    if not m:
        close_db(conn); return jsonify({"ok": False, "msg": "Meio de pagamento não encontrado"}), 404
    novo = 0 if m['ativo'] else 1
    conn.execute("UPDATE meios_pagamento SET ativo=? WHERE id=?", (novo, mid))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "ativo": bool(novo)})


@app.route('/meio-pagamento/<int:mid>/excluir', methods=['POST'])
@login_required
@admin_required
def meio_pagamento_excluir(mid):
    """Só exclui se não tiver nenhum lançamento vinculado — meio de pagamento
    é registro financeiro (quem pagou o quê, com qual cartão), apagar um que
    já foi usado deixaria lançamentos antigos órfãos e sem explicação. Se já
    foi usado, o caminho é desativar (toggle), não excluir."""
    conn = db()
    if not conn.execute("SELECT id FROM meios_pagamento WHERE id=?", (mid,)).fetchone():
        close_db(conn); return jsonify({"ok": False, "msg": "Meio de pagamento não encontrado"}), 404
    em_uso = conn.execute("SELECT COUNT(*) c FROM lancamentos WHERE meio_pagamento_id=?", (mid,)).fetchone()['c']
    if em_uso:
        close_db(conn)
        return jsonify({"ok": False, "msg": f"Esse meio já foi usado em {em_uso} lançamento(s) — desative em vez de excluir, pra não perder o histórico."}), 400
    conn.execute("DELETE FROM meios_pagamento WHERE id=?", (mid,))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True})


# ─── Conferência do mês: previsto × recebido, proposta por proposta ─────────
#
# "Entrou o que era pra entrar?" é a segunda das três perguntas que levam
# alguém ao Financeiro, e era a única sem resposta na tela: existia o total do
# mês e mais nada. Quando o número assustava — que foi exatamente o que
# aconteceu com a comissão inflada — não havia caminho DE DENTRO da tela para
# descobrir de quem era.
#
# RECEBIDO é dinheiro que chegou na corretora, e isso são três estados do
# fluxo, não um: chegou e não foi repassado, já liberado, já pago. Contar só
# 'Pago ao corretor' diria que nada entrou até o consultor receber, o que é o
# contrário do que a pergunta quer saber.
_PARC_RECEBIDAS = ('Recebido e não repassado', 'Liberado para o corretor', 'Pago ao corretor')


def _conferencia_mes(conn, mes):
    """Por proposta: quanto era previsto e quanto de fato entrou, na competência.

    Aplica o mesmo filtro das somas do topo (cancelada, estornada, excluída) —
    se divergir de lá, a conferência vira mais uma versão da verdade, que é
    justamente o problema que ela existe para resolver."""
    marca = ','.join(['?'] * len(_PARC_RECEBIDAS))
    linhas = conn.execute(f"""
        SELECT pr.id AS proposta_id, pr.razao_social, pr.consultor, pr.adm_operadora,
               COUNT(*) AS qtd,
               COALESCE(SUM(p.valor_corretora), 0) AS prev,
               COALESCE(SUM(CASE WHEN p.status IN ({marca})
                                 THEN p.valor_corretora ELSE 0 END), 0) AS receb
        FROM parcelas p
        JOIN propostas pr ON pr.id = p.proposta_id
        WHERE p.competencia = ?
          AND p.status <> 'Cancelada / Estornada'
          AND COALESCE(pr.estornada, 0) = 0
          AND COALESCE(pr.status, '') <> 'Excluída'
        GROUP BY pr.id, pr.razao_social, pr.consultor, pr.adm_operadora
    """, list(_PARC_RECEBIDAS) + [mes]).fetchall()
    itens = []
    for r in linhas:
        d = dict(r)
        d['falta'] = round(float(d['prev'] or 0) - float(d['receb'] or 0), 2)
        itens.append(d)
    # O QUE FALTA VEM PRIMEIRO. A tela existe pra achar o que não entrou; quem
    # já recebeu tudo não precisa de atenção nenhuma.
    itens.sort(key=lambda x: (-x['falta'], -float(x['prev'] or 0)))
    return {
        'itens': itens,
        'prev': round(sum(float(i['prev'] or 0) for i in itens), 2),
        'receb': round(sum(float(i['receb'] or 0) for i in itens), 2),
        'falta': round(sum(i['falta'] for i in itens), 2),
    }



def _previsao_meses(conn, mes, quantos=6):
    """Os próximos meses: o que entra, o que sai, e o que sobra.

    Eu tinha escrito no estudo que previsão precisaria de dado que não existe.
    Estava errado — o dado existe há meses, e nunca foi somado:

      · comissão a receber já está em `parcelas` com competência futura;
      · custo parcelado já grava N lançamentos, um por mês;
      · fixo é o valor cadastrado do consultor, dois pagamentos por mês.

    O fixo é o único CALCULADO em vez de lido: `gerar_fixo_mes` só cria os
    lançamentos quando o mês chega. Projetar sem ele daria a impressão de que
    sobra dinheiro que não sobra — e é justamente o erro que faz alguém
    aprovar um custo em novembro achando que cabe.
    """
    ano, m = int(mes[:4]), int(mes[5:7])
    meses = []
    for k in range(1, quantos + 1):
        t = (ano * 12 + (m - 1)) + k
        meses.append('%04d-%02d' % (t // 12, t % 12 + 1))
    if not meses:
        return []
    marca = ','.join(['?'] * len(meses))

    entra = {}
    for r in conn.execute(f"""
            SELECT p.competencia AS c, COALESCE(SUM(p.valor_corretora), 0) AS v
            FROM parcelas p JOIN propostas pr ON pr.id = p.proposta_id
            WHERE p.competencia IN ({marca})
              AND p.status <> 'Cancelada / Estornada'
              AND COALESCE(pr.estornada, 0) = 0
              AND COALESCE(pr.status, '') <> 'Excluída'
            GROUP BY p.competencia""", meses).fetchall():
        entra[dict(r)['c']] = float(dict(r)['v'] or 0)

    sai = {}
    for r in conn.execute(f"""
            SELECT data_competencia AS c, COALESCE(SUM(valor), 0) AS v
            FROM lancamentos WHERE tipo IN ('custo','fixo')
              AND data_competencia IN ({marca})
            GROUP BY data_competencia""", meses).fetchall():
        sai[dict(r)['c']] = float(dict(r)['v'] or 0)

    # O fixo que AINDA NÃO FOI GERADO. Sem isto, o mês que ninguém abriu
    # aparece leve e mente.
    fixo_mensal = 0.0
    try:
        fixo_mensal = float(conn.execute("""SELECT COALESCE(SUM(valor_fixo), 0) v FROM usuarios
            WHERE ativo=1 AND regime_base='com_fixo_lead' AND COALESCE(valor_fixo,0)>0"""
        ).fetchone()['v'] or 0)
    except Exception:
        fixo_mensal = 0.0
    gerados = set()
    for r in conn.execute(f"""SELECT DISTINCT data_competencia AS c FROM lancamentos
            WHERE tipo='fixo' AND data_competencia IN ({marca})""", meses).fetchall():
        gerados.add(dict(r)['c'])

    fora = []
    for c in meses:
        ent = entra.get(c, 0.0)
        lanc = sai.get(c, 0.0)
        estimado = 0.0 if c in gerados else fixo_mensal
        fora.append({'mes': c, 'entra': round(ent, 2),
                     'sai': round(lanc + estimado, 2),
                     'fixo_estimado': round(estimado, 2),
                     'saldo': round(ent - lanc - estimado, 2)})
    return fora



@app.route('/financeiro')
@login_required
@admin_required
def financeiro():
    mes = request.args.get('mes', competencia_atual())
    # Deep-link: notificação de "comprovante recebido" aponta pra cá com o
    # lançamento específico — antes caía sempre na aba/mês genérico.
    try:
        lancamento_focus = int(request.args.get('lancamento', '') or 0) or None
    except (TypeError, ValueError):
        lancamento_focus = None
    conn = db()
    # Comissões a receber (futuras) agrupadas por competência
    futuras = conn.execute("""SELECT p.competencia,
            COALESCE(SUM(p.valor),0) consultor, COALESCE(SUM(p.valor_corretora),0) corretora, COUNT(*) qtd
        FROM parcelas p
        JOIN propostas pr ON pr.id = p.proposta_id
        WHERE p.status NOT IN ('Pago ao corretor', 'Cancelada / Estornada') AND p.competencia IS NOT NULL
          AND COALESCE(pr.estornada, 0) = 0
          AND COALESCE(pr.status, '') <> 'Excluída'
        GROUP BY p.competencia ORDER BY p.competencia""").fetchall()
    # Lançamentos do mês (custos vêm com o meio de pagamento vinculado, se
    # houver, pra mostrar "Nubank •••• 4521" em vez de só "Cartão crédito").
    # ── Filtros do PRD (Fase 1). Combináveis entre si; vazio = sem filtro. ──
    f_faixa = (request.args.get('faixa') or '').strip()
    f_centro = (request.args.get('centro') or '').strip()
    f_status = (request.args.get('status_lanc') or '').strip()
    f_tipo_l = (request.args.get('tipo_lanc') or '').strip()
    f_meio = (request.args.get('meio') or '').strip()
    f_de = (request.args.get('de') or '').strip()
    f_ate = (request.args.get('ate') or '').strip()
    _w, _p = _lanc_faixa_where(f_faixa, de=f_de, ate=f_ate)
    # Intervalo manual substitui a competência; sem intervalo, competência é
    # estritamente o mês do vencimento.
    #
    # O resto da tela e sempre "o mes X". Se o intervalo escolhido a mao
    # continuasse preso a isso, pedir 25/08 a 10/09 devolveria tela vazia — e
    # tela vazia sem motivo parece defeito, nao resultado. Quando ele escolhe
    # as datas, elas mandam; a tela avisa que saiu da competencia.
    _cal_livre = bool(f_faixa == 'personalizado' and (f_de or f_ate))
    if f_centro:
        _w += " AND COALESCE(l.centro_custo,'') = ?"; _p.append(f_centro)
    if f_tipo_l:
        _w += " AND COALESCE(l.tipo_lancamento,'') = ?"; _p.append(f_tipo_l)
    if f_meio:
        _w += " AND CAST(l.meio_pagamento_id AS TEXT) = ?"; _p.append(f_meio)
    # 'Vencido' é derivado, então não vira WHERE: filtra depois, em Python,
    # pelo mesmo _lanc_status_efetivo que a tela usa — assim o que o filtro
    # entende por vencido é exatamente o que a tela mostra como vencido.
    if f_status and f_status != 'Vencido':
        _w += " AND COALESCE(l.status,'Previsto') = ?"; _p.append(f_status)

    _mes_where = "" if _cal_livre else " AND substr(COALESCE(l.data_vencimento,''),1,7)=?"
    _mes_params = [] if _cal_livre else [mes]
    custos = conn.execute("""SELECT l.*, u.nome AS consultor_nome, mp.nome AS meio_nome, mp.tipo AS meio_tipo, mp.banco AS meio_banco,
            mp.titular AS meio_titular, mp.final_cartao AS meio_final_cartao,
            mp.dia_vencimento_fatura AS meio_dia_vencimento
        FROM lancamentos l LEFT JOIN usuarios u ON u.id=l.usuario_id
        LEFT JOIN meios_pagamento mp ON mp.id = l.meio_pagamento_id
        WHERE l.tipo IN ('custo','fixo')""" + _mes_where + _w + " ORDER BY l.id DESC",
        _mes_params + _p).fetchall()
    custos = [dict(c) for c in custos]
    for c in custos:
        c['status_efetivo'] = _lanc_status_efetivo(c.get('status'), c.get('data_vencimento'))
    if f_status == 'Vencido':
        custos = [c for c in custos if c['status_efetivo'] == 'Vencido']
    aportes = conn.execute("SELECT * FROM lancamentos WHERE tipo='aporte' AND data_competencia=? ORDER BY id DESC", (mes,)).fetchall()
    reembolsos = conn.execute("SELECT * FROM lancamentos WHERE tipo='reembolso' AND data_competencia=? ORDER BY id DESC", (mes,)).fetchall()
    # A aba de fixos e o resumo usam exatamente a mesma lista filtrada da
    # tabela. Antes ela consultava data_competencia separadamente e podia
    # mostrar julho numa tela aberta em agosto.
    fixos = [c for c in custos if (c.get('tipo') or '') == 'fixo']
    # dict (não Row) — precisa ir serializado como JSON pro JS do template
    # montar o preview do meio selecionado sem chamada extra ao servidor.
    meios_pagamento = [dict(m) for m in conn.execute(
        "SELECT * FROM meios_pagamento ORDER BY ativo DESC, tipo, nome").fetchall()]
    # Totais do mês
    receber_mes = conn.execute("""SELECT COALESCE(SUM(p.valor_corretora),0) v FROM parcelas p
        JOIN propostas pr ON pr.id = p.proposta_id
        WHERE substr(COALESCE(p.data_prevista,''),1,7)=? AND p.status NOT IN ('Pago ao corretor', 'Cancelada / Estornada')
          AND COALESCE(pr.estornada, 0) = 0
          AND COALESCE(pr.status, '') <> 'Excluída'""", (mes,)).fetchone()['v']
    pagar_consultor = conn.execute("""SELECT COALESCE(SUM(p.valor),0) v FROM parcelas p
        JOIN propostas pr ON pr.id = p.proposta_id
        WHERE substr(COALESCE(p.data_prevista,''),1,7)=? AND p.status NOT IN ('Pago ao corretor', 'Cancelada / Estornada')
          AND COALESCE(pr.estornada, 0) = 0
          AND COALESCE(pr.status, '') <> 'Excluída'""", (mes,)).fetchone()['v']
    # A LISTA PASSOU A MOSTRAR CUSTO E FIXO, o total NAO pode somar os dois.
    #
    # O calendario sempre somou custo+fixo e a lista mostrava so custo — quem
    # conferia na mao nunca chegava no mesmo numero. Agora a lista mostra os
    # dois, como o calendario. Mas `total_custos_puro` alimenta o saldo, que
    # ja subtrai `total_fixos` em separado: somar tudo aqui contaria fixo duas
    # vezes e derrubaria o saldo do mes pela metade do salario.
    total_custos_puro = sum(c['valor'] for c in custos if (c.get('tipo') or '') == 'custo')
    total_fixos = sum(f['valor'] for f in fixos)
    total_custos = total_custos_puro + total_fixos
    total_aportes = sum(a['valor'] for a in aportes)
    total_reembolsos = sum(r['valor'] for r in reembolsos)
    saldo = receber_mes - pagar_consultor - total_custos_puro - total_fixos + total_aportes - total_reembolsos
    # ─── DRE do mês (regime de COMPETÊNCIA: tudo do mês, pago ou não) ───
    # Antes a DRE somava só parcelas NÃO pagas: pagar um consultor fazia a
    # receita e o repasse daquele valor SUMIREM do relatório, distorcendo o
    # resultado do mês conforme os pagamentos aconteciam. E a receita bruta só
    # contava a parte da corretora (valor_corretora), mas o repasse era
    # descontado por cima — dupla subtração da parte do consultor. Agora:
    # receita = comissão TOTAL da operadora (consultor + corretora), repasse =
    # parte do consultor (pago + a pagar), margem = parte líquida da corretora.
    tot_mes = conn.execute("""SELECT COALESCE(SUM(p.valor),0) consultor,
            COALESCE(SUM(p.valor_corretora),0) corretora FROM parcelas p
        JOIN propostas pr ON pr.id = p.proposta_id
        WHERE substr(COALESCE(p.data_prevista,''),1,7)=?
          AND p.status <> 'Cancelada / Estornada'
          AND COALESCE(pr.estornada, 0) = 0
          AND COALESCE(pr.status, '') <> 'Excluída'""", (mes,)).fetchone()
    repasse_pago = conn.execute("""SELECT COALESCE(SUM(p.valor),0) v FROM parcelas p
        JOIN propostas pr ON pr.id = p.proposta_id
        WHERE substr(COALESCE(p.data_prevista,''),1,7)=? AND p.status='Pago ao corretor'
          AND COALESCE(pr.estornada, 0) = 0
          AND COALESCE(pr.status, '') <> 'Excluída'""", (mes,)).fetchone()['v']
    dre = {
        'receita_bruta': (tot_mes['consultor'] or 0) + (tot_mes['corretora'] or 0),
        'repasse_consultores': tot_mes['consultor'] or 0,      # (-) repasses (pago + a pagar)
        'repasse_pago': repasse_pago,                          # quanto do repasse já foi pago
        'repasse_a_pagar': (tot_mes['consultor'] or 0) - repasse_pago,
        'custos_operacionais': total_custos_puro,              # (-) custos lançados
        'fixos': total_fixos,                                  # (-) fixos
        'aportes': total_aportes,                              # (+) aportes
        'reembolsos': total_reembolsos,                        # (-) reembolsos pagos aos sócios
    }
    dre['margem_bruta'] = dre['receita_bruta'] - dre['repasse_consultores']
    dre['resultado'] = dre['margem_bruta'] - dre['custos_operacionais'] - dre['fixos'] + dre['aportes'] - dre['reembolsos']

    # ─── Saldo entre sócios (histórico completo, não só do mês) ───
    # Quanto a empresa deve a cada sócio: aportes que ele colocou + custos que
    # ele pagou do próprio bolso (fonte_pagamento='Terceiro'), menos o que já
    # foi reembolsado a ele. Não é "sócio A deve a sócio B" direto (não há % de
    # sociedade cadastrado), é "quanto falta a empresa devolver a cada um".
    socios_aportes = conn.execute("""SELECT socio, COALESCE(SUM(valor),0) v FROM lancamentos
        WHERE tipo='aporte' AND socio IS NOT NULL AND socio != '' GROUP BY socio""").fetchall()
    socios_adiantado = conn.execute("""SELECT pago_por AS socio, COALESCE(SUM(valor),0) v FROM lancamentos
        WHERE tipo='custo' AND fonte_pagamento='Terceiro' AND pago_por IS NOT NULL AND pago_por != '' AND pago_por != 'Caixa da empresa'
        GROUP BY pago_por""").fetchall()
    socios_reembolsados = conn.execute("""SELECT socio, COALESCE(SUM(valor),0) v FROM lancamentos
        WHERE tipo='reembolso' AND socio IS NOT NULL AND socio != '' GROUP BY socio""").fetchall()
    saldo_socios = {}
    for r in socios_aportes:
        saldo_socios[r['socio']] = saldo_socios.get(r['socio'], 0) + r['v']
    for r in socios_adiantado:
        saldo_socios[r['socio']] = saldo_socios.get(r['socio'], 0) + r['v']
    for r in socios_reembolsados:
        saldo_socios[r['socio']] = saldo_socios.get(r['socio'], 0) - r['v']
    saldo_socios_lista = sorted(
        [{'socio': s, 'saldo': v} for s, v in saldo_socios.items() if abs(v) > 0.005],
        key=lambda x: -x['saldo'])

    # ─── Calendário de vencimentos (PRD 5) ───
    # Uma barra por dia do mês: mostra onde os pagamentos se concentram e qual
    # dia aperta o caixa. Soma custo E fixo, porque quem olha quer saber o que
    # sai do caixa naquele dia — a separação contábil não muda o aperto.
    # O CALENDARIO OBEDECE AOS FILTROS.
    #
    # Antes ele somava o mes inteiro sempre, e o numero do canto dizia
    # "vencendo neste mes" mesmo com um filtro ligado. Ficava um total de
    # R$ 2.594 em cima de uma lista que somava R$ 400, e quem esta olhando nao
    # tem como saber qual dos dois responde a pergunta dele.
    #
    # `_w`/`_p` sao os mesmos do restante da tela, entao barra, total e lista
    # contam a mesma historia. A coluna muda de `l.data_vencimento` pra
    # `data_vencimento` porque aqui nao ha o apelido da tabela.
    _cw, _cp = _lanc_faixa_where(f_faixa, coluna='data_vencimento', de=f_de, ate=f_ate)
    if f_centro:
        _cw += " AND COALESCE(centro_custo,'') = ?"; _cp.append(f_centro)
    if f_tipo_l:
        _cw += " AND COALESCE(tipo_lancamento,'') = ?"; _cp.append(f_tipo_l)
    if f_meio:
        _cw += " AND CAST(meio_pagamento_id AS TEXT) = ?"; _cp.append(f_meio)
    if f_status and f_status != 'Vencido':
        _cw += " AND COALESCE(status,'Previsto') = ?"; _cp.append(f_status)
    cal_dias, cal_max, cal_total = {}, 0, 0
    try:
        for r in conn.execute("""SELECT substr(data_vencimento, 9, 2) dia,
                   COALESCE(SUM(valor),0) v, COUNT(*) n
            FROM lancamentos
            WHERE tipo IN ('custo','fixo')""" + ("" if _cal_livre else " AND substr(COALESCE(data_vencimento,''),1,7)=?") + """
              AND data_vencimento IS NOT NULL AND data_vencimento <> ''""" + _cw + """
            GROUP BY 1""", ([] if _cal_livre else [mes]) + _cp).fetchall():
            if not (r['dia'] or '').isdigit():
                continue
            d = int(r['dia'])
            cal_dias[d] = {'valor': float(r['v'] or 0), 'qtd': r['n']}
            cal_max = max(cal_max, cal_dias[d]['valor'])
            cal_total += cal_dias[d]['valor']
    except Exception as e:
        app.logger.warning(f"[FINANCEIRO] calendário de vencimentos: {e}")
    _ano, _m = int(mes[:4]), int(mes[5:7])
    _ult = calendar.monthrange(_ano, _m)[1]
    calendario = [{'dia': d, 'valor': cal_dias.get(d, {}).get('valor', 0),
                   'qtd': cal_dias.get(d, {}).get('qtd', 0),
                   'pct': round(100 * cal_dias.get(d, {}).get('valor', 0) / cal_max) if cal_max else 0,
                   'hoje': (date.today().year == _ano and date.today().month == _m
                            and date.today().day == d)}
                  for d in range(1, _ult + 1)]
    # A CONFERENCIA E LIDA ENQUANTO A CONEXAO AINDA ESTA ABERTA.
    # `close_db` acontece logo abaixo; chamar isto dentro do render_template
    # usaria conexao fechada e a tela caia inteira.
    conferencia = _conferencia_mes(conn, mes)
    previsao = _previsao_meses(conn, mes)
    regras_faltando = _gestor_regras_faltando(conn)
    # Pergunta DIFERENTE da conferência acima: aquela compara o previsto com o
    # status interno ("marcamos como recebido?"); esta compara com o extrato da
    # Affinity, no líquido ("a administradora pagou o que devia?").
    saude = _bi_saude_dinheiro(conn, mes) if FINANCEIRO_NOVO else None
    # MESMA função que o Fluxo de Caixa chama, de propósito: enquanto cada tela
    # somava da sua própria consulta, as duas mostravam números diferentes pro
    # mesmo dinheiro e não havia como saber qual estava certa.
    fin_visao = _fin_visao(conn)
    close_db(conn)

    # O ROTULO ACOMPANHA O NUMERO. Um total que muda de valor sem dizer de que
    # periodo ele e vira desconfianca — e desconfianca num numero de dinheiro
    # faz a pessoa parar de usar a tela.
    def _br(d):
        try: return '%s/%s/%s' % (d[8:10], d[5:7], d[0:4])
        except Exception: return d
    if f_faixa == 'personalizado' and (f_de or f_ate):
        if f_de and f_ate: _cal_rotulo = 'Vencendo de %s a %s' % (_br(f_de), _br(f_ate))
        elif f_de:         _cal_rotulo = 'Vencendo a partir de %s' % _br(f_de)
        else:              _cal_rotulo = 'Vencendo até %s' % _br(f_ate)
    else:
        _cal_rotulo = {
            '01-10': 'A pagar entre os dias 01 e 10',
            '11-20': 'A pagar entre os dias 11 e 20',
            '21-31': 'A pagar entre os dias 21 e 31',
            'proximos7': 'A pagar nos próximos 7 dias',
            'vencidas': 'Já vencido e em aberto',
        }.get(f_faixa, 'A pagar neste mês')

    return render_template('financeiro.html', mes=mes, futuras=futuras,
        custos=custos, aportes=aportes, fixos=fixos, reembolsos=reembolsos,
        meios_pagamento=meios_pagamento,
        receber_mes=receber_mes, pagar_consultor=pagar_consultor,
        total_custos=total_custos, total_custos_puro=total_custos_puro, total_fixos=total_fixos,
        total_aportes=total_aportes, total_reembolsos=total_reembolsos,
        saldo=saldo, dre=dre, saldo_socios=saldo_socios_lista, lancamento_focus=lancamento_focus,
        centros_custo=CENTROS_CUSTO, tipos_lancamento=TIPOS_LANCAMENTO,
        canais_midia=CANAIS_MIDIA, status_lancamento=STATUS_LANCAMENTO,
        conferencia=conferencia, previsao=previsao, regras_faltando=regras_faltando, saude=saude,
        fin_visao=fin_visao,
        calendario=calendario, cal_total=cal_total, cal_rotulo=_cal_rotulo,
        cal_livre=_cal_livre,
        filtros={'faixa': f_faixa, 'centro': f_centro, 'status_lanc': f_status,
                 'tipo_lanc': f_tipo_l, 'meio': f_meio, 'de': f_de, 'ate': f_ate})

@app.route('/financeiro/exportar')
@login_required
@admin_required
def financeiro_exportar():
    """Exporta o recorte do Financeiro, dizendo por escrito QUAL recorte é.

    A tela tem mais de uma seção financeira (custos e fixos de um lado, comissão
    da Affinity de outro) e o arquivo só trazia a primeira, sem dizer isso em
    lugar nenhum. Quem abria a planilha via um total que não batia com o da tela
    e não tinha como saber por quê — o número estava certo para um recorte que o
    arquivo não declarava.

    Agora: o XLSX traz as DUAS seções, uma por aba, e o CSV — que não tem aba —
    traz a seção pedida com o escopo escrito na primeira linha e os filtros
    aplicados logo abaixo. O total de cada aba é o total daquela seção na tela."""
    import csv, io
    mes = request.args.get('mes', competencia_atual())
    fmt = (request.args.get('formato') or 'xlsx').lower()
    secao = (request.args.get('secao') or 'custos').strip().lower()
    if secao not in ('custos', 'comissao'):
        secao = 'custos'
    faixa, de, ate = (request.args.get('faixa') or '').strip(), (request.args.get('de') or '').strip(), (request.args.get('ate') or '').strip()
    centro, status, tipo, meio = [(request.args.get(k) or '').strip() for k in ('centro','status_lanc','tipo_lanc','meio')]
    conn = db()
    w, p = _lanc_faixa_where(faixa, coluna='l.data_vencimento', de=de, ate=ate)
    livre = bool(faixa == 'personalizado' and (de or ate))
    if not livre: w += " AND substr(COALESCE(l.data_vencimento,''),1,7)=?"; p.append(mes)
    if centro: w += " AND COALESCE(l.centro_custo,'')=?"; p.append(centro)
    if tipo: w += " AND COALESCE(l.tipo_lancamento,'')=?"; p.append(tipo)
    if meio: w += " AND CAST(l.meio_pagamento_id AS TEXT)=?"; p.append(meio)
    if status and status != 'Vencido': w += " AND COALESCE(l.status,'Previsto')=?"; p.append(status)
    rows = [dict(r) for r in conn.execute("""SELECT l.*, mp.nome meio_nome FROM lancamentos l
        LEFT JOIN meios_pagamento mp ON mp.id=l.meio_pagamento_id
        WHERE l.tipo IN ('custo','fixo')""" + w + " ORDER BY l.data_vencimento, l.id", p).fetchall()]
    for r in rows: r['status_efetivo'] = _lanc_status_efetivo(r.get('status'), r.get('data_vencimento'))
    if status == 'Vencido': rows = [r for r in rows if r['status_efetivo'] == 'Vencido']
    cab = ['Descrição','Centro de custo','Categoria','Emissão','Vencimento','Valor','Pago por','Fonte','Forma','Status']
    def br(d): return f'{d[8:10]}/{d[5:7]}/{d[:4]}' if d and len(d)>=10 else ''
    dados = [[r.get('descricao',''), r.get('centro_custo',''), r.get('categoria',''), br(r.get('data_emissao') or r.get('data_lancamento')), br(r.get('data_vencimento')), float(r.get('valor') or 0), r.get('pago_por',''), r.get('fonte_pagamento',''), r.get('meio_nome') or r.get('forma_pagamento',''), r.get('status_efetivo','')] for r in rows]
    total = sum(x[5] for x in dados)

    # ESCOPO POR ESCRITO. O que está e o que NÃO está no arquivo, junto do
    # arquivo. Sem isso, um total que não bate com a tela vira desconfiança na
    # tela inteira — e o problema quase sempre era só um filtro não declarado.
    filtros_txt = []
    if livre:
        _de_txt = de or 'o começo'
        _ate_txt = ate or 'hoje'
        filtros_txt.append(f"vencimento de {_de_txt} a {_ate_txt}")
    else:
        filtros_txt.append(f"vencimento na competência {mes}")
    if faixa and not livre: filtros_txt.append(f"faixa {faixa}")
    if centro: filtros_txt.append(f"centro de custo {centro}")
    if tipo: filtros_txt.append(f"tipo {tipo}")
    if meio: filtros_txt.append(f"meio de pagamento {meio}")
    if status: filtros_txt.append(f"status {status}")
    escopo_custos = 'Seção: custos e fixos. Filtros: ' + '; '.join(filtros_txt) + '.'

    # Seção 2: a comissão. Vem do razão, a MESMA fonte do painel da tela — o
    # arquivo não pode contar uma história diferente da que a tela contou.
    visao = _fin_visao(conn)
    cab_com = ['Indicador', 'Valor', 'O que é']
    dados_com = [
        ['Bruto esperado', visao['bruto_esperado'],
         'O que a régua congelada em cada venda diz que deveria vir. Previsão.'],
        ['Apurado pela Affinity', visao['apurado_affinity'],
         'Extratos importados. Ela diz que vai pagar. Ainda não é dinheiro na conta.'],
        ['Tarifas e débitos', visao['tarifas'],
         'Descontos do próprio extrato, como a tarifa por pagamento. Saída.'],
        ['Entrada confirmada', visao['entrada_confirmada'],
         'Provado por identificador Asaas ou confirmação humana registrada.'],
        ['Aguardando entrada', visao['aguardando_entrada'],
         'Apurado que ainda não apareceu como entrada confirmada.'],
        ['Bruto do gestor', visao['bruto_gestor'],
         'Parte do gestor antes de retenção. Obrigação a pagar.'],
        ['Retenção do gestor', visao['retencao_gestor'], 'Retenção de responsabilidade do gestor.'],
        ['Retenção da Serenus', visao['retencao_serenus'], 'Retenção de responsabilidade da empresa.'],
        ['Líquido para PIX do gestor', visao['liquido_pix_gestor'],
         'O que o gestor recebe de fato. Só sai após entrada confirmada e liberação.'],
        ['Saldo Serenus', visao['saldo_serenus'],
         'Recebido menos bruto do gestor e retenções da empresa.'],
    ]
    escopo_com = ('Seção: comissão da Affinity, lida do razão financeiro. '
                  f"Vendas de gestor com regra completa. {visao['sem_regra']} venda(s) ficaram de "
                  f"fora por regra incompleta; {visao['linhas_sem_vinculo']} linha(s) de extrato "
                  'ainda sem venda apontada.')

    def moeda_csv(v):
        return 'R$ ' + f'{v:,.2f}'.replace(',', 'X').replace('.', ',').replace('X', '.')

    if fmt == 'csv':
        # CSV não tem aba: exporta UMA seção e diz qual, na primeira linha.
        out = io.StringIO(); wri = csv.writer(out, delimiter=';')
        if secao == 'comissao':
            wri.writerow([escopo_com]); wri.writerow([])
            wri.writerow(cab_com)
            for linha in dados_com:
                wri.writerow([linha[0], moeda_csv(linha[1]), linha[2]])
        else:
            wri.writerow([escopo_custos]); wri.writerow([])
            wri.writerow(cab)
            for linha in dados: wri.writerow(linha[:5] + [moeda_csv(linha[5])] + linha[6:])
            wri.writerow(['TOTAL', '', '', '', '', moeda_csv(total)])
            wri.writerow([])
            wri.writerow(['Este arquivo traz só a seção de custos e fixos. '
                          'Para a comissão da Affinity, exporte com secao=comissao '
                          'ou use o XLSX, que traz as duas abas.'])
        close_db(conn)
        return Response('\ufeff' + out.getvalue(), mimetype='text/csv',
                        headers={'Content-Disposition':
                                 f'attachment; filename=financeiro_serenus_{secao}_{mes}.csv'})

    import openpyxl
    wb = openpyxl.Workbook()
    ws = wb.active; ws.title = 'Custos e fixos'
    ws.append([escopo_custos]); ws.append([])
    ws.append(cab)
    for row in dados: ws.append(row)
    ws.append(['TOTAL', '', '', '', '', total])
    for cell in ws['F'][3:]:
        cell.number_format = 'R$ #,##0.00'
    ws2 = wb.create_sheet('Comissao Affinity')
    ws2.append([escopo_com]); ws2.append([])
    ws2.append(cab_com)
    for row in dados_com: ws2.append(row)
    for cell in ws2['B'][3:]:
        cell.number_format = 'R$ #,##0.00'
    buf = io.BytesIO(); wb.save(buf); buf.seek(0); close_db(conn)
    return send_file(buf, as_attachment=True, download_name=f'financeiro_serenus_{mes}.xlsx',
                     mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')

def _proximo_mes(competencia, n):
    """Soma n meses a uma competência 'YYYY-MM'. Retorna 'YYYY-MM'."""
    ano, mes = int(competencia[:4]), int(competencia[5:7])
    total = (ano * 12 + (mes - 1)) + n
    return f"{total // 12}-{(total % 12) + 1:02d}"


# ─── FECHAMENTO MENSAL POR CONSULTOR ─────────────────────────────────────────
@app.route('/fechamento')
@login_required
@admin_required
def fechamento():
    """Fechamento do mês por consultor: "quanto devo ao Fulano em {mes}?" —
    fixo (lancamentos tipo fixo) + comissões (parcelas da competência) num
    lugar só, com pagamento em lote. Antes o fixo vivia no /financeiro e a
    comissão no /fluxo-caixa, e fechar o mês era caçar parcela por parcela
    (auditoria 14/07)."""
    mes = request.args.get('mes', competencia_atual())
    if len(mes) != 7:
        mes = competencia_atual()
    conn = db()
    consultores = conn.execute("""SELECT id, nome, chave_pix FROM usuarios
        WHERE ativo=1 AND perfil='consultor' ORDER BY nome""").fetchall()
    linhas = []
    tot = {'fixo_a_pagar': 0.0, 'liberado': 0.0, 'em_fluxo': 0.0, 'pago': 0.0, 'total_a_pagar': 0.0}
    for u in consultores:
        fixo = conn.execute("""SELECT COALESCE(SUM(valor),0) total,
                COALESCE(SUM(CASE WHEN status IN ('Pago','Conciliado') THEN valor ELSE 0 END),0) pago
            FROM lancamentos WHERE tipo='fixo' AND usuario_id=? AND data_competencia=?""",
            (u['id'], mes)).fetchone()
        com = conn.execute("""SELECT
                COALESCE(SUM(CASE WHEN pa.status='Liberado para o corretor' THEN pa.valor ELSE 0 END),0) liberado,
                COUNT(CASE WHEN pa.status='Liberado para o corretor' THEN 1 END) qtd_liberadas,
                COALESCE(SUM(CASE WHEN pa.status='Pago ao corretor' THEN pa.valor ELSE 0 END),0) pago,
                COALESCE(SUM(CASE WHEN pa.status NOT IN ('Liberado para o corretor','Pago ao corretor') THEN pa.valor ELSE 0 END),0) em_fluxo
            FROM parcelas pa JOIN propostas p ON p.id=pa.proposta_id
            WHERE p.usuario_id=? AND pa.competencia=?""", (u['id'], mes)).fetchone()
        fixo_a_pagar = round((fixo['total'] or 0) - (fixo['pago'] or 0), 2)
        linha = {
            'id': u['id'], 'nome': u['nome'], 'chave_pix': (u['chave_pix'] or '').strip(),
            'fixo_total': fixo['total'] or 0, 'fixo_pago': fixo['pago'] or 0, 'fixo_a_pagar': fixo_a_pagar,
            'liberado': com['liberado'] or 0, 'qtd_liberadas': com['qtd_liberadas'] or 0,
            'pago': com['pago'] or 0, 'em_fluxo': com['em_fluxo'] or 0,
        }
        linha['total_a_pagar'] = round(fixo_a_pagar + linha['liberado'], 2)
        # consultor sem nenhum movimento no mês não polui a tela
        if not any([linha['fixo_total'], linha['liberado'], linha['pago'], linha['em_fluxo']]):
            continue
        tot['fixo_a_pagar'] += fixo_a_pagar
        tot['liberado'] += linha['liberado']
        tot['em_fluxo'] += linha['em_fluxo']
        tot['pago'] += linha['pago'] + linha['fixo_pago']
        tot['total_a_pagar'] += linha['total_a_pagar']
        linhas.append(linha)
    close_db(conn)
    return render_template('fechamento.html', mes=mes, linhas=linhas, tot=tot,
                           mes_ant=_proximo_mes(mes, -1), mes_prox=_proximo_mes(mes, 1),
                           asaas_ok=asaas_configurado())


@app.route('/fechamento/pagar', methods=['POST'])
@login_required
@admin_required
def fechamento_pagar():
    """Paga o mês de UM consultor em lote.
    metodo='manual': marca as parcelas liberadas como pagas + fixo como pago
      (registro, não transfere dinheiro) e avisa o consultor com UM resumo.
    metodo='asaas': dispara PIX real parcela por parcela via Asaas — cada uma
      vira 'Pago ao corretor' quando o webhook confirmar (que também notifica).
      O fixo NÃO vai pelo Asaas (não é parcela) — marcar manual depois."""
    d = request.json or {}
    try:
        uid = int(d.get('usuario_id') or 0)
    except (TypeError, ValueError):
        uid = 0
    mes = str(d.get('mes') or '').strip()
    metodo = d.get('metodo')
    if not uid or len(mes) != 7 or metodo not in ('manual', 'asaas'):
        return jsonify({"ok": False, "erro": "Parâmetros inválidos"}), 400
    conn = db()
    parcelas = conn.execute("""SELECT pa.id, pa.valor FROM parcelas pa
        JOIN propostas p ON p.id=pa.proposta_id
        WHERE p.usuario_id=? AND pa.competencia=? AND pa.status='Liberado para o corretor'
        ORDER BY pa.id""", (uid, mes)).fetchall()
    resultado = {"parcelas_ok": 0, "parcelas_erro": [], "fixo_pago": 0.0, "total": 0.0}
    if metodo == 'asaas':
        if not asaas_configurado():
            close_db(conn)
            return jsonify({"ok": False, "erro": "Asaas não configurado. Adicione ASAAS_API_KEY no Railway."}), 400
        for pa in parcelas:
            ok, info = _pagar_parcela_asaas_core(conn, pa['id'], session.get('nome'))
            if ok:
                resultado['parcelas_ok'] += 1
                resultado['total'] += pa['valor'] or 0
            else:
                resultado['parcelas_erro'].append(f"parcela {pa['id']}: {info}")
    else:
        agora = datetime.now(TZ_SP).isoformat()
        for pa in parcelas:
            conn.execute("UPDATE parcelas SET status='Pago ao corretor', data_pagamento=? WHERE id=?",
                         (agora, pa['id']))
            resultado['parcelas_ok'] += 1
            resultado['total'] += pa['valor'] or 0
        fx = conn.execute("""SELECT COALESCE(SUM(valor),0) v FROM lancamentos
            WHERE tipo='fixo' AND usuario_id=? AND data_competencia=?
              AND COALESCE(status,'') NOT IN ('Pago','Conciliado')""", (uid, mes)).fetchone()
        if fx and fx['v']:
            conn.execute("""UPDATE lancamentos SET status='Pago', data_pagamento=?
                WHERE tipo='fixo' AND usuario_id=? AND data_competencia=?
                  AND COALESCE(status,'') NOT IN ('Pago','Conciliado')""",
                (_fmt_data_br(datetime.now(TZ_SP)), uid, mes))
            resultado['fixo_pago'] = fx['v']
            resultado['total'] += fx['v']
        conn.commit()
        if resultado['total'] > 0:
            _notificar(uid, 'comissao', f'Fechamento de {mes} pago',
                       f"{resultado['parcelas_ok']} parcela(s)" +
                       (f" + fixo de {_moeda(resultado['fixo_pago'])}" if resultado['fixo_pago'] else '') +
                       f" — total {_moeda(resultado['total'])}", '/fluxo-caixa')
    close_db(conn)
    return jsonify({"ok": True, **resultado})


def _venc_parcela(data_iso, i):
    """Vencimento da parcela i (0-based) a partir do vencimento da primeira.

    POLÍTICA DO DIA 29, 30 E 31, que é a única parte não óbvia disto:
    o vencimento cai no MESMO DIA do mês seguinte; quando esse dia não existe
    naquele mês, cai no ÚLTIMO DIA VÁLIDO dele. Vencimento dia 31 em janeiro vira
    28 (ou 29) em fevereiro e volta pra 31 em março.

    Volta pra 31, e não fica preso em 28, porque a conta é sempre feita a partir
    da data ORIGINAL — nunca a partir da parcela anterior. Encadear a partir da
    anterior faria a data escorregar mês a mês (31/01, 28/02, 28/03, 28/04...) e
    em seis parcelas o vencimento teria andado três dias sozinho.

    Vencimento em branco continua em branco: inventar data de vencimento para um
    lançamento que não tem é pior que não ter."""
    if not data_iso or len(data_iso) < 10:
        return data_iso
    if not i:
        return data_iso
    try:
        base = datetime.strptime(data_iso[:10], '%Y-%m-%d').date()
    except ValueError:
        return data_iso
    return (base + relativedelta(months=i)).strftime('%Y-%m-%d')


@app.route('/lancamento/salvar', methods=['POST'])
@login_required
@admin_required
def lancamento_salvar():
    """Cria um lançamento. Se num_parcelas > 1, divide o valor em N lançamentos
    mensais ligados por grupo_parcela (ex: compra parcelada no cartão) — cada
    parcela cai na competência do mês correspondente à emissão + i meses.
    A competência SEMPRE é derivada de data_emissao (nunca do mês que está
    sendo visualizado na tela) — evita lançamento cair na competência errada."""
    d = request.json or {}
    tipo = d.get('tipo')
    descricao = d.get('descricao')
    valor_total = float(str(d.get('valor') or 0).replace('.', '').replace(',', '.')) if isinstance(d.get('valor'), str) and ',' in str(d.get('valor')) else float(d.get('valor') or 0)
    data_emissao = (d.get('data_emissao') or d.get('data_lancamento') or '').strip()
    data_vencimento = (d.get('data_vencimento') or '').strip()
    try:
        num_parcelas = max(1, int(d.get('num_parcelas') or 1))
    except (ValueError, TypeError):
        num_parcelas = 1

    competencia_base = data_emissao[:7] if len(data_emissao) >= 7 else (d.get('data_competencia') or competencia_atual())

    conn = db()
    # Se veio um meio de pagamento cadastrado, a forma de pagamento é sempre
    # derivada do TIPO dele (não confia no que veio solto do front) — garante
    # que "Nubank final 4521" sempre aparece corretamente como cartão de
    # crédito, mesmo que o forma_pagamento enviado esteja desatualizado.
    forma_pagamento = (d.get('forma_pagamento') or '').strip()
    try:
        meio_pagamento_id = int(d.get('meio_pagamento_id')) if d.get('meio_pagamento_id') else None
    except (TypeError, ValueError):
        meio_pagamento_id = None
    if meio_pagamento_id:
        meio = conn.execute("SELECT tipo FROM meios_pagamento WHERE id=?", (meio_pagamento_id,)).fetchone()
        if meio:
            forma_pagamento = meio['tipo']
        else:
            meio_pagamento_id = None

    grupo = secrets.token_hex(6) if num_parcelas > 1 else None
    valor_parcela = round(valor_total / num_parcelas, 2)
    ids = []
    for i in range(num_parcelas):
        # Última parcela absorve a diferença de arredondamento
        valor_i = round(valor_total - valor_parcela * (num_parcelas - 1), 2) if i == num_parcelas - 1 else valor_parcela
        competencia_i = _proximo_mes(competencia_base, i) if competencia_base else competencia_atual()
        # VENCIMENTO ANDA COM A PARCELA. Antes as N parcelas nasciam com a MESMA
        # data de vencimento: a competência avançava mês a mês e o vencimento
        # ficava parado, então uma compra em 6x aparecia como seis contas
        # vencendo no mesmo dia — e o Financeiro, que passou a ordenar e somar
        # por vencimento, mostrava seis meses de despesa caindo num mês só.
        data_vencimento_i = _venc_parcela(data_vencimento, i)
        desc_i = f"{descricao} ({i+1}/{num_parcelas})" if num_parcelas > 1 else descricao
        # Centro de custo / tipo / canal: só aceita o que está na lista fechada.
        # Valor livre aqui viraria "Midia", "mídia" e "MÍDIA" como três centros
        # diferentes, e o dashboard de 64% em mídia sairia errado e calado.
        _centro = (d.get('centro_custo') or '').strip()
        _centro = _centro if _centro in CENTROS_CUSTO else None
        _tipol = (d.get('tipo_lancamento') or '').strip()
        _tipol = _tipol if _tipol in TIPOS_LANCAMENTO else None
        _canal = (d.get('canal_midia') or '').strip()
        # Canal de mídia só faz sentido em lançamento de mídia — em outro
        # centro seria ruído que estraga a soma por canal.
        _canal = _canal if (_canal in CANAIS_MIDIA and _centro == 'Mídia') else None
        # Parcelado se declara sozinho: quem lança em N parcelas está dizendo
        # o tipo pela própria ação, e obrigar a repetir no seletor só gera
        # divergência entre o que foi marcado e o que a linha é.
        if not _tipol and num_parcelas > 1:
            _tipol = 'Parcelado'
        _status_ini = (d.get('status') or 'Previsto').strip()
        if _status_ini not in STATUS_LANCAMENTO:
            _status_ini = 'Previsto'
        conn.execute("""INSERT INTO lancamentos
            (tipo,categoria,descricao,valor,data_competencia,data_lancamento,data_emissao,data_vencimento,
             socio,recorrente,status,pago_por,fonte_pagamento,forma_pagamento,meio_pagamento_id,grupo_parcela,parcela_num,parcela_total,
             centro_custo,tipo_lancamento,canal_midia)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (tipo, d.get('categoria', ''), desc_i, valor_i, competencia_i,
             data_emissao or competencia_i, data_emissao or None, data_vencimento_i or None,
             d.get('socio', ''), 1 if d.get('recorrente') else 0, _status_ini,
             (d.get('pago_por') or '').strip(), (d.get('fonte_pagamento') or '').strip(),
             forma_pagamento, meio_pagamento_id,
             grupo, i + 1 if num_parcelas > 1 else None, num_parcelas if num_parcelas > 1 else None,
             _centro, _tipol, _canal))
        lid = (conn.execute("SELECT lastval() AS id").fetchone()['id'] if DB_MODE == 'postgres'
               else conn.execute("SELECT last_insert_rowid() id").fetchone()['id'])
        ids.append(lid)
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "id": ids[0], "ids": ids, "parcelas_criadas": num_parcelas})


@app.route('/lancamento/<int:lid>/editar', methods=['POST'])
@login_required
@admin_required
def lancamento_editar(lid):
    """Edição de um lançamento já criado — antes não existia nenhuma forma de
    corrigir um lançamento, só excluir e recriar. Só atualiza os campos
    enviados no payload — campo ausente preserva o valor atual (edição
    parcial), em vez de apagar pago_por/fonte_pagamento/socio não reenviados."""
    d = request.json or {}
    conn = db()
    atual = conn.execute("SELECT * FROM lancamentos WHERE id=?", (lid,)).fetchone()
    if not atual:
        close_db(conn); return jsonify({"ok": False, "msg": "Lançamento não encontrado"}), 404

    def campo(chave, default=''):
        return d[chave] if chave in d else (atual[chave] if chave in atual.keys() else default)

    valor_raw = campo('valor', atual['valor'])
    valor = float(str(valor_raw).replace('.', '').replace(',', '.')) if isinstance(valor_raw, str) and ',' in str(valor_raw) else float(valor_raw or 0)
    data_emissao = (campo('data_emissao') or '').strip()
    competencia = data_emissao[:7] if len(data_emissao) >= 7 else (campo('data_competencia') or atual['data_competencia'])

    meio_raw = campo('meio_pagamento_id', atual['meio_pagamento_id'])
    try:
        meio_pagamento_id = int(meio_raw) if meio_raw else None
    except (TypeError, ValueError):
        meio_pagamento_id = None
    forma_pagamento = (campo('forma_pagamento') or '').strip()
    if meio_pagamento_id:
        meio = conn.execute("SELECT tipo FROM meios_pagamento WHERE id=?", (meio_pagamento_id,)).fetchone()
        if meio:
            forma_pagamento = meio['tipo']
        else:
            meio_pagamento_id = None

    conn.execute("""UPDATE lancamentos SET descricao=?, categoria=?, valor=?, data_emissao=?, data_vencimento=?,
        data_competencia=?, socio=?, pago_por=?, fonte_pagamento=?, forma_pagamento=?, meio_pagamento_id=?
        WHERE id=?""",
        (campo('descricao'), campo('categoria'), valor, data_emissao or None, (campo('data_vencimento') or '').strip() or None,
         competencia, campo('socio'), (campo('pago_por') or '').strip(), (campo('fonte_pagamento') or '').strip(),
         forma_pagamento, meio_pagamento_id, lid))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True})


