def _carregar_tabela_publicada(arquivo=None):
    """Lê o JSON versionado da tabela da administradora. Nunca levanta erro."""
    try:
        with open(arquivo or _TABELA_ARQ, encoding='utf-8') as fh:
            return json.load(fh)
    except Exception as e:
        app.logger.warning(f"[TABELA] nao consegui ler {arquivo or _TABELA_ARQ}: {e}")
        return []


def _regua_para_fracoes(regua_dict):
    """{'1':100,'2':100,'3':40} -> [{'ordem':1,'percentual':100,'mes':1}, ...]

    Mesmo formato de gestor_regra.fracoes_json de propósito: a régua de
    recebimento é uma coisa só no sistema, não uma por tela."""
    fracoes = []
    for i, chave in enumerate(sorted(regua_dict or {}, key=lambda k: int(k)), start=1):
        mes = int(chave)
        fracoes.append({'ordem': i, 'percentual': float(regua_dict[chave]), 'mes': mes})
    return fracoes


@app.route('/admin/tabela-operadora/importar', methods=['POST'])
@login_required
@admin_required
def tabela_operadora_importar():
    """Carrega a tabela publicada para dentro do banco. Idempotente (UPSERT).

    NÃO toca em `recebimento`: importar a tabela da administradora não pode
    mudar sozinho o que a corretora cobra. A aplicação é um passo humano,
    feito na tela de conciliação, linha a linha."""
    dados = _carregar_tabela_publicada()
    if not dados:
        return jsonify({'ok': False, 'erro': 'Arquivo da tabela não encontrado ou vazio'}), 400
    vig = (request.json or {}).get('vigencia') or _TABELA_VIGENCIA
    conn = db()
    # Cria a estrutura se ela não veio do init_db — assim o botão resolve
    # sozinho em vez de exigir um deploy só para destravar.
    ddl_pg = DB_MODE == 'postgres'
    for ddl in (
        f"""CREATE TABLE IF NOT EXISTS tabela_operadora (
                id {'SERIAL PRIMARY KEY' if ddl_pg else 'INTEGER PRIMARY KEY AUTOINCREMENT'},
                fonte TEXT DEFAULT 'affinity', vigencia TEXT NOT NULL, plano TEXT NOT NULL,
                empresa TEXT NOT NULL, sub TEXT DEFAULT '', faixa TEXT DEFAULT '',
                tipo TEXT DEFAULT 'perc', total REAL, regua_json TEXT DEFAULT '',
                obs TEXT DEFAULT '',
                UNIQUE(fonte, vigencia, plano, empresa, sub, faixa))""",
        f"""CREATE TABLE IF NOT EXISTS recebimento_backup (
                id {'SERIAL PRIMARY KEY' if ddl_pg else 'INTEGER PRIMARY KEY AUTOINCREMENT'},
                lote TEXT NOT NULL, recebimento_id INTEGER NOT NULL,
                total REAL, promo_total REAL, promo_parcela INTEGER,
                regua_json TEXT, fonte_tabela TEXT, criado_por TEXT,
                criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP)""",
    ):
        try:
            conn.execute(ddl); conn.commit()
        except Exception as e:
            try: conn.rollback()
            except Exception: pass
            app.logger.warning(f"[TABELA] DDL sob demanda falhou: {e}")
    gravados = 0
    for r in dados:
        try:
            conn.execute("""INSERT INTO tabela_operadora
                    (fonte,vigencia,plano,empresa,sub,faixa,tipo,total,regua_json,obs)
                    VALUES ('affinity',?,?,?,?,?,?,?,?,?)
                ON CONFLICT(fonte,vigencia,plano,empresa,sub,faixa) DO UPDATE SET
                    tipo=excluded.tipo, total=excluded.total,
                    regua_json=excluded.regua_json, obs=excluded.obs""",
                (vig, r.get('plano'), r.get('empresa'), r.get('sub') or '', r.get('faixa') or '',
                 r.get('tipo') or 'perc', r.get('total'),
                 json.dumps(_regua_para_fracoes(r.get('regua')), ensure_ascii=False),
                 r.get('obs') or ''))
            gravados += 1
        except Exception as e:
            app.logger.warning(f"[TABELA] linha ignorada {r.get('empresa')}/{r.get('plano')}: {e}")
    conn.commit(); close_db(conn)
    app.logger.info(f"[TABELA] vigencia {vig}: {gravados} linhas gravadas")
    return jsonify({'ok': True, 'gravados': gravados, 'vigencia': vig})


@app.route('/proposta/<int:pid>/excluir', methods=['POST'])
@login_required
@admin_required
def excluir_proposta_logica(pid):
    """Soft Delete: marca proposta como Excluída, cancela parcelas e registra motivo + detalhe."""
    d = request.json or {}
    motivo = (d.get('motivo_exclusao') or 'Outro').strip()
    detalhe = (d.get('detalhe_exclusao') or '').strip()
    nome_user = session.get('nome', 'admin')

    conn = db()
    p = conn.execute("SELECT * FROM propostas WHERE id=?", (pid,)).fetchone()
    if not p:
        close_db(conn)
        return jsonify({"ok": False, "msg": "Proposta não encontrada"}), 404

    # Atualizar status da proposta (exclusão lógica)
    conn.execute("""
        UPDATE propostas
        SET status='Excluída', motivo_exclusao=?, detalhe_exclusao=?
        WHERE id=?
    """, (motivo, detalhe, pid))

    # Estornar/cancelar todas as parcelas pendentes de receber
    conn.execute("""
        UPDATE parcelas
        SET status='Cancelada / Estornada'
        WHERE proposta_id=? AND status='Pendente de receber'
    """, (pid,))

    # Registrar no histórico
    desc = f"Proposta excluída. Motivo: {motivo}" + (f" — {detalhe}" if detalhe else "")
    conn.execute("""
        INSERT INTO historico_proposta (proposta_id, usuario_id, usuario_nome, tipo, descricao, criado_em)
        VALUES (?, ?, ?, 'exclusao', ?, ?)
    """, (pid, session['user_id'], nome_user, desc, datetime.now(TZ_SP)))

    conn.commit()
    close_db(conn)
    return jsonify({"ok": True, "msg": "Proposta excluída. Parcelas pendentes canceladas/estornadas."})

@app.route('/admin/propostas-excluidas')
@login_required
@admin_required
def propostas_excluidas():
    """Dashboard de propostas excluídas para auditoria."""
    conn = db()
    
    # Métricas
    total_excluidas = conn.execute("SELECT COUNT(*) c FROM propostas WHERE status='Excluída'").fetchone()['c']
    valor_excluido = conn.execute("SELECT COALESCE(SUM(valor),0) v FROM propostas WHERE status='Excluída'").fetchone()['v']
    com_bruta_excluida = conn.execute("SELECT COALESCE(SUM(comissao_total_corretora),0) v FROM propostas WHERE status='Excluída'").fetchone()['v']
    
    # Motivos mais frequentes
    motivos = conn.execute("""
        SELECT motivo_exclusao, COUNT(*) qtd
        FROM propostas 
        WHERE status='Excluída' AND motivo_exclusao IS NOT NULL
        GROUP BY motivo_exclusao
        ORDER BY qtd DESC
    """).fetchall()
    
    # Lista completa
    excluidas = conn.execute("""
        SELECT id, razao_social, consultor, valor, motivo_exclusao, quem_subiu
        FROM propostas 
        WHERE status='Excluída'
        ORDER BY id DESC
    """).fetchall()
    
    close_db(conn)
    return render_template('propostas_excluidas.html', 
                          total=total_excluidas, 
                          valor=valor_excluido,
                          com_bruta=com_bruta_excluida,
                          motivos=motivos,
                          excluidas=excluidas)

@app.route('/admin/recovery-anexos')
@login_required
@admin_required
def recovery_anexos():
    """Página para reenviar anexos perdidos, organizado por proposta."""
    conn = db()
    rows = conn.execute("""
        SELECT id, razao_social, comprovante_boleto, contrato_arquivo, anexos
        FROM propostas
        WHERE status != 'Excluído'
        AND (comprovante_boleto IS NOT NULL
             OR contrato_arquivo IS NOT NULL
             OR (anexos IS NOT NULL AND anexos != '[]'))
        ORDER BY id
    """).fetchall()
    close_db(conn)

    propostas_faltando = []
    for r in rows:
        pid        = r['id'] if hasattr(r,'keys') else r[0]
        razao      = r['razao_social'] if hasattr(r,'keys') else r[1]
        comp       = r['comprovante_boleto'] if hasattr(r,'keys') else r[2]
        cont       = r['contrato_arquivo']   if hasattr(r,'keys') else r[3]
        anexos_raw = r['anexos'] if hasattr(r,'keys') else r[4]

        faltando = []
        for campo, nome in [('comprovante_boleto', comp), ('contrato_arquivo', cont)]:
            if nome:
                basename = os.path.basename(nome)
                if not os.path.exists(os.path.join(UPLOAD_FOLDER, basename)):
                    faltando.append({'campo': campo, 'nome': basename})

        try:
            extras = json.loads(anexos_raw or '[]')
            for a in extras:
                basename = os.path.basename(a)
                if not os.path.exists(os.path.join(UPLOAD_FOLDER, basename)):
                    faltando.append({'campo': 'anexo_extra', 'nome': basename})
        except: pass

        if faltando:
            propostas_faltando.append({
                'id': pid,
                'razao_social': razao,
                'faltando': faltando
            })

    return render_template('recovery_anexos.html',
        propostas=propostas_faltando,
        total_faltando=sum(len(p['faltando']) for p in propostas_faltando)
    )


