def _doc_preparar_imagem(b64, mime='image/jpeg'):
    """Reduz pra 1568px no maior lado e corrige rotacao do celular.

    Acima de 1568 o modelo de visao nao ganha precisao — so custa mais. E foto de
    celular vem com a rotacao no METADADO, nao no pixel: sem corrigir, metade dos
    RGs chega deitado e a leitura piora sem motivo."""
    try:
        from PIL import Image, ImageOps
        import io as _io, base64 as _b64
        img = Image.open(_io.BytesIO(_b64.b64decode(b64)))
        img = ImageOps.exif_transpose(img)
        if img.mode not in ('RGB', 'L'):
            img = img.convert('RGB')
        maior = max(img.size)
        if maior > 1568:
            f = 1568 / maior
            img = img.resize((int(img.width * f), int(img.height * f)), Image.LANCZOS)
        buf = _io.BytesIO()
        img.save(buf, format='JPEG', quality=85, optimize=True)
        return _b64.b64encode(buf.getvalue()).decode('ascii'), 'image/jpeg'
    except Exception as e:
        app.logger.info(f"[DOC] não preparei a imagem ({e}) — mando como veio")
        return b64, (mime or 'image/jpeg')


def ler_documentos_cliente(arquivos, teto_imagens=24):
    """Le documentos e devolve dado estruturado. Uma chamada, duas tarefas.

    `arquivos`: [{'nome','base64','mime','tipo'('imagem'|'documento')}]

    Distribuicao em RODADAS: pega a 1a pagina de cada arquivo, depois a 2a de
    cada. Sem isso, um contrato social de 10 paginas no inicio da fila comeria o
    teto inteiro e os documentos do fim ficariam invisiveis pro modelo.
    """
    if not arquivos:
        return None, 'nenhum arquivo'
    api_key = (os.environ.get('ANTHROPIC_API_KEY') or '').strip()
    if not api_key:
        return None, 'ANTHROPIC_API_KEY não configurada'
    try:
        import anthropic
    except Exception as e:
        return None, f'pacote anthropic ausente: {e}'

    # 1) prepara: cada arquivo vira uma lista de paginas (imagens) ou texto puro
    preparados, textos = [], []
    for i, a in enumerate(arquivos, start=1):
        nome = (a.get('nome') or f'arquivo {i}')[:120]
        b64 = (a.get('base64') or '').strip()
        if not b64:
            continue
        if (a.get('tipo') or '') == 'documento':
            texto, paginas = _pdf_extrair_conteudo(b64, max_paginas=2, minimo_texto=400)
            # CAMADA DE TEXTO CURTA NAO E LEITURA. Uma CNH-e tem camada de texto,
            # mas ela e quase so metadado e QR — o modelo lia aquilo, nao via a
            # carteira, e classificava como 'outro'. Contrato ou conta de luz de
            # verdade tem muito texto. Abaixo de 400 caracteres, olha a IMAGEM da
            # pagina, que e onde o documento realmente esta.
            if texto and len(texto.strip()) >= 400:
                textos.append((i, nome, texto[:6000]))
                preparados.append((i, nome, []))
                continue
            if paginas:
                preparados.append((i, nome, [(p, 'image/jpeg') for p in (paginas or [])[:2]]))
                if texto and texto.strip():
                    textos.append((i, nome, texto[:1500]))
            else:
                preparados.append((i, nome, []))
                if texto:
                    textos.append((i, nome, texto[:6000]))
        else:
            preparados.append((i, nome, [_doc_preparar_imagem(b64, a.get('mime'))]))

    # 2) rodadas: 1a pagina de cada, depois 2a de cada, ate o teto
    conteudo, usados, rodada, sobraram = [], 0, 0, False
    while usados < teto_imagens:
        entrou = False
        for (i, nome, paginas) in preparados:
            if rodada >= len(paginas):
                continue
            if usados >= teto_imagens:
                sobraram = True
                break
            conteudo.append({'type': 'text', 'text': f'ARQUIVO {i}: {nome}'})
            b, m = paginas[rodada]
            conteudo.append({'type': 'image', 'source': {'type': 'base64', 'media_type': m, 'data': b}})
            usados += 1
            entrou = True
        if not entrou:
            break
        rodada += 1
    for (i, nome, texto) in textos:
        conteudo.append({'type': 'text', 'text': f'ARQUIVO {i}: {nome}\n{texto}'})
    if not conteudo:
        return None, 'nenhuma página legível'
    conteudo.append({'type': 'text', 'text':
        'Classifique cada ARQUIVO e extraia os dados das pessoas. Use a ferramenta.'})

    ferramenta = {'name': 'registrar_documentos',
                  'description': 'Classificação dos arquivos e dados extraídos',
                  'input_schema': _DOC_SCHEMA}
    # ESFORCO BAIXO DE PROPOSITO. Classificar documento e tarefa de VER, nao de
    # raciocinar: o modelo olha o papel, diz o que e e copia os dados. Sem este
    # parametro o Sonnet 5 entra no esforco 'high' por padrao e fica pensando em
    # toda leitura — era o consultor esperando na frente do cliente enquanto o
    # modelo deliberava sobre uma certidao de nascimento.
    kw = dict(model=_CLAUDE_MODEL_DESCREVER, max_tokens=3000, system=_DOC_SISTEMA,
              tools=[ferramenta], tool_choice={'type': 'tool', 'name': 'registrar_documentos'},
              messages=[{'role': 'user', 'content': conteudo}])
    try:
        client = anthropic.Anthropic(api_key=api_key, timeout=180.0, max_retries=1)
        t0 = time.perf_counter()
        try:
            resp = client.messages.create(output_config={'effort': 'medium'}, **kw)
        except TypeError:
            # SDK antigo nao conhece output_config. Ler o documento importa mais
            # que ler rapido — cai pro jeito antigo em vez de falhar.
            resp = client.messages.create(**kw)
        ms = (time.perf_counter() - t0) * 1000
        ti_log = getattr(resp.usage, 'input_tokens', 0) or 0
        to_log = getattr(resp.usage, 'output_tokens', 0) or 0
        # MEDIDO, nao estimado: sem isto "demorou muito" e indistinguivel de
        # rede lenta, download lento ou modelo lento.
        app.logger.info(f"[DOC] modelo {_CLAUDE_MODEL_DESCREVER} {ms:.0f} ms "
                        f"in={ti_log} out={to_log} paginas={usados} "
                        f"arquivos={len(arquivos)} stop={getattr(resp, 'stop_reason', None)}")
        bloco = next((b for b in resp.content if b.type == 'tool_use'), None)
        if not bloco:
            if getattr(resp, 'stop_reason', '') == 'max_tokens':
                return None, 'a leitura estourou o limite de tokens — avise o suporte'
            return None, 'o modelo não devolveu estrutura'
        out = dict(bloco.input or {})
    except Exception as e:
        app.logger.warning(f"[DOC] leitura falhou: {e}")
        return None, str(e)[:200]

    ti = getattr(resp.usage, 'input_tokens', 0) or 0
    to = getattr(resp.usage, 'output_tokens', 0) or 0
    pi, po = _precos_modelo(_CLAUDE_MODEL_DESCREVER)
    out['custo_usd'] = round(ti * pi / 1e6 + to * po / 1e6, 6)

    # 3) limpeza: nunca aceitar a resposta crua
    validos, vistos = [], set()
    for a in (out.get('arquivos') or []):
        try:
            idx = int(a.get('indice') or 0)
        except (TypeError, ValueError):
            continue
        if idx < 1 or idx > len(arquivos) or idx in vistos:
            continue
        vistos.add(idx)
        # Tipo fora da lista virava 'outro' calado, e depois ninguem sabia se o
        # modelo tinha errado ou so chutado um nome parecido com o certo.
        tipo_bruto = (a.get('tipo') or '').strip()
        if tipo_bruto and tipo_bruto not in _DOC_TIPOS:
            app.logger.warning(f"[DOC] tipo fora da lista: {tipo_bruto!r} para "
                               f"{arquivos[idx - 1].get('nome')!r} — virou 'outro'")
        validos.append({'indice': idx, 'nome': arquivos[idx - 1].get('nome') or '',
                        'tipo': tipo_bruto if tipo_bruto in _DOC_TIPOS else 'outro',
                        'pessoa': (a.get('pessoa') or '').strip(),
                        'certeza': a.get('certeza') if a.get('certeza') in ('alta', 'media', 'baixa') else 'baixa'})
    # Arquivo que o modelo nao classificou NAO some da tela: entra como 'outro'
    # com certeza baixa, pra alguem resolver na mao. Sumir em silencio e pior.
    for i, a in enumerate(arquivos, start=1):
        if i not in vistos:
            validos.append({'indice': i, 'nome': a.get('nome') or '', 'tipo': 'outro',
                            'pessoa': '', 'certeza': 'baixa'})
    out['arquivos'] = sorted(validos, key=lambda x: x['indice'])
    obs = list(out.get('observacoes') or [])
    if sobraram:
        obs.append(f'Só couberam {usados} páginas nesta leitura — o resto ficou de fora.')
    out['observacoes'] = obs
    return out, None




# O QUE A OPERADORA ESPERA DE CADA PESSOA.
#
# E isto que transforma inventario em conferencia: sem uma lista do que DEVERIA
# chegar, "faltando" nao existe como estado — a tela so consegue dizer o que ja
# chegou, e o consultor descobre o que falta na recusa da operadora.
#
# Cada vaga aceita mais de um tipo de proposito. Filho pequeno nao tem RG, tem
# certidao de nascimento; exigir os dois criaria pendencia falsa, e checklist que
# grita lobo para de ser lido na terceira vez.
_DOC_SLOTS_PADRAO = [
    {'k': 'foto', 'rotulo': 'Documento com foto (RG ou CNH)', 'tipos': ['identidade']},
]
_DOC_SLOTS = {
    'titular': [
        {'k': 'foto', 'rotulo': 'Documento com foto (RG ou CNH)', 'tipos': ['identidade']},
        {'k': 'end',  'rotulo': 'Comprovante de endereço', 'tipos': ['comprovante_endereco']},
    ],
    'conjuge': [
        {'k': 'foto', 'rotulo': 'Documento com foto (RG ou CNH)', 'tipos': ['identidade']},
        {'k': 'vinc', 'rotulo': 'Certidão de casamento', 'tipos': ['certidao_casamento']},
    ],
    'companheiro': [
        {'k': 'foto', 'rotulo': 'Documento com foto (RG ou CNH)', 'tipos': ['identidade']},
        {'k': 'vinc', 'rotulo': 'Declaração de união estável', 'tipos': ['declaracao_uniao_estavel']},
    ],
    'filho': [
        {'k': 'doc', 'rotulo': 'Documento com foto ou certidão de nascimento',
         'tipos': ['identidade', 'certidao_nascimento']},
    ],
    'enteado': [
        {'k': 'doc', 'rotulo': 'Documento com foto ou certidão de nascimento',
         'tipos': ['identidade', 'certidao_nascimento']},
        {'k': 'vinc', 'rotulo': 'Vínculo com o cônjuge (casamento ou união estável)',
         'tipos': ['certidao_casamento', 'declaracao_uniao_estavel']},
    ],
    'neto': [
        {'k': 'doc', 'rotulo': 'Documento com foto ou certidão de nascimento',
         'tipos': ['identidade', 'certidao_nascimento']},
    ],
}
# Empresa so entra quando a venda E empresarial. Cobrar cartao CNPJ num plano
# individual marcaria pendencia que nunca vai ser resolvida.
_DOC_SLOTS_EMPRESA = [
    {'k': 'cnpj', 'rotulo': 'Cartão CNPJ', 'tipos': ['cartao_cnpj']},
    {'k': 'social', 'rotulo': 'Contrato social ou requerimento de empresário',
     'tipos': ['contrato_social']},
]


def _doc_fichas(documentos, empresarial=False):
    """Monta uma ficha por PESSOA, com o que chegou e o que falta.

    Agrupa por (nome, parentesco) e nao so por parentesco: dois filhos sao duas
    pessoas, e juntar os dois numa ficha so faria a certidao de um cobrir a
    falta do outro."""
    pendentes = [d for d in documentos if not d.get('titularidade')]
    fichas, ordem = {}, []
    for d in documentos:
        if not d.get('titularidade'):
            continue
        pap = 'titular' if d['titularidade'] == 'titular' else (d.get('parentesco') or '')
        chave = ((d.get('pessoa') or '').strip().lower(), pap)
        if chave not in fichas:
            fichas[chave] = {'pessoa': d.get('pessoa') or '', 'papel': pap,
                             'titularidade': d['titularidade'], 'itens': []}
            ordem.append(chave)
        fichas[chave]['itens'].append(d)

    saida = []
    for chave in ordem:
        f = fichas[chave]
        slots = list(_DOC_SLOTS.get(f['papel'], _DOC_SLOTS_PADRAO))
        if f['titularidade'] == 'titular' and empresarial:
            slots = slots + _DOC_SLOTS_EMPRESA
        usados, linhas, faltam, conferir = set(), [], 0, 0
        for s in slots:
            achado = next((d for d in f['itens']
                           if d.get('tipo') in s['tipos'] and id(d) not in usados), None)
            if achado is not None:
                usados.add(id(achado))
                if not achado.get('conferido'):
                    conferir += 1
            else:
                faltam += 1
            linhas.append({'rotulo': s['rotulo'], 'doc': achado})
        # Papel que chegou alem do esperado nao some: entra como extra.
        extras = [d for d in f['itens'] if id(d) not in usados]
        for d in extras:
            if not d.get('conferido'):
                conferir += 1
        if f['papel'] == 'titular':
            titulo = 'Titular'
        elif f['papel']:
            titulo = _DOC_PARENTESCO_ROTULO.get(f['papel'], 'Dependente')
        else:
            titulo = 'Dependente'
        # TRES estados, nao dois. "Tudo chegou" e diferente de "alguem conferiu":
        # verde facil demais e verde que ninguem acredita.
        if faltam:
            estado, estado_txt = 'falta', f'Falta {faltam} documento' + ('s' if faltam > 1 else '')
        elif conferir:
            estado, estado_txt = 'conferir', f'Falta conferir {conferir}'
        else:
            estado, estado_txt = 'pronta', 'Conferida'
        saida.append({
            'pessoa': f['pessoa'], 'papel': f['papel'], 'titulo': titulo,
            'titularidade': f['titularidade'], 'linhas': linhas, 'extras': extras,
            'estado': estado, 'estado_txt': estado_txt,
            'faltam': faltam, 'conferir': conferir,
            'comprova': _DOC_PARENTESCO_COMPROVA.get(f['papel']),
        })
    saida.sort(key=lambda x: (x['titularidade'] != 'titular', x['estado'] == 'pronta'))
    return saida, pendentes


def _extracao_guardar(conn, lead_id, leitura):
    """Guarda o que foi lido dos documentos, ACUMULANDO entre leituras.

    O cliente manda o RG hoje e o comprovante amanha. Se cada leitura
    sobrescrevesse a anterior, o bloco pra operadora nunca ficaria completo.
    Entao: pessoa nova entra, pessoa que ja existe recebe so os campos que
    estavam VAZIOS. Documento nao corrige o que ja estava preenchido — ele
    completa."""
    if not (lead_id and leitura):
        return
    r = conn.execute("SELECT * FROM lead_extracao WHERE lead_id=?", (lead_id,)).fetchone()
    def _j(v, padrao):
        try:
            return json.loads(v) if v else padrao
        except Exception:
            return padrao
    pessoas = _j(r['pessoas_json'], []) if r else []
    empresa = _j(r['empresa_json'], {}) if r else {}
    endereco = _j(r['endereco_json'], {}) if r else {}
    contato = _j(r['contato_json'], {}) if r else {}

    for nova in (leitura.get('pessoas') or []):
        if not (nova.get('nome') or '').strip():
            continue
        alvo = next((p for p in pessoas if doc_mesma_pessoa(p.get('nome'), nova.get('nome'))), None)
        if alvo is None:
            pessoas.append({k: v for k, v in nova.items() if v})
            continue
        for k, v in nova.items():
            if v and not alvo.get(k):
                alvo[k] = v
    for origem, destino in ((leitura.get('empresa') or {}, empresa),
                            (leitura.get('endereco') or {}, endereco),
                            (leitura.get('contato') or {}, contato)):
        for k, v in origem.items():
            if v and not destino.get(k):
                destino[k] = v

    dados = (json.dumps(pessoas, ensure_ascii=False), json.dumps(empresa, ensure_ascii=False),
             json.dumps(endereco, ensure_ascii=False), json.dumps(contato, ensure_ascii=False),
             _agora_sp(), lead_id)
    if r:
        conn.execute("""UPDATE lead_extracao SET pessoas_json=?, empresa_json=?, endereco_json=?,
                        contato_json=?, atualizado_em=? WHERE lead_id=?""", dados)
    else:
        conn.execute("""INSERT INTO lead_extracao (pessoas_json, empresa_json, endereco_json,
                        contato_json, atualizado_em, lead_id) VALUES (?,?,?,?,?,?)""", dados)


def _extracao_ler(conn, lead_id):
    r = conn.execute("SELECT * FROM lead_extracao WHERE lead_id=?", (lead_id,)).fetchone()
    if not r:
        return {'pessoas': [], 'empresa': {}, 'endereco': {}, 'contato': {}}
    def _j(v, padrao):
        try:
            return json.loads(v) if v else padrao
        except Exception:
            return padrao
    return {'pessoas': _j(r['pessoas_json'], []), 'empresa': _j(r['empresa_json'], {}),
            'endereco': _j(r['endereco_json'], {}), 'contato': _j(r['contato_json'], {}),
            'atualizado_em': r['atualizado_em']}



def _extracao_resgatar(conn, lead_id):
    """Reconstitui o extraido de leads ANTERIORES a esta tabela.

    O bloco pra colar na operadora so aparecia quando lead_extracao tinha
    linha — e ela nasceu hoje. Para todo lead antigo a secao sumia da tela sem
    dizer por que, e a impressao certa era "o sistema nao faz isso". Faz: o dado
    estava espalhado na analise da conversa, nos campos do lead e nos documentos.
    Isto junta e grava uma vez."""
    if _extracao_ler(conn, lead_id).get('pessoas'):
        return
    pessoas, empresa, endereco, contato = [], {}, {}, {}
    # 1) o que a analise da conversa ja tinha extraido dos documentos
    try:
        r = conn.execute("""SELECT sugestoes_json FROM whatsapp_analises WHERE lead_id=?
                            ORDER BY id DESC LIMIT 1""", (lead_id,)).fetchone()
        diag = json.loads((r['sugestoes_json'] if r else '') or '{}')
        ia = diag.get('ia') or {}
        for p in (ia.get('documentos_pessoas') or []):
            if (p.get('nome') or '').strip():
                pessoas.append({k: v for k, v in p.items() if v})
        empresa = {k: v for k, v in (ia.get('dados_empresa') or {}).items() if v}
    except Exception:
        pass
    # 2) os nomes que os proprios documentos deram, quando a analise nao tinha
    try:
        for r in conn.execute("""SELECT DISTINCT pessoa FROM lead_documento
                                 WHERE lead_id=? AND pessoa IS NOT NULL AND pessoa<>''""",
                              (lead_id,)).fetchall():
            if not any(doc_mesma_pessoa(p.get('nome'), r['pessoa']) for p in pessoas):
                pessoas.append({'nome': r['pessoa']})
    except Exception:
        pass
    # 3) a ficha do lead: telefone, e o que o consultor ja preencheu a mao
    try:
        lead = conn.execute("SELECT nome, telefone FROM crm_leads WHERE id=?", (lead_id,)).fetchone()
        if lead:
            if lead['telefone']:
                contato['telefone'] = lead['telefone']
            if (lead['nome'] or '').strip() and not any(
                    doc_mesma_pessoa(p.get('nome'), lead['nome']) for p in pessoas):
                pessoas.insert(0, {'nome': lead['nome']})
        for r in conn.execute("""SELECT c.nome_tecnico, v.valor FROM crm_lead_campos v
                                 JOIN campos_custom c ON c.id=v.campo_id WHERE v.lead_id=?""",
                              (lead_id,)).fetchall():
            k, v = (r['nome_tecnico'] or ''), (r['valor'] or '')
            if not v:
                continue
            if 'cnpj' in k and not empresa.get('cnpj'):
                empresa['cnpj'] = v
            elif 'razao' in k and not empresa.get('razao_social'):
                empresa['razao_social'] = v
            elif 'cidade' in k and not endereco.get('cidade'):
                endereco['cidade'] = v
            elif 'email' in k and not contato.get('email'):
                contato['email'] = v
            elif 'cpf' in k and pessoas and not pessoas[0].get('cpf'):
                pessoas[0]['cpf'] = v
            elif ('nasc' in k) and pessoas and not pessoas[0].get('nascimento'):
                pessoas[0]['nascimento'] = v
    except Exception as e:
        app.logger.info(f"[EXTRACAO] resgate campos: {e}")
    if not (pessoas or empresa or endereco or contato):
        return
    _extracao_guardar(conn, lead_id, {'pessoas': pessoas, 'empresa': empresa,
                                      'endereco': endereco, 'contato': contato})
    try:
        conn.commit()
    except Exception:
        pass


def _doc_data_br(v):
    """AAAA-MM-DD -> DD/MM/AAAA. Aceita o que ja vier em BR."""
    s = str(v or '').strip()
    m = re.match(r'^(\d{4})-(\d{1,2})-(\d{1,2})', s)
    if m:
        return f"{int(m.group(3)):02d}/{int(m.group(2)):02d}/{m.group(1)}"
    m = re.match(r'^(\d{1,2})/(\d{1,2})/(\d{4})', s)
    if m:
        return f"{int(m.group(1)):02d}/{int(m.group(2)):02d}/{m.group(3)}"
    return ''


def _doc_cpf_br(v):
    d = re.sub(r'\D', '', str(v or ''))
    return f"{d[:3]}.{d[3:6]}.{d[6:9]}-{d[9:11]}" if len(d) == 11 else (str(v or '').strip())


def _doc_cnpj_br(v):
    d = re.sub(r'\D', '', str(v or ''))
    return f"{d[:2]}.{d[2:5]}.{d[5:8]}/{d[8:12]}-{d[12:14]}" if len(d) == 14 else (str(v or '').strip())


def _doc_cep_br(v):
    d = re.sub(r'\D', '', str(v or ''))
    return f"{d[:5]}-{d[5:8]}" if len(d) == 8 else (str(v or '').strip())


def _doc_fone_br(v):
    d = re.sub(r'\D', '', str(v or ''))
    if d.startswith('55') and len(d) > 11:
        d = d[2:]
    if len(d) == 11:
        return f"({d[:2]}) {d[2:7]}-{d[7:]}"
    if len(d) == 10:
        return f"({d[:2]}) {d[2:6]}-{d[6:]}"
    return str(v or '').strip()


def docs_texto_bloco(conn, lead_id):
    """O bloco de texto puro que se cola no sistema da operadora.

    Formato ditado pelo Guilherme, e a ordem das linhas IMPORTA — e a ordem em
    que os campos aparecem na ficha da operadora. Campo que nao existe some: a
    linha inteira sai, nunca vira "nao informado", porque "nao informado" ocupa
    o lugar do dado e obriga a conferir de novo.
    Tudo em MAIUSCULAS menos o e-mail."""
    e = _extracao_ler(conn, lead_id)
    blocos = []
    for p in (e.get('pessoas') or []):
        L = []
        nome = (p.get('nome') or '').strip()
        if not nome:
            continue
        L.append(nome.upper())
        cpf = _doc_cpf_br(p.get('cpf'))
        if cpf:
            L.append(cpf)
        rg = (p.get('rg') or '').strip()
        if rg:
            L.append(' '.join(x for x in [rg, (p.get('rg_emissor') or '').strip()] if x).upper())
        nasc = _doc_data_br(p.get('nascimento'))
        if nasc:
            L.append(nasc)
        # O pai vem antes da mae. Se so um existir, sai um so — a linha que falta
        # simplesmente nao aparece.
        if (p.get('pai') or '').strip():
            L.append(p['pai'].strip().upper())
        if (p.get('mae') or '').strip():
            L.append(p['mae'].strip().upper())
        cns = re.sub(r'\D', '', str(p.get('cns') or ''))
        if cns:
            L.append('CNES: ' + cns)
        # Naturalidade e emissao entram DEPOIS do CNES, nao no meio: o formato
        # que o Guilherme ditou fixa a 2a linha como CPF e a 4a como nascimento,
        # e enfiar campo novo la no meio quebraria quem ja usa o bloco.
        nat = ' - '.join(x for x in [(p.get('natural_cidade') or '').strip().upper(),
                                     (p.get('natural_uf') or '').strip().upper()] if x)
        if nat:
            # 'NATURAL:' e nao 'NATURAL DE:' — e o rotulo que o formulario de
            # proposta ja sabe ler. Emitir um e esperar outro quebraria o unico
            # caminho automatico entre as duas telas.
            L.append('NATURAL: ' + nat)
        emi = _doc_data_br(p.get('emissao'))
        if emi:
            L.append('EMISSAO: ' + emi)
        blocos.append('\n'.join(L))

    end = e.get('endereco') or {}
    L = []
    if (end.get('logradouro') or '').strip():
        L.append(end['logradouro'].strip().upper())
    if str(end.get('numero') or '').strip():
        L.append(str(end['numero']).strip().upper())
    if (end.get('bairro') or '').strip():
        L.append(end['bairro'].strip().upper())
    if (end.get('cidade') or '').strip():
        L.append(end['cidade'].strip().upper())
    cep = _doc_cep_br(end.get('cep'))
    if cep:
        L.append('CEP: ' + cep)
    if L:
        blocos.append('\n'.join(L))

    emp = e.get('empresa') or {}
    L = []
    cnpj = _doc_cnpj_br(emp.get('cnpj'))
    if cnpj:
        L.append('CNPJ: ' + cnpj)
    if (emp.get('razao_social') or '').strip():
        L.append(emp['razao_social'].strip().upper())
    if L:
        blocos.append('\n'.join(L))

    con = e.get('contato') or {}
    L = []
    fone = _doc_fone_br(con.get('telefone'))
    if fone:
        L.append(fone)
    if (con.get('email') or '').strip():
        L.append(con['email'].strip())        # e-mail e a UNICA coisa que nao vira maiuscula
    if L:
        blocos.append('\n'.join(L))

    return '\n\n'.join(blocos)


def _doc_propor_titularidade(conn, lead_id, nome_no_documento):
    """Propoe se o documento e do titular ou de um dependente.

    Quem decide e o CODIGO comparando com o cadastro, nao a IA — ela nao sabe
    quem e titular nesta venda. E e so uma PROPOSTA: o consultor confirma, porque
    e ele que responde pela ficha na operadora.

    Sem nome legivel no documento nao ha o que propor: fica vazio pra pessoa
    dizer, em vez de chutar 'titular' e o consultor aceitar sem olhar."""
    if not (lead_id and nome_no_documento):
        return None, None
    lead = conn.execute("SELECT nome FROM crm_leads WHERE id=?", (lead_id,)).fetchone()
    if lead and doc_mesma_pessoa(nome_no_documento, lead['nome']):
        return 'titular', None
    # Nome diferente do titular: e dependente, mas QUAL parentesco so o consultor
    # sabe — sobrenome igual pode ser filho, irmao ou pai.
    return 'dependente', None


def documentos_para_o_lead(conn, lead_id, leitura, arquivos):
    """Guarda o que foi lido e preenche o lead. AQUI e onde o codigo decide.

    A IA disse "este arquivo e uma identidade da Maria" e "a Maria tem CPF X".
    Quem casa a Maria com o titular do cadastro, e qual campo recebe o quê, e
    esta funcao — deterministica, auditavel, sem criatividade.

    so_se_vazio em tudo: documento confirma o que ja se sabia, nao corrige o
    consultor. E fonte='ia' deixa rastreavel quem escreveu cada valor."""
    if not (lead_id and leitura):
        return {'gravados': 0, 'campos': []}
    import hashlib as _h
    agora = _agora_sp()
    por_indice = {a['indice']: a for a in (leitura.get('arquivos') or [])}
    gravados = 0
    for i, arq in enumerate(arquivos, start=1):
        b64 = (arq.get('base64') or '')
        if not b64:
            continue
        h = _h.sha256(b64.encode('ascii', 'ignore')).hexdigest()
        cls = por_indice.get(i) or {}
        # GUARDA O ARQUIVO, nao so o que foi lido dele. Sem isso a leitura
        # preenchia campo e o documento continuava so no WhatsApp — e na hora de
        # subir na operadora alguem ia catar tudo de novo, um por um.
        chave_arq, tam, mime = None, 0, (arq.get('mime') or '')
        ext = _doc_extensao(arq.get('nome'), mime)
        titularidade, parentesco = _doc_propor_titularidade(conn, lead_id, cls.get('pessoa'))
        nome_final = _doc_nome_final(cls.get('tipo'), cls.get('pessoa'), ext)
        try:
            import base64 as _b64
            dados = _b64.b64decode(b64)
            tam = len(dados)
            chave_arq = f"lead-{lead_id}-{h[:12]}.{ext}"
            upload_arquivo_r2(dados, chave_arq)
        except Exception as e:
            app.logger.warning(f"[DOC] não guardei o arquivo {arq.get('nome')}: {e}")
        try:
            if DB_MODE == 'postgres':
                conn.execute("""INSERT INTO lead_documento
                    (lead_id, conteudo_hash, nome_arquivo, tipo, pessoa, certeza, dados_json, custo_usd, criado_em)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s) ON CONFLICT (lead_id, conteudo_hash) DO NOTHING""",
                    (lead_id, h, arq.get('nome'), cls.get('tipo'), cls.get('pessoa'),
                     cls.get('certeza'), json.dumps(cls, ensure_ascii=False), 0, agora))
            else:
                conn.execute("""INSERT OR IGNORE INTO lead_documento
                    (lead_id, conteudo_hash, nome_arquivo, tipo, pessoa, certeza, dados_json, custo_usd, criado_em)
                    VALUES (?,?,?,?,?,?,?,?,?)""",
                    (lead_id, h, arq.get('nome'), cls.get('tipo'), cls.get('pessoa'),
                     cls.get('certeza'), json.dumps(cls, ensure_ascii=False), 0, agora))
            conn.execute("""UPDATE lead_documento SET arquivo=?, mime=?, tamanho=?, nome_final=?,
                            titularidade=? WHERE lead_id=? AND conteudo_hash=?""",
                         (chave_arq, mime, tam, nome_final, titularidade, lead_id, h))
            gravados += 1
        except Exception as e:
            app.logger.warning(f"[DOC] não gravei {arq.get('nome')}: {e}")

    # Guarda o conjunto ANTES de mexer no lead: e ele que vira o bloco de texto
    # da operadora e o pre-preenchimento da proposta.
    try:
        _extracao_guardar(conn, lead_id, leitura)
    except Exception as e:
        app.logger.warning(f"[DOC] extracao: {e}")

    lead = conn.execute("SELECT * FROM crm_leads WHERE id=?", (lead_id,)).fetchone()
    if not lead:
        return {'gravados': gravados, 'campos': []}

    # A pessoa do lead: casa o nome lido com o nome do cadastro. Se nenhum casar,
    # NAO forca — dado de outra pessoa no campo do titular e pior que campo vazio.
    titular = None
    for p in (leitura.get('pessoas') or []):
        if doc_mesma_pessoa(p.get('nome'), lead['nome']):
            titular = p
            break
    campos = {}
    if titular:
        if titular.get('nascimento'):
            campos['data_nascimento_titular'] = titular['nascimento']
        if titular.get('cpf'):
            campos['cpf_titular'] = re.sub(r'\D', '', titular['cpf'])
    emp = leitura.get('empresa') or {}
    if emp.get('cnpj'):
        n = re.sub(r'\D', '', emp['cnpj'])
        if len(n) == 14:
            campos['cnpj'] = f"{n[:2]}.{n[2:5]}.{n[5:8]}/{n[8:12]}-{n[12:]}"
    end = leitura.get('endereco') or {}
    if end.get('cidade'):
        campos['cidade_rmc'] = end['cidade']
    # Quantas pessoas apareceram nos documentos e um sinal de composicao familiar,
    # mas so conta quem tem nascimento — nome solto num contrato social nao e vida.
    vidas = [p for p in (leitura.get('pessoas') or []) if p.get('nascimento')]
    if len(vidas) > 1:
        campos['numero_vidas'] = str(len(vidas))

    escritos = []
    for chave, valor in campos.items():
        try:
            if gravar_campo_lead(conn, lead_id, chave, valor, fonte='ia', so_se_vazio=True):
                escritos.append(chave)
        except Exception as e:
            app.logger.info(f"[DOC] campo {chave}: {e}")
    if campos.get('cnpj'):
        try:
            _preencher_campos_por_cnpj(conn, lead_id, campos['cnpj'])
        except Exception as e:
            app.logger.info(f"[DOC] CNPJ não consultado: {e}")

    tipos = [c.get('tipo') for c in (leitura.get('arquivos') or []) if c.get('tipo') and c['tipo'] != 'outro']
    if tipos or escritos:
        desc = 'Documentos lidos: ' + (', '.join(sorted(set(tipos))) or 'nenhum reconhecido')
        if escritos:
            desc += ' · preencheu: ' + ', '.join(escritos)
        duvidas = [c['nome'] for c in (leitura.get('arquivos') or []) if c.get('certeza') == 'baixa']
        if duvidas:
            desc += f' · {len(duvidas)} sem certeza, conferir'
        conn.execute("""INSERT INTO crm_atividades (lead_id, usuario_nome, tipo, descricao, criado_em)
                        VALUES (?,?,?,?,?)""", (lead_id, 'Leitura de documentos', 'documento', desc[:500], agora))
    return {'gravados': gravados, 'campos': escritos}


# Parentesco e o que a operadora precisa saber junto com o documento: uma
# certidao de casamento so vale como comprovacao se estiver dito que aquele
