@app.route('/api/whatsapp/lead-por-telefone', methods=['GET', 'OPTIONS'])
@requer('crm:ler')
def api_whatsapp_lead_por_telefone():
    """Acha o lead do CRM pelo telefone da conversa aberta — pro botão 'Abrir
    lead no CRM' do trilho da extensão (achar automático, sem precisar rodar
    análise antes). Usa o mesmo casamento por telefone_norm/sufixo de
    _buscar_lead_por_telefone (fonte única de verdade pro dedup)."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    tel = _normalizar_telefone(request.args.get('telefone', ''))
    if not tel:
        return _wa_cors(jsonify({"ok": True, "achou": False}))
    conn = db()
    lead = _buscar_lead_por_telefone(conn, tel)
    # ABRIR A CONVERSA JA AMARRA o @lid ao lead. Era o buraco que deixava a
    # maioria dos cards sem @lid: o vinculo so nascia ao ENVIAR pela extensao ou
    # na varredura. Consultar acontece toda vez que o consultor abre um chat —
    # e o momento mais barato e mais frequente pra gravar, e nao custa nada
    # (nenhuma IA, nenhum download, e o telefone ja esta resolvido aqui).
    chat_id = (request.args.get('chat_id') or '').strip()[:100]
    if chat_id and lead:
        try:
            registrar_chat_lead(conn, chat_id, request.args.get('telefone', ''),
                                (request.args.get('nome') or '').strip()[:200] or None,
                                lead_id=lead['id'])
            conn.commit()
        except Exception as e:
            app.logger.warning(f"[WA_CHAT_LEAD] consulta não gravou: {e}")
    close_db(conn)
    if not lead:
        return _wa_cors(jsonify({"ok": True, "achou": False}))
    return _wa_cors(jsonify({"ok": True, "achou": True, "lead_id": lead['id'], "nome": lead['nome']}))


# Origens aceitas ao cadastrar lead pela extensão. Lista fechada de propósito:
# origem digitada à mão vira sujeira no funil (mesma origem escrita de 5 jeitos
# não agrupa em relatório nenhum). 'Facebook'/'Google'/'manual'/'MEDSENIOR'
# mantêm exatamente a grafia que o CRM já filtra (templates/crm.html).
_WA_ORIGENS_LEAD = ['Indicação', 'Google', 'Facebook', 'Instagram', 'MEDSENIOR', 'Site', 'manual']


@app.route('/api/whatsapp/lead/criar', methods=['POST', 'OPTIONS'])
@requer('crm:escrever')
def api_whatsapp_lead_criar():
    """Cadastra no CRM o lead da conversa aberta, quando o botão CRM da extensão
    não achou ninguém pelo telefone. Opcional (o consultor decide), mas com
    dados completos obrigatórios: nome, telefone e origem — lead sem origem não
    dá pra medir canal depois. Grava telefone_norm (senão o lead ficaria
    invisível pro casamento por telefone do resto do sistema) e deduplica pelo
    mesmo critério de _buscar_lead_por_telefone: se já existir, devolve o
    existente em vez de criar duplicata."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    d = request.get_json(silent=True) or {}
    nome = (d.get('nome') or '').strip()[:200]
    origem = (d.get('origem') or '').strip()
    tel_norm = _normalizar_telefone(d.get('telefone', ''))
    if not nome:
        return _wa_cors(jsonify({"ok": False, "erro": "Informe o nome do lead."})), 400
    # Telefone: 10 (fixo+DDD) ou 11 (celular+DDD) dígitos depois de normalizado.
    if len(tel_norm) not in (10, 11):
        return _wa_cors(jsonify({"ok": False, "erro": "Telefone inválido — confira o número da conversa."})), 400
    if origem not in _WA_ORIGENS_LEAD:
        return _wa_cors(jsonify({"ok": False, "erro": "Selecione como o lead chegou."})), 400
    try:
        uid = int(d.get('usuario_id')) if d.get('usuario_id') else None
    except (TypeError, ValueError):
        uid = None
    conn = db()
    ja = _buscar_lead_por_telefone(conn, tel_norm)
    if ja:
        close_db(conn)
        return _wa_cors(jsonify({"ok": True, "ja_existia": True, "lead_id": ja['id'], "nome": ja['nome']}))
    agora = _agora_sp()
    cur = conn.execute("""INSERT INTO crm_leads
        (nome, telefone, telefone_norm, email, empresa, origem, etapa, responsavel_id, observacoes, criado_em, atualizado_em)
        VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
        (nome, _formatar_telefone(tel_norm), tel_norm,
         (d.get('email') or '').strip()[:200] or None,
         (d.get('empresa') or '').strip()[:200] or None,
         origem, 'lead_novo', uid,
         (d.get('observacoes') or '').strip()[:2000] or None, agora, agora))
    lead_id = _last_insert_id(cur)
    if lead_id is None:
        r = conn.execute("SELECT id FROM crm_leads WHERE telefone_norm=? ORDER BY id DESC LIMIT 1",
                         (tel_norm,)).fetchone()
        lead_id = r['id'] if r else None
    autor = ''
    if uid:
        u = conn.execute("SELECT nome FROM usuarios WHERE id=?", (uid,)).fetchone()
        autor = (u['nome'] if u else '') or ''
    conn.execute("""INSERT INTO crm_atividades (lead_id, usuario_nome, tipo, descricao, criado_em)
        VALUES (?,?,?,?,?)""",
        (lead_id, autor, 'criacao', f'Lead cadastrado pela extensão (origem: {origem})', agora))
    conn.commit(); close_db(conn)
    return _wa_cors(jsonify({"ok": True, "ja_existia": False, "lead_id": lead_id}))


# ─── ETIQUETAS DA PROPOSTA: O QUE FAZER, E QUANDO ─────────────────────────────
# Etiqueta que só colore não motiva nada. Cada uma passa a carregar a AÇÃO e o
# MOMENTO em que ela cabe, e a tela destaca as que servem pra fase atual.
_ETIQUETA_ACAO = {
    'Atenção estorno': ('Conferir pagamento antes que vire estorno — ligar pro cliente hoje',
                        'Aguardando Documentos,Em Análise Operadora'),
    'Campanha':        ('Elegível a campanha da operadora — confirmar antes de emitir',
                        'Aguardando Documentos,Em Análise Operadora'),
    'Indicação':       ('Pedir indicação: cliente satisfeito indica na primeira semana',
                        'Emitida/Ativa'),
    'Pós-venda':       ('Ligar pra ativar o uso do plano — carteirinha, rede, app',
                        'Emitida/Ativa'),
    'Reajuste':        ('Avisar o cliente ANTES do boleto reajustado chegar',
                        'Emitida/Ativa'),
    'Renovação':       ('Falar de renovação 60 dias antes do aniversário do contrato',
                        'Emitida/Ativa'),
}


def _seed_etiquetas_acao(conn):
    """Preenche ação/momento das etiquetas que já existem. Não cria nem apaga
    etiqueta: quem manda na lista é o admin."""
    try:
        for nome, (acao, momento) in _ETIQUETA_ACAO.items():
            conn.execute("UPDATE etiquetas SET acao=?, momento=? WHERE nome=? AND COALESCE(acao,'')=''",
                         (acao, momento, nome))
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        app.logger.warning(f"[ETIQUETAS] seed: {e}")


def _etiquetas_do_momento(p, lead):
    """Quais etiquetas fazem sentido AGORA, e por quê. Devolve lista pronta pra
    tela — a decisão de o que fazer não deveria depender de o consultor lembrar."""
    fase = (p['status_operacional'] if 'status_operacional' in p.keys() else '') or ''
    etapa_lead = ''
    if lead is not None:
        try:
            etapa_lead = (lead['etapa'] or '')
        except Exception:
            etapa_lead = ''
    conn = db()
    out = []
    try:
        for r in conn.execute("SELECT id, nome, cor, acao, momento FROM etiquetas ORDER BY nome").fetchall():
            momentos = [m.strip() for m in (r['momento'] or '').split(',') if m.strip()]
            out.append({'id': r['id'], 'nome': r['nome'], 'cor': r['cor'],
                        'acao': r['acao'] or '',
                        'cabe_agora': bool(momentos) and fase in momentos})
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        app.logger.warning(f"[ETIQUETAS] momento: {e}")
    close_db(conn)
    return {'fase': fase, 'etapa_lead': etapa_lead, 'etiquetas': out}


# ═══════════════ API PÚBLICA: CHAVES ═══════════════════════════════════════════
# Padrão de mercado: chave mostrada UMA vez; banco guarda só o SHA-256; prefixo em
# claro só pra identificar; escopos separam leitura de escrita; revogação imediata.

_API_ESCOPOS = {
    'CRM': ['crm:ler', 'crm:escrever'],
    'Cotação': ['cotacao:ler', 'cotacao:escrever'],
    'WhatsApp': ['whatsapp:ler', 'whatsapp:enviar'],
    'Propostas': ['propostas:ler', 'propostas:escrever'],
    'Financeiro': ['financeiro:ler', 'financeiro:escrever'],
    'IA': ['ia:usar']
}
_API_PREFIXO = 'job_live_'
# Teto por chave/minuto: /calcular roda no MESMO processo que serve o CRM — sem
# teto, um consumidor em laço derruba o sistema pra todo mundo.
_API_LIMITE_MIN = int(os.environ.get('API_LIMITE_POR_MINUTO', '120'))
_API_USO = {}


def _api_hash(chave):
    return hashlib.sha256((chave or '').encode('utf-8')).hexdigest()


def _api_erro(codigo, msg, http=400, extra=None):
    corpo = {'ok': False, 'erro': codigo, 'mensagem': msg}
    if extra:
        corpo.update(extra)
    return jsonify(corpo), http


def api_requer_chave(escopo):
    """Autenticação da API pública: sem login, sem cookie, sem sessão."""
    def deco(f):
        @wraps(f)
        def w(*a, **kw):
            if request.method == 'OPTIONS':
                return _wa_cors(Response(status=204))
            auth = (request.headers.get('Authorization') or '').strip()
            bruta = auth[7:].strip() if auth.lower().startswith('bearer ') \
                else (request.headers.get('X-API-Key') or '').strip()
            if not bruta:
                r = _api_erro('sem_chave', 'Envie a chave em Authorization: Bearer <chave>', 401)
                r[0].headers['WWW-Authenticate'] = 'Bearer realm="JOB API"'
                return r
            conn = db()
            reg = conn.execute("SELECT * FROM api_chave WHERE hash=?", (_api_hash(bruta),)).fetchone()
            # Mensagem IGUAL pra chave inexistente e revogada: distinguir as duas
            # ajuda quem está tentando adivinhar chave.
            if not reg or reg['revogada_em']:
                close_db(conn)
                return _api_erro('chave_invalida', 'Chave inválida ou revogada', 401)
            escopos = (reg['escopos'] or '').split(',')
            if escopo not in escopos:
                close_db(conn)
                return _api_erro('sem_permissao', f"Esta chave não tem o escopo '{escopo}'",
                                 403, {'escopos_da_chave': escopos})
            jan = int(time.time() // 60)
            marca = (reg['id'], jan)
            _API_USO[marca] = _API_USO.get(marca, 0) + 1
            if _API_USO[marca] > _API_LIMITE_MIN:
                close_db(conn)
                r = _api_erro('limite_excedido', f'Máximo de {_API_LIMITE_MIN} chamadas por minuto', 429)
                r[0].headers['Retry-After'] = '60'
                return r
            if len(_API_USO) > 5000:
                for k in [k for k in _API_USO if k[1] < jan - 2]:
                    _API_USO.pop(k, None)
            try:
                conn.execute("UPDATE api_chave SET ultimo_uso=?, usos=COALESCE(usos,0)+1 WHERE id=?",
                             (_agora_sp(), reg['id']))
                conn.commit()
            except Exception:
                try: conn.rollback()
                except Exception: pass
            close_db(conn)
            # A view pode devolver Response OU a tupla (corpo, status) — que é o
            # que _api_erro faz. Aplicar CORS direto na tupla estoura.
            res = f(*a, **kw)
            if isinstance(res, tuple):
                return (_wa_cors(res[0]),) + tuple(res[1:])
            return _wa_cors(res)
        return w
    return deco


@app.route('/configuracoes/api-chaves', methods=['POST'])
@login_required
@admin_required
def configuracoes_api_chaves():
    d = request.json or {}
    conn = db()
    if d.get('acao') == 'criar':
        nome = (d.get('nome') or '').strip()
        if not nome:
            close_db(conn); return jsonify({"ok": False, "erro": "Dê um nome pra chave"}), 400
        usuario_id = int(d.get('usuario_id') or 0)
        if not usuario_id:
            close_db(conn); return jsonify({"ok": False, "erro": "Selecione o dono da chave"}), 400
        
        dono = conn.execute("SELECT * FROM usuarios WHERE id=?", (usuario_id,)).fetchone()
        if not dono or not dono['ativo']:
            close_db(conn); return jsonify({"ok": False, "erro": "Usuário dono inválido ou inativo"}), 400
            
        perfil = dono['perfil'] or 'visualizador'
        # Perfil desconhecido nao herda poder: cair em 'visualizador' dava
        # `financeiro:ler` de brinde a quem o sistema nao sabe classificar.
        if perfil not in PERFIL_ESCOPOS: perfil = None
        escopos_permitidos = PERFIL_ESCOPOS[perfil]
        
        escopos = [e for e in (d.get('escopos') or []) if e in escopos_permitidos and e != 'admin']
        if not escopos:
            close_db(conn); return jsonify({"ok": False, "erro": "Selecione pelo menos um escopo válido para o perfil do dono"}), 400
            
        esc = ','.join(escopos)
        chave = _API_PREFIXO + secrets.token_urlsafe(32).replace('-', '').replace('_', '')[:40]
        conn.execute("""INSERT INTO api_chave (nome, prefixo, hash, escopos, usuario_id, criado_por, criado_em)
                        VALUES (?,?,?,?,?,?,?)""",
                     (nome[:80], chave[:len(_API_PREFIXO) + 6], _api_hash(chave), esc,
                      usuario_id, session['user_id'], _agora_sp()))
        conn.commit()
        reg = conn.execute("SELECT id FROM api_chave WHERE hash=?", (_api_hash(chave),)).fetchone()
        close_db(conn)
        # A chave vai NESTA resposta e em nenhum outro lugar. Perdeu, revoga e cria
        # outra — é o comportamento correto, não uma limitação.
        return jsonify({"ok": True, "chave": chave, "id": reg['id'],
                        "aviso": "Copie agora: esta chave não será mostrada de novo."})
    if d.get('acao') == 'revogar':
        try:
            kid = int(d.get('id'))
        except (TypeError, ValueError):
            close_db(conn); return jsonify({"ok": False, "erro": "Chave inválida"}), 400
        conn.execute("UPDATE api_chave SET revogada_em=?, revogada_por=? WHERE id=? AND revogada_em IS NULL",
                     (_agora_sp(), session['user_id'], kid))
        conn.commit(); close_db(conn)
        return jsonify({"ok": True})
    close_db(conn)
    return jsonify({"ok": False, "erro": "Ação desconhecida"}), 400


# ═══════════════ API v1 — COTAÇÃO ═════════════════════════════════════════════
@app.route('/api/v1/cotacao/planos', methods=['GET', 'OPTIONS'])
@chave_ou_login_ou_extensao('cotacao:ler')
def api_v1_cotacao_planos():
    """Tabelas importadas no JOB (MedSênior, Beneficência Vital, Santa Tereza,
    as grades de PDF da Hapvida) — as operadoras que o Painel do Corretor não
    cota. É a segunda fonte da cotação da extensão.

    Antes exigia chave de API pública (`api_requer_chave`), e a extensão entra
    por token do consultor: respondia 401 e o consultor não conseguia cotar
    nada disso. Passa a aceitar sessão do site OU extensão, como a rota da
    imagem já fazia.

    Filtros: `operadora`, `abrangencia`, `modalidade`, `acomodacao`,
    `coparticipacao`. `abrangencia` é o que separa MedSênior Campinas 1 de
    Campinas 2 — sem ele as duas viram uma lista só.
    """
    conn = db()
    # `?operadoras=1` devolve SÓ a lista de operadoras, sem preço nenhum.
    # A extensão precisa dela pra desenhar a tela de escolha, e baixar 500
    # tabelas com dez faixas cada pra ler o nome de doze operadoras é o tipo
    # de chamada que fica lenta em campo e ninguém liga com o defeito.
    if (request.args.get('operadoras') or '').strip() in ('1', 'true', 'sim'):
        linhas = conn.execute(
            "SELECT operadora, COUNT(*) AS n FROM cotacao_tabela "
            "WHERE ativo=1 AND operadora IS NOT NULL AND operadora<>'' "
            "GROUP BY operadora ORDER BY operadora").fetchall()
        close_db(conn)
        return jsonify({'ok': True, 'operadoras': [
            {'nome': r['operadora'], 'planos': int(r['n'] or 0)} for r in linhas]})

    q, p = "SELECT * FROM cotacao_tabela WHERE 1=1", []
    for campo in ('modalidade', 'acomodacao', 'coparticipacao', 'operadora', 'abrangencia'):
        v = (request.args.get(campo) or '').strip()
        if v:
            q += f" AND LOWER({campo})=LOWER(?)"; p.append(v)

    cidade = (request.args.get('cidade') or '').strip()
    if cidade:
        q += " AND (COALESCE(cidade,'')='' OR LOWER(cidade)=LOWER(?))"
        p.append(cidade)

    mei = (request.args.get('mei') or '').strip().lower()
    if mei in ('1', 'true', 'sim'):
        q += " AND COALESCE(mei,0)=1"
    elif mei in ('0', 'false', 'nao', 'não'):
        q += " AND COALESCE(mei,0)=0"

    ids_str = (request.args.get('ids') or '').strip()
    if ids_str:
        ids_filtro = []
        for x in ids_str.split(','):
            try: ids_filtro.append(int(x.strip()))
            except (TypeError, ValueError): pass
        if ids_filtro:
            marc_ids = ','.join(['?'] * len(ids_filtro))
            q += f" AND id IN ({marc_ids})"
            p.extend(ids_filtro)
            
    # Filtro de múltiplas operadoras (por ID da tabela operadoras)
    op_str = (request.args.get('operadoras') or '').strip()
    if op_str:
        op_ids = []
        for x in op_str.split(','):
            try: op_ids.append(int(x.strip()))
            except: pass
        if op_ids:
            marc = ','.join(['?'] * len(op_ids))
            q += f" AND operadora IN (SELECT operadora FROM operadoras WHERE id IN ({marc}))"
            p.extend(op_ids)
            
    if (request.args.get('ativo') or '1') != 'todos':
        q += " AND ativo=?"; p.append(1 if (request.args.get('ativo') or '1') == '1' else 0)
    lim = min(500, max(1, request.args.get('limite', type=int) or 200))
    linhas = conn.execute(q + " ORDER BY operadora, plano LIMIT ?", p + [lim]).fetchall()
    precos = {}
    ids = [r['id'] for r in linhas]
    if ids:
        marc = ','.join(['?'] * len(ids))
        for r in conn.execute(f"SELECT tabela_id, faixa, preco FROM cotacao_preco "
                              f"WHERE tabela_id IN ({marc})", ids).fetchall():
            precos.setdefault(r['tabela_id'], {})[r['faixa']] = round(float(r['preco'] or 0), 2)
    close_db(conn)
    # `vidas_min`/`vidas_max` iam faltando: `calcular_cotacao` usa os dois pra
    # recusar plano fora da faixa, então sem eles a tela deixa marcar um plano
    # de 5 a 29 vidas numa cotação de 2 e o consultor só descobre no cálculo.
    def _n(t, c):
        try:
            return int(t[c]) if t[c] is not None else 0
        except (KeyError, IndexError, TypeError, ValueError):
            return 0
    return jsonify({'ok': True, 'faixas': FAIXAS_ETARIAS, 'total': len(linhas),
                    'planos': [{'id': t['id'], 'operadora': t['operadora'], 'plano': t['plano'],
                                'modalidade': t['modalidade'], 'acomodacao': t['acomodacao'],
                                'coparticipacao': t['coparticipacao'], 'abrangencia': t['abrangencia'],
                                'vigencia': t['vigencia'], 'ativo': bool(t['ativo']),
                                'criado_em': str(dict(t).get('criado_em') or ''),
                                'cidade': dict(t).get('cidade') or '',
                                'entidade': dict(t).get('entidade') or '',
                                'administradora': dict(t).get('administradora') or '',
                                'linha': dict(t).get('linha') or '',
                                'tipo_cnpj': dict(t).get('tipo_cnpj') or '',
                                'vidas_min': _n(t, 'vidas_min'), 'vidas_max': _n(t, 'vidas_max'),
                                # `mei` nunca saia daqui, e sem ele a extensao
                                # tratava TODA tabela do JOB como "nao aceita
                                # MEI" — travava Vera Cruz, MedSenior e
                                # Beneficencia inteiras pra cliente MEI.
                                'mei': _n(t, 'mei') == 1,
                                'faixas': precos.get(t['id'], {})} for t in linhas]})


def _proximo_passo_calculo(planos, avisos, pedidos):
    """Frase acionável para quando o cálculo "deu certo" mas não entrega o que
    foi pedido.

    Existe porque a recusa por faixa de vidas faz o plano SUMIR de `resultados`
    em vez de voltar com elegivel=False (o motor dá `continue`). Quem lê só
    `ok`, `total_geral` e `resultados` não tem como perceber. E o caso perigoso
    não é o total zerado — esse é anômalo o bastante pra levantar suspeita. É o
    PARCIAL: volta um total plausível com um plano a menos e nenhum zero pra
    denunciar. 663 das 669 tabelas ativas têm faixa de vidas, então cair nisso é
    o caminho comum, não a exceção.

    Sai como chave NOVA e opcional: trocar ok:true por ok:false quebraria a tela
    (que aborta o cálculo inteiro e perde junto os planos que TÊM preço) e a
    extensão (que perde o motivo específico e passa a culpar o banco). E o nome
    não pode ser 'erro' nem 'mensagem': o cliente do MCP lê essas duas chaves
    como falha mesmo quando ok=True."""
    if not avisos:
        return None
    # dict.fromkeys em vez de set: tira o repetido (o mesmo motivo volta uma vez
    # por plano) sem embaralhar a ordem em que os avisos saíram.
    vistos = dict.fromkeys((a.get('mensagem') or a.get('codigo') or '')
                           for a in avisos if isinstance(a, dict))
    motivos = '; '.join(m for m in vistos if m)
    codigos = {a.get('codigo') for a in avisos if isinstance(a, dict)}
    # A orientação segue o motivo real: mandar "ajuste as vidas" quando o plano
    # nem existe faz o agente girar em falso na correção errada.
    if 'fora_da_faixa_de_vidas' in codigos:
        acao = ('Escolha planos que aceitem esta quantidade de vidas (cada plano traz '
                'vidas_min e vidas_max) e calcule de novo.')
    else:
        acao = 'Confira os planos enviados em cotacoes_planos_listar e calcule de novo.'
    if not planos:
        return ('Nenhum plano pôde ser calculado para este grupo — total zero não é preço. '
                f'Motivo: {motivos}. {acao} Não apresente este resultado ao cliente.')
    faltando = max(0, pedidos - len(planos))
    if faltando:
        ficou = 'ficou' if faltando == 1 else 'ficaram'
        sobrou = (f'o {len(planos)} que sobrou' if len(planos) == 1
                  else f'os {len(planos)} que sobraram')
        return (f'{faltando} de {pedidos} planos pedidos {ficou} FORA de "resultados": '
                f'o total_geral cobre só {sobrou}. Motivo: {motivos}. '
                'Confira antes de comparar preços com o cliente.')
    return f'Cálculo saiu com ressalva: {motivos}.'


@app.route('/api/v1/cotacao/calcular', methods=['POST', 'OPTIONS'])
# Mesma porta da rota de cima: chave de API pública OU sessão/extensão.
# Calcular não cria nada — é leitura com conta.
@chave_ou_login_ou_extensao('cotacao:ler')
def api_v1_cotacao_calcular():
    """Calcula sem salvar. É o que a extensão usa pra mostrar preço na conversa
    sem sujar o banco com cotação de rascunho."""
    d = request.get_json(silent=True) or {}
    bruto = d.get('idades') or []
    if not isinstance(bruto, list) or not bruto:
        return _api_erro('idades_obrigatorias', 'Envie "idades": [42, 39, 12]')
    idades = []
    for x in bruto[:60]:
        try:
            i = int(x)
        except (TypeError, ValueError):
            return _api_erro('idade_invalida', f'Idade inválida: {x!r}')
        if i < 0 or i > 120:
            return _api_erro('idade_invalida', f'Idade fora de 0 a 120: {i}')
        idades.append(i)
    pl = d.get('planos') or []
    ids, recs = [], {}
    for x in pl[:30]:
        v = x.get('plano_id') if isinstance(x, dict) else x
        try:
            vi = int(v)
        except (TypeError, ValueError):
            continue
        ids.append(vi)
        if isinstance(x, dict) and x.get('recomendacao'):
            recs[vi] = x['recomendacao']
    if not ids:
        return _api_erro('planos_obrigatorios', 'Envie "planos": [42, 57] ou [{"plano_id": 42}]')
    conn = db()
    planos, total, dist, avisos = calcular_cotacao(conn, idades, ids, recs)
    close_db(conn)
    resp = {'ok': True, 'vidas': len(idades), 'distribuicao': dist,
            'resultados': planos, 'total_geral': total, 'avisos': avisos}
    prox = _proximo_passo_calculo(planos, avisos, len(ids))
    if prox:
        resp['proximo_passo'] = prox
    return jsonify(resp)


def _cotacao_completa(conn, c):
    """Tudo o que existe de uma cotação salva — é o "extrair tudo" do pedido."""
    d = dict(c)
    for campo, destino in (('planos_json', 'planos'), ('vidas_json', 'vidas')):
        try:
            d[destino] = json.loads(d.get(campo) or '[]')
        except Exception:
            d[destino] = []
        d.pop(campo, None)
    d['url_publica'] = _SITE_BASE_URL + '/c/' + (d.get('token') or '')
    d['url_documento'] = '/cotacao/documento/' + str(d.get('id'))
    d['imagem_url'] = ('/api/v1/cotacao/%s/imagem' % d['id']) if d.get('imagem_arquivo') else None
    try:
        d['engajamento'] = [dict(r) for r in conn.execute(
            "SELECT evento, dados, criado_em FROM cotacao_engajamento WHERE cotacao_id=? ORDER BY id",
            (d['id'],)).fetchall()]
    except Exception:
        d['engajamento'] = []
    return d


@app.route('/api/v1/cotacao/<int:cid>', methods=['GET', 'OPTIONS'])
@requer('cotacao:ler')
def api_v1_cotacao_ler(cid):
    conn = db()
    c = conn.execute("SELECT * FROM cotacao_salva WHERE id=?", (cid,)).fetchone()
    if not c:
        close_db(conn); return _api_erro('nao_encontrada', 'Cotação não encontrada', 404)
    usuario = _api_usuario_ativo(conn)
    if not usuario or (usuario['perfil'] != 'admin' and c['corretor_id'] != usuario['id']):
        close_db(conn); return _api_erro('sem_permissao', 'Você não pode consultar esta cotação', 403)
    out = _cotacao_completa(conn, c)
    close_db(conn)
    return jsonify({'ok': True, 'cotacao': out})


@app.route('/api/v1/cotacao/salvas', methods=['GET', 'OPTIONS'])
@requer('cotacao:ler')
def api_v1_cotacao_salvas():
    """O mesmo histórico da tela /cotacao/salvas, extraível por inteiro."""
    conn = db()
    q, p = "SELECT * FROM cotacao_salva WHERE 1=1", []
    usuario = _api_usuario_ativo(conn)
    if not usuario:
        close_db(conn); return _api_erro('nao_autenticado', 'Usuário da chave inválido ou inativo', 401)
    if usuario['perfil'] != 'admin':
        q += " AND corretor_id=?"; p.append(usuario['id'])
    if request.args.get('lead_id', type=int):
        q += " AND lead_id=?"; p.append(request.args.get('lead_id', type=int))
    tel = (request.args.get('telefone') or '').strip()
    if tel:
        tn = _normalizar_telefone(tel)
        if tn:
            q += " AND cliente_telefone LIKE ?"; p.append('%' + tn[-8:])
    if (request.args.get('desde') or '').strip():
        q += " AND CAST(criado_em AS TEXT) >= ?"; p.append(request.args.get('desde'))
    lim = min(200, max(1, request.args.get('limite', type=int) or 50))
    linhas = conn.execute(q + " ORDER BY id DESC LIMIT ?", p + [lim]).fetchall()
    out = [_cotacao_completa(conn, c) for c in linhas]
    close_db(conn)
    return jsonify({'ok': True, 'cotacoes': out, 'total': len(out)})


@app.route('/api/v1/cotacao/<int:cid>/imagem', methods=['GET', 'OPTIONS'])
# ABERTA PRA EXTENSAO em 08/08, por decisao do Guilherme.
#
# Ela era so da API publica, com chave. Trocar a fechadura teria fechado a
# porta da unica chave em uso ('GABRIEL TESTE', 4 usos) — por isso ficou
# pendente ontem. Hoje ele revogou essa chave e vai emitir uma nova, entao
# nao ha mais consumidor externo a proteger.
#
# A chave nova que ele criar precisa cobrir cotacao + extensao + CRM num
# lugar so. Enquanto isso nao existe, quem alcanca isto e a sessao do site ou
# o token do consultor.
@requer('cotacao:ler')
def api_v1_cotacao_imagem(cid):
    """PNG da cotação. A imagem é renderizada no NAVEGADOR (html2canvas) e
    persistida quando alguém abre o documento — o servidor não tem navegador."""
    conn = db()
    c = conn.execute("SELECT imagem_arquivo, corretor_id FROM cotacao_salva WHERE id=?", (cid,)).fetchone()
    if not c:
        close_db(conn)
        return _api_erro('nao_encontrada', 'Cotação não encontrada', 404)
    usuario = _api_usuario_ativo(conn)
    if not usuario or (usuario['perfil'] != 'admin' and c['corretor_id'] != usuario['id']):
        close_db(conn); return _api_erro('sem_permissao', 'Você não pode consultar esta imagem', 403)
    close_db(conn)
    if not c['imagem_arquivo']:
        return _api_erro('imagem_ausente',
                         f'Imagem ainda não gerada. Abrir /cotacao/documento/{cid} uma vez a cria.',
                         404, {'url_documento': f'/cotacao/documento/{cid}'})
    conteudo, ctype = _localizar_anexo(os.path.basename(c['imagem_arquivo']))
    if conteudo is None:
        return _api_erro('imagem_ausente', 'Arquivo não encontrado no armazenamento', 404)
    resp = Response(conteudo, mimetype=ctype or 'image/png')
    resp.headers['Cache-Control'] = 'private, max-age=3600'
    return resp


@app.route('/cotacao/<int:cid>/imagem', methods=['POST'])
def cotacao_guardar_imagem(cid):
    """A página do documento manda o PNG que ela mesma renderizou. Continua sem
    login de propósito — o link público /c/<token> também renderiza e não tem
    sessão —, mas em troca a página pública precisa PROVAR que conhece o token
    da cotação. Sem essa prova, qualquer um plantava o PNG de qualquer cotação
    que ainda não tivesse imagem, acertando só o id numérico: e esse é
    exatamente o arquivo que o corretor manda para o cliente."""
    d = request.get_json(silent=True) or {}
    b64 = (d.get('imagem') or '').strip()
    if b64.startswith('data:'):
        b64 = b64.split(',', 1)[-1]
    if not b64 or len(b64) > 12_000_000:
        return jsonify({'ok': False, 'erro': 'imagem_invalida'}), 400
    conn = db()
    c = conn.execute("SELECT id, imagem_arquivo, token FROM cotacao_salva WHERE id=?", (cid,)).fetchone()
    if not c:
        close_db(conn); return jsonify({'ok': False, 'erro': 'nao_encontrada'}), 404
    # A checagem vem ANTES do "já existia" de propósito: senão a rota vira
    # oráculo de quais cotações ainda estão sem imagem.
    if not session.get('user_id'):
        enviado = (d.get('token') or '').strip()
        if not enviado or not hmac.compare_digest(enviado, c['token'] or ''):
            close_db(conn)
            app.logger.warning(f"[COTACAO_IMG] {cid}: gravação recusada — sem sessão e sem token válido")
            return jsonify({'ok': False, 'erro': 'nao_autorizado'}), 403
    if c['imagem_arquivo']:
        close_db(conn); return jsonify({'ok': True, 'ja_existia': True})
    try:
        import base64 as _b64i, io as _ioi
        nome = f"COTACAO_{cid}_{secrets.token_hex(6)}.png"
        upload_arquivo_r2(_ioi.BytesIO(_b64i.b64decode(b64)), f"cotacoes/{nome}")
        conn.execute("UPDATE cotacao_salva SET imagem_arquivo=?, imagem_em=? WHERE id=?",
                     (nome, _agora_sp(), cid))
        conn.commit()
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        close_db(conn)
        app.logger.warning(f"[COTACAO_IMG] {cid}: {e}")
        return jsonify({'ok': False, 'erro': 'falha_ao_salvar'}), 500
    close_db(conn)
    return jsonify({'ok': True})


# ─── VARREDURA: CONFIGURAÇÃO ──────────────────────────────────────────────────
# Guardada em meta_flags como JSON (chave 'varredura_cfg'): é config de uma coisa
# só, não merece tabela própria, e assim já nasce disponível em todo lugar.
_VARREDURA_PADRAO = {
    'ativa': False,           # mestre: desligada até alguém ligar de propósito
    'horas': 24,              # janela de conversas a considerar
    'max_rodada': 12,         # teto de conversas por rodada
    'intervalo_min': 30,      # de quanto em quanto tempo
    'hora_inicio': 8,
    'hora_fim': 20,
    'dias_uteis': True,       # não roda sábado/domingo
    'forcar_ate': None,       # timestamp: "rodar agora" pedido pelo painel
}


def varredura_cfg(conn=None):
    fechar = False
    if conn is None:
        conn = db(); fechar = True
    cfg = dict(_VARREDURA_PADRAO)
    try:
        r = conn.execute("SELECT v FROM meta_flags_valor WHERE k='varredura_cfg'").fetchone()
        if r and r['v']:
            cfg.update(json.loads(r['v']))
    except Exception as e:
        # ROLLBACK obrigatório: no Postgres a transação fica abortada depois de um
        # erro, e TODA query seguinte na mesma conexão falha. Engolir o erro sem
        # desfazer é o que derrubou a página inteira, não só esta config.
        try:
            conn.rollback()
        except Exception:
            pass
        app.logger.warning(f"[VARREDURA] config não lida: {e}")
    if fechar:
        close_db(conn)
    return cfg


def varredura_cfg_salvar(conn, novo):
    atual = varredura_cfg(conn)
    atual.update(novo or {})
    try:
        conn.execute("CREATE TABLE IF NOT EXISTS meta_flags_valor (k TEXT PRIMARY KEY, v TEXT)")
        if conn.execute("SELECT 1 FROM meta_flags_valor WHERE k='varredura_cfg'").fetchone():
            conn.execute("UPDATE meta_flags_valor SET v=? WHERE k='varredura_cfg'",
                         (json.dumps(atual, ensure_ascii=False),))
        else:
            conn.execute("INSERT INTO meta_flags_valor (k,v) VALUES ('varredura_cfg',?)",
                         (json.dumps(atual, ensure_ascii=False),))
    except Exception as e:
        app.logger.warning(f"[VARREDURA] não salvou config: {e}")
    return atual


def varredura_pode_agora(cfg, uid=None, conn=None):
    """Decide se a varredura pode rodar NESTE momento pra ESTE consultor. A
    resposta vai pra extensão junto com o motivo — 'não roda' sem motivo é o que
    faz alguém ficar meia hora achando que está quebrado."""
    if cfg.get('forcar_ate'):
        try:
            if float(cfg['forcar_ate']) > time.time():
                return True, 'rodar_agora'
        except (TypeError, ValueError):
            pass
    if not cfg.get('ativa'):
        return False, 'desligada'
    if uid is not None:
        try:
            u = (conn or db()).execute("SELECT varredura_ativa FROM usuarios WHERE id=?", (uid,)).fetchone()
            if not u or not (u['varredura_ativa'] or 0):
                return False, 'consultor_fora'
        except Exception:
            return False, 'consultor_desconhecido'
    agora = datetime.now(TZ_SP)
    if cfg.get('dias_uteis') and agora.weekday() >= 5:
        return False, 'fim_de_semana'
    if not (int(cfg.get('hora_inicio', 8)) <= agora.hour < int(cfg.get('hora_fim', 20))):
        return False, 'fora_do_horario'
    return True, 'ok'


@app.route('/configuracoes/varredura', methods=['POST'])
@login_required
@admin_required
def configuracoes_varredura():
    d = request.json or {}
    conn = db()
    if d.get('acao') == 'rodar_agora':
        # Vale por 10 minutos: tempo de a extensão consultar a config e disparar,
        # sem deixar o "rodar agora" ligado pra sempre por esquecimento.
        cfg = varredura_cfg_salvar(conn, {'forcar_ate': time.time() + 600})
    elif d.get('acao') == 'consultor':
        try:
            uid = int(d.get('usuario_id'))
        except (TypeError, ValueError):
            close_db(conn); return jsonify({"ok": False, "erro": "Consultor inválido"}), 400
        conn.execute("UPDATE usuarios SET varredura_ativa=? WHERE id=?",
                     (1 if d.get('ativo') else 0, uid))
        cfg = varredura_cfg(conn)
    else:
        limpo = {}
        for k in ('ativa', 'dias_uteis'):
            if k in d:
                limpo[k] = bool(d[k])
        for k, lo, hi in (('horas', 1, 168), ('max_rodada', 1, 60),
                          ('intervalo_min', 5, 720), ('hora_inicio', 0, 23), ('hora_fim', 1, 24)):
            if k in d:
                try:
                    limpo[k] = max(lo, min(hi, int(d[k])))
                except (TypeError, ValueError):
                    pass
        if limpo.get('hora_fim') is not None and limpo.get('hora_inicio') is not None \
           and limpo['hora_fim'] <= limpo['hora_inicio']:
            close_db(conn); return jsonify({"ok": False, "erro": "O fim tem que ser depois do início"}), 400
        cfg = varredura_cfg_salvar(conn, limpo)
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "cfg": cfg})


