@admin_required
def ia_saude_painel():
    return render_template('ia_saude.html', provedores=ia_saude())


@app.route('/ia-saude/testar', methods=['POST'])
@login_required
@admin_required
def ia_saude_testar():
    """Bate de verdade em cada provedor com a chamada mais barata possível. É a
    diferença entre 'não deu erro ainda' e 'está funcionando agora'."""
    alvo = (request.json or {}).get('provedor') or ''
    res = {}
    if alvo in ('groq', 'openai', ''):
        # WAV de 0,5s de silêncio, montado na hora. A primeira versão tinha ZERO
        # segundo de áudio e os dois provedores recusavam com 'audio_too_short' —
        # o teste marcava erro num provedor saudável, que é pior que não testar.
        import base64 as _b64, struct as _st
        taxa, dur = 8000, 0.5
        n = int(taxa * dur)
        dados = b'\x00\x00' * n
        cab = (b'RIFF' + _st.pack('<I', 36 + len(dados)) + b'WAVEfmt ' +
               _st.pack('<IHHIIHH', 16, 1, 1, taxa, taxa * 2, 2, 16) +
               b'data' + _st.pack('<I', len(dados)))
        wav = _b64.b64encode(cab + dados).decode('ascii')
        # Bate em CADA provedor separadamente. Usar _transcrever_audio testaria só a
        # Groq: ela é a primária e, dando certo, a OpenAI (reserva) nunca é
        # chamada — o registro dela envelhecia e a tela mostrava 'erro' de um
        # teste antigo, num provedor que ninguém sabia se estava de pé.
        import base64 as _b64d
        raw = _b64d.b64decode(wav)
        provs = [
            ('groq', 'https://api.groq.com/openai/v1/audio/transcriptions',
             (os.environ.get('GROQ_API_KEY') or '').strip(),
             os.environ.get('GROQ_TRANSCRICAO_MODELO', 'whisper-large-v3-turbo')),
            ('openai', 'https://api.openai.com/v1/audio/transcriptions',
             (os.environ.get('OPENAI_API_KEY') or '').strip(),
             os.environ.get('OPENAI_TRANSCRICAO_MODELO', 'whisper-1')),
        ]
        for nome, url, chave, modelo in provs:
            if not chave:
                res[nome] = 'sem chave'
                continue
            try:
                rr = _requests.post(url, headers={'Authorization': f'Bearer {chave}'},
                                    files={'file': ('teste.wav', raw, 'audio/wav')},
                                    data={'model': modelo, 'language': 'pt'}, timeout=40)
                if rr.status_code == 200:
                    ia_registrar(nome, True)
                    res[nome] = 'ok'
                else:
                    ia_registrar(nome, False, rr.status_code, rr.text[:400])
                    st, det = _ia_classificar(rr.status_code, rr.text[:400])
                    res[nome] = 'ok' if st == 'ok' else det
            except Exception as e:
                ia_registrar(nome, False, None, str(e)[:400])
                res[nome] = str(e)[:160]
    if alvo in ('claude', ''):
        try:
            import anthropic
            k = (os.environ.get('ANTHROPIC_API_KEY') or '').strip()
            if not k:
                ia_registrar('claude', False, None, 'sem chave configurada')
                res['claude'] = 'sem chave'
            else:
                c = anthropic.Anthropic(api_key=k, timeout=30.0, max_retries=0)
                c.messages.create(model=_CLAUDE_MODEL, max_tokens=4,
                                  messages=[{"role": "user", "content": "oi"}])
                ia_registrar('claude', True)
                res['claude'] = 'ok'
        except Exception as e:
            ia_registrar('claude', False, getattr(e, 'status_code', None), str(e)[:400])
            res['claude'] = str(e)[:200]
    return jsonify({"ok": True, "resultado": res, "provedores": ia_saude()})


# ─── VENDA PRECISA DE LEAD ────────────────────────────────────────────────────
@app.route('/proposta/checar-lead', methods=['POST'])
@login_required
def proposta_checar_lead():
    """Antes de gravar a venda, diz se ela tem lead. Se não tiver, devolve o que
    seria preciso pra criar um na hora — em vez de só barrar o consultor no meio
    do cadastro. Metade das vendas hoje entra fora do funil (25 de 48), e venda
    sem lead é venda sem origem de mídia e sem retorno pro Google Ads."""
    d = request.json or {}
    lead_id = d.get('lead_id_origem')
    conn = db()
    if lead_id:
        r = conn.execute("SELECT id, nome FROM crm_leads WHERE id=?", (lead_id,)).fetchone()
        if r:
            close_db(conn)
            return jsonify({"ok": True, "tem_lead": True, "lead": dict(r), "criterio": "informado"})
    # Sem id explícito: tenta achar pelos mesmos critérios do vínculo (CNPJ, depois
    # telefone), pra não obrigar a criar um lead que já existe.
    falso = {'cnpj': (d.get('cnpj') or ''), 'tel_resp_contrato': (d.get('tel_resp_contrato') or ''),
             'tel_resp_negociacao': (d.get('tel_resp_negociacao') or '')}
    class _P(dict):
        def keys(self): return list(super().keys())
    achado, criterio = achar_lead_da_proposta(conn, _P(falso))
    if achado:
        r = conn.execute("SELECT id, nome FROM crm_leads WHERE id=?", (achado,)).fetchone()
        close_db(conn)
        return jsonify({"ok": True, "tem_lead": True, "lead": dict(r) if r else None, "criterio": criterio})
    close_db(conn)
    return jsonify({"ok": True, "tem_lead": False, "criterio": criterio,
                    "sugestao": {"nome": (d.get('razao_social') or d.get('resp_contrato') or ''),
                                 "telefone": (d.get('tel_resp_contrato') or d.get('tel_resp_negociacao') or ''),
                                 "email": (d.get('email_resp_contrato') or ''),
                                 "cnpj": (d.get('cnpj') or '')},
                    "origens": _WA_ORIGENS_LEAD})


@app.route('/proposta/criar-lead', methods=['POST'])
@login_required
def proposta_criar_lead():
    """Cria o lead ali mesmo, com o que o consultor já digitou na proposta. É a
    saída da trava: em vez de 'você não pode cadastrar', vira 'um clique e a venda
    nasce ligada'."""
    d = request.json or {}
    nome = (d.get('nome') or '').strip()[:120]
    telefone = (d.get('telefone') or '').strip()
    if not nome:
        return jsonify({"ok": False, "erro": "Nome é obrigatório"}), 400
    tel_norm = _normalizar_telefone(telefone)
    conn = db()
    if tel_norm:
        ja = _buscar_lead_por_telefone(conn, tel_norm)
        if ja:
            close_db(conn)
            return jsonify({"ok": True, "lead_id": ja['id'], "nome": ja['nome'], "ja_existia": True})
    origem = (d.get('origem') or 'manual')
    if origem not in _WA_ORIGENS_LEAD:
        origem = 'manual'
    etapas = [e['id'] for e in carregar_etapas_crm(conn)]
    # Nasce como venda fechada: a proposta está sendo cadastrada agora, então
    # colocar em 'Novo Lead' criaria um card falso no topo do funil.
    etapa = 'venda_fechada' if 'venda_fechada' in etapas else (etapas[0] if etapas else 'lead_novo')
    # _last_insert_id PRECISA do cursor deste INSERT — passar outro devolve o id
    # errado (ou None). Já errei isso nesta mesma base.
    cur = conn.execute("""INSERT INTO crm_leads (nome, telefone, telefone_norm, email, empresa, origem,
                    etapa, responsavel_id, criado_em, atualizado_em, avancou_em,
                    indicado_por_lead_id, indicado_por_nome, qual_cnpj)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                 (nome, telefone or None, tel_norm or None, (d.get('email') or '').strip() or None,
                  (d.get('empresa') or '').strip() or None, origem, etapa, session['user_id'],
                  _agora_sp(), _agora_sp(), _agora_sp(),
                  (int(d['indicado_por_lead_id']) if str(d.get('indicado_por_lead_id') or '').isdigit() else None),
                  (d.get('indicado_por_nome') or '').strip()[:120] or None,
                  (d.get('cnpj') or '').strip() or None))
    lid = _last_insert_id(cur)
    if not lid:
        lid = conn.execute("SELECT id FROM crm_leads WHERE telefone_norm=? OR nome=? ORDER BY id DESC LIMIT 1",
                           (tel_norm or '', nome)).fetchone()['id']
    conn.execute("""INSERT INTO crm_atividades (lead_id, usuario_nome, tipo, descricao, criado_em)
                    VALUES (?,?,?,?,?)""",
                 (lid, session.get('nome'), 'edicao', 'Lead criado no cadastro da proposta', _agora_sp()))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "lead_id": lid, "nome": nome, "ja_existia": False})


# ─── INDICAÇÃO: QUEM TROUXE QUEM ──────────────────────────────────────────────
@app.route('/crm/leads/buscar')
@login_required
def crm_leads_buscar():
    """Busca leads por nome ou telefone, pra escolher quem indicou. Devolve pouco
    de propósito: é um seletor, não uma listagem."""
    q = (request.args.get('q') or '').strip()
    excluir = request.args.get('excluir', type=int)
    if len(q) < 2:
        return jsonify({"ok": True, "leads": []})
    conn = db()
    tel = _normalizar_telefone(q)
    like = f'%{q.lower()}%'
    sql = """SELECT l.id, l.nome, l.telefone, l.etapa, u.nome resp
             FROM crm_leads l LEFT JOIN usuarios u ON u.id = l.responsavel_id
             WHERE (LOWER(l.nome) LIKE ? OR l.telefone_norm LIKE ?)"""
    p = [like, ('%' + tel) if tel else '%__nada__%']
    if excluir:
        sql += " AND l.id <> ?"
        p.append(excluir)
    rows = conn.execute(sql + " ORDER BY l.atualizado_em DESC LIMIT 12", p).fetchall()
    close_db(conn)
    return jsonify({"ok": True, "leads": [dict(r) for r in rows]})


@app.route('/crm/lead/<int:lid>/indicacao', methods=['POST'])
@login_required
def crm_lead_indicacao(lid):
    """Liga este lead a quem o indicou. Aceita o id de outro lead (o caso bom) ou
    só um nome, quando quem indicou não é lead do CRM (um parceiro, um cliente
    antigo). O nome sozinho não fecha conta, mas é melhor que perder a informação."""
    d = request.json or {}
    conn = db()
    lead = conn.execute("SELECT * FROM crm_leads WHERE id=?", (lid,)).fetchone()
    if not lead:
        close_db(conn); return jsonify({"ok": False, "erro": "Lead não encontrado"}), 404
    if session.get('perfil') != 'admin' and lead['responsavel_id'] != session.get('user_id'):
        close_db(conn); return jsonify({"ok": False, "erro": "Sem permissão"}), 403
    ind_id = d.get('indicado_por_lead_id')
    nome = (d.get('indicado_por_nome') or '').strip()[:120]
    try:
        ind_id = int(ind_id) if ind_id else None
    except (TypeError, ValueError):
        ind_id = None
    if ind_id == lid:
        close_db(conn); return jsonify({"ok": False, "erro": "Um lead não pode indicar a si mesmo"}), 400
    if ind_id:
        ref = conn.execute("SELECT nome FROM crm_leads WHERE id=?", (ind_id,)).fetchone()
        if not ref:
            close_db(conn); return jsonify({"ok": False, "erro": "Quem indicou não foi encontrado"}), 404
        # Ciclo simples (A indica B, B indica A) não quebra nada hoje, mas embaralha
        # qualquer contagem de "quantos o fulano trouxe" — recusa e explica.
        volta = conn.execute("SELECT indicado_por_lead_id FROM crm_leads WHERE id=?", (ind_id,)).fetchone()
        if volta and volta['indicado_por_lead_id'] == lid:
            close_db(conn)
            return jsonify({"ok": False, "erro": "Esses dois já se indicam mutuamente"}), 400
        nome = nome or (ref['nome'] or '')
    conn.execute("""UPDATE crm_leads SET indicado_por_lead_id=?, indicado_por_nome=?,
                    origem=CASE WHEN COALESCE(origem,'')='' OR origem='manual' THEN 'Indicação' ELSE origem END,
                    atualizado_em=? WHERE id=?""",
                 (ind_id, nome or None, _agora_sp(), lid))
    conn.execute("""INSERT INTO crm_atividades (lead_id, usuario_nome, tipo, descricao, criado_em)
                    VALUES (?,?,?,?,?)""",
                 (lid, session.get('nome'), 'edicao',
                  ('Indicado por: ' + (nome or f'lead #{ind_id}')) if (ind_id or nome) else 'Indicação removida',
                  _agora_sp()))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "indicado_por_lead_id": ind_id, "indicado_por_nome": nome})


def indicacoes_do_lead(conn, lid):
    """Quem este lead indicou, e o que já virou venda. É a conta que transforma
    'indicação' de origem solta em canal com resultado medido."""
    try:
        rows = conn.execute("""SELECT l.id, l.nome, l.etapa, p.id prop_id, p.razao_social,
                                      p.comissao_total_corretora com
                               FROM crm_leads l
                               LEFT JOIN propostas p ON p.lead_id = l.id
                                    AND p.status_operacional='Emitida/Ativa'
                                    AND COALESCE(p.estornada,0)=0 AND COALESCE(p.status,'')<>'Excluída'
                               WHERE l.indicado_por_lead_id=? ORDER BY l.criado_em DESC""", (lid,)).fetchall()
    except Exception:
        return {'indicados': [], 'vendas': 0, 'comissao': 0.0}
    ind = [dict(r) for r in rows]
    return {'indicados': ind,
            'vendas': sum(1 for r in ind if r.get('prop_id')),
            'comissao': sum(float(r.get('com') or 0) for r in ind if r.get('prop_id'))}


# ─── VARREDURA DIÁRIA: O QUE VALE ANALISAR ────────────────────────────────────
# CONTRATO (a extensão pergunta antes de subir qualquer conversa):
#
#   POST /api/whatsapp/conversas/pendentes
#   {"conversas": [
#      {"chat_id": "1234@lid",        # identificador da CONVERSA no WhatsApp
#       "telefone": "19991046030",    # identificador da PESSOA (balizador do JOB)
#       "ultima_msg_id": "ABC123",    # id da última mensagem que existe hoje
#       "ultima_msg_em": 1785400000,  # timestamp dela (epoch)
#       "msgs": 42}                   # total de mensagens na conversa
#   ]}
#
#   -> {"analisar": [{"chat_id": "...", "desde_msg_id": "XYZ", "motivo": "novas_mensagens"}],
#       "pular":    [{"chat_id": "...", "motivo": "sem_novidade"}]}
#
# A extensão SÓ baixa e sobe as conversas que vierem em "analisar", e só a partir
# de "desde_msg_id". É isso que impede pagar de novo por conversa que não mudou —
# a decisão é do servidor, que é quem sabe o que já foi analisado.
#
# Por que as DUAS chaves: o @lid identifica a conversa (o WhatsApp novo não expõe
# mais o telefone no data-id), e o telefone identifica a pessoa. Um @lid pode não
# resolver telefone nenhum; e a mesma pessoa pode aparecer com @lid diferente.
# Guardando os dois, nenhum dos casos vira reanálise nem lead duplicado.
_MOTIVOS_PENDENTE = {
    'nunca_analisada': 'conversa ainda não foi analisada',
    'novas_mensagens': 'tem mensagem nova desde a última análise',
    'sem_novidade': 'nada mudou desde a última análise',
    'sem_mensagem': 'conversa sem mensagem',
}


def _wa_desempenho(conn):
    """Quanto tempo as coisas levam, medido — nao sentido.

    Duas fontes, de proposito: a fila JA guarda criado_em e enviado_em, entao o
    tempo de espera de mensagem pode ser medido no historico inteiro, inclusive
    de antes de existir medicao nenhuma. wa_metrica cobre o que o servidor nao
    ve (transcricao, analise, envio visto do lado do navegador).

    Mediana e p95 em vez de media: uma mensagem que ficou presa 40 minutos
    empurra a media e some da mediana — e o que interessa e o dia normal e o
    dia ruim, separados."""
    def _percentis(vals):
        if not vals:
            return None
        vals = sorted(vals)
        def p(q):
            i = min(len(vals) - 1, max(0, int(round(q * (len(vals) - 1)))))
            return vals[i]
        return {'n': len(vals), 'p50': p(0.50), 'p95': p(0.95), 'max': vals[-1]}

    out = {'fila': None, 'ops': [], 'desde': None}
    corte = (datetime.now(TZ_SP) - timedelta(days=7)).strftime('%Y-%m-%d %H:%M:%S')
    out['desde'] = corte[:10]
    try:
        esperas = []
        for r in conn.execute("""SELECT criado_em, enviado_em FROM whatsapp_extensao_fila
                                 WHERE status='enviado' AND enviado_em IS NOT NULL
                                   AND criado_em >= ? ORDER BY id DESC LIMIT 800""", (corte,)).fetchall():
            a_, b_ = _parse_dt_seguro(r['criado_em']), _parse_dt_seguro(r['enviado_em'])
            if a_ and b_:
                seg = (b_ - a_).total_seconds()
                if 0 <= seg < 86400:
                    esperas.append(round(seg, 1))
        out['fila'] = _percentis(esperas)
    except Exception as e:
        app.logger.warning(f"[DESEMPENHO] fila: {e}")
        try: conn.rollback()
        except Exception: pass
    try:
        por_op = {}
        for r in conn.execute("""SELECT operacao, ms FROM wa_metrica
                                 WHERE criado_em >= ? AND ms > 0
                                 ORDER BY id DESC LIMIT 4000""", (corte,)).fetchall():
            por_op.setdefault(r['operacao'], []).append(int(r['ms'] or 0))
        for op, vals in sorted(por_op.items()):
            p = _percentis(vals)
            if p:
                out['ops'].append({'operacao': op, 'n': p['n'],
                                   'p50': round(p['p50'] / 1000.0, 1),
                                   'p95': round(p['p95'] / 1000.0, 1),
                                   'max': round(p['max'] / 1000.0, 1)})
    except Exception as e:
        app.logger.warning(f"[DESEMPENHO] métricas: {e}")
        try: conn.rollback()
        except Exception: pass
    return out


@app.route('/api/whatsapp/metrica', methods=['POST', 'OPTIONS'])
@requer('whatsapp:enviar')
def api_whatsapp_metrica():
    """A extensao reporta quanto tempo cada coisa levou.

    Pedido do Guilherme: "voce precisa captar esse tipo de informacao pra
    melhorias". Ele estava certo — ate aqui toda queixa de lentidao virava eu
    lendo codigo e adivinhando. Com numero, "esta lento" vira "o envio esta
    levando 38s desde julho, e antes levava 14".

    Best-effort e barato: aceita lote, guarda so o essencial, e nunca pode
    atrapalhar a extensao. Sem payload de conversa, sem dado de cliente."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    itens = (request.get_json(silent=True) or {}).get('metricas') or []
    if not isinstance(itens, list):
        return _wa_cors(jsonify({"ok": False, "erro": "formato"})), 400
    conn = db()
    n = 0
    try:
        for m in itens[:50]:
            op = str((m or {}).get('operacao') or '').strip()[:40]
            if not op:
                continue
            try:
                ms = int((m or {}).get('ms') or 0)
            except (TypeError, ValueError):
                ms = 0
            conn.execute("""INSERT INTO wa_metrica (operacao, ms, ok, usuario_id, detalhe, criado_em)
                            VALUES (?,?,?,?,?,?)""",
                         (op, max(0, min(ms, 3_600_000)), 1 if (m or {}).get('ok', True) else 0,
                          (m or {}).get('usuario_id'), str((m or {}).get('detalhe') or '')[:120] or None,
                          _agora_sp()))
            n += 1
        conn.commit()
    except Exception as ex:
        try: conn.rollback()
        except Exception: pass
        app.logger.warning(f"[METRICA] {ex}")
    close_db(conn)
    return _wa_cors(jsonify({"ok": True, "gravadas": n}))


@app.route('/api/whatsapp/documentos/tipo', methods=['POST', 'OPTIONS'])
@requer('ia:usar')
def api_whatsapp_documento_tipo():
    """O consultor CONFIRMA ou corrige o tipo do documento.

    A IA propoe, a pessoa decide — mesma regra do resto do sistema. E aqui ela
    vale dobrado: o tipo vira o NOME do arquivo, e o nome e o que faz a pasta
    baixada servir pra subir na operadora sem abrir um por um."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    d = request.get_json(silent=True) or {}
    tipo = (d.get('tipo') or '').strip()
    if tipo not in _DOC_TIPOS:
        return _wa_cors(jsonify({"ok": False, "erro": "tipo inválido"})), 400
    conn = db()
    doc = None
    if d.get('doc_id'):
        doc = conn.execute("SELECT * FROM lead_documento WHERE id=?", (d['doc_id'],)).fetchone()
    elif d.get('hash'):
        doc = conn.execute("SELECT * FROM lead_documento WHERE conteudo_hash=? ORDER BY id DESC LIMIT 1",
                           (d['hash'],)).fetchone()
    if not doc:
        close_db(conn)
        return _wa_cors(jsonify({"ok": False, "erro": "documento não encontrado"})), 404
    pessoa = (d.get('pessoa') or doc['pessoa'] or '').strip()
    titularidade = (d.get('titularidade') or doc['titularidade'] or '').strip() or None
    if titularidade not in (None, 'titular', 'dependente'):
        titularidade = None
    parentesco = (d.get('parentesco') or '').strip() or None
    if parentesco and parentesco not in _DOC_PARENTESCOS:
        parentesco = None
    # Parentesco so faz sentido em dependente. Guardar num documento de titular
    # deixaria a ficha dizendo que o titular e conjuge de si mesmo.
    if titularidade != 'dependente':
        parentesco = None
    ext = _doc_extensao(doc['arquivo'] or doc['nome_arquivo'], doc['mime'])
    nome = _doc_nome_final(tipo, pessoa, ext, titularidade=titularidade, parentesco=parentesco)
    conn.execute("""UPDATE lead_documento SET tipo=?, pessoa=?, nome_final=?, tipo_conferido=1,
                    titularidade=?, parentesco=? WHERE id=?""",
                 (tipo, pessoa or None, nome, titularidade, parentesco, doc['id']))
    conn.commit(); close_db(conn)
    return _wa_cors(jsonify({"ok": True, "nome_final": nome, "tipo": tipo}))


def documentos_do_lead_para_proposta(conn, pid, lead_id, usuario_nome='Sistema'):
    """Leva os documentos do lead pros anexos da venda.

    O cliente mandou o RG no WhatsApp; o consultor cadastrou a venda. Sem isto,
    ele teria que baixar tudo e subir de novo, arquivo por arquivo — o mesmo
    documento, duas vezes, com chance de subir o errado no meio.

    COPIA o arquivo com o nome padronizado em vez de apontar pro mesmo: anexo de
    proposta e prova documental do que foi vendido, e nao pode mudar se alguem
    reclassificar o documento no lead depois. Aqui e melhor duplicar bytes do que
    deixar a prova mudar sozinha.

    Nao duplica: anexo que ja esta na lista fica como esta."""
    if not (pid and lead_id):
        return {'copiados': 0, 'nomes': []}
    docs = conn.execute("""SELECT * FROM lead_documento
                           WHERE lead_id=? AND arquivo IS NOT NULL ORDER BY tipo, id""",
                        (lead_id,)).fetchall()
    if not docs:
        return {'copiados': 0, 'nomes': []}
    prop = conn.execute("SELECT anexos FROM propostas WHERE id=?", (pid,)).fetchone()
    if not prop:
        return {'copiados': 0, 'nomes': []}
    try:
        anexos = json.loads(prop['anexos'] or '[]')
    except Exception:
        anexos = []
    ja = {(x['nome'] if isinstance(x, dict) else x) for x in anexos}
    novos = []
    for d in docs:
        conteudo, _ct = _localizar_anexo(os.path.basename(d['arquivo']))
        if not conteudo:
            continue
        base = d['nome_final'] or os.path.basename(d['arquivo'])
        raiz, _p, ext = base.rpartition('.')
        chave = f"prop-{pid}-{(raiz or base)[:60]}.{ext or 'jpg'}".replace('/', '-')
        if chave in ja:
            continue
        try:
            upload_arquivo_r2(conteudo, chave)
        except Exception as e:
            app.logger.warning(f"[DOC->PROP] não copiei {base}: {e}")
            continue
        anexos.append(chave)
        ja.add(chave)
        novos.append(base)
    if novos:
        conn.execute("UPDATE propostas SET anexos=? WHERE id=?", (json.dumps(anexos), pid))
        conn.execute("""INSERT INTO historico_proposta (proposta_id, usuario_nome, tipo, descricao, criado_em)
                        VALUES (?,?,?,?,?)""",
                     (pid, usuario_nome, 'edicao',
                      f"{len(novos)} documento(s) trazido(s) do lead: " + ', '.join(novos[:6]), _agora_sp()))
    return {'copiados': len(novos), 'nomes': novos}


@app.route('/proposta/<int:pid>/documentos-do-lead', methods=['POST'])
@login_required
def proposta_documentos_do_lead(pid):
    """Traz os documentos do lead pra esta venda. Botao, nao automatico: o
    consultor ve o que veio antes de mandar pra operadora."""
    conn = db()
    p = conn.execute("SELECT id, lead_id FROM propostas WHERE id=?", (pid,)).fetchone()
    if not p:
        close_db(conn); return jsonify({"ok": False, "erro": "Proposta não encontrada"}), 404
    if not p['lead_id']:
        close_db(conn)
        return jsonify({"ok": False, "erro": "Esta venda não tem lead vinculado — sem lead não há documentos"}), 400
    res = documentos_do_lead_para_proposta(conn, pid, p['lead_id'], session.get('nome') or 'Sistema')
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, **res})


@app.route('/lead/documento/tipo', methods=['POST'])
@login_required
def lead_documento_tipo():
    """Corrige o tipo pelo painel. Mesma regra da extensao: a IA propoe, a pessoa
    decide — e o nome do arquivo acompanha, porque e o nome que serve na
    operadora."""
    d = request.json or {}
    conn = db()
    doc = conn.execute("SELECT * FROM lead_documento WHERE id=?", (d.get('doc_id'),)).fetchone()
    if not doc:
        close_db(conn); return jsonify({"ok": False, "erro": "Documento não encontrado"}), 404
    # TIPO AUSENTE E "NAO MEXE", nao "vira outro". Quem resolve de quem e o
    # arquivo pela bandeja nao tem o seletor de tipo na tela — mandar o campo
    # vazio dali apagaria a classificacao que a leitura tinha acertado.
    tipo = (d.get('tipo') or '').strip() or (doc['tipo'] or 'outro')
    if tipo not in _DOC_TIPOS:
        close_db(conn); return jsonify({"ok": False, "erro": "Tipo inválido"}), 400
    # As outras duas perguntas: de quem e o documento e, se for de dependente,
    # qual o parentesco. Parentesco em titular nao existe — zera, senao fica
    # "TITULAR CONJUGE" no nome do arquivo e ninguem entende a pasta.
    titularidade = (d.get('titularidade') or '').strip() or None
    if titularidade not in (None, 'titular', 'dependente'):
        close_db(conn); return jsonify({"ok": False, "erro": "Titularidade inválida"}), 400
    parentesco = (d.get('parentesco') or '').strip() or None
    if titularidade != 'dependente':
        parentesco = None
    elif parentesco and parentesco not in _DOC_PARENTESCOS:
        close_db(conn); return jsonify({"ok": False, "erro": "Parentesco inválido"}), 400
    ext = _doc_extensao(doc['arquivo'] or doc['nome_arquivo'], doc['mime'])
    nome = _doc_nome_final(tipo, doc['pessoa'], ext, titularidade=titularidade,
                           parentesco=parentesco)
    conn.execute("""UPDATE lead_documento SET tipo=?, nome_final=?, tipo_conferido=1,
                    titularidade=?, parentesco=? WHERE id=?""",
                 (tipo, nome, titularidade, parentesco, doc['id']))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "nome_final": nome})


