@app.route('/lead/<int:lid>/documentos.zip')
@login_required
def lead_documentos_zip(lid):
    """Baixa TODOS os documentos do lead numa pasta, ja renomeados.

    E o passo que fecha o ciclo: o consultor sobe no sistema da operadora sem
    abrir arquivo por arquivo pra descobrir o que e cada um. Nome repetido ganha
    numero em vez de sobrescrever — dois RGs de pessoas diferentes na mesma pasta
    e comum, e perder um seria perder documento de cliente."""
    import io as _io, zipfile as _zip
    conn = db()
    lead = conn.execute("SELECT id, nome FROM crm_leads WHERE id=?", (lid,)).fetchone()
    if not lead:
        close_db(conn); abort(404)
    docs = conn.execute("""SELECT * FROM lead_documento WHERE lead_id=? AND arquivo IS NOT NULL
                           ORDER BY tipo, id""", (lid,)).fetchall()
    close_db(conn)
    if not docs:
        abort(404)
    buf = _io.BytesIO()
    usados = {}
    with _zip.ZipFile(buf, 'w', _zip.ZIP_DEFLATED) as z:
        for d in docs:
            conteudo, _ctype = _localizar_anexo(os.path.basename(d['arquivo']))
            if not conteudo:
                continue
            nome = d['nome_final'] or os.path.basename(d['arquivo'])
            usados[nome] = usados.get(nome, 0) + 1
            if usados[nome] > 1:
                raiz, ext = nome.rsplit('.', 1) if '.' in nome else (nome, 'jpg')
                nome = f"{raiz} ({usados[nome]}).{ext}"
            z.writestr(nome, conteudo)
    buf.seek(0)
    limpo = re.sub(r'[^A-Za-z0-9 ]+', '', (lead['nome'] or f'lead-{lid}')).strip()[:50]
    return send_file(buf, mimetype='application/zip', as_attachment=True,
                     download_name=f"documentos - {limpo}.zip")


@app.route('/lead/<int:lid>/documento/<int:did>')
@login_required
def lead_documento_baixar(lid, did):
    """Um documento, com o nome padronizado."""
    conn = db()
    d = conn.execute("SELECT * FROM lead_documento WHERE id=? AND lead_id=?", (did, lid)).fetchone()
    close_db(conn)
    if not d or not d['arquivo']:
        abort(404)
    conteudo, ctype = _localizar_anexo(os.path.basename(d['arquivo']))
    if not conteudo:
        abort(404)
    import io as _io
    # ?ver=1 mostra na tela em vez de baixar. Conferir se o arquivo e mesmo o que
    # a IA disse nao pode custar um download, uma pasta cheia e um arquivo aberto
    # a mais — e a conferencia que faz o consultor confiar no resto.
    inline = request.args.get('ver') == '1'
    return send_file(_io.BytesIO(conteudo), mimetype=ctype or d['mime'] or 'application/octet-stream',
                     as_attachment=not inline,
                     download_name=d['nome_final'] or os.path.basename(d['arquivo']))


@app.route('/api/whatsapp/documentos/ler', methods=['POST', 'OPTIONS'])
@requer('ia:usar')
def api_whatsapp_documentos_ler():
    """A extensao manda os documentos da conversa; o JOB le e preenche o lead.

    Roda no SERVIDOR de proposito: a chave da IA nunca vai pro navegador do
    consultor, o custo fica medido num lugar so, e o cache por conteudo evita
    pagar duas vezes pelo mesmo RG que o cliente reenviou."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    d = request.get_json(silent=True) or {}
    arquivos = d.get('arquivos') or []
    if not isinstance(arquivos, list) or not arquivos:
        return _wa_cors(jsonify({"ok": False, "erro": "Nenhum documento recebido"})), 400
    # Teto de payload: 12 arquivos por chamada. Quem soltar a pasta errada nao
    # gera uma conta surpresa num clique.
    arquivos = arquivos[:12]
    conn = db()
    lead_id = None
    try:
        lead_id = int(d.get('lead_id') or 0) or None
    except (TypeError, ValueError):
        lead_id = None
    if not lead_id:
        tel = _normalizar_telefone(d.get('telefone') or '')
        if tel:
            lead = _buscar_lead_por_telefone(conn, tel)
            lead_id = lead['id'] if lead else None

    # JA LIDO NAO SE PAGA DE NOVO — mas TEM QUE VOLTAR PRA TELA.
    #
    # Antes o arquivo ja lido era simplesmente pulado e a resposta saia sem a
    # lista de arquivos. A extensao lia essa lista vazia e pintava "OUTRO" e
    # "nada novo pro lead" — uma classificacao que o modelo nunca deu. O
    # consultor via um erro que nao existia, e como nao vinha doc_id, sumiam
    # junto os tres seletores. Agora o que ja foi lido volta do banco com o que
    # esta gravado.
    import hashlib as _h
    reler = bool(d.get('reler'))
    novos, prontos = [], []
    for i, a in enumerate(arquivos, start=1):
        b64 = (a.get('base64') or '').strip()
        if not b64:
            continue
        h = _h.sha256(b64.encode('ascii', 'ignore')).hexdigest()
        antigo = conn.execute(
            "SELECT * FROM lead_documento WHERE lead_id=? AND conteudo_hash=?",
            (lead_id, h)).fetchone() if lead_id else None
        if antigo is not None and not reler:
            prontos.append({
                'indice': i, 'nome': a.get('nome') or '', 'ja_lido': True,
                'tipo': antigo['tipo'] or 'outro', 'pessoa': antigo['pessoa'] or '',
                'certeza': antigo['certeza'] or 'baixa', 'doc_id': antigo['id'],
                'nome_final': antigo['nome_final'], 'titularidade': antigo['titularidade'],
                'parentesco': antigo['parentesco'],
            })
            continue
        novos.append((i, a))

    leitura, erro = ({}, None)
    if novos:
        leitura, erro = ler_documentos_cliente([x[1] for x in novos])
        if erro or not leitura:
            close_db(conn)
            return _wa_cors(jsonify({"ok": False, "erro": erro or "não consegui ler"})), 200
        # O modelo numera 1..N sobre os NOVOS; a tela numera sobre o que foi
        # enviado. Sem esta traducao, ler 1 arquivo novo junto de 2 ja lidos
        # entregava o resultado na bolha errada.
        for x in (leitura.get('arquivos') or []):
            k = x.get('indice') or 0
            if 0 < k <= len(novos):
                x['indice'] = novos[k - 1][0]
    res = {}
    try:
        # A funcao numera de 1 a N sobre a lista que recebe; a leitura ja foi
        # renumerada pro indice da tela. Reindexo de volta so pra ela.
        _lt = dict(leitura)
        _lt['arquivos'] = [dict(x, indice=k + 1) for k, x in enumerate(
            sorted((leitura.get('arquivos') or []),
                   key=lambda y: [n[0] for n in novos].index(y['indice'])
                   if y.get('indice') in [n[0] for n in novos] else 999))]
        res = documentos_para_o_lead(conn, lead_id, _lt, [x[1] for x in novos])
        conn.commit()
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        app.logger.warning(f"[DOC] gravação: {e}")
    close_db(conn)
    # Devolve o id de cada documento guardado, pra extensao poder corrigir o tipo
    # sem precisar procurar depois.
    try:
        conn2 = db()
        import hashlib as _h2
        _por_indice = {n[0]: n[1] for n in novos}
        for a_ in (leitura.get('arquivos') or []):
            arq = _por_indice.get(a_.get('indice'))
            if not arq:
                continue
            h2 = _h2.sha256((arq.get('base64') or '').encode('ascii', 'ignore')).hexdigest()
            r2 = conn2.execute("SELECT id, nome_final, titularidade FROM lead_documento "
                               "WHERE conteudo_hash=? ORDER BY id DESC LIMIT 1", (h2,)).fetchone()
            if r2:
                a_['doc_id'] = r2['id']
                a_['nome_final'] = r2['nome_final']
                a_['titularidade'] = r2['titularidade']
        close_db(conn2)
    except Exception as e:
        app.logger.info(f"[DOC] ids: {e}")
    return _wa_cors(jsonify({
        "ok": True, "lead_id": lead_id, "lidos": len(novos), "ja_lidos": len(prontos),
        "tipos": _DOC_TIPOS, "rotulos": _DOC_ROTULO,
        "parentescos": _DOC_PARENTESCOS, "parentesco_rotulos": _DOC_PARENTESCO_ROTULO,
        "parentesco_comprova": _DOC_PARENTESCO_COMPROVA,
        "arquivos": sorted((leitura.get('arquivos') or []) + prontos,
                           key=lambda x: x.get('indice') or 0),
        "pessoas": leitura.get('pessoas') or [],
        "empresa": leitura.get('empresa') or {},
        "endereco": leitura.get('endereco') or {},
        "observacoes": leitura.get('observacoes') or [],
        "campos_preenchidos": res.get('campos') or [],
        "custo_usd": leitura.get('custo_usd') or 0,
    }))



# ── CANARIO DA EXTENSAO ────────────────────────────────────────────────────────
# A extensao roda DENTRO do WhatsApp, que muda sem avisar ninguem. Quando muda,
# o sintoma chega distorcido ("o JOB parou", "o WhatsApp travou") e dias depois.
# Cada capacidade e testada isolada, de proposito: saber QUAL peca caiu e a
# diferenca entre trocar uma linha e reescrever a ponte.
# Frase curta que funciona nos dois lugares: na tabela do painel e na frase
# "<isto> parou" do alerta. Sem jargao: quem le e quem vende, nao quem programa.
_CANARIO_ROTULO = {
    'wa_js':        'A ponte com o WhatsApp',
    'conta':        'A identificação da conta logada',
    'conversa':     'A leitura da conversa aberta',
    'mensagens':    'A leitura das mensagens',
    'achar_msg':    'A busca de mensagem por id (o caminho do @lid)',
    'midia':        'O acesso à mídia guardada (áudio, foto, PDF)',
    'baixar':       'O download de midia',
    'enviar':       'O envio de mensagem',
    'dom_linhas':   'O reconhecimento das mensagens na tela',
    'dom_arquivo':  'O bloco de ler documento nas bolhas de arquivo',
    'dom_audio':    'O bloco de transcrever nas bolhas de áudio',
    # AS TRES ABAIXO SAO O JUIZ INDEPENDENTE, e existem por causa de um furo
    # real: as duas de cima perguntam "esta linha e documento?" usando a MESMA
    # funcao que desenha o botao. Quando o WhatsApp mudou a pintura da
    # miniatura de PDF e o detector parou de reconhecer a bolha, elas contaram
    # ZERO documentos, chamaram de "ausencia de amostra" e disseram que estava
    # tudo bem — enquanto o consultor abria a conversa e nao via botao nenhum.
    #
    # Estas comparam com a wa-js, que sabe o TIPO de cada mensagem sem depender
    # de seletor de tela. Se ela ve tres documentos e a extensao desenhou zero,
    # sai vermelho aqui em vez de ninguem ficar sabendo.
    'contrato_documento': 'Documento visto pela wa-js x bloco desenhado na tela',
    'contrato_audio':     'Áudio visto pela wa-js x bloco desenhado na tela',
    'contrato_tela':      'A conferência entre a wa-js e a tela',
}
# Capacidade que, caindo, faz MENSAGEM NAO SAIR. Falha barulhenta e chata;
# falha silenciosa custa lead. Estas viram notificacao na hora.
# `contrato_*` nao entram aqui: elas nao impedem mensagem de sair — mas sao o
# unico aviso de que um botao sumiu da tela sem erro nenhum no console.
_CANARIO_CRITICAS = {'wa_js', 'enviar', 'conversa', 'achar_msg'}


def _canario_ha(quando):
    """'ha 3 dias' diz mais que uma data. E o tempo desde a virada que amarra a
    quebra a uma atualizacao do WhatsApp."""
    dt = _parse_dt_seguro(quando)
    if not dt:
        return ''
    try:
        agora = datetime.now(TZ_SP)
        # O banco guarda hora de SP sem fuso; o parse pode devolver ingenuo.
        seg = (agora.replace(tzinfo=None) - dt.replace(tzinfo=None)).total_seconds()
    except Exception:
        return ''
    if seg < 0:
        return 'agora'
    if seg < 3600:
        return f'há {int(seg // 60)} min'
    if seg < 86400:
        return f'há {int(seg // 3600)} h'
    d = int(seg // 86400)
    return f'há {d} dia' + ('s' if d > 1 else '')


def _canario_estado(conn):
    """Ultimo resultado de cada capacidade, e desde quando esta assim.

    'Desde quando' e o dado que importa: e ele que amarra a quebra a uma
    atualizacao do WhatsApp, em vez de deixar todo mundo adivinhando."""
    linhas = []
    for cap in _CANARIO_ROTULO:
        ult = conn.execute("""SELECT ok, detalhe, versao, criado_em FROM wa_canario
                              WHERE capacidade=? ORDER BY id DESC LIMIT 1""", (cap,)).fetchone()
        if not ult:
            linhas.append({'cap': cap, 'rotulo': _CANARIO_ROTULO[cap], 'estado': 'sem dado',
                           'ok': None, 'desde': None, 'detalhe': None,
                           'critica': cap in _CANARIO_CRITICAS})
            continue
        # Ha quanto tempo esta neste estado: a primeira leitura, subindo, que
        # ainda concorda com a de agora.
        desde = ult['criado_em']
        for r in conn.execute("""SELECT ok, criado_em FROM wa_canario WHERE capacidade=?
                                 ORDER BY id DESC LIMIT 200""", (cap,)).fetchall():
            if int(r['ok'] or 0) != int(ult['ok'] or 0):
                break
            desde = r['criado_em']
        linhas.append({'cap': cap, 'rotulo': _CANARIO_ROTULO[cap],
                       'ok': bool(ult['ok']), 'estado': 'funciona' if ult['ok'] else 'quebrou',
                       'desde': _fmt_datahora_br(desde) if desde else None,
                       'ha': _canario_ha(desde),
                       'detalhe': ult['detalhe'], 'versao': ult['versao'],
                       'critica': cap in _CANARIO_CRITICAS})
    linhas.sort(key=lambda x: (x['ok'] is not False, not x['critica']))
    # A ULTIMA NOTICIA vale por um item de lista. Se a extensao parar de falar,
    # todas as linhas continuam verdes eternamente — e verde velho engana mais
    # que vermelho. Sem canario chegando, nao se sabe nada.
    ult = conn.execute("SELECT MAX(criado_em) AS q FROM wa_canario").fetchone()
    return {'linhas': linhas,
            'ultima': _fmt_datahora_br(ult['q']) if ult and ult['q'] else None,
            'ha': _canario_ha(ult['q']) if ult and ult['q'] else None,
            'quebradas': sum(1 for x in linhas if x['ok'] is False),
            'criticas_quebradas': sum(1 for x in linhas if x['ok'] is False and x['critica'])}


@app.route('/api/whatsapp/canario', methods=['POST', 'OPTIONS'])
@requer('whatsapp:enviar')
def api_whatsapp_canario():
    """A extensao conta o que ainda funciona nela. Ninguem pergunta, ela avisa.

    Nao envia mensagem, nao baixa midia, nao mexe em nada: so verifica que as
    pecas existem e respondem. Rodar isto nao pode custar nada, senao vira mais
    um motivo de o WhatsApp ficar lento."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    d = request.get_json(silent=True) or {}
    checagens = d.get('checagens') or []
    if not isinstance(checagens, list):
        return _wa_cors(jsonify({"ok": False, "erro": "formato"})), 400
    versao = str(d.get('versao') or '')[:20]
    uid = d.get('usuario_id')
    conn = db()
    quebrou_agora = []
    try:
        for c in checagens[:40]:
            cap = str((c or {}).get('cap') or '').strip()[:24]
            if cap not in _CANARIO_ROTULO:
                continue
            ok = 1 if (c or {}).get('ok') else 0
            try:
                ms = max(0, min(int((c or {}).get('ms') or 0), 600000))
            except (TypeError, ValueError):
                ms = 0
            ant = conn.execute("""SELECT ok FROM wa_canario WHERE capacidade=?
                                  ORDER BY id DESC LIMIT 1""", (cap,)).fetchone()
            conn.execute("""INSERT INTO wa_canario
                            (capacidade, ok, detalhe, ms, versao, usuario_id, criado_em)
                            VALUES (?,?,?,?,?,?,?)""",
                         (cap, ok, str((c or {}).get('detalhe') or '')[:200] or None,
                          ms, versao, uid, _agora_sp()))
            # SO A VIRADA notifica. Repetir o aviso a cada rodada treina todo
            # mundo a ignorar o sino, e ai o proximo aviso de verdade se perde.
            if not ok and ant is not None and int(ant['ok'] or 0) == 1:
                quebrou_agora.append(cap)
        conn.commit()
    except Exception as ex:
        try: conn.rollback()
        except Exception: pass
        close_db(conn)
        app.logger.warning(f"[CANARIO] {ex}")
        return _wa_cors(jsonify({"ok": False})), 200
    close_db(conn)
    for cap in quebrou_agora:
        grave = cap in _CANARIO_CRITICAS
        _notificar_admins(
            'alerta' if grave else 'aviso',
            ('WhatsApp mudou: ' if grave else 'Extensao: ') + _CANARIO_ROTULO[cap] + ' parou',
            ('Isto derruba envio e leitura de conversa. ' if grave else '')
            + 'Detectado pelo canário da extensão ' + (versao or 's/versao') + '.',
            '/configuracoes')
    return _wa_cors(jsonify({"ok": True, "gravadas": len(checagens), "quebrou": quebrou_agora}))


def _ignorar_conversa_wa(conn, chat_id, tel_norm, desmarcar, nome, motivo, quem):
    if desmarcar:
        conn.execute("DELETE FROM wa_conversa_ignorada WHERE chat_id=? OR (telefone_norm IS NOT NULL "
                     "AND telefone_norm <> '' AND telefone_norm=?)",
                     (chat_id or '__nada__', tel_norm or '__nada__'))
    else:
        chave = chat_id or ('tel:' + tel_norm)
        if DB_MODE == 'postgres':
            conn.execute("""INSERT INTO wa_conversa_ignorada
                (chat_id, telefone_norm, nome, motivo, criado_por, criado_em)
                VALUES (?,?,?,?,?,?) ON CONFLICT (chat_id) DO UPDATE SET
                telefone_norm=excluded.telefone_norm, nome=excluded.nome""",
                (chave, tel_norm or None, str(nome or '')[:120],
                 str(motivo or '')[:200], quem, _agora_sp()))
        else:
            conn.execute("""INSERT OR REPLACE INTO wa_conversa_ignorada
                (chat_id, telefone_norm, nome, motivo, criado_por, criado_em)
                VALUES (?,?,?,?,?,?)""",
                (chave, tel_norm or None, str(nome or '')[:120],
                 str(motivo or '')[:200], quem, _agora_sp()))


@app.route('/api/whatsapp/ignorar', methods=['POST', 'OPTIONS'])
@requer('crm:escrever')
def api_whatsapp_ignorar():
    """Marca (ou desmarca) uma conversa como "não é lead"."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    d = request.get_json(silent=True) or {}
    chat_id = str(d.get('chat_id') or '').strip()[:120]
    tel_norm = _normalizar_telefone(str(d.get('telefone') or ''))
    if not chat_id and not tel_norm:
        return _wa_cors(jsonify({"ok": False, "erro": "Sem conversa"})), 400
    desmarcar = bool(d.get('desmarcar'))
    conn = db()
    try:
        quem = ''
        try:
            u = conn.execute("SELECT nome FROM usuarios WHERE id=?",
                             (int(d.get('usuario_id') or 0),)).fetchone()
            quem = (u['nome'] if u else '') or ''
        except Exception:
            pass
        _ignorar_conversa_wa(conn, chat_id, tel_norm, desmarcar, d.get('nome'), d.get('motivo'), quem)
        conn.commit()
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        close_db(conn)
        app.logger.warning(f"[IGNORAR] {e}")
        return _wa_cors(jsonify({"ok": False, "erro": "não consegui gravar"})), 500
    close_db(conn)
    return _wa_cors(jsonify({"ok": True, "ignorada": not desmarcar}))


@app.route('/api/whatsapp/chats/vincular', methods=['POST', 'OPTIONS'])
@requer('whatsapp:enviar')
def api_whatsapp_chats_vincular():
    """Amarra @lid -> lead em MASSA, a partir da lista inteira de conversas.

    O @lid so aparecia nos cards que a extensao ja tinha tocado — uma minoria dos
    5.502 leads, porque o vinculo nascia conversa a conversa. Isto e a varredura
    unica que resolve o passivo: a extensao manda todas as conversas com telefone
    resolvido e o servidor casa cada uma com o lead pelo mesmo casador do resto do
    sistema.

    Nao cria lead nenhum e nao mexe em dado de lead: so registra a identidade da
    conversa. Rodar duas vezes nao muda nada."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    d = request.get_json(silent=True) or {}
    convs = d.get('conversas') or []
    if not isinstance(convs, list):
        return _wa_cors(jsonify({"ok": False, "erro": "Formato inválido"})), 400
    convs = convs[:500]
    conn = db()
    ligados = sem_lead = 0
    try:
        for c in convs:
            cid = str((c or {}).get('chat_id') or '')
            tel = str((c or {}).get('telefone') or '')
            # lead_id EXPLICITO tem prioridade sobre o casamento por telefone.
            # E o caso do consultor que esta com a conversa aberta e diz "esta
            # conversa e deste lead" — ele sabe melhor que qualquer heuristica,
            # e em conversa @lid o telefone as vezes nem existe pra casar.
            try:
                lid_ex = int((c or {}).get('lead_id') or 0) or None
            except (TypeError, ValueError):
                lid_ex = None
            if not cid or not (tel or lid_ex):
                continue
            if registrar_chat_lead(conn, cid, tel, (c or {}).get('nome') or None, lead_id=lid_ex):
                ligados += 1
            else:
                sem_lead += 1
        conn.commit()
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        app.logger.warning(f"[VINCULAR_CHATS] {e}")
    close_db(conn)
    return _wa_cors(jsonify({"ok": True, "recebidos": len(convs),
                             "ligados": ligados, "sem_lead": sem_lead}))


@app.route('/crm/varredura/criar', methods=['POST'])
@login_required
def crm_varredura_criar():
    """Monta a fila a partir dos LEADS QUE ESTÃO NA TELA — os mesmos filtros.

    O consultor já filtrou o que quer olhar; pedir de novo em outra tela seria
    fazer o trabalho duas vezes e abrir espaço pra divergir. Reusa
    `_crm_montar_query`, que é o WHERE do próprio kanban."""
    fl = _crm_ler_filtros_url()
    conn = db()
    uid = session['user_id']
    eh_admin = session.get('perfil') == 'admin'
    leads = conn.execute(*_crm_montar_query(
        uid, eh_admin, fl['etapa'], fl['consultor'], fl['origem'], fl['data_de'], fl['data_ate'],
        fl['busca'], fl['externo'], fl['sub_status'], fl['etiqueta'], fl['sem_resp'], fl['sem_cont'],
        fl['parados'], fl['nao_frio'], fl['abertos'])).fetchall()

    # Só entra lead COM conversa vinculada — sem ela não há o que ler. E fora os
    # marcados como "não é lead".
    vinc = {}
    ids = [l['id'] for l in leads]
    if ids:
        marc = ','.join(['?'] * len(ids))
        try:
            for r in conn.execute(f"""SELECT w.lead_id, w.chat_id FROM wa_chat_lead w
                WHERE w.lead_id IN ({marc})
                  AND NOT EXISTS (SELECT 1 FROM wa_conversa_ignorada i WHERE i.chat_id = w.chat_id)""",
                ids).fetchall():
                vinc.setdefault(r['lead_id'], r['chat_id'])
        except Exception as e:
            app.logger.warning(f"[VARREDURA_LOTE] vinculos: {e}")

    alvos = [(l['id'], l['nome'] or '', vinc[l['id']]) for l in leads if l['id'] in vinc]
    # QUEM FICOU DE FORA, NÃO SÓ QUANTOS. Antes o "43 de fora" morria no alerta:
    # fechou a janela, ninguém mais sabia QUAIS. E "de fora" não é erro só —
    # normalmente é lead sem conversa vinculada ainda, que "Sincronizar @lid"
    # resolve. Guardando cada um como item do lote, a lista fica visível e
    # revisável na mesma tela dos que leram — inclusive depois de ajustar.
    excluidos = [l for l in leads if l['id'] not in vinc]
    fora = len(excluidos)
    if not alvos:
        close_db(conn)
        return jsonify({"ok": False, "erro": "Nenhum dos leads filtrados tem conversa vinculada. "
                        "Rode 'Sincronizar @lid' na extensão primeiro.", "sem_conversa": fora}), 400

    # De quem é a fila: a extensão de CADA consultor pede os itens dela. Com
    # filtro de consultor, é ele; senão, é quem está criando.
    try:
        alvo_uid = int(fl['consultor']) if (fl['consultor'] or '').isdigit() else uid
    except (TypeError, ValueError):
        alvo_uid = uid

    desc = 'todos os filtros da tela' if not any(
        [fl['etapa'], fl['data_de'], fl['data_ate'], fl['busca'], fl['origem'], fl['etiqueta']]) else ' · '.join(
        x for x in [('etapa ' + fl['etapa']) if fl['etapa'] else '',
                    ('de ' + fl['data_de']) if fl['data_de'] else '',
                    ('até ' + fl['data_ate']) if fl['data_ate'] else '',
                    ('busca "' + fl['busca'] + '"') if fl['busca'] else '',
                    ('origem ' + fl['origem']) if fl['origem'] else ''] if x)

    # UMA VARREDURA POR CONSULTOR DE CADA VEZ.
    #
    # Duas rodando disputam a MESMA fila: a extensao pede "o proximo item" e o
    # servidor entrega pela ordem de id, entao a segunda so comeca a andar
    # quando a primeira acabar — mas as duas aparecem 'rodando' e o consultor
    # fica olhando um lote parado sem entender. Pior: da pra empilhar 353 leads
    # em cima de 26 sem perceber, e o gasto vira surpresa.
    ja = conn.execute("""SELECT id, total FROM varredura_lote
                          WHERE consultor_id=? AND status='rodando'
                            AND EXISTS (SELECT 1 FROM varredura_item i
                                        WHERE i.lote_id=varredura_lote.id AND i.status='pendente')
                          ORDER BY id LIMIT 1""", (alvo_uid,)).fetchone()
    if ja:
        close_db(conn)
        return jsonify({"ok": False, "em_andamento": ja['id'],
                        "erro": f"Já existe a varredura #{ja['id']} rodando pra este consultor. "
                                "Espere terminar ou pare ela antes de começar outra."}), 409

    cur = conn.execute("""INSERT INTO varredura_lote
        (consultor_id, criado_por, filtro_txt, total, status, criado_em)
        VALUES (?,?,?,?,?,?)""",
        (alvo_uid, session.get('nome') or '', desc[:300], len(alvos), 'rodando', _agora_sp()))
    lote_id = _last_insert_id(cur)
    if lote_id is None:
        lote_id = conn.execute("SELECT id FROM varredura_lote ORDER BY id DESC LIMIT 1").fetchone()['id']
    for lid, nome, cid in alvos:
        conn.execute("""INSERT INTO varredura_item (lote_id, lead_id, chat_id, lead_nome, status, atualizado_em)
                        VALUES (?,?,?,?,?,?)""", (lote_id, lid, cid, nome[:120], 'pendente', _agora_sp()))
    for l in excluidos:
        conn.execute("""INSERT INTO varredura_item (lote_id, lead_id, chat_id, lead_nome, status, erro, atualizado_em)
                        VALUES (?,?,?,?,?,?,?)""",
                     (lote_id, l['id'], None, (l['nome'] or '')[:120], 'sem_conversa',
                      'não tinha conversa vinculada (@lid) na hora que a varredura foi criada', _agora_sp()))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "lote_id": lote_id, "total": len(alvos), "sem_conversa": fora})


@app.route('/api/whatsapp/varredura/proximo', methods=['GET', 'OPTIONS'])
@requer('whatsapp:ler')
def api_whatsapp_varredura_proximo():
    """UM item por vez. É o que mantém a máquina do consultor livre.

    A extensão pergunta, lê uma conversa, devolve o resultado e pergunta de
    novo. Nada de laço segurando a aba; se ela fechar, o lote fica esperando e
    continua quando o WhatsApp abrir. O ritmo (espera_seg) também vem daqui —
    quem decide o compasso é o servidor, não a paciência de quem está na tela."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    try:
        uid = int(request.args.get('consultor_id') or 0) or None
    except (TypeError, ValueError):
        uid = None
    if not uid:
        return _wa_cors(jsonify({"ok": True, "item": None}))

    # EXTENSAO VELHA NAO CONSOME A FILA.
    #
    # Ate a 3.15.0 a leitura pegava UMA mensagem por conversa fechada e gravava
    # a analise sem dono — 29 leituras pagas e inuteis. Se uma aba ficou com a
    # versao antiga, ela torraria a fila de novo em silencio, e o estrago so
    # apareceria depois. O servidor recusa e diz o que fazer; a fila espera.
    # Comparador de versao e um so: _versao_ge, junto da politica EXT_VERSAO.
    # 3.22.0: as versoes 3.20 e 3.21 tem um defeito MEU — eu pus openChatBottom
    # na leitura achando que ele carregava a conversa sem mexer na tela, e ele
    # NAVEGA (abrirChat usa exatamente esse metodo pra abrir conversa). Numa
    # varredura isso faz a tela do consultor pular de conversa em conversa.
    # 3.22 reverte. Abaixo disso a fila nao anda: e melhor a varredura parar e
    # dizer o motivo do que rodar mexendo na tela de quem esta trabalhando.
    # O MINIMO VEM DA POLITICA, nao de um numero solto aqui.
    # Antes este literal era a unica fonte da verdade que de fato bloqueava,
    # enquanto EXT_VERSAO['bloqueia_abaixo'] existia so pra documentar — mexer
    # na politica nao mudava nada, e os dois ja tinham comecado a divergir do
    # comentario que os explicava.
    _MIN_VARREDURA = EXT_VERSAO['bloqueia_abaixo']
    versao = (request.args.get('versao') or '').strip()
    if not _versao_ge(versao, _MIN_VARREDURA):
        # BLOQUEIO TEM QUE DEIXAR RASTRO. Antes isto devolvia 200 com item:null
        # e a extensao descartava 'bloqueado' e 'motivo', voltando a perguntar
        # a cada 2 min pra sempre: o consultor via 'sem fila', o admin nao via
        # nada, e a fila ficava parada sem explicacao. Agora o motivo fica
        # gravado na pessoa e vira pendencia no sino.
        try:
            conn_b = db()
            conn_b.execute("""UPDATE usuarios SET varr_visto_em=?, varr_versao=?,
                              varr_pode=0, varr_motivo='versao_bloqueada' WHERE id=?""",
                           (_agora_sp(), versao[:20], uid))
            conn_b.commit()
            _pendencias_reconciliar(conn_b)
            close_db(conn_b)
        except Exception as e:
            app.logger.warning(f'[VARREDURA] bloqueio por versao {versao} (uid {uid}): {e}')
        return _wa_cors(jsonify({
            "ok": True, "item": None, "bloqueado": True,
            "motivo": f"Extensão {versao or 'antiga'} — a varredura exige {_MIN_VARREDURA}. "
                      "Recarregue em chrome://extensions e dê F5 no WhatsApp."}))

    conn = db()
    # A MARCA D'ÁGUA TEM QUE VIAJAR JUNTO. Sem ela, TODO lead deste caminho —
    # mesmo o que já foi lido ontem — pedia a conversa inteira de novo (até 400
    # mensagens) pro WhatsApp Web guardar na memória pra sempre (é assim que a
    # própria wa-js se comporta: o que carrega, fica). Multiplicado por uma
    # fila de 76 leads, é exatamente o tipo de acúmulo que derruba a aba por
    # falta de memória — mais provável que concorrência entre rotinas.
    # ITEM PRESO EM 'lendo' VOLTA PRA FILA.
    #
    # A extensão marca 'lendo' ao pegar e só reporta no fim. Se a aba morrer
    # nesse meio — crash de memória, F5 do consultor, ou o recarregamento
    # estratégico que a própria extensão faz pra liberar RAM — o item ficava
    # 'lendo' PARA SEMPRE: some da fila (a busca só pega 'pendente'), o lote
    # nunca fecha, e aquele lead simplesmente não é lido, sem erro nenhum.
    #
    # A fila de ENVIO já tinha essa rede desde sempre (_WA_FILA_RECLAIM_MINUTOS);
    # a de varredura não. Mesmo teto: 10 min é folga de sobra pra uma leitura,
    # que leva segundos, e curto o bastante pra não segurar a fila.
    try:
        _corte = (datetime.now(TZ_SP) - timedelta(minutes=10)).strftime('%Y-%m-%d %H:%M:%S')
        _voltaram = conn.execute("""UPDATE varredura_item SET status='pendente'
            WHERE status='lendo' AND COALESCE(atualizado_em,'') < ?
              AND lote_id IN (SELECT id FROM varredura_lote
                              WHERE consultor_id=? AND status='rodando')""",
            (_corte, uid))
        conn.commit()
        _n = getattr(_voltaram, 'rowcount', 0) or 0
        if _n:
            app.logger.info(f"[VARREDURA_LOTE] {_n} item(ns) presos em 'lendo' voltaram pra fila")
    except Exception as e:
        app.logger.info(f"[VARREDURA_LOTE] reclaim: {e}")
        try: conn.rollback()
        except Exception: pass

    r = conn.execute("""SELECT i.id, i.lead_id, i.chat_id, i.lead_nome, i.lote_id,
                                e.ultima_msg_id
        FROM varredura_item i JOIN varredura_lote t ON t.id = i.lote_id
        LEFT JOIN wa_conversa_estado e ON e.chat_id = i.chat_id
        WHERE t.consultor_id=? AND t.status='rodando' AND i.status='pendente'
        ORDER BY COALESCE(t.prioridade,0) DESC, i.id LIMIT 1""", (uid,)).fetchone()
    if not r:
        # Fecha os lotes que acabaram — sem isso ficam 'rodando' pra sempre e o
        # painel mente sobre o que ainda está em pé.
        try:
            conn.execute("""UPDATE varredura_lote SET status='concluido', terminado_em=?
                WHERE consultor_id=? AND status='rodando'
                  AND NOT EXISTS (SELECT 1 FROM varredura_item i
                                  WHERE i.lote_id = varredura_lote.id AND i.status='pendente')""",
                (_agora_sp(), uid))
            conn.commit()
        except Exception as e:
            app.logger.info(f"[VARREDURA_LOTE] fechar: {e}")
        close_db(conn)
        return _wa_cors(jsonify({"ok": True, "item": None}))
    conn.execute("UPDATE varredura_item SET status='lendo', atualizado_em=? WHERE id=?",
                 (_agora_sp(), r['id']))
    falta = conn.execute("""SELECT COUNT(*) c FROM varredura_item
                            WHERE lote_id=? AND status='pendente'""", (r['lote_id'],)).fetchone()['c']
    conn.commit(); close_db(conn)
    return _wa_cors(jsonify({"ok": True, "item": {
        "item_id": r['id'], "lote_id": r['lote_id'], "lead_id": r['lead_id'],
        "chat_id": r['chat_id'], "nome": r['lead_nome'] or '',
        "desde_msg_id": r['ultima_msg_id'] or None},
        "faltam": falta,
        # 25s entre conversas. Ler dezenas em rajada dentro do WhatsApp é
        # padrão de robô — e número derrubado custa muito mais que uma varredura
        # lenta. Roda em segundo plano; ninguém está esperando na frente da tela.
        "espera_seg": 25}))


@app.route('/api/whatsapp/varredura/item', methods=['POST', 'OPTIONS'])
@requer('whatsapp:enviar')
def api_whatsapp_varredura_item():
    """O resultado de UM item — inclusive o erro, com o motivo por escrito.

    'Deu erro em alguns' não serve pra ninguém: o que resolve é saber em QUAL
    lead e POR QUÊ, pra decidir se é conversa apagada, telefone trocado ou peça
    quebrada."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    d = request.get_json(silent=True) or {}
    try:
        item_id = int(d.get('item_id') or 0)
    except (TypeError, ValueError):
        item_id = 0
    if not item_id:
        return _wa_cors(jsonify({"ok": False, "erro": "sem item"})), 400
    ok = bool(d.get('ok'))
    erro = str(d.get('erro') or '')[:200]
    # CONVERSA VAZIA NÃO É ERRO — é notícia. Quer dizer que existe lead no CRM e
    # NENHUMA mensagem trocada com ele: ninguém chamou essa pessoa. Misturar
    # isso com falha técnica esconde as duas coisas: quem olha a lista vermelha
    # procurando defeito acha lead não abordado, e desiste de olhar.
    # Aqui vira estado próprio, e a tela transforma em fila de trabalho.
    # TIMEOUT NAO E FALHA, E "TENTE DE NOVO" — e era exatamente o que a tela
    # dizia, enquanto o sistema tratava como definitivo e nunca mais lia aquele
    # lead. Soluco de rede, deploy do Railway reiniciando, analise longa demais:
    # nada disso e motivo pra descartar a pessoa. Volta pra fila.
    #
    # COM TETO. Sem contador, um lead que sempre estoura o tempo giraria pra
    # sempre, segurando a fila atras dele e gastando a cada volta.
    # 'falha_mensagens' entrou na lista em 04/08: é o caso da conversa @lid
    # nunca aberta na sessão do WhatsApp Web — a extensão agora tenta
    # pré-carregar sozinha (openChatBottom) antes de desistir, mas esse
    # carregamento é assíncrono e pode não estar pronto na primeira tentativa.
    # Tratar como passageiro dá o tempo de que precisa, sem exigir que alguém
    # abra a conversa na mão.
    _passageiro = any(x in erro.lower() for x in (
        'demorou mais que', 'não respondeu', 'nao respondeu', 'failed to fetch',
        'timeout', 'networkerror', 'load failed', 'aborted', 'falha_mensagens'))
    MAX_TENTATIVAS = 3
    conn = db()
    _t = 0
    try:
        r0 = conn.execute("SELECT COALESCE(tentativas,0) t FROM varredura_item WHERE id=?",
                          (item_id,)).fetchone()
        _t = (r0['t'] if r0 else 0) or 0
    except Exception:
        _t = 0
    if ok:
        estado = 'lido'
    elif 'vazia' in erro.lower():
        estado = 'vazia'
        erro = 'Você nunca trocou mensagem com esta pessoa.'
    elif _passageiro and _t + 1 < MAX_TENTATIVAS:
        estado = 'pendente'
        _t += 1
        erro = f'Tentativa {_t} falhou ({erro[:80]}) — volta pra fila.'
    else:
        estado = 'erro'
        if _passageiro:
            _t += 1                      # o contador tem que bater com a frase
            erro = f'Falhou {_t}x seguidas: {erro[:120]}'
    conn.execute("UPDATE varredura_item SET status=?, erro=?, tentativas=?, atualizado_em=? WHERE id=?",
                 (estado, erro or None, _t, _agora_sp(), item_id))
    conn.commit(); close_db(conn)
    return _wa_cors(jsonify({"ok": True, "estado": estado, "tentativas": _t}))


@app.route('/crm/varredura/<int:lote_id>/parar', methods=['POST'])
@login_required
def crm_varredura_parar(lote_id):
    """Freio de mao. Uma varredura de 353 leads leva 2h30 e gasta dinheiro a
    cada item — quem comeca uma sem querer (ou com o filtro errado) precisa de
    um jeito de parar AGORA, nao de esperar terminar.

    Nao apaga nada: o que ja foi lido continua lido, e o que estava na fila fica
    guardado. Retomar continua de onde parou."""
    d = request.json or {}
    novo = 'rodando' if d.get('retomar') else 'parado'
    conn = db()
    lote = conn.execute("SELECT id, status FROM varredura_lote WHERE id=?", (lote_id,)).fetchone()
    if not lote:
        close_db(conn); return jsonify({"ok": False, "erro": "Lote não encontrado"}), 404
    conn.execute("UPDATE varredura_lote SET status=? WHERE id=?", (novo, lote_id))
    # Item que estava 'lendo' volta pra fila: se a extensao ja tinha pegado ele,
    # o resultado pode nunca chegar, e sem isto ele ficaria preso pra sempre.
    if novo == 'parado':
        conn.execute("UPDATE varredura_item SET status='pendente' WHERE lote_id=? AND status='lendo'",
                     (lote_id,))
    conn.commit()
    falta = conn.execute("SELECT COUNT(*) c FROM varredura_item WHERE lote_id=? AND status='pendente'",
                         (lote_id,)).fetchone()['c']
    close_db(conn)
    return jsonify({"ok": True, "status": novo, "na_fila": falta})


@app.route('/crm/varreduras')
@login_required
def crm_varreduras():
    """A lista dos lotes. Existe porque o link do lote so aparecia UMA vez, no
    alerta logo depois de criar: quem fechasse aquela janela perdia o caminho e
    nao tinha como voltar. Acompanhamento que so se acha por link salvo nao e
    acompanhamento."""
    conn = db()
    try:
        rows = conn.execute("""SELECT t.*, u.nome consultor,
            (SELECT COUNT(*) FROM varredura_item i WHERE i.lote_id=t.id AND i.status='lido') lidos,
            (SELECT COUNT(*) FROM varredura_item i WHERE i.lote_id=t.id AND i.status='erro') erros,
            (SELECT COUNT(*) FROM varredura_item i WHERE i.lote_id=t.id AND i.status='vazia') vazias,
            (SELECT COUNT(*) FROM varredura_item i WHERE i.lote_id=t.id AND i.status IN ('pendente','lendo')) fila
            FROM varredura_lote t LEFT JOIN usuarios u ON u.id=t.consultor_id
            ORDER BY t.id DESC LIMIT 100""").fetchall()
        lotes = [dict(r) for r in rows]
    except Exception as e:
        app.logger.warning(f"[VARREDURAS] {e}")
        lotes = []
    close_db(conn)
    for l in lotes:
        l['quando'] = _fmt_datahora_br(l.get('criado_em'))
    return render_template('crm_varreduras.html', lotes=lotes)


@app.route('/crm/varredura/<int:lote_id>')
@login_required
def crm_varredura_painel(lote_id):
    """Onde se vê se deu certo — e onde errou, lead por lead."""
    conn = db()
    lote = conn.execute("SELECT * FROM varredura_lote WHERE id=?", (lote_id,)).fetchone()
    if not lote:
        close_db(conn); abort(404)
    itens = conn.execute("""SELECT i.*, u.nome consultor FROM varredura_item i
        LEFT JOIN varredura_lote t ON t.id=i.lote_id
        LEFT JOIN usuarios u ON u.id=t.consultor_id
        WHERE i.lote_id=?
        ORDER BY (i.status='sem_conversa') DESC, (i.status='erro') DESC, (i.status='vazia') DESC, i.id""",
        (lote_id,)).fetchall()
    cons = conn.execute("SELECT nome FROM usuarios WHERE id=?", (lote['consultor_id'],)).fetchone()
    # QUEM CONTINUA SEM CONVERSA, agora — não na hora que o lote foi criado.
    # O card "Sem conversa vinculada" tem um botão que resolve exatamente isto
    # (vincular pela extensão ou juntar num lead com @lid), e sem reconferir o
    # botão "Adicionar à fila" nunca saberia se ainda valia a pena aparecer.
    ids_sem_conversa = [dict(i)['lead_id'] for i in itens if dict(i)['status'] == 'sem_conversa']
    ainda_sem = set()
    if ids_sem_conversa:
        marc = ','.join(['?'] * len(ids_sem_conversa))
        try:
            tem = {r['lead_id'] for r in conn.execute(
                f"""SELECT DISTINCT w.lead_id FROM wa_chat_lead w
                    WHERE w.lead_id IN ({marc})
                      AND NOT EXISTS (SELECT 1 FROM wa_conversa_ignorada g WHERE g.chat_id = w.chat_id)""",
                ids_sem_conversa).fetchall()}
            ainda_sem = set(ids_sem_conversa) - tem
        except Exception as e:
            app.logger.warning(f"[VARREDURA] reconferência sem_conversa: {e}")
            ainda_sem = set(ids_sem_conversa)
    close_db(conn)
    itens = [dict(r) for r in itens]
    for i in itens:
        i['quando'] = _fmt_datahora_br(i.get('atualizado_em'))
        if i['status'] == 'sem_conversa':
            i['ja_resolvido'] = i['lead_id'] not in ainda_sem
    cont = {'pendente': 0, 'lendo': 0, 'lido': 0, 'erro': 0, 'vazia': 0, 'sem_conversa': 0}
    for i in itens:
        cont[i['status']] = cont.get(i['status'], 0) + 1
    cont['sem_conversa_resolvido'] = sum(1 for i in itens if i.get('ja_resolvido'))
    return render_template('crm_varredura.html', lote=dict(lote), itens=itens, cont=cont,
                           consultor=(cons['nome'] if cons else ''))


@app.route('/crm/varredura/<int:lote_id>/reenfileirar-resolvidos', methods=['POST'])
@login_required
def crm_varredura_reenfileirar_resolvidos(lote_id):
    """Pega quem ficou 'sem conversa' neste lote e, pra quem JÁ TEM conversa
    agora, cria uma fila nova. É o botão que fecha o ciclo do "43 de fora":
    depois de rodar 'Sincronizar @lid' ou juntar o lead certo, não devolve
    pra tela de filtro — resolve dali mesmo, só com quem estava faltando."""
    conn = db()
    lote = conn.execute("SELECT * FROM varredura_lote WHERE id=?", (lote_id,)).fetchone()
    if not lote:
        close_db(conn); return jsonify({"ok": False, "erro": "Lote não encontrado"}), 404
    pendentes = conn.execute(
        "SELECT lead_id, lead_nome FROM varredura_item WHERE lote_id=? AND status='sem_conversa'",
        (lote_id,)).fetchall()
    if not pendentes:
        close_db(conn)
        return jsonify({"ok": False, "erro": "Este lote não tem lead marcado como sem conversa."}), 400
    ids = [p['lead_id'] for p in pendentes]
    marc = ','.join(['?'] * len(ids))
    vinc = {}
    for r in conn.execute(f"""SELECT w.lead_id, w.chat_id FROM wa_chat_lead w
        WHERE w.lead_id IN ({marc})
          AND NOT EXISTS (SELECT 1 FROM wa_conversa_ignorada i WHERE i.chat_id = w.chat_id)""",
        ids).fetchall():
        vinc.setdefault(r['lead_id'], r['chat_id'])
    alvos = [(p['lead_id'], p['lead_nome'] or '', vinc[p['lead_id']]) for p in pendentes if p['lead_id'] in vinc]
    if not alvos:
        close_db(conn)
        return jsonify({"ok": False, "erro": "Nenhum destes ganhou conversa vinculada ainda."}), 400
    uid = session['user_id']
    alvo_uid = lote['consultor_id'] or uid
    ja = conn.execute("""SELECT id FROM varredura_lote
                          WHERE consultor_id=? AND status='rodando'
                            AND EXISTS (SELECT 1 FROM varredura_item i
                                        WHERE i.lote_id=varredura_lote.id AND i.status='pendente')
                          ORDER BY id LIMIT 1""", (alvo_uid,)).fetchone()
    if ja:
        close_db(conn)
        return jsonify({"ok": False, "em_andamento": ja['id'],
                        "erro": f"Já existe a varredura #{ja['id']} rodando pra este consultor."}), 409
    cur = conn.execute("""INSERT INTO varredura_lote
        (consultor_id, criado_por, filtro_txt, total, status, criado_em)
        VALUES (?,?,?,?,?,?)""",
        (alvo_uid, session.get('nome') or '', f'ajustados do lote #{lote_id} (estavam sem conversa)',
         len(alvos), 'rodando', _agora_sp()))
    novo_id = _last_insert_id(cur)
    if novo_id is None:
        novo_id = conn.execute("SELECT id FROM varredura_lote ORDER BY id DESC LIMIT 1").fetchone()['id']
    for lid, nome, cid in alvos:
        conn.execute("""INSERT INTO varredura_item (lote_id, lead_id, chat_id, lead_nome, status, atualizado_em)
                        VALUES (?,?,?,?,?,?)""", (novo_id, lid, cid, nome[:120], 'pendente', _agora_sp()))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "lote_id": novo_id, "total": len(alvos)})


@app.route('/api/whatsapp/conversas/pendentes', methods=['POST', 'OPTIONS'])
@requer('whatsapp:enviar')
def api_whatsapp_conversas_pendentes():
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    convs = (request.get_json(silent=True) or {}).get('conversas') or []
    if not isinstance(convs, list):
        return _wa_cors(jsonify({"ok": False, "erro": "Formato inválido"})), 400
    convs = convs[:300]
    conn = db()

    # A TRAVA POR PESSOA MORA AQUI, e o pulso tambem.
    #
    # Aqui porque esta rota e autenticada (sabe quem e sem precisar perguntar) e
    # porque TODA versao da extensao ja passa por ela — inclusive as antigas,
    # que nao conhecem a rota de decisao nova. Resultado: a extensao velha
    # continua trabalhando, mas nunca recebe conversa de quem nao devia ser
    # lido, e ainda assim aparece na tela de saude com versao e motivo.
    _uid_varr = getattr(g, 'usuario_id', None)
    _versao_ext = (request.headers.get('X-Ext-Versao') or
                   (request.get_json(silent=True) or {}).get('versao') or '').strip()[:20]
    try:
        _cfgv = varredura_cfg(conn)
        _pode, _motivo = varredura_pode_agora(_cfgv, _uid_varr, conn)
        if _uid_varr:
            conn.execute("""UPDATE usuarios SET varr_visto_em=?, varr_pode=?, varr_motivo=?,
                            varr_versao=COALESCE(NULLIF(?,''), varr_versao) WHERE id=?""",
                         (_agora_sp(), 1 if _pode else 0, _motivo, _versao_ext, _uid_varr))
            conn.commit()
        if not _pode:
            close_db(conn)
            # 200 com lista vazia, nao erro: a extensao nao fez nada errado, so
            # nao ha o que ela deva ler agora. E o motivo vai junto pra tela.
            return _wa_cors(jsonify({"ok": True, "analisar": [], "pular": [],
                                     "motivo": _motivo}))
    except Exception as e:
        app.logger.warning(f"[VARREDURA] trava por usuario: {e}")
        try: conn.rollback()
        except Exception: pass

    estados = {}
    ids = [str((c or {}).get('chat_id') or '') for c in convs if (c or {}).get('chat_id')]
    if ids:
        try:
            marc = ','.join(['?'] * len(ids))
            for r in conn.execute(f"""SELECT * FROM wa_conversa_estado
                                      WHERE chat_id IN ({marc})""", ids).fetchall():
                estados[r['chat_id']] = r
        except Exception as e:
            app.logger.warning(f"[VARREDURA] leitura de estado falhou: {e}")
    analisar, pular = [], []
    vinculados = 0
    for c in convs:
        cid = str((c or {}).get('chat_id') or '')
        if not cid:
            continue
        # Grava o vínculo @lid -> lead ANTES de decidir se analisa: mesmo conversa
        # que vai ser pulada por não ter novidade tem identidade a registrar, e é
        # justamente a conversa antiga que hoje aparece sem @lid no card.
        if registrar_chat_lead(conn, cid, (c or {}).get('telefone'), (c or {}).get('nome')):
            vinculados += 1
        ult_id = str((c or {}).get('ultima_msg_id') or '')
        if not ult_id:
            pular.append({'chat_id': cid, 'motivo': 'sem_mensagem'})
            continue
        e = estados.get(cid)
        if not e:
            analisar.append({'chat_id': cid, 'desde_msg_id': None, 'motivo': 'nunca_analisada'})
            continue
        # Marca d'água: a última mensagem de hoje é a mesma da última análise?
        # Comparo pelo ID, não pelo timestamp — timestamp de WhatsApp tem
        # granularidade de segundo e mensagens do mesmo segundo empatariam.
        if (e['ultima_msg_id'] or '') == ult_id:
            pular.append({'chat_id': cid, 'motivo': 'sem_novidade'})
        else:
            analisar.append({'chat_id': cid, 'desde_msg_id': e['ultima_msg_id'],
                             'motivo': 'novas_mensagens'})
    conn.commit()
    close_db(conn)
    return _wa_cors(jsonify({"ok": True, "analisar": analisar, "pular": pular,
                             "vinculados": vinculados, "motivos": _MOTIVOS_PENDENTE}))


def registrar_chat_lead(conn, chat_id, telefone=None, nome=None, lead_id=None):
    """Amarra um chat do WhatsApp (@lid) ao lead. Devolve o lead_id amarrado.

    Isto só era gravado quando alguém MANDAVA mensagem pela extensão — por isso o
    @lid aparecia numa minoria dos cards: a maioria das conversas o consultor
    responde direto no WhatsApp, sem passar pelo JOB, e o vínculo nunca nascia.
    Agora a varredura também registra, o que cobre toda conversa que teve troca no
    dia sem custar nada (é só o identificador, nenhuma IA envolvida)."""
    if not chat_id:
        return None
    tel_norm = _normalizar_telefone(telefone) if telefone else None
    if not lead_id and tel_norm:
        try:
            achado = _buscar_lead_por_telefone(conn, tel_norm)
            lead_id = achado['id'] if achado else None
        except Exception:
            lead_id = None
    if not (lead_id or tel_norm or nome):
        return None
    try:
        if DB_MODE == 'postgres':
            conn.execute("""INSERT INTO wa_chat_lead (chat_id, lead_id, telefone, telefone_norm, nome, atualizado_em)
                VALUES (%s,%s,%s,%s,%s,%s) ON CONFLICT (chat_id) DO UPDATE SET
                lead_id=COALESCE(excluded.lead_id, wa_chat_lead.lead_id),
                telefone=COALESCE(excluded.telefone, wa_chat_lead.telefone),
                telefone_norm=COALESCE(excluded.telefone_norm, wa_chat_lead.telefone_norm),
                nome=COALESCE(excluded.nome, wa_chat_lead.nome),
                atualizado_em=excluded.atualizado_em""",
                (chat_id, lead_id, telefone, tel_norm, nome or None, _agora_sp()))
        else:
            ja = conn.execute("SELECT lead_id, telefone, telefone_norm, nome FROM wa_chat_lead WHERE chat_id=?",
                              (chat_id,)).fetchone()
            if ja:
                conn.execute("""UPDATE wa_chat_lead SET lead_id=COALESCE(?,lead_id),
                    telefone=COALESCE(?,telefone), telefone_norm=COALESCE(?,telefone_norm),
                    nome=COALESCE(?,nome), atualizado_em=? WHERE chat_id=?""",
                    (lead_id, telefone, tel_norm, nome or None, _agora_sp(), chat_id))
            else:
                conn.execute("""INSERT INTO wa_chat_lead
                    (chat_id, lead_id, telefone, telefone_norm, nome, atualizado_em)
                    VALUES (?,?,?,?,?,?)""",
                    (chat_id, lead_id, telefone, tel_norm, nome or None, _agora_sp()))
    except Exception as e:
        app.logger.warning(f"[WA_CHAT_LEAD] não gravou {chat_id}: {e}")
        return None
    return lead_id


def registrar_estado_conversa(conn, chat_id, telefone_norm=None, lead_id=None,
                              ultima_msg_id=None, ultima_msg_em=None,
                              analise_id=None, msgs=0, custo_usd=0.0):
    """Carimba até onde esta conversa foi analisada. Chamado DEPOIS de a análise
    ter sido gravada — nunca antes, senão uma análise que falhasse marcaria a
    conversa como feita e o dado se perderia em silêncio."""
    if not chat_id:
        return
    agora = _agora_sp()
    try:
        ja = conn.execute("SELECT chat_id, custo_acumulado_usd FROM wa_conversa_estado WHERE chat_id=?",
                          (chat_id,)).fetchone()
        acum = float((ja['custo_acumulado_usd'] if ja else 0) or 0) + float(custo_usd or 0)
        if ja:
            conn.execute("""UPDATE wa_conversa_estado SET telefone_norm=COALESCE(?,telefone_norm),
                            lead_id=COALESCE(?,lead_id), ultima_msg_id=?, ultima_msg_em=?,
                            ultima_analise_id=?, ultima_analise_em=?, msgs_analisadas=?,
                            custo_acumulado_usd=?, atualizado_em=? WHERE chat_id=?""",
                         (telefone_norm or None, lead_id or None, ultima_msg_id, ultima_msg_em,
                          analise_id, agora, int(msgs or 0), acum, agora, chat_id))
        else:
            conn.execute("""INSERT INTO wa_conversa_estado
                (chat_id, telefone_norm, lead_id, ultima_msg_id, ultima_msg_em,
                 ultima_analise_id, ultima_analise_em, msgs_analisadas, custo_acumulado_usd, atualizado_em)
                VALUES (?,?,?,?,?,?,?,?,?,?)""",
                (chat_id, telefone_norm or None, lead_id or None, ultima_msg_id, ultima_msg_em,
                 analise_id, agora, int(msgs or 0), acum, agora))
    except Exception as e:
        app.logger.warning(f"[VARREDURA] não registrou estado de {chat_id}: {e}")


# ─── TRANSCRIÇÃO INLINE DOS ÁUDIOS ────────────────────────────────────────────
# A extensão mostra a transcrição colada embaixo de cada áudio, na própria
# conversa. Dois endpoints em vez de um: primeiro ela pergunta o que JÁ está em
# cache (barato, sem subir áudio nenhum) e pinta na hora; só depois sobe os que
# faltam. Sem essa separação, abrir uma conversa antiga significaria subir dezenas
# de megabytes de áudio que já foram transcritos e pagos.
_TETO_TRANSCRICAO_MES_USD = float(os.environ.get('TRANSCRICAO_TETO_MES_USD', '15'))


def _gasto_transcricao_mes(conn):
    """Quanto já foi gasto em transcrição no mês corrente (pelo cache, que é onde
    o custo real de cada áudio fica registrado)."""
    ini = datetime.now(TZ_SP).strftime('%Y-%m') + '-01'
    try:
        r = conn.execute("""SELECT COALESCE(SUM(custo_usd),0) v FROM whatsapp_transcricoes_cache
                            WHERE CAST(criado_em AS TEXT) >= ?""", (ini,)).fetchone()
        return float(r['v'] or 0)
    except Exception:
        return 0.0


@app.route('/api/whatsapp/transcricoes', methods=['POST', 'OPTIONS'])
@requer('ia:usar')
def api_whatsapp_transcricoes():
    """O que já está transcrito, pelos ids das mensagens. Resposta imediata."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    ids = (request.get_json(silent=True) or {}).get('ids') or []
    ids = [str(i) for i in ids if i][:400]
    if not ids:
        return _wa_cors(jsonify({"ok": True, "transcricoes": {}}))
    conn = db()
    out = {}
    try:
        marc = ','.join(['?'] * len(ids))
        for r in conn.execute(f"""SELECT msg_id, texto FROM whatsapp_transcricoes_cache
                                  WHERE msg_id IN ({marc})""", ids).fetchall():
            out[r['msg_id']] = r['texto']
        # Segunda passada por filehash: audio que a extensao ainda nao viu nesta
        # conversa, mas cujo CONTEUDO ja foi transcrito em outra.
        hs = (request.get_json(silent=True) or {}).get('filehashes') or {}
        faltam = {m: h for m, h in hs.items() if m not in out and h}
        if faltam:
            vals = list({h for h in faltam.values()})[:400]
            m2 = ','.join(['?'] * len(vals))
            porhash = {}
            for r in conn.execute(f"""SELECT filehash, texto FROM whatsapp_transcricoes_cache
                                      WHERE filehash IN ({m2})""", vals).fetchall():
                porhash.setdefault(r['filehash'], r['texto'])
            for m, h in faltam.items():
                if porhash.get(h):
                    out[m] = porhash[h]
        gasto = _gasto_transcricao_mes(conn)
    except Exception as e:
        app.logger.warning(f"[TRANSCRICAO] consulta de cache falhou: {e}")
        gasto = 0.0
    close_db(conn)
    return _wa_cors(jsonify({"ok": True, "transcricoes": out,
                             "gasto_mes_usd": round(gasto, 4),
                             "teto_mes_usd": _TETO_TRANSCRICAO_MES_USD}))


@app.route('/api/whatsapp/transcrever', methods=['POST', 'OPTIONS'])
@requer('ia:usar')
def api_whatsapp_transcrever():
    """Transcreve os áudios que ainda não têm cache. A extensão manda em lotes
    pequenos, do mais recente pro mais antigo — o que interessa aparece primeiro."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    audios = (request.get_json(silent=True) or {}).get('audios') or []
    if not isinstance(audios, list) or not audios:
        return _wa_cors(jsonify({"ok": False, "erro": "Nenhum áudio recebido"})), 400
    audios = audios[:10]
    conn = db()
    gasto = _gasto_transcricao_mes(conn)
    # Teto mensal: mesmo princípio do CUSTO_MAX_ANALISE_BRL que já existe. Nunca
    # deixa a transcrição automática virar uma conta surpresa no fim do mês.
    if gasto >= _TETO_TRANSCRICAO_MES_USD:
        close_db(conn)
        return _wa_cors(jsonify({"ok": False, "erro": "teto_mensal",
                                 "detalhe": f"Teto de US${_TETO_TRANSCRICAO_MES_USD} atingido neste mês",
                                 "gasto_mes_usd": round(gasto, 4)})), 200
    out, custo_rodada = {}, 0.0
    for a in audios:
        mid = str((a or {}).get('msg_id') or '')
        if not mid:
            continue
        fh = str((a or {}).get('filehash') or '') or None
        ja = _wa_transcricao_cache_buscar(conn, mid, fh)
        if ja:
            # Achou por filehash: carimba tambem neste msg_id, pra proxima
            # consulta desta conversa nem precisar do filehash.
            _wa_transcricao_cache_salvar(conn, mid, ja['texto'], ja.get('segundos'), 0.0, fh)
            out[mid] = ja['texto']
            continue
        b64 = (a or {}).get('base64') or ''
        if not b64:
            continue
        r = _transcrever_audio(b64, (a or {}).get('mime') or 'audio/ogg')
        if r and (r.get('texto') or '').strip():
            _wa_transcricao_cache_salvar(conn, mid, r['texto'], r.get('segundos'), r.get('custo_usd'), fh)
            out[mid] = r['texto']
            custo_rodada += float(r.get('custo_usd') or 0)
        else:
            # Falha vira string vazia em vez de sumir: a extensão marca o áudio
            # como "não deu pra transcrever" e não fica tentando pra sempre.
            out[mid] = ''
        if gasto + custo_rodada >= _TETO_TRANSCRICAO_MES_USD:
            break
    conn.commit(); close_db(conn)
    return _wa_cors(jsonify({"ok": True, "transcricoes": out,
                             "custo_rodada_usd": round(custo_rodada, 5),
                             "gasto_mes_usd": round(gasto + custo_rodada, 4)}))


# ─── FICHA COMPLETA DO LEAD PRA EXTENSÃO ──────────────────────────────────────
# UMA chamada devolve tudo que o popup dentro do WhatsApp precisa. É de propósito:
# o consultor abre a conversa e o painel tem que estar pronto — seis requisições em
# série (lead, etapas, sub-status, campos, etiquetas, atividades) dariam um painel
# que monta aos pedaços na frente dele, e aí ninguém usa.
@app.route('/api/whatsapp/lead/ficha', methods=['GET', 'OPTIONS'])
@requer('crm:ler')
def api_whatsapp_lead_ficha():
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    tel = _normalizar_telefone(request.args.get('telefone', ''))
    lid = request.args.get('lead_id', type=int)
    chat_id = (request.args.get('chat_id') or '').strip()[:120]
    if not tel and not lid:
        return _wa_cors(jsonify({"ok": False, "erro": "telefone ou lead_id ausente"})), 400
    conn = db()
    # JA MARCADA COMO PESSOAL? Sem isto o consultor marca, sai da conversa,
    # volta e ve o botao como se nada tivesse acontecido — e marca de novo, sem
    # saber se da primeira vez pegou.
    ignorada = False
    try:
        ignorada = bool(conn.execute(
            "SELECT 1 FROM wa_conversa_ignorada WHERE chat_id=? OR (telefone_norm IS NOT NULL "
            "AND telefone_norm <> '' AND telefone_norm=?)",
            (chat_id or '__nada__', tel or '__nada__')).fetchone())
    except Exception:
        pass
    try:
        if lid:
            lead = conn.execute("SELECT * FROM crm_leads WHERE id=?", (lid,)).fetchone()
        else:
            achado = _buscar_lead_por_telefone(conn, tel)
            lead = conn.execute("SELECT * FROM crm_leads WHERE id=?", (achado['id'],)).fetchone() if achado else None
        etapas = [dict(e) for e in carregar_etapas_crm(conn)]
        # Os quadros vão junto: sem eles a extensão listava as etapas de TODOS os
        # funis sem dizer de qual era cada uma, e o consultor tirava o lead do
        # kanban comercial achando que só estava mudando de etapa.
        quadros_lista = carregar_quadros_crm(conn)
        etiquetas_todas = carregar_etiquetas_crm(conn)
        campos_def = carregar_campos_crm(conn)
        if not lead:
            close_db(conn)
            # Sem lead ainda: devolve as listas pro popup já oferecer "criar lead"
            # com etapa/etiquetas prontas, sem uma segunda ida ao servidor.
            return _wa_cors(jsonify({
            # Os motivos de perda e o que cada um QUER DIZER viajam com a ficha:
            # a extensao precisa perguntar dentro do WhatsApp, e quem pergunta
            # tem que explicar.
            "motivos_perda": _motivos_perda_lista(conn),
            "motivos_ajuda": MOTIVO_PERDA_AJUDA,
                "ok": True, "existe": False, "telefone_norm": tel, "ignorada": ignorada,
                "etapas": etapas, "quadros": quadros_lista,
                "etiquetas_todas": etiquetas_todas,
                "campos_def": campos_def, "origens": _WA_ORIGENS_LEAD}))
        lead_d = dict(lead)
        resp_nome = ''
        if lead['responsavel_id']:
            u = conn.execute("SELECT nome FROM usuarios WHERE id=?", (lead['responsavel_id'],)).fetchone()
            resp_nome = (u['nome'] if u else '') or ''
        etqs = _etiquetas_dos_leads(conn, [lead['id']]).get(lead['id'], [])
        atividades = [dict(a) for a in conn.execute("""
            SELECT id, usuario_nome, tipo, descricao, criado_em FROM crm_atividades
            WHERE lead_id=? ORDER BY id DESC LIMIT 30""", (lead['id'],)).fetchall()]
        sla = conn.execute("SELECT sla_dias FROM crm_etapas WHERE slug=?", (lead['etapa'] or '',)).fetchone()
        payload = {
            "ok": True, "existe": True, "ignorada": ignorada,
            "lead": lead_d,
            "responsavel_nome": resp_nome,
            "etapas": etapas,
            "quadros": quadros_lista,
            "sub_status_etapa": _sub_status_por_etapa(conn).get(lead['etapa'] or '', []),
            "campos_def": campos_def,
            "campos_val": valores_campos_lead(conn, lead, campos_def),
            "campos_faltando": campos_faltando_pra_sair(conn, lead, campos_def),
            "etiquetas_todas": etiquetas_todas,
            "etiquetas_marcadas": [e['id'] for e in etqs],
            "atividades": atividades,
            "playbook": _playbook_do_lead(lead, [e['nome'] for e in etqs]),
            "saude": _saude_card(lead_d.get('avancou_em'),
                                 (sla['sla_dias'] if sla else None), lead_d.get('atualizado_em')),
            # Quais conversas ja estao amarradas a este lead. A extensao compara
            # com o chat ABERTO pra saber se oferece o botao de vincular.
            "wa_chats": [r['chat_id'] for r in conn.execute(
                "SELECT chat_id FROM wa_chat_lead WHERE lead_id=?", (lead['id'],)).fetchall()],
            "origens": _WA_ORIGENS_LEAD,
            # Os motivos de perda e o que cada um QUER DIZER viajam com a ficha:
            # a extensao precisa perguntar dentro do WhatsApp, e quem pergunta
            # tem que explicar.
            "motivos_perda": _motivos_perda_lista(conn),
            "motivos_ajuda": MOTIVO_PERDA_AJUDA,
            "cidades": _municipios(),
        }
    except Exception as e:
        close_db(conn)
        app.logger.error(f"[WA/FICHA] {e}")
        return _wa_cors(jsonify({"ok": False, "erro": "Falha ao montar a ficha"})), 500
    close_db(conn)
    return _wa_cors(jsonify(payload))


@app.route('/api/whatsapp/lead/<int:lid>/cnpj', methods=['POST', 'OPTIONS'])
@requer('crm:escrever')
def api_whatsapp_lead_cnpj(lid):
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    d = request.get_json(silent=True) or {}
    cnpj = (d.get('cnpj') or '').strip()
    empresa_nova = (d.get('empresa') or '').strip()
    
    if len(cnpj) > 50:
        return _wa_cors(jsonify({"ok": False, "erro": "CNPJ muito longo"})), 400
    conn = db()
    lead = conn.execute("SELECT qual_cnpj, empresa FROM crm_leads WHERE id=?", (lid,)).fetchone()
    if not lead:
        close_db(conn)
        return _wa_cors(jsonify({"ok": False, "erro": "Lead não encontrado"})), 404
        
    if lead['qual_cnpj'] and cnpj and not d.get('sobrescrever'):
        close_db(conn)
        return _wa_cors(jsonify({"ok": False, "erro": "cnpj_existente", "existente": lead['qual_cnpj']})), 409

    if lead['empresa'] and empresa_nova and not d.get('sobrescrever') and lead['empresa'].strip() != empresa_nova:
        close_db(conn)
        return _wa_cors(jsonify({"ok": False, "erro": "empresa_existente", "existente": lead['empresa']})), 409

    try:
        sets = []
        vals = []
        if cnpj:
            sets.append("qual_cnpj=?")
            vals.append(cnpj)
        if empresa_nova:
            sets.append("empresa=?")
            vals.append(empresa_nova)
            
        if sets:
            sets.append("atualizado_em=?")
            vals.extend([_agora_sp(), lid])
            conn.execute(f"UPDATE crm_leads SET {', '.join(sets)} WHERE id=?", vals)
            conn.commit()
    except Exception as e:
        try: conn.rollback()
        except: pass
        close_db(conn)
        app.logger.error(f"[WA/CNPJ] {e}")
        return _wa_cors(jsonify({"ok": False, "erro": "Falha ao salvar CNPJ/Empresa"})), 500
    close_db(conn)
    return _wa_cors(jsonify({"ok": True}))


@app.route('/api/whatsapp/cotador/hashes', methods=['GET', 'POST', 'OPTIONS'])
@requer('cotacao:escrever')
def api_whatsapp_cotador_hashes():
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    
    conn = db()
    try:
        import re as _re
        if request.method == 'GET':
            origem = (request.args.get('origem') or '').strip()
            if not origem.startswith('https://') or len(origem) > 120:
                close_db(conn)
                return _wa_cors(jsonify({"ok": False}))
                
            linhas = conn.execute("SELECT papel, hash FROM cotador_hash WHERE origem=?", (origem,)).fetchall()
            papeis = {r['papel']: r['hash'] for r in linhas}
            close_db(conn)
            return _wa_cors(jsonify({"ok": True, "papeis": papeis}))
            
        elif request.method == 'POST':
            d = request.get_json(silent=True) or {}
            origem = str(d.get('origem') or '').strip()
            if not origem.startswith('https://') or len(origem) > 120:
                close_db(conn)
                return _wa_cors(jsonify({"ok": False}))
                
            papeis_validos = {'criar', 'abrir', 'vidas', 'filtro', 'operadoras', 'planos', 'preco', 'entidade'}
            
            mortos = d.get('mortos') or []
            if isinstance(mortos, list):
                for m in mortos:
                    if not isinstance(m, dict):
                        continue
                    papel = str(m.get('papel') or '').strip()
                    h = str(m.get('hash') or '').strip()
                    if papel in papeis_validos and h:
                        conn.execute("DELETE FROM cotador_hash WHERE origem=? AND papel=? AND hash=?", (origem, papel, h))
            
            papeis = d.get('papeis') or {}
            if isinstance(papeis, dict):
                for papel, h in papeis.items():
                    papel = str(papel).strip()
                    h = str(h).strip()
                    if papel not in papeis_validos:
                        continue
                    if not _re.match(r'^[A-Za-z0-9_-]{1,200}$', h):
                        continue
                        
                    row = conn.execute("SELECT id FROM cotador_hash WHERE origem=? AND papel=?", (origem, papel)).fetchone()
                    if row:
                        conn.execute("UPDATE cotador_hash SET hash=?, visto_em=? WHERE id=?", (h, _agora_sp(), row['id'] if hasattr(row, 'keys') else row[0]))
                    else:
                        conn.execute("INSERT INTO cotador_hash (origem, papel, hash, visto_em) VALUES (?,?,?,?)", (origem, papel, h, _agora_sp()))
                        
            conn.commit()
            close_db(conn)
            return _wa_cors(jsonify({"ok": True}))
            
    except Exception as e:
        if hasattr(conn, 'rollback'):
            try: conn.rollback()
            except Exception: pass
        close_db(conn)
        app.logger.warning(f"[COTADOR_HASH] erro: {e}")
        return _wa_cors(jsonify({"ok": False}))


@app.route('/api/whatsapp/cotacoes', methods=['GET', 'OPTIONS'])
@requer('whatsapp:ler')
def api_whatsapp_cotacoes():
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))

    tel = _normalizar_telefone(request.args.get('telefone', ''))
    lid = request.args.get('lead_id', type=int)

    if not tel and not lid:
        return _wa_cors(jsonify({"ok": False, "erro": "telefone ou lead_id ausente"})), 400

    conn = db()
    try:
        achado_id = None
        lead_nome = ""
        
        if lid:
            lead = conn.execute("SELECT id, nome FROM crm_leads WHERE id=?", (lid,)).fetchone()
            if lead:
                achado_id = lead['id']
                lead_nome = lead['nome']
        else:
            achado = _buscar_lead_por_telefone(conn, tel)
            if achado:
                achado_id = achado['id']
                lead = conn.execute("SELECT nome FROM crm_leads WHERE id=?", (achado_id,)).fetchone()
                if lead:
                    lead_nome = lead['nome']

        if not achado_id:
            close_db(conn)
            return _wa_cors(jsonify({"ok": True, "lead_id": None, "cotacoes": []}))
            
        rows = conn.execute("""
            SELECT id, titulo, token, total, planos_json, criado_em 
            FROM cotacao_salva 
            WHERE lead_id = ? 
            ORDER BY criado_em DESC 
            LIMIT 10
        """, (achado_id,)).fetchall()
        
        agora_dt = datetime.now(TZ_SP)
        agora_date = agora_dt.date()
        
        cotacoes = []
        import json
        for r in rows:
            qtd_planos = None
            if r['planos_json']:
                try:
                    planos_arr = json.loads(r['planos_json'])
                    if isinstance(planos_arr, list):
                        qtd_planos = len(planos_arr)
                except Exception:
                    pass
                    
            url = None
            if r['token']:
                url = f"{_SITE_BASE_URL.rstrip('/')}/c/{r['token']}"
                
            dias = 0
            if r['criado_em']:
                dt_criacao = _parse_dt_seguro(r['criado_em'])
                if dt_criacao:
                    if dt_criacao.tzinfo is None:
                        dt_criacao = pytz.utc.localize(dt_criacao).astimezone(TZ_SP)
                    dias = (agora_date - dt_criacao.date()).days
                    criado_str = dt_criacao.isoformat()
                else:
                    criado_str = r['criado_em']
            else:
                criado_str = None
                
            cotacoes.append({
                "id": r['id'],
                "titulo": r['titulo'],
                "token": r['token'],
                "url": url,
                "total": r['total'],
                "planos_cotados": qtd_planos,
                "criado_em": criado_str,
                "dias": dias
            })

        close_db(conn)
        return _wa_cors(jsonify({
            "ok": True, 
            "lead_id": achado_id, 
            "lead_nome": lead_nome, 
            "cotacoes": cotacoes
        }))
    except Exception as e:
        close_db(conn)
        app.logger.warning(f"[WA/COTACOES] Erro ao buscar cotações do lead {lid or tel}: {e}")
        return _wa_cors(jsonify({"ok": False, "erro": "Não foi possível carregar as cotações."})), 500


@app.route('/api/whatsapp/cotacao/salvar', methods=['POST', 'OPTIONS'])
@requer('cotacao:escrever')
def api_whatsapp_cotacao_salvar():
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))

    d = request.get_json(silent=True) or {}
    conn = db()

    try:
        try:
            usuario_id = int(d.get('usuario_id') or 0)
        except Exception:
            usuario_id = 0

        if not usuario_id:
            close_db(conn)
            return _wa_cors(jsonify({"ok": False, "erro": "usuario_invalido"})), 400

        urow = conn.execute("SELECT id, nome, email FROM usuarios WHERE id=? AND ativo=1", (usuario_id,)).fetchone()
        if not urow:
            close_db(conn)
            return _wa_cors(jsonify({"ok": False, "erro": "usuario_invalido"})), 400

        try:
            lead_id = int(d.get('lead_id') or 0)
        except Exception:
            lead_id = 0

        if not lead_id:
            tel = _normalizar_telefone(d.get('telefone', ''))
            achado = _buscar_lead_por_telefone(conn, tel) if tel else None
            if achado:
                lead_id = achado['id']
            else:
                close_db(conn)
                return _wa_cors(jsonify({"ok": False, "erro": "sem_lead"})), 400

        d['lead_id'] = lead_id

        # 1. Grava histórico "vivo"
        try:
            vid = _cotacao_viva_gravar(conn, d, usuario_id, 'whatsapp')
        except ValueError as e:
            close_db(conn)
            erro_val = e.args[0] if e.args else "dados_invalidos"
            return _wa_cors(jsonify({"ok": False, "erro": erro_val})), 400

        # 2. Gera a apresentação final
        planos, total_geral, cont_faixa = _viva_para_apresentacao(d)

        token = secrets.token_urlsafe(9)
        mods = sorted(list(set(p.get('modalidade') for p in planos if p.get('modalidade'))))
        modalidades_json = json.dumps(mods, ensure_ascii=False) if mods else '[]'
        
        conn.execute("""INSERT INTO cotacao_salva
            (token, orientacao, lead_id, corretor_id, corretor_nome, corretor_email,
             corretor_telefone, cliente_nome, cliente_email, cliente_telefone, titulo,
             vidas_json, planos_json, total, tabela_ids_json, cidade, modalidades)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (token, 'horizontal', lead_id, usuario_id,
             urow['nome'] or '', urow['email'] or '', '',
             str(d.get('cliente_nome') or '').strip(),
             str(d.get('cliente_email') or '').strip(),
             str(d.get('cliente_telefone') or '').strip(),
             str(d.get('titulo') or 'Cotação').strip(),
             json.dumps(cont_faixa), json.dumps(planos, ensure_ascii=False),
             total_geral, '[]', str(d.get('cidade') or '').strip(), modalidades_json))
             
        cid = _last_insert_id(conn.cursor() if hasattr(conn, 'cursor') else conn)
        if not cid:
            cid = (conn.execute("SELECT lastval() AS id").fetchone()['id'] if DB_MODE == 'postgres'
                   else conn.execute("SELECT last_insert_rowid() id").fetchone()['id'])
                   
        try:
            registrar_cotacao_no_lead(conn, lead_id, cid, planos, total_geral, [], str(d.get('titulo') or '').strip())
        except Exception:
            pass

        conn.commit()
        close_db(conn)

        url = f"{_SITE_BASE_URL.rstrip('/')}/c/{token}"
        # DEVOLVE O QUE FOI GRAVADO, pra imagem e documento nao discordarem.
        #
        # A extensao desenha a imagem da cotacao no proprio navegador, com a
        # copia dela das regras. Quando as duas copias divergiram — a do
        # servidor sabia ler acomodacao 1/0 e a da extensao nao — o consultor
        # abria o documento com "Enfermaria" e mandava pro cliente uma imagem
        # com a linha em branco, da MESMA cotacao. Duas fontes da verdade pro
        # mesmo papel do cliente e sempre um jeito de errar.
        #
        # So o essencial pra identificar o plano e o que estava faltando: nao e
        # pra extensao redesenhar tudo daqui, e sim pra ela poder corrigir o
        # que ela nao soube resolver sozinha.
        resolvidos = [{'operadora': p.get('operadora') or '',
                       'plano': p.get('plano') or '',
                       'acomodacao': p.get('acomodacao') or ''} for p in planos]
        return _wa_cors(jsonify({"ok": True, "id": cid, "token": token, "url": url,
                                 "planos_resolvidos": resolvidos}))

    except Exception as e:
        conn.rollback()
        close_db(conn)
        app.logger.error(f"[WA/COTACAO_SALVAR] {e}")
        return _wa_cors(jsonify({"ok": False, "erro": "Não foi possível salvar a cotação."})), 500


@app.route('/api/whatsapp/preferencias', methods=['GET', 'POST', 'OPTIONS'])
@requer('whatsapp:enviar')
def api_whatsapp_preferencias():
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))

    conn = db()
    try:
        if request.method == 'GET':
            try: usuario_id = int(request.args.get('usuario_id') or 0)
            except Exception: usuario_id = 0
            if not usuario_id:
                close_db(conn)
                return _wa_cors(jsonify({"ok": False}))
                
            urow = conn.execute("SELECT id FROM usuarios WHERE id=? AND ativo=1", (usuario_id,)).fetchone()
            if not urow:
                close_db(conn)
                return _wa_cors(jsonify({"ok": False}))
                
            cidade = _pref_cotacao(conn, usuario_id, 'cidade')
            close_db(conn)
            return _wa_cors(jsonify({"ok": True, "cidade": cidade}))
            
        elif request.method == 'POST':
            d = request.get_json(silent=True) or {}
            try: usuario_id = int(d.get('usuario_id') or 0)
            except Exception: usuario_id = 0
            if not usuario_id:
                close_db(conn)
                return _wa_cors(jsonify({"ok": False}))
                
            urow = conn.execute("SELECT id FROM usuarios WHERE id=? AND ativo=1", (usuario_id,)).fetchone()
            if not urow:
                close_db(conn)
                return _wa_cors(jsonify({"ok": False}))
                
            cidade = str(d.get('cidade') or '').strip()[:120]
            conn.execute("DELETE FROM cotacao_preferencia WHERE usuario_id=? AND chave=?", (usuario_id, 'cidade'))
            if cidade:
                conn.execute("""INSERT INTO cotacao_preferencia (usuario_id, chave, valor, atualizado_em)
                                VALUES (?,?,?,?)""", (usuario_id, 'cidade', cidade, _agora_sp()))
            conn.commit()
            close_db(conn)
            return _wa_cors(jsonify({"ok": True}))
            
    except Exception:
        if hasattr(conn, 'rollback'):
            try: conn.rollback()
            except Exception: pass
        close_db(conn)
        return _wa_cors(jsonify({"ok": False}))

@app.route('/api/whatsapp/lead/salvar', methods=['POST', 'OPTIONS'])
@requer('crm:escrever')
def api_whatsapp_lead_salvar():
    """Salva em UMA chamada o que o popup mudou. Aplica na ordem: campos → etiquetas
    → sub-status → etapa. A etapa é a ÚLTIMA de propósito: ela é a única que pode
    ser recusada (campo obrigatório em branco), e nessa ordem o consultor não perde
    o que digitou quando a mudança de etapa é barrada."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    d = request.get_json(silent=True) or {}
    try:
        lid = int(d.get('lead_id') or 0)
    except (TypeError, ValueError):
        lid = 0
    if not lid:
        return _wa_cors(jsonify({"ok": False, "erro": "lead_id ausente"})), 400
    try:
        uid = int(d.get('usuario_id') or 0) or None
    except (TypeError, ValueError):
        uid = None
    conn = db()
    # A extensão guarda só o id do consultor, não o nome — quem resolve é aqui,
    # senão a atividade ficaria assinada como "Extensão" e o histórico não diria
    # quem fez o quê.
    autor = (d.get('usuario_nome') or '').strip()[:80]
    if not autor and uid:
        u = conn.execute("SELECT nome FROM usuarios WHERE id=?", (uid,)).fetchone()
        autor = (u['nome'] if u else '') or ''
    autor = autor or 'Extensão'
    lead = conn.execute("SELECT * FROM crm_leads WHERE id=?", (lid,)).fetchone()
    if not lead:
        close_db(conn)
        return _wa_cors(jsonify({"ok": False, "erro": "Lead não encontrado"})), 404
    # Mesma checagem de dono das rotas equivalentes do CRM (crm_lead_editar,
    # crm_lead_campos_salvar, crm_lead_etiqueta): sem ela, pela extensão qualquer
    # consultor editava lead de colega — e a atividade saía assinada com o nome
    # que ele mesmo mandou. A chave da extensão diz que a chamada vem do JOB, não
    # QUEM está chamando.
    if uid:
        u = conn.execute("SELECT perfil FROM usuarios WHERE id=? AND ativo=1", (uid,)).fetchone()
        eh_admin_wa = bool(u) and (u['perfil'] or '') == 'admin'
        if not eh_admin_wa and lead['responsavel_id'] and lead['responsavel_id'] != uid:
            close_db(conn)
            return _wa_cors(jsonify({"ok": False,
                "erro": "Este lead é de outro consultor. Peça a transferência no CRM."})), 403
    mudancas, avisos = [], []
    try:
        # 1) Dados básicos
        campos_simples = {'nome': 80, 'email': 120, 'empresa': 120, 'observacoes': 4000, 'qual_cidade': 120}
        sets, vals = [], []
        for k, lim in campos_simples.items():
            if k in d:
                novo = (str(d.get(k) or '')).strip()[:lim]
                if novo != ((lead[k] or '') if k in lead.keys() else ''):
                    sets.append(f"{k}=?"); vals.append(novo or None)
                    mudancas.append(k)
        if 'origem' in d and (d.get('origem') or '') in _WA_ORIGENS_LEAD:
            if d['origem'] != (lead['origem'] or ''):
                sets.append("origem=?"); vals.append(d['origem']); mudancas.append('origem')
        if 'valor_estimado' in d:
            bruto = str(d.get('valor_estimado') or '').replace('.', '').replace(',', '.')
            try:
                v = float(bruto) if bruto else None
            except ValueError:
                v = None
            # Só grava se MUDOU. Antes entrava em toda gravação: `mudancas` nunca
            # ficava vazio, então todo save inseria uma atividade 'edicao' falsa no
            # histórico e o painel dizia "Salvo: valor" sem nada ter mudado. Pior:
            # campo em branco virava None e apagava o valor que existia.
            atual = lead['valor_estimado'] if 'valor_estimado' in lead.keys() else None
            if (v is None) != (atual is None) or (v is not None and float(v) != float(atual or 0)):
                sets.append("valor_estimado=?"); vals.append(v); mudancas.append('valor')
        if sets:
            conn.execute(f"UPDATE crm_leads SET {', '.join(sets)}, atualizado_em=? WHERE id=?",
                         vals + [_agora_sp(), lid])

        # 2) Campos personalizados (reaproveita o mesmo gravador do CRM, então a
        #    regra de campo utm/só-se-vazio vale igual aqui)
        campos = {c['chave']: c for c in carregar_campos_crm(conn)}
        antes = valores_campos_lead(conn, lead)
        for chave, valor in (d.get('campos') or {}).items():
            c = campos.get(chave)
            if not c or c['fonte'] == 'utm':
                continue
            if isinstance(valor, list):
                valor = ', '.join([str(v) for v in valor if str(v).strip()])
            novo = ('' if valor is None else str(valor)).strip()
            if novo != (antes.get(chave, {}).get('valor') or ''):
                gravar_campo_lead(conn, lid, chave, novo, fonte=f"extensao:{uid or '-'}")
                mudancas.append(c['nome'])
        if (d.get('campos') or {}).get('cnpj'):
            try:
                _preencher_campos_por_cnpj(conn, lid, d['campos']['cnpj'])
            except Exception as e:
                avisos.append(f"CNPJ não consultado: {e}")

        # 3) Etiquetas — lista fechada de ids marcados
        if isinstance(d.get('etiquetas'), list):
            querem = {int(x) for x in d['etiquetas'] if str(x).isdigit()}
            validas = {e['id'] for e in carregar_etiquetas_crm(conn)}
            querem &= validas
            atuais = {e['id'] for e in _etiquetas_dos_leads(conn, [lid]).get(lid, [])}
            for eid in querem - atuais:
                if DB_MODE == 'postgres':
                    conn.execute("""INSERT INTO crm_lead_etiquetas (lead_id,etiqueta_id,criado_em)
                        VALUES (%s,%s,%s) ON CONFLICT DO NOTHING""", (lid, eid, _agora_sp()))
                else:
                    conn.execute("""INSERT OR IGNORE INTO crm_lead_etiquetas (lead_id,etiqueta_id,criado_em)
                        VALUES (?,?,?)""", (lid, eid, _agora_sp()))
            for eid in atuais - querem:
                conn.execute("DELETE FROM crm_lead_etiquetas WHERE lead_id=? AND etiqueta_id=?", (lid, eid))
            if querem != atuais:
                mudancas.append('etiquetas')

        # 4) Sub-status (validado contra a etapa ATUAL)
        if 'sub_status' in d:
            novo_ss = (d.get('sub_status') or '').strip()
            permitidos = [''] + _sub_status_por_etapa(conn).get(lead['etapa'] or '', [])
            if novo_ss not in permitidos:
                avisos.append('Sub-status não existe nesta etapa')
            elif novo_ss != (lead['sub_status'] or ''):
                conn.execute("UPDATE crm_leads SET sub_status=?, atualizado_em=?, avancou_em=? WHERE id=?",
                             (novo_ss or None, _agora_sp(), _agora_sp(), lid))
                mudancas.append(f'sub-status: {novo_ss or "—"}')

        # 5) Atividade escrita pelo consultor
        nota = (d.get('atividade') or '').strip()[:4000]
        if nota:
            conn.execute("""INSERT INTO crm_atividades (lead_id, usuario_nome, tipo, descricao, criado_em)
                            VALUES (?,?,?,?,?)""", (lid, autor, d.get('atividade_tipo') or 'nota', nota, _agora_sp()))

        if mudancas:
            conn.execute("""INSERT INTO crm_atividades (lead_id, usuario_nome, tipo, descricao, criado_em)
                            VALUES (?,?,?,?,?)""",
                         (lid, autor, 'edicao', 'Pelo WhatsApp: ' + ', '.join(mudancas[:12]), _agora_sp()))
        conn.commit()

        # 6) Etapa por último — a única que pode ser barrada
        etapa_ok, etapa_erro = True, None
        nova_etapa = (d.get('etapa') or '').strip()
        if nova_etapa and nova_etapa != (lead['etapa'] or ''):
            atual = conn.execute("SELECT * FROM crm_leads WHERE id=?", (lid,)).fetchone()
            if nova_etapa not in [e['id'] for e in carregar_etapas_crm(conn)]:
                etapa_ok, etapa_erro = False, 'Etapa inválida'
            else:
                faltando = campos_faltando_pra_sair(conn, atual)
                if faltando:
                    etapa_ok = False
                    etapa_erro = 'Preencha antes de mudar de etapa: ' + ', '.join([f['nome'] for f in faltando])
                # A etapa de DESTINO tambem exige. Os campos ja foram gravados no
                # passo 1 desta mesma chamada, entao o consultor responde dentro
                # do WhatsApp e a etapa vai junto — sem abrir o site.
                _td = conn.execute("SELECT tipo FROM crm_etapas WHERE slug=?", (nova_etapa,)).fetchone()
                _falta_ent = [] if faltando else campos_faltando_pra_entrar(
                    conn, nova_etapa, atual, tipo_destino=((_td['tipo'] if _td else '') or ''))
                if faltando:
                    pass                      # ja tratado acima
                elif _falta_ent:
                    etapa_ok = False
                    etapa_erro = ('Antes de mover para esta etapa: '
                                  + ', '.join([f['nome'] for f in _falta_ent]))
                else:
                    conn.execute("""UPDATE crm_leads SET etapa=?, sub_status=NULL,
                                    atualizado_em=?, avancou_em=? WHERE id=?""",
                                 (nova_etapa, _agora_sp(), _agora_sp(), lid))
                    conn.execute("""INSERT INTO crm_atividades (lead_id, usuario_nome, tipo, descricao, criado_em)
                                    VALUES (?,?,?,?,?)""",
                                 (lid, autor, 'movimentacao',
                                  f'Movido de "{lead["etapa"]}" para "{nova_etapa}" (pelo WhatsApp)', _agora_sp()))
                    _mp = ((d.get('campos') or {}).get('motivo_perda') or '').strip()
                    if _mp:
                        conn.execute("UPDATE crm_leads SET perdido_motivo=? WHERE id=?",
                                     (_mp[:120], lid))
                    conn.commit()
                    try:
                        _fluxo_cancelar_por_etapa(conn, lid, nova_etapa)
                        _fluxo_autoiniciar_por_etapa(conn, lid, nova_etapa)
                        conn.commit()
                    except Exception as e:
                        try: conn.rollback()
                        except Exception: pass
                        app.logger.error(f"[WA/FICHA] hook de etapa falhou (lead {lid}): {e}")
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        close_db(conn)
        app.logger.error(f"[WA/SALVAR] {e}")
        return _wa_cors(jsonify({"ok": False, "erro": "Falha ao salvar"})), 500
    lead = conn.execute("SELECT * FROM crm_leads WHERE id=?", (lid,)).fetchone()
    fresco = {
        "lead": dict(lead),
        "campos_val": valores_campos_lead(conn, lead),
        "campos_faltando": campos_faltando_pra_sair(conn, lead),
        "sub_status_etapa": _sub_status_por_etapa(conn).get(lead['etapa'] or '', []),
        "etiquetas_marcadas": [e['id'] for e in _etiquetas_dos_leads(conn, [lid]).get(lid, [])],
    }
    close_db(conn)
    return _wa_cors(jsonify({"ok": True, "mudou": mudancas, "avisos": avisos,
                             "etapa_ok": etapa_ok, "etapa_erro": etapa_erro, **fresco}))


@app.route('/api/whatsapp/enviar-direto', methods=['POST', 'OPTIONS'])
@requer('whatsapp:enviar')
def api_whatsapp_enviar_direto():
    """Enfileira uma mensagem direto da conversa aberta no WhatsApp Web — pedido
    explícito do Guilherme pra extensão funcionar inteira ali, sem precisar
    abrir o site do JOB (igual WaSpeed/ZapVoice). Autenticado por chave de
    extensão (não sessão de login), casa ou cria o lead pelo telefone (mesma
    lógica de _wa_auth_ok/casamento usada em /api/whatsapp/analisar).
    responsavel_id da fila é SEMPRE o usuario_id de quem está usando a
    extensão agora — é o WhatsApp Web dessa pessoa que vai executar o envio,
    então tem que bater com o que /fila/proximo vai filtrar depois."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    d = request.json or {}
    telefone = str(d.get('telefone') or '').strip()
    nome = str(d.get('nome') or '').strip()[:200]
    texto = str(d.get('texto') or '').strip()[:4000]
    # Texto pode ser vazio SE for um modelo de mídia (áudio/imagem sem legenda) —
    # a validação de "mensagem vazia" pra texto puro acontece depois de resolver
    # o modelo (senão áudio/nota de voz sem legenda era barrado como vazio).
    tem_modelo = bool(str(d.get('modelo_id') or '').strip())
    if not texto and not tem_modelo:
        return _wa_cors(jsonify({"ok": False, "erro": "Mensagem vazia"})), 400
    # chat_id explícito (id serializado da conversa aberta, via wa-js) é o
    # caminho à prova de falha — funciona pra contato salvo e @lid, onde o
    # telefone não é lido. Se não veio, cai pro cálculo pelo telefone.
    chat_id = str(d.get('chat_id') or '').strip()[:100]
    if not chat_id:
        chat_id = _wa_chat_id(telefone)
    if not chat_id:
        return _wa_cors(jsonify({"ok": False, "erro": "Não consegui identificar a conversa (abra a conversa e tente de novo)"})), 400
    # Se o telefone não veio mas o chat_id é de contato normal (55...@c.us),
    # extrai os dígitos pra ainda tentar casar o lead.
    if not telefone and chat_id.endswith('@c.us'):
        telefone = chat_id.split('@')[0]
    usuario_id = None
    try:
        usuario_id = int(d.get('usuario_id'))
    except (TypeError, ValueError):
        pass
    conn = db()
    if usuario_id:
        u = conn.execute("SELECT id FROM usuarios WHERE id=? AND ativo=1", (usuario_id,)).fetchone()
        if not u:
            usuario_id = None
    if not usuario_id:
        close_db(conn)
        return _wa_cors(jsonify({"ok": False, "erro": "Selecione seu usuário no popup da extensão antes de mandar mensagem"})), 400
    try:
        modelo_id = int(d.get('modelo_id'))
    except (TypeError, ValueError):
        modelo_id = None
    if modelo_id:
        # A extensão só pode disparar conteúdo próprio ou compartilhado.
        permitido = conn.execute("""SELECT 1 FROM modelos_conteudo
            WHERE id=? AND tipo='whatsapp' AND ativo=1
              AND (dono_consultor_id=? OR dono_consultor_id IS NULL)""",
                                 (modelo_id, usuario_id)).fetchone()
        if not permitido:
            close_db(conn)
            return _wa_cors(jsonify({"ok": False, "erro": "Sua biblioteca mudou. Feche e abra Mensagens novamente antes de enviar."})), 403

    _sem_numero_reportar = False
    tel_norm = _normalizar_telefone(telefone)
    lead = _buscar_lead_por_telefone(conn, tel_norm)
    if not lead and nome:
        # Casa por NOME (contatos @lid, sem número exposto). REAPROVEITA um lead que
        # já existe em vez de criar outro a cada envio — pega o melhor: do consultor
        # atual, de preferência já COM número, senão o mais antigo. Antes só casava
        # se houvesse exatamente um -> com duplicados ele desistia e criava mais um.
        cands = conn.execute(
            "SELECT id, nome, responsavel_id, telefone_norm FROM crm_leads WHERE LOWER(TRIM(nome))=?",
            (nome.strip().lower(),)).fetchall()
        if cands:
            meus = [c for c in cands if c['responsavel_id'] == usuario_id] or list(cands)
            meus.sort(key=lambda c: (0 if (c['telefone_norm'] or '').strip() else 1, c['id']))
            lead = meus[0]
    lead_id = lead['id'] if lead else None
    # Lead já existe e é de OUTRO consultor: não trava nada — a mensagem sai igual
    # e a atividade é registrada do mesmo jeito — só avisa os dois (quem está
    # conversando agora e o dono do lead no JOB), pra não passar batido.
    dono_diferente_id = lead['responsavel_id'] if (lead and lead['responsavel_id'] and lead['responsavel_id'] != usuario_id) else None
    nome_lead_atual = (lead['nome'] if lead else '') or nome or 'Lead'
    # Casou um lead sem número e AGORA temos: completa (deixa de ser órfão).
    if lead_id and tel_norm:
        conn.execute("""UPDATE crm_leads SET telefone=COALESCE(NULLIF(telefone,''),?),
            telefone_norm=COALESCE(NULLIF(telefone_norm,''),?) WHERE id=?""",
            (telefone, tel_norm, lead_id))
    if not lead_id and (tel_norm or nome):
        # Cria UMA vez. A partir daqui os próximos envios casam por número (se houver)
        # ou por nome (reaproveita) — não duplica mais. Sem número, avisa os admins.
        conn.execute("""INSERT INTO crm_leads
            (nome, telefone, telefone_norm, origem, etapa, responsavel_id, observacoes, criado_em)
            VALUES (?,?,?,?,?,?,?,?)""",
            (nome or telefone or 'Lead WhatsApp', telefone, tel_norm, 'WhatsApp (extensão)',
             'lead_novo', usuario_id, 'Criado automaticamente ao mandar mensagem pela extensão.', _agora_sp()))
        lead_id = (conn.execute("SELECT lastval() AS id").fetchone()['id'] if DB_MODE == "postgres"
                   else conn.execute("SELECT last_insert_rowid() id").fetchone()['id'])
        conn.execute("INSERT INTO crm_atividades (lead_id, usuario_nome, tipo, descricao, criado_em) VALUES (?,?,?,?,?)",
                     (lead_id, 'Extensão WhatsApp', 'criacao',
                      'Lead criado automaticamente ao mandar mensagem pela extensão.', _agora_sp()))
        if not tel_norm:
            _sem_numero_reportar = True  # nasceu sem número — pedir pra alguém completar

    # Se veio de um modelo salvo com MÍDIA (áudio/imagem), a fila manda a mídia
    # (item A) — texto vira legenda. Sem mídia, é texto puro como antes.
    tipo, midia_arquivo = 'texto', None
    if modelo_id:
        mod = conn.execute("SELECT midia_arquivo, midia_tipo FROM modelos_conteudo WHERE id=? AND tipo='whatsapp'", (modelo_id,)).fetchone()
        if mod and mod['midia_arquivo'] and mod['midia_tipo'] in ('audio', 'imagem', 'video', 'documento'):
            tipo, midia_arquivo = mod['midia_tipo'], mod['midia_arquivo']
    # Agora sim: se acabou sendo texto puro (sem mídia) e o texto está vazio, barra.
    if tipo == 'texto' and not texto:
        close_db(conn)
        return _wa_cors(jsonify({"ok": False, "erro": "Mensagem vazia"})), 400
    conn.execute("""INSERT INTO whatsapp_extensao_fila
        (lead_id, responsavel_id, telefone, chat_id, tipo, texto, midia_arquivo, origem, criado_por, criado_em)
        VALUES (?,?,?,?,?,?,?,'extensao_direto',?,?)""",
        (lead_id, usuario_id, telefone, chat_id, tipo, texto, midia_arquivo, usuario_id,
         _agora_sp()))
    fila_id = (conn.execute("SELECT lastval() AS id").fetchone()['id'] if DB_MODE == "postgres"
               else conn.execute("SELECT last_insert_rowid() id").fetchone()['id'])
    # Contabiliza uso do modelo (pra "mais usadas" na biblioteca).
    if modelo_id:
        conn.execute("UPDATE modelos_conteudo SET vezes_usado = COALESCE(vezes_usado,0) + 1 WHERE id=? AND tipo='whatsapp'", (modelo_id,))
    # Guarda chat_id -> lead/telefone/nome NO SERVIDOR (não só no navegador do
    # consultor) — assim, na próxima vez que QUALQUER extensão perguntar por essa
    # conversa, o JOB já responde sem precisar abrir o popup de novo.
    if chat_id and (lead_id or telefone or nome):
        if DB_MODE == 'postgres':
            conn.execute("""INSERT INTO wa_chat_lead (chat_id, lead_id, telefone, telefone_norm, nome, atualizado_em)
                VALUES (%s,%s,%s,%s,%s,%s) ON CONFLICT (chat_id) DO UPDATE SET
                lead_id=excluded.lead_id, telefone=excluded.telefone, telefone_norm=excluded.telefone_norm,
                nome=excluded.nome, atualizado_em=excluded.atualizado_em""",
                (chat_id, lead_id, telefone, tel_norm, nome, _agora_sp()))
        else:
            conn.execute("""INSERT OR REPLACE INTO wa_chat_lead (chat_id, lead_id, telefone, telefone_norm, nome, atualizado_em)
                VALUES (?,?,?,?,?,?)""", (chat_id, lead_id, telefone, tel_norm, nome, _agora_sp()))
    conn.commit(); close_db(conn)
    if _sem_numero_reportar:
        # Reporta 1x pros admins: contato sem número exposto, ninguém foi cadastrado.
        try:
            _notificar_admins('lead_sem_numero', 'Contato de WhatsApp sem número',
                f'{nome or "Contato"} recebeu mensagem pela extensão, mas o WhatsApp não expôs o número '
                '(conta business/privacidade). O lead NÃO foi cadastrado — peça o número ao cliente.', '/crm')
        except Exception:
            pass
    if dono_diferente_id and lead_id:
        # Throttle: não avisa de novo se já avisou nos últimos 30min pra esse
        # par lead+consultor (conversa ativa não pode virar spam de notificação).
        try:
            conn2 = db()
            cutoff = (datetime.now(TZ_SP) - timedelta(minutes=30)).strftime('%Y-%m-%d %H:%M:%S')
            ja_avisou = conn2.execute("""SELECT 1 FROM notificacoes WHERE tipo='lead_outro_consultor'
                AND link=? AND criado_em>? LIMIT 1""", (f'/crm/lead/{lead_id}', cutoff)).fetchone()
            if not ja_avisou:
                quem_conversa = conn2.execute("SELECT nome FROM usuarios WHERE id=?", (usuario_id,)).fetchone()
                quem_conversa_nome = quem_conversa['nome'] if quem_conversa else 'Um consultor'
                dono_nome_row = conn2.execute("SELECT nome FROM usuarios WHERE id=?", (dono_diferente_id,)).fetchone()
                dono_nome = dono_nome_row['nome'] if dono_nome_row else 'outro consultor'
                _notificar(dono_diferente_id, 'lead_outro_consultor', 'Seu lead está sendo atendido por outro consultor',
                           f'{quem_conversa_nome} está conversando com {nome_lead_atual} no WhatsApp — esse lead é seu no JOB.',
                           f'/crm/lead/{lead_id}')
                _notificar(usuario_id, 'lead_outro_consultor', 'Esse lead já é de outro consultor',
                           f'{nome_lead_atual} já é atendido por {dono_nome} no JOB. Sua mensagem foi enviada normalmente — '
                           'combine com ele antes de seguir a conversa.', f'/crm/lead/{lead_id}')
            close_db(conn2)
        except Exception:
            pass
    return _wa_cors(jsonify({"ok": True, "id": fila_id, "lead_id": lead_id,
                             "precisa_numero": _sem_numero_reportar,
                             "dono_diferente": bool(dono_diferente_id)}))


@app.route('/api/whatsapp/extensao/cotacao/contexto', methods=['GET', 'OPTIONS'])
@requer('cotacao:ler')
def api_whatsapp_extensao_cotacao_contexto():
    """Tudo que o CABEÇALHO do documento de cotação precisa, numa chamada.

    A extensão desenha a cotação dentro do painel (o consultor não pode ser
    jogado pra fora do WhatsApp no meio de um atendimento). Só que ela sabia
    apenas o id e o nome de quem entrou — então o desenho saía sem o logo da
    corretora, sem o e-mail do consultor e com o nome do CONTATO no lugar do
    nome do cliente. Guilherme, 09/08/2026: "se vire e puxe do JOB site esses
    dados e imagem".

    Escrita pelo Claude, que normalmente não mexe neste arquivo. É aditiva de
    propósito: rota nova, nada alterado — pra não colidir com o Antigravity.

    O logo vai como data URL porque a página do WhatsApp barra imagem de outro
    endereço (a mesma razão pela qual as logos das operadoras já vêm assim).
    """
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))

    uid = request.args.get('usuario_id', type=int)
    lid = request.args.get('lead_id', type=int)
    conn = db()
    corretor = {'nome': '', 'email': '', 'telefone': ''}
    if uid:
        u = conn.execute("SELECT nome, email FROM usuarios WHERE id=?", (uid,)).fetchone()
        if u:
            # `usuarios` não tem telefone — a rota de salvar já grava '' nesse
            # campo. Vai vazio e a extensão simplesmente não desenha a linha,
            # em vez de inventar um número.
            corretor = {'nome': u['nome'] or '', 'email': u['email'] or '', 'telefone': ''}
    lead = {}
    if lid:
        r = conn.execute("SELECT nome, empresa, qual_cnpj, telefone FROM crm_leads WHERE id=?",
                         (lid,)).fetchone()
        if r:
            lead = {'nome': r['nome'] or '', 'empresa': r['empresa'] or '',
                    'cnpj': r['qual_cnpj'] or '', 'telefone': r['telefone'] or ''}
    close_db(conn)

    logo_data = ''
    try:
        import base64 as _b64c
        # O de CLIENTE: a imagem que a extensao desenha vai pro WhatsApp do
        # cliente, entao quem assina ali e a corretora.
        alvo = BRAND.get('logo_cliente') or BRAND.get('logo') or ''
        if alvo.startswith('/static/'):
            caminho = os.path.join(app.root_path, alvo.lstrip('/'))
            if os.path.exists(caminho) and os.path.getsize(caminho) < 2_000_000:
                ext = os.path.splitext(caminho)[1].lower().lstrip('.') or 'png'
                with open(caminho, 'rb') as fh:
                    logo_data = 'data:image/%s;base64,%s' % (
                        'svg+xml' if ext == 'svg' else ext,
                        _b64c.b64encode(fh.read()).decode('ascii'))
    except Exception as e:
        app.logger.warning('[EXT_CONTEXTO] logo: %s', e)

    return _wa_cors(jsonify({
        'ok': True,
        'corretor': corretor,
        'lead': lead,
        'marca': {'nome_curto': BRAND.get('nome_curto') or '',
                  'nome': BRAND.get('nome') or '',
                  'logo': logo_data,
                  'logo_url': BRAND.get('logo_cliente') or BRAND.get('logo') or ''},
    }))


@app.route('/api/whatsapp/extensao/modelos', methods=['GET', 'OPTIONS'])
@requer('crm:ler')
def api_whatsapp_extensao_modelos():
    """Lista os modelos de mensagem de WhatsApp ativos pra extensão mostrar na
    seção Mensagens do painel. Monta a URL de mídia pronta pra extensão não
    precisar saber o padrão de rota.

    A identidade vem do token do aparelho. A extensão mostra conteúdo próprio
    e compartilhado, mas nunca o conteúdo pessoal de outro consultor."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    if not getattr(g, 'usuario_id', None) or not getattr(g, 'usuario', None):
        return _wa_cors(jsonify({'ok': False, 'erro': 'Entre no JOB pelo popup da extensão'})), 401
    uid = g.usuario_id
    conn = db()
    where = "m.tipo='whatsapp' AND m.ativo=1 AND (m.dono_consultor_id = ? OR m.dono_consultor_id IS NULL)"
    params = [uid]
    rows = conn.execute(f"""SELECT m.id, m.nome, m.corpo_texto, m.variante, m.midia_arquivo, m.midia_tipo,
        m.categoria, m.favorito, m.vezes_usado, m.dono_consultor_id, m.pasta_id, u.nome AS dono_nome
        FROM modelos_conteudo m LEFT JOIN usuarios u ON u.id = m.dono_consultor_id
        WHERE {where}
        ORDER BY favorito DESC, (u.nome IS NULL), u.nome, (m.categoria IS NULL), m.categoria, m.nome""", params).fetchall()
    # A extensão precisa do NOME da pasta, não da árvore: manda o caminho já
    # pronto, sem a pasta-mãe (que a extensão já mostra como Minha biblioteca /
    # Compartilhado). Uma consulta à tabela de pastas, não uma por item.
    mapa_pastas = _bib_mapa_pastas(conn)
    close_db(conn)
    modelos = []
    for m in rows:
        md = dict(m)
        caminho = _bib_caminho(mapa_pastas, md.get('pasta_id'))[1:] if md.get('pasta_id') else []
        modelos.append({
            "id": md['id'], "nome": md['nome'], "texto": md['corpo_texto'] or '',
            "variante": md['variante'], "midia_tipo": md['midia_tipo'],
            "categoria": md.get('categoria') or '', "favorito": bool(md.get('favorito')),
            "vezes_usado": md.get('vezes_usado') or 0,
            "dono_nome": md.get('dono_nome') or 'Compartilhado',
            "compartilhado": md.get('dono_consultor_id') is None,
            "pasta": ' / '.join(caminho),
            "pode_editar": True,
            "midia_url": (f"{_SITE_BASE_URL}/crm/modelos/midia/{md['midia_arquivo']}" if md['midia_arquivo'] else None),
        })
    return _wa_cors(jsonify({"ok": True, "gestor": False, "modelos": modelos}))


@app.route('/api/whatsapp/extensao/modelos/novo', methods=['POST', 'OPTIONS'])
@requer('crm:escrever')
def api_whatsapp_extensao_modelo_novo():
    """Cria um modelo de mensagem de WhatsApp DIRETO da extensão (texto sempre;
    mídia opcional — áudio gravado na hora, áudio pronto ou imagem). Autenticado
    por chave de extensão (não sessão) — decisão explícita do Guilherme de poder
    montar a biblioteca inteira sem sair do WhatsApp, igual WaSpeed/ZapVoice.
    criado_por = usuario_id escolhido no popup (pra saber quem cadastrou)."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    if not getattr(g, 'usuario_id', None) or not getattr(g, 'usuario', None):
        return _wa_cors(jsonify({'ok': False, 'erro': 'Entre no JOB pelo popup da extensão'})), 401
    nome = (request.form.get('nome') or '').strip()
    texto = (request.form.get('texto') or '').strip()
    if not nome or not texto:
        return _wa_cors(jsonify({"ok": False, "erro": "Nome e texto são obrigatórios"})), 400
    if len(texto) > 4000:
        return _wa_cors(jsonify({"ok": False, "erro": "Texto longo demais (máx. 4000 caracteres)"})), 400
    criado_por = g.usuario_id
    # dono_consultor_id = quem gravou (mesmo usuario_id) — sem isso, o próprio
    # áudio que a consultora acabou de gravar sumiria da lista dela assim que
    # a extensão passasse a filtrar por dono_consultor_id em vez de criado_por.
    dono_consultor_id = criado_por

    midia_arquivo, midia_tipo = None, None
    f = request.files.get('arquivo_midia')
    if f and f.filename:
        ext = os.path.splitext(f.filename)[1].lower()
        midia_tipo = _midia_tipo_por_ext(ext)
        if not midia_tipo:
            return _wa_cors(jsonify({"ok": False, "erro": f"Formato não aceito: {ext}"})), 400
        f.stream.seek(0, os.SEEK_END)
        tamanho = f.stream.tell()
        f.stream.seek(0)
        if tamanho > 16_000_000:
            return _wa_cors(jsonify({"ok": False, "erro": "Arquivo grande demais (máx. 16MB)"})), 400
        nome_arquivo = f"MODELO_WPP_{datetime.now(TZ_SP).strftime('%Y%m%d%H%M%S')}_{_sanitizar_filename(f.filename)}"
        resultado = upload_arquivo_r2(f.stream, f"modelos/{nome_arquivo}")
        if not resultado.get('ok'):
            return _wa_cors(jsonify({"ok": False, "erro": "Erro ao salvar mídia"})), 500
        midia_arquivo = nome_arquivo

    categoria = (request.form.get('categoria') or '').strip()[:80] or None
    conn = db()
    conn.execute("""INSERT INTO modelos_conteudo
                    (tipo, nome, corpo_texto, ativo, criado_por, midia_arquivo, midia_tipo, categoria, dono_consultor_id)
                    VALUES ('whatsapp',?,?,1,?,?,?,?,?)""",
                 (nome, texto, criado_por, midia_arquivo, midia_tipo, categoria, dono_consultor_id))
    mid = (conn.execute("SELECT lastval() AS id").fetchone()['id'] if DB_MODE == "postgres"
           else conn.execute("SELECT last_insert_rowid() id").fetchone()['id'])
    conn.commit(); close_db(conn)
    return _wa_cors(jsonify({"ok": True, "id": mid}))


