def _nome_copia_disponivel(conn, tabela, nome, dono_consultor_id):
    """Cria um nome de cópia sem tocar no item original."""
    base = f"Cópia de {(nome or 'Sem nome').strip()}"[:200]
    candidato = base
    n = 2
    while conn.execute(
            f"SELECT id FROM {tabela} WHERE nome=? AND COALESCE(dono_consultor_id,0)=COALESCE(?,0)",
            (candidato, dono_consultor_id)).fetchone():
        sufixo = f" ({n})"
        candidato = base[:200 - len(sufixo)] + sufixo
        n += 1
    return candidato


def _duplicar_modelo_whatsapp(conn, mid, usuario_id):
    origem = conn.execute("""SELECT * FROM modelos_conteudo
        WHERE id=? AND tipo='whatsapp' AND ativo=1""", (mid,)).fetchone()
    if not origem:
        return None, 'Mensagem não encontrada'
    origem = dict(origem)
    nome = _nome_copia_disponivel(conn, 'modelos_conteudo', origem['nome'], usuario_id)
    cur = conn.cursor()
    cur.execute("""INSERT INTO modelos_conteudo
        (tipo, nome, assunto, corpo_html, corpo_texto, variante, ativo, criado_por,
         midia_arquivo, midia_tipo, categoria, favorito, vezes_usado, pasta_id, dono_consultor_id)
        VALUES ('whatsapp',?,?,?,?,?,1,?,?,?,?,0,0,NULL,?)""",
        (nome, origem.get('assunto'), origem.get('corpo_html'), origem.get('corpo_texto'),
         origem.get('variante'), usuario_id, origem.get('midia_arquivo'), origem.get('midia_tipo'),
         origem.get('categoria'), usuario_id))
    return _last_insert_id(cur), None


@app.route('/api/whatsapp/extensao/modelos/<int:mid>/duplicar', methods=['POST', 'OPTIONS'])
@requer('crm:escrever')
def api_whatsapp_extensao_modelo_duplicar(mid):
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    if not getattr(g, 'usuario_id', None) or not getattr(g, 'usuario', None):
        return _wa_cors(jsonify({'ok': False, 'erro': 'Entre no JOB pelo popup da extensão'})), 401
    conn = db()
    origem = conn.execute("""SELECT dono_consultor_id FROM modelos_conteudo
        WHERE id=? AND tipo='whatsapp' AND ativo=1""", (mid,)).fetchone()
    if not origem:
        close_db(conn)
        return _wa_cors(jsonify({'ok': False, 'erro': 'Mensagem não encontrada'})), 404
    if origem['dono_consultor_id'] not in (None, g.usuario_id):
        close_db(conn)
        return _wa_cors(jsonify({'ok': False, 'erro': 'Você não tem acesso a esta mensagem'})), 403
    novo_id, erro = _duplicar_modelo_whatsapp(conn, mid, g.usuario_id)
    if erro:
        close_db(conn)
        return _wa_cors(jsonify({'ok': False, 'erro': erro})), 404
    conn.commit(); close_db(conn)
    return _wa_cors(jsonify({'ok': True, 'id': novo_id}))


@app.route('/api/whatsapp/extensao/funis', methods=['GET', 'OPTIONS'])
@requer('crm:ler')
def api_whatsapp_extensao_funis():
    """Lista os funis (sequências de disparo) ativos, cada um com seus passos já
    resolvidos (texto/mídia + delay) — a extensão precisa de tudo pronto pra
    TOCAR a sequência na conversa aberta (envia passo, espera o delay, próximo),
    sem ida-e-volta por passo. O disparo é sempre uma ação explícita do consultor
    na conversa que está na tela — nunca em massa/automático."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    if not getattr(g, 'usuario_id', None) or not getattr(g, 'usuario', None):
        return _wa_cors(jsonify({'ok': False, 'erro': 'Entre no JOB pelo popup da extensão'})), 401
    # A extensão mostra funis próprios e compartilhados, nunca os de colegas.
    uid = g.usuario_id
    conn = db()
    # Não devolve um funil pessoal que ainda aponte para mensagem sem dono ou
    # de outra pessoa: isso vazaria o conteúdo pelo passo, apesar do cabeçalho
    # do funil ser próprio.
    where_f = """f.ativo=1 AND (f.dono_consultor_id = ? OR f.dono_consultor_id IS NULL) AND NOT EXISTS (
        SELECT 1 FROM whatsapp_funil_passos px
        JOIN modelos_conteudo mx ON mx.id=px.modelo_id
        WHERE px.funil_id=f.id AND mx.dono_consultor_id IS NOT NULL AND mx.dono_consultor_id != ?
    )"""
    params_f = [uid, uid]
    funis = conn.execute(f"""SELECT f.id, f.nome, f.categoria, f.favorito, f.vezes_disparado,
            f.dono_consultor_id, f.pasta_id, u.nome AS dono_nome
        FROM whatsapp_funis f LEFT JOIN usuarios u ON u.id = f.dono_consultor_id
        WHERE {where_f}
        ORDER BY favorito DESC, (u.nome IS NULL), u.nome, (f.categoria IS NULL), f.categoria, f.nome""", params_f).fetchall()
    mapa_pastas = _bib_mapa_pastas(conn)
    # Puxa TODOS os passos de uma vez (join com o modelo) e agrupa por funil —
    # evita N+1 e mantém a ordem definida no builder.
    passos = conn.execute("""SELECT p.id AS passo_id, p.funil_id, p.ordem, p.delay_segundos,
            m.id AS modelo_id, m.nome, m.corpo_texto, m.midia_arquivo, m.midia_tipo
        FROM whatsapp_funil_passos p
        JOIN modelos_conteudo m ON m.id = p.modelo_id AND m.tipo='whatsapp' AND m.ativo=1
        ORDER BY p.funil_id, p.ordem, p.id""").fetchall()
    close_db(conn)
    por_funil = {}
    for p in passos:
        pd = dict(p)
        por_funil.setdefault(pd['funil_id'], []).append({
            "passo_id": pd['passo_id'],
            "modelo_id": pd['modelo_id'],
            "nome": pd['nome'],
            "texto": pd['corpo_texto'] or '',
            "delay_segundos": pd['delay_segundos'] or 0,
            "tipo": (pd['midia_tipo'] if pd['midia_tipo'] in ('audio', 'imagem', 'video', 'documento') else 'texto'),
            "midia_url": (f"{_SITE_BASE_URL}/crm/modelos/midia/{pd['midia_arquivo']}" if pd['midia_arquivo'] else None),
        })
    out = []
    for f in funis:
        fd = dict(f)
        caminho = _bib_caminho(mapa_pastas, fd.get('pasta_id'))[1:] if fd.get('pasta_id') else []
        out.append({
            "id": fd['id'], "nome": fd['nome'],
            "categoria": fd.get('categoria') or '', "favorito": bool(fd.get('favorito')),
            "vezes_disparado": fd.get('vezes_disparado') or 0,
            "dono_nome": fd.get('dono_nome') or 'Compartilhado',
            "compartilhado": fd.get('dono_consultor_id') is None,
            "pasta": ' / '.join(caminho),
            "pode_editar": True,
            "passos": por_funil.get(fd['id'], []),
        })
    return _wa_cors(jsonify({"ok": True, "gestor": False, "pode_criar": True, "funis": out}))


