def _wa_extracao_para_qualificacao(ex):
    """Mapeia o dict de extração da conversa (_wa_extrair_lead) pros campos
    qual_* do CRM. Só preenche o que dá pra inferir com confiança direto da
    conversa — nunca inventa (mesma regra da extração em si). qual_tipo_plano
    (Titular/Familiar/Funcionário) e qual_estagio2 (critérios específicos) não
    são preenchidos automaticamente por serem ambíguos/curados manualmente."""
    q = {}
    if ex.get('cidade'):
        q['qual_cidade'] = ex['cidade']
    if ex.get('idades'):
        idades_fmt = ', '.join(str(i) for i in sorted(ex['idades']))
        q['qual_idade'] = f"{idades_fmt} anos"
    elif ex.get('faixa_etaria_texto'):
        q['qual_idade'] = 'Faixa(s): ' + ', '.join(ex['faixa_etaria_texto'])
    if ex.get('cnpj'):
        c = ex['cnpj']
        q['qual_cnpj'] = f"{c[:2]}.{c[2:5]}.{c[5:8]}/{c[8:12]}-{c[12:14]}" if len(c) == 14 else c
    elif ex.get('tem_cnpj') is False:
        q['qual_cnpj'] = 'Não possui'
    if ex.get('plano_ativo') == 'ATIVO' and ex.get('operadora_atual'):
        q['qual_plano_atual'] = ex['operadora_atual'].title()
    elif ex.get('plano_ativo') == 'SEM_PLANO':
        q['qual_plano_atual'] = 'Não possui'
    elif ex.get('plano_ativo') == 'CANCELADO_RECENTE':
        op = f" ({ex['operadora_atual'].title()})" if ex.get('operadora_atual') else ''
        q['qual_plano_atual'] = f"Cancelado recentemente{op}"
    if ex.get('operadora_interesse'):
        q['qual_operadora_interesse'] = ex['operadora_interesse']
        if ex.get('plano_preferido'):
            q['qual_operadora_interesse'] += f" — {ex['plano_preferido']}"
    if ex.get('tipo_contratacao'):
        q['qual_tipo_contratacao'] = {'PJ': 'CNPJ / empresarial', 'ADESAO': 'Adesão (PF)',
                                       'PF': 'Pessoa física'}.get(ex['tipo_contratacao'], ex['tipo_contratacao'])
    return q


def _wa_extracao_para_campos(ex):
    """Mapeia a extração da conversa pros CAMPOS PERSONALIZADOS do CRM.

    Faltava justamente isto: a IA lia a conversa inteira, tirava CNPJ, vidas,
    operadora, plano atual — e nada daquilo chegava na ficha. O consultor via
    "89 mensagens analisadas, score 850" e uma ficha em branco, o que dá a
    impressão correta de que a leitura não serviu pra nada.

    Só devolve o que a conversa disse de fato. O que grava por cima do trabalho
    do consultor não é decidido aqui: quem grava usa so_se_vazio=True."""
    c = {}
    if not isinstance(ex, dict):
        return c
    if ex.get('cnpj'):
        n = re.sub(r'\D', '', str(ex['cnpj']))
        c['cnpj'] = f"{n[:2]}.{n[2:5]}.{n[5:8]}/{n[8:12]}-{n[12:14]}" if len(n) == 14 else str(ex['cnpj'])
    # O campo é um SELECT com opções ["CNPJ","MEI","PF","Adesão"]. Gravava
    # "CNPJ / empresarial" e "Pessoa física" — valores fora da lista, que a ficha
    # exibe como "(fora da lista)": legível, mas sujo, e não filtrável.
    if ex.get('tipo_contratacao_crm'):
        c['tipo_contratacao'] = ex['tipo_contratacao_crm']
    elif ex.get('tipo_contratacao'):
        c['tipo_contratacao'] = {'PJ': 'CNPJ', 'ADESAO': 'Adesão',
                                 'PF': 'PF'}.get(ex['tipo_contratacao'], ex['tipo_contratacao'])
    if ex.get('tipo_plano') in ('Individual', 'Familiar', 'Empresarial', 'Adesão'):
        c['tipo_plano'] = ex['tipo_plano']
    if ex.get('plano_ativo') == 'ATIVO':
        c['tem_plano_hoje'] = 'Sim'
        if ex.get('operadora_atual'):
            c['plano_atual'] = str(ex['operadora_atual']).title()
    elif ex.get('plano_ativo') == 'SEM_PLANO':
        c['tem_plano_hoje'] = 'Não'
    elif ex.get('plano_ativo') == 'CANCELADO_RECENTE':
        c['tem_plano_hoje'] = 'Não (cancelou recentemente)'
        if ex.get('operadora_atual'):
            c['plano_atual'] = str(ex['operadora_atual']).title()
    if ex.get('operadora_interesse'):
        v = str(ex['operadora_interesse'])
        if ex.get('plano_preferido'):
            v += f" — {ex['plano_preferido']}"
        c['operadora_cotada'] = v
    if ex.get('cidade'):
        c['cidade_rmc'] = str(ex['cidade'])
    if ex.get('vidas'):
        c['numero_vidas'] = str(ex['vidas'])
    elif ex.get('idades'):
        c['numero_vidas'] = str(len(ex['idades']))
    # composicao_familiar é MULTISELECT (Cônjuge/Filhos/Pais/Sócio). Escrevia
    # "34 anos, 31 anos" nele — texto que a lista não aceita, dado que morria na
    # tela. As idades já vivem em numero_vidas/idade; aqui vai QUEM entra.
    if ex.get('composicao_familiar'):
        c['composicao_familiar'] = ', '.join(ex['composicao_familiar'])
    if ex.get('idades'):
        c['idade_informada'] = ', '.join(f"{i} anos" for i in sorted(ex['idades']))
    elif ex.get('faixa_etaria_texto'):
        c['idade_informada'] = ', '.join(ex['faixa_etaria_texto'])
    # Campo do tipo 'data' = <input type="date">, que só entende AAAA-MM-DD.
    # A conversa e os documentos falam DD/MM/AAAA — sem esta conversão o campo
    # aparece vazio e o próximo save apaga o que a IA tinha achado.
    if ex.get('nascimento_titular'):
        _m = re.match(r'^(\d{2})/(\d{2})/(\d{4})$', str(ex['nascimento_titular']).strip())
        if _m:
            c['data_nascimento_titular'] = f"{_m.group(3)}-{_m.group(2)}-{_m.group(1)}"
    # VALOR PAGO HOJE: é o que o CLIENTE paga no plano dele. Antes vinha de
    # valor_cotacao — que é o preço da NOSSA proposta. Os dois trocados quebram
    # exatamente a conta que esse campo existe pra fazer (quanto ele economiza).
    if ex.get('valor_pago_hoje'):
        try:
            # Campo do tipo moeda: o input pede "0,00" — o "R$" na frente virava
            # texto que o próprio campo não sabe reler.
            c['valor_pago_hoje'] = f"{float(ex['valor_pago_hoje']):.2f}".replace('.', ',')
        except (TypeError, ValueError):
            pass
    # O campo é do tipo 'mes' — vira <input type="month">, que só aceita AAAA-MM.
    # Gravar "Maio" ali some da tela E é apagado no próximo save. Como o reajuste
    # é anual, o que interessa é a PRÓXIMA ocorrência: é ela que dispara a
    # nutrição ("liga antes do aumento").
    if ex.get('mes_reajuste'):
        try:
            n = _WA_MESES_NOME.index(str(ex['mes_reajuste']).strip().lower()) + 1
            hoje = datetime.now(TZ_SP)
            ano = hoje.year if n > hoje.month else hoje.year + 1
            c['mes_reajuste'] = f"{ano}-{n:02d}"
        except ValueError:
            pass
    if ex.get('hospital_preferencia'):
        c['hospital_preferencia'] = ', '.join(ex['hospital_preferencia'])
    # Saúde e quem decide não têm campo próprio no catálogo — vão pras notas da
    # qualificação, que é onde o consultor lê antes de ligar.
    notas = []
    if ex.get('condicoes_saude'):
        notas.append(f"Saúde: {ex['condicoes_saude']}")
    if ex.get('quem_decide'):
        notas.append(f"Quem decide: {ex['quem_decide']}")
    if notas:
        c['qualificacao_notas'] = ' · '.join(notas)
    return {k: v for k, v in c.items() if str(v or '').strip()}


@app.route('/api/ia/sugerir-planos', methods=['GET', 'OPTIONS'])
def api_ia_sugerir_planos():
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    
    if 'user_id' not in session:
        return _wa_cors(jsonify({"ok": False, "erro": "Não autorizado"})), 401

    lead_id = request.args.get('lead_id')
    if not lead_id:
        return _wa_cors(jsonify({"ok": False, "erro": "lead_id não informado"})), 400
        
    try:
        conn = db()
        lead = conn.execute("SELECT * FROM crm_leads WHERE id=?", (lead_id,)).fetchone()
        if not lead:
            close_db(conn)
            return _wa_cors(jsonify({"ok": False, "erro": "Lead não encontrado"})), 404
            
        # Puxar campos customizados (ex: valor_pago_hoje)
        campos = conn.execute("SELECT campo_id, valor FROM campos_custom WHERE lead_id=?", (lead_id,)).fetchall()
        campos_dict = {c['campo_id']: c['valor'] for c in campos}
        valor_pago = campos_dict.get('valor_pago_hoje', 'Não informado')
            
        concorrentes = conn.execute("SELECT nivel_id, operadora, nome_plano FROM produtos_concorrencia ORDER BY nivel_id, operadora").fetchall()
        close_db(conn)
        
        # Build prompt
        matriz_str = "\\n".join([f"Nível {c['nivel_id']}: {c['operadora']} - {c['nome_plano']}" for c in concorrentes])
        
        prompt = f"""Você é um corretor de planos de saúde sênior. 
Abaixo está o contexto de um lead anonimizado e a matriz de concorrência dos planos de saúde (onde planos no mesmo Nível são concorrentes diretos equivalentes, Níveis maiores são superiores e Níveis menores são inferiores/downgrades).

Lead:
- Plano Atual: {lead.get('qual_plano_atual') or 'Não informado'}
- Idades: {lead.get('qual_idade') or 'Não informado'}
- Cidade: {lead.get('qual_cidade') or 'Não informado'}
- Valor Pago Hoje: {valor_pago}
- Operadora de interesse: {lead.get('qual_operadora_interesse') or 'Não informado'}

Matriz de Concorrência:
{matriz_str}

Com base nesses dados, sugira 2 ou 3 planos específicos presentes na Matriz que façam mais sentido para ele (um downgrade se ele achou caro, ou equivalentes diretos). 
Responda EXCLUSIVAMENTE em formato JSON com o seguinte schema, sem markdown:
{{
  "sugestoes": [
    {{
      "operadora": "nome da operadora",
      "plano": "nome do plano sugerido",
      "motivo": "Por que você sugeriu este plano para ele (um argumento comercial curto)"
    }}
  ],
  "pitch_vendas": "Um rascunho de mensagem curta para o WhatsApp oferecendo essas opções."
}}
"""

        gemini_key = os.environ.get('GEMINI_API_KEY', '').strip()
        
        resultado = None
        
        if gemini_key:
            import requests
            url = f"https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key={gemini_key}"
            payload = {
                "contents": [{"parts": [{"text": prompt}]}],
                "generationConfig": {"response_mime_type": "application/json"}
            }
            res = requests.post(url, json=payload, timeout=15)
            res.raise_for_status()
            data = res.json()
            texto_limpo = data['candidates'][0]['content']['parts'][0]['text'].strip()
            
            import json
            resultado = json.loads(texto_limpo)
            
        else:
            api_key = os.environ.get('ANTHROPIC_API_KEY', '').strip()
            if not api_key:
                return _wa_cors(jsonify({"ok": False, "erro": "Nenhuma chave de IA configurada (Gemini ou Anthropic)"})), 500
                
            try:
                import anthropic
            except Exception as e:
                return _wa_cors(jsonify({"ok": False, "erro": "Pacote anthropic não instalado"})), 500
                
            client = anthropic.Anthropic(api_key=api_key)
            msg = client.messages.create(
                model="claude-3-5-sonnet-20240620",
                max_tokens=1000,
                system="Você retorna apenas JSON válido, sem tags markdown, no formato especificado.",
                messages=[{"role": "user", "content": prompt}]
            )
            
            import json
            texto_limpo = msg.content[0].text.strip()
            if texto_limpo.startswith('```json'):
                texto_limpo = texto_limpo[7:-3].strip()
            elif texto_limpo.startswith('```'):
                texto_limpo = texto_limpo[3:-3].strip()
                
            resultado = json.loads(texto_limpo)
            
        return _wa_cors(jsonify({"ok": True, "resultado": resultado}))
        
    except Exception as e:
        app.logger.error(f"[IA Copiloto] Erro ao sugerir planos: {e}")
        return _wa_cors(jsonify({"ok": False, "erro": str(e)})), 500

