def _normalizar_origem_label(origem):
    """Agrupa as variações de origem em rótulos limpos para métricas."""
    o = (origem or '').strip().lower()
    if not o:
        return 'Manual'
    if 'face' in o or o == 'fb' or 'meta' in o:
        return 'Meta'
    if 'google' in o:
        return 'Google'
    if 'meds' in o:
        return 'MedSênior'
    if 'manual' in o:
        return 'Manual'
    return (origem or 'Outros').strip().split('(')[0].strip().title()



def _crm_fila_acao(conn, uid, eh_admin):
    """Os quatro numeros que dizem o que esta travando o funil AGORA.

    Vivem no /crm, nao no painel: sao trabalho do dia, e trabalho tem que estar
    onde a pessoa ja esta. O painel ficou so com o relatorio do mes, que se olha
    de vez em quando — juntos, um atrapalhava o outro.

    Conta por SQL agregado, nao carregando os 5 mil leads em memoria como o
    painel faz: isto roda em TODA abertura do CRM e nao pode pesar."""
    from datetime import timedelta as _td
    hoje = datetime.now(TZ_SP)
    corte_novo = (hoje - _td(days=30)).strftime('%Y-%m-%d')
    corte_parado = (hoje - _td(days=7)).strftime('%Y-%m-%d')
    corte_frio = (hoje - _td(days=60)).strftime('%Y-%m-%d')

    dono = "" if eh_admin else " AND l.responsavel_id=?"
    p = [] if eh_admin else [uid]
    # Etapa aberta = nem ganho nem perdido.
    abertas = """l.etapa IN (SELECT slug FROM crm_etapas
                             WHERE ativo=1 AND COALESCE(tipo,'normal')='normal')"""
    teve = """EXISTS (SELECT 1 FROM crm_atividades a WHERE a.lead_id=l.id
                      AND a.tipo IN ('whatsapp','atividade','nota','email','ligacao'))"""
    frio = f"(l.responsavel_id IS NULL AND NOT {teve} AND substr(CAST(l.criado_em AS TEXT),1,10) < ?)"

    def _um(sql, extra):
        try:
            r = conn.execute(f"SELECT COUNT(*) c FROM crm_leads l WHERE {abertas}{dono} AND {sql}",
                             p + extra).fetchone()
            return int((r['c'] if hasattr(r, 'keys') else r[0]) or 0)
        except Exception as e:
            app.logger.info(f"[CRM] fila: {e}")
            try: conn.rollback()
            except Exception: pass
            return 0

    return {
        'sem_dono': _um(f"NOT {frio} AND l.responsavel_id IS NULL "
                        "AND substr(CAST(l.criado_em AS TEXT),1,10) >= ?", [corte_frio, corte_novo]),
        'sem_contato': _um(f"NOT {frio} AND NOT {teve}", [corte_frio]),
        'parados': _um(f"NOT {frio} AND COALESCE(substr(CAST(l.avancou_em AS TEXT),1,10), "
                       "substr(CAST(l.criado_em AS TEXT),1,10)) < ?", [corte_frio, corte_parado]),
        'frios': _um(frio.replace('(', '(', 1), [corte_frio]),
        'corte_novo': corte_novo,
    }



def _agenda_medicao(conn, dias=30):
    """A agenda esta funcionando? Com numero, nao com impressao.

    Mediana e p95, nunca media: uma tarefa concluida tres semanas depois desloca
    a media inteira e some da mediana — e e a mediana que descreve o dia normal.

    Este e o passo que torna possivel aprender depois. Sem medir a regra hoje,
    qualquer modelo daqui a tres meses vai aprender ruido com cara de padrao."""
    from datetime import timedelta as _td
    desde = (datetime.now(TZ_SP) - _td(days=dias)).strftime('%Y-%m-%d')
    hoje = datetime.now(TZ_SP).strftime('%Y-%m-%d')

    linhas = []
    for chave, r in _AGENDA_POR_CHAVE.items():
        criadas = conn.execute("""SELECT COUNT(*) c FROM crm_agenda
                                  WHERE regra=? AND SUBSTR(criado_em,1,10) >= ?""",
                               (chave, desde)).fetchone()['c']
        if not criadas:
            continue
        feitas = conn.execute("""SELECT COUNT(*) c FROM crm_agenda
                                 WHERE regra=? AND status='concluida'
                                   AND SUBSTR(criado_em,1,10) >= ?""",
                              (chave, desde)).fetchone()['c']
        atrasadas = conn.execute("""SELECT COUNT(*) c FROM crm_agenda
                                    WHERE regra=? AND status='pendente'
                                      AND SUBSTR(data_hora,1,10) < ?""",
                                 (chave, hoje)).fetchone()['c']
        # Adiada varias vezes nao e adiamento, e recusa — e o numero que mostra
        # qual regra o time ignora na pratica.
        recusadas = conn.execute("""SELECT COUNT(*) c FROM crm_agenda
                                    WHERE regra=? AND COALESCE(adiada_vezes,0) >= 3
                                      AND SUBSTR(criado_em,1,10) >= ?""",
                                 (chave, desde)).fetchone()['c']
        # Horas entre criar e concluir, so das que foram concluidas.
        horas = []
        for x in conn.execute("""SELECT criado_em, concluida_em FROM crm_agenda
                                 WHERE regra=? AND status='concluida'
                                   AND concluida_em IS NOT NULL
                                   AND SUBSTR(criado_em,1,10) >= ?""",
                              (chave, desde)).fetchall():
            a1, b1 = _parse_dt_seguro(x['criado_em']), _parse_dt_seguro(x['concluida_em'])
            if a1 and b1:
                h = (b1.replace(tzinfo=None) - a1.replace(tzinfo=None)).total_seconds() / 3600
                if 0 <= h < 24 * 90:
                    horas.append(h)
        horas.sort()
        def _pct(p):
            if not horas:
                return None
            i = min(len(horas) - 1, int(round((len(horas) - 1) * p)))
            return round(horas[i], 1)
        # Virou venda? So conta lead que teve tarefa desta regra.
        ganhos = conn.execute("""SELECT COUNT(DISTINCT a.lead_id) c
                                   FROM crm_agenda a
                                   JOIN crm_leads l ON l.id = a.lead_id
                                   JOIN crm_etapas e ON e.slug = l.etapa AND e.tipo='ganho'
                                  WHERE a.regra=? AND SUBSTR(a.criado_em,1,10) >= ?""",
                              (chave, desde)).fetchone()['c']
        linhas.append({
            'chave': chave, 'nome': r['titulo'], 'criadas': criadas, 'feitas': feitas,
            'cumprimento': round(feitas / criadas * 100, 1) if criadas else 0,
            'atrasadas': atrasadas, 'recusadas': recusadas,
            'p50': _pct(0.50), 'p95': _pct(0.95), 'ganhos': ganhos,
            'amostra_ok': feitas >= 20,
        })
    linhas.sort(key=lambda x: -x['criadas'])

    por_pessoa = [dict(r) for r in conn.execute("""
        SELECT u.nome,
               SUM(CASE WHEN a.status='concluida' THEN 1 ELSE 0 END) feitas,
               SUM(CASE WHEN a.status='pendente' THEN 1 ELSE 0 END) abertas,
               SUM(CASE WHEN a.status='pendente' AND SUBSTR(a.data_hora,1,10) < ? THEN 1 ELSE 0 END) atrasadas
          FROM crm_agenda a JOIN usuarios u ON u.id = a.usuario_id
         WHERE SUBSTR(a.criado_em,1,10) >= ?
         GROUP BY u.nome ORDER BY atrasadas DESC, feitas DESC""", (hoje, desde)).fetchall()]

    tot_c = sum(x['criadas'] for x in linhas)
    tot_f = sum(x['feitas'] for x in linhas)
    return {
        'dias': dias, 'linhas': linhas, 'por_pessoa': por_pessoa,
        'criadas': tot_c, 'feitas': tot_f,
        'cumprimento': round(tot_f / tot_c * 100, 1) if tot_c else 0,
        # Abaixo disso qualquer taxa e ruido — e dizer isso na tela evita que
        # alguem tome decisao em cima de tres tarefas.
        'confiavel': tot_f >= 30,
    }


@app.route('/crm/painel')
@login_required
def crm_painel():
    """Painel RevOps do CRM: conversão, funil, origem, performance por consultor, SLA de contato."""
    conn = db()
    eh_admin = session.get('perfil') == 'admin'
    uid = session['user_id']

    f_de = request.args.get('data_de', '').strip()
    f_ate = request.args.get('data_ate', '').strip()

    etapas = conn.execute(
        "SELECT slug, nome, tipo, ordem, cor FROM crm_etapas WHERE ativo=1 ORDER BY ordem, id"
    ).fetchall()
    etapa_tipo = {e['slug']: (e['tipo'] or 'normal') for e in etapas}
    etapa_nome = {e['slug']: e['nome'] for e in etapas}
    etapa_cor = {e['slug']: (e['cor'] or '#3b82f6') for e in etapas}
    etapa_ordem = [e['slug'] for e in etapas]

    q = ("SELECT id, etapa, responsavel_id, origem, criado_em, valor_estimado, "
         "perdido_motivo, avancou_em FROM crm_leads WHERE 1=1")
    params = []
    if not eh_admin:
        q += " AND responsavel_id=?"; params.append(uid)
    if f_de:
        q += " AND DATE(criado_em) >= ?"; params.append(f_de)
    if f_ate:
        q += " AND DATE(criado_em) <= ?"; params.append(f_ate)
    leads = conn.execute(q, params).fetchall()

    usuarios = {u['id']: u['nome'] for u in conn.execute("SELECT id, nome FROM usuarios").fetchall()}

    # Leads que tiveram algum contato real (não só criação/movimentação automática)
    contato_ids = set()
    try:
        rows = conn.execute(
            "SELECT DISTINCT lead_id FROM crm_atividades WHERE tipo IN ('whatsapp','atividade','nota','email','ligacao')"
        ).fetchall()
        contato_ids = {(r['lead_id'] if hasattr(r, 'keys') else r[0]) for r in rows}
    except Exception:
        pass
    close_db(conn)

    # ── BASE FRIA SAI DA CONTA ────────────────────────────────────────────────
    # Lead aberto, sem dono e sem nenhum contato ha mais de 60 dias nao e
    # pipeline: e historico. Deixar isso no denominador fazia a conversao medir
    # uma coisa que ninguem trabalhou — o painel dizia 5,3% de conversao com 96%
    # da base nunca tocada, e os dois numeros nao falavam do mesmo assunto.
    from datetime import timedelta as _td
    corte_frio = (datetime.now(TZ_SP) - _td(days=60)).strftime('%Y-%m-%d')
    corte_novo = (datetime.now(TZ_SP) - _td(days=30)).strftime('%Y-%m-%d')
    corte_parado = (datetime.now(TZ_SP) - _td(days=7)).strftime('%Y-%m-%d')

    def _dia(v):
        return str(v or '')[:10]

    frios, sem_dono_novos, parados = 0, 0, 0
    total = len(leads)
    ganhos = perdidos = aberto = sem_contato = 0
    pipeline_valor = 0.0
    por_etapa = {s: 0 for s in etapa_ordem}
    por_origem = {}
    por_consultor = {}
    motivos_perda = {}

    for l in leads:
        et = l['etapa'] or (etapa_ordem[0] if etapa_ordem else '')
        tipo = etapa_tipo.get(et, 'normal')
        por_etapa[et] = por_etapa.get(et, 0) + 1

        if tipo == 'ganho':
            ganhos += 1
        elif tipo == 'perdido':
            perdidos += 1
            mot = (l['perdido_motivo'] or '').strip() or 'Não informado'
            motivos_perda[mot] = motivos_perda.get(mot, 0) + 1
        else:
            eh_frio = (not l['responsavel_id'] and l['id'] not in contato_ids
                       and _dia(l['criado_em']) and _dia(l['criado_em']) < corte_frio)
            if eh_frio:
                frios += 1
                continue          # base fria nao entra em pipeline nem em conversao
            aberto += 1
            pipeline_valor += float(l['valor_estimado'] or 0)
            if l['id'] not in contato_ids:
                sem_contato += 1
            # A FILA DE TRABALHO: sem dono e ainda quente, e parado ha uma semana.
            if not l['responsavel_id'] and _dia(l['criado_em']) >= corte_novo:
                sem_dono_novos += 1
            ult = _dia(l['avancou_em']) or _dia(l['criado_em'])
            if ult and ult < corte_parado:
                parados += 1

        org = _normalizar_origem_label(l['origem'])
        do = por_origem.setdefault(org, {'total': 0, 'ganhos': 0, 'perdidos': 0})
        do['total'] += 1
        if tipo == 'ganho':
            do['ganhos'] += 1
        elif tipo == 'perdido':
            do['perdidos'] += 1

        nome = usuarios.get(l['responsavel_id'], 'Sem responsável')
        c = por_consultor.setdefault(nome, {'total': 0, 'ganhos': 0, 'perdidos': 0, 'aberto': 0})
        c['total'] += 1
        if tipo == 'ganho':
            c['ganhos'] += 1
        elif tipo == 'perdido':
            c['perdidos'] += 1
        else:
            c['aberto'] += 1

    decididos = ganhos + perdidos
    taxa_conv = round(ganhos / decididos * 100, 1) if decididos else 0.0
    taxa_contato = round((aberto - sem_contato) / aberto * 100, 1) if aberto else 0.0

    # Monta estruturas ordenadas para o template
    funil = [{'nome': etapa_nome.get(s, s), 'cor': etapa_cor.get(s, '#3b82f6'),
              'qtd': por_etapa.get(s, 0),
              'pct': round(por_etapa.get(s, 0) / total * 100, 1) if total else 0}
             for s in etapa_ordem]
    # UMA definicao de conversao na tela inteira: ganhos sobre DECIDIDOS.
    #
    # Estava com duas. Origem dividia por TODOS os leads e consultor dividia so
    # pelos decididos — as duas chamadas de "conversao", uma do lado da outra.
    # Dava pra ler que o Guilherme converte 60% e a Meta 0,3%, numeros que nao
    # se comparam de jeito nenhum. Lead em aberto ainda pode virar os dois lados;
    # conta-lo como perdido faz a taxa mentir pra baixo.
    #
    # E o DENOMINADOR VAI JUNTO. 60% de 5 decisoes e ruido; 4,7% de 85 e sinal.
    # Sem a base do lado, os dois numeros parecem a mesma coisa — foi por isso
    # que a tela ficou "sem funcao real".
    _BASE_MINIMA = 10

    def _conv(ganhos_, perdidos_):
        dec = ganhos_ + perdidos_
        return {'decididos': dec,
                'conv': round(ganhos_ / dec * 100, 1) if dec else None,
                'confiavel': dec >= _BASE_MINIMA}

    origens = sorted(
        [{'nome': k, 'total': v['total'], 'ganhos': v['ganhos'],
          'perdidos': v.get('perdidos', 0),
          'pct': round(v['total'] / total * 100, 1) if total else 0,
          **_conv(v['ganhos'], v.get('perdidos', 0))}
         for k, v in por_origem.items()],
        key=lambda x: -x['total'])
    consultores = sorted(
        [{'nome': k, **v, **_conv(v['ganhos'], v['perdidos'])}
         for k, v in por_consultor.items()],
        key=lambda x: -x['total'])
    perdas = sorted([{'motivo': k, 'qtd': v} for k, v in motivos_perda.items()], key=lambda x: -x['qtd'])

    cards = {
        'total': total, 'ganhos': ganhos, 'perdidos': perdidos, 'aberto': aberto,
        'taxa_conv': taxa_conv, 'pipeline_valor': pipeline_valor,
        'sem_contato': sem_contato, 'taxa_contato': taxa_contato,
        # O que precisa de acao hoje, separado do que e resultado do periodo.
        'frios': frios, 'sem_dono': sem_dono_novos, 'parados': parados,
        'corte_novo': corte_novo,
        'trabalhaveis': total - frios,
    }

    # A MEDICAO DA AGENDA MORA AQUI, nao num item novo do menu. O menu ja tem 25
    # itens; tela nova entra dentro de uma que existe.
    conn3 = db()
    try:
        medicao = _agenda_medicao(conn3)
    except Exception as e:
        app.logger.info(f"[AGENDA] medicao: {e}")
        medicao = None
    finally:
        close_db(conn3)
    return render_template('crm_painel.html', cards=cards, funil=funil, origens=origens,
                           medicao=medicao,
                           consultores=consultores, perdas=perdas, eh_admin=eh_admin,
                           filtros={'data_de': f_de, 'data_ate': f_ate})


# ─── COTAÇÃO / MULTICÁLCULO ──────────────────────────────────────────────────
# Faixas etárias padrão ANS (10 faixas).
FAIXAS_ETARIAS = ['00-18', '19-23', '24-28', '29-33', '34-38', '39-43', '44-48', '49-53', '54-58', '59+']
COTACAO_MODALIDADES = ['PME', 'PF', 'Adesão']
COTACAO_ACOMODACOES = ['Enfermaria', 'Apartamento']
COTACAO_COPART = ['Sem', 'Parcial', 'Total']


def _faixa_da_idade(idade):
    """Retorna a faixa etária ANS para uma idade inteira."""
    try:
        i = int(idade)
    except Exception:
        return None
    limites = [(18, '00-18'), (23, '19-23'), (28, '24-28'), (33, '29-33'), (38, '34-38'),
               (43, '39-43'), (48, '44-48'), (53, '49-53'), (58, '54-58')]
    for lim, faixa in limites:
        if i <= lim:
            return faixa
    return '59+'


def _parse_idades(texto):
    """Extrai idades de um texto livre. Aceita idade (ex: 25) OU data de nascimento
    (ex: 15/03/1990) — converte a data em idade. Ex: '25, 30 e 15/03/1990'."""
    if not texto:
        return []
    hoje = datetime.now(TZ_SP).date()
    idades = []
    for parte in re.split(r'[,;\n]| e ', str(texto)):
        p = parte.strip()
        if not p:
            continue
        m = re.match(r'^(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2,4})$', p)
        if m:
            d, mo, a = int(m.group(1)), int(m.group(2)), int(m.group(3))
            if a < 100:
                a += 2000 if a <= 30 else 1900
            try:
                nasc = date(a, mo, d)
                idade = hoje.year - nasc.year - ((hoje.month, hoje.day) < (nasc.month, nasc.day))
                if 0 <= idade <= 120:
                    idades.append(idade)
                continue
            except Exception:
                pass
        nums = re.findall(r'\d+', p)
        if nums:
            idades.append(int(nums[0]))
    return idades[:50]


