def _copart_texto(tb):
    """'Sem' / 'Parcial' / 'Completa', do jeito que a apresentacao ja mostra."""
    if not (tb or {}).get('coparticipacao'):
        return 'Sem'
    t = str((tb or {}).get('coparticipacaoTipo') or '').strip().lower()
    if 'parcial' in t:
        return 'Parcial'
    if any(x in t for x in ('total', 'complet', 'integral')):
        return 'Completa'
    return 'Com'


def _acomodacao_do_payload(pl):
    """A palavra da acomodacao a partir do que o plano trouxe, sem chutar.

    Devolve '' quando o payload nao diz — e '' aqui significa NAO SEI, nao
    'Enfermaria'. Quem chama decide se procura noutro lugar.
    """
    bruto = (pl or {}).get('acomodacaoTxt')
    if bruto in (None, ''):
        bruto = (pl or {}).get('acomodacao')
    if isinstance(bruto, str):
        return bruto.strip()
    if isinstance(bruto, bool):
        return 'Apartamento' if bruto else 'Enfermaria'
    if isinstance(bruto, (int, float)):
        # `is True` / `is False` nao servia: JSON manda 1/0 e o valor sumia.
        return 'Apartamento' if bruto else 'Enfermaria'
    return ''


def _acomodacao_da_base(conn, operadora, plano, modalidade):
    """Ultima tentativa antes de desistir: a palavra que a base ja tem gravada.

    Existe porque CHUTAR E PIOR QUE NAO SABER. O codigo antigo devolvia
    'Enfermaria' pra tudo que nao fosse claramente apartamento — e escrevia
    'Enfermaria' num plano Ambulatorial, no documento que vai pro cliente.
    621bbd7 tirou o chute e passou a devolver vazio, o que sumiu com a linha
    inteira da apresentacao. Nenhum dos dois e aceitavel: o certo e perguntar.
    """
    if not operadora or not plano:
        return ''
    try:
        q = ("SELECT acomodacao FROM cotacao_tabela "
             "WHERE LOWER(operadora)=LOWER(?) AND LOWER(plano)=LOWER(?) "
             "AND COALESCE(acomodacao,'') <> ''")
        par = [str(operadora).strip(), str(plano).strip()]
        if modalidade:
            q += " AND LOWER(modalidade)=LOWER(?)"
            par.append(str(modalidade).strip())
        # Sem desempate: se a mesma dupla operadora+plano tiver acomodacoes
        # diferentes, nao da pra saber qual e a desta cotacao — e ai vazio e a
        # resposta honesta.
        achados = {str(r['acomodacao']).strip()
                   for r in conn.execute(q + " LIMIT 20", par).fetchall()}
        return achados.pop() if len(achados) == 1 else ''
    except Exception:
        return ''


def _viva_para_apresentacao(d):
    """Traduz a cotacao ao vivo pro formato que o documento do cliente ja usa.

    Reaproveitar em vez de refazer: o documento, o link publico, o PDF, o envio
    por WhatsApp e a nova versao ja existem e ja foram testados em cima da
    `cotacao_salva`. Fazer a tela nova gravar tambem nesse formato entrega toda
    essa experiencia de uma vez, e sem duplicar regra de apresentacao."""
    planos, total_geral, cont_faixa = [], 0.0, {}
    _conn_acom = [None]        # so abre se algum plano vier sem acomodacao
    for p in (d.get('planos') or []):
        if p.get('total') is None:
            continue          # plano sem preco nao vai pra proposta do cliente
        linhas = []
        elegivel = True
        for f in (p.get('faixas') or []):
            fx = _faixa_do_painel(f.get('faixa'))
            qtd = int(f.get('quantidade') or 0)
            if qtd <= 0:
                continue
            preco = float(f.get('unitario') or 0)
            if preco <= 0:
                elegivel = False
            cont_faixa[fx] = qtd
            linhas.append({'faixa': fx, 'label': _faixa_label(fx), 'qtd': qtd,
                           'preco': preco, 'subtotal': round(preco * qtd, 2)})
        tb = p.get('tabela') or {}
        total = float(p.get('total') or 0)
        if elegivel:
            total_geral += total
        pl = p.get('plano') or {}
        acomodacao = _acomodacao_do_payload(pl)
        if not acomodacao:
            # Nao sabemos pelo que veio; a base pode saber. Conexao aberta so
            # aqui, e uma vez por cotacao — o caminho normal nem chega neste if.
            #
            # `db()` SEM GUARDA DERRUBAVA O SALVAMENTO INTEIRO.
            #
            # Uma soletrada no Postgres (pico de conexoes, restart) nesta linha
            # jogava a excecao pra fora de _viva_para_apresentacao sem ser
            # pega em lugar nenhum, e o consultor via "Nao foi possivel salvar
            # a cotacao" — pra um problema que nao tinha nada a ver com o
            # preco ou o plano dele. Acomodacao desconhecida e so isso: '' e
            # sempre uma resposta aceitavel aqui, nunca motivo pra falhar a
            # cotacao inteira.
            try:
                if _conn_acom[0] is None:
                    _conn_acom[0] = db()
                acomodacao = _acomodacao_da_base(
                    _conn_acom[0],
                    (p.get('operadora') or {}).get('nome'),
                    pl.get('nome'),
                    p.get('_tipo'))
            except Exception:
                acomodacao = ''
        planos.append({
            'operadora': (p.get('operadora') or {}).get('nome') or '',
            'plano': (p.get('plano') or {}).get('nome') or '',
            'modalidade': p.get('_tipo') or '',
            'acomodacao': acomodacao,
            'coparticipacao': _copart_texto(tb),
            'abrangencia': (p.get('produto') or {}).get('nome') or '',
            'vigencia': '',
            'linhas': linhas, 'total': round(total, 2), 'recomendacao': '',
            'elegivel': elegivel,
        })
    if _conn_acom[0] is not None:
        close_db(_conn_acom[0])
    return planos, round(total_geral, 2), cont_faixa


@app.route('/cotacao/viva/salvar', methods=['POST'])
@login_required
def cotacao_viva_salvar():
    d = request.get_json(silent=True) or {}
    # SEM LEAD NÃO SALVA.
    #
    # A trava da tela é conveniência; esta é a que vale. Cotação sem lead não
    # volta como conversão pra Meta nem pro Google, e o funil não fica sabendo
    # que aquele lead recebeu proposta — foi assim que 25 de 48 vendas ficaram
    # órfãs, e o "o JOB tenta casar pelo telefone" que existia antes é
    # exatamente o "tenta" onde elas se perdiam.
    try:
        _lead = int(d.get('lead_id') or 0)
    except (TypeError, ValueError):
        _lead = 0
    if not _lead:
        return jsonify({'ok': False, 'erro': 'sem_lead',
                        'mensagem': 'Ligue a cotação a um lead do CRM antes de salvar.'}), 400

    conn = db()
    try:
        vid = _cotacao_viva_gravar(conn, d, session.get('user_id'), 'site')
    except ValueError as e:
        return jsonify({'ok': False, 'erro': str(e)}), 400
    except Exception:
        conn.rollback()
        return jsonify({'ok': False, 'erro': 'falha_ao_salvar'}), 500

    # Alem do historico, a cotacao entra na apresentacao de sempre.
    planos, total_geral, cont_faixa = _viva_para_apresentacao(d)
    if not planos:
        return jsonify({'ok': True, 'id': vid, 'url': '/cotacao/viva/%d' % vid,
                        'aviso': 'nenhum plano com preco'})

    try:
        lead_id = int(d.get('lead_id')) if d.get('lead_id') else None
    except Exception:
        lead_id = None
    cliente_tel = str(d.get('cliente_telefone') or '').strip()
    cliente_email = str(d.get('cliente_email') or '').strip()
    # Sem lead escolhido, tenta casar por telefone e e-mail — mesmo casador do
    # CRM e da venda. Cotacao orfa e o comeco de venda sem origem de midia.
    if not lead_id:
        try:
            tel_norm = _normalizar_telefone(cliente_tel)
            row = _buscar_lead_por_telefone(conn, tel_norm) if tel_norm else None
            if not row and cliente_email:
                row = conn.execute("SELECT id FROM crm_leads WHERE LOWER(email)=LOWER(?)",
                                   (cliente_email,)).fetchone()
            if row:
                lead_id = row['id'] if hasattr(row, 'keys') else row[0]
        except Exception:
            lead_id = None

    urow = conn.execute("SELECT nome, email FROM usuarios WHERE id=?",
                        (session.get('user_id'),)).fetchone()
    token = secrets.token_urlsafe(9)
    try:
        mods = sorted(list(set(p.get('modalidade') for p in planos if p.get('modalidade'))))
        modalidades_json = json.dumps(mods, ensure_ascii=False) if mods else '[]'

        conn.execute("""INSERT INTO cotacao_salva
            (token, orientacao, lead_id, corretor_id, corretor_nome, corretor_email,
             corretor_telefone, cliente_nome, cliente_email, cliente_telefone, titulo,
             vidas_json, planos_json, total, tabela_ids_json, cidade, modalidades)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (token, 'horizontal', lead_id, session.get('user_id'),
             (urow['nome'] if urow else '') or session.get('nome') or '',
             (urow['email'] if urow else '') or '', '',
             str(d.get('cliente_nome') or '').strip(), cliente_email, cliente_tel,
             str(d.get('titulo') or 'Cotação').strip(),
             json.dumps(cont_faixa), json.dumps(planos, ensure_ascii=False),
             total_geral, '[]', str(d.get('cidade') or '').strip(), modalidades_json))
        cid = _last_insert_id(conn.cursor() if hasattr(conn, 'cursor') else conn)
        if not cid:
            cid = (conn.execute("SELECT lastval() AS id").fetchone()['id'] if DB_MODE == 'postgres'
                   else conn.execute("SELECT last_insert_rowid() id").fetchone()['id'])
        try:
            registrar_cotacao_no_lead(conn, lead_id, cid, planos, total_geral, [],
                                      str(d.get('titulo') or '').strip())
        except Exception:
            pass          # o registro no lead e ganho, nao requisito da cotacao
        conn.commit()
    except Exception:
        conn.rollback()
        return jsonify({'ok': True, 'id': vid, 'url': '/cotacao/viva/%d' % vid,
                        'aviso': 'salvou o historico, mas nao gerou a apresentacao'})
    return jsonify({'ok': True, 'id': vid, 'documento': cid, 'lead_id': lead_id,
                    'url': '/cotacao/documento/%d' % cid})


