        cur = conn.execute(
            """INSERT INTO catalogo_varredura (usuario_id, iniciado_em, alvos, estado)
               VALUES (?,?,?,'rodando')""",
            (session.get('user_id'), _agora_sp(), int(d.get('alvos') or 0)))
