@app.route('/cotacao/tabela/importar', methods=['POST'])
@login_required
@admin_required
def cotacao_tabela_importar_json():
    """
    Importa um lote de tabelas de preço vindo do extrator de PDF da operadora.
    O formato do payload é definido no contrato: handoff/contrato-importar-tabela-de-pdf.md
    """
    payload = request.get_json(silent=True) or {}
    operadora = str(payload.get('operadora') or '').strip()[:120]
    fonte = str(payload.get('fonte') or 'pdf').strip()[:20]
    vigencia_pdf = str(payload.get('vigencia_pdf') or '').strip()[:40]
    tabelas = payload.get('tabelas') or []

    if not operadora or not tabelas:
        return jsonify({"ok": False, "erro": "Payload inválido: falta operadora ou tabelas"}), 400

    agora = _agora_sp()
    criadas = 0
    atualizadas = 0
    recusadas = 0
    precos_trocados = []

    # db(), nao get_db(): get_db nao existe neste app e a rota estourava
    # NameError em toda chamada — 500 antes de gravar qualquer linha.
    conn = db()
    for t in tabelas:
        vidas_min = t.get('vidas_min')
        vidas_max = t.get('vidas_max')
        copart = str(t.get('coparticipacao') or '').strip()

        # Regra 2: Recuse a tabela sem vidas_min/vidas_max ou sem coparticipacao
        if vidas_min is None or vidas_max is None or not copart:
            recusadas += 1
            continue

        try: vidas_min = int(vidas_min)
        except Exception: vidas_min = 0
        try: vidas_max = int(vidas_max)
        except Exception: vidas_max = 0

        plano = str(t.get('plano') or '').strip()[:160]
        codigo = str(t.get('codigo') or '').strip()[:60]
        modalidade = str(t.get('modalidade') or 'PME').strip()[:40]
        acomodacao = str(t.get('acomodacao') or 'Enfermaria').strip()[:40]
        linha = str(t.get('linha') or '').strip()[:160]
        abrangencia = str(t.get('abrangencia') or '').strip()[:120]
        administradora = str(t.get('administradora') or '').strip()[:120]
        cidade = str(t.get('cidade') or '').strip()[:120]
        mei = 1 if t.get('mei') else 0

        # Verifica se já existe a chave exata
        ex = conn.execute(
            """SELECT id FROM cotacao_tabela 
               WHERE operadora=? AND plano=? AND modalidade=?
                 AND acomodacao=? AND coparticipacao=? AND COALESCE(cidade,'')=?
                 AND COALESCE(linha,'')=? AND COALESCE(abrangencia,'')=? AND COALESCE(administradora,'')=?
                 AND COALESCE(vidas_min, 0)=? AND COALESCE(vidas_max, 0)=? AND COALESCE(mei, 0)=?
                 AND COALESCE(entidade,'')=''""",
            (operadora, plano, modalidade, acomodacao, copart, cidade, 
             linha, abrangencia, administradora, vidas_min, vidas_max, mei)
        ).fetchone()

        if ex:
            tid = ex['id']
            conn.execute(
                """UPDATE cotacao_tabela 
                   SET ativo=1, atualizado_em=?, codigo=?, fonte=?, vigencia_pdf=? 
                   WHERE id=?""",
                (agora, codigo, fonte, vigencia_pdf, tid)
            )
            atualizadas += 1
        else:
            conn.execute(
                """INSERT INTO cotacao_tabela
                     (operadora, plano, modalidade, acomodacao, coparticipacao,
                      cidade, entidade, linha, abrangencia, administradora, 
                      ativo, atualizado_em, vidas_min, vidas_max, mei, 
                      codigo, fonte, vigencia_pdf)
                   VALUES (?,?,?,?,?,?,?,?,?,?,1,?,?,?,?,?,?,?)""",
                (operadora, plano, modalidade, acomodacao, copart,
                 cidade, '', linha, abrangencia, administradora,
                 agora, vidas_min, vidas_max, mei, codigo, fonte, vigencia_pdf)
            )
            tid = (conn.execute("SELECT lastval() AS id").fetchone()['id'] if DB_MODE == 'postgres'
                   else conn.execute("SELECT last_insert_rowid() id").fetchone()['id'])
            criadas += 1

        faixas = t.get('faixas') or {}
        for fx, val in faixas.items():
            fx = str(fx).strip()
            if fx not in FAIXAS_ETARIAS:
                continue
            try:
                valor = float(val)
            except (TypeError, ValueError):
                continue
            if valor <= 0:
                continue
            
            achou = conn.execute("SELECT id, preco FROM cotacao_preco WHERE tabela_id=? AND faixa=?", (tid, fx)).fetchone()
            if achou:
                preco_antigo = float(achou['preco'])
                if abs(preco_antigo - valor) > 0.01:
                    precos_trocados.append({
                        "plano": plano,
                        "faixa": fx,
                        "de": preco_antigo,
                        "para": valor
                    })
                    app.logger.info(f"[COTACAO] Importação PDF - Preço trocado: {operadora}/{plano} faixa {fx} R${preco_antigo} -> R${valor}")
                conn.execute("UPDATE cotacao_preco SET preco=? WHERE id=?", (valor, achou['id']))
            else:
                conn.execute("INSERT INTO cotacao_preco (tabela_id, faixa, preco) VALUES (?,?,?)", (tid, fx, valor))

    if DB_MODE == 'postgres':
        try: conn.commit()
        except Exception: pass
    else:
        conn.commit()
    close_db(conn)

    return jsonify({
        "ok": True,
        "criadas": criadas,
        "atualizadas": atualizadas,
        "recusadas": recusadas,
        "precos_trocados": precos_trocados
    })


@app.route('/cotacao/tabelas/importar', methods=['GET', 'POST'])
@login_required
@admin_required
def cotacao_import():
    if request.method == 'GET':
        return render_template('cotacao_import.html', faixas=FAIXAS_ETARIAS)

    f = request.files.get('arquivo')
    if not f or not f.filename:
        return render_template('cotacao_import.html', faixas=FAIXAS_ETARIAS, erro='Selecione um arquivo.')

    nome = f.filename.lower()
    rows = []
    try:
        if nome.endswith('.xlsx'):
            import openpyxl
            wb = openpyxl.load_workbook(f, read_only=True, data_only=True)
            ws = wb.active
            def _celula_texto(c):
                if c is None:
                    return ''
                # Excel guarda telefone/CNPJ como número quando a coluna não é
                # formatada como texto — openpyxl devolve float (19988608662.0).
                # str() direto grudaria um "0" extra no final ao tirar o ".0".
                if isinstance(c, float) and c.is_integer():
                    return str(int(c))
                return str(c)
            for r in ws.iter_rows(values_only=True):
                rows.append([_celula_texto(c) for c in r])
        else:
            import csv, io
            raw = f.read().decode('utf-8-sig', errors='replace')
            primeira = raw.split('\n', 1)[0]
            delim = ';' if primeira.count(';') >= primeira.count(',') else ','
            rows = [list(r) for r in csv.reader(io.StringIO(raw), delimiter=delim)]
    except Exception as e:
        return render_template('cotacao_import.html', faixas=FAIXAS_ETARIAS, erro='Erro ao ler o arquivo: ' + str(e)[:200])

    rows = [r for r in rows if any((str(c) or '').strip() for c in r)]
    if len(rows) < 2:
        return render_template('cotacao_import.html', faixas=FAIXAS_ETARIAS, erro='O arquivo não tem linhas de dados.')

    header = rows[0]
    meta_idx, faixa_idx = {}, {}
    for i, h in enumerate(header):
        nh = _norm_txt(h)
        if nh in _COLMAP_META:
            meta_idx[_COLMAP_META[nh]] = i
        else:
            fx = _match_faixa_header(h)
            if fx and fx not in faixa_idx:
                faixa_idx[fx] = i
    if 'operadora' not in meta_idx or 'plano' not in meta_idx:
        return render_template('cotacao_import.html', faixas=FAIXAS_ETARIAS,
                               erro='Faltam as colunas obrigatórias "operadora" e "plano" no cabeçalho.')

    conn = db()
    importadas, ignoradas = 0, 0
    for r in rows[1:]:
        def cell(key, default=''):
            i = meta_idx.get(key)
            return (str(r[i]).strip() if (i is not None and i < len(r) and r[i] is not None) else default)
        operadora, plano = cell('operadora'), cell('plano')
        if not operadora or not plano:
            ignoradas += 1
            continue
        try:
            conn.execute("""INSERT INTO cotacao_tabela
                (operadora, plano, modalidade, acomodacao, coparticipacao, linha, tipo_cnpj, abrangencia, vigencia, ativo, atualizado_em)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?)""",
                (operadora, plano, cell('modalidade', 'PME') or 'PME',
                 cell('acomodacao', 'Enfermaria') or 'Enfermaria', cell('coparticipacao', 'Sem') or 'Sem',
                 cell('linha'), cell('tipo_cnpj'), cell('abrangencia'), cell('vigencia'), _agora_sp()))
            tid = (conn.execute("SELECT lastval() AS id").fetchone()['id'] if DB_MODE == 'postgres'
                   else conn.execute("SELECT last_insert_rowid() id").fetchone()['id'])
            for fx, i in faixa_idx.items():
                preco = _parse_preco_br(r[i]) if i < len(r) else 0
                conn.execute("INSERT INTO cotacao_preco (tabela_id, faixa, preco) VALUES (?, ?, ?)", (tid, fx, preco))
            conn.commit()
            importadas += 1
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
            ignoradas += 1
    close_db(conn)
    return render_template('cotacao_import.html', faixas=FAIXAS_ETARIAS,
                           resultado={'importadas': importadas, 'ignoradas': ignoradas,
                                      'faixas_detectadas': sorted(faixa_idx.keys())})


# ── Import de PDF do Painel do Corretor (parser por posição de coluna) ──
def _norm_modalidade(s):
    n = _norm_txt(s)
    if 'pme' in n: return 'PME'
    if 'adesao' in n: return 'Adesão'
    if 'individual' in n or 'pessoa fisica' in n or n.strip() == 'pf' or n.endswith(' pf'): return 'PF'
    return (s or '').strip() or 'PME'

def _norm_acomod(s):
    n = _norm_txt(s)
    if 'apart' in n: return 'Apartamento'
    if 'enferm' in n: return 'Enfermaria'
    return (s or '').strip()

def _norm_copart(s):
    n = _norm_txt(s)
    if 'sem' in n: return 'Sem'
    if 'parcial' in n: return 'Parcial'
    if 'complet' in n or 'total' in n: return 'Completa'
    return (s or '').strip()


def _parse_pdc_pdf(file_obj):
    """Lê uma cotação PDF do Painel do Corretor e devolve a lista de planos (por coluna)."""
    import pdfplumber
    _price_re = re.compile(r'^\d{1,3}(?:\.\d{3})*,\d{2}$')
    planos = []
    with pdfplumber.open(file_obj) as pdf:
        for page in pdf.pages:
            words = page.extract_words()
            if not words:
                continue
            lines = {}
            for w in words:
                lines.setdefault(round(w['top'] / 4) * 4, []).append(w)
            ordered = [sorted(ws, key=lambda x: x['x0']) for _, ws in sorted(lines.items())]

            band_rows = [(ws, [w for w in ws if _price_re.match(w['text'])]) for ws in ordered]
            # >= 1 (não >= 2): uma cotação com um único plano selecionado no Painel do
            # Corretor só tem 1 preço por linha de faixa etária — exigir 2 fazia o parser
            # nunca reconhecer nenhuma linha e cair direto no erro "não identifiquei a tabela".
            band_rows = [(ws, p) for ws, p in band_rows if len(p) >= 1]
            if not band_rows:
                continue

            xs = sorted(w['x0'] for _, ps in band_rows for w in ps)
            cols, cur = [], [xs[0]]
            for x in xs[1:]:
                if x - cur[-1] > 30:
                    cols.append(sum(cur) / len(cur)); cur = [x]
                else:
                    cur.append(x)
            cols.append(sum(cur) / len(cur))
            N = len(cols)

            def col_de(x0):
                d = [abs(x0 - c) for c in cols]
                i = d.index(min(d))
                return i if d[i] < 55 else None

            def label_de(ws):
                return ' '.join(w['text'] for w in ws if w['x0'] < 140)

            top_mod = min((w['top'] for ws in ordered for w in ws
                           if _norm_txt(label_de(ws)).startswith('modalidade')), default=10 ** 9)

            meta = {'modalidade': {}, 'acomodacao': {}, 'coparticipacao': {}}
            for ws in ordered:
                nl = _norm_txt(label_de(ws)).strip()
                destino = ('modalidade' if nl.startswith('modalidade')
                           else 'acomodacao' if nl.startswith('acomod')
                           else 'coparticipacao' if nl.startswith('coparticip') else None)
                if not destino:
                    continue
                buckets = {}
                for w in ws:
                    if w['x0'] < 140:
                        continue
                    c = col_de(w['x0'])
                    if c is not None:
                        buckets.setdefault(c, []).append(w['text'])
                for c, vs in buckets.items():
                    meta[destino][c] = ' '.join(vs)

            precos = {i: {} for i in range(N)}
            for ws, ps in band_rows:
                lbl = ' '.join(w['text'] for w in ws
                               if w['x0'] < 140 and not _price_re.match(w['text']) and w['text'].lower() != 'x')
                fx = _match_faixa_header(lbl)
                if not fx:
                    continue
                for w in ps:
                    c = col_de(w['x0'])
                    if c is not None:
                        precos[c][fx] = _parse_preco_br(w['text'])

            head_words = [w for ws in ordered for w in ws if w['top'] < top_mod - 2 and w['x0'] >= 140]
            col_head = {i: {} for i in range(N)}
            for w in head_words:
                c = col_de(w['x0'])
                if c is not None:
                    col_head[c].setdefault(round(w['top'] / 4) * 4, []).append(w)

            for c in range(N):
                linhas_h = [' '.join(x['text'] for x in sorted(ws, key=lambda z: z['x0']))
                            for _, ws in sorted(col_head[c].items())]
                operadora = linhas_h[-1] if linhas_h else ''
                plano = ' '.join(linhas_h[:-1]) if len(linhas_h) > 1 else (linhas_h[0] if linhas_h else '')
                planos.append({
                    'operadora': operadora.strip(), 'plano': plano.strip(),
                    'modalidade': _norm_modalidade(meta['modalidade'].get(c, '')),
                    'acomodacao': _norm_acomod(meta['acomodacao'].get(c, '')),
                    'coparticipacao': _norm_copart(meta['coparticipacao'].get(c, '')),
                    'precos': precos[c],
                })
            break  # usa a primeira página com tabela de planos
    return planos


@app.route('/cotacao/tabelas/importar-pdf', methods=['GET', 'POST'])
@login_required
@admin_required
def cotacao_import_pdf():
    if request.method == 'GET':
        return render_template('cotacao_import_pdf.html', faixas=FAIXAS_ETARIAS)
    f = request.files.get('arquivo')
    if not f or not f.filename:
        return render_template('cotacao_import_pdf.html', faixas=FAIXAS_ETARIAS, erro='Selecione um arquivo PDF.')
    try:
        planos = _parse_pdc_pdf(f)
    except Exception as e:
        return render_template('cotacao_import_pdf.html', faixas=FAIXAS_ETARIAS,
                               erro='Erro ao ler o PDF: ' + str(e)[:200])
    if not planos:
        return render_template('cotacao_import_pdf.html', faixas=FAIXAS_ETARIAS,
                               erro='Não identifiquei a tabela de planos neste PDF. Confirme que é uma cotação do Painel do Corretor.')
    # Pré-preenche os preços de cada plano por faixa (todas as 10 faixas, vazio onde faltar)
    for p in planos:
        p['precos_lista'] = [{'faixa': fx, 'label': _faixa_label(fx),
                              'valor': (f"{p['precos'][fx]:.2f}".replace('.', ',') if fx in p['precos'] else '')}
                             for fx in FAIXAS_ETARIAS]
    return render_template('cotacao_import_pdf.html', faixas=FAIXAS_ETARIAS, planos=planos)


@app.route('/cotacao/tabelas/importar-pdf/salvar', methods=['POST'])
@login_required
@admin_required
def cotacao_import_pdf_salvar():
    d = request.form
    n = int(d.get('num_planos', '0') or 0)
    conn = db()
    salvas = 0
    for j in range(n):
        if not d.get(f'incluir_{j}'):
            continue
        operadora = (d.get(f'operadora_{j}') or '').strip()
        plano = (d.get(f'plano_{j}') or '').strip()
        if not operadora or not plano:
            continue
        conn.execute("""INSERT INTO cotacao_tabela
            (operadora, plano, modalidade, acomodacao, coparticipacao, linha, tipo_cnpj, abrangencia, vigencia, ativo, atualizado_em)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?)""",
            (operadora, plano, (d.get(f'modalidade_{j}') or 'PME').strip(),
             (d.get(f'acomodacao_{j}') or 'Enfermaria').strip(), (d.get(f'coparticipacao_{j}') or 'Sem').strip(),
             (d.get('linha_global') or '').strip(), (d.get('tipo_cnpj_global') or '').strip(),
             (d.get(f'abrangencia_{j}') or '').strip(), (d.get(f'vigencia_{j}') or '').strip(), _agora_sp()))
        tid = (conn.execute("SELECT lastval() AS id").fetchone()['id'] if DB_MODE == 'postgres'
               else conn.execute("SELECT last_insert_rowid() id").fetchone()['id'])
        for k, fx in enumerate(FAIXAS_ETARIAS):
            preco = _parse_preco_br(d.get(f'preco_{j}_{k}') or '0')
            conn.execute("INSERT INTO cotacao_preco (tabela_id, faixa, preco) VALUES (?, ?, ?)", (tid, fx, preco))
        conn.commit()
        salvas += 1
    close_db(conn)
    return redirect('/cotacao/tabelas')


def _faixa_pdc_para_job(faixa_txt):
    """Converte a faixa do PDC ("00 a 18", "59 ou mais") pro formato do JOB
    ("00-18", "59+")."""
    t = str(faixa_txt or '').strip().lower()
    if '59' in t:
        return '59+'
    m = re.match(r'(\d+)\s*a\s*(\d+)', t)
    if m:
        return f"{int(m.group(1)):02d}-{int(m.group(2)):02d}"
    return None


def _norm_modalidade_pdc(txt):
    t = _norm_txt(txt or '')
    if 'adesao' in t:
        return 'Adesão'
    if 'pf' in t or 'pessoa fisica' in t or 'individual' in t or 'familiar' in t:
        return 'PF'
    return 'PME'  # padrão


def _norm_acomodacao_pdc(txt):
    t = _norm_txt(txt or '')
    return 'Apartamento' if ('apart' in t or 'individual' in t or 'quarto' in t) else 'Enfermaria'


def _norm_copart_pdc(txt):
    t = _norm_txt(txt or '')
    if 'sem' in t:
        return 'Sem'
    if 'parcial' in t:
        return 'Parcial'
    if 'com' in t or 'copart' in t:
        return 'Total'
    return 'Sem'


def _validar_precos_faixa(precos_job):
    """Trava de qualidade da opção C: só deixa gravar uma tabela CERTEIRA. Recebe
    {faixa_job: preco} e devolve (ok, motivo). Rejeita extração incompleta/torta
    pra não sobrescrever preço bom com lixo:
    - todas as 10 faixas ANS presentes e com preço > 0;
    - preço não-decrescente com a idade (faixa mais velha nunca custa menos que a
      mais nova) — pega leitura embaralhada/coluna trocada."""
    faltando = [fx for fx in FAIXAS_ETARIAS if not (precos_job.get(fx) or 0) > 0]
    if faltando:
        return False, f"faltam faixas com preço: {', '.join(faltando)}"
    seq = [precos_job[fx] for fx in FAIXAS_ETARIAS]
    for i in range(1, len(seq)):
        if seq[i] < seq[i - 1] - 0.005:
            return False, f"preço cai com a idade ({FAIXAS_ETARIAS[i-1]}={seq[i-1]:.2f} > {FAIXAS_ETARIAS[i]}={seq[i]:.2f})"
    return True, ''


def _checar_auth_escrita_cotacao():
    """Verifica permissão de escrita em tabelas de cotação.
    Permite se:
    1. Usuário admin estiver logado na sessão Web; OR
    2. Header X-Cotacao-Key bater com a env COTACAO_WRITE_API_KEY (via hmac.compare_digest).
    Se COTACAO_WRITE_API_KEY não estiver no ambiente, o acesso por chave fica desabilitado.
    """
    if session.get('user_id') and session.get('perfil') == 'admin':
        return True
    hdr_key = (request.headers.get('X-Cotacao-Key') or '').strip()
    env_key = (os.environ.get('COTACAO_WRITE_API_KEY') or '').strip()
    if hdr_key and env_key and hmac.compare_digest(hdr_key, env_key):
        return True
    return False


@app.route('/cotacao/tabelas/importar-pdc', methods=['POST'])
def cotacao_importar_pdc():
    """Importa o JSON extraído do Painel do Corretor (scripts/pdc_extrator_console.js).
    Cada plano vira/atualiza uma linha em cotacao_tabela + os preços por faixa em
    cotacao_preco + a rede em cotacao_rede. Dedup por (operadora, plano,
    modalidade, acomodacao, coparticipacao, cidade, tipo_cnpj, entidade) — re-subir o mesmo
    plano ATUALIZA (apaga preços/rede antigos e regrava), não duplica. Assim dá
    pra rodar de novo pra atualizar valores sem virar bagunça."""
    if not _checar_auth_escrita_cotacao():
        return jsonify({"ok": False, "erro": "Acesso negado: requer sessão admin ou X-Cotacao-Key válida"}), 403

    dados = request.get_json(silent=True)
    if dados is None:
        return jsonify({"ok": False, "erro": "Envie o JSON exportado pelo script do PDC"}), 400
    # Aceita tanto {cidade, modalidade, planos:[...]} quanto uma lista/1 plano só.
    if isinstance(dados, list):
        planos = dados
        cidade_g, modalidade_g, tipo_cnpj_g, abrangencia_g = '', '', '', ''
    else:
        planos = dados.get('planos') or ([dados] if dados.get('plano') else [])
        cidade_g = (dados.get('cidade') or '').strip()
        modalidade_g = dados.get('modalidade') or ''
        tipo_cnpj_g = (dados.get('tipo_cnpj') or '').strip()
        abrangencia_g = (dados.get('abrangencia') or '').strip()

    conn = db()
    agora = _agora_sp()
    cont = {'planos_novos': 0, 'planos_atualizados': 0, 'precos': 0, 'rede': 0, 'ignorados': 0, 'rejeitados': 0}
    rejeitos = []
    for p in planos:
        operadora = (p.get('operadora') or '').strip()
        plano = (p.get('plano') or '').strip()
        entidade = (p.get('entidade') or '').strip()
        admin_nome = (p.get('administradora_nome') or p.get('administradora') or '').strip()
        if not operadora and admin_nome:
            operadora = admin_nome

        precos = p.get('precos') or {}
        if not operadora or not plano or not precos:
            cont['ignorados'] += 1
            continue
        # Monta o mapa de preços por faixa ANS e VALIDA antes de tocar no banco —
        # extração torta/incompleta é rejeitada e NÃO sobrescreve o preço bom que
        # já estava lá (trava de "certeiro").
        precos_job = {}
        for faixa_txt, valor in precos.items():
            fx = _faixa_pdc_para_job(faixa_txt)
            if fx:
                precos_job[fx] = _parse_preco_br(str(valor))
        ok_val, motivo = _validar_precos_faixa(precos_job)
        if not ok_val:
            cont['rejeitados'] += 1
            rejeitos.append(f"{operadora} · {plano}: {motivo}")
            continue

        cidade = (p.get('cidade') or cidade_g or '').strip()
        modalidade = _norm_modalidade_pdc(p.get('modalidade') or modalidade_g)
        acomodacao = _norm_acomodacao_pdc(p.get('acomodacao'))
        copart = _norm_copart_pdc(p.get('coparticipacao'))
        tipo_cnpj = (p.get('tipo_cnpj') or tipo_cnpj_g or '').strip()
        # Campo próprio, vindo do extrator. Vazio é vazio — melhor não saber a
        # abrangência do que registrar a cidade no lugar dela.
        abrangencia = (p.get('abrangencia') or abrangencia_g or '').strip()[:60]

        existente = conn.execute("""SELECT id FROM cotacao_tabela WHERE operadora=? AND plano=?
            AND modalidade=? AND acomodacao=? AND coparticipacao=? AND COALESCE(cidade,'')=?
            AND COALESCE(tipo_cnpj,'')=? AND COALESCE(entidade,'')=?""",
            (operadora, plano, modalidade, acomodacao, copart, cidade, tipo_cnpj, entidade)).fetchone()
        if existente:
            tid = existente['id']
            conn.execute("DELETE FROM cotacao_preco WHERE tabela_id=?", (tid,))
            conn.execute("DELETE FROM cotacao_rede WHERE tabela_id=?", (tid,))
            if abrangencia:
                conn.execute("UPDATE cotacao_tabela SET ativo=1, abrangencia=?, entidade=?, atualizado_em=? WHERE id=?",
                             (abrangencia, entidade, agora, tid))
            else:
                conn.execute("UPDATE cotacao_tabela SET ativo=1, entidade=?, atualizado_em=? WHERE id=?",
                             (entidade, agora, tid))
            cont['planos_atualizados'] += 1
        else:
            conn.execute("""INSERT INTO cotacao_tabela
                (operadora, plano, modalidade, acomodacao, coparticipacao, tipo_cnpj, cidade, abrangencia, entidade, ativo, atualizado_em)
                VALUES (?,?,?,?,?,?,?,?,?,1,?)""",
                (operadora, plano, modalidade, acomodacao, copart, tipo_cnpj, cidade, abrangencia, entidade, agora))
            tid = (conn.execute("SELECT lastval() AS id").fetchone()['id'] if DB_MODE == 'postgres'
                   else conn.execute("SELECT last_insert_rowid() id").fetchone()['id'])
            cont['planos_novos'] += 1

        for fx, preco in precos_job.items():
            conn.execute("INSERT INTO cotacao_preco (tabela_id, faixa, preco) VALUES (?,?,?)", (tid, fx, preco))
            cont['precos'] += 1

        for cred in (p.get('rede') or []):
            nome = (cred.get('nome') or '').strip()
            if not nome:
                continue
            conn.execute("INSERT INTO cotacao_rede (tabela_id, nome, cidade, cobertura) VALUES (?,?,?,?)",
                         (tid, nome[:200], (cred.get('cidade') or '').strip()[:120], (cred.get('cobertura') or '').strip()[:60]))
            cont['rede'] += 1
        conn.commit()
    close_db(conn)
    return jsonify({"ok": True, "contagem": cont, "rejeitos": rejeitos[:20]})


