@app.route('/material-apoio')
@login_required
def material_apoio():
    """Regras comerciais e tabelas de venda por operadora (apoio ao corretor)."""
    conn = db()
    q = (request.args.get('q') or '').strip()
    if q:
        like = f"%{q.lower()}%"
        rows = conn.execute("""SELECT * FROM material_apoio
            WHERE LOWER(COALESCE(operadora,'')) LIKE ? OR LOWER(titulo) LIKE ?
               OR LOWER(COALESCE(tipo,'')) LIKE ? OR LOWER(COALESCE(descricao,'')) LIKE ?
               OR LOWER(COALESCE(conteudo,'')) LIKE ?
            ORDER BY operadora, id DESC""", (like, like, like, like, like)).fetchall()
    else:
        rows = conn.execute("SELECT * FROM material_apoio ORDER BY operadora, id DESC").fetchall()
    grupos = {}
    for r in rows:
        d = dict(r)
        op = d.get('operadora') or 'Geral'
        tp = (d.get('tipo') or '').strip() or 'Geral'
        if op not in grupos:
            grupos[op] = {'operadora': op, 'logo': _logo_operadora_url(conn, op), 'tipos': {}}
        grupos[op]['tipos'].setdefault(tp, []).append(d)
    # Pastas criadas explicitamente (mesmo sem nenhum item ainda) — só faz sentido no navegador, não na busca
    if not q:
        for pr in conn.execute("SELECT operadora, nome FROM material_apoio_pasta ORDER BY operadora, nome").fetchall():
            pd = dict(pr)
            op = pd['operadora']
            if op not in grupos:
                grupos[op] = {'operadora': op, 'logo': _logo_operadora_url(conn, op), 'tipos': {}}
            grupos[op]['tipos'].setdefault(pd['nome'], [])
    grupos_l = []
    for g in grupos.values():
        g['caixas'] = [{'tipo': t, 'itens': it} for t, it in g['tipos'].items()]
        grupos_l.append(g)
    try:
        operadoras = [r['operadora'] for r in conn.execute(
            "SELECT DISTINCT operadora FROM cotacao_tabela ORDER BY operadora").fetchall()]
    except Exception:
        operadoras = []
    close_db(conn)
    return render_template('material_apoio.html', grupos=grupos_l, q=q,
                           operadoras=operadoras, eh_admin=(session.get('perfil') == 'admin'))


def _extrair_texto_pdf(file_obj):
    """Lê e limpa o texto de um PDF (regras/fichas de operadora)."""
    import pdfplumber, io as _io
    partes = []
    try:
        with pdfplumber.open(file_obj) as pdf:
            for pg in pdf.pages:
                t = pg.extract_text() or ''
                if t.strip():
                    partes.append(t)
    except Exception:
        return ''
    txt = '\n'.join(partes)
    txt = txt.replace('(cid:127)', '• ').replace('', '• ')
    txt = re.sub(r'\(cid:\d+\)', '', txt)
    txt = re.sub(r'[ \t]{2,}', ' ', txt)
    txt = re.sub(r'\n{3,}', '\n\n', txt)
    return txt.strip()


@app.route('/material-apoio/novo', methods=['POST'])
@login_required
@admin_required
def material_apoio_novo():
    import io as _io
    from urllib.parse import quote
    d = request.form
    titulo = (d.get('titulo') or '').strip()
    if not titulo:
        return redirect('/material-apoio')
    arquivo = None
    conteudo = ''
    falha_upload = False
    f = request.files.get('arquivo')
    if f and f.filename:
        # O `accept=".pdf,.png,..."` do &lt;input&gt; e so sugestao pro navegador —
        # nao impede nada de fato, e quem manda o POST direto passa reto.
        # `/anexos/&lt;nome&gt;` serve todo arquivo com `Content-Disposition: inline`
        # (de proposito: contrato e comprovante precisam abrir no navegador,
        # nao baixar). Um .svg/.html/.xml sobe com esse Content-Disposition e
        # roda como pagina do proprio dominio pra quem abrir o link — a mesma
        # lista aceita do lado do navegador, só que valendo de verdade aqui.
        _EXT_MATERIAL_OK = {'.pdf', '.png', '.jpg', '.jpeg', '.xlsx', '.xls', '.csv', '.doc', '.docx'}
        ext = os.path.splitext(f.filename)[1].lower()
        if ext not in _EXT_MATERIAL_OK:
            return redirect('/material-apoio?erro=' + quote(
                f'Tipo de arquivo não aceito ({ext or "sem extensão"}). Use PDF, imagem, planilha ou Word.'))
        data = f.read()
        nome_gerado = _sanitizar_filename(f'material_{secrets.token_hex(4)}{ext}')
        try:
            upload_arquivo_r2(_io.BytesIO(data), f'material/{nome_gerado}')
            arquivo = nome_gerado
        except Exception as e:
            app.logger.error(f"[MATERIAL] upload falhou: {e}"); falha_upload = True
        if ext == '.pdf':
            try:
                conteudo = _extrair_texto_pdf(_io.BytesIO(data))
            except Exception as e:
                app.logger.error(f"[MATERIAL] extracao de texto falhou: {e}"); conteudo = ''
    conn = db()
    conn.execute("INSERT INTO material_apoio (operadora, tipo, titulo, descricao, conteudo, arquivo) VALUES (?, ?, ?, ?, ?, ?)",
                 ((d.get('operadora') or '').strip(), (d.get('tipo') or '').strip(),
                  titulo, (d.get('descricao') or '').strip(), conteudo, arquivo))
    conn.commit(); close_db(conn)
    if falha_upload:
        return redirect('/material-apoio?erro=' + quote(
            f'"{titulo}" foi salvo, mas o ARQUIVO não pôde ser anexado (falha no upload). Tente anexar de novo editando o item.'))
    return redirect('/material-apoio')


