def _build_cot(conn, c):
    """Monta o dicionário da cotação para o documento (planos, faixas, logos)."""
    cot = dict(c)
    try:
        planos = json.loads(cot.get('planos_json') or '[]')
    except Exception:
        planos = []
    cot['planos'] = planos
    faixas_usadas = []
    if planos:
        faixas_usadas = [{'faixa': l['faixa'], 'label': l.get('label') or _faixa_label(l['faixa']),
                          'qtd': l['qtd']} for l in planos[0]['linhas']]
    for p in planos:
        p['precos'] = {l['faixa']: l['subtotal'] for l in p['linhas']}
        p['precos_unit'] = {l['faixa']: (l['preco'] if l.get('preco') is not None
                            else round(float(l.get('subtotal') or 0) / max(int(l.get('qtd') or 1), 1), 2))
                            for l in p['linhas']}
        p['logo'] = _logo_operadora_url(conn, p.get('operadora'))
    cot['faixas_usadas'] = faixas_usadas
    cot['orientacao'] = cot.get('orientacao') or 'horizontal'
    # Cores automáticas por plano (para destaque opcional) + legenda pronta p/ copiar
    PALETA = [('VERDE', '#1fb88a'), ('LARANJA', '#fb923c'), ('AZUL', '#3b82f6'),
              ('ROXO', '#8b5cf6'), ('ROSA', '#f43f7c'), ('CIANO', '#06b6d4')]
    for i, p in enumerate(planos):
        nome_cor, cor = PALETA[i % len(PALETA)]
        p['cor'] = cor
        p['cor_nome'] = nome_cor
    try:
        vidas = json.loads(cot.get('vidas_json') or '{}')
        total_vidas = sum(int(v) for v in vidas.values())
    except Exception:
        total_vidas = 0
    leg = ['*' + (cot.get('titulo') or 'Cotação') + '*']
    if total_vidas:
        leg.append(str(total_vidas) + ' vida(s)')
    for p in planos:
        leg.append('Em ' + p['cor_nome'] + ': ' + (p.get('operadora') or '') + ' ' + (p.get('plano') or '')
                   + ' - copart. ' + (p.get('coparticipacao') or '') + ' - R$ ' + _moeda_doc(p.get('total')) + '/mês')
    cot['legenda'] = '\n'.join(leg)
    return cot


@app.route('/c/<token>')
def cotacao_publica(token):
    """Página pública e imutável da cotação (para enviar link ao cliente)."""
    conn = db()
    c = conn.execute("SELECT * FROM cotacao_salva WHERE token=?", (token,)).fetchone()
    if not c:
        close_db(conn); abort(404)
    cd = dict(c)
    # Rastreia abertura: conta + registra no pipeline do lead no CRM
    # Guarda: notifica o corretor no máximo 1x a cada 5 min por cotação (evita spam de refresh)
    notificar_abertura = False
    if request.args.get('render') != '1':
        try:
            ult = cd.get('ultima_abertura')
            ult_dt = _parse_dt_seguro(ult) if ult else None
            if not ult_dt:
                notificar_abertura = True
            else:
                if ult_dt.tzinfo is None:
                    ult_dt = TZ_SP.localize(ult_dt)
                if (datetime.now(TZ_SP) - ult_dt).total_seconds() > 300:
                    notificar_abertura = True
        except Exception:
            notificar_abertura = True
        try:
            conn.execute("UPDATE cotacao_salva SET aberturas=COALESCE(aberturas,0)+1, ultima_abertura=? WHERE id=?",
                         (datetime.now(TZ_SP).strftime('%Y-%m-%d %H:%M:%S'), cd['id']))
            if cd.get('lead_id'):
                conn.execute("INSERT INTO crm_atividades (lead_id, usuario_nome, tipo, descricao) VALUES (?, ?, ?, ?)",
                             (cd['lead_id'], 'Sistema', 'abertura',
                              'Cliente ABRIU a cotação "' + (cd.get('titulo') or 'Cotação') + '" pelo link'))
            conn.commit()
        except Exception:
            pass
    cot = _build_cot(conn, c)
    close_db(conn)
    if notificar_abertura:
        try:
            cliente = cd.get('cliente_nome') or 'O cliente'
            _notificar(cd.get('corretor_id'), 'cotacao', 'Cotação visualizada',
                       f"{cliente} abriu a cotação \"{cd.get('titulo') or 'Cotação'}\"",
                       '/cotacao/documento/' + str(cd['id']))
        except Exception:
            pass
    return render_template('cotacao_documento.html', cot=cot, c=c, publico=True)


@app.route('/c/<token>/feedback', methods=['POST'])
def cotacao_publica_feedback(token):
    """Cliente clica 'Gostei dessa proposta' ou 'Me explique mais essa opção' no link
    público. Avisa o corretor (sino + WhatsApp) e registra na timeline do lead."""
    d = request.json or {}
    tipo = (d.get('tipo') or '').strip()
    if tipo not in ('gostei', 'explicar'):
        return jsonify({"ok": False, "erro": "Tipo inválido"}), 400
    conn = db()
    c = conn.execute("SELECT * FROM cotacao_salva WHERE token=?", (token,)).fetchone()
    if not c:
        close_db(conn); return jsonify({"ok": False, "erro": "Cotação não encontrada"}), 404
    cd = dict(c)
    cliente = cd.get('cliente_nome') or 'O cliente'
    titulo_cot = cd.get('titulo') or 'Cotação'
    if tipo == 'gostei':
        titulo_notif = 'Cliente gostou da cotação!'
        desc = f'{cliente} clicou em "Gostei dessa proposta" na cotação "{titulo_cot}"'
        desc_timeline = f'Cliente clicou em "Gostei dessa proposta" — "{titulo_cot}"'
    else:
        titulo_notif = 'Cliente quer mais explicação'
        desc = f'{cliente} clicou em "Me explique mais essa opção" na cotação "{titulo_cot}" — vale ligar'
        desc_timeline = f'Cliente clicou em "Me explique mais essa opção" — "{titulo_cot}"'
    try:
        if cd.get('lead_id'):
            conn.execute("INSERT INTO crm_atividades (lead_id, usuario_nome, tipo, descricao, criado_em) VALUES (?,?,?,?,?)",
                         (cd['lead_id'], 'Sistema', 'feedback_cotacao', desc_timeline, _agora_sp()))
            conn.commit()
    except Exception:
        pass
    close_db(conn)
    try:
        _notificar(cd.get('corretor_id'), 'cotacao', titulo_notif, desc, '/cotacao/documento/' + str(cd['id']))
    except Exception:
        pass
    return jsonify({"ok": True})


_COT_EVENTOS_VALIDOS = ('consentimento', 'tempo_pagina', 'scroll', 'clique_plano')


@app.route('/c/<token>/evento', methods=['POST'])
def cotacao_publica_evento(token):
    """Captura de comportamento na cotação pública — SÓ depois do cliente aceitar
    (evento 'consentimento' precisa ser o primeiro; os demais são recusados sem
    ele). Cookie de 1ª parte, sem rastreio de terceiros: tempo na página, até onde
    rolou, em qual plano clicou. Serve pro corretor entender o que o cliente olhou
    antes de ligar — não vira seleção de risco nem decisão de saúde."""
    d = request.json or {}
    evento = (d.get('evento') or '').strip()
    if evento not in _COT_EVENTOS_VALIDOS:
        return jsonify({"ok": False}), 400
    conn = db()
    c = conn.execute("SELECT id FROM cotacao_salva WHERE token=?", (token,)).fetchone()
    if not c:
        close_db(conn); return jsonify({"ok": False}), 404
    cot_id = c['id']
    if evento != 'consentimento':
        # só grava comportamento se já existe consentimento pra essa cotação
        consentiu = conn.execute(
            "SELECT 1 FROM cotacao_engajamento WHERE cotacao_id=? AND evento='consentimento' LIMIT 1",
            (cot_id,)).fetchone()
        if not consentiu:
            close_db(conn); return jsonify({"ok": False, "erro": "sem_consentimento"}), 403
    dados = d.get('dados') if isinstance(d.get('dados'), dict) else {}
    dados_str = json.dumps(dados, ensure_ascii=False)[:800]
    conn.execute("INSERT INTO cotacao_engajamento (cotacao_id, evento, dados, criado_em) VALUES (?,?,?,?)",
                 (cot_id, evento, dados_str, _agora_sp()))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True})


