# ── NOTIFICAÇÕES (sininho) ──────────────────────────────────────────────────

def _notificar(usuario_id, tipo, titulo, descricao='', link=''):
    """Cria uma notificação. usuario_id=None → broadcast para todos os admins.
    Também envia WhatsApp via WaSpeed (do número do gestor) em background.
    Nunca propaga erro (não pode derrubar o fluxo que a chamou)."""
    try:
        conn = db()
        conn.execute(
            "INSERT INTO notificacoes (usuario_id, tipo, titulo, descricao, link, criado_em) VALUES (?, ?, ?, ?, ?, ?)",
            (usuario_id, tipo, titulo, descricao, link,
             datetime.now(TZ_SP).strftime('%Y-%m-%d %H:%M:%S')))
        conn.commit()
        close_db(conn)
    except Exception as e:
        try: app.logger.warning(f"[NOTIF] falha ao criar: {e}")
        except Exception: pass
    # WhatsApp em thread separada: nunca atrasa nem derruba a requisição
    try:
        threading.Thread(target=_notificar_whatsapp, args=(usuario_id, tipo, titulo, descricao, link), daemon=True).start()
    except Exception:
        pass


_SITE_BASE_URL = "https://job-serenus-production.up.railway.app"


def _notificar_whatsapp(usuario_id, tipo, titulo, descricao, link=''):
    """Envia a notificação para o WhatsApp do(s) destinatário(s) via WaSpeed.
    Usa o token global (WASPEED_TOKEN — número do Guilherme). Loga sucesso/falha
    de cada envio — antes falhava 100% em silêncio e não dava pra saber por quê.
    O sino interno (tabela notificacoes) NUNCA é afetado por isso — é sempre
    criado antes desta função rodar; aqui só decide se manda por WhatsApp
    também. Opt-out é só pra tipo='lead' (aviso de lead novo) — uma coluna
    única silenciando TUDO desligaria também aviso de proposta/comprovante/
    comissão, que não foi pedido."""
    token = os.environ.get('WASPEED_TOKEN', '').strip()
    if not token:
        app.logger.warning(f"[NOTIF-WPP] WASPEED_TOKEN não configurada — lembrete '{titulo}' NÃO enviado")
        return
    try:
        import requests as _rq
        conn = db()
        filtro_opt_out = " AND COALESCE(notificar_wpp_leads,1)=1" if tipo == 'lead' else ""
        if usuario_id:
            rows = conn.execute(f"SELECT telefone FROM usuarios WHERE id=? AND ativo=1{filtro_opt_out}", (usuario_id,)).fetchall()
        else:  # broadcast → todos os admins com telefone (que não desligaram esse tipo)
            rows = conn.execute(f"SELECT telefone FROM usuarios WHERE perfil='admin' AND ativo=1{filtro_opt_out}").fetchall()
        close_db(conn)
        fones = set()
        for r in rows:
            tel = r['telefone'] if hasattr(r, 'keys') else r[0]
            f = _waspeed_normaliza_fone(tel or '')
            if f:
                fones.add(f)
        if not fones:
            app.logger.info(f"[NOTIF-WPP] usuario_id={usuario_id} sem telefone válido ou optou por não receber — lembrete '{titulo}' NÃO enviado")
            return
        # Mensagem compacta: nome do app + título já diz o essencial, descrição
        # só entra se acrescentar algo que o título não disse.
        msg = f"*JOB* — {titulo}"
        if descricao and descricao.strip() != titulo.strip():
            msg += f"\n{descricao}"
        # Se a descrição já traz um link (ex: confirmação de atividade), não duplica com o link genérico
        if link and 'http' not in (descricao or ''):
            url = link if link.startswith('http') else _SITE_BASE_URL + link
            msg += f"\n{url}"
        for f in fones:
            fone_mascarado = f[:4] + '****' + f[-2:]
            try:
                resp = _rq.post(f"{WASPEED_BASE}/api/enviar-texto/{token}",
                                json={"phone": f, "message": msg}, timeout=15)
                try:
                    j = resp.json()
                except Exception:
                    j = {}
                if j.get('success'):
                    app.logger.info(f"[NOTIF-WPP] OK -> {fone_mascarado} | '{titulo}'")
                else:
                    app.logger.warning(f"[NOTIF-WPP] FALHOU -> {fone_mascarado} | http={resp.status_code} | resposta={j or resp.text[:200]}")
            except Exception as e:
                app.logger.warning(f"[NOTIF-WPP] ERRO DE REDE -> {fone_mascarado} | {e}")
    except Exception as e:
        try: app.logger.warning(f"[NOTIF-WPP] erro geral: {e}")
        except Exception: pass


def _notificar_admins(tipo, titulo, descricao='', link=''):
    """Notifica todos os admins (broadcast: usuario_id NULL)."""
    _notificar(None, tipo, titulo, descricao, link)


@app.route('/api/heartbeat', methods=['POST'])
@login_required
def api_heartbeat():
    """Recebe um 'sinal de vida' do navegador — só é chamado pelo JS quando
    houve mouse/teclado desde o último ping (ver script no base.html), então
    cada chamada representa ~2min de uso ativo de verdade, não a aba só aberta
    em segundo plano. Acumula em score_heartbeat, usado pelo score de utilização."""
    uid = session.get('user_id')
    if not uid:
        return jsonify({"ok": False}), 401
    dia = datetime.now(TZ_SP).strftime('%Y-%m-%d')
    conn = db()
    if DB_MODE == 'postgres':
        conn.execute("""INSERT INTO score_heartbeat (usuario_id, dia, minutos_ativos, atualizado_em)
            VALUES (?,?,2,?)
            ON CONFLICT (usuario_id, dia) DO UPDATE SET
                minutos_ativos = score_heartbeat.minutos_ativos + 2, atualizado_em = excluded.atualizado_em""",
            (uid, dia, _agora_sp()))
    else:
        existe = conn.execute("SELECT id FROM score_heartbeat WHERE usuario_id=? AND dia=?", (uid, dia)).fetchone()
        if existe:
            conn.execute("UPDATE score_heartbeat SET minutos_ativos = minutos_ativos + 2, atualizado_em=? WHERE id=?",
                         (_agora_sp(), existe['id']))
        else:
            conn.execute("INSERT INTO score_heartbeat (usuario_id, dia, minutos_ativos, atualizado_em) VALUES (?,?,2,?)",
                         (uid, dia, _agora_sp()))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True})


@app.route('/api/notificacoes')
@login_required
def api_notificacoes():
    """Lista as notificações do usuário logado (próprias + broadcast p/ admin)."""
    uid = session.get('user_id')
    eh_admin = session.get('perfil') == 'admin'
    conn = db()
    som_row = conn.execute("SELECT som_notificacao FROM usuarios WHERE id=?", (uid,)).fetchone()
    som_pref = (dict(som_row).get('som_notificacao') if som_row else None) or 'thriller'
    # O sino e o lugar onde o admin descobre que algo parou, entao a conferencia
    # roda aqui: e barata e acontece exatamente quando alguem esta olhando.
    if eh_admin:
        try:
            _pendencias_reconciliar(conn)
        except Exception as e:
            app.logger.info(f'[PENDENCIA] reconciliar no sino: {e}')
            try: conn.rollback()
            except Exception: pass
    dono = ('(usuario_id=? OR usuario_id IS NULL)' if eh_admin else 'usuario_id=?')
    # PENDENCIAS ABERTAS VEM TODAS, sem teto e sem depender de terem sido lidas:
    # sao trabalho a fazer, nao historico. O limite de 30 vale so pros avisos.
    pend_rows = conn.execute(
        f'SELECT * FROM notificacoes WHERE {dono} AND tipo=? AND resolvida_em IS NULL '
        f'ORDER BY CASE WHEN severidade=? THEN 0 ELSE 1 END, id DESC',
        (uid, 'pendencia', 'erro')).fetchall()
    rows = conn.execute(
        f'SELECT * FROM notificacoes WHERE {dono} AND (tipo IS NULL OR tipo<>?) '
        f'ORDER BY id DESC LIMIT 30', (uid, 'pendencia')).fetchall()
    close_db(conn)
    itens = []
    nao_lidas = 0
    for r in rows:
        d = dict(r)
        if not d.get('lida'):
            nao_lidas += 1
        itens.append({
            'id': d['id'], 'tipo': d.get('tipo') or '', 'titulo': d.get('titulo') or '',
            'descricao': d.get('descricao') or '', 'link': d.get('link') or '',
            'lida': bool(d.get('lida')), 'quando': _tempo_relativo(d.get('criado_em')),
        })
    pendencias = [{
        'id': dict(r)['id'], 'titulo': dict(r).get('titulo') or '',
        'descricao': dict(r).get('descricao') or '',
        'como_resolver': dict(r).get('como_resolver') or '',
        'severidade': dict(r).get('severidade') or 'atencao',
        'link': dict(r).get('link') or '',
        'quando': _tempo_relativo(dict(r).get('criado_em')),
    } for r in pend_rows]
    # A pendencia conta no contador do sino mesmo depois de lida: enquanto o
    # problema existir, o sino tem que continuar chamando. Marcar como lida
    # nao pode ser jeito de fazer sumir.
    return jsonify({'nao_lidas': nao_lidas + len(pendencias), 'itens': itens,
                    'pendencias': pendencias, 'som': som_pref})


