def _tempo_relativo(quando):
    """'há 5 min', 'há 2 h', 'há 3 d' a partir de um timestamp (str ou datetime)."""
    try:
        dt = _parse_dt_seguro(quando) if quando else None
        if not dt:
            return ''
        if dt.tzinfo is None:
            dt = TZ_SP.localize(dt)
        delta = datetime.now(TZ_SP) - dt
        seg = int(delta.total_seconds())
        # Registro "no futuro" = linha antiga gravada em UTC → corrige -3h
        if seg < -300:
            seg += 3 * 3600
        if seg < 60: return 'agora'
        if seg < 3600: return f'há {seg // 60} min'
        if seg < 86400: return f'há {seg // 3600} h'
        return f'há {seg // 86400} d'
    except Exception:
        return ''


@app.route('/crm/importar-agora', methods=['POST'])
@login_required
@admin_required
def crm_importar_agora():
    """Dispara a importação de leads das planilhas imediatamente (botão no CRM).
    Substitui a necessidade de abrir o Apps Script do Google manualmente."""
    # MESMO CADEADO DO PULL AUTOMATICO.
    #
    # O pull automatico (a cada 15min, ou por request com throttle de 10min)
    # roda em thread separada e segura `_AUTO_PULL_LOCK` enquanto importa. Este
    # botao chamava `_importar_leads_automatico()` direto, sem tocar no
    # cadeado — se alguem clicasse enquanto o pull automatico estivesse no
    # meio, as duas rodavam a mesma planilha ao mesmo tempo. O dedup e
    # "SELECT depois INSERT", sem UNIQUE em telefone_norm: as duas podiam
    # checar "nao existe" ao mesmo tempo e o mesmo lead entrava duas vezes.
    #
    # `blocking=False`: se o automatico ja esta rodando, este pedido nao
    # espera nem dispara por cima — avisa e devolve, e o proprio automatico
    # ja ia trazer o mesmo lead minutos depois de qualquer forma.
    if not _AUTO_PULL_LOCK.acquire(blocking=False):
        return jsonify({'ok': False, 'erro': 'ja_importando',
                        'mensagem': 'Já existe uma importação em andamento. Aguarde alguns segundos e tente de novo.'}), 409
    try:
        importados, duplicados = _importar_leads_automatico()
    finally:
        _AUTO_PULL_LOCK.release()
    return jsonify({'ok': True, 'importados': importados, 'duplicados': duplicados})


# ── AGENDA DO CRM: atividades futuras com lembrete ─────────────────────────

@app.route('/crm/lead/<int:lid>/agendar', methods=['POST'])
@login_required
def crm_lead_agendar(lid):
    """Agenda uma atividade futura (conversa, retorno...) para o lead."""
    conn = db()
    lead = conn.execute("SELECT * FROM crm_leads WHERE id=?", (lid,)).fetchone()
    if not lead:
        close_db(conn); return jsonify({"ok": False, "erro": "Lead não encontrado"}), 404
    if session.get('perfil') != 'admin' and lead['responsavel_id'] != session.get('user_id'):
        close_db(conn); return jsonify({"ok": False, "erro": "Sem permissão"}), 403
    d = request.json or {}
    assunto = (d.get('assunto') or '').strip()
    data_hora = (d.get('data_hora') or '').strip().replace('T', ' ')[:16]
    if not assunto or not data_hora:
        close_db(conn); return jsonify({"ok": False, "erro": "Informe assunto e data/hora"}), 400
    conn.execute("""INSERT INTO crm_agenda (lead_id, usuario_id, assunto, descricao, data_hora, mensagem_lead, criado_em)
        VALUES (?, ?, ?, ?, ?, ?, ?)""",
        (lid, session.get('user_id'), assunto, (d.get('descricao') or '').strip(),
         data_hora, (d.get('mensagem_lead') or '').strip() or None, _agora_sp()))
    conn.execute("INSERT INTO crm_atividades (lead_id, usuario_nome, tipo, descricao, criado_em) VALUES (?,?,?,?,?)",
                 (lid, session.get('nome'), 'agendamento',
                  f"Atividade agendada para {_fmt_datahora_br(data_hora)}: {assunto}", _agora_sp()))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True})


