def _ads_testar_conexao():
    """Testa a ligação com o Google Ads SEM enviar venda nenhuma.

    Por que uma rota só pra isso: ligar seis credenciais e descobrir se prestam
    só quando a primeira venda real falha é o jeito errado de fazer. Aqui cada
    degrau é testado separado, então o erro aponta o culpado em vez de dizer
    'não funcionou': chave errada, token não aprovado, conta errada ou ação de
    conversão inexistente dão mensagens diferentes.

    O último degrau usa um gclid inválido de propósito. Se o Google responder
    "clique não encontrado", está tudo certo — ele autenticou, achou a conta,
    achou a ação de conversão e só não achou aquele clique (que não existe
    mesmo). Esse erro é a APROVAÇÃO do teste, não a reprovação dele."""
    passos = []

    def passo(nome, ok, detalhe='', dica=''):
        passos.append({'nome': nome, 'ok': bool(ok), 'detalhe': str(detalhe)[:500], 'dica': dica})
        return ok

    cfg, faltando = _ads_config()
    if not passo('Credenciais no servidor', not faltando,
                 'Faltando: ' + ', '.join(faltando) if faltando else 'as 6 estão configuradas',
                 'Cadastre as variáveis no Railway e faça o redeploy.' if faltando else ''):
        return {'ok': False, 'passos': passos}

    try:
        token = _ads_token(cfg)
        passo('Login (OAuth)', True, 'access_token recebido')
    except Exception as e:
        passo('Login (OAuth)', False, e,
              'Client ID, Client Secret ou Refresh Token errados/expirados. '
              'O refresh token morre se a senha da conta Google mudar ou se o acesso for revogado.')
        return {'ok': False, 'passos': passos}

    headers = {'Authorization': 'Bearer ' + token,
               'developer-token': cfg['developer_token'],
               'Content-Type': 'application/json'}
    if cfg['login_customer_id']:
        headers['login-customer-id'] = cfg['login_customer_id']

    # Degrau 2: a conta existe e este token enxerga ela? Uma consulta de leitura,
    # que não altera nada — é aqui que aparece developer token não aprovado.
    conta = ''
    try:
        r = _requests.post(f"{_ADS_API}/customers/{cfg['customer_id']}/googleAds:search",
                           headers=headers, timeout=30,
                           json={'query': 'SELECT customer.id, customer.descriptive_name, '
                                          'customer.currency_code, customer.time_zone FROM customer LIMIT 1'})
        if r.status_code == 200:
            res = ((r.json() or {}).get('results') or [{}])[0].get('customer') or {}
            conta = res.get('descriptiveName') or ''
            passo('Conta do Google Ads', True,
                  f"{conta or '(sem nome)'} · id {res.get('id') or cfg['customer_id']} · "
                  f"{res.get('currencyCode') or '?'} · fuso {res.get('timeZone') or '?'}")
        else:
            corpo = r.text[:400]
            dica = ''
            if 'DEVELOPER_TOKEN' in corpo.upper():
                dica = ('O developer token está em modo teste ou não foi aprovado. Só token com acesso '
                        'Basic/Standard fala com conta real — peça a aprovação no Google Ads API Center.')
            elif r.status_code == 403:
                dica = ('A conta existe mas este login não tem permissão nela. Se ela fica dentro de um '
                        'MCC, cadastre GOOGLE_ADS_LOGIN_CUSTOMER_ID com o id do MCC (só dígitos).')
            elif r.status_code == 404:
                # 404 aqui quase nunca é o id: é a VERSÃO da API. O Google
                # aposenta cada uma ~1 ano depois de lançar e a antiga some, o
                # que derruba tudo de uma vez sem nenhuma outra pista.
                dica = (f'A API está configurada na versão {_ADS_API_VERSAO}. Se ela foi aposentada, '
                        'o Google responde 404 em tudo — troque GOOGLE_ADS_API_VERSAO por uma versão '
                        'ativa. Se a versão estiver certa, o Customer ID é que não existe (só dígitos, '
                        'sem hífens).')
            passo('Conta do Google Ads', False, f"HTTP {r.status_code}: {corpo}", dica)
            return {'ok': False, 'passos': passos}
    except Exception as e:
        passo('Conta do Google Ads', False, e, '')
        return {'ok': False, 'passos': passos}

    # Degrau 3: a ação de conversão existe e é do tipo que aceita upload?
    acao_nome = ''
    try:
        r = _requests.post(f"{_ADS_API}/customers/{cfg['customer_id']}/googleAds:search",
                           headers=headers, timeout=30,
                           json={'query': 'SELECT conversion_action.id, conversion_action.name, '
                                          'conversion_action.type, conversion_action.status '
                                          'FROM conversion_action WHERE conversion_action.id = '
                                          f"{int(re.sub(r'[^0-9]', '', cfg['conversion_action_id']) or 0)}"})
        achou = ((r.json() or {}).get('results') or []) if r.status_code == 200 else []
        if achou:
            ca = achou[0].get('conversionAction') or {}
            acao_nome = ca.get('name') or ''
            tipo = ca.get('type') or ''
            ok_tipo = tipo in ('UPLOAD_CLICKS', 'UPLOAD_CALLS')
            passo('Ação de conversão', ok_tipo,
                  f"{acao_nome} · tipo {tipo} · {ca.get('status') or '?'}",
                  '' if ok_tipo else ('Esta ação não é do tipo "Importar > Cliques" (UPLOAD_CLICKS). '
                                      'Conversão offline por gclid só entra numa ação desse tipo — '
                                      'crie uma nova no Google Ads e use o id dela.'))
            if not ok_tipo:
                return {'ok': False, 'passos': passos, 'conta': conta}
        else:
            passo('Ação de conversão', False,
                  f"HTTP {r.status_code}: {r.text[:300]}" if r.status_code != 200 else 'id não encontrado nesta conta',
                  'O Conversion Action ID não existe nesta conta. Ele aparece na URL quando você abre a '
                  'conversão em Metas > Conversões (ctId=...).')
            return {'ok': False, 'passos': passos, 'conta': conta}
    except Exception as e:
        passo('Ação de conversão', False, e, '')
        return {'ok': False, 'passos': passos, 'conta': conta}

    # Degrau 4: a ENTREGA, pela Data Manager API — que é por onde passa qualquer
    # integração nova (o caminho antigo do Google Ads foi fechado). validateOnly
    # deixa o Google conferir o pedido inteiro sem gravar conversão nenhuma, que
    # é exatamente o que um botão de teste deve fazer.
    try:
        ev_teste = {'eventSource': 'WEB',
                    'adIdentifiers': {'gclid': 'TESTE_JOB_SEM_CLIQUE_REAL'},
                    'eventTimestamp': datetime.now(TZ_SP).isoformat(timespec='seconds'),
                    'conversionValue': 0.01, 'currency': 'BRL',
                    'transactionId': 'job-teste-conexao',
                    'consent': {'adUserData': 'CONSENT_GRANTED', 'adPersonalization': 'CONSENT_GRANTED'}}
        r = _requests.post(f"{_DM_API}/events:ingest", timeout=45,
                           headers={'Authorization': headers['Authorization'],
                                    'Content-Type': 'application/json'},
                           json={'destinations': _dm_destino(cfg),
                                 'events': [ev_teste],
                                 'validateOnly': True})
        if r.status_code == 200:
            passo('Entrega da conversão', True,
                  'O Google aceitou o pedido de teste sem gravar nada (validação). Autenticação, conta '
                  'e ação de conversão estão todas certas.')
        else:
            erro_msg = _dm_erro_legivel(r.status_code, r.text)
            dica = ''
            if 'SCOPE' in (r.text or '').upper():
                dica = ('Este é o degrau que fica faltando quando o refresh token foi gerado só para ler o '
                        'Google Ads. Entregar conversão exige um segundo escopo.')
            elif r.status_code == 400:
                dica = ('Erro 400 nos parâmetros da requisição para a Data Manager API. Confira a resposta do Google.')
            passo('Entrega da conversão', False, erro_msg, dica)
            return {'ok': False, 'passos': passos, 'conta': conta}
    except Exception as e:
        passo('Entrega da conversão', False, e, '')
        return {'ok': False, 'passos': passos, 'conta': conta}

    return {'ok': True, 'passos': passos, 'conta': conta, 'acao': acao_nome}


def _clique_aplicar_no_lead(conn, lead_id, tel_norm):
    """Se havia um clique guardado pra este telefone, gruda no lead.

    Chamado depois que o lead nasce. É o que fecha a corrida: a página avisa o
    JOB na hora do envio do formulário, mas o lead só entra no CRM minutos
    depois (n8n, planilha, cache do Google). Sem isto, o clique chegava antes
    do lead e não tinha onde encostar."""
    if not lead_id or not tel_norm:
        return False
    try:
        p = conn.execute("SELECT * FROM clique_pendente WHERE telefone_norm=?", (tel_norm,)).fetchone()
        if not p:
            return False
        # A COLUNA gclid SÓ RECEBE gclid. gbraid/wbraid ficam em dados_extras,
        # que é de onde _ads_click_id_do_lead os lê COM O TIPO CERTO. Enfiar um
        # gbraid na coluna do gclid faria o envio rotular o identificador
        # errado, e o Google recusa — o campo tem que casar com a origem.
        clique_col = (p['gclid'] or '').strip()
        if not (clique_col or (p['gbraid'] or '').strip() or (p['wbraid'] or '').strip()):
            return False
        atual = conn.execute("SELECT gclid, dados_extras FROM crm_leads WHERE id=?", (lead_id,)).fetchone()
        if atual and (atual['gclid'] or '').strip():
            return False  # já tem clique: o primeiro é o que trouxe a pessoa
        extras = {}
        try:
            extras = json.loads((atual['dados_extras'] if atual else '') or '{}') or {}
        except Exception:
            extras = {}
        cl = extras.get('click') or {}
        for k in ('gclid', 'gbraid', 'wbraid', 'fbclid'):
            if (p[k] or '').strip():
                cl[k] = p[k].strip()
        if (p['landing'] or '').strip():
            cl['landing'] = p['landing'].strip()
        try:
            for k, v in (json.loads(p['utm_json'] or '{}') or {}).items():
                cl.setdefault(k, v)
        except Exception:
            pass
        extras['click'] = cl
        conn.execute("UPDATE crm_leads SET gclid=?, dados_extras=?, trafego=COALESCE(NULLIF(trafego,''),?) WHERE id=?",
                     (clique_col or None, json.dumps(extras, ensure_ascii=False), 'Pago', lead_id))
        conn.execute("UPDATE clique_pendente SET aplicado_em=? WHERE telefone_norm=?", (_agora_sp(), tel_norm))
        conn.execute("""INSERT INTO crm_atividades (lead_id, usuario_nome, tipo, descricao, criado_em)
                        VALUES (?,?,?,?,?)""",
                     (lead_id, 'Sistema', 'edicao',
                      'Clique do anúncio ligado a este lead (avisado pela página no envio do formulário)',
                      _agora_sp()))
        return True
    except Exception as e:
        app.logger.info(f"[CLIQUE] não aplicado no lead {lead_id}: {e}")
        return False


@app.route('/api/clique', methods=['POST', 'OPTIONS'])
def api_clique():
    """A landing page avisa o JOB, na hora, de qual clique trouxe a pessoa.

    POR QUE ISTO EXISTE: o caminho normal do lead é página -> n8n -> planilha ->
    JOB, e quem grava a planilha não leva o identificador do clique. Medido:
    1.417 linhas, nenhuma coluna de clique; 5.627 leads no CRM, zero com gclid.
    Enquanto essa coluna não existir, a conversão offline não tem o que enviar.
    Este atalho tira o n8n do caminho do CLIQUE (o lead continua indo por lá,
    sem nada duplicado): a página manda telefone + clique direto pra cá.

    NÃO CRIA LEAD, de propósito. Só encosta o clique num lead que já existe, ou
    guarda esperando ele chegar. Endpoint público — landing page não tem como
    guardar segredo —, e por isso o pior que alguém de fora consegue fazer é
    encostar um clique errado num telefone que ele já conhece. Não expõe
    nenhum dado: responde sempre a mesma coisa, ache ou não ache o lead."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    d = request.json or {}
    tel = _normalizar_telefone(str(d.get('telefone') or d.get('phone') or ''))
    ids = {k: str(d.get(k) or '').strip()[:200] for k in ('gclid', 'gbraid', 'wbraid', 'fbclid')}
    if not tel or not any(ids.values()):
        return _wa_cors(jsonify({'ok': True}))
    utm = {k: str(d.get(k) or '').strip()[:200] for k in
           ('utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content')}
    utm = {k: v for k, v in utm.items() if v}
    landing = str(d.get('landing_url') or d.get('page') or '').strip()[:500]
    try:
        conn = db()
        agora = _agora_sp()
        # DB_MODE, nao `is_pg`: is_pg e variavel local de init_db, nao existe
        # no escopo do modulo — usar aqui viraria NameError engolido pelo except.
        if DB_MODE == 'postgres':
            conn.execute("""INSERT INTO clique_pendente
                (telefone_norm,gclid,gbraid,wbraid,fbclid,landing,utm_json,criado_em)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s)
                ON CONFLICT (telefone_norm) DO NOTHING""",
                (tel, ids['gclid'], ids['gbraid'], ids['wbraid'], ids['fbclid'],
                 landing, json.dumps(utm, ensure_ascii=False), agora))
        else:
            conn.execute("""INSERT OR IGNORE INTO clique_pendente
                (telefone_norm,gclid,gbraid,wbraid,fbclid,landing,utm_json,criado_em)
                VALUES (?,?,?,?,?,?,?,?)""",
                (tel, ids['gclid'], ids['gbraid'], ids['wbraid'], ids['fbclid'],
                 landing, json.dumps(utm, ensure_ascii=False), agora))
        # Se o lead já existe (pessoa que voltou), gruda agora mesmo.
        lead = conn.execute("SELECT id FROM crm_leads WHERE telefone_norm=? ORDER BY id LIMIT 1",
                            (tel,)).fetchone()
        if lead:
            _clique_aplicar_no_lead(conn, lead['id'], tel)
        conn.commit(); close_db(conn)
    except Exception as e:
        app.logger.warning(f"[CLIQUE] falhou: {e}")
    return _wa_cors(jsonify({'ok': True}))


def _clique_casar_pendentes(limite=500):
    """Casa os cliques que estavam esperando com os leads que já chegaram.

    Roda junto do import: o lead entra pela planilha alguns minutos depois do
    formulário, então é aqui que a maior parte dos cliques encontra seu dono."""
    n = 0
    try:
        conn = db()
        pend = conn.execute("""SELECT p.telefone_norm, l.id lead_id
            FROM clique_pendente p JOIN crm_leads l ON l.telefone_norm = p.telefone_norm
            WHERE p.aplicado_em IS NULL AND COALESCE(l.gclid,'') = ''
            ORDER BY p.criado_em LIMIT ?""", (limite,)).fetchall()
        for r in pend:
            if _clique_aplicar_no_lead(conn, r['lead_id'], r['telefone_norm']):
                n += 1
        conn.commit(); close_db(conn)
        if n:
            app.logger.info(f"[CLIQUE] {n} clique(s) ligados ao lead")
    except Exception as e:
        app.logger.warning(f"[CLIQUE] casamento falhou: {e}")
    return n


def _ads_redirect_uri():
    """Endereço de volta da autorização. Tem que bater LETRA POR LETRA com o que
    está cadastrado no cliente OAuth do Google — é a causa do redirect_uri_mismatch."""
    base = (os.environ.get('APP_URL') or 'https://job-serenus-production.up.railway.app').strip().rstrip('/')
    return base + '/google-ads/autorizado'


@app.route('/google-ads/autorizar')
@login_required
@admin_required
def google_ads_autorizar():
    """Manda pro Google pedindo os DOIS escopos e volta com o refresh token.

    Por que dentro do JOB: o cliente OAuth da Serenus é do tipo 'aplicativo Web',
    então não aceita http://localhost — o caminho de linha de comando morre com
    redirect_uri_mismatch. Aqui o endereço de volta é fixo e conhecido, e o
    token cai direto no lugar certo, sem ninguém copiar segredo pra lugar nenhum."""
    cfg, _ = _ads_config()
    if not cfg['client_id']:
        return "Falta GOOGLE_ADS_CLIENT_ID no servidor.", 400
    from urllib.parse import urlencode
    return redirect('https://accounts.google.com/o/oauth2/v2/auth?' + urlencode({
        'client_id': cfg['client_id'],
        'redirect_uri': _ads_redirect_uri(),
        'response_type': 'code',
        'access_type': 'offline',
        # prompt=consent é obrigatório aqui: sem ele o Google devolve só o
        # access_token quando já existe consentimento, e o refresh_token —
        # que é o que precisamos guardar — não vem.
        'prompt': 'consent',
        'include_granted_scopes': 'true',
        'scope': ' '.join(_ADS_ESCOPOS),
    }))


@app.route('/google-ads/autorizado')
@login_required
@admin_required
def google_ads_autorizado():
    """Volta do Google: troca o código por refresh token e guarda."""
    erro = (request.args.get('error') or '').strip()
    codigo = (request.args.get('code') or '').strip()
    def pagina(titulo, corpo, cor='var(--rosa)'):
        return render_template_string(
            """{% extends 'base.html' %}{% block content %}<div class="page">
            <div class="card"><div class="card-header"><h3>{{ t }}</h3></div>
            <div style="padding:0 16px 18px; font-size:13.5px; line-height:1.7; color:var(--cinza); max-width:70ch;">
            {{ c|safe }}<div style="margin-top:16px;"><a class="btn btn-sm" href="/google-ads">Voltar para Conversão offline</a></div>
            </div></div></div>{% endblock %}""", t=titulo, c=corpo)
    if erro:
        return pagina('A autorização não foi concluída',
                      f'O Google respondeu <code>{erro}</code>. Se for <code>redirect_uri_mismatch</code>, '
                      f'falta cadastrar <code>{_ads_redirect_uri()}</code> como URI de redirecionamento '
                      'autorizado no cliente OAuth, no Google Cloud.')
    if not codigo:
        return pagina('Faltou o código', 'O Google não devolveu o código de autorização. Tente de novo.')
    cfg, _ = _ads_config()
    try:
        r = _requests.post('https://oauth2.googleapis.com/token', timeout=25, data={
            'code': codigo, 'client_id': cfg['client_id'], 'client_secret': cfg['client_secret'],
            'redirect_uri': _ads_redirect_uri(), 'grant_type': 'authorization_code'})
        d = r.json() or {}
        if r.status_code != 200 or not d.get('refresh_token'):
            return pagina('O Google não devolveu um refresh token',
                          f'Resposta: <code>{str(d)[:400]}</code><br><br>Se vier <code>invalid_grant</code>, '
                          'o código já foi usado — comece de novo pelo botão Autorizar.')
        conn = db()
        if DB_MODE == 'postgres':
            conn.execute("""INSERT INTO config (chave,valor) VALUES (%s,%s)
                            ON CONFLICT (chave) DO UPDATE SET valor=EXCLUDED.valor""",
                         ('google_ads_refresh_token', d['refresh_token']))
        else:
            conn.execute("INSERT OR REPLACE INTO config (chave,valor) VALUES (?,?)",
                         ('google_ads_refresh_token', d['refresh_token']))
        conn.commit(); close_db(conn)
        escopos = d.get('scope') or ''
        tem_dm = 'datamanager' in escopos
        return pagina('Autorização concluída',
                      ('Escopos autorizados: <code>' + (escopos or '(não informado)') + '</code><br><br>'
                       + ('O escopo de entrega de conversão está presente. Use "Testar ligação" na tela '
                          'de Conversão offline para confirmar ponta a ponta.'
                          if tem_dm else
                          '<b style="color:var(--rosa);">Atenção: o escopo de entrega (datamanager) NÃO veio.</b> '
                          'Ele é sensível e precisa estar marcado na tela de consentimento OAuth do projeto, '
                          'em Google Auth Platform &gt; Acesso a dados.')))
    except Exception as e:
        return pagina('Falhou ao trocar o código', f'<code>{str(e)[:400]}</code>')


