def _fluxo_render_texto(s, nome='', consultor='', link=''):
    """Substitui os placeholders {nome}/{consultor}/{link} SEM usar .format() —
    texto digitado pelo usuário no editor pode ter chaves soltas que
    estourariam KeyError e derrubariam o passo inteiro."""
    return ((s or '').replace('{nome}', nome or '')
                     .replace('{consultor}', consultor or '')
                     .replace('{link}', link or ''))


def _seed_fluxos_padrao(conn):
    """Cadastra os 3 fluxos pré-definidos na primeira vez que a tabela `fluxos`
    estiver vazia. Não sobrescreve edições feitas depois (gatilho_etapa, ativo)."""
    ja_tem = conn.execute("SELECT COUNT(*) c FROM fluxos").fetchone()['c']
    if ja_tem:
        return
    for f in FLUXOS_PADRAO:
        conn.execute("INSERT INTO fluxos (nome, descricao, gatilho_etapa, ativo) VALUES (?,?,?,1)",
                     (f['nome'], f['descricao'], None))
        fluxo_id = (conn.execute("SELECT lastval() AS id").fetchone()['id'] if DB_MODE == "postgres"
                    else conn.execute("SELECT last_insert_rowid() id").fetchone()['id'])
        for i, (canal, template, delay) in enumerate(f['passos']):
            conn.execute("INSERT INTO fluxo_passos (fluxo_id, ordem, canal, template, delay_dias) VALUES (?,?,?,?,?)",
                         (fluxo_id, i, canal, template, delay))
    conn.commit()
    print(f"[FLUXOS] {len(FLUXOS_PADRAO)} fluxo(s) padrão cadastrados")


def _corpo_email_fluxo(tpl, nome_lead, corretor_nome, link_click, foto_url=None):
    """HTML no mesmo padrão visual do e-mail de contato (cartão do consultor em
    tabela, não flexbox — ver histórico do bug de renderização no Gmail/Outlook),
    mas com múltiplos parágrafos (fluxos são narrativos, não uma frase só)."""
    import html as _html
    primeiro = (_nome_pra_pessoa(nome_lead or '')).strip().split(' ')[0].title() if nome_lead else ''
    # Escape DEPOIS de substituir os placeholders: nome do lead vem de fonte
    # externa (LP/planilha) e texto de passo personalizado vem do editor —
    # nenhum dos dois pode injetar HTML no e-mail.
    corpo_paragrafos = ''.join(
        f"<p style='font-size:14px;color:#4a4f63;margin:0 0 16px;line-height:1.7;'>"
        f"{_html.escape(_fluxo_render_texto(p, nome=primeiro or 'tudo bem', consultor=corretor_nome, link=link_click))}</p>"
        for p in tpl['paragrafos'] if (p or '').strip()
    )
    corretor_nome = _html.escape(corretor_nome or 'Serenus')
    cta_txt = _html.escape(tpl.get('cta') or 'Falar com o consultor no WhatsApp')
    cartao_consultor = (
        "<table role='presentation' cellpadding='0' cellspacing='0' border='0' "
        "style='background:#f8f9fb;border-radius:12px;margin-bottom:26px;'><tr>"
        f"<td style='padding:14px 0 14px 16px;'>"
        + (f"<img src='{foto_url}' width='52' height='52' alt='{corretor_nome}' "
           "style='width:52px;height:52px;border-radius:50%;object-fit:cover;display:block;border:2px solid #fff;box-shadow:0 1px 4px rgba(0,0,0,.12);'>"
           if foto_url else
           f"<div style='width:52px;height:52px;border-radius:50%;background:#1a1d2e;color:#fff;display:flex;align-items:center;justify-content:center;"
           f"font-size:19px;font-weight:700;'>{(corretor_nome or '?')[:1].upper()}</div>")
        + f"</td><td style='padding:14px 16px 14px 14px;'>"
        f"<div style='font-size:10.5px;color:#8c93a8;text-transform:uppercase;letter-spacing:.6px;font-weight:700;'>Seu consultor</div>"
        f"<div style='font-size:15px;color:#1a1d2e;font-weight:700;margin-top:2px;'>{corretor_nome}</div>"
        "</td></tr></table>"
    )
    return (
        "<div style='background:#f4f6f9;padding:30px 12px;font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif;'>"
        "<div style='max-width:560px;margin:0 auto;background:#fff;border-radius:14px;overflow:hidden;"
        "box-shadow:0 4px 24px rgba(0,0,0,.08);'>"
        "<div style='background:#1a1d2e;padding:22px 30px;'>"
        "<span style='color:#fff;font-size:19px;font-weight:800;letter-spacing:2px;'>SERENUS</span>"
        "<span style='color:#8c93a8;font-size:10px;letter-spacing:2px;display:block;margin-top:2px;'>CORRETORA DE SAÚDE</span></div>"
        "<div style='padding:30px;'>"
        f"{corpo_paragrafos}"
        f"{cartao_consultor}"
        f"<div style='text-align:center;margin-bottom:26px;'><a href='{link_click}' "
        "style='display:inline-block;background:#25d366;color:#fff;text-decoration:none;font-weight:700;"
        f"font-size:15px;padding:14px 34px;border-radius:10px;'>{cta_txt}</a></div>"
        "<p style='font-size:12px;color:#8c93a8;margin:0;line-height:1.6;'>Se o botão não funcionar, "
        f"copie este link no navegador:<br><a href='{link_click}' style='color:#3b82f6;word-break:break-all;'>{link_click}</a></p>"
        "</div>"
        "<div style='padding:16px 30px;background:#fafbfc;border-top:1px solid #eef0f3;font-size:11px;"
        "color:#9aa0b0;line-height:1.5;'>Serenus Corretora de Saúde. Você recebeu este e-mail porque "
        "solicitou uma cotação de plano de saúde.</div>"
        f"</div></div>"
    )


def _fluxo_inscrever(conn, fluxo_id, lead_id, etapa_origem=None, iniciado_por=None):
    """Cria uma inscrição ativa (se ainda não houver uma ativa pro mesmo lead+fluxo).
    Respeita o delay do 1º passo: delay 0 sai na próxima rodada do motor."""
    ja = conn.execute(
        "SELECT id FROM fluxo_inscricoes WHERE fluxo_id=? AND lead_id=? AND status='ativo'",
        (fluxo_id, lead_id)).fetchone()
    if ja:
        return None
    p0 = conn.execute(
        "SELECT delay_dias FROM fluxo_passos WHERE fluxo_id=? ORDER BY ordem LIMIT 1", (fluxo_id,)).fetchone()
    delay0 = (p0['delay_dias'] if p0 else 0) or 0
    envio = (datetime.now(TZ_SP) + timedelta(days=delay0)).strftime('%Y-%m-%d %H:%M:%S')
    conn.execute("""INSERT INTO fluxo_inscricoes
        (fluxo_id, lead_id, etapa_origem, status, passo_atual, proximo_envio_em, iniciado_por)
        VALUES (?,?,?,'ativo',0,?,?)""",
        (fluxo_id, lead_id, etapa_origem, envio, iniciado_por))
    return (conn.execute("SELECT lastval() AS id").fetchone()['id'] if DB_MODE == "postgres"
            else conn.execute("SELECT last_insert_rowid() id").fetchone()['id'])


def _fluxo_cancelar_por_etapa(conn, lead_id, nova_etapa):
    """Cancela inscrições ativas cujo fluxo está preso a uma etapa (gatilho_etapa)
    diferente da nova etapa do lead. Fluxos iniciados manualmente (sem gatilho_etapa)
    não são afetados por mudança de etapa — só cancelamento manual os para."""
    ativas = conn.execute("""
        SELECT fi.id FROM fluxo_inscricoes fi JOIN fluxos f ON f.id = fi.fluxo_id
        WHERE fi.lead_id=? AND fi.status='ativo' AND f.gatilho_etapa IS NOT NULL AND f.gatilho_etapa <> ?
    """, (lead_id, nova_etapa)).fetchall()
    for row in ativas:
        conn.execute("UPDATE fluxo_inscricoes SET status='cancelado', finalizado_em=? WHERE id=?",
                     (_agora_sp(), row['id']))


def _fluxo_autoiniciar_por_etapa(conn, lead_id, nova_etapa):
    """Inscreve o lead em qualquer fluxo ativo cujo gatilho_etapa bate com a etapa nova."""
    fluxos = conn.execute("SELECT id FROM fluxos WHERE ativo=1 AND gatilho_etapa=?", (nova_etapa,)).fetchall()
    for f in fluxos:
        _fluxo_inscrever(conn, f['id'], lead_id, etapa_origem=nova_etapa)


_FLUXO_MAX_POR_RODADA = 50
# 'botconversa' saiu em 31/07/2026: a Serenus nao usa mais. Passos antigos
# continuam no banco (historico preservado), mas nao da mais pra criar novo.
FLUXO_CANAIS = ('email', 'sms', 'whatsapp')


def _renderizar_modelo_html(html, nome_lead):
    """Substitui os placeholders de nome no HTML enviado pelo admin. Cobre tanto
    {{nome}} (convenção do JOB) quanto {{ contact.FIRSTNAME }} (tag nativa do
    Brevo) — como o envio é pela API transacional, não pela automação do Brevo,
    essa segunda tag nunca seria substituída sozinha; sem isso o e-mail chegaria
    com "{{ contact.FIRSTNAME }}" literal no texto."""
    primeiro = (nome_lead or '').strip().split(' ')[0].title() if nome_lead else 'tudo bem'
    out = html or ''
    for token in ('{{nome}}', '{{ nome }}', '{{contact.FIRSTNAME}}', '{{ contact.FIRSTNAME }}'):
        out = out.replace(token, primeiro)
    return out


def _fluxo_executar_passo(conn, passo, lead):
    """Executa 1 passo do fluxo pra 1 lead. Retorna (ok, erro, modelo_id).
    Conteúdo do passo: personalizado (JSON gravado pelo editor), modelo pronto
    do catálogo embutido (FLUXO_TEMPLATES/SMS_TEMPLATES_LEAD), ou modelo
    enviado pelo admin (tabela modelos_conteudo, chave 'upload_<id>')."""
    template_key = passo['template'] or ''
    modelo_id = None
    tpl = None

    if template_key.startswith('upload_'):
        try:
            modelo_id = int(template_key.split('_', 1)[1])
        except (ValueError, IndexError):
            modelo_id = None
        modelo = conn.execute("SELECT * FROM modelos_conteudo WHERE id=? AND ativo=1", (modelo_id,)).fetchone() if modelo_id else None
        if not modelo:
            return False, f"Modelo enviado #{modelo_id} não existe mais ou foi desativado", modelo_id
        modelo = dict(modelo)
        tpl = {'assunto': modelo.get('assunto') or '', 'corpo_html': modelo.get('corpo_html'),
               'corpo_texto': modelo.get('corpo_texto')}
    elif passo.get('conteudo'):
        try:
            tpl = json.loads(passo['conteudo']) if isinstance(passo['conteudo'], str) else dict(passo['conteudo'])
        except Exception:
            tpl = None
    if tpl is None and not template_key.startswith('upload_'):
        tpl = FLUXO_TEMPLATES.get(template_key)

    urow = conn.execute("SELECT id, nome, foto FROM usuarios WHERE id=?",
                         (lead.get('responsavel_id'),)).fetchone()
    consultor_nome = (urow['nome'] if urow else None) or 'Serenus'
    foto_url = f"{_SITE_BASE_URL}/avatar/{urow['id']}" if urow and urow['foto'] else None
    primeiro = (lead.get('nome') or '').strip().split(' ')[0].title()
    link_wpp = f"https://wa.me/{_whatsapp_do_consultor(conn, lead.get('responsavel_id'))}"
    canal = passo['canal']

    if canal == 'email':
        email_lead = (lead.get('email') or '').strip()
        if not email_lead or '@' not in email_lead:
            return False, 'Lead sem e-mail válido', modelo_id
        if modelo_id is not None:
            if not tpl.get('corpo_html'):
                return False, f"Modelo enviado #{modelo_id} está sem HTML", modelo_id
            assunto = _renderizar_modelo_html(tpl.get('assunto') or 'Serenus Corretora', lead.get('nome'))
            corpo = _renderizar_modelo_html(tpl['corpo_html'], lead.get('nome'))
            ok = _enviar_email(email_lead, assunto, corpo, remetente_nome='Cotação de Plano de Saúde')
            return ok, (None if ok else (getattr(_enviar_email, 'ultimo_erro', None) or 'Falha ao enviar e-mail')), modelo_id
        if not tpl or not tpl.get('paragrafos'):
            return False, f"Passo de e-mail sem conteúdo (template: {template_key})", modelo_id
        assunto = _fluxo_render_texto(tpl.get('assunto') or 'Serenus Corretora',
                                       nome=primeiro or 'tudo bem', consultor=consultor_nome)
        corpo = _corpo_email_fluxo(tpl, lead.get('nome'), consultor_nome, link_wpp, foto_url)
        ok = _enviar_email(email_lead, assunto, corpo, remetente_nome='Cotação de Plano de Saúde')
        return ok, (None if ok else (getattr(_enviar_email, 'ultimo_erro', None) or 'Falha ao enviar e-mail')), modelo_id

    if not lead.get('telefone'):
        return False, 'Lead sem telefone', modelo_id

    if modelo_id is not None and canal == 'sms':
        mensagem = _renderizar_modelo_html(tpl.get('corpo_texto') or '', lead.get('nome')).strip()
        if not mensagem:
            return False, f"Modelo enviado #{modelo_id} está sem texto", modelo_id
        ok, erro = _enviar_sms(lead['telefone'], mensagem)
        return ok, erro, modelo_id

    if canal == 'sms':
        if passo['template'] in SMS_TEMPLATES_LEAD:
            # Modelo aprovado na operadora: monta EXATAMENTE como no envio manual
            # (link wa.me do consultor, nunca truncar nome) — ver _texto_sms_lead.
            # split() em nome vazio devolve [] — o "or ['']" evita IndexError.
            nome_lead = ((lead.get('nome') or '').split() or [''])[0]
            consultor_primeiro = ((consultor_nome or '').split() or ['Serenus'])[0]
            mensagem, _n = _texto_sms_lead(passo['template'], consultor_primeiro, link_wpp, nome_lead)
        else:
            mensagem = _fluxo_render_texto((tpl or {}).get('texto'),
                                            nome=primeiro, consultor=consultor_nome, link=link_wpp).strip()
        if not mensagem:
            return False, 'Passo de SMS sem texto', modelo_id
        ok, erro = _enviar_sms(lead['telefone'], mensagem)
        return ok, erro, modelo_id

    texto = _fluxo_render_texto((tpl or {}).get('texto') or '\n\n'.join((tpl or {}).get('paragrafos') or []),
                                 nome=primeiro, consultor=consultor_nome, link=link_wpp).strip()
    if not texto:
        return False, f'Passo de {canal} sem texto', modelo_id
    if canal == 'whatsapp':
        token = _waspeed_token_do_usuario(conn, lead.get('responsavel_id'))
        ok, erro = _enviar_whatsapp_waspeed(token, lead.get('telefone'), texto)
        return ok, erro, modelo_id
    if canal == 'botconversa':
        # Canal removido em 31/07/2026 — o BotConversa deixou de existir pra
        # Serenus. Passo antigo de fluxo nao envia nada e diz por que, em vez de
        # falhar com "canal desconhecido" e parecer defeito do sistema.
        return False, 'Canal BotConversa foi removido — troque o passo para WhatsApp', modelo_id
    return False, f'Canal desconhecido: {canal}', modelo_id


def _varrer_fila_vencida():
    """Vence a fila de envio sem depender de nenhuma extensao estar viva.

    O vencimento sempre existiu, mas morava DENTRO de /fila/proximo — a rota
    que a extensao chama. Consequencia perversa: exatamente o consultor cuja
    extensao parou (o caso que mais importa) nunca disparava a checagem. As
    mensagens dele ficavam 'pendente' pra sempre: nao saiam, nao venciam e nao
    avisavam ninguem.

    Foi assim que 5 aberturas de lead pago da Aline e da Bianca ficaram de 8 a
    15 horas paradas — leads pagos sem primeira mensagem, e ninguem sabendo.

    Roda de 5 em 5 minutos, varre todo mundo, e cada vencimento vira pendencia
    no sino com o telefone de quem ficou sem resposta.
    """
    try:
        conn = db()
    except Exception as e:
        app.logger.warning(f"[FILA_VARRE] sem banco: {e}")
        return
    try:
        n = _wa_fila_vencer_atrasados(conn)
        if n:
            conn.commit()
            app.logger.warning(f"[FILA_VARRE] {n} item(ns) vencido(s) — pendencia aberta pra cada um")
    except Exception as e:
        app.logger.warning(f"[FILA_VARRE] {e}")
        try: conn.rollback()
        except Exception: pass
    finally:
        try: close_db(conn)
        except Exception: pass


def _processar_fluxos_pendentes():
    """Motor de disparo: roda 1x/dia (+ fallback por request) e envia o passo
    pendente de cada inscrição ativa cujo proximo_envio_em já chegou.
    delay_dias de cada passo = dias de espera após o passo anterior."""
    try:
        conn = db()
        agora = datetime.now(TZ_SP)
        agora_str = _agora_sp()
        pendentes = conn.execute("""
            SELECT fi.*, f.nome AS fluxo_nome FROM fluxo_inscricoes fi
            JOIN fluxos f ON f.id = fi.fluxo_id
            WHERE fi.status='ativo' AND f.ativo=1 AND fi.proximo_envio_em <= ?
            ORDER BY fi.proximo_envio_em ASC LIMIT ?
        """, (agora_str, _FLUXO_MAX_POR_RODADA)).fetchall()
        enviados = 0
        for insc in pendentes:
            insc = dict(insc)
            # "Claim" atômico: empurra proximo_envio_em 15 min pra frente ANTES de
            # enviar e comita na hora. O gunicorn roda 3 workers, cada um com seu
            # scheduler — sem isso, os 3 leriam as mesmas inscrições às 08:00 e o
            # lead receberia cada passo em triplicata. Só quem ganha o UPDATE
            # (rowcount 1) processa; os outros veem 0 e pulam.
            claim = conn.execute(
                "UPDATE fluxo_inscricoes SET proximo_envio_em=? WHERE id=? AND status='ativo' AND proximo_envio_em<=?",
                ((agora + timedelta(minutes=15)).strftime('%Y-%m-%d %H:%M:%S'), insc['id'], agora_str))
            if getattr(claim, 'rowcount', 1) == 0:
                continue
            conn.commit()
            try:
                passos = [dict(p) for p in conn.execute(
                    "SELECT * FROM fluxo_passos WHERE fluxo_id=? ORDER BY ordem", (insc['fluxo_id'],)).fetchall()]
                passo_idx = insc['passo_atual']
                if passo_idx >= len(passos):
                    conn.execute("UPDATE fluxo_inscricoes SET status='concluido', finalizado_em=? WHERE id=?",
                                 (_agora_sp(), insc['id']))
                    conn.commit()
                    continue
                passo = passos[passo_idx]
                lead = conn.execute("SELECT * FROM crm_leads WHERE id=?", (insc['lead_id'],)).fetchone()
                if lead:
                    ok, erro, modelo_id = _fluxo_executar_passo(conn, passo, dict(lead))
                else:
                    ok, erro, modelo_id = False, 'Lead não encontrado', None
                conn.execute("INSERT INTO fluxo_envio_log (inscricao_id, passo_id, canal, ok, erro, modelo_id) VALUES (?,?,?,?,?,?)",
                             (insc['id'], passo['id'], passo['canal'], 1 if ok else 0, erro, modelo_id))
                proximo_passo_idx = passo_idx + 1
                if proximo_passo_idx >= len(passos):
                    conn.execute("UPDATE fluxo_inscricoes SET status='concluido', passo_atual=?, finalizado_em=? WHERE id=?",
                                 (proximo_passo_idx, _agora_sp(), insc['id']))
                else:
                    delay_prox = passos[proximo_passo_idx]['delay_dias'] or 0
                    proximo_envio = agora + timedelta(days=delay_prox)
                    conn.execute("UPDATE fluxo_inscricoes SET passo_atual=?, proximo_envio_em=? WHERE id=?",
                                 (proximo_passo_idx, proximo_envio.strftime('%Y-%m-%d %H:%M:%S'), insc['id']))
                conn.commit()
                if ok:
                    enviados += 1
            except Exception as e:
                # Uma inscrição com dado ruim NUNCA pode envenenar a rodada inteira
                # (travaria todos os fluxos pra sempre, sempre na mesma inscrição).
                # Rollback + reagenda pra amanhã e segue pras próximas.
                try:
                    conn.rollback()
                except Exception:
                    pass
                app.logger.error(f"[FLUXOS] Erro na inscrição {insc['id']} (lead {insc.get('lead_id')}): {e}")
                try:
                    conn.execute("UPDATE fluxo_inscricoes SET proximo_envio_em=? WHERE id=?",
                                 ((agora + timedelta(days=1)).strftime('%Y-%m-%d %H:%M:%S'), insc['id']))
                    conn.commit()
                except Exception:
                    pass
        close_db(conn)
        if enviados:
            app.logger.info(f"[FLUXOS] {enviados}/{len(pendentes)} passo(s) enviados")
    except Exception as e:
        app.logger.error(f"[FLUXOS] Erro no motor: {e}")
        try:
            close_db(conn)
        except Exception:
            pass


@app.route('/crm/fluxos')
@login_required
@admin_required
def crm_fluxos():
    conn = db()
    fluxos = [dict(f) for f in conn.execute("SELECT * FROM fluxos ORDER BY id").fetchall()]
    for f in fluxos:
        f['passos'] = [dict(p) for p in conn.execute(
            "SELECT * FROM fluxo_passos WHERE fluxo_id=? ORDER BY ordem", (f['id'],)).fetchall()]
        f['ativos'] = conn.execute(
            "SELECT COUNT(*) c FROM fluxo_inscricoes WHERE fluxo_id=? AND status='ativo'", (f['id'],)).fetchone()['c']
        f['concluidos'] = conn.execute(
            "SELECT COUNT(*) c FROM fluxo_inscricoes WHERE fluxo_id=? AND status='concluido'", (f['id'],)).fetchone()['c']
    etapas = [dict(e) for e in carregar_etapas_crm(conn)]
    close_db(conn)
    return render_template('crm_fluxos.html', fluxos=fluxos, etapas=etapas)


@app.route('/crm/fluxos/<int:fid>/toggle', methods=['POST'])
@login_required
@admin_required
def crm_fluxo_toggle(fid):
    conn = db()
    f = conn.execute("SELECT ativo FROM fluxos WHERE id=?", (fid,)).fetchone()
    if not f:
        close_db(conn); return jsonify({"ok": False, "erro": "Fluxo não encontrado"}), 404
    novo = 0 if f['ativo'] else 1
    conn.execute("UPDATE fluxos SET ativo=? WHERE id=?", (novo, fid))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "ativo": bool(novo)})


@app.route('/crm/fluxos/<int:fid>/gatilho', methods=['POST'])
@login_required
@admin_required
def crm_fluxo_gatilho(fid):
    """Define (ou remove) a etapa do funil que dispara este fluxo automaticamente."""
    d = request.json or {}
    gatilho = (d.get('gatilho_etapa') or '').strip() or None
    conn = db()
    f = conn.execute("SELECT id FROM fluxos WHERE id=?", (fid,)).fetchone()
    if not f:
        close_db(conn); return jsonify({"ok": False, "erro": "Fluxo não encontrado"}), 404
    conn.execute("UPDATE fluxos SET gatilho_etapa=? WHERE id=?", (gatilho, fid))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True})


@app.route('/crm/fluxos/novo', methods=['POST'])
@login_required
@admin_required
def crm_fluxo_novo():
    d = request.json or {}
    nome = (d.get('nome') or '').strip()
    if not nome:
        return jsonify({"ok": False, "erro": "Digite o nome do fluxo"}), 400
    conn = db()
    # Nasce desativado (igual ao WaSpeed): só liga depois de montar os passos.
    conn.execute("INSERT INTO fluxos (nome, descricao, gatilho_etapa, ativo) VALUES (?,?,NULL,0)",
                 (nome, (d.get('descricao') or '').strip()))
    fid = (conn.execute("SELECT lastval() AS id").fetchone()['id'] if DB_MODE == "postgres"
           else conn.execute("SELECT last_insert_rowid() id").fetchone()['id'])
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "id": fid})


@app.route('/crm/fluxos/<int:fid>')
@login_required
@admin_required
def crm_fluxo_editor(fid):
    """Editor visual do fluxo (canvas de blocos, modelado no construtor do WaSpeed)."""
    conn = db()
    fluxo = conn.execute("SELECT * FROM fluxos WHERE id=?", (fid,)).fetchone()
    if not fluxo:
        close_db(conn); return redirect('/crm/fluxos')
    fluxo = dict(fluxo)
    passos = []
    for p in conn.execute("SELECT * FROM fluxo_passos WHERE fluxo_id=? ORDER BY ordem", (fid,)).fetchall():
        p = dict(p)
        try:
            conteudo = json.loads(p['conteudo']) if p.get('conteudo') else None
        except Exception:
            conteudo = None
        # Só campos escalares pro |tojson (criado_em vem como datetime no Postgres)
        passos.append({'canal': p['canal'], 'template': p['template'],
                       'delay_dias': p['delay_dias'], 'conteudo': conteudo})
    etapas = [dict(e) for e in carregar_etapas_crm(conn)]
    modelos_email = {f"upload_{m['id']}": {'nome': m['nome'], 'assunto': m['assunto'] or '', 'variante': m['variante']}
                      for m in conn.execute("SELECT id, nome, assunto, variante FROM modelos_conteudo WHERE tipo='email' AND ativo=1 ORDER BY nome").fetchall()}
    modelos_sms = {f"upload_{m['id']}": {'nome': m['nome'], 'exemplo': (m['corpo_texto'] or '')[:200], 'variante': m['variante']}
                   for m in conn.execute("SELECT id, nome, corpo_texto, variante FROM modelos_conteudo WHERE tipo='sms' AND ativo=1 ORDER BY nome").fetchall()}
    close_db(conn)
    return render_template('crm_fluxo_editor.html',
                           fluxo={'id': fluxo['id'], 'nome': fluxo['nome'],
                                  'descricao': fluxo.get('descricao') or '',
                                  'ativo': bool(fluxo.get('ativo')),
                                  'gatilho_etapa': fluxo.get('gatilho_etapa')},
                           passos=passos, etapas=etapas,
                           email_tpls=FLUXO_TEMPLATES,
                           sms_tpls={k: {'nome': v['nome'], 'exemplo': v['sem_nome']}
                                     for k, v in SMS_TEMPLATES_LEAD.items()},
                           modelos_email=modelos_email, modelos_sms=modelos_sms)


@app.route('/crm/fluxos/<int:fid>/salvar', methods=['POST'])
@login_required
@admin_required
def crm_fluxo_salvar(fid):
    """Salva nome, gatilho e a lista completa de passos do editor (substitui tudo).
    Leads já inscritos continuam de onde estão — alterações valem pros próximos envios."""
    d = request.json or {}
    conn = db()
    f = conn.execute("SELECT id FROM fluxos WHERE id=?", (fid,)).fetchone()
    if not f:
        close_db(conn); return jsonify({"ok": False, "erro": "Fluxo não encontrado"}), 404
    nome = (d.get('nome') or '').strip()
    if not nome:
        close_db(conn); return jsonify({"ok": False, "erro": "Nome do fluxo não pode ficar vazio"}), 400
    gatilho = (d.get('gatilho_etapa') or '').strip() or None
    if gatilho and gatilho not in [e['id'] for e in carregar_etapas_crm(conn)]:
        close_db(conn); return jsonify({"ok": False, "erro": "Etapa de gatilho inválida"}), 400
    passos = d.get('passos')
    if not isinstance(passos, list) or len(passos) > 30:
        close_db(conn); return jsonify({"ok": False, "erro": "Lista de passos inválida (máx. 30)"}), 400
    validados = []
    for p in passos:
        canal = (p.get('canal') or '').strip()
        if canal not in FLUXO_CANAIS:
            close_db(conn); return jsonify({"ok": False, "erro": f"Canal inválido: {canal}"}), 400
        try:
            delay = max(0, min(365, int(p.get('delay_dias') or 0)))
        except Exception:
            delay = 0
        template = (p.get('template') or 'custom').strip()
        conteudo = p.get('conteudo')
        if template.startswith('upload_'):
            try:
                modelo_id_check = int(template.split('_', 1)[1])
            except (ValueError, IndexError):
                modelo_id_check = None
            modelo_row = conn.execute("SELECT tipo FROM modelos_conteudo WHERE id=? AND ativo=1", (modelo_id_check,)).fetchone() if modelo_id_check else None
            if not modelo_row or modelo_row['tipo'] != canal:
                close_db(conn); return jsonify({"ok": False, "erro": f"Modelo enviado inválido: {template}"}), 400
            conteudo = None
        elif template != 'custom':
            if canal == 'email' and template not in FLUXO_TEMPLATES:
                close_db(conn); return jsonify({"ok": False, "erro": f"Modelo de e-mail inválido: {template}"}), 400
            if canal == 'sms' and template not in SMS_TEMPLATES_LEAD:
                close_db(conn); return jsonify({"ok": False, "erro": f"Modelo de SMS inválido: {template}"}), 400
            if canal == 'whatsapp':
                close_db(conn); return jsonify({"ok": False, "erro": "WhatsApp usa texto próprio, não modelo"}), 400
            conteudo = None
        else:
            if not isinstance(conteudo, dict):
                close_db(conn); return jsonify({"ok": False, "erro": "Passo personalizado sem conteúdo"}), 400
            if canal == 'email':
                assunto = (conteudo.get('assunto') or '').strip()
                parags = [str(x).strip() for x in (conteudo.get('paragrafos') or []) if str(x or '').strip()]
                if not assunto or not parags:
                    close_db(conn); return jsonify({"ok": False, "erro": "E-mail personalizado precisa de assunto e corpo"}), 400
                conteudo = {'assunto': assunto, 'paragrafos': parags,
                            'cta': (conteudo.get('cta') or '').strip() or 'Falar com o consultor no WhatsApp'}
            else:
                texto = (conteudo.get('texto') or '').strip()
                if not texto:
                    close_db(conn); return jsonify({"ok": False, "erro": f"Passo de {canal} sem texto"}), 400
                conteudo = {'texto': texto}
        validados.append((canal, template, delay,
                          json.dumps(conteudo, ensure_ascii=False) if conteudo else None))
    conn.execute("UPDATE fluxos SET nome=?, descricao=?, gatilho_etapa=? WHERE id=?",
                 (nome, (d.get('descricao') or '').strip(), gatilho, fid))
    conn.execute("DELETE FROM fluxo_passos WHERE fluxo_id=?", (fid,))
    for i, (canal, template, delay, conteudo) in enumerate(validados):
        conn.execute("""INSERT INTO fluxo_passos (fluxo_id, ordem, canal, template, delay_dias, conteudo)
                        VALUES (?,?,?,?,?,?)""", (fid, i, canal, template, delay, conteudo))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "passos": len(validados)})


@app.route('/crm/fluxos/<int:fid>/excluir', methods=['POST'])
@login_required
@admin_required
def crm_fluxo_excluir(fid):
    conn = db()
    f = conn.execute("SELECT id FROM fluxos WHERE id=?", (fid,)).fetchone()
    if not f:
        close_db(conn); return jsonify({"ok": False, "erro": "Fluxo não encontrado"}), 404
    conn.execute("UPDATE fluxo_inscricoes SET status='cancelado', finalizado_em=? WHERE fluxo_id=? AND status='ativo'",
                 (_agora_sp(), fid))
    conn.execute("DELETE FROM fluxo_passos WHERE fluxo_id=?", (fid,))
    conn.execute("DELETE FROM fluxos WHERE id=?", (fid,))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True})


# ─── BIBLIOTECA DE MODELOS (e-mail/SMS reutilizáveis nos Fluxos) ───────────
# Antes disso, todo modelo de e-mail/SMS novo precisava ser colado no chat pra
# eu montar em código. Agora o admin sobe o HTML/texto direto pelo sistema e
# ele já aparece pronto pra usar no editor de fluxo, sem precisar de mim.

_MODELO_IMG_EXTS = ('.png', '.jpg', '.jpeg', '.webp', '.gif')


def _salvar_imagem_modelo(fstorage, prefixo):
    """Salva uma imagem enviada (logo/banner) em UPLOAD_FOLDER com nome único
    e devolve o nome do arquivo salvo (ou None se não veio nada válido)."""
    if not fstorage or not fstorage.filename:
        return None
    ext = os.path.splitext(fstorage.filename)[1].lower()
    if ext not in _MODELO_IMG_EXTS:
        return None
    fstorage.seek(0, os.SEEK_END)
    if fstorage.tell() > 5 * 1024 * 1024:
        return None
    fstorage.seek(0)
    nome = f"modelo_{prefixo}_{int(datetime.now(TZ_SP).timestamp())}{ext}"
    fstorage.save(os.path.join(UPLOAD_FOLDER, nome))
    return nome


