@app.route('/crm/biblioteca/conteudos/excluir', methods=['POST'])
@login_required
def crm_biblioteca_conteudos_excluir():
    """Exclui uma seleção explícita da página da Biblioteca.

    A tela nunca manda "a pasta toda": só IDs que a pessoa marcou. Antes de
    apagar, o servidor confere permissões e vínculos novamente — a página pode
    ter ficado aberta enquanto outra pessoa alterava um funil.
    """
    dados = request.json or {}
    brutos = dados.get('ids')
    if not isinstance(brutos, list) or not brutos:
        return _bib_erro('Selecione pelo menos um conteúdo para excluir.')
    if len(brutos) > 60:
        return _bib_erro('Exclua no máximo 60 conteúdos por vez.')
    try:
        ids = sorted({int(v) for v in brutos if int(v) > 0})
    except (TypeError, ValueError):
        return _bib_erro('A seleção contém um conteúdo inválido.')
    if not ids:
        return _bib_erro('Selecione pelo menos um conteúdo para excluir.')

    conn = db()
    marcadores = ','.join('?' for _ in ids)
    itens = [dict(r) for r in conn.execute(
        f"SELECT id,nome,dono_consultor_id FROM modelos_conteudo WHERE id IN ({marcadores})", tuple(ids)).fetchall()]
    if len(itens) != len(ids):
        close_db(conn)
        return _bib_erro('Um dos conteúdos já não existe. Recarregue a lista antes de excluir.', 409)
    uid, eh_gestor = session.get('user_id'), _bib_eh_gestor()
    if any(not _bib_pode_gerir(i['dono_consultor_id'], uid, eh_gestor) for i in itens):
        close_db(conn)
        return _bib_erro('Você não tem acesso a um dos conteúdos selecionados.', 403)
    usados_funil = conn.execute(
        f"SELECT DISTINCT modelo_id FROM whatsapp_funil_passos WHERE modelo_id IN ({marcadores})", tuple(ids)).fetchall()
    chaves_fluxo = tuple('upload_%d' % mid for mid in ids)
    marc_fluxo = ','.join('?' for _ in chaves_fluxo)
    usados_fluxo = conn.execute(
        f"SELECT DISTINCT template FROM fluxo_passos WHERE template IN ({marc_fluxo})", chaves_fluxo).fetchall()
    tem_vinculo = bool(usados_funil or usados_fluxo)
    if tem_vinculo and not bool(dados.get('confirmar_vinculos')):
        close_db(conn)
        return _bib_erro('Há conteúdos usados em funis ou fluxos. Confirme essa consequência antes de excluir.', 409)
    try:
        conn.execute(f"DELETE FROM modelos_conteudo WHERE id IN ({marcadores})", tuple(ids))
        conn.commit()
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        app.logger.warning(f"[BIBLIOTECA] exclusão em massa falhou: {e}")
        close_db(conn)
        return _bib_erro('Não foi possível excluir os conteúdos selecionados. Revise se algum está protegido por vínculo.')
    close_db(conn)
    return jsonify({'ok': True, 'excluidos': len(ids), 'tinha_vinculos': tem_vinculo})


@app.route('/crm/modelos/<int:mid>/editar', methods=['POST'])
@login_required
@admin_required
def crm_modelo_editar(mid):
    """Edita nome, texto e/ou o ARQUIVO de mídia de um modelo. Só mexe no que veio
    (multipart) — se não subir arquivo novo, a mídia atual fica intacta ('não perde
    nada'). Subiu arquivo: substitui a mídia (imagem/áudio/vídeo/PDF)."""
    nome = (request.form.get('nome') or '').strip()
    texto = request.form.get('corpo_texto')
    conn = db()
    m = conn.execute("SELECT id, dono_consultor_id FROM modelos_conteudo WHERE id=?", (mid,)).fetchone()
    if not m:
        close_db(conn); return jsonify({"ok": False, "erro": "Modelo não encontrado"}), 404
    if not _bib_pode_gerir(m['dono_consultor_id'], session.get('user_id'), _bib_eh_gestor()):
        close_db(conn)
        return jsonify({"ok": False, "erro": "Você não tem acesso a este conteúdo"}), 403
    sets, args = [], []
    if nome:
        sets.append("nome=?"); args.append(nome[:200])
    if texto is not None:
        sets.append("corpo_texto=?"); args.append(str(texto)[:4000])
    # Troca de arquivo (opcional)
    f = request.files.get('arquivo_midia')
    if f and f.filename:
        ext = os.path.splitext(f.filename)[1].lower()
        midia_tipo = _midia_tipo_por_ext(ext)
        if not midia_tipo:
            close_db(conn); return jsonify({"ok": False, "erro": f"Formato não aceito: {ext} (imagem, áudio, vídeo mp4/mov, ou PDF)"})
        f.stream.seek(0, os.SEEK_END); tamanho = f.stream.tell(); f.stream.seek(0)
        limite = _MODELO_WPP_LIMITE.get(midia_tipo, 8_000_000)
        if tamanho > limite:
            close_db(conn); return jsonify({"ok": False, "erro": f"Arquivo grande demais (máx. {limite // 1_000_000}MB)"})
        nome_arquivo = f"MODELO_WPP_{datetime.now(TZ_SP).strftime('%Y%m%d%H%M%S')}_{_sanitizar_filename(f.filename)}"
        resultado = upload_arquivo_r2(f.stream, f"modelos/{nome_arquivo}")
        if not resultado.get('ok'):
            close_db(conn); return jsonify({"ok": False, "erro": f"Erro ao salvar mídia: {resultado.get('erro', 'desconhecido')}"})
        sets.append("midia_arquivo=?"); args.append(nome_arquivo)
        sets.append("midia_tipo=?"); args.append(midia_tipo)
    if sets:
        args.append(mid)
        conn.execute(f"UPDATE modelos_conteudo SET {', '.join(sets)} WHERE id=?", tuple(args))
        conn.commit()
    close_db(conn)
    return jsonify({"ok": True})


# ─── Pastas (Modelos + Funis organizados por consultor → operadora → subpasta) ──
# Hierarquia de profundidade livre. Só existem 5 pastas RAIZ (parent_id NULL),
# fixas/protegidas contra exclusão: "Compartilhado", "A organizar" e uma por
# consultor (consultor_id = usuarios.id, criadas pelo backfill automático a
# partir de quem tem perfil='consultor'). Sob qualquer raiz, subpastas
# arbitrárias via parent_id — essas NUNCA guardam consultor_id direto, o dono
# de uma subpasta é sempre calculado subindo até a raiz (_pasta_dono). Modelos
# e funis apontam pra uma pasta folha (pasta_id) e carregam dono_consultor_id
# denormalizado a partir da raiz, pra a extensão da consultora filtrar com um
# WHERE direto (roda a cada troca de conversa, não pode subir árvore toda vez).

def _pasta_dono(conn, pasta_id):
    """Sobe a árvore a partir de qualquer pasta até achar a raiz e devolve o
    consultor_id dela (None = Compartilhado/A organizar, ou pasta órfã)."""
    visitados = set()
    atual = pasta_id
    ultimo = None
    while atual and atual not in visitados:
        visitados.add(atual)
        p = conn.execute("SELECT parent_id, consultor_id FROM pastas WHERE id=?", (atual,)).fetchone()
        if not p:
            return None
        ultimo = p
        if not p['parent_id']:
            return p['consultor_id']
        atual = p['parent_id']
    return ultimo['consultor_id'] if ultimo else None


def _pasta_recalcular_cascata(conn, pasta_id):
    """Depois de mover uma pasta pra debaixo de outra raiz, recalcula
    dono_consultor_id de todo modelo/funil na subárvore inteira a partir dela
    (não só os diretamente dentro) — mover uma pasta de Compartilhado pra
    dentro de um consultor é uma reatribuição de dono de tudo que tem nela."""
    dono = _pasta_dono(conn, pasta_id)
    fila = [pasta_id]
    todas = []
    while fila:
        atual = fila.pop()
        todas.append(atual)
        fila.extend(f['id'] for f in conn.execute("SELECT id FROM pastas WHERE parent_id=?", (atual,)).fetchall())
    marcadores = ','.join(['?'] * len(todas))
    conn.execute(f"UPDATE modelos_conteudo SET dono_consultor_id=? WHERE pasta_id IN ({marcadores})", (dono, *todas))
    conn.execute(f"UPDATE whatsapp_funis SET dono_consultor_id=? WHERE pasta_id IN ({marcadores})", (dono, *todas))


def _construir_arvore_pastas(conn, usuario_id=None, eh_gestor=True):
    """Monta a árvore inteira (pastas + contagem de modelos/funis ativos
    dentro de cada uma) num JSON só, pra navegação client-side sem round-trip
    — mesmo espírito do navegador do Material de Apoio, mas recursivo de
    verdade (aquele é hardcoded em 2 níveis, não dava pra reaproveitar)."""
    pastas = [dict(p) for p in conn.execute("SELECT * FROM pastas ORDER BY nome").fetchall()]
    cont_modelos, cont_funis = {}, {}
    for r in conn.execute("SELECT pasta_id, COUNT(*) n FROM modelos_conteudo WHERE pasta_id IS NOT NULL AND ativo=1 GROUP BY pasta_id").fetchall():
        cont_modelos[r['pasta_id']] = r['n']
    for r in conn.execute("SELECT pasta_id, COUNT(*) n FROM whatsapp_funis WHERE pasta_id IS NOT NULL AND ativo=1 GROUP BY pasta_id").fetchall():
        cont_funis[r['pasta_id']] = r['n']
    by_id = {p['id']: {**p, 'filhas': [], 'modelos': cont_modelos.get(p['id'], 0), 'funis': cont_funis.get(p['id'], 0)}
             for p in pastas}
    raizes = []
    for p in by_id.values():
        if p['parent_id'] and p['parent_id'] in by_id:
            by_id[p['parent_id']]['filhas'].append(p)
        else:
            raizes.append(p)
    if eh_gestor:
        return raizes
    return [p for p in raizes if p.get('consultor_id') == usuario_id]


@app.route('/crm/pastas/nova', methods=['POST'])
@login_required
def crm_pasta_nova():
    """Só cria SUBpasta — as 5 raízes (Compartilhado, A organizar, uma por
    consultor) são geridas pelo backfill automático, não por aqui."""
    d = request.json or {}
    nome = (d.get('nome') or '').strip()[:120]
    parent_id = d.get('parent_id')
    if not nome:
        return jsonify({"ok": False, "erro": "Dê um nome à pasta"}), 400
    if not parent_id:
        return jsonify({"ok": False, "erro": "Escolha em qual pasta ela vai ficar dentro"}), 400
    conn = db()
    if not conn.execute("SELECT id FROM pastas WHERE id=?", (parent_id,)).fetchone():
        close_db(conn); return jsonify({"ok": False, "erro": "Pasta pai não encontrada"}), 400
    if not _bib_eh_gestor() and _pasta_dono(conn, parent_id) != session.get('user_id'):
        close_db(conn)
        return jsonify({"ok": False, "erro": "Você só pode criar pasta dentro das suas"}), 403
    conn.execute("INSERT INTO pastas (nome, parent_id, consultor_id) VALUES (?,?,NULL)", (nome, parent_id))
    pid = (conn.execute("SELECT lastval() AS id").fetchone()['id'] if DB_MODE == "postgres"
           else conn.execute("SELECT last_insert_rowid() id").fetchone()['id'])
    conn.commit(); close_db(conn)
    return jsonify({"ok": True, "id": pid})


@app.route('/crm/pastas/<int:pid>/renomear', methods=['POST'])
@login_required
def crm_pasta_renomear(pid):
    d = request.json or {}
    nome = (d.get('nome') or '').strip()[:120]
    if not nome:
        return jsonify({"ok": False, "erro": "Nome não pode ficar vazio"}), 400
    conn = db()
    pasta = conn.execute("SELECT id,parent_id FROM pastas WHERE id=?", (pid,)).fetchone()
    if not pasta:
        close_db(conn); return jsonify({"ok": False, "erro": "Pasta não encontrada"}), 404
    if pasta['parent_id'] is None:
        close_db(conn); return jsonify({"ok": False, "erro": "A pasta-mãe é definida pelo consultor e não pode ser renomeada aqui."}), 400
    if not _bib_eh_gestor() and _pasta_dono(conn, pid) != session.get('user_id'):
        close_db(conn)
        return jsonify({"ok": False, "erro": "Você só pode renomear as suas pastas"}), 403
    conn.execute("UPDATE pastas SET nome=? WHERE id=?", (nome, pid))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True})


@app.route('/crm/pastas/<int:pid>/mover', methods=['POST'])
@login_required
def crm_pasta_mover(pid):
    """Muda uma SUBpasta de lugar (as 5 raízes não se movem — ficam fixas).
    Recalcula dono_consultor_id em cascata pra ela e tudo dentro, já que
    mover entre Compartilhado/A organizar/pasta de um consultor troca o
    dono de tudo que tem lá dentro."""
    d = request.json or {}
    novo_parent = d.get('parent_id')
    if not novo_parent:
        return jsonify({"ok": False, "erro": "Escolha a pasta destino"}), 400
    conn = db()
    pasta = conn.execute("SELECT id, parent_id FROM pastas WHERE id=?", (pid,)).fetchone()
    if not pasta:
        close_db(conn); return jsonify({"ok": False, "erro": "Pasta não encontrada"}), 404
    if not pasta['parent_id']:
        close_db(conn); return jsonify({"ok": False, "erro": "Essa é uma pasta raiz — não pode ser movida"}), 400
    if not _bib_eh_gestor() and _pasta_dono(conn, pid) != session.get('user_id'):
        close_db(conn)
        return jsonify({"ok": False, "erro": "Você só pode mover as suas pastas"}), 403
    novo_parent = int(novo_parent)
    if novo_parent == pid:
        close_db(conn); return jsonify({"ok": False, "erro": "Uma pasta não pode ser pai dela mesma"}), 400
    if not conn.execute("SELECT id FROM pastas WHERE id=?", (novo_parent,)).fetchone():
        close_db(conn); return jsonify({"ok": False, "erro": "Pasta destino não encontrada"}), 400
    atual, visitados = novo_parent, set()
    while atual and atual not in visitados:
        if atual == pid:
            close_db(conn); return jsonify({"ok": False, "erro": "Não dá pra mover uma pasta pra dentro dela mesma"}), 400
        visitados.add(atual)
        p = conn.execute("SELECT parent_id FROM pastas WHERE id=?", (atual,)).fetchone()
        atual = p['parent_id'] if p else None
    conn.execute("UPDATE pastas SET parent_id=? WHERE id=?", (novo_parent, pid))
    _pasta_recalcular_cascata(conn, pid)
    conn.commit(); close_db(conn)
    return jsonify({"ok": True})


@app.route('/crm/pastas/<int:pid>/excluir', methods=['POST'])
@login_required
def crm_pasta_excluir(pid):
    conn = db()
    pasta = conn.execute("SELECT id, parent_id FROM pastas WHERE id=?", (pid,)).fetchone()
    if not pasta:
        close_db(conn); return jsonify({"ok": False, "erro": "Pasta não encontrada"}), 404
    if not pasta['parent_id']:
        close_db(conn); return jsonify({"ok": False, "erro": "Essa é uma pasta raiz — não pode ser excluída"}), 400
    if not _bib_eh_gestor() and _pasta_dono(conn, pid) != session.get('user_id'):
        close_db(conn)
        return jsonify({"ok": False, "erro": "Você só pode excluir as suas pastas"}), 403
    if conn.execute("SELECT id FROM pastas WHERE parent_id=?", (pid,)).fetchone():
        close_db(conn); return jsonify({"ok": False, "erro": "Essa pasta tem subpastas — mova ou exclua elas primeiro"}), 400
    if conn.execute("SELECT id FROM modelos_conteudo WHERE pasta_id=?", (pid,)).fetchone():
        close_db(conn); return jsonify({"ok": False, "erro": "Essa pasta tem modelos dentro — mova eles primeiro"}), 400
    if conn.execute("SELECT id FROM whatsapp_funis WHERE pasta_id=?", (pid,)).fetchone():
        close_db(conn); return jsonify({"ok": False, "erro": "Essa pasta tem funis dentro — mova eles primeiro"}), 400
    conn.execute("DELETE FROM pastas WHERE id=?", (pid,))
    conn.commit(); close_db(conn)
    return jsonify({"ok": True})


@app.route('/crm/pastas/<int:pid>/arquivar', methods=['POST'])
@login_required
def crm_pasta_arquivar(pid):
    """Arquiva somente a raiz pessoal de um consultor já inativo.

    Arquivar não exclui mídia, conteúdo, subpastas nem funis. A pasta passa a
    aparecer no agrupamento Arquivadas para gestores, sem poluir a operação.
    """
    if not _bib_eh_gestor():
        return jsonify({'ok': False, 'erro': 'Somente gestores podem arquivar uma pasta de consultor.'}), 403
    conn = db()
    pasta = conn.execute("""SELECT p.id,p.parent_id,p.consultor_id,COALESCE(p.arquivada,0) arquivada,
                                  u.ativo usuario_ativo
                           FROM pastas p LEFT JOIN usuarios u ON u.id=p.consultor_id
                           WHERE p.id=?""", (pid,)).fetchone()
    if not pasta:
        close_db(conn); return jsonify({'ok': False, 'erro': 'Pasta não encontrada.'}), 404
    if pasta['parent_id'] is not None or pasta['consultor_id'] is None:
        close_db(conn); return jsonify({'ok': False, 'erro': 'Apenas a pasta-mãe pessoal de um consultor pode ser arquivada.'}), 400
    if pasta['usuario_ativo']:
        close_db(conn); return jsonify({'ok': False, 'erro': 'Desative o consultor antes de arquivar a pasta dele.'}), 400
    if pasta['arquivada']:
        close_db(conn); return jsonify({'ok': True, 'arquivada': True})
    conn.execute("UPDATE pastas SET arquivada=1, arquivada_em=CURRENT_TIMESTAMP WHERE id=?", (pid,))
    conn.commit(); close_db(conn)
    return jsonify({'ok': True, 'arquivada': True})


@app.route('/crm/pastas/<int:pid>/desarquivar', methods=['POST'])
@login_required
def crm_pasta_desarquivar(pid):
    if not _bib_eh_gestor():
        return jsonify({'ok': False, 'erro': 'Somente gestores podem restaurar uma pasta arquivada.'}), 403
    conn = db()
    pasta = conn.execute("SELECT id,parent_id,consultor_id FROM pastas WHERE id=?", (pid,)).fetchone()
    if not pasta:
        close_db(conn); return jsonify({'ok': False, 'erro': 'Pasta não encontrada.'}), 404
    if pasta['parent_id'] is not None or pasta['consultor_id'] is None:
        close_db(conn); return jsonify({'ok': False, 'erro': 'Apenas uma pasta-mãe pessoal pode ser restaurada.'}), 400
    conn.execute("UPDATE pastas SET arquivada=0, arquivada_em=NULL WHERE id=?", (pid,))
    conn.commit(); close_db(conn)
    return jsonify({'ok': True, 'arquivada': False})


@app.route('/crm/modelos/<int:mid>/mover-pasta', methods=['POST'])
@login_required
@admin_required
def crm_modelo_mover_pasta(mid):
    d = request.json or {}
    pasta_id = d.get('pasta_id')
    conn = db()
    atual = conn.execute("SELECT id, dono_consultor_id FROM modelos_conteudo WHERE id=?", (mid,)).fetchone()
    if not atual:
        close_db(conn); return jsonify({"ok": False, "erro": "Modelo não encontrado"}), 404
    eh_gestor = _bib_eh_gestor()
    if not _bib_pode_gerir(atual['dono_consultor_id'], session.get('user_id'), eh_gestor):
        close_db(conn)
        return jsonify({"ok": False, "erro": "Você não tem acesso a este conteúdo"}), 403
    dono = None
    if pasta_id:
        if not conn.execute("SELECT id FROM pastas WHERE id=?", (pasta_id,)).fetchone():
            close_db(conn); return jsonify({"ok": False, "erro": "Pasta não encontrada"}), 400
