@app.route('/crm/biblioteca/funil/<int:fid>/transferir', methods=['POST'])
@login_required
def crm_biblioteca_funil_transferir(fid):
    """Transfere o funil e resolve as mensagens de que ele depende.

    Sem escolher a política, um funil com passo de outro dono devolve 409 com a
    lista — nunca é transferido pela metade."""
    d = request.json or {}
    uid = session.get('user_id')
    eh_gestor = _bib_eh_gestor()
    conn = db()
    f = conn.execute("SELECT id, nome, dono_consultor_id FROM whatsapp_funis WHERE id=?", (fid,)).fetchone()
    if not f:
        close_db(conn); return _bib_erro('Funil não encontrado', 404)
    f = dict(f)
    if not _bib_pode_gerir(f['dono_consultor_id'], uid, eh_gestor):
        close_db(conn); return _bib_erro('Você não tem acesso a este funil', 403)
    dono, erro = _bib_dono_pedido(conn, d.get('dono'), eh_gestor)
    if erro:
        close_db(conn); return _bib_erro(erro, 403 if not eh_gestor else 400)
    if d.get('pasta_id'):
        pasta_id, dono_pasta, erro = _bib_destino(conn, d.get('pasta_id'), uid, eh_gestor)
        if erro:
            close_db(conn); return _bib_erro(erro)
        if dono_pasta != dono:
            close_db(conn)
            return _bib_erro('A pasta escolhida não pertence ao proprietário de destino')
    else:
        pasta_id = _bib_raiz_do_dono(conn, dono)
    pendentes = _bib_dependencias_funil(conn, fid, dono)
    politica = (d.get('dependencias') or '').strip()
    if pendentes:
        if politica not in ('transferir', 'copiar'):
            close_db(conn)
            return jsonify({'ok': False, 'precisa_decidir': True,
                            'erro': 'Este funil usa mensagens de outro proprietário',
                            'dependencias': pendentes}), 409
        erro = _bib_resolver_dependencias(conn, fid, pendentes, pasta_id, dono, uid, politica)
        if erro:
            close_db(conn); return _bib_erro(erro)
    conn.execute("UPDATE whatsapp_funis SET pasta_id=?, dono_consultor_id=? WHERE id=?",
                 (pasta_id, dono, fid))
    conn.commit(); close_db(conn)
    return jsonify({'ok': True, 'id': fid, 'dependencias_resolvidas': len(pendentes)})


@app.route('/crm/biblioteca/funil/<int:fid>/copiar', methods=['POST'])
@login_required
def crm_biblioteca_funil_copiar(fid):
    """Copia o funil para outra pasta. O original fica onde está.

    Se a cópia vai para outro proprietário e a sequência usa mensagens que ele
    não enxerga, as mensagens são copiadas junto — copiar um funil que nasce
    quebrado não ajudaria ninguém."""
    d = request.json or {}
    uid = session.get('user_id')
    eh_gestor = _bib_eh_gestor()
    conn = db()
    f = conn.execute("SELECT * FROM whatsapp_funis WHERE id=?", (fid,)).fetchone()
    if not f:
        close_db(conn); return _bib_erro('Funil não encontrado', 404)
    f = dict(f)
    if not _bib_pode_gerir(f['dono_consultor_id'], uid, eh_gestor):
        close_db(conn); return _bib_erro('Você não tem acesso a este funil', 403)
    pasta_id, dono, erro = _bib_destino(conn, d.get('pasta_id'), uid, eh_gestor)
    if erro:
        close_db(conn); return _bib_erro(erro)
    passos = [dict(p) for p in conn.execute(
        """SELECT ordem, modelo_id, delay_segundos FROM whatsapp_funil_passos
           WHERE funil_id=? ORDER BY ordem, id""", (fid,)).fetchall()]
    nome = _nome_copia_disponivel(conn, 'whatsapp_funis', f['nome'], dono)
    cur = conn.cursor()
    cur.execute("""INSERT INTO whatsapp_funis
        (nome, categoria, favorito, ativo, vezes_disparado, criado_por, pasta_id, dono_consultor_id)
        VALUES (?,?,0,1,0,?,?,?)""",
        (nome, f.get('categoria'), uid, pasta_id, dono))
    novo_fid = _last_insert_id(cur)
    copias = {}
    for p in passos:
        modelo_id = p['modelo_id']
        origem = _bib_conteudo(conn, modelo_id)
        if origem and origem.get('dono_consultor_id') is not None \
                and origem['dono_consultor_id'] != dono:
            if modelo_id not in copias:
                copias[modelo_id] = _bib_copiar_conteudo(conn, origem, pasta_id, dono, uid)
            modelo_id = copias[modelo_id]
        conn.execute("""INSERT INTO whatsapp_funil_passos (funil_id, ordem, modelo_id, delay_segundos)
            VALUES (?,?,?,?)""", (novo_fid, p['ordem'], modelo_id, p['delay_segundos']))
    conn.commit(); close_db(conn)
    return jsonify({'ok': True, 'id': novo_fid, 'mensagens_copiadas': len(copias)})


# ─── Funis de WhatsApp (sequências de disparo) ──────────────────────────────
# Um funil é uma sequência ordenada de passos; cada passo aponta pra um modelo
# da biblioteca (texto/áudio/imagem/PDF) + um delay antes de mandar. A extensão
# TOCA a sequência na conversa aberta. Isto é SEPARADO dos "fluxos" do CRM
# (tabela fluxos) — por decisão do Guilherme; casar os dois é passo futuro.

def _funil_num(v, padrao, minimo, maximo):
    try:
        n = int(v)
    except (TypeError, ValueError):
        return padrao
    return max(minimo, min(maximo, n))


def _funil_salvar_completo(conn, dados, criado_por, funil_id=None, dono_forcado=None):
    """Salva cabeçalho e sequência numa transação lógica só.

    O editor antigo persistia cada clique separadamente e recarregava a página
    inteira. Este contrato recebe o rascunho completo, valida tudo antes de
    tocar no banco e só então substitui os passos. É usado pelo site e pela
    extensão para os dois editores falarem a mesma língua.
    """
    nome = (dados.get('nome') or '').strip()[:200]
    categoria = (dados.get('categoria') or '').strip()[:120] or None
    passos_brutos = dados.get('passos')
    if not nome:
        return None, 'Dê um nome ao funil'
    if not isinstance(passos_brutos, list) or not passos_brutos:
        return None, 'Adicione pelo menos uma mensagem à sequência'
    if len(passos_brutos) > 60:
        return None, 'Um funil pode ter no máximo 60 mensagens'

    passos = []
    for i, passo in enumerate(passos_brutos, 1):
        if not isinstance(passo, dict):
            return None, f'A mensagem {i} está inválida'
        modelo_id = _funil_num(passo.get('modelo_id'), 0, 0, 2_000_000_000)
        if not modelo_id:
            return None, f'Escolha o conteúdo da mensagem {i}'
        delay = _funil_num(passo.get('delay_segundos'), 5, 0, 3600)
        passos.append({'modelo_id': modelo_id, 'delay_segundos': delay})

    ids = sorted(set(p['modelo_id'] for p in passos))
    marcadores = ','.join('?' for _ in ids)
    validos = conn.execute(
        f"SELECT id FROM modelos_conteudo WHERE id IN ({marcadores}) AND tipo='whatsapp' AND ativo=1",
        ids).fetchall()
    if {r['id'] for r in validos} != set(ids):
        return None, 'Uma das mensagens não existe mais na biblioteca'

    pasta_foi_enviada = 'pasta_id' in dados
    pasta_id = dados.get('pasta_id') if pasta_foi_enviada else None
    dono = dono_forcado
    if pasta_foi_enviada and pasta_id:
        try:
            pasta_id = int(pasta_id)
        except (TypeError, ValueError):
            return None, 'A pasta escolhida é inválida'
        if not conn.execute("SELECT id FROM pastas WHERE id=?", (pasta_id,)).fetchone():
            return None, 'A pasta escolhida não existe mais'
        dono_pasta = _pasta_dono(conn, pasta_id)
        if dono_forcado is not None and dono_pasta != dono_forcado:
            return None, 'Escolha uma pasta sua'
        dono = dono_pasta

    if funil_id:
        atual = conn.execute("SELECT id FROM whatsapp_funis WHERE id=? AND ativo=1", (funil_id,)).fetchone()
        if not atual:
            return None, 'Funil não encontrado'
        if pasta_foi_enviada:
            conn.execute("""UPDATE whatsapp_funis
                SET nome=?, categoria=?, pasta_id=?, dono_consultor_id=? WHERE id=?""",
                (nome, categoria, pasta_id or None, dono, funil_id))
        else:
            conn.execute("UPDATE whatsapp_funis SET nome=?, categoria=? WHERE id=?",
                         (nome, categoria, funil_id))
        conn.execute("DELETE FROM whatsapp_funil_passos WHERE funil_id=?", (funil_id,))
    else:
        cur = conn.cursor()
        cur.execute("""INSERT INTO whatsapp_funis
            (nome, categoria, ativo, criado_por, pasta_id, dono_consultor_id)
            VALUES (?,?,1,?,?,?)""",
            (nome, categoria, criado_por, pasta_id or None, dono))
        funil_id = _last_insert_id(cur)

    for ordem, passo in enumerate(passos, 1):
        conn.execute("""INSERT INTO whatsapp_funil_passos
            (funil_id, ordem, modelo_id, delay_segundos) VALUES (?,?,?,?)""",
            (funil_id, ordem, passo['modelo_id'], passo['delay_segundos']))
    return funil_id, None


@app.route('/crm/funis/salvar', methods=['POST'])
@login_required
def crm_funil_salvar_completo():
    dados = request.json or {}
    funil_id = _funil_num(dados.get('id'), 0, 0, 2_000_000_000) or None
    uid = session.get('user_id')
    eh_gestor = session.get('perfil') in ('admin', 'supervisor', 'gestor_vendedor')
    conn = db()
    if funil_id and not eh_gestor:
        atual = conn.execute("SELECT dono_consultor_id FROM whatsapp_funis WHERE id=?", (funil_id,)).fetchone()
        if not atual or atual['dono_consultor_id'] != uid:
            close_db(conn)
            return jsonify({'ok': False, 'erro': 'Você só pode editar seus funis'}), 403
    salvo_id, erro = _funil_salvar_completo(
        conn, dados, uid, funil_id, None if eh_gestor else uid)
    if erro:
        close_db(conn)
        return jsonify({'ok': False, 'erro': erro}), 400
    conn.commit(); close_db(conn)
    return jsonify({'ok': True, 'id': salvo_id})


@app.route('/api/whatsapp/extensao/funis/salvar', methods=['POST', 'OPTIONS'])
@requer('crm:escrever')
def api_whatsapp_extensao_funil_salvar():
    """Cria ou edita uma sequência sem tirar o gestor do WhatsApp."""
    if request.method == 'OPTIONS':
        return _wa_cors(Response(status=204))
    if not getattr(g, 'usuario_id', None) or not getattr(g, 'usuario', None):
        return _wa_cors(jsonify({'ok': False, 'erro': 'Entre no JOB pelo popup da extensão'})), 401
    dados = request.json or {}
    funil_id = _funil_num(dados.get('id'), 0, 0, 2_000_000_000) or None
    conn = db()
    if funil_id:
        atual = conn.execute("SELECT dono_consultor_id FROM whatsapp_funis WHERE id=?", (funil_id,)).fetchone()
        if not atual or atual['dono_consultor_id'] != g.usuario_id:
            close_db(conn)
            return _wa_cors(jsonify({'ok': False, 'erro': 'Você só pode editar seus funis'})), 403
    # A tela só lista mensagens próprias/compartilhadas, e a rota mantém a
    # regra quando alguém tentar postar um id de outro dono diretamente.
    passos = dados.get('passos') if isinstance(dados.get('passos'), list) else []
    modelo_ids = sorted({_funil_num(p.get('modelo_id'), 0, 0, 2_000_000_000)
                         for p in passos if isinstance(p, dict) and p.get('modelo_id')})
    modelo_ids = [mid for mid in modelo_ids if mid]
    if modelo_ids:
        marcadores = ','.join('?' for _ in modelo_ids)
        meus = conn.execute(
            f"SELECT id FROM modelos_conteudo WHERE id IN ({marcadores}) "
            "AND tipo='whatsapp' AND ativo=1 AND (dono_consultor_id=? OR dono_consultor_id IS NULL)",
            (*modelo_ids, g.usuario_id)).fetchall()
        if {r['id'] for r in meus} != set(modelo_ids):
            close_db(conn)
            return _wa_cors(jsonify({'ok': False, 'erro': 'Você só pode usar suas mensagens no funil'})), 403
    salvo_id, erro = _funil_salvar_completo(
        conn, dados, g.usuario_id, funil_id, g.usuario_id)
    if erro:
        close_db(conn)
        return _wa_cors(jsonify({'ok': False, 'erro': erro})), 400
    conn.commit(); close_db(conn)
    return _wa_cors(jsonify({'ok': True, 'id': salvo_id}))


@app.route('/crm/funis')
@login_required
def crm_funis():
    uid = session.get('user_id')
    eh_gestor = session.get('perfil') in ('admin', 'supervisor', 'gestor_vendedor')
    conn = db()
    where = "ativo=1" if eh_gestor else """ativo=1 AND dono_consultor_id=? AND NOT EXISTS (
        SELECT 1 FROM whatsapp_funil_passos px
        JOIN modelos_conteudo mx ON mx.id=px.modelo_id
        WHERE px.funil_id=whatsapp_funis.id
          AND (mx.dono_consultor_id IS NULL OR mx.dono_consultor_id != ?)
    )"""
    params = () if eh_gestor else (uid, uid)
    funis = [dict(f) for f in conn.execute(
        f"SELECT * FROM whatsapp_funis WHERE {where} ORDER BY favorito DESC, (categoria IS NULL), categoria, nome", params).fetchall()]
    ids_funis = [f['id'] for f in funis]
    filtro_passos = ''
    params_passos = ()
    if ids_funis:
        filtro_passos = 'WHERE p.funil_id IN (%s)' % ','.join('?' for _ in ids_funis)
        params_passos = tuple(ids_funis)
    else:
        filtro_passos = 'WHERE 1=0'
    passos = [dict(p) for p in conn.execute("""
        SELECT p.id, p.funil_id, p.ordem, p.delay_segundos,
               m.id AS modelo_id, m.nome AS modelo_nome, m.midia_tipo, m.corpo_texto
        FROM whatsapp_funil_passos p
        JOIN modelos_conteudo m ON m.id = p.modelo_id
        %s ORDER BY p.funil_id, p.ordem, p.id""" % filtro_passos, params_passos).fetchall()]
    # Biblioteca de modelos pra montar os passos (só WhatsApp ativos).
    modelos = [dict(m) for m in conn.execute("""
        SELECT id, nome, midia_tipo, categoria, corpo_texto FROM modelos_conteudo
        WHERE tipo='whatsapp' AND ativo=1
        %s ORDER BY (categoria IS NULL), categoria, nome""" %
        ('' if eh_gestor else 'AND dono_consultor_id=?'),
        () if eh_gestor else (uid,)).fetchall()]
    arvore_pastas = _construir_arvore_pastas(conn, uid, eh_gestor)
    close_db(conn)
    por_funil = {}
    for p in passos:
        p['tipo'] = p['midia_tipo'] if p['midia_tipo'] in ('audio', 'imagem', 'video', 'documento') else 'texto'
        por_funil.setdefault(p['funil_id'], []).append(p)
    for f in funis:
        f['passos'] = por_funil.get(f['id'], [])
        f['total_delay'] = sum((p['delay_segundos'] or 0) for p in f['passos'])
        f['pode_editar'] = eh_gestor or f.get('dono_consultor_id') == uid
    return render_template('crm_funis.html', funis=funis, modelos=modelos,
                           arvore_pastas=arvore_pastas, pode_gerir=eh_gestor,
                           usuario_id=uid)


def _duplicar_funil(conn, fid, usuario_id):
    origem = conn.execute("SELECT * FROM whatsapp_funis WHERE id=? AND ativo=1", (fid,)).fetchone()
    if not origem:
        return None, 'Funil não encontrado'
    origem = dict(origem)
    nome = _nome_copia_disponivel(conn, 'whatsapp_funis', origem['nome'], usuario_id)
    cur = conn.cursor()
    cur.execute("""INSERT INTO whatsapp_funis
        (nome, categoria, favorito, ativo, vezes_disparado, criado_por, pasta_id, dono_consultor_id)
        VALUES (?,?,0,1,0,?,NULL,?)""",
        (nome, origem.get('categoria'), usuario_id, usuario_id))
    novo_id = _last_insert_id(cur)
    for p in conn.execute("""SELECT ordem, modelo_id, delay_segundos
            FROM whatsapp_funil_passos WHERE funil_id=? ORDER BY ordem,id""", (fid,)).fetchall():
        conn.execute("""INSERT INTO whatsapp_funil_passos
            (funil_id, ordem, modelo_id, delay_segundos) VALUES (?,?,?,?)""",
            (novo_id, p['ordem'], p['modelo_id'], p['delay_segundos']))
    return novo_id, None


