@app.route('/crm/lead/<int:lid>/fluxo/iniciar', methods=['POST'])
@login_required
def crm_lead_fluxo_iniciar(lid):
    d = request.json or {}
    fluxo_id = d.get('fluxo_id')
    conn = db()
    lead = conn.execute("SELECT id, responsavel_id, etapa FROM crm_leads WHERE id=?", (lid,)).fetchone()
