    fluxo = conn.execute("SELECT id, nome FROM fluxos WHERE id=? AND ativo=1", (fluxo_id,)).fetchone()
    if not fluxo:
        close_db(conn); return jsonify({"ok": False, "erro": "Fluxo inválido ou inativo"}), 400
